    // One-shot whitebox scene assembly for the Iteration Room prototype.
    // Run via Unity menu "Iteration Room/Build Whitebox Scene", or headlessly:
    //   Unity.exe -batchmode -quit -projectPath <path> -executeMethod IterationRoom.EditorTools.SceneBuilder.Build
    public static class SceneBuilder
    {
        private const string ScenePath = "Assets/Scenes/IterationRoom.unity";
        private const string MenuScenePath = "Assets/Scenes/MainMenu.unity";
        // How far in from the left edge the title and the button column sit, at the canvas's 1920
        // reference width. One number, so the two cannot drift apart.
        // **HOW FAR THE TITLE SCREEN'S COLUMN SITS FROM THE LEFT EDGE.** 132 -> 84 on 2026-08-28,
        // by request ("버튼 위치를 좀더 사이드로 붙여도 좋아").
        //
        // The margin is doing one job: keeping the words off the edge of the frame. Past that, every
        // pixel it spends is picture it takes away - and the picture here is a render of the room the
        // game is set in. Tighter reads as a title card with a menu at its edge rather than as a menu
        // laid over a photograph, which is the arrangement this screen has been moving toward since
        // the title was pushed off-centre.
        private const float MenuLeftMargin = 84f;

        // ONE SCENE PER CYCLE, on top of the core one. `IterationRoom` keeps the player, the HUD, the
        // loop and the join between storeys; everything a cycle IS moves out into these.
        //
        // The order is play order, and it is the same order `CycleSceneLoader` reads them back in - so
        // a cycle's position in this array is what says which cycle it is. Append, never reorder.
        private static readonly string[] CycleSceneNames = { "Cycle1", "Cycle2", "Cycle3", "Cycle4" };
        private static string CycleScenePath(string name) => $"Assets/Scenes/{name}.unity";
        private const string MaterialsDir = "Assets/Materials";
        private const string PrefabsDir = "Assets/Prefabs";
        private const string ShadersDir = "Assets/Shaders";
        // Item ids are a WIRE VALUE - KeyLock asks for "Key", BalloonTool and GhostReplayer both
        // ask for "Tool". Declared once so a rename cannot silently disarm one side of a gate.
        private const string ToolItemId = "Tool";
        // ~~CycleTwoToolItemId~~ UNUSED since 2026-08-15: cycle 2's nightstand went, and with it the
        // three pins it carried. Kept as the reserved name for whatever tool cycle 2 eventually has,
        // so a second `"Tool"` pool can never be created by accident (see ItemRegistry on why an id
        // silently becoming a supply is the collision worth catching).
        private const string CycleTwoToolItemId = "Tool2";

        // CYCLE 2'S ESCAPE OBJECTS: three shards of one broken ring.
        //
        // Not the cube, sphere and prism again. Those were three DIFFERENT shapes, and finding a
        // shape for a shaped hole is the verb cycle 1 is made of; three pieces of the same broken
        // thing say something else - that what the facility is missing is one object, and it is in
        // pieces inside the core.
        //
        // Three ids rather than one shared one, because `ItemRegistry` maps an id to exactly ONE
        // socket with the last writer winning - a shared id would leave two of the three recesses
        // unreachable.
        // Room2-2's buckets. ONE ID FOR FOUR OBJECTS, which `ItemRegistry` has supported since the pin
        // drawer: an id can name a SUPPLY. Each bucket still obeys the one-object rule and returns to
        // its own origin - what is forbidden is two holders of one object, never two objects of one id.
        private const string BucketItemId = "Bucket";
        // The block on cycle 2's chest of drawers. It has no job yet - see BuildDresser - so the id
        // says what the object IS rather than what it opens.
        private const string CycleTwoBlockItemId = "Block2";
        // THE POOL'S OWN CARRYABLES. Ids naming a SUPPLY, like the pins and the buckets: three ducks
        // and two beach balls share one id each, and every instance obeys the one-object rule and
        // returns to its own spot on the water (CLAUDE.md §1.2).
        // **PREFIXES, NOT IDS.** `BuildFloatingProps` appends `_0`, `_1`... so each duck and each
        // beach ball carries its own id - see the note at that assignment for why a shared one was a
        // bug rather than a saving.
        private const string DuckItemId = "Duck2";
        private const string BeachBallItemId = "BeachBall2";

        // ROOM2-0'S KEYS: nine billiard balls in the chest of drawers, and each one is its own id.
        //
        // NOT A SUPPLY, unlike the pins, the buckets, the ducks and the beach balls - and that is the
        // whole point of them. A supply says "any of these will do"; here WHICH ONE is the answer to
        // the puzzle, so every ball is a distinct object with a distinct socket that will take it and
        // nothing else. Nine ids, nine one-member pools, four of which a pedestal wants.
        private const string BilliardIdPrefix = "Billiard";

        private const string ShardAItemId = "Shard2A";
        private const string ShardBItemId = "Shard2B";
        private const string ShardCItemId = "Shard2C";
        // Yellow keeps the id "Key" it has always had. It is a wire value shared by the key object and
        // its lock, and both come from here, so renaming it would be safe - but there is nothing to buy
        // and the yellow key, its door and its lock are the ones already play-tested.
        private const string KeyItemId = "Key";
        private const string RedKeyItemId = "KeyRed";
        private const string BlueKeyItemId = "KeyBlue";

        // One key, described once. Three of these exist and every part of the chain reads the same
        // entry - the key's own material, the tint on its HUD icon, the plate on its lock, the band on
        // its door - which is the whole mechanism by which the colours cannot drift apart.
        //
        // A DISPLAY colour and a KEY colour, and they are not the same value. The key is a shaded metal
        // object lit by ceiling fixtures, so its own colour has to survive being darkened; the plate,
        // band and icon are flat and read at their face value. A single colour that worked as brushed
        // metal came out muddy on a wall plate, and one that read on the wall came out fluorescent on
        // the key.
        private struct KeySpec
        {
            public string itemId;
            public string materialName;
            public Color metal;      // the key object, tinted onto the glb's own gold shading
            public Color display;    // lock plate, door band, HUD icon
        }

        private static readonly KeySpec[] Room2Keys =
        {
            // Yellow is the glb's own gold, untinted - the existing key exactly as it was.
            new KeySpec { itemId = KeyItemId, materialName = "KeyGold",
                          metal = Color.white, display = new Color(0.85f, 0.68f, 0.24f) },
            // Dark red rather than a bright one: the room's own warning red is (0.74, 0.09, 0.09) and a
            // key that matched it would read as part of the facility's signage rather than as an object.
            new KeySpec { itemId = RedKeyItemId, materialName = "KeyRed",
                          metal = new Color(1.15f, 0.30f, 0.26f), display = new Color(0.62f, 0.10f, 0.10f) },
            // The blue tint is EXTREME on purpose, and the first attempt at it came out green. The tint
            // multiplies the glb's own gold, which is (0.831, 0.686, 0.216) - so blue is the channel
            // being scaled by 0.216 while green is scaled by 0.686. A tint that looks blue on paper
            // (0.42, 0.72, 1.35) lands on (0.349, 0.494, 0.291), green-dominant, which is what shipped
            // and what had to be fixed. Working backwards from the wanted (0.13, 0.32, 0.86) instead
            // gives these, and a B of nearly 4 is simply what undoing a 0.216 costs.
            new KeySpec { itemId = BlueKeyItemId, materialName = "KeyBlue",
                          metal = new Color(0.16f, 0.47f, 3.98f), display = new Color(0.16f, 0.36f, 0.72f) },
        };
        // The three objects the final room wants, one per puzzle room. All three exist now, so all
        // three of Room4's recesses name one - which is what makes `FinalSlot.AllFilled` a real
        // question. Nothing asks it yet: see TODO.md for why the last button is still ungated.
        private const string TriangleKeyItemId = "KeyTriangle";
        private const string CubeKeyItemId = "KeyCube";
        private const string SphereKeyItemId = "KeySphere";

        // The root every third-party model lives under. `ReadModelCredits` walks it, so an asset
        // dropped anywhere inside is credited without anything else being edited.
        private const string ArtAssetsDir = "Assets/ArtAssets";

        private const string FurnitureDir = "Assets/ArtAssets/Furniture";
        // Kept apart from the furniture because neither is furniture, and because the tree is the
        // only asset in the project whose SHAPE is load-bearing - its clear trunk is the bridge.
        private const string NatureDir = "Assets/ArtAssets/Nature";
        private const string PlayDir = "Assets/ArtAssets/Play";
        private const string ToolsDir = "Assets/ArtAssets/Tools";
        // Meshes this file builds rather than imports. Written to disk because a Mesh created at
        // build time and left in memory does not survive the scene being saved - see
        // TriangularPrismMesh.
        private const string GeneratedDir = "Assets/ArtAssets/Generated";
        // 5.4m across the board: 1.8 first, then twice that, then half again. Derived, not chosen -
        // chess.glb spans 3.155m at its 0.1776 import scale, so it is 17.77m at scale 1 and 5.4 / 17.77
        // is this. A square is 0.675m and the pieces stand 0.46 to 1.09, so a king is waist-high and the
        // board is something walked around rather than looked at.
        private const float ChessScale = 0.3039f;

        // How big a piece is in the HAND, as a fraction of its size on the board. The tallest piece is
        // 1.09m at the scale above and a hold 0.5m from the eye can show about 0.58m of height, so a
        // piece at its own size fills the screen twice over. 0.28 brings a king to 0.30m - large enough
        // to tell a king from a pawn, small enough to see the room past it.
        private const float HeldPieceScale = 0.28f;

        // How far a held piece is turned about its own vertical. Face-on, a bishop and a pawn are the
        // same silhouette; a three-quarter view is what makes the thing in your hand identifiable.
        private const float HeldPieceYaw = 25f;

        // Eight files and eight ranks. Named rather than inlined because the grid is MEASURED off the
        // opening position - see BuildChessSet - and this is the number that measurement divides by.
        private const int SquaresPerSide = 8;

        // HOW MANY PIECES ARE MISSING OFF THE BOARD, and therefore how long the puzzle is. It is the
        // one number that sets Room2West's cost, so it lives here.
        //
        // Twelve, because the cost is paid in ITERATIONS and they compound: a player who tidies four in
        // a loop has four past selves tidying four for them in the next, so twelve is about three
        // iterations of work and not twelve.
        //
        // MEASURED 2026-08-12: the whole game clears in FIFTEEN iterations, up from the four it took
        // before this room and the cube room were on the critical path. So this constant is the
        // game's length dial, and twelve is not a small number - it is most of the run. Turn it down
        // before adding rooms, not after.
        //
        // The other twenty stay on their squares. That is not padding - it is the statement of the
        // puzzle: a board that is nearly right shows the player exactly which squares are empty, and
        // there is nothing to work out and no layout to memorise.
        private const int ScatteredPieceCount = 12;

        // Fixed, because a scene is BUILD OUTPUT: two builds of the same commit have to lay the room
        // out identically, or a bug found in one is not reproducible in the next.
        private const int ChessScatterSeed = 20260812;
        private const int CubeScatterSeed = 20260813;
        private const string SettingsDir = "Assets/Settings";
        // Wall panel albedo. Near-white is the reference film's clinical room; the dark value reads
        // as a switched-off display, which only becomes legible because the panels are glossy and
        // have a reflection probe to mirror - a matte dark panel would just be a black hole.
        // Kept well clear of GrooveDark (0.04) so the seams still read against it.
        private static readonly Color WallPanelColor = new Color(0.13f, 0.135f, 0.15f);

        // **WHAT A LIT PANEL'S ALBEDO IS, AND WHY IT IS NOT 1.0** (2026-08-25).
        //
        // Albedo 1.0 is a surface that returns every photon it receives and absorbs none. Nothing
        // does; fresh white paint is about 0.85, which is what the FLOOR was already set to when play
        // reported it as "too white" - and the walls and ceiling were left at 1.0, because with no
        // bounce being computed it made no difference.
        //
        // **It makes all the difference now, and it is a DIVERGENCE.** Indirect light is a geometric
        // series in albedo: at 0.85 it converges to 1/(1-0.85) = 6.7x the direct light, and adding
        // bounces past about eight changes nothing. At 1.0 it does not converge at all - every bounce
        // adds the SAME amount again, forever - so the room's brightness became a function of the
        // bounce COUNT rather than of its lighting. That is exactly what play saw: two bounces looked
        // fine, eight was bright, sixteen was "over-bright". The count was never the problem.
        //
        // **This must match `WallPanelDisplay.onColor`, which is why it is one constant.** The bake
        // reads the material and the runtime paints the property block, so if they disagree the room
        // is lit for one wall and rendered as another.
        private static readonly Color PanelLitColor = new Color(0.85f, 0.85f, 0.86f);

        // **HOW BRIGHT A CEILING FIXTURE IS - and since the ambient went to zero, this is the ONLY
        // thing that sets how bright the building is** (2026-08-25).
        //
        // It was 10.5 in three separate literals and one derivation, which is three places to forget.
        // 10.5 was itself derived - `9 x (5.408/5.0)^2` - to hold the floor where it had been signed
        // off at a lower ceiling, back when flat ambient was carrying most of the room.
        //
        // **7, because 10.5 was measurably blowing the floor out.** Sampling the menu render's floor
        // gave (241, 255, 255) with 39% of its pixels at or past 254 - clipped, not bright. This is
        // the second time that has been measured on this exact surface; the first was answered by
        // dropping the floor's albedo to 0.85, which is now as low as it should go.
        //
        // **This is the right lever and the other two are not.** Bounces are converged at eight now
        // that albedo is below 1, so cutting them would deliberately under-compute light to hide
        // having too much of it; and albedo below ~0.8 stops being white paint and makes the cell
        // grey. Intensity scales the direct light and everything that bounces off it TOGETHER, which
        // is the only change that dims the room without changing what it looks like.
        // Read off `LightingTuner` 2026-08-26, with the ambient bands above. It came DOWN from 10.5
        // as the ambient went up - see there. 10.5 was itself derived (`9 x (5.408/5.0)^2`) to hold
        // the floor at a brightness signed off under a lower ceiling; this replaces that derivation
        // with a look.
        private const float CeilingLightIntensity = 7.022f;

        // **155 DEGREES, WIDENED FROM 130** (same pass). A wider cone from 5.41m spreads the same
        // flux over more floor, so the bright pool under each fixture softens and the room reads
        // evenly lit rather than spotted. It is the other half of the same decision as the intensity
        // above and they move together: widening alone would dim the floor, dimming alone would keep
        // the pools.
        private const float CeilingSpotAngle = 156.798f;

        // Room2West's ceiling fixtures, filled in by BuildShell and read by one thing: the chess
        // board dims them and brings them back up as its reward. Held here rather than found by name
        // later, because a lookup by name is a second statement of what BuildCeilingLights called them.
        private static Light[] Room2WestLights;
        // The calibration room's own fixtures, kept because `LightingTuner` drives them - that room
        // is where the lighting is tuned, so it is the one room whose lights something else holds.
        private static Light[] CalibrationLights;
        private static Renderer[] Room2WestPanels;

        private const string TexturesDir = "Assets/Textures";
        // Symbols printed on the cube room's cubes and on the recesses that want them. Their own
        // folder because they are WORLD textures - mipmapped, opaque, imported as Default - where
        // everything in Icons/ is a HUD sprite with its shape in the alpha.
        private const string SymbolsDir = TexturesDir + "/Symbols";
        // Near-white paper and near-black ink, which is the building's own palette. Contrast rather
        // than colour is the whole point: a spade has to be a spade to a player who cannot tell red
        // from green, and at whatever brightness the room happens to be.
        private static readonly Color SymbolPaper = new Color(0.88f, 0.88f, 0.90f);
        private static readonly Color SymbolInk = new Color(0.07f, 0.07f, 0.09f);
        private const string IconsDir = TexturesDir + "/Icons";
        private const string MenuBackgroundPath = TexturesDir + "/MenuBackground.png";
        // **THE SAME SHOT WITH HALF THE ROOM'S FIXTURES OFF.** The title screen flickers by fading
        // this over the one above - see `MenuFlicker` for why a photograph cannot do it any other
        // way, and `CaptureMenuBackground` for the one rule that keeps the pair usable: both frames
        // are taken from the same camera in the same pose, so nothing between them moves except the
        // light.
        private const string MenuBackgroundDarkPath = TexturesDir + "/MenuBackgroundDark.png";
        // The menu capture's tripwire colour, and how much of it a frame is allowed to show.
        // Magenta because the room is white panelling and black grooves and cannot produce it; the
        // threshold is 1% against a measured 0 stray pixels out of 1920x1080, so the margin is
        // slack, not a tuned number. Why a tripwire at all: `docs/gotchas.md`.
        private static readonly Color MenuCaptureTripwire = Color.magenta;
        private const float MenuCaptureMaxStray = 0.01f;
        private const string FontsDir = "Assets/Fonts";
        private const string AudioDir = "Assets/Audio";
        private const string VoiceDir = AudioDir + "/Voice";
        private const string SfxDir = AudioDir + "/SFX";

        // Must match the range Tools/generate_narration.ps1 writes out. Past this the announcer
        // falls back to a generic line rather than going silent.
        private const int NarrationIterationLines = 30;

        // The attribution shown at the bottom of the title screen. Everything in this project is
        // generated from a script except the two furniture models and the HUD typeface, so this is
        // ~~`CreditsLine`~~ **REPLACED 2026-08-23 by a generated credits PAGE.** One dim line reading
        // "FURNITURE MODELS: CREATIVE COMMONS" named no author, no title, no licence version and no
        // link - a statement that a licence exists somewhere rather than an attribution, for
        // twenty-six CC-BY models. See `ReadModelCredits` and `BuildCreditsPage`.

        // Balloons get their own physics layer so the player's CharacterController can exclude it
        // outright. See FirstPersonController.PushOverlapping for why not colliding with them at
        // all is the point rather than a shortcut.
        private const string BalloonLayerName = "Balloon";

        // Room shell dimensions. The wall-grid tiling is derived from these (see MakeGridMaterial),
        // so changing a dimension here keeps the grid cells the right physical size automatically -
        // don't hardcode tiling numbers anywhere else.
        private const float RoomWidth = 8.75f;   // X span, i.e. the door wall
        private const float RoomDepth = 10.5f;   // Z span, i.e. the side walls
        // Not a round number, and worth knowing why: this is what the golden-ratio pass left the
        // room at, when it was five phi-proportioned cells tall. The cells have since been made
        // taller and the ratio has gone, but the height itself was deliberately kept - it is what
        // the fixture intensity and the two reflection probes are tuned against, and moving it
        // would invalidate both for no gain.
        private const float RoomHeight = 5.4077968f;
        private const float WallThickness = 0.1f;

        // Wall grid cells are deliberately landscape: 1.75 x 1.3519, a ratio of about 1.29.
        //
        // Two hard constraints sit behind these numbers. A cell's WIDTH has to divide both 8.75 and
        // 10.5 exactly, or the last column of a wall overshoots its end (BuildPanelWall lays cells
        // at fixed GridCellWidth steps after rounding the column count). A cell's HEIGHT has to
        // divide RoomHeight exactly, or the top row is a part cell and the panelling runs off cut
        // in half at the ceiling - which is what a 4.5m room height once did.
        //
        // The height constraint is enforced by construction rather than by care: RoomHeight is the
        // fixed dimension and the cell height is derived from it. To change how tall the cells are,
        // change GridRows - four rows instead of five is what took them from 1.0816 to 1.3519.
        //
        // The cells were briefly exactly phi:1 (1.75 x 1.0816, five rows). That is where the odd
        // room height below comes from, and the ratio went when the cells were made taller; phi
        // could not have survived the change anyway, since it needs a specific height and this asks
        // for a different one.
        private const float GridCellWidth = 1.75f;
        private const int GridRows = 4;
        private const float GridCellHeight = RoomHeight / GridRows;         // 1.3519
        // Wide enough to read as a real reveal between panels rather than as a drawn line. It was
        // 0.082 while the cells were shorter; the taller the panel, the more groove it takes to
        // keep the same visual weight.
        private const float GridLineThickness = 0.05f;

        // How far the gaps between wall panels are recessed. This is what turns the grid from a
        // drawing into geometry: the recesses catch real shadow and ambient occlusion.
        // Deep enough to catch ambient occlusion, shallow enough that the panels' white side faces
        // don't wash the seam out when you view a wall at a grazing angle.
        private const float GrooveDepth = 0.025f;

        // HOW WIDE THE CHAMFER ON A PANEL'S FRONT RIM IS - see `ChamferedPanelMesh`.
        //
        // 6mm against the panel's own 25mm of relief. Large enough that the band is a line the eye
        // reads rather than an aliased pixel at the far end of a room, and small enough that 19mm of
        // straight side is left to be the groove wall - a chamfer that ate the whole depth would turn
        // every panel into a shallow pyramid and lose the flat face the room is made of.
        private const float PanelChamfer = 0.006f;

        // HOW FAR THE WEAR PASS IS ALLOWED TO DULL A SURFACE, as a fraction of its authored
        // smoothness - see `MakeSmoothnessMap`. 0.72 means the dullest patch reflects about three
        // quarters as sharply as the cleanest, which on the walls' 0.85 is a range of 0.61 to 0.85.
        //
        // Deliberately modest. This is a pass that should be impossible to point at and easy to miss
        // when it is switched off; a wide range reads as dirt, and the facility is not dirty, it is
        // used. Turn it toward 1.0 to disable the effect without removing the texture.
        // **1.0 MEANS THE WEAR MAP IS OFF, AND THAT IS DELIBERATE (2026-08-25).**
        //
        // It was added the same day to break up "perfectly uniform roughness", which really is one of
        // the strongest tells that a surface is rendered. It replaced that tell with a worse one:
        // reported from play, twice, as pale grey squares repeating across the walls and floor.
        //
        // **The cause is the TILING, not the noise, and it cannot be tuned out.** URP/Lit drives every
        // secondary map from `_BaseMap`'s single UV transform, so the wear map is locked to the
        // (5,3)-per-panel tiling the NORMAL map needs for its fine grain. That puts fifteen copies of
        // the same tile on every panel and the same fifteen on all 88 of them - and value noise has
        // its extrema on a lattice, so what repeats is a regular grid of soft blobs. Decorrelating the
        // octaves (coprime periods, a third octave) was simulated and does not help: the repeat is the
        // artifact, not the octave design. It shows worst at GRAZING angles, where the specular is
        // strongest, which is why the head-on walls always looked fine.
        //
        // **If per-surface variation is wanted back, it has to come from somewhere that is not a
        // tiled texture.** The building is made of discrete panels, so the shape that fits is one
        // smoothness value PER PANEL through the property block `WallPanelDisplay` already owns - no
        // tiling, and variation at the scale the architecture actually has.
        //
        // The map is still generated and still carries metallic in red; only its alpha is now a flat
        // 1.0, which multiplies smoothness by nothing. Set this back below 1 to re-enable it.
        private const float WearFloor = 1.0f;

        // Natural door proportions, deliberately NOT snapped to the grid - the panelling is cut
        // around it instead, so it reads as a doorway rather than a missing panel.
        private const float DoorWidth = 1.3f;
        private const float DoorHeight = 2.5f;
        private const float DoorThickness = 0.06f;
        // Clearance left between the two rooms' walls. The door lives in this cavity and slides
        // sideways into it, so when it's open both walls hide it - a pocket door.
        private const float DoorPocketDepth = 0.1f;

        // How high a step the player walks up without jumping. See where it is applied for why it is
        // this and not higher: it has to clear half a grid row and stay under the jump.
        private const float PlayerStepOffset = 0.72f;

        // ROOM3-1'S GATES ARE PANELS, NOT DOORS. An ordinary door in this building is 1.3 x 2.5 and
        // reads as a door; a gate is TWO CELLS of the wall's own grid wide and TWO ROWS tall, cut on
        // the grid lines, so what opens is a piece of the wall rather than a thing set into it.
        //
        // Only the HEIGHT is a constant. The width and where along the wall it sits are `GateSpan`'s
        // to answer, because they depend on whether that wall's cell count is even - and a constant
        // here would be a second answer that happens to agree.
        private const float GateHeight = 2f * GridCellHeight;    // 2.7038


        // Where room3-2N's CENTRE sits, and the corridor's far end is derived from it. Its own south
        // face is half of its doubled depth back from here, which is not `RoomDepth / 2` any more -
        // getting that wrong leaves the corridor ending inside the room or short of it, and neither
        // announces itself.
        // **EVERY CORRIDOR DIMENSION IS AN EXACT MULTIPLE OF THE GRID, and the first version was not.**
        // `BuildPanelWall` divides a wall's width by its ROUNDED cell count, so a 22.05m corridor came
        // out in cells of 1.696 where every other wall in the building is 1.75 - a different rhythm,
        // and visible the moment you look down it from room3-1. Its height did the same thing one axis
        // over: corridor plus shaft came to 5.5076, which is four rows of 1.3519 plus a 0.1m SLIVER,
        // and a cut-off panel against the top is the exact fault play called out on the tree hall.
        //
        // Thirteen cells and four rows. The room beyond is placed FROM the corridor rather than the
        // corridor being measured between the rooms, because only one of the two can be the multiple.
        private const float CorridorRun = 13f * GridCellWidth;          // 22.75
        private const float CorridorShaftHeight = 2f * GridCellHeight;  // 2.7038 - shaft top is row 4

        // Room3-2N's centre. FOUR wall build-ups between the two rooms' inner faces, not two: one
        // for each room's own wall, and one more at each end for the corridor's overrun to sit in
        // WITHOUT touching them. See the corridor's own note on why touching is the whole problem.
        private const float NorthRoomZ =
            RoomDepth / 2f + 4f * WallDepth + CorridorRun + RoomDepth;

        // The east-west equivalent of `RoomPitch`. Rooms are 8.75 across and 10.5 deep, so a
        // neighbour to the side sits at a different remove from one in front - and the term that is
        // NOT the room's own size is identical, which is the point: the two walls meet with the same
        // build-up and the same pocket a door slides into, so a gate works on any of the four.
        private const float RoomPitchX = RoomWidth + 2f * WallDepth + DoorPocketDepth;

        // Total build-up of a wall from the room surface outwards: recess + backing slab.
        private const float WallDepth = GrooveDepth + WallThickness;
        // Centre-to-centre spacing of adjacent rooms: one room, both sides of the divider, and the
        // pocket between them.
        private const float RoomPitch = RoomDepth + 2f * WallDepth + DoorPocketDepth;

        // THE GAP BETWEEN ONE CYCLE'S FLOOR AND THE NEXT ONE'S CEILING, and it exists for a reason
        // that only showed up once there was a room underneath.
        //
        // **Every `RewardPlinth` retracts about a metre BELOW its floor.** Room1-0's console sinks
        // 1.13m, which was invisible while there was nothing under it and became a box hanging out of
        // room2-1's ceiling the moment there was. Housing it did not help: the housing hung into the
        // room too. The only fix that leaves the room below clean is for the machinery to have
        // somewhere to be that is not in either room - which is what a real building would do.
        //
        // 1.6m: the console's 1.13m of travel, its housing, and clearance. The shaft between the two
        // holes runs through this, so it is also how long the drop feels before the lower room opens
        // up underneath.
        private const float ServiceVoid = 1.6f;

        // HOW FAR DOWN THE NEXT STOREY IS. A cycle's rooms sit one of these below the cycle before it.
        //
        // The upper room's floor spans y -WallThickness..0 and the lower room's ceiling spans
        // -(ServiceVoid + 2*WallThickness)..-(ServiceVoid + WallThickness), with the void between
        // them. The hole cut through both lines up because it is the same Rect in each room's local
        // XZ - see BuildExitShaft for what joins them.
        private const float StoreyDrop = RoomHeight + 2f * WallThickness + ServiceVoid;

        // WHERE A CYCLE'S WAY OUT IS, in room-local Z. Behind the console from the player's approach,
        // which is always from -Z: the console body ends at z = 0.575, so this clears it, and the north
        // wall is at 5.25, so it clears that too.
        private const float CycleExitZ = 2f;

        // One wall grid cell across, and square. The grid gives the SIZE - a hole on the building's own
        // module reads as a piece of the structure coming away rather than as a hatch fitted to a
        // person - and squaring it is what makes it something to fall down rather than step through.
        //
        // The same Rect is handed to the room above's FLOOR and the room below's CEILING, in each one's
        // local XZ. That is why they line up: not two numbers kept in agreement, one number used twice.
        private static readonly Rect CycleExitHole = Rect.MinMaxRect(
            -GridCellWidth / 2f, CycleExitZ - GridCellWidth / 2f,
             GridCellWidth / 2f, CycleExitZ + GridCellWidth / 2f);

        // THE SAME HOLE SEEN FROM THE CYCLE BELOW, mirrored in Z.
        //
        // The two slabs the shaft passes through are cut with the same Rect in each room's own local
        // XZ, which lined them up for as long as both rooms faced the same way. Cycle 2 is turned
        // 180 degrees now (see CycleTwoYaw), so its first room's local +Z is the world's -Z and the
        // unmirrored Rect would cut its ceiling four metres from where cycle 1 cut its floor - a
        // shaft into solid slab, and nothing else in the build would have complained.
        private static readonly Rect CycleExitHoleFromBelow = Rect.MinMaxRect(
            -GridCellWidth / 2f, -CycleExitZ - GridCellWidth / 2f,
             GridCellWidth / 2f, -CycleExitZ + GridCellWidth / 2f);

        // Cycle 2 sits one storey down and runs BACK the way cycle 1 came. Its first room is directly
        // beneath cycle 1's last, so the drop is short and vertical and the player can see the bed
        // through the opening before committing to it; everything after it walks toward -Z.
        // HOW MANY CYCLES THE GAME HAS. Read by the title screen's picker; `LoopManager` derives the
        // same fact from the length of its own array, which is the authority. Adding a cycle means
        // changing both, and they are meant to be found together.
        private const int CycleCount = 3;

        private const float CycleTwoFirstRoomZ = 5f * RoomPitch;

        // HOW FAR APART TWO ROOMS SIT AT A CORNER, where one presents its WEST wall and the next
        // presents its NORTH wall.
        //
        // `RoomPitch` cannot serve, and that is the one piece of arithmetic the ring turns on: a room
        // is 8.75 across and 10.5 deep, so two rooms meeting along the same axis are a different
        // distance apart than two meeting across a corner. Half of each, plus the same divider every
        // other join has.
        private const float CornerPitch = RoomWidth / 2f + RoomDepth / 2f + 2f * WallDepth + DoorPocketDepth;

        // ---------------------------------------------------------------------------------------
        // CYCLE 2 IS TURNED ROUND, 2026-08-16, and this one line is what let the tree hall exist.
        //
        // The ring used to switchback back along -Z, which ran it directly UNDER cycle 1's corridor.
        // That is what capped the hall's ceiling: raise a room to 17.5m with cycle 1 five metres
        // above it and the ceiling drives up through the floor of the room above. The first version
        // worked around it by keeping half the hall short.
        //
        // Turning the ring 180 degrees ABOUT THE BED removes the constraint instead of dodging it.
        // The bed has to stay where it is - it is what the exit shaft drops into - so the rotation
        // pivots there, and every other room swings out to z > 59.5, which is past the end of cycle
        // 1 entirely. **Nothing is above cycle 2 any more except its own first room**, so any room
        // in it can be any height, now and for every cycle-2 room designed later.
        //
        // Implemented as a rotation on the cycle root with the pivot folded into its position, so
        // that everything INSIDE cycle 2 is authored in the same local frame it always was.
        private static readonly Quaternion CycleTwoYaw = Quaternion.Euler(0f, 180f, 0f);

        // THE TREE HALL: room2-3, room2-4 and room2-5 merged into ONE space.
        //
        // ONE BOX, at ONE height. The first version kept the three rooms' differing widths - a 10.5m
        // bay opening into an 8.75m run, with a soffit over the step - because the bay could not be
        // raised. With the ring turned round that reason is gone, and the hall is a single room:
        // 10.5m across, 30.45m along, 17.57m to the ceiling.
        private const float TreeHallHeight = GridCellHeight * 13f;   // 17.5746, thirteen grid cells

        // ACROSS the hall. It is `RoomDepth` because the r2 join fixes it there: r2's south face has
        // to meet the hall's north wall and r2 is an ordinary room, so widening past this would mean
        // moving r2 rather than the hall.
        private const float TreeHallWidth = RoomDepth;               // 10.5

        // The north wall is the one BOTH doorways are in - r2's near the east end, r6's near the
        // west - so everything else is measured off it. Making the two openings share a wall is what
        // let the width be uniform at all: they used to be in walls 0.875m apart, which is precisely
        // the step the soffit was covering. See BuildCycleTwoShell for the 0.875m leg-3 shift that
        // pays for it.
        private const float TreeHallNorthFace = RoomDepth / 2f;                 // +5.25
        private const float TreeHallSouthFace = TreeHallNorthFace - TreeHallWidth;

        // The two ends, unmoved: r3's east wall and r5's west wall.
        private const float TreeHallEastFace = RoomWidth / 2f;                              // +4.375
        private const float TreeHallWestFace = -CornerPitch - RoomPitch - RoomDepth / 2f;   // -26.075

        // THE PIT: room2-4's full 10.5m, wall to wall across the hall, which is what makes it
        // uncrossable. Placed to leave a ledge at each end rather than at room2-4's own footprint -
        // that would have put the lip 0.35m inside the entrance and left nowhere to stand and swing.
        // The near ledge carries the tree, the far one carries the door out.
        private const float TreePitEastEdge = -5.5f;
        private const float TreePitWidth = RoomDepth;                                 // 10.5
        private const float TreePitWestEdge = TreePitEastEdge - TreePitWidth;         // -16.0

        // How far down it goes. Deep enough that the bottom is not part of the picture - falling in
        // is fatal (see KillVolume), so this is what the drop looks like, not somewhere to land.
        private const float TreePitDepth = 26f;

        // Where the two doorways sit along the north wall - the entrance under r2, the exit under
        // r6. Both are a long way clear of the lip: a doorway on the edge of a fatal drop is a place
        // to be nudged into it.
        private const float TreeHallEntranceX = 0f;
        private const float TreeHallExitX = -CornerPitch - RoomPitch;                 // -20.825

        // ---------------------------------------------------------------------------------------
        // ROOM2-5: THE SLIDE, ITS MOUTH, AND THE ROOM ON THE OTHER SIDE OF THE WALL.
        //
        // THE SLIDE AND THE SEESAW WERE PLACED BY HAND IN THE EDITOR AND READ BACK, the same way
        // room2-1's switch height was. Three things about these numbers matter:
        //   - each is the MODEL NODE's own pose in the hall's frame, not a wrapper's, so it can be
        //     applied straight to the imported instance and land where the editor showed it;
        //   - the 270 in each rotation is the glTF import's Z-up correction. It is PART OF THE POSE,
        //     not noise - "tidying" it to zero lays the model on its face;
        //   - the scales are what the hand placement left rather than a fresh fit. The slide keeps
        //     the 0.5403 its old room2-6 fit produced; the seesaw's 0.3709 is a nudge off its 0.3808.
        private static readonly Vector3 SlideLocalPosition = new Vector3(-24.8773f, 0.0610f, -4.8604f);
        private static readonly Vector3 SlideLocalEuler = new Vector3(270f, 183.654f, 0f);
        private const float SlideLocalScale = 0.5403f;

        private static readonly Vector3 SeesawLocalPosition = new Vector3(-19.8104f, 0.9773f, 2.2949f);
        private static readonly Vector3 SeesawLocalEuler = new Vector3(270f, 76f, 0f);
        private const float SeesawLocalScale = 0.3709f;

        // THE MOUTH: where the chute goes through the south wall, and the whole reason the room
        // beyond it exists.
        //
        // From the hall's west corner east to just past the chute's outer rail. That is slightly
        // WIDER than the one panel cell cleared by hand: the rails are wider than a cell, and a chute
        // clipping the edge of its own opening is a hole that does not look like the thing going
        // through it. 1.7m tall, which clears a rider sitting up - the chute's surface is still half a
        // metre off the floor where it passes the wall.
        private const float SlideMouthEast = -23.72f;
        private const float SlideMouthHeight = 1.7f;

        // THE RIDE, in hall coordinates - and only its X and Z. The head is the flat platform the
        // stairs arrive at, the foot is where the chute's tip passes the wall plane, the landing is
        // out on the floor of the room beyond. EVERY HEIGHT IS RAYCAST at build time off whatever is
        // actually under the line, so the path is the chute's own surface rather than a description
        // of it, and a slide that is moved or replaced gets a new path for free. See SampleRidePath.
        private static readonly Vector2 SlideRideHead = new Vector2(-24.70f, 0.15f);
        private static readonly Vector2 SlideRideFoot = new Vector2(-24.70f, -5.50f);
        // FURTHER INTO THE ROOM than it used to be. The run-out is no longer a run-out: the chute's tip
        // now hangs inside the landing room near the top of its wall, so this leg is a plunge into the
        // water rather than a slide across a floor, and how far it reaches is what sets how steep that
        // plunge is. At -9.80 it is about 4.3m along for 4.0m down - 43 degrees, which is a slide's
        // last stretch. -8.40 made it 55, which is a fall with a direction.
        private static readonly Vector2 SlideRideLanding = new Vector2(-24.70f, -9.80f);
        private const int SlideRideSamples = 26;
        // The plunge off the end of it. More samples than the six the old flat run-out needed, because
        // this leg is now a CURVE - see SampleRidePath - and six points across a four-metre arc is a
        // staircase.
        private const int SlideRidePlungeSamples = 12;

        // THE ROOM THE SLIDE LANDS IN: an ordinary shell hung on the hall's south wall at the west
        // end, its west wall flush with the hall's own - so the mouth is in a corner rather than
        // adrift in a long wall. Nothing is above or below it: cycle 2 was turned round in 2026-08-16
        // and this is SOUTH of the hall, which is past the end of cycle 1 entirely.
        private const float SlideRoomCentreX = TreeHallWestFace + RoomWidth / 2f;              // -21.7
        private const float SlideRoomCentreZ = TreeHallSouthFace - (2f * WallDepth + DoorPocketDepth)
                                             - RoomDepth / 2f;                                 // -10.85

        // HOW FAR BELOW THE HALL IT SITS, and this number is DERIVED rather than chosen (2026-08-19,
        // second pass). It was `-StoreyDrop` - a full storey plus the service void - and at that depth
        // the two openings did not meet: the chute left the hall at the hall's own floor and the room's
        // opening was five metres further down, so the rider passed through solid slab and arrived
        // falling out of the ceiling, and the hole in the hall's wall looked into a void rather than
        // into the room.
        //
        // The room's CEILING is now exactly the top of the mouth. Both walls are then cut over the same
        // 1.7m band (`SlideMouthHeight`), so the hall's opening and the room's are ONE HOLE with a
        // wall's thickness of tunnel between them: standing at the top of the slide you look through it
        // and see the room, its water and the balls on it before you commit to the ride.
        //
        // What it costs is a drop - the chute's tip is at the top of that wall and the floor is a room's
        // height below it. That is the point rather than a leftover: it is a slide over a pool, and the
        // water is what it drops into.
        private const float SlideRoomFloorY = SlideMouthHeight - RoomHeight;                   // -3.708

        // THE WAY BACK. A slide is one-way, so without a door this room is somewhere the player can
        // only wait out the clock. At the far end of the wall from the mouth: down the slide, across
        // the room, back up through the door.
        private const float SlideRoomDoorX = -18.90f;
        // Where the south wall is split into two spans - between the mouth and the doorway, because
        // `SubtractRect` takes one hole per wall and this wall now has two. Same trick as the north.
        private const float SlideRoomWallSplitX = -21.70f;

        // THE ROOM IS FLOODED, 2026-08-19 by request: the slide does not land on a floor, it lands in
        // water, and plastic balls float on it. It is PRESENTATION AND NOTHING ELSE - the water is not
        // solid, not fatal, not a puzzle and not recorded. The player wades out of it.
        //
        // 1.2m, which is waist-to-chest on a 1.8m body and the depth that was asked for. It is also the
        // deepest this can go without becoming a mechanic: the eye is at 1.6m, so at 1.2m the player
        // looks DOWN at the surface from above it, and anything deeper puts the waterline across the
        // camera and needs an underwater view, a swim and a way out of it that this room does not have.
        private const float PoolDepth = 1.2f;
        // The grid step the surface is built on. See WaterMeshes.Sheet for why a room-sized quad is not
        // enough: the shader's wobble lives on the vertices, so a sheet with none in the middle is flat
        // in the middle. ~3,000 triangles at this room's size.
        private const float PoolSurfaceCell = 0.25f;
        // HOW MANY BALLS FLOAT ON IT. Not a carpet: things that float SPREAD, and the ball pit in
        // room2-7 is what a floor covered in balls already looks like. Three hundred over ninety square
        // metres is a ball every half metre or so - enough that they are everywhere the eye goes and
        // sparse enough that the water is still the thing under them.
        //
        // It is also what the drift costs. These are individual renderers rather than one merged mesh
        // (see FloatingBalls), so the count is a draw-call count, and a couple of hundred instanced
        // spheres is cheap where a couple of thousand would not be.
        //
        // CUT FROM 300 the same day it was written, once the ducks and the beach balls went on the
        // water: three hundred small balls is a surface the bigger things have to be picked out OF,
        // and the whole reason to have them is that they are seen.
        private const int PoolBallCount = 210;
        // The same 220mm ball the pit is built from, which means the same generated mesh asset.
        private const float PoolBallRadius = BallRadius;
        // How high a ball rides. A hollow plastic ball is nearly all air, so it sits high in the water -
        // a sphere half under reads as a heavy one, which is a different object.
        private const float PoolBallFloat = 0.72f;

        // CYCLE 3, AND IT IS PLACED BY MEASUREMENT RATHER THAN BY THE RING.
        //
        // Cycle 1 and cycle 2 are stacked on the ORIGIN - cycle 2 is one `StoreyDrop` under cycle 1's
        // last room and turned about its own bed. Cycle 3 cannot be: cycle 2's walk wanders twenty
        // metres west and two rooms south of where it started, and it ENDS in room2-0. The bed a
        // player wakes in has to be under the hatch they fell through, so these two numbers are
        // room2-0's own centre, and the storey below it is where cycle 3 begins.
        //
        // Read off the built scene rather than derived: room2-0's world position is the product of the
        // tree hall's origin, the slide room's offsets and `CycleTwoYaw`, and re-deriving that chain
        // here would be a second copy of it to keep in step. If room2-0 ever moves, these move with it
        // and the build says so - `AssertUnderHatch` below fails the build if they drift apart.
        private const float CycleThreeX = 21.7f;
        private const float CycleThreeZ = 108.5f;
        // Room2-0's floor is at -10.916; one storey under it is where cycle 3's floor goes.
        private const float CycleThreeFloorY = -10.916f - StoreyDrop;

        // ROOM2-0: THE END OF CYCLE 2, and the four pedestals that break it.
        //
        // THE SHAPE OF THE PUZZLE. Four pedestals rise as the player comes through the last door, each
        // with a recess in its top and one object drawn on the side facing them. What goes in the
        // recess is the billiard ball whose NUMBER is how many of that object cycle 2 contains - four
        // buckets, five axes, two beach balls, three rubber ducks - so the answer is not written
        // anywhere and cannot be, it is a count of rooms the player has already walked through. All
        // four right and the cycle breaks, exactly as cycle 1's console breaks cycle 1.
        //
        // WHY A ROW AND NOT A SQUARE ROUND THE HATCH, which was the first arrangement tried on paper:
        // a square puts two of the four pictograms facing AWAY from a player walking in, and the
        // pictogram is the only thing that says which pedestal is which. A row facing the door shows
        // all four at once from the threshold.
        private const float PedestalWidth = 1.10f;
        private const float PedestalDepth = 0.80f;
        // Waist height, like cycle 1's console and for the same reason: the recess in the top is
        // looked DOWN into from a 1.6m eye rather than squared up to.
        private const float PedestalHeight = 1.05f;
        // 1.95 apart spans 5.85 of the room's 8.75, which leaves a stride between neighbours - enough
        // that standing at one is unambiguously standing at one, and `BuildFinalSlot`'s reach volumes
        // (1.3 wide) cannot overlap.
        private const float PedestalPitch = 1.95f;
        // South of centre, with the hatch at the room's middle in FRONT of the row: the way down opens
        // between the player and the door they came in by, which is where they are looking anyway.
        private const float PedestalRowZ = -2.80f;

        // THE BOWL IN THE TOP OF A PEDESTAL, cut to the ball's own radius with 5mm of daylight round
        // it - enough that the ball drops in rather than being pressed into a shell of its exact size,
        // and little enough that nothing else in the game would sit in it.
        private const float SocketBowlRadius = BilliardBallSize / 2f + 0.005f;
        // How thick the cap the bowl is cut out of has to be. The bowl's own depth is its radius; the
        // rest is material under the pole, so the cap is a solid thing with a hole in it rather than a
        // shell that meets itself at a point.
        private const float SocketCapThickness = SocketBowlRadius + 0.006f;

        // HOW FAR A GHOST MAY REACH FOR A DUCK OR A BEACH BALL. The pool room is 8.75 x 10.5, and the
        // drain that drags them all to its middle is at most 6.8m from any corner of it - so this
        // covers every way one of them can have moved since the recording was made, and stops well
        // short of being able to reach a neighbouring room. See `CarryableItem.ghostTakeReach`.
        private const float PoolPropTakeReach = 9f;

        // A BILLIARD BALL, at more than twice life size (57mm). Every object in this building is
        // oversized - a 220mm ball-pit ball, a 160mm Rubik's cube, a 13m tree - and a ball has to be
        // read by its NUMBER from across a drawer, which a 57mm sphere at arm's length is not.
        private const float BilliardBallSize = 0.13f;

        // THE WAY DOWN OUT OF CYCLE 2, one grid cell in the middle of room2-0's floor. Centred on the
        // room rather than offset like cycle 1's `CycleExitHole`, which sits 2m behind that console
        // because the console is in the middle of ITS room; here the pedestals are the thing that is
        // off-centre and the hole is what "the floor opens in the middle" means.
        private static readonly Rect CycleTwoExitHole = Rect.MinMaxRect(
            -GridCellWidth / 2f, -GridCellWidth / 2f,
             GridCellWidth / 2f,  GridCellWidth / 2f);

        // Where the tree stands: 0.85m back from the lip, which is what it takes to keep the stump's
        // own collider off the pit - `AssertNotWalkable` caught 0.45m on the first build, which is
        // what that assert is for.
        // PLUS, not minus: the near ledge is EAST of the pit's east edge, and subtracting put the
        // tree 0.85m out over the hole. `AssertNotWalkable` caught it on the first build - which is
        // twice now that this one constant has been wrong and twice that the same assert has said so.
        private const float TreeStandX = TreePitEastEdge + 0.85f;                     // -4.65
        // Where the trunk is cut, and where the notch is bitten. A real chopping height, and it is
        // what divides the model in two: below stays as the stump, above becomes the bridge.
        private const float TreeCutHeight = 1.2f;
        // SUNK, so the base reads as growing out of the floor rather than as a model set down on it.
        // The flare at the bottom of this trunk is what gives it away: standing exactly on y=0 it
        // meets the floor along a hard line all the way round, which nothing that grew there would.
        private const float TreeSinkDepth = 0.24f;
        // Clearance left between the crown and the side walls. The tree is scaled to FIT rather than
        // set to a number - see BuildTree - because the crown is 11.72m across at native size and
        // the hall is 10.5m, so a native-scale tree grows through both walls.
        private const float TreeWallClearance = 0.35f;
        // How many notch stages are cut. Each is a real hole in the trunk mesh, built here and
        // switched at runtime - see BuildTree for why the notch is geometry rather than a decal.
        private const int TreeNotchStages = 8;
        // How far the V opens per metre of depth - about 22 degrees off the cut plane. It is HERE
        // rather than inside the carve because the heartwood has to be exactly as tall as the notch
        // is, and the two disagreeing is what leaves a hole you can see through the tree.
        private const float TreeNotchHalfAngleTan = 0.40f;


        // The sensitivity room. Deliberately NOT a multiple of RoomPitch in the positive direction
        // - it is not part of the chain and must never be walked into, so it sits behind Room1 with
        // a room's worth of nothing between them.
        private const string CalibrationRoomName = "CalibrationRoom";
        private const float CalibrationRoomZ = -2f * RoomPitch;

        // THERE IS ONE BUILD, and the probe bake is part of it.
        //
        // A "fast, no probes" menu item lived here until 2026-08-15 and was REMOVED as a trap rather
        // than as a saving. It left the existing `.exr` files in place, so a fast-built scene comes up
        // looking lit and reflective while reflecting the building as it was at some earlier build -
        // and this project's walls are 0.85 smoothness and its escape objects are metallic 0.9, which
        // is to say almost entirely what they reflect. A stale reflection does not announce itself;
        // it just makes every judgement about how the room LOOKS quietly untrustworthy, which is the
        // one thing a build is for.
        //
        // The bake is genuinely most of the build's time - fifteen probes, six faces each. If that
        // becomes intolerable the answer is the per-cycle scene split (`docs/cycle-design.md` §7b),
        // which cuts what has to be baked, rather than a switch that bakes nothing and says nothing.
        // REBUILDS ONE CYCLE, INTO ITS OWN SCENE, AND BAKES ONLY ITS PROBES.
        //
        // This is what the scene split was FOR. The full build re-bakes all fifteen reflection probes,
        // six faces each, and that is nearly all of the minutes it takes - while a session spent moving
        // a switch in room2-2 is not looking at cycle 1 at all. Here the scene contains one cycle, so
        // `BakeReflectionProbes` finds eight probes instead of fifteen and `Cycle1.unity` is not touched.
        //
        // NOT THE SAME BARGAIN AS THE OLD "fast, no probes" BUILD, which was removed as a trap. That one
        // left STALE cubemaps in place and said nothing about it, so a room could reflect a building
        // that no longer existed. This bakes every probe it is responsible for, in full; what it leaves
        // alone is a different cycle, whose geometry this cannot have changed because it is not in the
        // scene. Nothing goes out of date without the file it belongs to being rebuilt.
        //
        // The core scene is not needed and not opened. Everything cycle 2 points at outside itself is
        // re-established at runtime by `CycleBinding`, which is why the core references below are null.
        // **IT REBUILDS THE CYCLE, NOT THE PLAYER.** Anything that lives on the player, the HUD or the
        // loop is in the CORE scene and this does not touch it - which is the whole point, and also the
        // one way it misleads. Adding `BucketPlacer` to the player and then rebuilding only cycle 2
        // produced a game where the buckets existed, the stands existed, and left click did nothing at
        // all, because the component that answers it had never been built.
        //
        // The rule that follows: **a change to a room is a cycle build; a change to the player, the
        // HUD or the loop is a full build.** When in doubt, full.
        [MenuItem("Iteration Room/Rebuild Cycle 2 Only")]
        public static void RebuildCycleTwo()
        {
            EnsureFolders();
            PlayerSettings.runInBackground = true;

            EditorSceneManager.NewScene(NewSceneSetup.DefaultGameObjects, NewSceneMode.Single);
            Scene scene = SceneManager.GetActiveScene();

            // THE DEFAULT CAMERA AND LIGHT GO, and forgetting this shipped a silent room.
            //
            // A cycle scene is loaded ADDITIVELY on top of the core one, which already has the player's
            // camera and the one AudioListener the game is allowed to have. `NewSceneSetup.
            // DefaultGameObjects` hands over a Main Camera carrying a listener of its own, so the built
            // player ran with TWO - Unity keeps one and the other's spatial audio simply does not
            // arrive. It presents as "the taps make no sound", which is nothing like its cause.
            //
            // The full build does not have this problem because it puts the player in the same scene
            // and clears these on its way past. A per-cycle build has to do it for itself - the same
            // hazard as the door audio: whatever `Build` does for a cycle, the cycle's own path must
            // do too.
            foreach (GameObject go in scene.GetRootGameObjects())
                if (go.GetComponent<Camera>() != null || go.GetComponent<Light>() != null)
                    Object.DestroyImmediate(go);

            // **0.85, NOT WHITE** - settled 2026-08-20, and the
            // reason it is not 1.0 is measurable rather than a matter of taste. Albedo 1.0 is a
            // surface that returns every photon that hits it; nothing does, fresh white paint is
            // about 0.85, and a floor is always darker than the walls above it. With four spots at
            // intensity 10.5 pointing straight down, a 1.0 floor CLIPPED - the title screen's own
            // capture had this floor at (235, 253, 255), two channels already at the top - and play
            // read it exactly: stand in the middle, look down, it is too white.
            //
            // The alternatives were both wider. Dropping the light intensity darkens the walls with
            // it, and pulling exposure down in the volume changes every surface in the game. This
            // changes the one surface that was wrong, and it still reads WHITE: it is 15% off
            // clipping and the eye has nothing brighter on screen to compare it against.
            Material floorMat = MakeColorMaterial("FloorWhite", new Color(0.85f, 0.85f, 0.86f));
            Material grooveMat = MakeColorMaterial("GrooveDark", new Color(0.04f, 0.04f, 0.045f));
            Material propMat = MakeColorMaterial("PropLight", new Color(0.85f, 0.85f, 0.85f));
            Material panelMat = MakeColorMaterial("PanelWhite", PanelLitColor);
            Texture2D surfaceGrain = MakeNoiseNormalMap("SurfaceGrain", 512, 2.5f);
            ApplySurfaceDetail(panelMat, surfaceGrain, 0.2f, new Vector2(5f, 3f), 0.85f);
            // SMOOTHNESS 0.65, UP FROM 0.3, and BUMP 0.6, DOWN FROM 1.8. Settled 2026-08-20. They are
            // one decision, not two, and the order they happened in is the whole lesson.
            //
            // The smoothness first: a floor at smoothness 0 is a perfectly uniform field, and the eye
            // reads a field with no variation in it as blown out rather than as bright - which was
            // half of what "too white" meant. At 0.65 the ceiling fixtures lay pools across the floor
            // and the 26x30 grain rides in them, so the floor has structure to read distance off.
            //
            // THEN THE BUMP, because raising the gloss is what exposed it. Wall and floor share one
            // normal map at one physical grain size (~0.35m repeat on both) and differed ONLY in this
            // number - 0.2 against 1.8, nine times apart. While the floor was matte that relief only
            // reached the diffuse and read as the tooth of sealed concrete. Glossy, the same grain
            // modulates the SPECULAR, and the floor stopped being the matte counterpart to a glazed
            // wall and became a third finish that was neither. Play called it as the wall and the
            // floor not going together.
            //
            // 0.6, not the wall's 0.2, and the asymmetry is earned: a wall is a grid of 1.7x0.9m
            // panels with near-black grooves between them, so it already has geometry breaking up its
            // reflection. The floor is one 9x10.9m slab with nothing of the sort, and its grain is the
            // only thing doing that job.
            //
            // WHAT TO WATCH IF EITHER MOVES AGAIN: specular is added on top of diffuse, so both of
            // these push the floor back toward the clipping that 0.85 albedo was chosen to stop. Judge
            // them standing under a fixture, not in the middle of the room.
            ApplySurfaceDetail(floorMat, surfaceGrain, 0.6f, new Vector2(26f, 30f), 0.65f);

            (Transform root, Transform bedSpawn, ParticleSystem[] gas,
             Door[] doors, RoomCondition[] conditions,
             GhostInteractable[] signals, Transform[] rooms, Transform[] loweredRooms,
             FinalRoomSequence finalRoom, CycleExit _wayOut) =
                BuildCycleTwoShell(floorMat, grooveMat, panelMat, propMat, null);

            (Cycle cycle, _) = AssembleCycleTwo(
                root, bedSpawn, doors, conditions, signals, gas, rooms, loweredRooms, finalRoom,
                floorMat, propMat, MakeTestCardTexture("TvTestCard"), MakeStaticTexture("TvStatic", 64),
                null, null, null);

            // Anything a cycle needs must be reachable from the cycle's own path, not only from
            // `Build` - see WireDoorAudio, which this omitting is exactly how cycle 2 shipped with
            // seven silent doors.
            WireDoorAudio(doors);

            // The same lighting the full build sets up, and it has to be here rather than inherited:
            // a probe bakes what the scene is lit by, and an unlit scene bakes eight black cubemaps.
            SetupLighting();
            AddFallingToEveryCarryable();
            BakeReflectionProbes();

            // The cycle's world goes under its own component, exactly as the split leaves it, so the
            // scene has one root and `CycleSceneLoader` finds it the same way.
            root.SetParent(cycle.transform, true);
            if (cycle.wallPanels != null) cycle.wallPanels.transform.SetParent(cycle.transform, true);
            SleepCycle(root);

            Directory.CreateDirectory("Assets/Scenes");
            EditorSceneManager.SaveScene(scene, CycleScenePath("Cycle2"));
            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();

            Debug.Log("[SceneBuilder] Cycle 2 rebuilt on its own at " + CycleScenePath("Cycle2")
                    + " - cycle 1 and the core scene were not touched.");
        }

        [MenuItem("Iteration Room/Build Whitebox Scene")]
        public static void Build()
        {
            EnsureFolders();

            // Without this, play mode stops ticking the moment the Editor loses focus, so any
            // MCP-driven test (teleport the player, open the door, screenshot) captures a stale
            // frame and looks like nothing happened. Setting it during play mode doesn't stick,
            // hence doing it here.
            PlayerSettings.runInBackground = true;

            Scene scene = EditorSceneManager.NewScene(NewSceneSetup.DefaultGameObjects, NewSceneMode.Single);

            Camera defaultCam = Camera.main;
            if (defaultCam != null) Object.DestroyImmediate(defaultCam.gameObject);

            // One material for both slabs. Floor and ceiling were split apart for a marble floor;
            // that was dropped in favour of a plain white one, and with the two surfaces identical
            // again the split was only duplication.
            // **0.85, NOT WHITE** - settled 2026-08-20, and the
            // reason it is not 1.0 is measurable rather than a matter of taste. Albedo 1.0 is a
            // surface that returns every photon that hits it; nothing does, fresh white paint is
            // about 0.85, and a floor is always darker than the walls above it. With four spots at
            // intensity 10.5 pointing straight down, a 1.0 floor CLIPPED - the title screen's own
            // capture had this floor at (235, 253, 255), two channels already at the top - and play
            // read it exactly: stand in the middle, look down, it is too white.
            //
            // The alternatives were both wider. Dropping the light intensity darkens the walls with
            // it, and pulling exposure down in the volume changes every surface in the game. This
            // changes the one surface that was wrong, and it still reads WHITE: it is 15% off
            // clipping and the eye has nothing brighter on screen to compare it against.
            Material floorMat = MakeColorMaterial("FloorWhite", new Color(0.85f, 0.85f, 0.86f));
            // Sits at the bottom of every groove and inside the door pocket. Near-black so the
            // seams read the way the old painted-on grid lines did.
            Material grooveMat = MakeColorMaterial("GrooveDark", new Color(0.04f, 0.04f, 0.045f));
            Material propMat = MakeColorMaterial("PropLight", new Color(0.85f, 0.85f, 0.85f));
            // White is the resting state - what the panels are for all but the first seconds of an
            // iteration, and what the reflection probes bake against. WallPanelDisplay drives them
            // to WallPanelColor and back through a property block at runtime.
            Material panelMat = MakeColorMaterial("PanelWhite", PanelLitColor);
            // Emission is enabled with a black colour: the keyword has to be compiled in for
            // WallPanelDisplay's collapse flare to have anything to drive, and a property block
            // cannot turn a shader keyword on. Black means it contributes nothing until then.
            panelMat.EnableKeyword("_EMISSION");
            panelMat.SetColor("_EmissionColor", Color.black);
            panelMat.globalIlluminationFlags = MaterialGlobalIlluminationFlags.RealtimeEmissive;
            EditorUtility.SetDirty(panelMat);

            // Tiling is per face, and a wall panel's face is roughly 1.7 x 0.9m while a floor slab
            // is 9 x 10.9m - so the two need very different repeat counts to land on the same
            // physical grain size (~0.35m per repeat).
            // bumpScale is ~2.5, not the <1 that looks like a sane default. Central differences
            // across a smooth multi-octave field give very small gradients, so the generated map is
            // genuinely shallow: at 0.7 the walls rendered perfectly flat and the detail was
            // invisible even with the camera against them. 10 turns it into stucco. 2.5 reads as
            // painted plaster up close and disappears at room distance, which is the goal.
            // The floor is left smoother, as a harder finish would be.
            // Walls read as a smooth glazed panel - closer to ceramic tile or a switched-off
            // display than to plaster. That means gloss, and almost no relief: the grain is kept
            // at a whisper (0.2) purely so the specular isn't a perfectly uniform sheet, which is
            // what makes a flat surface look CG. Smoothness 0.85 is what actually does the work,
            // and it only reads correctly because the reflection probes give it the room to mirror
            // rather than the blue sky.
            //
            // THE FLOOR IS NO LONGER MATTE BY COMPARISON - it was, and that pairing is what this
            // paragraph was written against, but it went to smoothness 0.65 on 2026-08-20. What now
            // separates the two is relief rather than gloss: the wall keeps its whisper of grain
            // (0.2) and the floor carries three times it (0.6), because the wall has a panel grid to
            // break up its reflection and the floor is one bare slab. See the floor's own comment.
            Texture2D surfaceGrain = MakeNoiseNormalMap("SurfaceGrain", 512, 2.5f);
            ApplySurfaceDetail(panelMat, surfaceGrain, 0.2f, new Vector2(5f, 3f), 0.85f);
            // Floor and ceiling: plain white, matte, with the same plaster grain the walls get -
            // just at a far higher repeat count, since a slab face is 9 x 10.9m against a wall
            // panel's 1.7 x 0.9m.
            // SMOOTHNESS 0.65, UP FROM 0.3, and BUMP 0.6, DOWN FROM 1.8. Settled 2026-08-20. They are
            // one decision, not two, and the order they happened in is the whole lesson.
            //
            // The smoothness first: a floor at smoothness 0 is a perfectly uniform field, and the eye
            // reads a field with no variation in it as blown out rather than as bright - which was
            // half of what "too white" meant. At 0.65 the ceiling fixtures lay pools across the floor
            // and the 26x30 grain rides in them, so the floor has structure to read distance off.
            //
            // THEN THE BUMP, because raising the gloss is what exposed it. Wall and floor share one
            // normal map at one physical grain size (~0.35m repeat on both) and differed ONLY in this
            // number - 0.2 against 1.8, nine times apart. While the floor was matte that relief only
            // reached the diffuse and read as the tooth of sealed concrete. Glossy, the same grain
            // modulates the SPECULAR, and the floor stopped being the matte counterpart to a glazed
            // wall and became a third finish that was neither. Play called it as the wall and the
            // floor not going together.
            //
            // 0.6, not the wall's 0.2, and the asymmetry is earned: a wall is a grid of 1.7x0.9m
            // panels with near-black grooves between them, so it already has geometry breaking up its
            // reflection. The floor is one 9x10.9m slab with nothing of the sort, and its grain is the
            // only thing doing that job.
            //
            // WHAT TO WATCH IF EITHER MOVES AGAIN: specular is added on top of diffuse, so both of
            // these push the floor back toward the clipping that 0.85 albedo was chosen to stop. Judge
            // them standing under a fixture, not in the middle of the room.
            ApplySurfaceDetail(floorMat, surfaceGrain, 0.6f, new Vector2(26f, 30f), 0.65f);

            GameObject room = new GameObject("Room");
            BuildShell(room.transform, floorMat, grooveMat, panelMat);

            // MADE HERE rather than beside the loop it belongs to, because cycle 2's haul room counts
            // the ghosts standing beside its load and is built moments from now. Nothing else about
            // it changes - `LoopManager` still parents every ghost to it.
            GameObject ghostParent = new GameObject("Ghosts");

            // Cycle 2, one storey down. Deliberately OUTSIDE `room` - see BuildCycleTwoShell for why
            // the panel gather below is the reason.
            (Transform cycleTwoRoot, Transform cycleTwoBedSpawn, ParticleSystem[] cycleTwoGas,
             Door[] cycleTwoDoors, RoomCondition[] cycleTwoConditions,
             GhostInteractable[] cycleTwoSignals, Transform[] cycleTwoRooms,
             Transform[] cycleTwoLoweredRooms,
             // The hatch element is DISCARDED: room2-0 stopped building its own the day cycle 3
             // existed, so this is always null now. It is built on `CycleJoin_2_3` below, in the core
             // scene, because one `CycleExit` drives a lid in two different cycles' scenes.
             FinalRoomSequence cycleTwoFinalRoom, _) =
                BuildCycleTwoShell(floorMat, grooveMat, panelMat, propMat, ghostParent.transform);

            // Every wall panel, gathered by parent name rather than threaded back out through
            // BuildShell/BuildRoomShell/BuildPanelWall - the panels are the only children of a
            // "*_Panels" node, so this stays correct without four signature changes.
            var wallPanelRenderers = new System.Collections.Generic.List<Renderer>();
            foreach (Renderer r in room.GetComponentsInChildren<Renderer>())
            {
                if (r.transform.parent == null || !r.transform.parent.name.EndsWith("_Panels")) continue;
                // The calibration room is left out. It is seen once, before the loop starts, and
                // never again - so booting and flaring its ~88 panels would be a per-frame property
                // block written to renderers nobody can look at. Property blocks already break SRP
                // batching across this array; there is no reason to make it a third longer.
                if (InCalibrationRoom(r.transform)) continue;
                wallPanelRenderers.Add(r);
            }

            // What a panel shows once it fails. Generated rather than sourced, like every other
            // texture in this build, and shared by both cycles' displays.
            Texture2D testCard = MakeTestCardTexture("TvTestCard");
            Texture2D staticNoise = MakeStaticTexture("TvStatic", 64);

            WallPanelDisplay wallDisplay = MakeWallPanelDisplay(
                "WallPanelDisplay", wallPanelRenderers.ToArray(), testCard, staticNoise);

            // Cycle 2's own display is built with the rest of cycle 2, in AssembleCycleTwo - see there
            // for why everything that cycle IS now lives behind one call.

            // Four recessed downlights per room, plus Trilight ambient standing in for the bounce
            // URP is not computing. The scene's default Directional Light is deleted rather than
            // dimmed - these are sealed boxes with a ceiling slab, so a sun has no way in.
            SetupLighting();
            BuildPostProcessing();
            ConfigureAmbientOcclusion();
            ConfigureLightingPipeline();

            (Transform bed, Transform bedSpawn) = BuildBed(room.transform, propMat);
            (Drawer drawer, CarryableItem[] pins) = BuildNightstand(room.transform);
            // Out in the open floor area past the foot of the bed, matching room_layout_sample.png.
            FloorButton floorButton = BuildFloorButton(room.transform, propMat, "FloorButton",
                new Vector3(2.8f, 0.03f, -1.75f));
            Door door = BuildPadDoor(room.transform, "Door", 0f, new[] { floorButton }, propMat);

            // Room2: a roomful of balloons and three keys. None of the three doors they open is a
            // GhostInteractable - carrying is not part of a recording, so a ghost cannot open one for
            // you. Getting yourself to each one holding its key is what the room asks.
            //
            // THREE KEYED DOORS, one per key colour, and the colours are the only instruction the
            // player gets - but they are no longer three exits off Room2's own walls. The whole run is
            // ONE CORRIDOR now: Room2 -> Room2West -> Room2East -> Room3 -> Room4, and a coloured door
            // sits at each of the first three joins, in the order the keys have to be spent. Red and
            // blue used to be side doors off Room2 leading straight to these same two rooms; they keep
            // exactly that pairing (red still opens onto the chess room, blue still onto the cube room)
            // and only their POSITION moved, from a wall in Room2 to the threshold of the room itself.
            // Yellow was Room2's original way out and is still the last of the three, now handing off
            // to Room3 instead of straight to it. Each door's lock and its key are built from the same
            // KeySpec entry, so a plate cannot end up wanting a key that does not match it.
            (Door doorRed, KeyLock lockRed) =
                BuildKeyDoor(room.transform, "DoorRed", RoomPitch, propMat, Room2Keys[1]);
            (Door doorBlue, KeyLock lockBlue) =
                BuildKeyDoor(room.transform, "DoorBlue", 2f * RoomPitch, propMat, Room2Keys[2]);
            (Door doorYellow, KeyLock lockYellow) =
                BuildKeyDoor(room.transform, "DoorYellow", 3f * RoomPitch, propMat, Room2Keys[0]);
            (BalloonField balloonField, CarryableItem[] keys) = BuildBalloons(room.transform);

            // Room2West, behind the red door: a chess set in the middle of the floor, with a dozen of
            // its pieces scattered around it and its lights turned down until they are all back.
            //
            // ON THE FLOOR at 1.8m rather than on a table, because at that size the pieces are 0.4m
            // tall - things a person could pick up and put down, which is the shape any puzzle here is
            // going to want. A board at table height and table scale would be scenery.
            //
            // 0.1013 comes from measuring: the glb arrives at import scale 0.1776 spanning 3.155m, so
            // it is 17.77m at scale 1 and 1.8 / 17.77 is this. The -90 X is the same Z-up correction the
            // bed and the nightstand need - PlaceModel REPLACES the prefab's own rotation, so the 270 X
            // the import gives it does not survive and has to be asked for again.
            //
            // Room2West is a room on the chain now, the same shape and orientation as Room1-4, entered
            // from its SOUTH wall - not the rotated side room this used to be, entered from the east.
            // The doorway hint only guards the entrance (south); the room also has a north doorway
            // through to Room2East, and pieces are not scattered densely enough near it to need a
            // second guard - the same one-doorway simplification the room lived with before, when a
            // second doorway did not yet exist.
            Vector3 room2WestCentre = new Vector3(0f, 0f, 2f * RoomPitch);
            Vector3 room2EastCentre = new Vector3(0f, 0f, 3f * RoomPitch);
            Vector3 room2WestDoorway = new Vector3(0f, 0f, room2WestCentre.z - RoomDepth / 2f + 0.6f);
            (CarryableItem[] chessPieces, ChessBoard chessBoard) =
                BuildChessSet(room.transform, room2WestCentre, room2WestDoorway, propMat,
                              Room2WestLights, Room2WestPanels);

            // Room2East, behind the blue door: six symbol cubes on the floor and six recesses in the
            // walls that want them, paying out the blue sphere.
            (CarryableItem[] symbolCubes, CubeRoom cubeRoom) =
                BuildCubeRoom(room.transform, room2EastCentre, propMat);

            // Room3: TWO pads and one door that needs both at once. Deliberately the plainest room
            // of the three - no items, nothing to search, nothing to carry. Room2 already costs the
            // player a key retrieval every iteration, and a second expensive room behind it would be
            // unreachable rather than hard. What Room3 costs is ITERATIONS: one to stand on each
            // pad, and a third to walk through while two past selves hold them.
            //
            // ONE AGAINST EACH SIDE WALL, facing each other across the room at its mid-depth. Two is
            // the smallest count that still says "not something one person can do", and a facing
            // PAIR is the clearest arrangement there is for it - a player who finds one is looking
            // straight at the other, so there is nothing to hunt for and nothing to suggest that a
            // subset might do.
            //
            // Mirror-symmetric about the room's north-south axis, which the earlier triangle could
            // not be: a triangle symmetric about that axis has to put a vertex ON it, and that axis
            // is the straight walk from the south door to the north one. With a pair, the symmetry
            // and the clear walk come free - each pad sits 3.2m off the line, eight times its own
            // reach. Standing on one is the only way to learn what the other is for, so the room has
            // to show them together and never trigger by accident.
            const float roomThreeZ = 4f * RoomPitch;
            // 3.2 from the centre line leaves 1.175m to the wall face - against the wall as read
            // from the middle of the room, with room to stand on the pad rather than in the wall.
            const float padWallX = 3.2f;
            FloorButton[] roomThreePads =
            {
                BuildFloorButton(room.transform, propMat, "FloorButton3A", new Vector3(-padWallX, 0.03f, roomThreeZ)),
                BuildFloorButton(room.transform, propMat, "FloorButton3B", new Vector3(padWallX, 0.03f, roomThreeZ)),
            };
            Door door3 = BuildPadDoor(room.transform, "Door3", roomThreeZ, roomThreePads, propMat);

            // ROOM3 PAYS OUT TOO, on exactly the condition that opens its door. Both pads held raises
            // a plinth carrying the yellow triangle, and lets it go again when one is released - the
            // same promise the door makes, because it is the same rule (`FloorButton.AllActive`).
            //
            // DEAD CENTRE, between the two pads and on the straight walk from the south door to the
            // north one. That axis was ruled out for a PAD, and for a reason that does not apply here:
            // a pad there fires by accident, where this is the one thing in the room the player is
            // meant to walk into. It also keeps the mirror symmetry the pair of pads is built on.
            (Transform yellowPlinth, Transform yellowSeat, CarryableItem yellowKey) =
                BuildKeyPlinth(room.transform, "YellowPlinth", new Vector3(0f, 0f, roomThreeZ), propMat,
                    SlotShape.Triangle, new Color(0.95f, 0.78f, 0.12f), "KeyTriangleMat",
                    TriangleKeyItemId, "TRIANGLE", TriangleIcon());

            RewardPlinth yellowRise = yellowPlinth.gameObject.AddComponent<RewardPlinth>();
            yellowRise.pads = roomThreePads;
            yellowRise.plinth = yellowPlinth;
            yellowRise.key = yellowKey;
            yellowRise.keySeat = yellowSeat;
            // Clear of the floor slab with the object's own height counted in, so nothing shows
            // through before the pads are held.
            yellowRise.riseHeight = 1.25f;

            // THE WAY INTO ROOM4, and no longer the way out of the game. Crossing this latches
            // "the player got here this iteration", which is what raises the console through the
            // floor beyond it; the clock keeps running and what ends a run is putting all three
            // escape objects into that console. Still sat ON the threshold rather than past it,
            // which is now simply where a doorway is - it used to be forced, because the FarCap was
            // right behind that opening with no "through" to stand in.
            // See EscapeTrigger and FinalRoomSequence.
            GameObject escapeGO = new GameObject("EscapeTrigger");
            escapeGO.transform.SetParent(room.transform, false);
            escapeGO.transform.localPosition = new Vector3(0f, 0f, roomThreeZ + RoomDepth / 2f);
            EscapeTrigger escape = escapeGO.AddComponent<EscapeTrigger>();
            escape.door = door3;
            // Half the doorway plus a little, so only a player actually in the opening qualifies -
            // without this, anyone at the same Z anywhere along the north wall would count.
            escape.halfWidth = DoorWidth / 2f + 0.05f;

            // The wire format for ghost playback: an entry's index is its bit in
            // RecordedFrame.signals, so this is appended to and never reordered. The recorder and
            // the loop are handed the same array, so the two can never drift out of order.
            //
            // The drawer is in it - pulling a drawer needs no inventory, so a ghost can repeat it.
            // The KEY LOCK is deliberately NOT: the condition that lets the player open that door
            // is holding the key, and a ghost cannot hold anything. See the note on KeyLock.
            //
            // The door button used to sit between these two and has been removed with it; the
            // drawer therefore moved from bit 2 to bit 1. That is safe only because timelines live
            // for one session of play and are never persisted - reordering this at runtime would
            // invalidate every recording made so far.
            GhostInteractable[] ghostInteractables =
            {
                floorButton, drawer,
                roomThreePads[0], roomThreePads[1],
            };

            // The player starts in the calibration room, not at the bed. Iteration 1 teleports them
            // to bedSpawn at the top of RunLoop regardless, so this only decides where they stand
            // while setting the sensitivity.
            GameObject calibSpawnGO = new GameObject("CalibrationSpawn");
            calibSpawnGO.transform.SetParent(room.transform, false);
            // The SAME offset and facing as the bed spawn, one room over: (0, -0.7) looking at 180.
            // That is not tidiness, it is the point of the room.
            //
            // Turning in place has the same angular rate whatever is in front of you, so the number
            // being set is identical either way - but how FAST it feels is not. What the eye
            // actually counts is detail crossing the view, and a far wall puts many more panel
            // edges in a degree than a near one. An earlier version stood the player 3m from the
            // south wall facing the length of the room, with 8.25m of wall ahead against the game's
            // 4.55m: same sensitivity, noticeably quicker to look at. Matching the pose makes the
            // calibration frame the frame the game opens on.
            calibSpawnGO.transform.localPosition = new Vector3(0f, 0f, CalibrationRoomZ - 0.7f);
            calibSpawnGO.transform.localRotation = Quaternion.Euler(0f, 180f, 0f);
            Transform calibrationSpawn = calibSpawnGO.transform;

            (GameObject player, FirstPersonController fpc, PlayerRecorder recorder, CameraShaker shaker, PlayerHand hand) = BuildPlayer(calibrationSpawn, ghostInteractables);

            GhostReplayer ghostPrefab = BuildGhostPrefab();
            // Already built, above - cycle 2's haul room needs it, and that is built with the shell.
            // (kept here as a comment so the old creation site is not re-added)

            (IterationLabel label, WakeUpSequence wakeUp, Transform canvas, CanvasGroup loadingBackdrop, CaptureRig capture) = BuildUI(hand);
            wakeUp.wallPanels = wallDisplay;

            // Everything E does something to, in the order the player is likely to meet it. The
            // prompt is shown over whichever of these is nearest and currently wants it - every
            // time, not once; see ControlHintDisplay for why that changed. Room1's door is not in
            // the list any more because it has no control to press.
            //
            // ALL THREE pins go in, not just the first: the display picks the nearest one that wants a
            // prompt, so a drawer holding three prompts over whichever is being looked at. Once one
            // is taken the other two go quiet - CarryableItem.WantsInteractHint asks the hand whether
            // it already has this id, which it had no reason to before an id could be a supply.
            // Three keys and three locks go in for the same reason. Nearest-wins means standing at a
            // door prompts over that door's lock and not over the other two, and standing over a key on
            // the floor prompts over the key - which is exactly what the coloured doors need, since the
            // prompt is what says "this is the thing you can act on from here".
            var pinTargets = new System.Collections.Generic.List<MonoBehaviour> { drawer };
            pinTargets.AddRange(pins);
            pinTargets.Add(lockRed);
            pinTargets.Add(lockBlue);
            pinTargets.Add(lockYellow);
            pinTargets.AddRange(keys);
            // And every chess piece, so E over one shows the prompt like E over anything else. Thirty-two
            // more entries in a list NearestWantingHint walks every frame, which is nothing next to what
            // it would cost to have the one room full of takeable objects be the room with no prompts.
            pinTargets.AddRange(chessPieces);
            // And Room3's triangle, which is only ever reachable while two past selves are standing on
            // the pads - the one moment in the game where a prompt appears because somebody ELSE is
            // holding a condition open.
            pinTargets.Add(yellowKey);
            // The cube room, both halves of it: the six cubes on the floor and the six recesses that
            // want them. The recesses are E fixtures like the drawer and the locks, so they get the
            // same disc; nearest-wins keeps a player standing at one wall from being prompted by the
            // recess behind them.
            pinTargets.AddRange(symbolCubes);
            pinTargets.AddRange(cubeRoom.slots);
            pinTargets.Add(cubeRoom.reward.key);
            ControlHintDisplay hints = BuildControlHints(canvas, player.GetComponentInChildren<Camera>(),
                player.GetComponent<BalloonTool>(), pinTargets.ToArray());

            // Putting a piece back. On the player beside BalloonTool, sharing the left button with it and
            // unable to clash: that one is silent unless the pin is held, this one unless a piece is, and
            // PlayerHand has one item out at a time.
            ChessPlacer placer = player.AddComponent<ChessPlacer>();
            placer.playerCamera = player.GetComponentInChildren<Camera>();
            placer.hand = hand;

            // And the bucket's own left click, beside the chess placer and the swing. None of the
            // three can clash: each is silent unless the hand holds the one thing it acts on, and the
            // hand holds exactly one thing at a time.
            BucketPlacer bucketPlacer = player.AddComponent<BucketPlacer>();
            bucketPlacer.hand = hand;

            // And room3-2N's blocks, the fourth thing on that button and unable to clash with the
            // other three for the same reason: a block in the hand is not a pin, a piece or a pail.
            BedlamPlacer bedlamPlacer = player.AddComponent<BedlamPlacer>();
            bedlamPlacer.hand = hand;

            // And the ladder's, the fifth thing on that button. Same guarantee as the other four:
            // silent unless the hand holds the one thing it acts on.
            LadderPlacer ladderPlacer = player.AddComponent<LadderPlacer>();
            ladderPlacer.hand = hand;
            placer.board = chessBoard;
            // The mouse prompt rides the board's lit square, which is the same rule the swing prompt
            // follows: the label goes on the thing the click acts on, not on the hand it is held in.
            hints.placer = placer;
            hints.bucketPlacer = bucketPlacer;
            hints.bedlamPlacer = bedlamPlacer;
            hints.ladderPlacer = ladderPlacer;

            // The touch layer, under the pause menu so a paused game's buttons draw over it.
            TouchControls touch = BuildTouchControls(canvas);

            // The rest of the capture rig, now that the prompts, the touch layer and the player's
            // camera all exist. Everything it needs is named here rather than found at runtime.
            WireCaptureRig(capture, hints.gameObject, touch.gameObject,
                           player.GetComponentInChildren<Camera>());

            // Escape's overlay covers the HUD, the prompts and the eyelids...
            BuildPauseMenu(canvas, fpc);
            // ...and the ending covers even that. Built last so nothing in the game can draw over
            // the last thing the player sees. (Pausing is locked out for its duration anyway - see
            // PauseMenu - but the draw order should not depend on that being true.)
            EndingSequence ending = BuildEndingScreen(canvas);
            // Above even that, because it is the first thing the run shows and nothing else is
            // running while it is up.
            SensitivityCalibration calibration = BuildCalibrationPage(canvas);
            CalibrationStartButton startButton = BuildCalibrationWall(room.transform, CalibrationRoomZ, calibration);

            // Room4 and the plate that ends the run. Its narration is wired after BuildAudio below;
            // control is LoopManager's to take, at the scrim, so nothing here needs the player.
            FinalRoomSequence finalRoom = BuildFinalRoom(room.transform, 5f * RoomPitch, propMat,
                                                        door3, wallDisplay, shaker, hand,
                                                        CubeKeyItemId, SphereKeyItemId, TriangleKeyItemId);

            // THE WAY ON, in room1-0's floor behind that console. Wiring it is what makes cycle 1 not
            // the last cycle - LoopManager reads "is there another entry in the array", and this is
            // the door that entry is reached through.
            // THE JOIN BELONGS TO NEITHER CYCLE, so it hangs off its own root rather than off cycle
            // 1's.
            //
            // It was under `Room`, which is cycle 1's world root - and that root is deactivated the
            // moment cycle 1 ends. So the lid over the hole went with it, and room2-1 spent the whole
            // of cycle 2 with an open square in its ceiling. It reads as a patch of wrong colour
            // rather than as a hole, which is why it took a walk-through to notice: what is visible
            // through it is the void between the storeys.
            //
            // The shaft has the same problem in the other direction - it is what the player falls
            // down, at the one moment both cycles are awake - so it moves here too. The console
            // housing does NOT: it is cycle 1's machinery, it sits inside the service void where
            // neither room can see it, and it should sleep when cycle 1 does.
            GameObject join = new GameObject("CycleJoin_1_2");

            CycleExit cycleOneExit = BuildCycleExit(join.transform, 5f * RoomPitch, floorMat, fpc.transform);
            finalRoom.wayOut = cycleOneExit;

            // The console retracts a metre below the floor, which is now a metre INTO room2-1. Give
            // it something to retract into - see BuildPlinthHousing. Sized off the plinth (1.70 x
            // 1.15) with clearance, and deep enough to swallow its full 1.13m travel.
            BuildPlinthHousing(room.transform, "ConsoleHousing",
                new Vector3(0f, 0f, 5f * RoomPitch), 1.86f, 1.31f, 1.45f, floorMat);

            // And the tube the player falls down, joining this floor's hole to the ceiling hole of
            // the room below across the service void.
            BuildExitShaft(join.transform, "ExitShaft_Cycle1", 5f * RoomPitch, floorMat);

            // Appended after the fact because both buttons live in rooms built later than the hint
            // display. They are the two E fixtures OUTSIDE the loop - one before the first
            // iteration, one after the last - and they get the same grey disc as every other one,
            // which is the point: the run opens and closes on the game's own prompt.
            var hintTargets = new System.Collections.Generic.List<MonoBehaviour>(hints.interactTargets)
            {
                startButton,
            };
            // And the console's three recesses, which are E fixtures like any other now that the
            // clock runs through the room they are in.
            hintTargets.AddRange(finalRoom.slots);
            // CYCLE 2'S OWN E FIXTURES. Gathered off the cycle root rather than threaded back out of
            // `BuildCycleTwoShell`, so every switch a later room adds joins this list by existing -
            // the prompt is the only thing that tells a player a fixture is a fixture at all, and a
            // new one silently missing from here is exactly the fault that shipped in the last build.
            // Inactive included: the cycle starts asleep.
            hintTargets.AddRange(cycleTwoRoot.GetComponentsInChildren<LightSwitch>(true));
            hintTargets.AddRange(cycleTwoRoot.GetComponentsInChildren<WaterTap>(true));
            // Room2-0's four recesses, and room2-6's three valves, on the same footing. Gathered by
            // type off the root for the reason stated above rather than named one by one.
            hintTargets.AddRange(cycleTwoRoot.GetComponentsInChildren<FinalSlot>(true));
            hintTargets.AddRange(cycleTwoRoot.GetComponentsInChildren<Valve>(true));
            hints.interactTargets = hintTargets.ToArray();
            hints.calibration = calibration;
            // "The player got through the last door", which arms Room4's console. Wired after the
            // fact because the trigger is built with Room3 and the console with Room4.
            finalRoom.arrival = escape;

            // Room2's wordless sign. Built here rather than with Room2 because it needs the
            // player's BalloonTool: it retires on the first pop, not on the first visit.
            BuildBalloonPictogram(room.transform, RoomPitch, player.GetComponent<BalloonTool>());

            // The end-cycle sign, IN ROOM1 AND FROM ITERATION 2 - it used to hang in Room3 and go up
            // on the first visit there. Same four walls, same words, different address:
            //
            //   - Room1 is where every iteration BEGINS, so the player is standing still with
            //     nothing to do yet, which is the only moment in this game that is reliably free.
            //     Room3 could only ever catch them mid-errand.
            //   - Iteration 2 is the earliest the message means anything. It is an offer to skip
            //     dead time, and a player who has not yet watched a clock run out has no dead time
            //     to skip. Room3 was the old way of buying that same delay - "by the time they get
            //     here they will have felt it" - expressed as distance instead of as iterations.
            //   - It retires on the ACTION, not on leaving the room, and here that is load-bearing
            //     rather than a refinement: the player can be out of Room1 in under three seconds,
            //     so the leave-once rule could retire a sign nobody read. See PanelMessage.
            //
            // Built here for the same reason as the pictogram - it needs something off the canvas.
            PanelMessage wallMessage = BuildWallMessage(room.transform, 0f);
            wallMessage.showFromIteration = 2;
            // Long enough to clear "Iteration 2, 60 seconds remaining." Announcements replace each
            // other rather than stacking, so a chime at t=0 in this room truncates the loop's own
            // line - which no room had to worry about while this lived three rooms away.
            wallMessage.announceDelay = 5f;
            wallMessage.retireOnEndCycle = canvas.GetComponentInChildren<EndCycleControl>(true);

            // EVERY DOOR IN THE GAME, both cycles, and cycle 2's were missing until 2026-08-15: this
            // took a hand-written list of cycle 1's five, so the ring's seven were built with no
            // AudioSource and no clip and opened in silence. Nothing reported it because a door that
            // makes no sound looks exactly like a door.
            //
            // Concatenated rather than a second call, because the pads and the wake-up in there are
            // one-per-game and would be wired twice.
            var everyDoor = new System.Collections.Generic.List<Door>
                { door, doorRed, doorBlue, doorYellow, door3 };
            everyDoor.AddRange(cycleTwoDoors);

            (NarrationDirector narration, RoomAmbience ambience) =
                BuildAudio(player, everyDoor.ToArray(), wakeUp);

            wallMessage.narration = narration;
            // Announced at the PRESS rather than when the player stepped through the doorway:
            // walking into a room is not what breaks a cycle. See FinalRoomSequence.
            finalRoom.narration = narration;

            // CYCLE 1'S WORLD, gathered onto one object. Every field here used to sit directly on
            // LoopManager, which was right while there was one bed and stops being right the moment
            // there are two - `balloonField` cannot be *the* balloon field with two in the scene.
            //
            // **Cycle 1's `wayOut` is deliberately left null, and that is what makes it the last
            // cycle.** LoopManager derives "last" from having no successor in the array rather than
            // from a number, so adding cycle 2 is adding an entry and wiring an exit - nothing here
            // needs a count.
            GameObject cycleOneGO = new GameObject("Cycle1");
            Cycle cycleOne = cycleOneGO.AddComponent<Cycle>();
            cycleOne.bedSpawnPoint = bedSpawn;
            // Every door on the one corridor. This array is what the cycle SHUTS at the top of an
            // iteration, and a door that can be opened has to be one of them.
            cycleOne.doors = new[] { door, doorRed, doorBlue, doorYellow, door3 };
            cycleOne.drawers = new[] { drawer };
            cycleOne.balloonField = balloonField;
            cycleOne.chessBoard = chessBoard;
            cycleOne.cubeRoom = cubeRoom;
            cycleOne.finalRoom = finalRoom;
            CheckGhostSignals("Cycle 1", ghostInteractables);
            CheckCycleFinishable("Cycle 1", room.transform, finalRoom);
            cycleOne.ghostInteractables = ghostInteractables;
            cycleOne.wallPanels = wallDisplay;
            cycleOne.worldRoot = room.transform;

            // CYCLE 2. A bed, a room and nothing else yet - which is exactly what the boundary needs
            // to be exercised, and no more.
            //
            // AND IT ENDS THE SAME WAY CYCLE 1 DOES, since 2026-08-20: room2-0's four pedestals are
            // its console, four billiard balls are its objects, and `Cycle.Complete` is a real
            // question again.
            (Cycle cycleTwo, WallPanelDisplay cycleTwoDisplay) = AssembleCycleTwo(
                cycleTwoRoot, cycleTwoBedSpawn, cycleTwoDoors, cycleTwoConditions, cycleTwoSignals,
                cycleTwoGas, cycleTwoRooms, cycleTwoLoweredRooms, cycleTwoFinalRoom, floorMat,
                propMat, testCard, staticNoise, shaker, hand, narration);


            // CYCLE 3. One sealed room under room2-0's hatch: a bed, an empty chest and the gas.
            // What cycle 2 was on the day it was started, and for the same reason - the boundary is
            // the thing being exercised, and a puzzle would be in the way of testing it.
            (Transform cycleThreeRoot, Transform cycleThreeBedSpawn, ParticleSystem[] cycleThreeGas,
             Transform cycleThreeRoom, GhostInteractable[] cycleThreeSignals,
             CrushingBarrier cycleThreeBarrier, BeamLift[] cycleThreeLifts) =
                BuildCycleThreeShell(floorMat, grooveMat, panelMat, propMat);

            // THE JOIN BETWEEN CYCLE 2 AND CYCLE 3, and it is in the CORE scene for the reason
            // cycle 1's is: one `CycleExit` drives a lid in the floor above and a lid in the ceiling
            // below, and a reference across a scene boundary comes back null with no error.
            //
            // Positioned so that `BuildCycleExit`'s own `+CycleExitZ` lands the hatch exactly on
            // room2-0's centre, which is where its floor hole is cut. The Y is room2-0's floor plane.
            GameObject join23 = new GameObject("CycleJoin_2_3");
            join23.transform.position =
                new Vector3(CycleThreeX, CycleThreeFloorY + StoreyDrop, CycleThreeZ - CycleExitZ);

            CycleExit cycleTwoExit = BuildCycleExit(join23.transform, 0f, floorMat, fpc.transform);
            if (cycleTwoFinalRoom != null) cycleTwoFinalRoom.wayOut = cycleTwoExit;

            // And the tube the player falls down, joining room2-0's floor to room3-1's ceiling.
            BuildExitShaft(join23.transform, "ExitShaft_Cycle2", 0f, floorMat);

            AssertUnderHatch(cycleTwoExit != null ? cycleTwoExit.transform : null);

            (Cycle cycleThree, WallPanelDisplay cycleThreeDisplay) = AssembleCycleThree(
                cycleThreeRoot, cycleThreeBedSpawn, cycleThreeGas, cycleThreeSignals,
                testCard, staticNoise, cycleThreeBarrier, cycleThreeLifts);

            // CYCLE 4, and the join into it. The same three objects cycle 3's boundary is made of,
            // in the same order and for the same reasons - the only thing different is the height
            // the hatch is at, because room3-0 is two storeys up inside room3-2N.
            (Transform cycleFourRoot, Transform cycleFourBedSpawn, ParticleSystem[] cycleFourGas,
             GhostInteractable[] cycleFourSignals) =
                BuildCycleFourShell(floorMat, grooveMat, panelMat, propMat);

            GameObject join34 = new GameObject("CycleJoin_3_4");
            join34.transform.position =
                new Vector3(CycleFourX, CycleFourFloorY + StoreyDrop, CycleFourZ - CycleExitZ);

            CycleExit cycleThreeExit = BuildRoomSizedExit(join34.transform, floorMat, fpc.transform);
            if (cycleThree != null && cycleThree.finalRoom != null)
                cycleThree.finalRoom.wayOut = cycleThreeExit;

            // The skirt round the void between room3-2N's floor and room4-1's walls. Sized to the
            // OPENING rather than to a grid cell, for the same reason the lid is.
            BuildRoomSizedSkirt(join34.transform, floorMat);

            AssertCycleFourClear(cycleThreeRoot, cycleFourRoot);
            AssertUnderCycleFourHole(cycleFourRoot);

            (Cycle cycleFour, WallPanelDisplay cycleFourDisplay) = AssembleCycleFour(
                cycleFourRoot, cycleFourBedSpawn, cycleFourGas, cycleFourSignals,
                testCard, staticNoise);

            GameObject loopGO = new GameObject("LoopManager");
            LoopManager loop = loopGO.AddComponent<LoopManager>();
            loop.loopDuration = 60f;
            // Taken down once the cycles are in and the game knows what it is showing - see
            // LoopManager.RunLoop.
            loop.loadingBackdrop = loadingBackdrop;
            // NOT ASSIGNED HERE ANY MORE. `cycles` is filled at runtime from `CycleSceneLoader`,
            // because each cycle is a scene of its own and Unity drops a serialized reference that
            // crosses one. Assigning it would look right in the Inspector and be null in the player.
            CycleSceneLoader sceneLoader = loopGO.AddComponent<CycleSceneLoader>();
            sceneLoader.cycleSceneNames = CycleSceneNames;
            loop.sceneLoader = sceneLoader;
            loop.playerRecorder = recorder;
            loop.playerController = fpc;
            loop.playerHand = hand;
            loop.ghostPrefab = ghostPrefab;
            loop.ghostParent = ghostParent.transform;
            loop.iterationLabel = label;
            loop.wakeUpSequence = wakeUp;
            loop.narration = narration;
            loop.ambience = ambience;
            loop.cameraShaker = shaker;
            loop.endingSequence = ending;
            loop.calibration = calibration;
            // Both live on the HUD canvas, found the same way the wall sign finds the control it
            // teaches. Reset and driven at a cycle boundary respectively.
            loop.endCycleControl = canvas.GetComponentInChildren<EndCycleControl>(true);
            loop.sleepingGas = canvas.GetComponentInChildren<SleepingGas>(true);
            // The room-side half of the gas. The wash on the canvas is what it feels like; the vapour
            // is what it looks like.
            if (loop.sleepingGas != null) loop.sleepingGas.emitters = cycleTwoGas;

            // AND THE SAME WIRING AGAIN, AT RUNTIME. Everything above is correct and stays; this is
            // the groundwork for splitting the cycles into scenes of their own, where every reference
            // that crosses one comes back NULL and says nothing about it. See CycleBinding.
            CycleBinding binding = loopGO.AddComponent<CycleBinding>();
            loop.binding = binding;
            binding.loop = loop;
            binding.hand = hand;
            binding.cameraShaker = shaker;
            binding.narration = narration;
            binding.player = fpc.transform;
            binding.sleepingGas = loop.sleepingGas;
            binding.hints = hints;
            binding.endCycleControl = loop.endCycleControl;
            binding.placer = placer;
            binding.bucketPlacer = bucketPlacer;
            binding.bedlamPlacer = bedlamPlacer;
            binding.ladderPlacer = ladderPlacer;
            binding.swingTool = player.GetComponent<BalloonTool>();
            // One per cycle, in cycle order. Cycle 2's is null, and that null is what says it is the
            // last cycle - see LoopManager, which derives "last" from having no successor.
            // BOTH CYCLES HAVE ONE NOW. Cycle 1's sits on the JOIN between the two storeys, outside
            // either cycle root, because it is a hole through both of them; cycle 2's is inside
            // room2-0, because there is nothing under that floor for it to join TO - it is a hatch in
            // the last room rather than a seam between two. When cycle 3 exists, it becomes a seam and
            // moves out here with cycle 1's.
            // THREE CYCLES, AND THE LAST ONE'S NULL IS WHAT MAKES IT LAST. Cycle 3 has no successor
            // and no hatch of its own yet; `LoopManager` derives "last" from the array rather than
            // from a count, so the day cycle 4 exists this grows by one entry.
            binding.wayOuts = new[] { cycleOneExit, cycleTwoExit, cycleThreeExit, null };
            // The one E fixture that belongs to no cycle: the calibration room runs before the first
            // iteration, so its button cannot be gathered off a cycle root.
            binding.coreHintTargets = new MonoBehaviour[] { startButton };

            // THE PROBES ARE BAKED HERE, LAST, AND THAT IS A FIX RATHER THAN A TIDY-UP.
            //
            // They were baked where they are built, inside BuildShell, and it did not survive: every
            // probe in the saved scene came back with a NULL bakedTexture even though all seven .exr
            // files were on disk and correct. BuildShell runs before SetupLighting, and changing the
            // scene's lighting after a bake is what drops the reference - so the game shipped with
            // seven reflection probes that reflected nothing at all.
            //
            // What that silently cost is much wider than the probes: the walls are deliberately
            // glossy (smoothness 0.85, see ApplySurfaceDetail) and that whole decision is written
            // down as only working "because the reflection probes give it the room to mirror". They
            // were not. And it is the real reason behind this project's "cannot light a pure metal"
            // rule - a metal is ALL reflection, so a metal with an empty probe has nothing to be.
            //
            // Baking last is also strictly better than baking early: the rooms are furnished by now,
            // so what a glossy wall mirrors is the room as the player sees it rather than a bare
            // shell. Before the save, because the reference lives in the scene.
            // Before the bake, because it adds an AudioSource child to every carryable and the sweep
            // that marks static renderers walks the scene as it finds it. A scene walk rather than a
            // line in every room's builder: a new carryable anywhere gets the behaviour without its
            // author having to know the rule exists.
            AddFallingToEveryCarryable();

            // BEFORE THE BAKE, and that is the point rather than an ordering detail. This leaves every
            // fixture at `LightShadows.None` and hands the list to a runtime component - so the probe
            // cubemaps, which render 360 degrees and see most of the corridor at once, bake without
            // asking for thirty shadow maps apiece. See `ShadowBudget`.
            WireShadowBudget();

            Debug.Log($"[SceneBuilder] Panel meshes: {panelMeshNames.Count} distinct sizes in use "
                    + $"({panelMeshesBuilt} generated this run, the rest served from disk). Identical "
                    + "grid cells share one asset, so the building goes on batching; the partial "
                    + "panels around doorways are what mint new ones. Hundreds here would mean the "
                    + "sizes have stopped repeating - see ChamferedPanelMesh.");

            CheckHintAnchors();

            BakeReflectionProbes();

            // The core scene's own probe volume - it holds the calibration room, which is a room like
            // any other and wants bounce like any other. The cycles get theirs in
            // `SplitCyclesIntoScenes`. See `EnsureProbeVolume` for why the BUILD owns these and the
            // bake does not.
            EnsureProbeVolume(SceneManager.GetActiveScene(), onlyCalibrationRoom: true);

            // ASLEEP UNTIL ITS TURN - and AFTER the bake, which is the whole reason this is here
            // rather than beside the rest of cycle 2's wiring.
            //
            // A probe renders the scene from its own position, and a disabled renderer does not
            // render. Deactivated first, room2-1 and room2-2 baked an empty room: their .exr files
            // came out half the size of every other room's, which is what a cubemap of nothing
            // compresses to. Walls at 0.85 smoothness are almost entirely what they reflect, so that
            // would have shipped as two rooms lit by a void.
            //
            // WHY DEACTIVATE AT ALL. Frustum culling already keeps an unseen cycle off the screen for
            // nothing, but it does NOT stop scripts: about two hundred components in this scene poll
            // every frame - fifty carryables, fifty falls, seventy balloons, the pads, the doors - and
            // they run whether or not anybody is in their cycle. This stops all of it, drops the
            // renderers and lights, and unregisters the carryables through their own OnDisable, which
            // is exactly right: a cycle nobody can reach should not be in ItemRegistry's sweep.
            //
            // LoopManager wakes the next one before the hatch opens - the player has to be able to
            // look down through it and see the bed - and puts the old one away behind the eyelids.
            SleepCycle(cycleTwoRoot);
            SleepCycle(cycleFourRoot);

            // AND CYCLE 1, which used to ship AWAKE because it is the one the game opens in - and that
            // is precisely the bug. Scenes load additively and asynchronously, so between a cycle's
            // scene arriving and `LoopManager` deciding which one should be awake there are frames
            // where whatever the scene was SAVED with is on screen. Starting the game at cycle 2 (the
            // debug shortcut) therefore opened on a flash of cycle 1's rooms seen from cycle 2's bed.
            //
            // With every root asleep on disk, a loading cycle is never visible and the decision about
            // which one is awake is made in exactly one place - see LoopManager, which now wakes one
            // unconditionally rather than relying on a scene's saved state.
            SleepCycle(room.transform);

            Directory.CreateDirectory("Assets/Scenes");

            // SAVED BEFORE THE SPLIT, AND AGAIN AFTER IT, and the first save is not optional: a scene
            // that has never been written to disk is "untitled", and Unity refuses to open a second
            // scene additively alongside an untitled one. The split creates the cycle scenes exactly
            // that way, so without this it fails outright.
            EditorSceneManager.SaveScene(scene, ScenePath);

            // THE SPLIT, AND IT HAPPENS LAST FOR A REASON. Everything above builds and bakes in ONE
            // scene, exactly as it always did - a reflection probe renders the world around it, so it
            // has to be baked while that world is still assembled. Only once the cubemaps are on disk
            // does each cycle move out into a scene of its own.
            SplitCyclesIntoScenes(new[] { cycleOne, cycleTwo, cycleThree, cycleFour },
                                  new[] { wallDisplay, cycleTwoDisplay, cycleThreeDisplay,
                                          cycleFourDisplay });

            // And again, because the cycles have just left it. The first save wrote a scene that still
            // contained them.
            EditorSceneManager.SaveScene(scene, ScenePath);

            // THE TITLE SCREEN'S PHOTOGRAPH, and it is FRAMED rather than borrowed.
            //
            // It used to be taken from the bed spawn, on the reasoning that the first frame of the
            // game is the honest thing to advertise. What that actually produces is a wall: Room1 is
            // an empty white box, the spawn looks straight down it, and the shot came back as one
            // flat grey panel grid filling the frame with the bright part of the room - the floor,
            // the ceiling fixtures, the bed - all outside it.
            //
            // **AND THEN IT WAS FRAMED AGAIN, 2026-08-20, SQUARE TO ONE WALL.** The corner shot did
            // put the whole room in frame and that turned out to be the problem: two wall grids
            // running in different directions with the ceiling in a third, converging on a vanishing
            // point in the middle of the picture. There is no calm area anywhere in it, and the menu
            // sets its type over near-black grooves on white at full contrast.
            //
            // A wall parallel to the image plane does not converge AT ALL - every groove projects
            // perfectly horizontal or perfectly vertical - so the same room, shot square, reads as a
            // designed surface rather than as a screenshot. That is the whole change: the room is
            // just as bright and just as white, and the geometry stops arguing with the words.
            //
            // Safe to move both the player and the camera here: the scene has already been saved
            // above, and this in-memory edit is discarded when the room is reopened from disk at the
            // end of this method.
            player.transform.SetPositionAndRotation(bedSpawn.position, bedSpawn.rotation);

            // AWAKE FOR THE PHOTOGRAPH, then straight back to sleep. Cycle 1's root ships asleep now
            // (see SleepCycle, and the flash it fixes) and this runs after that, so without waking it
            // the capture is a photograph of an empty scene and the title screen goes black.
            bool wasAwake = room.activeSelf;
            room.SetActive(true);

            Camera shotCam = player.GetComponentInChildren<Camera>();
            if (shotCam != null)
            {
                // Room1 is centred on the origin: 8.75 across, 10.5 deep, 5.41 to the ceiling. These
                // are world coordinates because that is the frame the room is built in.
                //
                // THE SOUTH WALL, AND IT IS CHOSEN FOR WHAT IT DOES NOT HAVE. Room1 is built with
                // `Rect.zero` for its south cutout, so that wall is the one unbroken panel grid in the
                // building - no doorway, no pocket, no fixture. And every piece of furniture in the
                // room is in the +Z half (the nightstand is at z=1.35 and the bed beside it), so a
                // camera at z=+0.5 facing -Z has all of it BEHIND the lens rather than in the shot.
                //
                // Dead centre in X on purpose. A grid is symmetrical and a picture of one that is
                // nearly-but-not-quite centred reads as a mistake; the asymmetry on this screen is the
                // menu column, which is where asymmetry belongs.
                // **SQUARE TO THE FAR WALL, FROM THE BACK OF THE ROOM.** The first square shot filled
                // the frame with the wall alone and it came back as wallpaper: fifteen cells, no
                // depth, and a surface that is in shade at that angle so the room stopped being
                // bright - which is the one thing the picture had going for it.
                //
                // Standing back instead puts the floor, the ceiling and both side walls in frame with
                // the far wall small in the middle. **The front wall's grid still does not converge**
                // - that is what "square" buys and it is kept - while everything else runs to a single
                // vanishing point dead centre. One-point perspective is the most deliberate-looking
                // thing a room can do, and it costs nothing but where the camera stands.
                //
                // Facing the NORTH wall, which is the one with the doorway: the shot gets a subject
                // (a door in a white wall, which is the whole game) and the bed in the middle
                // distance, without either being the corner-shot clutter this replaced.
                const float wallZ = RoomDepth / 2f;                   // +5.25
                const float standoff = 9.85f;                         // camera to wall
                // Wider than the flat shot's 40 because the frame now has to reach the side walls, and
                // still narrower than the player's 60 - a 60 here bows the grid at the corners.
                // **COMPOSED FOR THE OVERSCANNED VIEW, NOT THE RAW ONE.** `MenuBackdrop` draws this
                // image 8% past every edge so it has room to drift, which magnifies it by 1.16 and
                // crops that 8% off - so the picture a player actually sees is TIGHTER than the file.
                // Play caught it as "the composition was good until it started moving".
                //
                // The magnification cannot be removed; an image can only be slid inside a window if it
                // is bigger than the window. So the capture is widened by the same factor instead:
                // 36 degrees is the framing that was wanted, tan(18) x 1.16 is what has to be captured
                // to still see 36 of it after the crop, and that is 41.3.
                const float shotFov = 41.3f;
                // **THE CEILING IS FRAMED OUT ENTIRELY, and that is the fix rather than a compromise.**
                //
                // It is the darkest surface in the building by a wide margin - it faces away from every
                // downlight and is lit by ambient alone - so in a shot that included it, it read as a
                // hole in the roof rather than as a surface. Lighting it was tried and reverted: an
                // emissive ceiling fixes the picture and makes the ROOM wrong, and the room is not the
                // menu's to change.
                //
                // A surface that is not in the frame cannot be the wrong colour. What is left is what
                // the downlights actually hit - the floor at (235,253,255) and the walls - which is
                // also what the player looks at in play, so the menu and the game agree.
                //
                // A LEVEL CAMERA IS NON-NEGOTIABLE - pitching down would put more floor in frame and
                // take the square grid with it, because the far wall only projects without convergence
                // while it is parallel to the image plane. So the ceiling has to be excluded by HEIGHT
                // and LENS together, and the two trade against each other: the top of the frame lands
                // at `eyeY + standoff * tan(fov/2)`, which has to stay under the 5.41m wall.
                //
                // 2.00m and 41.3 degrees puts the top of the CAPTURE at 5.71m, which is 0.30m above
                // the wall - so the file does contain a sliver of ceiling, in its top 4.1%. That is
                // deliberate and it is safe: `MenuBackdrop` slides this image within an 8% margin and
                // only ever spends `verticalRatio` (0.22) of the vertical one, so the top 6.2% of the
                // file is cropped away no matter where the drift is. 4.1 sits inside 6.2 with room to
                // spare, and what the player sees is the 36-degree framing with no ceiling in it.
                //
                // **The two numbers are coupled**: widen the lens or raise the camera and more ceiling
                // enters the file; raise `MenuBackdrop.verticalRatio` and less of the top is hidden.
                const float eyeY = 2.0f;

                Vector3 eye = new Vector3(0f, eyeY, wallZ - standoff);
                shotCam.fieldOfView = shotFov;
                shotCam.transform.SetPositionAndRotation(eye, Quaternion.LookRotation(Vector3.forward, Vector3.up));
                Debug.Log($"[SceneBuilder] Menu background: square to the north wall from {eye}, fov {shotFov}");
            }

            CaptureMenuBackground(shotCam, room.transform);
            room.SetActive(wasAwake);

            BuildMainMenuScene();

            // The build settings scene list was empty, so a standalone player would have shipped
            // with no scenes at all. Reasserted on every build rather than set once, because the
            // list lives in ProjectSettings and nothing else here maintains it.
            //
            // MainMenu is index 0, so that is where a standalone player opens.
            // And every cycle scene after them. A scene that is not in this list cannot be loaded by
            // name at runtime at all - `SceneManager.LoadSceneAsync` simply returns null - so a cycle
            // missing from here is a cycle that does not exist in a built player.
            var buildScenes = new System.Collections.Generic.List<EditorBuildSettingsScene>
            {
                new EditorBuildSettingsScene(MenuScenePath, true),
                new EditorBuildSettingsScene(ScenePath, true),
            };
            foreach (string name in CycleSceneNames)
                buildScenes.Add(new EditorBuildSettingsScene(CycleScenePath(name), true));
            EditorBuildSettings.scenes = buildScenes.ToArray();

            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();

            // BuildMainMenuScene left the menu open. Put the room back, so building from the GUI
            // leaves the Editor looking at the thing that was just built.
            EditorSceneManager.OpenScene(ScenePath);

            Debug.Log("[SceneBuilder] IterationRoom scene built at " + ScenePath);
            Debug.Log("[SceneBuilder] MainMenu scene built at " + MenuScenePath);
        }

        // Renders the player camera to a PNG for the title screen to sit behind. It is literally
        // the first frame of the game - the view down the room from the foot of the bed, which is
        // exactly what the Editor's Game view shows before Play is pressed.
        //
        // Regenerated on every build that can render, so the menu can never advertise a room that
        // no longer exists. Under `-nographics` there is no device to render with: the capture is
        // SKIPPED and the previous PNG stands, because a stale background is a far better outcome
        // than a failed build. A frame that renders but comes back WRONG is held to the same rule,
        // and the tripwire below is what makes "wrong" something this can actually tell.
        // A BOX-FILTERED DOWNSCALE, which is the second half of supersampling and the half that
        // actually removes the aliasing - averaging the samples is what turns four hard pixels into
        // one soft edge. Done in C# rather than by a bilinear blit because a blit at exactly 2:1
        // samples pixel CENTRES and can miss half the detail it is supposed to be averaging.
        private static Texture2D Downsample(Texture2D src, int width, int height)
        {
            int sx = src.width / width, sy = src.height / height;
            if (sx <= 1 && sy <= 1) return src;

            Color[] source = src.GetPixels();
            Color[] outPixels = new Color[width * height];
            float inv = 1f / (sx * sy);

            for (int y = 0; y < height; y++)
            {
                for (int x = 0; x < width; x++)
                {
                    float r = 0f, g = 0f, b = 0f;
                    for (int j = 0; j < sy; j++)
                    {
                        int row = (y * sy + j) * src.width + x * sx;
                        for (int i = 0; i < sx; i++)
                        {
                            Color c = source[row + i];
                            r += c.r; g += c.g; b += c.b;
                        }
                    }
                    outPixels[y * width + x] = new Color(r * inv, g * inv, b * inv, 1f);
                }
            }

            Texture2D result = new Texture2D(width, height, TextureFormat.RGB24, false);
            result.SetPixels(outPixels);
            result.Apply();
            return result;
        }

        // **TWO FRAMES, ONE POSE.** The lit room, and the same room with the fixtures on one side
        // switched off - `MenuFlicker` cross-cuts between them on the title screen.
        //
        // The pair only works because NOTHING moves between the two exposures: same camera, same
        // position, same lens, same frame. Anything that shifted - a drifting prop, a re-framed
        // camera - would read as a jump cut rather than as a light going out, which is the one way
        // this effect can look broken rather than absent.
        private static void CaptureMenuBackground(Camera cam, Transform room)
        {
            CaptureMenuFrame(cam, MenuBackgroundPath);

            // **THE LIGHTS ONLY, NEVER THE EMISSIVE PANELS.** A fixture's glowing face wears
            // `CeilingFixture`, which is ONE material shared by every fixture in the building - dim it
            // and every ceiling in the game goes with it. The `Light` components are per-object and
            // are what actually paints the walls and floor, which is the whole of what this shot is
            // of: the framing deliberately excludes the ceiling (see the note at the call site), so
            // the panels are barely in frame anyway.
            var doused = new System.Collections.Generic.List<Light>();
            if (room != null)
                foreach (Light light in room.GetComponentsInChildren<Light>(true))
                {
                    // ONE SIDE OF THE ROOM. `BuildCeilingLights` lays a 2x2 grid either side of the
                    // room's centreline, so everything at negative x is the left-hand pair - which is
                    // the side the menu's column of text sits over, so the fault is behind the words
                    // rather than out on the open right where the eye is resting.
                    if (!light.enabled || light.transform.position.x >= 0f) continue;
                    light.enabled = false;
                    doused.Add(light);
                }

            try { CaptureMenuFrame(cam, MenuBackgroundDarkPath); }
            finally { foreach (Light light in doused) light.enabled = true; }

            Debug.Log($"[SceneBuilder] Menu background: two frames, {doused.Count} fixture(s) doused "
                    + "for the dark one. Zero would mean the flicker has nothing to show.");
        }

        private static void CaptureMenuFrame(Camera cam, string path)
        {
            if (cam == null)
            {
                Debug.LogWarning("[SceneBuilder] No player camera; menu background not captured.");
                return;
            }

            if (SystemInfo.graphicsDeviceType == GraphicsDeviceType.Null)
            {
                Debug.LogWarning("[SceneBuilder] No graphics device (-nographics): keeping the existing "
                               + "menu background. Rebuild from the Editor to refresh it.");
                return;
            }

            const int width = 1920, height = 1080;
            // RENDERED AT 2x AND DOWNSAMPLED. The room is a grid of thin black grooves on white, which
            // is the worst case for aliasing there is: at 1:1 every line crawls and breaks up, and the
            // menu advertised the game as a jaggy mess. Supersampling fixes it regardless of what MSAA
            // the pipeline asset happens to be set to, which is the reason to do it this way rather
            // than by asking the RenderTexture for anti-aliasing.
            const int ss = 2;
            int rw = width * ss, rh = height * ss;

            RenderTexture rt = new RenderTexture(rw, rh, 24, RenderTextureFormat.ARGB32, RenderTextureReadWrite.sRGB);
            RenderTexture previousActive = RenderTexture.active;
            RenderTexture previousTarget = cam.targetTexture;
            CameraClearFlags previousFlags = cam.clearFlags;
            Color previousBackground = cam.backgroundColor;
            int previousMask = cam.cullingMask;
            Texture2D shot = null;
            byte[] png = null;
            float stray = 1f;

            try
            {
                cam.targetTexture = rt;

                // The tripwire. The camera clears to Skybox in play, and the rooms are sealed boxes
                // with the camera INSIDE one, so a correct frame is geometry edge to edge and the
                // clear never shows - which means the clear colour reaching the PNG is proof that
                // something did not draw, or that the camera is not where it should be. Clearing to
                // magenta instead makes that proof readable. It cannot change a good frame, because
                // a good frame contains none of it.
                cam.clearFlags = CameraClearFlags.SolidColor;
                cam.backgroundColor = MenuCaptureTripwire;

                // **NO BODY IN THE TITLE SHOT** (2026-08-23, by request). This is the player's own
                // camera, and the caller MOVES it across the room to frame the north wall - but the
                // body stays with the player root, so it does not come along. It stands wherever the
                // spawn left it and walks straight into the frame. Before the player had a body this
                // capture was of an empty room, which is what the title screen is composed as.
                //
                // All three layers, not just the world one. The first-person body is headless and
                // armless by design, so what it contributes to a shot taken from across the room is a
                // legless torso - worse than the whole person, not better. And the shadow-only
                // instance would leave a person-shaped shadow on the floor with nobody casting it.
                cam.cullingMask &= ~((1 << EnsureLayer(PlayerBodyViewLayer))
                                   | (1 << EnsureLayer(PlayerBodyWorldLayer))
                                   | (1 << EnsureLayer(PlayerBodyShadowLayer)));

                shot = new Texture2D(rw, rh, TextureFormat.RGB24, false);

                // Rendered up to TWICE. The frame this has been seen to get wrong was the first one
                // after the URP asset was rewritten earlier in the same build: URP drops and
                // rebuilds its pipeline instance when its asset changes, and a request submitted
                // into that window came back as bare skybox with every lit surface missing. A
                // second request is enough, and costs one frame on the build that needs it.
                const int attempts = 2;
                for (int attempt = 1; attempt <= attempts && png == null; attempt++)
                {
                    // URP does not support a bare Camera.Render() from arbitrary code - a render
                    // request is the supported route, and it is also what actually runs the volume
                    // stack (tonemapping, bloom, vignette) the room's look is tuned against. The
                    // fallback is there for a pipeline that does not advertise the request.
                    var request = new UniversalRenderPipeline.SingleCameraRequest { destination = rt };
                    if (RenderPipeline.SupportsRenderRequest(cam, request))
                        RenderPipeline.SubmitRenderRequest(cam, request);
                    else
                        cam.Render();

                    RenderTexture.active = rt;
                    shot.ReadPixels(new Rect(0f, 0f, rw, rh), 0, 0);
                    shot.Apply();

                    stray = StrayClearFraction(shot);
                    if (stray <= MenuCaptureMaxStray)
                        png = Downsample(shot, width, height).EncodeToPNG();
                    else if (attempt < attempts)
                        Debug.LogWarning($"[SceneBuilder] Menu background attempt {attempt}: {stray:P1} of the "
                                       + "frame is clear colour, so the room did not render. Retrying.");
                }
            }
            finally
            {
                // Restored in a finally: leaving a target texture on the player camera would mean
                // the game renders into a RenderTexture instead of the screen, and the saved scene
                // would carry it. The clear flags go back for the same reason - the room is sealed
                // so it would never show, but the scene should not carry a setting made for a
                // one-off capture.
                cam.targetTexture = previousTarget;
                cam.clearFlags = previousFlags;
                cam.backgroundColor = previousBackground;
                // Or the saved scene ships a player who cannot see their own legs.
                cam.cullingMask = previousMask;
                RenderTexture.active = previousActive;
                if (shot != null) Object.DestroyImmediate(shot);
                rt.Release();
                Object.DestroyImmediate(rt);
            }

            // Nothing written, so the previous PNG stands - same call as `-nographics`. An ERROR
            // rather than a warning because this one already shipped once: a skybox went to itch.io
            // behind the title screen and the build reported success.
            if (png == null)
            {
                Debug.LogError($"[SceneBuilder] Menu background NOT captured - {stray:P1} of the frame came back "
                             + "clear colour on both attempts. The previous PNG is kept. Build again from the "
                             + "Editor; if it persists, the camera is no longer inside the room.");
                return;
            }

            File.WriteAllBytes(path, png);

            AssetDatabase.ImportAsset(path, ImportAssetOptions.ForceUpdate);
            if (AssetImporter.GetAtPath(path) is TextureImporter importer)
            {
                importer.textureType = TextureImporterType.Sprite;
                importer.spriteImportMode = SpriteImportMode.Single;
                importer.mipmapEnabled = false;
                importer.maxTextureSize = 2048;
                // UNCOMPRESSED, and this is what the softness was. The default is DXT at quality 50,
                // and block compression is at its worst on exactly this image: huge smooth gradients
                // across a wall and floor, where 4x4 blocks of two interpolated endpoints show as
                // banding and mush. It is one full-screen sprite on a menu - about 8MB uncompressed,
                // which is nothing to spend on the first thing anybody sees.
                importer.textureCompression = TextureImporterCompression.Uncompressed;
                importer.filterMode = FilterMode.Bilinear;
                importer.SaveAndReimport();
            }

            Debug.Log($"[SceneBuilder] Menu background captured to {path}");
        }

        // What fraction of the frame is still wearing the camera's clear colour. Compared with a
        // tolerance rather than for equality because the readback is sRGB-converted, and only on the
        // two channels that separate magenta from anything the room contains.
        private static float StrayClearFraction(Texture2D shot)
        {
            Color32 want = MenuCaptureTripwire;
            Color32[] pixels = shot.GetPixels32();
            int stray = 0;
            for (int i = 0; i < pixels.Length; i++)
            {
                Color32 p = pixels[i];
                if (Mathf.Abs(p.r - want.r) < 56 && Mathf.Abs(p.g - want.g) < 56 && Mathf.Abs(p.b - want.b) < 56)
                    stray++;
            }
            return pixels.Length == 0 ? 1f : (float)stray / pixels.Length;
        }

        private static void EnsureFolders()
        {
            if (!AssetDatabase.IsValidFolder("Assets/Editor")) AssetDatabase.CreateFolder("Assets", "Editor");
            if (!AssetDatabase.IsValidFolder(MaterialsDir)) AssetDatabase.CreateFolder("Assets", "Materials");
            if (!AssetDatabase.IsValidFolder(PrefabsDir)) AssetDatabase.CreateFolder("Assets", "Prefabs");
            if (!AssetDatabase.IsValidFolder(SettingsDir)) AssetDatabase.CreateFolder("Assets", "Settings");
            if (!AssetDatabase.IsValidFolder(TexturesDir)) AssetDatabase.CreateFolder("Assets", "Textures");
            if (!AssetDatabase.IsValidFolder(AudioDir)) AssetDatabase.CreateFolder("Assets", "Audio");
            if (!AssetDatabase.IsValidFolder(VoiceDir)) AssetDatabase.CreateFolder(AudioDir, "Voice");
            if (!AssetDatabase.IsValidFolder(SfxDir)) AssetDatabase.CreateFolder(AudioDir, "SFX");
            if (!AssetDatabase.IsValidFolder(IconsDir)) AssetDatabase.CreateFolder(TexturesDir, "Icons");
        }

        // Layers have to exist in ProjectSettings/TagManager.asset before anything can be put on
        // one, and there is no scripting API that creates them - the settings asset is edited
        // directly. Idempotent by name, so a rebuild reuses the slot instead of burning a new one
        // every time (there are only 24 user layers, and this runs on every build).
        private static int EnsureLayer(string layerName)
        {
            int existing = LayerMask.NameToLayer(layerName);
            if (existing >= 0) return existing;

            Object[] assets = AssetDatabase.LoadAllAssetsAtPath("ProjectSettings/TagManager.asset");
            if (assets == null || assets.Length == 0)
            {
                Debug.LogWarning($"[SceneBuilder] TagManager.asset unreadable; '{layerName}' stays on Default.");
                return 0;
            }

            SerializedObject tagManager = new SerializedObject(assets[0]);
            SerializedProperty layers = tagManager.FindProperty("layers");

            // 0-7 are Unity's own - Default, TransparentFX, Ignore Raycast, Water, UI and three
            // reserved blanks. The blanks look free and are not: writing into one is silently
            // dropped, so the search starts at 8.
            for (int i = 8; i < layers.arraySize; i++)
            {
                SerializedProperty slot = layers.GetArrayElementAtIndex(i);
                if (!string.IsNullOrEmpty(slot.stringValue)) continue;

                slot.stringValue = layerName;
                tagManager.ApplyModifiedProperties();
                AssetDatabase.SaveAssets();
                Debug.Log($"[SceneBuilder] Created layer '{layerName}' at index {i}.");
                return i;
            }

            Debug.LogWarning($"[SceneBuilder] No free user layer for '{layerName}'; staying on Default.");
            return 0;
        }

        // Ambient occlusion is a renderer feature on the URP renderer asset rather than a volume
        // override, so it lives outside the scene and has to be reconciled separately. Adding it
        // is also not idempotent on its own - a retried add silently stacks duplicates - so this
        // collapses the list back down to exactly one configured instance.
        private static void ConfigureAmbientOcclusion()
        {
            var rendererData = AssetDatabase.LoadAssetAtPath<UniversalRendererData>($"{SettingsDir}/IterationRenderer.asset");
            if (rendererData == null) return;

            ScriptableRendererFeature ssao = rendererData.rendererFeatures
                .Find(f => f != null && f.GetType().Name == "ScreenSpaceAmbientOcclusion");
            if (ssao == null) return;

            SerializedObject so = new SerializedObject(ssao);
            // Deliberately a tight contact-shadow radius. Anything wide (0.12 was tried) throws a
            // broad dithered halo around small objects - the door button, the door edges - and on
            // flat white walls that reads as dirt rather than shading.
            so.FindProperty("m_Settings.Radius").floatValue = 0.045f;
            so.FindProperty("m_Settings.Intensity").floatValue = 0.7f;
            so.FindProperty("m_Settings.DirectLightingStrength").floatValue = 0.25f;
            // Interleaved gradient resolves cleaner than blue noise once the radius is this small.
            so.FindProperty("m_Settings.AOMethod").enumValueIndex = 1;
            // These enums run High=0, Medium=1, Low=2 - 0 is the BEST quality, which reads
            // backwards. Setting Samples to 2 drops it to 4 samples and sprays occlusion noise
            // around every object; that is not a lighting bug, it's this field.
            so.FindProperty("m_Settings.Samples").enumValueIndex = 0;
            so.FindProperty("m_Settings.NormalSamples").enumValueIndex = 0;
            so.FindProperty("m_Settings.BlurQuality").enumValueIndex = 0;
            // HALF RESOLUTION. SSAO is a full-screen pass and this is a WebGL build; running it at
            // full res was costing a lot for very little, because the radius above is 0.045 - the
            // occlusion it draws is a thin contact line under objects, and a thin line survives
            // being resolved at half res. Turn this back off if the contact shading starts to
            // crawl along the door edges.
            so.FindProperty("m_Settings.Downsample").boolValue = true;
            so.ApplyModifiedPropertiesWithoutUndo();

            EditorUtility.SetDirty(ssao);
            AssetDatabase.SaveAssets();
        }

        // Post-processing is where most of the "not a flat whitebox" impression comes from.
        private static void BuildPostProcessing()
        {
            string profilePath = $"{SettingsDir}/IterationVolume.asset";
            VolumeProfile profile = AssetDatabase.LoadAssetAtPath<VolumeProfile>(profilePath);
            if (profile == null)
            {
                profile = ScriptableObject.CreateInstance<VolumeProfile>();
                AssetDatabase.CreateAsset(profile, profilePath);
            }

            Tonemapping tonemapping = GetOrAddOverride<Tonemapping>(profile);
            tonemapping.mode.overrideState = true;
            // Neutral, not ACES: ACES crushes the near-white walls into grey and warms them.
            tonemapping.mode.value = TonemappingMode.Neutral;

            Vignette vignette = GetOrAddOverride<Vignette>(profile);
            vignette.intensity.overrideState = true;
            vignette.intensity.value = 0.25f;
            vignette.smoothness.overrideState = true;
            vignette.smoothness.value = 0.4f;

            Bloom bloom = GetOrAddOverride<Bloom>(profile);
            bloom.threshold.overrideState = true;
            // The walls sit near 1.0 luminance, so a default threshold would bloom the entire room.
            bloom.threshold.value = 1.2f;
            bloom.intensity.overrideState = true;
            bloom.intensity.value = 0.2f;

            ColorAdjustments color = GetOrAddOverride<ColorAdjustments>(profile);
            color.contrast.overrideState = true;
            color.contrast.value = 8f;

            // **APV'S SAMPLING NOISE IS A TAA FEATURE, AND THIS PROJECT HAS NO TAA.**
            //
            // Adaptive Probe Volumes dither the probe sampling position to hide the seams between
            // subdivision levels, and Unity's own tooltip on `animateSamplingNoise` says what it is
            // for: *"Whether to animate the noise WHEN TAA IS ENABLED, smoothing potentially out the
            // noise pattern introduced."* It defaults to **on**, with 0.1 of noise.
            //
            // The player camera runs **SMAA** (`BuildPlayer`), which resolves one frame at a time and
            // cannot smooth anything across frames. So the dither was simply re-rolled every frame
            // with nothing to average it out, and every wall panel in the building visibly pulsed the
            // instant APV was turned on (2026-08-25, reported from play as "밝기가 튀는" - brightness
            // popping). Nothing was wrong with the bake; this is the sampler.
            //
            // **Noise to zero as well, not just un-animated.** A static dither is a fixed grain, and
            // this project has already learnt once what fine grain does to a white room - the SSAO
            // radius note calls 0.12 a halo that "on white walls reads as *dirt*". Clinical evenness
            // is the look. **If seams appear between subdivision levels** - a visible step in
            // brightness partway along a wall, which is what the noise exists to hide - raise this
            // toward 0.1 rather than turning the animation back on.
            //
            // `leakReductionMode` is left at Unity's default (`Quality`), which is already the good
            // one; it is named here only so the next person knows it was considered.
            ProbeVolumesOptions probes = GetOrAddOverride<ProbeVolumesOptions>(profile);
            probes.animateSamplingNoise.overrideState = true;
            probes.animateSamplingNoise.value = false;
            probes.samplingNoise.overrideState = true;
            probes.samplingNoise.value = 0f;

            EditorUtility.SetDirty(profile);
            AssetDatabase.SaveAssets();

            GameObject go = new GameObject("PostProcessing");
            Volume volume = go.AddComponent<Volume>();
            volume.isGlobal = true;
            volume.priority = 0f;
            volume.sharedProfile = profile;
        }

        private static T GetOrAddOverride<T>(VolumeProfile profile) where T : VolumeComponent
        {
            if (profile.TryGet(out T existing)) return existing;

            T added = profile.Add<T>(true);
            // Volume overrides live as sub-assets of the profile; without this they are lost on reload.
            AssetDatabase.AddObjectToAsset(added, profile);
            return added;
        }

        // URP has no "Standard" shader and Built-in has no URP Lit, so resolve whichever the
        // project is actually on rather than hardcoding one and silently producing magenta.
        private static Shader OpaqueShader()
        {
            Shader urp = Shader.Find("Universal Render Pipeline/Lit");
            return urp != null ? urp : Shader.Find("Standard");
        }

        // Standard calls it _Glossiness, URP Lit calls it _Smoothness.
        private static void SetSmoothness(Material mat, float value)
        {
            if (mat.HasProperty("_Glossiness")) mat.SetFloat("_Glossiness", value);
            if (mat.HasProperty("_Smoothness")) mat.SetFloat("_Smoothness", value);
        }

        // URP gates additional (non-main) lights behind the pipeline asset, and the defaults are
        // tuned for mobile: too few lights per object and no shadows from them. Reconciled here
        // rather than left to the asset, so the scene's lighting can't be broken by an asset reset.
        private static void ConfigureLightingPipeline()
        {
            var urp = AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>($"{SettingsDir}/IterationURP.asset");
            if (urp == null) return;

            SerializedObject so = new SerializedObject(urp);

            // Enums are set BY NAME, never by index. URP serialises this one as
            // [Disabled, PerPixel, PerVertex] - PerPixel is index 1, not the 2 you would guess
            // from the inspector's ordering, and picking 2 silently gives per-vertex lighting,
            // which washes the room into flat blocks: precisely the look this change exists to fix.
            SetEnumByName(so, "m_AdditionalLightsRenderingMode", "PerPixel");
            // Every surface in the room is reached by all six fixtures, and anything under this
            // limit means a slab silently drops the lights beyond it. 8 is URP's maximum.
            SetIfPresent(so, "m_AdditionalLightsPerObjectLimit", 8);
            SetIfPresent(so, "m_AdditionalLightShadowsSupported", true);
            // Also an enum, not a pixel count - assigning 2048 as an int throws "enum index is out
            // of range". One shared atlas holds every additional light's shadow map.
            //
            // **4096, HOLDING EXACTLY FOUR MAPS OF 2048** (2026-08-25, by request, after play).
            //
            // The atlas, `ShadowBudget.maxCasters` and the tier below are ONE decision and must move
            // together. A 2048 atlas is 4.2M texels, which buys either four maps of 1024 or one of
            // 2048 - and play rejected BOTH: four of 1024 gave 22.7mm texels and a 20cm key threw a
            // 10cm smudge, while one of 2048 was sharp but made the shadow JUMP as the player crossed
            // the room, because the single caster is whichever fixture is nearest and that changes.
            //
            // 4096 is 16.8M and takes four maps of 2048: sharp AND stable, plus the soft overlap a
            // ceiling of four panels genuinely produces. **The cost is four times the shadow pixels
            // this game drew before**, and this number was 4096 once before and came down after play
            // reported lag - so it is the first thing to put back if the frame rate suffers. The
            // suspected cause then was full-screen passes rather than this, but that was never
            // measured.
            // **If the console ever prints "Reduced additional punctual light shadows resolution ...
            // to make N shadow maps fit" again, either `maxCasters` went up or something is casting
            // that this does not know about.** That line is the only warning URP gives before it
            // silently halves every map in the building.
            //
            // **2048 PER LIGHT.** A 130-degree cone from 5.41m spreads its map over 23.2m of floor, so
            // this is what sets the texel: 1024 gave 22.7mm and a key's shank is thinner than one of
            // those, which is how a 20cm key came out as a 10cm smudge. 2048 halves it to 11.3mm.
            //
            // **Paired with `maxCasters` 4 and a 4096 atlas above** - raise either without the other
            // and URP silently halves every map in the building, warning once.
            SetEnumByName(so, "m_AdditionalLightsShadowmapResolution", "_4096");
            // The per-light tiers URP picks from. `UniversalAdditionalLightData` defaults a light to
            // the HIGH one, so this is what actually reaches the fixtures.
            SetIfPresent(so, "m_AdditionalLightsShadowResolutionTierHigh", 2048);
            SetIfPresent(so, "m_SoftShadowsSupported", true);

            // **THE PROBE SYSTEM FOLLOWS THE DATA - it is not a constant, and it used to be.**
            //
            // `BakeLighting` switches this to APV as the first step of a bake, because APV is the only
            // GI this project can use (nothing here has lightmap UVs; see that file). But **APV with
            // no baked data is worse than no APV**: every renderer marked `ReceiveGI.LightProbes` -
            // which is all 3,432 of them - samples a grid that does not exist.
            //
            // So this was pinned to `LegacyLightProbes` on every build, as a safety catch, with a note
            // saying that IF A BAKE WERE EVER MADE TO STICK THE TWO HALVES WOULD HAVE TO MOVE
            // TOGETHER. **They now do** (2026-08-25): the bake works, so pinning it off would silently
            // throw away every cell of it on the next rebuild - a bake nobody could see the result of,
            // which is a worse failure than the crash was, because it does not announce itself.
            //
            // **The catch is kept, only asked as a QUESTION rather than assumed.** No baked data
            // anywhere - a fresh clone, or a bake that has not been run yet - still lands on legacy,
            // which is the state that renders correctly without one.
            //
            // BY NAME, because this is a serialised enum and `SetIfPresent(int)` refuses those on
            // purpose - the same guard that silently ignored the first attempt at `m_MSAA`. The
            // values are `LegacyLightProbes = 0` and `ProbeVolumes = 1`.
            bool haveBakedProbes = AnyBakedProbeVolumes();
            SetEnumByName(so, "m_LightProbeSystem",
                haveBakedProbes ? "ProbeVolumes" : "LegacyLightProbes");
            Debug.Log(haveBakedProbes
                ? "[SceneBuilder] Baked probe volumes found - URP left on Adaptive Probe Volumes."
                : "[SceneBuilder] URP on LegacyLightProbes - Adaptive Probe Volumes are OFF by "
                + "choice, not for want of a bake. See SceneBuilder.AnyBakedProbeVolumes.");

            // **MSAA 2, NOT 4** (2026-08-25, after play reported lag). Authored here rather than left
            // in the asset for the reason every tuned value is (CLAUDE.md §2) - it was 4 and nothing
            // anywhere said why, which is how a number nobody has examined survives.
            //
            // **THIS GAME ALREADY HAS A SECOND ANTIALIASER.** The player camera runs SMAA
            // (`BuildPlayer`), so MSAA is not carrying the picture on its own - it is buying extra
            // coverage on geometric edges, which this building does have a lot of in the panel
            // grooves. 4x at 1080p in HDR is four full colour and depth samples per pixel of
            // bandwidth for the second half of a job already being done.
            //
            // 2 keeps the geometric coverage that SMAA cannot give (SMAA only sees the resolved
            // image) at half the bandwidth. **Use "Disabled" to turn MSAA off entirely** - that is the
            // bigger saving and the one to try next if the frame rate is still short.
            //
            // BY NAME, because `m_MSAA` is an enum and `SetIfPresent(int)` refuses those on purpose:
            // MsaaQuality's values are 1/2/4/8 and its INDICES are 0/1/2/3, so assigning the number
            // you want picks a different mode. The first attempt at this line did exactly that and
            // was silently ignored by the guard, which is the guard working.
            SetEnumByName(so, "m_MSAA", "_2x");

            // **DEPTH BIAS 0.5, NOT URP'S DEFAULT 1** (2026-08-24, by request). Authored here rather
            // than left to the asset for the reason every tuned value is (CLAUDE.md §2) - the asset is
            // rewritten on every build, so a number only an inspector knows is a number that survives
            // by luck.
            //
            // What it trades: a shadow map stores one depth per texel, so a surface whose depth varies
            // within a texel shadows ITSELF in stripes - acne. Depth bias pushes the stored depth away
            // from the light to stop that, and the side effect is that the whole shadow shifts, which
            // reads as the object floating above its own shadow (peter-panning). **Too low is acne,
            // too high is a detached shadow, and both are visible on the floor of any room here.**
            //
            // Halved because detachment is the fault this building actually reported and 2048 maps
            // over a 130-degree cone need less bias than 1024 did. Normal bias is left at 1: it buys
            // the same protection by moving the SAMPLE along the surface normal instead, which costs
            // thin shadows rather than contact, so it is the wrong one to spend first.
            //
            // **Neither number is verified by eye.** If the floor develops stripes, this is what did
            // it. See docs/rendering-notes.md.
            SetFloatIfPresent(so, "m_ShadowDepthBias", 0.5f);
            SetFloatIfPresent(so, "m_ShadowNormalBias", 1f);

            // OFF, because there is no main light. URP's main light is the brightest DIRECTIONAL
            // light and this project deletes the scene's - the rooms are sealed boxes with a
            // ceiling slab, so a sun has no way in. Keeping its shadows enabled reserved a 2048 map
            // and a shadow pass for a light that does not exist.
            SetIfPresent(so, "m_MainLightShadowsSupported", false);

            // **30, RAISED BACK FROM 15** (2026-08-25, after play: "a shadow only appears once you
            // get close, even though the object is already on screen"). That is precisely what this
            // number does - URP draws shadows within it OF THE CAMERA and fades them out before the
            // edge, so past it an object on screen simply has none.
            //
            // **The argument for 15 was that halving it doubles the effective texel density, and that
            // argument is FALSE HERE.** Cascade resolution is a DIRECTIONAL-light property, and this
            // project has no directional light: it is deleted at build, `m_MainLightShadowsSupported`
            // is off and the cascade count is 1. Every shadow in the game comes from a spot, whose
            // map is sized by its cone angle and its resolution tier and does not know this number
            // exists. So the "quality gain" half of that trade was never being collected - 15 was
            // buying nothing and paying for it in pop-in.
            //
            // The other half of the old reasoning has also expired: it was written when **only Room1
            // cast**, so "30m reaches two rooms past anything worth shadowing" was true. Every room
            // casts now.
            //
            // What it still genuinely does is stop a whole corridor of lit rooms rendering shadow
            // maps at once, and that is the thing to watch if the frame rate moves.
            SetFloatIfPresent(so, "m_ShadowDistance", 30f);

            // GhostFaint samples _CameraDepthTexture to fade where a ghost crosses solid geometry,
            // and that texture only exists if something asks for it. SSAO happens to request depth
            // as a pass input today, which is exactly the kind of accident that breaks the day the
            // renderer feature is retuned - so the dependency is declared here rather than relied on.
            SetIfPresent(so, "m_RequireDepthTexture", true);

            // URP GATES BOX PROJECTION AND PROBE BLENDING AT THE ASSET, and both were OFF. Setting
            // `probe.boxProjection = true` on the component - which BuildReflectionProbe has always
            // done, with a comment explaining why this room shape needs it - does nothing at all
            // while this is false. Blending matters at the doorways, where two rooms' probes
            // overlap and an unblended switch pops as the player walks through.
            SetIfPresent(so, "m_ReflectionProbeBoxProjection", true);
            SetIfPresent(so, "m_ReflectionProbeBlending", true);

            so.ApplyModifiedPropertiesWithoutUndo();
            EditorUtility.SetDirty(urp);
            AssetDatabase.SaveAssets();
        }

        private static void SetIfPresent(SerializedObject so, string path, int value)
        {
            SerializedProperty p = so.FindProperty(path);
            if (p != null && p.propertyType != SerializedPropertyType.Enum) p.intValue = value;
        }

        // Resolves the index from the serialised enum's own name list, so a reordered or extended
        // URP enum can't quietly select a different mode.
        private static void SetEnumByName(SerializedObject so, string path, string valueName)
        {
            SerializedProperty p = so.FindProperty(path);
            if (p == null || p.propertyType != SerializedPropertyType.Enum) return;

            int index = System.Array.IndexOf(p.enumNames, valueName);
            if (index < 0)
            {
                Debug.LogWarning($"[SceneBuilder] {path} has no value '{valueName}' - left at "
                    + p.enumNames[p.enumValueIndex] + ". Options: " + string.Join(", ", p.enumNames));
                return;
            }
            p.enumValueIndex = index;
        }

        private static void SetFloatIfPresent(SerializedObject so, string path, float value)
        {
            SerializedProperty p = so.FindProperty(path);
            if (p != null && p.propertyType == SerializedPropertyType.Float) p.floatValue = value;
        }

        private static void SetIfPresent(SerializedObject so, string path, bool value)
        {
            SerializedProperty p = so.FindProperty(path);
            if (p != null) p.boolValue = value;
        }

        private static void SetupLighting()
        {
            // Even, clinical-white lighting: carry almost all of it on flat ambient (which hits every
            // surface equally, including the ceiling, which a directional light never reaches) and
            // leave the directional as a weak, steeply-angled source purely for enough shading to
            // read geometry. A strong low-angle directional blew out one wall while the opposite
            // wall read grey.
            // Trilight, NOT Flat - and this is the single most important line in here.
            //
            // The room used to be lit by flat ambient at (0.95, 0.95, 0.97) with no lights in it
            // at all, so ambient was doing 100% of the lighting. That is exactly why it read as a
            // whitebox: flat ambient adds the *same* amount to every surface regardless of
            // orientation, distance or occlusion, so wall, ceiling and floor all came out
            // identical. No falloff, no direction, no contrast, nothing to read depth from.
            //
            // Real fixtures do the lighting now (BuildCeilingLights). Ambient is demoted to
            // standing in for the bounce URP isn't computing, and Trilight makes that stand-in
            // directional: it lights a surface by which way it faces. That maps straight onto the
            // problem downlights have - they hammer the floor and never touch the ceiling.
            //   ground  -> hits DOWNWARD faces, i.e. the ceiling. Highest of the three, standing in
            //             for light kicked back up off the bright floor.
            //   equator -> the walls.
            //   sky     -> hits UPWARD faces, i.e. the floor, which the spots already cover. Lowest,
            //             or the floor blows out to featureless white.
            // Expect the ground colour to bleed onto the walls too - that's spherical harmonics
            // doing what bounce would, and it's why the walls read lit rather than painted.
            //
            // Tuned by eye in play mode, 2026-08-10, over two passes. (The IMGUI panel that was
            // used to find these has since been deleted - the values are settled.)
            //
            // The fixtures came down (15 -> 9) and the floor band with them, but the walls went
            // back UP (0.644) after a pass at 0.138 - at that level the spots' falloff toward the
            // corners was reading as gloom rather than as shape, and the room lost the clinical
            // evenness it is supposed to have. So the shape of it is: floor lowest (0.155, the
            // spots already hammer it), walls and ceiling high and close together (0.644 / 0.719),
            // which is what a room lit by recessed panels and white paint actually looks like.
            // **AMBIENT IS BACK, AND ZERO WAS TRIED AND FAILED** (2026-08-25/26).
            //
            // A sealed windowless room physically HAS no ambient light: there is no sky, and every
            // photon leaves a ceiling panel. So once the bake worked and the bounce count was raised
            // to eight, this was taken to zero on exactly that argument.
            //
            // **It produced a black building.** Measured off play screenshots: walls at 4-8 out of
            // 255 - not dark, BLACK - with the floor still lit at 67 and the emissive fixtures at 255.
            // The floor is the one surface the downlights reach directly; everything else in this
            // building lives on bounce, and the bake does not deliver enough of it to stand alone.
            // The ceiling is the extreme case, with no direct light at all.
            //
            // Raising `CeilingLightIntensity` to 17 did not help and could not: it took the floor from
            // 39% to 65.7% of its pixels CLIPPED while the walls stayed black, because 2.4 times
            // almost nothing is still almost nothing.
            //
            // **So the constant stays, and it is still a fudge - just an honest one now.** The bake
            // carries the floor's share (this is why the sky band is 0.028 and not 0.155), and this
            // carries the walls and ceiling that the bake cannot reach. Why it cannot is a real open
            // question - probe validity against 25mm panels, reflection probes capturing an unlit
            // room, or simply four downlights not making much wall bounce in a 8.75 x 10.5m room -
            // and it is worth answering, but not while the game is unusable. `TODO.md`.
            ApplyEnvironment();

            // The default Directional Light is deleted, not dimmed. These rooms are sealed boxes
            // with a ceiling slab over them - a sun has no way in, so it contributed exactly
            // nothing while still costing a shadow pass. (It was even less use once the corner
            // seams and the door pocket were closed.)
            foreach (Light light in Object.FindObjectsByType<Light>(FindObjectsInactive.Exclude))
                if (light.type == LightType.Directional) Object.DestroyImmediate(light.gameObject);
        }

        // **THE PROBE VOLUME IS PART OF THE SCENE, SO THE BUILD OWNS IT** (2026-08-26).
        //
        // It used to be created by `BakeLighting` just before baking, and that quietly broke the
        // whole feature: `SceneBuilder.Build()` rebuilds a scene from nothing, so the next build
        // after a bake DELETED the volume and the `ProbeVolumePerSceneData` that Unity attaches
        // beside it. The baked cell data stayed on disk, tens of megabytes of it, with nothing in the
        // scene left to load it.
        //
        // **The workflow made it invisible.** Every run was build -> bake -> build, so the last step
        // always threw the result away. The bake logged success, the files were there, and the game
        // was lit entirely by the flat ambient constant - which is exactly what the measurements
        // showed and nobody could explain: `LightProbes.GetInterpolatedProbe` returned the SAME value
        // 30cm under the ceiling as 30cm above the floor (DC 0.3748 at every point in the room),
        // because it was reading the ambient probe rather than any baked field. A real irradiance
        // field cannot be constant in space.
        //
        // Sized off the renderers rather than written down, for the reason every size here is: the
        // cycles are different shapes, and a box written for one is wrong for the others.
        private const float ProbeVolumePadding = 4f;

        // `onlyCalibrationRoom` boxes JUST that room rather than everything in the scene. The core
        // scene is built with the entire building still in it - the cycles are moved out afterwards -
        // so measuring every renderer there gives a 48 x 52 x 193m box, **25.6 times the volume of a
        // cycle's**, for one 8.75 x 10.5m room. APV spreads a fixed cell budget over whatever box it
        // is given, so that room got a far coarser field than the identical rooms in the cycles, and
        // play saw it: Room1 read grey while the calibration room blew out to pure white, from one
        // global ambient value that cannot do both.
        private static void EnsureProbeVolume(Scene scene, bool onlyCalibrationRoom = false)
        {
            Bounds bounds = default;
            bool any = false;

            foreach (GameObject root in scene.GetRootGameObjects())
            {
                foreach (Renderer r in root.GetComponentsInChildren<Renderer>(true))
                {
                    // Particle systems report wandering bounds; only the built world should decide
                    // how big the lit volume is.
                    if (r is ParticleSystemRenderer) continue;
                    // The prefix test, not the exact one - the room is several siblings and the
                    // shell is only the first. See `LiftedWithCalibrationRoom`.
                    if (onlyCalibrationRoom && !LiftedWithCalibrationRoom(r.transform)) continue;
                    if (!any) { bounds = r.bounds; any = true; }
                    else bounds.Encapsulate(r.bounds);
                }
            }

            if (!any) return;

            const string volumeName = "AdaptiveProbeVolume";
            GameObject go = null;
            foreach (GameObject root in scene.GetRootGameObjects())
                if (root.name == volumeName) { go = root; break; }

            if (go == null)
            {
                go = new GameObject(volumeName);
                EditorSceneManager.MoveGameObjectToScene(go, scene);
            }

            ProbeVolume volume = go.GetComponent<ProbeVolume>();
            if (volume == null) volume = go.AddComponent<ProbeVolume>();

            go.transform.position = bounds.center;
            go.transform.rotation = Quaternion.identity;
            volume.mode = ProbeVolume.Mode.Local;
            volume.size = bounds.size + Vector3.one * (ProbeVolumePadding * 2f);

            EditorSceneManager.MarkSceneDirty(scene);
            Debug.Log($"[SceneBuilder] '{scene.name}': probe volume {volume.size} at {bounds.center}.");
        }

        // **THE LIGHTING ENVIRONMENT, AND IT HAS TO BE APPLIED TO EVERY SCENE SEPARATELY.**
        //
        // `RenderSettings` is PER SCENE. `SetupLighting` writes it while the core scene is open, and
        // `SplitCyclesIntoScenes` then makes each cycle with `NewScene(EmptyScene)` - which arrives
        // with Unity's DEFAULTS and no way to inherit anything. Nothing copied them across, so from
        // the day the cycles were split until 2026-08-26 **every tuned lighting value in this project
        // existed in `IterationRoom.unity` alone**, and Cycle1/2/3 ran on skybox ambient at
        // (0.212, 0.227, 0.259) that nobody chose.
        //
        // **It hid for months because it looks like lighting, not like a bug**, and it invalidated
        // every attempt to tune the room:
        //
        // - `m_DefaultReflectionMode` defaulted to Skybox in those scenes, so walls at smoothness
        //   0.85 were mirroring the PROCEDURAL SKY - a constant no ceiling light can move. That is
        //   the anomaly that finally gave it away: the menu render's floor tracked fixture intensity
        //   exactly (140 / 173 / 211 for 7 / 10.5 / 17) while the wall beside it did not move at all
        //   (115 / 117 / 122).
        // - Everything measured came out BLUE - B greater than G greater than R in every single
        //   sample, in a white room lit by white panels. That was the sky, and it was on screen the
        //   whole time.
        // - Setting ambient to zero blacked out the calibration room (which lives in the core scene
        //   and does get these values) while the cycle rooms carried on, which made the result look
        //   inconsistent and sent three separate diagnoses in the wrong direction.
        //
        // **Anything else added to the environment must go in HERE, not in `SetupLighting`.**
        private static void ApplyEnvironment()
        {
            RenderSettings.ambientMode = AmbientMode.Trilight;

            // **AMBIENT IS A FUDGE THIS BUILDING CANNOT DO WITHOUT, AND IT WAS TESTED TWICE.**
            //
            // A sealed windowless room physically has no ambient light: no sky, and every photon
            // leaves a ceiling panel. Zero was tried on that argument, gave a black building, and was
            // tried AGAIN after `ApplyEnvironment` fixed the three cycle scenes that had been running
            // on skybox ambient - because the first attempt had measured an inconsistency rather than
            // the idea. On the corrected baseline it still gives black walls and a black ceiling.
            //
            // **The measurement that settles it**: with ambient at zero the walls read 13 and the
            // ceiling 9 out of 255, against 149 and 169 with it on. Direct light from the fixtures
            // barely reaches a wall at all - the spots point DOWN, so the floor takes 100 and the
            // vertical surfaces get the tail of the cone - and eight bounces of that tail is not
            // enough to light a room. This constant is doing almost all of the wall and ceiling
            // lighting, and it has been all along.
            //
            // Raising the fixtures does not substitute for it either: 10.5 -> 17 took the floor from
            // 39% to 65.7% of its pixels CLIPPED while the walls stayed dark. The light is not
            // missing, it is pointing somewhere else.
            //
            // **If this is ever to go, the fixtures have to stop being downlights** - a source that
            // actually faces the walls, or an emissive panel that contributes to the bake (these are
            // `RealtimeEmissive`, so their glow lights nothing). `TODO.md`.
            // **HALVED AGAIN 2026-08-26, THE MOMENT THE BAKE STARTED ACTUALLY APPLYING.**
            //
            // Until the probe volume survived a rebuild (see `EnsureProbeVolume`) the baked bounce
            // reached nothing, and these numbers were tuned to carry the whole room by themselves.
            // Now the bounce arrives as well and the two are ADDED, which showed up first on the
            // things that take all their light from probes: play reported the bed as blown out, and
            // it measured 255,255,255 across its whole frame - 100% clipped - with the sheet at 92%
            // while the walls beside it sat at 100 and were called too dark.
            //
            // Static surfaces and dynamic objects were being lit by different amounts of the same
            // double count, so no single brightness fixed both. Taking ambient down is what removes
            // the duplication rather than trading one complaint for the other.
            //
            // Was 0.028 / 0.659 / 0.843, itself already halved from the pre-bake 0.155 / 0.644 /
            // 0.719. **If the room now reads flat rather than dim, this is still too high** - the
            // whole point is for the bake to be what lights the walls.
            // **FOUND ON THE DIAL, 2026-08-26, IN TWO PASSES - AND THE SECOND PASS IS THE IMPORTANT
            // ONE.** The first got the room properly white (0.036 / 0.836 / 0.729) and play's verdict
            // was that it HURT TO LOOK AT. These are the numbers that came back from making it
            // comfortable instead of maximally white.
            //
            // The shape of that second correction: the FLOOR band came up tenfold (0.036 -> 0.356)
            // while the ceiling came down (0.729 -> 0.521) and the walls eased slightly. The three
            // bands are now much closer together, which is the whole point - the eye reads a room by
            // the RATIOS between its surfaces, and pushing every one of them toward white removes the
            // ratios and leaves a glare.
            //
            // **The lesson for anyone retuning this: brightness is not the target, comfort is.** Two
            // days went into trying to replace this constant with something physically derived - baked
            // bounce, then wall washers - and both failed on the same point. They add brightness where
            // light already is; what this room wants is EVENNESS, at a level that can be looked at.
            // That is an eye's judgement and it was only ever going to be found by looking.
            RenderSettings.ambientSkyColor     = new Color(0.356f, 0.356f, 0.361f);
            RenderSettings.ambientEquatorColor = new Color(0.763f, 0.763f, 0.768f);
            RenderSettings.ambientGroundColor  = new Color(0.521f, 0.521f, 0.528f);
            RenderSettings.ambientIntensity = 1f;
            // Assigning the colours does NOT rebuild the ambient probe. Without this they are
            // stored and never reach a shader, and every tweak looks like it did nothing.
            DynamicGI.UpdateEnvironment();

            // Reflections come from per-room probes that see the actual white room. **This being
            // left at Unity's default in the cycle scenes is what painted the sky onto the walls**,
            // so it is set here rather than assumed.
            RenderSettings.defaultReflectionMode = DefaultReflectionMode.Skybox;
            RenderSettings.reflectionIntensity = 1f;
        }

        // Recessed ceiling fixtures - the actual light in the room.
        //
        // Spots rather than points, aimed straight down, because a downlight's cone is what gives
        // the floor bright pools and lets the walls fall off toward the corners. That gradient is
        // most of what separates a room from a whitebox; a point light just washes everything.
        //
        // castShadows is TRUE for every room now, and the flag is kept rather than removed: it is the
        // per-room switch for the one thing here that costs real frames, so a room that turns out to
        // be too heavy can opt out without touching the mechanism. It was off everywhere but Room1
        // until 2026-08-24 - see the shadow block below for what that did to the player's own shadow.
        // xCenter is 0 for every room in the north-south chain and non-zero only for Room2's two side
        // rooms, which sit off that axis.
        //
        // Returns the four Lights AND the four emissive panels they sit in, because one room's
        // fixtures are now something a puzzle drives: Room2West starts dark and comes up when its
        // board is finished. The panels come back too because dimming the lights alone leaves four
        // bright ceiling tiles lighting nothing, which reads as broken rather than as off.
        private static (Light[] lights, Renderer[] panels) BuildCeilingLights(Transform parent, string roomName, float zCenter, Material emissiveMat, bool castShadows, float xCenter = 0f)
        {
            GameObject root = new GameObject(roomName + "_CeilingLights");
            root.transform.SetParent(parent, false);

            var built = new System.Collections.Generic.List<Light>();
            var panels = new System.Collections.Generic.List<Renderer>();

            // Two columns on the wall-panel rhythm, two rows down the room's length.
            float[] xs = { xCenter - GridCellWidth, xCenter + GridCellWidth };
            float[] zs = { zCenter - 2.6f, zCenter + 2.6f };

            const float panelSize = 1.4f;
            const float panelThickness = 0.04f;

            int index = 0;
            foreach (float x in xs)
            {
                foreach (float z in zs)
                {
                    GameObject fixture = new GameObject($"Fixture_{index++}");
                    fixture.transform.SetParent(root.transform, false);
                    fixture.transform.localPosition = new Vector3(x, RoomHeight, z);

                    // Sits just under the ceiling plane so it reads as set into it. Emission is
                    // pushed well past 1.0 so it clears the deliberately high bloom threshold.
                    GameObject panel = Prim(PrimitiveType.Cube, "Panel", fixture.transform,
                        new Vector3(0f, -panelThickness / 2f, 0f),
                        new Vector3(panelSize, panelThickness, panelSize),
                        emissiveMat, removeCollider: true);
                    panels.Add(panel.GetComponent<Renderer>());

                    GameObject lightGO = new GameObject("Light");
                    lightGO.transform.SetParent(fixture.transform, false);
                    lightGO.transform.localPosition = new Vector3(0f, -panelThickness, 0f);
                    lightGO.transform.localRotation = Quaternion.Euler(90f, 0f, 0f);

                    Light light = lightGO.AddComponent<Light>();
                    light.type = LightType.Spot;
                    // Wide and soft-edged, so it behaves like a panel rather than a torch.
                    light.spotAngle = CeilingSpotAngle;
                    light.innerSpotAngle = 45f;
                    light.range = 11f;
                    // Found by eye against Neutral tonemapping, in play mode.
                    // A 130-degree cone from over 5m up spreads its energy over most of the room,
                    // so this reads lower than it is: at 4 the room came out a dim grey.
                    //
                    // History, because it has moved three times for three different reasons: 11
                    // with six fixtures, 15 when the count dropped to four, 9 once the ambient fill
                    // was cut back (the fill had been doing more of the lighting than it looked),
                    // and now 10.5 because the golden-ratio grid raised the ceiling.
                    //
                    // That last one is DERIVED, not tuned: the fixtures moved from 5.0m to 5.408m,
                    // and 9 * (5.408/5.0)^2 = 10.5 holds the floor at the brightness that was
                    // signed off at the lower ceiling. Inverse square is an approximation here -
                    // the cone also spreads wider from higher up - so treat it as a starting point
                    // and check it by eye.
                    light.intensity = CeilingLightIntensity;
                    // Barely off white - clinical rather than domestic, without tinting the room.
                    light.color = new Color(0.99f, 0.99f, 1f);
                    // **ALL FOUR CAST** (2026-08-24, after play called the player's shadow detached -
                    // "not something coming off my body"). It was ONE per room before, and that is
                    // what the complaint was: one caster is one shadow pointing one way, and this
                    // grid's first fixture is a CORNER of it, so a player at the room's centre was
                    // lit for shadow purposes from 3.13m to one side and threw a 1.8m body into a
                    // shadow whose head landed a metre away - while the room LOOKS evenly lit from
                    // four panels overhead. A shadow at that angle reads as a separate object lying
                    // on the floor beside you.
                    //
                    // **THE CUE THAT WAS MISSING IS A CONTACT SHADOW, AND ONLY SEVERAL LIGHTS MAKE
                    // ONE.** With four, each fixture carries about a quarter of the light: directly
                    // under the feet all four are blocked and it goes properly dark, while each
                    // single radiating shadow loses only its own quarter and stays faint. Dark at the
                    // feet fading outward is what the eye reads as "this is standing here" - a
                    // better-aimed single shadow cannot produce it at all.
                    //
                    // The old reasoning here was that four overlapping shadows "read as a smear, not
                    // as a figure". That is true of four EQUALLY dark ones; the gradient is the point.
                    //
                    // **0.45, DOWN FROM 0.75** (2026-08-25, after play: four scattered shadows under a
                    // held object read as wrong). They are in the RIGHT PLACE - a point light at
                    // (+-1.75, 5.41, +-2.6) throws an object held at 1.3m onto the floor 0.99m from
                    // its own footprint, so the four sit on a 1.11 x 1.65m rectangle, which is exactly
                    // what the screen shows. What is wrong is the EDGE: these stand in for 1.4m
                    // emissive panels, and a real source that size would blur each shadow over 0.44m
                    // at that height - half their separation - so the four would melt into one soft
                    // pool. A point light gives four crisp copies instead, and URP has no realtime
                    // area light to fix that with.
                    //
                    // So the lever is CONTRAST, not geometry. Each fixture carries about a quarter of
                    // the light, so one shadow alone removes strength/4: at 0.75 that was 19% and read
                    // as a distinct copy, at 0.45 it is 11% and reads as a smudge. Under the object
                    // all four still stack to 45%, which is the contact cue this is really for. The other half of the old argument -
                    // that four casters a room is a budget nobody has - was written for the WebGL
                    // build. The target is Steam, and six shadowed fixtures is a configuration this
                    // project has already shipped (see the atlas note in `ConfigureUrpAsset`).
                    //
                    // Cost is bounded by CULLING, not by room count: a light outside the frustum is
                    // not in `visibleLights` and costs nothing, so this is four casters in the room
                    // you are standing in and up to eight seen through an open door - never fourteen
                    // rooms' worth.
                    // **MIXED, SO THE BOUNCE CAN BE BAKED WITHOUT GIVING UP THE DIRECT LIGHT**
                    // (2026-08-25). Left at the default Realtime these contribute NOTHING to a GI
                    // bake - the bake log said so in as many words, "0 lights" - so a building lit
                    // entirely by them bakes pitch black indirect and the whole exercise is wasted.
                    //
                    // Mixed rather than Baked because the direct half has to stay live: `ShadowBudget`
                    // switches these fixtures' shadows on and off as the player moves, and a fully
                    // baked light has no runtime shadow to switch. Mixed keeps the direct light and
                    // its shadow realtime and bakes only what bounces, which is exactly the split
                    // this room wants.
                    light.lightmapBakeType = LightmapBakeType.Mixed;
                    light.shadows = castShadows ? LightShadows.Soft : LightShadows.None;
                    light.shadowStrength = 0.45f;
                    light.renderMode = LightRenderMode.ForcePixel;
                    built.Add(light);
                }
            }

            return (built.ToArray(), panels.ToArray());
        }

        // Surface detail, generated rather than sourced, so the project stays reproducible from
        // scripts like everything else here.
        //
        // The room's walls and slabs are perfectly uniform flat colour, which is the other half of
        // why it read as a whitebox: real lights now sweep across them, but there is no micro-relief
        // for that light to catch, so every surface still shades as one continuous gradient. A fine
        // normal map gives the light something to break up on - the difference between "painted
        // white" and "a painted white wall".
        //
        // Multi-octave value noise, made *tileable* by wrapping the lattice at each octave's period
        // (see Hash). Mathf.PerlinNoise is not tileable and would seam at every repeat.
        // The picture every wall panel shows once it fails: seven colour bars with a dark band
        // under them carrying the word ERROR.
        //
        // A TEST CARD rather than a warning sign, and that is the whole idea. A sign is something a
        // room PUTS UP, and a facility still capable of putting a sign up has not failed. This is
        // the image a display shows when it has nothing left to show - so a room built entirely out
        // of displays does not report the fault, it becomes it.
        //
        // 126 x 100 for seven exact 18px bars, uncompressed and point-filtered: block colour with
        // hard edges is precisely what DXT smears, and a soft test card is a poster of one.
        private static Texture2D MakeTestCardTexture(string name)
        {
            const int w = 126, h = 100;
            const int bandHeight = 30;          // the dark strip along the bottom
            const int bars = 7;

            // The broadcast order, brightest to darkest by luma - which is what makes a row of them
            // read as a test card rather than as a row of coloured squares.
            Color[] bar =
            {
                Color.white,
                new Color(1f, 1f, 0f),
                new Color(0f, 1f, 1f),
                new Color(0f, 1f, 0f),
                new Color(1f, 0f, 1f),
                new Color(1f, 0f, 0f),
                new Color(0f, 0f, 1f),
            };

            Color band = new Color(0.04f, 0.04f, 0.045f);   // GrooveDark, like every dark plate here
            Color ink = new Color(1f, 0.13f, 0.11f);        // and the same red as every display

            Color[] px = new Color[w * h];
            for (int y = 0; y < h; y++)
            {
                for (int x = 0; x < w; x++)
                {
                    px[y * w + x] = y < bandHeight
                        ? band
                        : bar[Mathf.Clamp(x * bars / w, 0, bars - 1)];
                }
            }

            // ERROR, drawn from a 5x7 bitmap because there is no font rasteriser to hand when the
            // target is a Texture2D. Three glyphs is all five letters need.
            const int glyphScale = 3;
            int textWidth = (5 * 5 + 4) * glyphScale;       // five glyphs, four one-pixel gaps
            int originX = (w - textWidth) / 2;
            int originY = (bandHeight - 7 * glyphScale) / 2;
            string word = "ERROR";
            for (int c = 0; c < word.Length; c++)
                BlitGlyph(px, w, h, word[c], originX + c * 6 * glyphScale, originY, glyphScale, ink);

            return WriteTexture(name, w, h, px, TextureWrapMode.Repeat, FilterMode.Point);
        }

        // Rows top-to-bottom, so a glyph reads the right way up when it is written into a texture
        // whose y = 0 is the BOTTOM.
        private static void BlitGlyph(Color[] px, int w, int h, char c, int x0, int y0, int scale, Color ink)
        {
            string[] rows;
            switch (c)
            {
                case 'E': rows = new[] { "11111", "10000", "10000", "11110", "10000", "10000", "11111" }; break;
                case 'R': rows = new[] { "11110", "10001", "10001", "11110", "10100", "10010", "10001" }; break;
                case 'O': rows = new[] { "01110", "10001", "10001", "10001", "10001", "10001", "01110" }; break;
                default: return;
            }

            for (int row = 0; row < rows.Length; row++)
            {
                for (int col = 0; col < 5; col++)
                {
                    if (rows[row][col] != '1') continue;
                    for (int sy = 0; sy < scale; sy++)
                    {
                        for (int sx = 0; sx < scale; sx++)
                        {
                            int x = x0 + col * scale + sx;
                            int y = y0 + (rows.Length - 1 - row) * scale + sy;
                            if (x < 0 || x >= w || y < 0 || y >= h) continue;
                            px[y * w + x] = ink;
                        }
                    }
                }
            }
        }

        // Monochrome grain, tiled several times across a panel and scrolled a whole texture at a
        // time between frames. Deterministic through System.Random rather than UnityEngine.Random,
        // which BuildOnsets depends on being left alone.
        private static Texture2D MakeStaticTexture(string name, int size)
        {
            var rng = new System.Random(20260812);
            Color[] px = new Color[size * size];
            for (int i = 0; i < px.Length; i++)
            {
                // Weighted toward the dark end. Even static is mostly black - an even spread comes
                // out as flat grey at any distance and stops reading as noise at all.
                float v = (float)rng.NextDouble();
                v *= v;
                px[i] = new Color(v, v, v);
            }

            return WriteTexture(name, size, size, px, TextureWrapMode.Repeat, FilterMode.Point);
        }

        private static Texture2D WriteTexture(string name, int w, int h, Color[] pixels,
                                              TextureWrapMode wrap, FilterMode filter)
        {
            string path = $"{TexturesDir}/{name}.png";

            Texture2D tex = new Texture2D(w, h, TextureFormat.RGBA32, false);
            tex.SetPixels(pixels);
            tex.Apply();

            Directory.CreateDirectory(TexturesDir);
            File.WriteAllBytes(path, tex.EncodeToPNG());
            Object.DestroyImmediate(tex);

            AssetDatabase.ImportAsset(path, ImportAssetOptions.ForceUpdate);
            TextureImporter importer = AssetImporter.GetAtPath(path) as TextureImporter;
            if (importer != null)
            {
                importer.textureType = TextureImporterType.Default;
                importer.sRGBTexture = true;
                importer.wrapMode = wrap;
                importer.filterMode = filter;
                // NPOT sizes are rescaled to the nearest power of two by default, which would turn
                // 126 x 100 into 128 x 128 and put the seven exact bars back on fractional pixels.
                importer.npotScale = TextureImporterNPOTScale.None;
                // Block colour with hard edges is the worst case for DXT, and this is nothing else.
                importer.textureCompression = TextureImporterCompression.Uncompressed;
                importer.SaveAndReimport();
            }

            return AssetDatabase.LoadAssetAtPath<Texture2D>(path);
        }

        // HOW SHINY THE SURFACE IS, VARYING ACROSS IT - the other half of what the normal map does.
        //
        // **PERFECTLY UNIFORM ROUGHNESS IS ONE OF THE STRONGEST TELLS THAT SOMETHING IS RENDERED.**
        // `ApplySurfaceDetail` gives the walls a normal map, so light already breaks up on the
        // micro-relief - but it also hands them ONE smoothness number, so every square metre of the
        // building reflects exactly as sharply as every other. Real paint does not: it is duller
        // where it has been touched, cleaned, or run down a wall, and the eye reads that unevenness
        // long before it can name it.
        //
        // **LOW FREQUENCY ON PURPOSE, and that is the whole difference between this and the normal
        // map.** That one wants near-pixel grain, because it is standing in for plaster texture. This
        // wants broad soft patches the size of a hand or a body, because it is standing in for wear -
        // fine noise in roughness reads as sparkle, which is the opposite of the intent.
        //
        // **IT ONLY EVER DULLS.** URP multiplies (`specGloss.a *= _Smoothness` in LitInput.hlsl), so
        // the alpha here is a fraction of the material's authored smoothness and 1.0 means "as
        // authored". Nothing can come out glossier than the number somebody chose, which keeps this a
        // detail pass rather than a second place the surface is defined.
        //
        // R CARRIES METALLIC, because the same texture supplies both and a zero red channel would
        // silently un-metal anything this is applied to. Read off the material rather than assumed.
        private static Texture2D MakeSmoothnessMap(string name, int size, float metallic, float floor)
        {
            string path = $"{TexturesDir}/{name}.png";

            float[] wear = new float[size * size];
            // Two coarse octaves only - 4 and 12 periods across the tile. The normal map's finest is
            // 64; going anywhere near that here is what turns wear into glitter.
            AddNoiseOctave(wear, size, 4, 0.65f, 4801);
            AddNoiseOctave(wear, size, 12, 0.35f, 5779);

            float min = float.MaxValue, max = float.MinValue;
            foreach (float v in wear) { if (v < min) min = v; if (v > max) max = v; }
            float span = Mathf.Max(0.0001f, max - min);

            Color[] pixels = new Color[size * size];
            for (int i = 0; i < pixels.Length; i++)
            {
                // Normalised to the noise's ACTUAL range rather than an assumed one, so `floor` means
                // the same depth of dulling whatever the octave weights above are changed to.
                float t = (wear[i] - min) / span;
                pixels[i] = new Color(metallic, 0f, 0f, Mathf.Lerp(floor, 1f, t));
            }

            Texture2D tex = new Texture2D(size, size, TextureFormat.RGBA32, false, true);
            tex.SetPixels(pixels);
            tex.Apply();

            Directory.CreateDirectory(TexturesDir);
            File.WriteAllBytes(path, tex.EncodeToPNG());
            Object.DestroyImmediate(tex);

            AssetDatabase.ImportAsset(path, ImportAssetOptions.ForceUpdate);
            TextureImporter importer = AssetImporter.GetAtPath(path) as TextureImporter;
            if (importer != null)
            {
                importer.textureType = TextureImporterType.Default;
                // **sRGB OFF.** This is data, not a picture - a gamma curve applied to a roughness
                // value is a different roughness. The same reason the normal map is created with
                // `linear: true`.
                importer.sRGBTexture = false;
                // **AND ALPHA MUST SURVIVE THE IMPORT.** The smoothness lives in it, and Unity will
                // happily compress a texture whose alpha it thinks is unused.
                importer.alphaSource = TextureImporterAlphaSource.FromInput;
                importer.alphaIsTransparency = false;
                // **AND IT MUST NOT BE BLOCK-COMPRESSED.** DXT5 stores alpha in 4x4 blocks, and the
                // smoothness lives in alpha - so a smooth low-frequency field gets quantised per
                // block and the walls come out wearing a faint grid of small squares, visible across
                // a room. Reported from play as "연한 회색 사각형들", 2026-08-25.
                //
                // Same rule the HUD icons already carry for the same reason ("block compression
                // frays something that is nothing but alpha"), which this map did not inherit
                // because it goes through a different importer path. **A DATA texture is not a
                // picture: it gets no gamma curve and no block compression.**
                importer.textureCompression = TextureImporterCompression.Uncompressed;
                importer.wrapMode = TextureWrapMode.Repeat;
                importer.anisoLevel = 4;
                importer.SaveAndReimport();
            }

            return AssetDatabase.LoadAssetAtPath<Texture2D>(path);
        }

        private static Texture2D MakeNoiseNormalMap(string name, int size, float bumpStrength)
        {
            string path = $"{TexturesDir}/{name}.png";

            float[] height = new float[size * size];
            // Coarsest octave is a broad undulation like a skimmed wall; finest is near-pixel grain.
            int[] periods = { 8, 16, 32, 64 };
            float[] weights = { 0.5f, 0.28f, 0.15f, 0.07f };
            for (int o = 0; o < periods.Length; o++)
                AddNoiseOctave(height, size, periods[o], weights[o], 1000 + o * 977);

            Color[] pixels = new Color[size * size];
            for (int y = 0; y < size; y++)
            {
                for (int x = 0; x < size; x++)
                {
                    // Central differences, wrapped, so the derived normals tile with the heights.
                    float dx = height[WrapIndex(x - 1, y, size)] - height[WrapIndex(x + 1, y, size)];
                    float dy = height[WrapIndex(x, y - 1, size)] - height[WrapIndex(x, y + 1, size)];
                    Vector3 n = new Vector3(dx * bumpStrength, dy * bumpStrength, 1f).normalized;
                    pixels[y * size + x] = new Color(n.x * 0.5f + 0.5f, n.y * 0.5f + 0.5f, n.z * 0.5f + 0.5f, 1f);
                }
            }

            Texture2D tex = new Texture2D(size, size, TextureFormat.RGBA32, false, true);
            tex.SetPixels(pixels);
            tex.Apply();

            Directory.CreateDirectory(TexturesDir);
            File.WriteAllBytes(path, tex.EncodeToPNG());
            Object.DestroyImmediate(tex);

            AssetDatabase.ImportAsset(path, ImportAssetOptions.ForceUpdate);
            TextureImporter importer = AssetImporter.GetAtPath(path) as TextureImporter;
            if (importer != null)
            {
                // Without NormalMap the PNG imports as a colour texture and the shader reads the
                // raw RGB as a normal, which tilts every surface toward +X/+Y.
                importer.textureType = TextureImporterType.NormalMap;
                importer.wrapMode = TextureWrapMode.Repeat;
                importer.anisoLevel = 4;
                importer.SaveAndReimport();
            }

            return AssetDatabase.LoadAssetAtPath<Texture2D>(path);
        }

        private static void AddNoiseOctave(float[] height, int size, int period, float weight, int seed)
        {
            float cell = (float)size / period;
            for (int y = 0; y < size; y++)
            {
                for (int x = 0; x < size; x++)
                {
                    float fx = x / cell, fy = y / cell;
                    int x0 = Mathf.FloorToInt(fx), y0 = Mathf.FloorToInt(fy);
                    float tx = SmoothStep(fx - x0), ty = SmoothStep(fy - y0);

                    float bottom = Mathf.Lerp(LatticeHash(x0, y0, period, seed), LatticeHash(x0 + 1, y0, period, seed), tx);
                    float top = Mathf.Lerp(LatticeHash(x0, y0 + 1, period, seed), LatticeHash(x0 + 1, y0 + 1, period, seed), tx);
                    height[y * size + x] += Mathf.Lerp(bottom, top, ty) * weight;
                }
            }
        }

        private static float SmoothStep(float t) => t * t * (3f - 2f * t);

        private static int WrapIndex(int x, int y, int size)
        {
            x = ((x % size) + size) % size;
            y = ((y % size) + size) % size;
            return y * size + x;
        }

        // The lattice coordinate wraps at `period`, which is precisely what makes each octave -
        // and therefore the whole map - tile seamlessly.
        private static float LatticeHash(int x, int y, int period, int seed)
        {
            x = ((x % period) + period) % period;
            y = ((y % period) + period) % period;
            unchecked
            {
                int h = x * 374761393 + y * 668265263 + seed * 1274126177;
                h = (h ^ (h >> 13)) * 1274126177;
                return ((h ^ (h >> 16)) & 0x7fffffff) / (float)0x7fffffff;
            }
        }

        // A tiny software rasteriser for the HUD's glyphs. They are drawn from code for the same
        // reason the wall grain and the narration are: everything here has to rebuild from a
        // script, and a folder of sourced PNGs was exactly the part that could not.
        //
        // Shapes are predicates over a 0..1 square with the origin bottom-left, matching Unity's
        // texture coordinates so a row index needs no flipping. Coverage is supersampled 4x4, which
        // is the whole reason a 128px disc has a clean edge rather than a staircase.
        private sealed class IconCanvas
        {
            private const int Supersample = 4;

            private readonly int size;
            private readonly float[] coverage;

            public IconCanvas(int size)
            {
                this.size = size;
                coverage = new float[size * size];
            }

            // sign -1 cuts back out of what is already drawn - the hole in a key's bow, the hollow
            // inside the mouse outline. Predicates compose, so an intersection is just &&.
            public void Shape(System.Func<Vector2, bool> inside, float sign = 1f)
            {
                float step = 1f / (size * Supersample);
                const float samples = Supersample * Supersample;

                for (int y = 0; y < size; y++)
                {
                    for (int x = 0; x < size; x++)
                    {
                        float hits = 0f;
                        for (int sy = 0; sy < Supersample; sy++)
                            for (int sx = 0; sx < Supersample; sx++)
                            {
                                Vector2 p = new Vector2(
                                    (x * Supersample + sx + 0.5f) * step,
                                    (y * Supersample + sy + 0.5f) * step);
                                if (inside(p)) hits++;
                            }

                        if (hits == 0f) continue;
                        int i = y * size + x;
                        coverage[i] = Mathf.Clamp01(coverage[i] + sign * (hits / samples));
                    }
                }
            }

            public void Disc(Vector2 centre, float radius, float sign = 1f) =>
                Shape(p => (p - centre).sqrMagnitude <= radius * radius, sign);

            // A THICK LINE WITH ROUND ENDS - the distance from a point to a segment, thresholded.
            // Everything curved in these icons used to be a stack of overlapping `Bar`s stepped along
            // the shape, which is why the axe read as a hammer and the question mark as a broken ring:
            // a staircase of rectangles has corners the eye finds before it finds the curve. One
            // swept disc has none.
            public void Capsule(Vector2 a, Vector2 b, float radius, float sign = 1f)
            {
                Vector2 ab = b - a;
                float lenSqr = Mathf.Max(1e-6f, ab.sqrMagnitude);
                Shape(p =>
                {
                    float t = Mathf.Clamp01(Vector2.Dot(p - a, ab) / lenSqr);
                    return (p - (a + ab * t)).sqrMagnitude <= radius * radius;
                }, sign);
            }

            // A STROKED ARC, as a chain of capsules. Enough segments that the joins disappear at the
            // 128px these are authored at; fewer and the curve polygonises again.
            public void Arc(Vector2 centre, float radius, float fromDegrees, float toDegrees,
                            float thickness, float sign = 1f)
            {
                const int steps = 28;
                Vector2 previous = Vector2.zero;
                for (int i = 0; i <= steps; i++)
                {
                    float a = Mathf.Deg2Rad * Mathf.Lerp(fromDegrees, toDegrees, i / (float)steps);
                    Vector2 at = centre + new Vector2(Mathf.Cos(a), Mathf.Sin(a)) * radius;
                    if (i > 0) Capsule(previous, at, thickness, sign);
                    previous = at;
                }
            }

            public void Ring(Vector2 centre, float outer, float inner, float sign = 1f) =>
                Shape(p =>
                {
                    float sqr = (p - centre).sqrMagnitude;
                    return sqr <= outer * outer && sqr >= inner * inner;
                }, sign);

            // Described by centre, half extents and an angle rather than by four corners, so the
            // needle and its handle can share one diagonal.
            public void Bar(Vector2 centre, Vector2 halfExtents, float degrees = 0f, float sign = 1f)
            {
                float rad = -degrees * Mathf.Deg2Rad;
                float cos = Mathf.Cos(rad), sin = Mathf.Sin(rad);

                Shape(p =>
                {
                    Vector2 d = p - centre;
                    // Un-rotate the sample rather than rotating the rectangle: an axis-aligned
                    // containment test is the only one that stays trivially correct.
                    Vector2 local = new Vector2(d.x * cos - d.y * sin, d.x * sin + d.y * cos);
                    return Mathf.Abs(local.x) <= halfExtents.x && Mathf.Abs(local.y) <= halfExtents.y;
                }, sign);
            }

            // The same glyph as an OPAQUE picture, for the ones that go on an object in the world
            // rather than in the HUD. Alpha is not an option there: a lit surface with the shape in
            // its alpha is a white card, because nothing in this project reads alpha off an opaque
            // material. The coverage becomes ink over paper instead.
            public Texture2D ToOpaqueTexture(string name, Color paper, Color ink)
            {
                Texture2D tex = new Texture2D(size, size, TextureFormat.RGBA32, false) { name = name };
                Color[] pixels = new Color[size * size];
                for (int i = 0; i < pixels.Length; i++) pixels[i] = Color.Lerp(paper, ink, coverage[i]);
                tex.SetPixels(pixels);
                tex.Apply();
                return tex;
            }

            // White, with the whole shape carried in alpha: the HUD tints these through
            // Image.color, and a glyph with baked-in colour could not be recoloured to match.
            public Texture2D ToTexture(string name)
            {
                Texture2D tex = new Texture2D(size, size, TextureFormat.RGBA32, false) { name = name };
                Color[] pixels = new Color[size * size];
                for (int i = 0; i < pixels.Length; i++) pixels[i] = new Color(1f, 1f, 1f, coverage[i]);
                tex.SetPixels(pixels);
                tex.Apply();
                return tex;
            }
        }

        // The same glyph as a world texture: opaque, mipmapped, and imported as a plain texture
        // rather than a sprite. Mipmaps matter here where they do not in the HUD - these are read at
        // four metres across a room, and an unmipped glyph at that distance is a shimmering mess.
        private static Texture2D SaveSymbolTexture(IconCanvas canvas, string name)
            => SaveSymbolTexture(canvas, name, SymbolPaper, SymbolInk);

        // The same, with the two values named rather than assumed. The cube room's inclusion wants
        // them INVERTED - a near-black core carrying a pale glyph - because it is read through glass
        // in a white room, where ink-on-paper is a white card inside a white cube seen against a
        // white wall. Which of the two is the glyph never changes; only which one is bright does.
        private static Texture2D SaveSymbolTexture(IconCanvas canvas, string name, Color paper, Color ink)
        {
            if (!Directory.Exists(SymbolsDir)) Directory.CreateDirectory(SymbolsDir);

            string path = $"{SymbolsDir}/{name}.png";
            Texture2D tex = canvas.ToOpaqueTexture(name, paper, ink);
            File.WriteAllBytes(path, tex.EncodeToPNG());
            Object.DestroyImmediate(tex);

            AssetDatabase.ImportAsset(path, ImportAssetOptions.ForceUpdate);

            if (AssetImporter.GetAtPath(path) is TextureImporter importer)
            {
                importer.textureType = TextureImporterType.Default;
                importer.alphaIsTransparency = false;
                importer.mipmapEnabled = true;
                importer.wrapMode = TextureWrapMode.Clamp;
                importer.filterMode = FilterMode.Bilinear;
                importer.textureCompression = TextureImporterCompression.Uncompressed;
                importer.SaveAndReimport();
            }

            return AssetDatabase.LoadAssetAtPath<Texture2D>(path);
        }

        // A lit material with a picture on it, which is the first one in this building - every other
        // surface here is a flat colour. `_BaseMap` AND `mainTexture` are both set because URP reads
        // the first and a good deal of Unity's own tooling still reads the second.
        private static Material MakeSymbolMaterial(string name, Texture2D map)
        {
            string path = $"{MaterialsDir}/{name}.mat";
            Material mat = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (mat == null)
            {
                mat = new Material(OpaqueShader());
                AssetDatabase.CreateAsset(mat, path);
            }

            mat.shader = OpaqueShader();
            mat.color = Color.white;
            mat.SetTexture("_BaseMap", map);
            mat.mainTexture = map;
            // Matte. A glyph is being read, and a specular highlight across it is the one thing that
            // stops it being readable from an angle.
            SetSmoothness(mat, 0.08f);
            EditorUtility.SetDirty(mat);
            return mat;
        }

        private static Sprite SaveSprite(IconCanvas canvas, string name)
        {
            string path = $"{IconsDir}/{name}.png";
            Texture2D tex = canvas.ToTexture(name);
            File.WriteAllBytes(path, tex.EncodeToPNG());
            Object.DestroyImmediate(tex);

            AssetDatabase.ImportAsset(path, ImportAssetOptions.ForceUpdate);

            if (AssetImporter.GetAtPath(path) is TextureImporter importer)
            {
                importer.textureType = TextureImporterType.Sprite;
                importer.spriteImportMode = SpriteImportMode.Single;
                importer.alphaIsTransparency = true;
                importer.mipmapEnabled = false;
                importer.filterMode = FilterMode.Bilinear;
                importer.wrapMode = TextureWrapMode.Clamp;
                // Uncompressed: these are a few KB each, and block compression frays the edge of a
                // glyph that is nothing but alpha.
                importer.textureCompression = TextureImporterCompression.Uncompressed;
                importer.SaveAndReimport();
            }

            return AssetDatabase.LoadAssetAtPath<Sprite>(path);
        }

        // The pin, as a silhouette: a stubby grip and a long needle on one diagonal. Drawn on the
        // diagonal rather than upright because upright it reads as a nail, and because a HUD slot
        // is square - a diagonal uses the corners.
        // A pail seen side on: a tapered body with a handle over it. Drawn rather than rendered, like
        // every other icon here.
        // A RUBBER DUCK IN SILHOUETTE. Body, head, bill, and a notch bitten out for the eye - a duck
        // is one of the few shapes that survives being reduced to an outline, which is exactly why it
        // is the object a pictogram can name without a caption.
        private static Sprite DuckIcon()
        {
            var icon = new IconCanvas(128);
            Vector2 mid = new Vector2(0.5f, 0.46f);

            // The body: a big disc with a tail bar, which reads as a duck sitting on water.
            icon.Disc(mid + new Vector2(-0.02f, -0.06f), 0.235f);
            icon.Bar(mid + new Vector2(-0.245f, 0.010f), new Vector2(0.090f, 0.055f), 22f);

            // Head and neck.
            icon.Disc(mid + new Vector2(0.150f, 0.195f), 0.135f);
            icon.Bar(mid + new Vector2(0.115f, 0.075f), new Vector2(0.075f, 0.100f), 0f);

            // The bill, forward and slightly down.
            icon.Bar(mid + new Vector2(0.305f, 0.170f), new Vector2(0.090f, 0.042f), -8f);

            // The eye, cut back OUT of the head - a hole reads at icon size where a dot does not.
            icon.Disc(mid + new Vector2(0.170f, 0.235f), 0.038f, -1f);
            return SaveSprite(icon, "icon_duck");
        }

        // A BEACH BALL: a disc with two curved panel seams. The seams are the whole of it - without
        // them this is a circle, and a circle in a row of objects reads as "any ball" or as a full
        // stop.
        private static Sprite BeachBallIcon()
        {
            var icon = new IconCanvas(128);
            Vector2 mid = new Vector2(0.5f, 0.5f);

            icon.Disc(mid, 0.330f);
            // Two seams, cut out rather than drawn on, each built from short bars stepped across the
            // face so they bow like meridians on a sphere.
            for (int side = -1; side <= 1; side += 2)
            {
                for (int i = -5; i <= 5; i++)
                {
                    float t = i / 5f;
                    float y = t * 0.300f;
                    // The bow: widest at the equator, meeting at the poles.
                    float x = side * 0.150f * Mathf.Cos(t * Mathf.PI * 0.5f);
                    icon.Bar(mid + new Vector2(x, y), new Vector2(0.026f, 0.036f), 0f, -1f);
                }
            }
            return SaveSprite(icon, "icon_beachball");
        }

        // A CUBE, SEEN CORNER-ON: a hexagon with a Y cut into it.
        //
        // That is the whole of the shape, and it is why this reads as a cube where the previous two
        // attempts did not. A square with panels implied on it is a square; a hexagon divided by a Y
        // is three rhombi meeting at a corner, which the eye resolves as a box with no other cue at
        // all - it is the same drawing everybody makes of a cube by hand.
        //
        // THE Y IS CUT OUT, not drawn on. These icons are a single colour with an alpha mask, so a
        // hole is the only mark available; it shows through as whatever is behind, which is the white
        // line asked for.
        private static Sprite CubeIcon()
        {
            var icon = new IconCanvas(128);
            Vector2 mid = new Vector2(0.5f, 0.5f);
            const float radius = 0.345f;      // corner to centre
            const float line = 0.026f;        // half-width of the white lines

            // A pointy-top hexagon is the intersection of three slabs, at 0, 60 and 120 degrees, each
            // an apothem wide. Written that way rather than as six edges because three inequalities
            // cannot disagree about a corner.
            float apothem = radius * Mathf.Cos(30f * Mathf.Deg2Rad);
            icon.Shape(pt =>
            {
                Vector2 d = pt - mid;
                for (int k = 0; k < 3; k++)
                {
                    float a = Mathf.Deg2Rad * (k * 60f);
                    if (Mathf.Abs(d.x * Mathf.Cos(a) + d.y * Mathf.Sin(a)) > apothem) return false;
                }
                return true;
            });

            // The three arms: up to the top corner, and down to the two lower ones. Those are the
            // edges where the three visible faces meet.
            foreach (float degrees in new[] { 90f, 210f, 330f })
            {
                float a = Mathf.Deg2Rad * degrees;
                Vector2 corner = mid + new Vector2(Mathf.Cos(a), Mathf.Sin(a)) * radius;
                icon.Capsule(mid, corner, line, -1f);
            }
            return SaveSprite(icon, "icon_cube");
        }

        // A BUCKET WITH WATER IN IT, which has to be distinguishable from the empty one at a glance
        // because the two weigh 1.8 and 12.0 - the biggest single fact in room2-7. Same silhouette as
        // `BucketIcon` with a waterline across it and the pail below it cut hollow, so the difference
        // is a FILL rather than a decoration.
        private static Sprite FullBucketIcon()
        {
            var icon = new IconCanvas(128);
            Vector2 mid = new Vector2(0.5f, 0.46f);

            icon.Bar(mid + new Vector2(0f, 0.145f), new Vector2(0.360f, 0.055f), 0f);
            icon.Bar(mid + new Vector2(0f, 0.055f), new Vector2(0.330f, 0.130f), 0f);
            icon.Bar(mid + new Vector2(0f, -0.070f), new Vector2(0.280f, 0.130f), 0f);
            icon.Bar(mid + new Vector2(0f, -0.165f), new Vector2(0.240f, 0.070f), 0f);

            icon.Bar(mid + new Vector2(-0.175f, 0.255f), new Vector2(0.032f, 0.150f), 0f);
            icon.Bar(mid + new Vector2(0.175f, 0.255f), new Vector2(0.032f, 0.150f), 0f);
            icon.Bar(mid + new Vector2(0f, 0.325f), new Vector2(0.360f, 0.032f), 0f);

            // THE WATERLINE, and then the pail below it hollowed out. Cutting the body away under the
            // line leaves a filled band at the top and an outline beneath: at icon size that reads as
            // "there is something in this one" far better than shading it darker would.
            icon.Bar(mid + new Vector2(0f, 0.078f), new Vector2(0.300f, 0.026f), 0f, -1f);
            icon.Bar(mid + new Vector2(0f, -0.085f), new Vector2(0.245f, 0.130f), 0f, -1f);
            return SaveSprite(icon, "icon_bucket_full");
        }

        // A QUESTION MARK, built rather than typed. The signs in this building are ICONS - a glyph
        // from the UI font among them would read as a different kind of object, and the one thing
        // this sign must not do is look like it is explaining itself in words.
        //
        // STROKED ALONG ITS OWN PATH rather than assembled from a ring with a bite taken out of it.
        // That is how the first version was built and it showed: the cut left a squared-off end where
        // the hook should taper into the stem, and the join read as a break. A question mark is one
        // continuous line, so it is drawn as one - an arc from the lower left of the bowl round the
        // top and down the right, then a short curve into the tail, then the dot.
        private static Sprite QuestionIcon()
        {
            var icon = new IconCanvas(128);
            Vector2 mid = new Vector2(0.5f, 0.5f);
            const float stroke = 0.062f;

            // THE BOWL: three-quarters of a circle, opening at the bottom left. 200 degrees round to
            // -20 leaves the tail pointing down and inward, which is where the stem picks it up.
            Vector2 bowl = mid + new Vector2(0f, 0.215f);
            icon.Arc(bowl, 0.175f, 200f, -20f, stroke);

            // THE STEM, from where the bowl ends, curving in to the centre line. Two segments rather
            // than one: a question mark's tail is not straight, and the bend is what stops it reading
            // as a lollipop.
            float endRad = Mathf.Deg2Rad * -20f;
            Vector2 bowlEnd = bowl + new Vector2(Mathf.Cos(endRad), Mathf.Sin(endRad)) * 0.175f;
            Vector2 waist = mid + new Vector2(0.055f, -0.020f);
            Vector2 tail = mid + new Vector2(0.005f, -0.145f);
            icon.Capsule(bowlEnd, waist, stroke);
            icon.Capsule(waist, tail, stroke);

            // THE DOT, clear of the tail by its own width - touching, it reads as an exclamation.
            icon.Disc(mid + new Vector2(0.005f, -0.310f), 0.078f);
            return SaveSprite(icon, "icon_question");
        }

        // PLUS AND EQUALS. Two bars and a cross - trivial, and here rather than as text for the same
        // reason the question mark is.
        private static Sprite PlusIcon()
        {
            var icon = new IconCanvas(128);
            Vector2 mid = new Vector2(0.5f, 0.5f);
            icon.Bar(mid, new Vector2(0.300f, 0.062f), 0f);
            icon.Bar(mid, new Vector2(0.062f, 0.300f), 0f);
            return SaveSprite(icon, "icon_plus");
        }

        private static Sprite EqualsIcon()
        {
            var icon = new IconCanvas(128);
            Vector2 mid = new Vector2(0.5f, 0.5f);
            icon.Bar(mid + new Vector2(0f, 0.115f), new Vector2(0.300f, 0.058f), 0f);
            icon.Bar(mid + new Vector2(0f, -0.115f), new Vector2(0.300f, 0.058f), 0f);
            return SaveSprite(icon, "icon_equals");
        }

        private static Sprite BucketIcon()
        {
            var icon = new IconCanvas(128);
            Vector2 mid = new Vector2(0.5f, 0.46f);

            // The body, as a stack of narrowing bars - the taper is what makes it a bucket rather than
            // a tin, and it is the only part of the silhouette that survives at 58px.
            icon.Bar(mid + new Vector2(0f, 0.145f), new Vector2(0.360f, 0.055f), 0f);
            icon.Bar(mid + new Vector2(0f, 0.055f), new Vector2(0.330f, 0.130f), 0f);
            icon.Bar(mid + new Vector2(0f, -0.070f), new Vector2(0.280f, 0.130f), 0f);
            icon.Bar(mid + new Vector2(0f, -0.165f), new Vector2(0.240f, 0.070f), 0f);

            // The handle, an arc built from two uprights and a span across the top.
            icon.Bar(mid + new Vector2(-0.175f, 0.255f), new Vector2(0.032f, 0.150f), 0f);
            icon.Bar(mid + new Vector2(0.175f, 0.255f), new Vector2(0.032f, 0.150f), 0f);
            icon.Bar(mid + new Vector2(0f, 0.325f), new Vector2(0.360f, 0.032f), 0f);
            return SaveSprite(icon, "icon_bucket");
        }

        private static Sprite PinIcon()
        {
            var icon = new IconCanvas(128);
            Vector2 along = new Vector2(0.7071f, 0.7071f);
            Vector2 mid = new Vector2(0.5f, 0.5f);
            // Everything is placed by distance along that one diagonal, so the parts stay in line
            // however they are resized.
            System.Func<float, Vector2> at = t => mid + along * t;

            // The needle is deliberately fatter than the real pin is. This is drawn at 128px and
            // displayed at 58: a truly slim needle lands on one screen pixel and disappears.
            icon.Bar(at(0.235f), new Vector2(0.030f, 0.185f), -45f);
            icon.Bar(at(-0.15f), new Vector2(0.058f, 0.19f), -45f);   // grip
            icon.Disc(at(-0.34f), 0.058f);                            // rounded butt
            icon.Disc(at(0.045f), 0.045f);                            // ferrule, where the two meet
            return SaveSprite(icon, "icon_pin");
        }

        // A MIRROR: the round pane, its stand, and two glints across the glass.
        //
        // The glints are not decoration - a ring on a stem is a hand mirror, a lollipop or a road
        // sign, and every one of those is a plausible thing to be carrying in this building. Two
        // parallel bars across the inside is the one mark that says the circle is REFLECTIVE, and it
        // is the same mark a mirror gets in every pictogram set for that reason.
        //
        // Both bars stay inside the ring's inner radius: they are placed by offsetting perpendicular
        // to their own direction, so the pair stays parallel and centred however the angle is retuned.
        private static Sprite MirrorIcon()
        {
            var icon = new IconCanvas(128);
            Vector2 mid = new Vector2(0.5f, 0.585f);

            icon.Ring(mid, 0.275f, 0.212f);

            const float glintDegrees = -35f;
            float rad = -glintDegrees * Mathf.Deg2Rad;
            Vector2 perp = new Vector2(Mathf.Cos(rad), -Mathf.Sin(rad));

            icon.Bar(mid - perp * 0.075f, new Vector2(0.024f, 0.145f), glintDegrees);
            icon.Bar(mid + perp * 0.075f, new Vector2(0.024f, 0.085f), glintDegrees);

            // The stem runs up into the ring rather than stopping at it - butted against the outside
            // it reads as a circle balanced on a stick.
            icon.Bar(new Vector2(0.5f, 0.235f), new Vector2(0.026f, 0.085f));
            icon.Bar(new Vector2(0.5f, 0.155f), new Vector2(0.125f, 0.028f));
            return SaveSprite(icon, "icon_mirror");
        }

        // ---- the figure pictograms: one body, six poses --------------------------------------------
        //
        // The calibration wall used to caption its controls in words (MOVE, JUMP, SPRINT...). These
        // replace them, which is the same move the Room2 sign makes and for the same reason: the game
        // has no text elsewhere and a player who cannot read English should still be able to start it.
        //
        // ONE body plan, six poses, and that is the point rather than tidiness. Six figures each drawn
        // to look right on its own is how a set of pictograms ends up looking like six pictograms from
        // six different sets - the same head size, limb length and thickness across all of them is what
        // makes them read as one person doing different things.
        private const float FigureLimb = 0.075f;    // limb thickness, fat enough to survive 128px
        private const float FigureHead = 0.088f;    // head radius
        private const float FigureThigh = 0.20f;
        private const float FigureShin = 0.19f;
        private const float FigureUpperArm = 0.16f;
        private const float FigureForearm = 0.15f;

        // Draws a limb segment from `from` in `direction` and returns its far end, so segments chain
        // into a bent limb. Angles are given in degrees CLOCKWISE FROM STRAIGHT DOWN, because every
        // limb here hangs off a joint and down is the rest pose.
        private static Vector2 FigureBone(IconCanvas icon, Vector2 from, float degrees, float length)
        {
            float rad = degrees * Mathf.Deg2Rad;
            Vector2 dir = new Vector2(Mathf.Sin(rad), -Mathf.Cos(rad));
            Vector2 to = from + dir * length;
            // Bar takes half-extents and a rotation; the sign convention is the pin icon's.
            icon.Bar((from + to) * 0.5f, new Vector2(FigureLimb * 0.5f, length * 0.5f),
                     -Mathf.Atan2(dir.x, dir.y) * Mathf.Rad2Deg);
            // Joint discs at every hinge. Without them a bent limb shows the corner of one bar poking
            // past the other and the elbow reads as a break.
            icon.Disc(to, FigureLimb * 0.5f);
            return to;
        }

        // Head, spine and a joint at each end. Returns the shoulder and hip so the caller can hang
        // limbs off them, which is the only thing any of the poses differ by.
        private static (Vector2 shoulder, Vector2 hip) FigureTorso(IconCanvas icon, Vector2 hip,
                                                                   float spineLength, float leanDegrees)
        {
            float rad = leanDegrees * Mathf.Deg2Rad;
            Vector2 up = new Vector2(Mathf.Sin(rad), Mathf.Cos(rad));
            Vector2 shoulder = hip + up * spineLength;

            icon.Bar((hip + shoulder) * 0.5f, new Vector2(FigureLimb * 0.55f, spineLength * 0.5f),
                     -leanDegrees);
            icon.Disc(hip, FigureLimb * 0.5f);
            icon.Disc(shoulder, FigureLimb * 0.5f);
            // The head sits off the shoulder along the same lean, so a leaning figure's head leads.
            icon.Disc(shoulder + up * (FigureHead + 0.035f), FigureHead);
            return (shoulder, hip);
        }

        // MOVE. A mid-stride walk: one leg forward and planted, one trailing, arms opposing. Upright,
        // because upright against the run's lean is what tells the two apart at a glance - the stride
        // widths alone are too similar at this size.
        private static Sprite FigureWalkIcon()
        {
            var icon = new IconCanvas(128);
            var (shoulder, hip) = FigureTorso(icon, new Vector2(0.47f, 0.44f), 0.26f, 2f);
            FigureBone(icon, FigureBone(icon, hip, 26f, FigureThigh), 12f, FigureShin);
            FigureBone(icon, FigureBone(icon, hip, -22f, FigureThigh), -6f, FigureShin);
            FigureBone(icon, FigureBone(icon, shoulder, -20f, FigureUpperArm), -44f, FigureForearm);
            FigureBone(icon, FigureBone(icon, shoulder, 18f, FigureUpperArm), 40f, FigureForearm);
            return SaveSprite(icon, "icon_figure_walk");
        }

        // SPRINT. The same body leaning into it, with a longer stride and arms driving harder. The
        // LEAN is what reads as speed; a running figure drawn upright reads as a wider walk.
        private static Sprite FigureRunIcon()
        {
            var icon = new IconCanvas(128);
            var (shoulder, hip) = FigureTorso(icon, new Vector2(0.44f, 0.45f), 0.26f, 20f);
            FigureBone(icon, FigureBone(icon, hip, 48f, FigureThigh), 20f, FigureShin);
            FigureBone(icon, FigureBone(icon, hip, -34f, FigureThigh), -74f, FigureShin);
            FigureBone(icon, FigureBone(icon, shoulder, -52f, FigureUpperArm), -104f, FigureForearm);
            FigureBone(icon, FigureBone(icon, shoulder, 46f, FigureUpperArm), 96f, FigureForearm);
            return SaveSprite(icon, "icon_figure_run");
        }

        // CROUCH. Knees folded hard, hip dropped, spine tipped forward to balance over the feet. The
        // dropped hip is the whole silhouette: a figure with bent knees at standing height reads as
        // someone about to jump.
        private static Sprite FigureCrouchIcon()
        {
            var icon = new IconCanvas(128);
            var (shoulder, hip) = FigureTorso(icon, new Vector2(0.47f, 0.31f), 0.24f, 16f);
            FigureBone(icon, FigureBone(icon, hip, 58f, FigureThigh * 0.92f), -30f, FigureShin * 0.92f);
            FigureBone(icon, FigureBone(icon, hip, 30f, FigureThigh * 0.92f), -52f, FigureShin * 0.92f);
            FigureBone(icon, FigureBone(icon, shoulder, 30f, FigureUpperArm), 74f, FigureForearm * 0.9f);
            return SaveSprite(icon, "icon_figure_crouch");
        }

        // JUMP. Both feet off the floor and tucked the same way, arms up. Symmetry is what separates it
        // from the walk - a stride says one foot is down, and two matching legs say neither is.
        private static Sprite FigureJumpIcon()
        {
            var icon = new IconCanvas(128);
            var (shoulder, hip) = FigureTorso(icon, new Vector2(0.5f, 0.46f), 0.25f, 0f);
            FigureBone(icon, FigureBone(icon, hip, 30f, FigureThigh * 0.85f), 66f, FigureShin * 0.85f);
            FigureBone(icon, FigureBone(icon, hip, -30f, FigureThigh * 0.85f), -66f, FigureShin * 0.85f);
            FigureBone(icon, FigureBone(icon, shoulder, 156f, FigureUpperArm), 168f, FigureForearm * 0.85f);
            FigureBone(icon, FigureBone(icon, shoulder, -156f, FigureUpperArm), -168f, FigureForearm * 0.85f);
            // The floor it has left. Without it the pose is just a figure with odd legs; with it there
            // is a gap under the feet, and the gap is the jump.
            icon.Bar(new Vector2(0.5f, 0.055f), new Vector2(0.30f, 0.022f));
            return SaveSprite(icon, "icon_figure_jump");
        }

        // INTERACT. A figure with one arm out to a panel on the wall - the panel is what makes it
        // "press this" rather than "wave". Drawn as one of the room's own wall cells, because that is
        // literally what E is pressed at.
        private static Sprite FigurePressIcon()
        {
            var icon = new IconCanvas(128);
            var (shoulder, hip) = FigureTorso(icon, new Vector2(0.36f, 0.42f), 0.26f, 4f);
            FigureBone(icon, FigureBone(icon, hip, 12f, FigureThigh), 4f, FigureShin);
            FigureBone(icon, FigureBone(icon, hip, -14f, FigureThigh), -4f, FigureShin);
            // The reaching arm, straight out and level, ending at the panel.
            FigureBone(icon, FigureBone(icon, shoulder, 88f, FigureUpperArm), 92f, FigureForearm);
            FigureBone(icon, FigureBone(icon, shoulder, -14f, FigureUpperArm), -8f, FigureForearm);

            // Panel, and a groove down its left edge so it reads as set into a wall.
            icon.Bar(new Vector2(0.85f, 0.60f), new Vector2(0.075f, 0.135f));
            icon.Bar(new Vector2(0.745f, 0.60f), new Vector2(0.012f, 0.155f), 0f, -1f);
            return SaveSprite(icon, "icon_figure_press");
        }

        // LOOK AROUND. A head seen FROM ABOVE with an arc over it - the only one of the six not drawn
        // from the side, because a head turning is invisible in profile. The arc is an annulus segment
        // with a head on each end, which is a turn in both directions and therefore a look rather than
        // a glance.
        private static Sprite FigureLookIcon()
        {
            var icon = new IconCanvas(128);
            Vector2 centre = new Vector2(0.5f, 0.35f);

            icon.Disc(centre, 0.15f);
            // Nose, so the head has a facing and the arc has something to be turning.
            icon.Bar(new Vector2(centre.x, centre.y + 0.175f), new Vector2(0.035f, 0.045f));

            // The sweep: a ring, kept to its upper half and to the outside of the head.
            icon.Shape(p =>
            {
                float r = (p - centre).magnitude;
                return r > 0.245f && r < 0.315f && p.y > centre.y + 0.02f;
            });
            // Arrowheads on both ends of that arc. Placed on the ring at +-58 degrees from straight up.
            for (int s = -1; s <= 1; s += 2)
            {
                float rad = 58f * s * Mathf.Deg2Rad;
                Vector2 tip = centre + new Vector2(Mathf.Sin(rad), Mathf.Cos(rad)) * 0.28f;
                icon.Shape(p => (p - tip).magnitude < 0.075f && Vector2.Dot(p - tip, new Vector2(Mathf.Cos(rad) * s, -Mathf.Sin(rad) * s)) > 0f);
            }
            return SaveSprite(icon, "icon_figure_look");
        }

        // TAB. Not one of the six body poses - switching what is in the hand moves no limb a figure
        // could show - so this is the one calibration-wall control captioned with an object glyph
        // instead: two arrows chasing each other round a ring, the ordinary mark for "cycle through".
        // Built the same way the look icon's turn arc is, a ring cut to an arc with a half-disc
        // arrowhead at its leading end, just carried all the way round instead of stopping at a head.
        private static Sprite CycleIcon()
        {
            var icon = new IconCanvas(128);
            Vector2 centre = new Vector2(0.5f, 0.5f);
            const float outer = 0.36f, inner = 0.275f;
            const float mid = (outer + inner) * 0.5f;

            // Two arcs, opposite halves of the ring, each a little short of a true half so its
            // arrowhead has clear ring under it rather than overlapping the far arc.
            float[] starts = { 15f, 195f };
            float[] ends = { 165f, 345f };

            for (int i = 0; i < 2; i++)
            {
                float from = starts[i], to = ends[i];
                icon.Shape(p =>
                {
                    Vector2 d = p - centre;
                    float r = d.magnitude;
                    if (r < inner || r > outer) return false;
                    float deg = Mathf.Atan2(d.x, d.y) * Mathf.Rad2Deg;
                    if (deg < 0f) deg += 360f;
                    return deg >= from && deg <= to;
                });

                // The arrowhead sits at the arc's leading end - `to`, since the sweep runs clockwise -
                // a half disc cut along the tangent so it points the way the ring is turning.
                float tipRad = to * Mathf.Deg2Rad;
                Vector2 tip = centre + new Vector2(Mathf.Sin(tipRad), Mathf.Cos(tipRad)) * mid;
                float tangentRad = (to + 90f) * Mathf.Deg2Rad;
                Vector2 dir = new Vector2(Mathf.Sin(tangentRad), Mathf.Cos(tangentRad));
                icon.Shape(p => (p - tip).magnitude < 0.085f && Vector2.Dot(p - tip, dir) > 0f);
            }
            return SaveSprite(icon, "icon_cycle");
        }

        // A balloon: egg-shaped body, knot, short string. Wider at the top than a circle and narrowed
        // to the knot, because a plain disc with a string under it reads as a lollipop.
        private static Sprite BalloonIcon()
        {
            var icon = new IconCanvas(128);
            Vector2 centre = new Vector2(0.5f, 0.60f);
            icon.Shape(p =>
            {
                float dx = (p.x - centre.x) / 0.285f;
                // Narrower below the middle: that taper is the whole silhouette.
                float ry = p.y < centre.y ? 0.30f : 0.255f;
                float dy = (p.y - centre.y) / ry;
                return dx * dx + dy * dy <= 1f;
            });
            icon.Bar(new Vector2(0.5f, 0.285f), new Vector2(0.036f, 0.030f));   // knot
            icon.Bar(new Vector2(0.5f, 0.175f), new Vector2(0.014f, 0.085f));   // string
            return SaveSprite(icon, "icon_balloon");
        }

        // The same balloon a moment later: a scrap of skin still on the knot, and shards going out.
        // The shards are what carries it - a torn remnant on its own reads as a damaged balloon
        // rather than one that has just gone.
        private static Sprite BalloonBurstIcon()
        {
            var icon = new IconCanvas(128);
            Vector2 centre = new Vector2(0.5f, 0.56f);

            // Eight shards at uneven lengths. Even ones read as a sun, which is a different sign.
            float[] degrees = { 12f, 52f, 88f, 126f, 168f, 212f, 258f, 312f };
            float[] lengths = { 0.20f, 0.14f, 0.22f, 0.15f, 0.19f, 0.13f, 0.17f, 0.15f };
            for (int i = 0; i < degrees.Length; i++)
            {
                float rad = degrees[i] * Mathf.Deg2Rad;
                Vector2 dir = new Vector2(Mathf.Cos(rad), Mathf.Sin(rad));
                // Placed at half its own length out from the gap, so the shards do not meet in the
                // middle - the hole is what says the balloon is gone.
                Vector2 at = centre + dir * (0.105f + lengths[i] * 0.5f);
                icon.Bar(at, new Vector2(0.026f, lengths[i] * 0.5f), -degrees[i] + 90f);
            }

            icon.Bar(new Vector2(0.5f, 0.285f), new Vector2(0.036f, 0.030f));   // knot, still there
            icon.Bar(new Vector2(0.5f, 0.175f), new Vector2(0.014f, 0.085f));   // string
            return SaveSprite(icon, "icon_balloon_burst");
        }

        // A plain right-pointing arrow, for the pictogram rows. Shaft plus a solid head built from a
        // half-plane test rather than three bars, so the point cannot come out blunt at 128px.
        private static Sprite ArrowRightIcon()
        {
            var icon = new IconCanvas(128);
            icon.Bar(new Vector2(0.40f, 0.5f), new Vector2(0.24f, 0.055f));
            icon.Shape(p =>
            {
                if (p.x < 0.60f || p.x > 0.90f) return false;
                // Half-width shrinks to nothing at the tip.
                float half = Mathf.Lerp(0.20f, 0f, (p.x - 0.60f) / 0.30f);
                return Mathf.Abs(p.y - 0.5f) <= half;
            });
            return SaveSprite(icon, "icon_arrow_right");
        }

        // The key's silhouette at HUD size: ring bow, shaft, two teeth off one side only. A
        // symmetrical bit would read as a cross. Drawn rather than rendered from gold_key.glb,
        // because at 58px the model's bit resolves to a smudge - the same call the pin icon makes.
        private static Sprite KeyIcon()
        {
            var icon = new IconCanvas(128);
            icon.Ring(new Vector2(0.5f, 0.72f), 0.20f, 0.095f);
            icon.Bar(new Vector2(0.5f, 0.35f), new Vector2(0.045f, 0.20f));
            icon.Bar(new Vector2(0.60f, 0.26f), new Vector2(0.07f, 0.042f));
            icon.Bar(new Vector2(0.60f, 0.155f), new Vector2(0.07f, 0.042f));
            return SaveSprite(icon, "icon_key");
        }

        // The grey disc both control hints sit on.
        private static Sprite HintDiscSprite()
        {
            var icon = new IconCanvas(128);
            icon.Disc(new Vector2(0.5f, 0.5f), 0.48f);
            return SaveSprite(icon, "icon_hint_disc");
        }

        // A mouse seen from above, outlined, with the left button filled - which is the entire
        // message. Built from one capsule distance function so the outline, the hollow and the
        // button are all the same shape at three insets, and none of them can drift apart.
        private static Sprite MouseLeftIcon()
        {
            var icon = new IconCanvas(128);
            const float radius = 0.215f;
            const float topY = 0.655f, bottomY = 0.345f;

            System.Func<Vector2, float> toSpine = p =>
                (p - new Vector2(0.5f, Mathf.Clamp(p.y, bottomY, topY))).magnitude;

            icon.Shape(p => toSpine(p) <= radius);
            icon.Shape(p => toSpine(p) <= radius - 0.042f, -1f);
            icon.Shape(p => toSpine(p) <= radius - 0.072f && p.x < 0.484f && p.y > 0.60f);
            return SaveSprite(icon, "icon_mouse_left");
        }

        // The same mouse with no button filled - the calibration page's "look around" row, where
        // highlighting a button would say "click", which is the one thing that row does not mean.
        // The two seams are what keep it from reading as a plain capsule.
        private static Sprite MouseIcon()
        {
            var icon = new IconCanvas(128);
            const float radius = 0.215f;
            const float topY = 0.655f, bottomY = 0.345f;

            System.Func<Vector2, float> toSpine = p =>
                (p - new Vector2(0.5f, Mathf.Clamp(p.y, bottomY, topY))).magnitude;

            icon.Shape(p => toSpine(p) <= radius);
            icon.Shape(p => toSpine(p) <= radius - 0.042f, -1f);
            const float hollow = radius - 0.042f;
            icon.Shape(p => toSpine(p) <= hollow && Mathf.Abs(p.y - 0.605f) < 0.017f);
            icon.Shape(p => toSpine(p) <= hollow && p.y > 0.605f && Mathf.Abs(p.x - 0.5f) < 0.017f);
            return SaveSprite(icon, "icon_mouse");
        }

        // A speaker with sound coming off it - "turn your volume up", over the calibration room's
        // BEGIN button. The PA and every room's audio cues are half of what the facility tells the
        // player, and this is the last screen before the loop's clock starts, so it is the one place
        // a muted or silent tab can still be caught rather than discovered mid-iteration.
        private static Sprite VolumeIcon()
        {
            var icon = new IconCanvas(128);

            // The body: a plain box, standing in for the speaker cabinet.
            icon.Bar(new Vector2(0.28f, 0.5f), new Vector2(0.07f, 0.11f));
            // The cone, widening away from the box - the same tapered half-plane test the right
            // arrow's head uses, just wider so it reads as a speaker rather than an arrow.
            icon.Shape(p =>
            {
                if (p.x < 0.28f || p.x > 0.46f) return false;
                float half = Mathf.Lerp(0.11f, 0.22f, (p.x - 0.28f) / 0.18f);
                return Mathf.Abs(p.y - 0.5f) <= half;
            });

            // Three sound waves fanning out to the right, each a band of an arc rather than a full
            // ring so they read as coming FROM the cone rather than surrounding it.
            Vector2 mouth = new Vector2(0.46f, 0.5f);
            for (int i = 0; i < 3; i++)
            {
                float r = 0.13f + i * 0.085f;
                const float thickness = 0.026f;
                icon.Shape(p =>
                {
                    Vector2 d = p - mouth;
                    float dist = d.magnitude;
                    if (dist < r - thickness || dist > r + thickness) return false;
                    float deg = Mathf.Atan2(d.y, d.x) * Mathf.Rad2Deg;
                    return Mathf.Abs(deg) <= 55f;
                });
            }
            return SaveSprite(icon, "icon_volume");
        }

        // tiling is in repeats across one face. URP/Lit drives the normal map's UVs from _BaseMap's
        // transform, not _BumpMap's, so setting the scale on _BumpMap does nothing at all.
        private static void ApplySurfaceDetail(Material mat, Texture2D normalMap, float bumpScale, Vector2 tiling, float smoothness)
        {
            if (normalMap == null) return;

            mat.EnableKeyword("_NORMALMAP");
            mat.SetTexture("_BumpMap", normalMap);
            mat.SetFloat("_BumpScale", bumpScale);
            mat.SetTextureScale("_BaseMap", tiling);
            // Raised off the old 0.03: at that roughness there is almost no specular response, so
            // the relief only shows in diffuse shading and barely reads. Still well short of the
            // 0.5 default that mirrors the skybox onto the walls.
            SetSmoothness(mat, smoothness);

            // **AND THE SMOOTHNESS VARIES ACROSS IT NOW** - see `MakeSmoothnessMap`. Every surface
            // that gets a normal map gets this, because the two are halves of one idea: the normal
            // map breaks the light up, this breaks up how sharply it comes back.
            //
            // Applied HERE rather than at each call site so a new surface cannot get one without the
            // other - the same reason `AddFallingToEveryCarryable` is a sweep.
            ApplyWear(mat);

            EditorUtility.SetDirty(mat);
        }

        // The smoothness variation, on one material.
        //
        // **THE KEYWORD IS THE WHOLE OF IT.** Assigning `_MetallicGlossMap` and stopping is the exact
        // shape of mistake this project has recorded twice already - transparency needing
        // `_SURFACE_TYPE_TRANSPARENT` as well as the blend modes, and `_BumpScale` only being
        // drivable because `_NORMALMAP` was already compiled in. URP's `SampleMetallicSpecGloss` is
        // wrapped in `#ifdef _METALLICSPECGLOSSMAP`: without it the texture is set, costs memory, and
        // is never read.
        //
        // ONE TEXTURE PER METALLIC VALUE, cached by name, because the map carries metallic in its red
        // channel - two materials that differ only in colour share one, and a metal and a non-metal
        // cannot.
        private static void ApplyWear(Material mat)
        {
            if (mat == null) return;

            float metallic = mat.HasProperty("_Metallic") ? mat.GetFloat("_Metallic") : 0f;

            // Named off the metallic value so the cache key and the file name are the same fact.
            Texture2D wear = MakeSmoothnessMap($"SurfaceWear_{Mathf.RoundToInt(metallic * 100f)}",
                                               256, metallic, WearFloor);

            if (wear == null) return;

            mat.EnableKeyword("_METALLICSPECGLOSSMAP");
            mat.SetTexture("_MetallicGlossMap", wear);
            // The alpha channel of the metallic map, not of the base map. It is URP's default, and
            // stating it is cheap against a material that arrives with the other one set.
            mat.SetFloat("_SmoothnessTextureChannel", 0f);
            // The wear tiles on its OWN scale, much broader than the grain - `_BaseMap`'s tiling is
            // tuned to make the normal map read as plaster, and wear at that rate is glitter.
            mat.SetTextureScale("_MetallicGlossMap", Vector2.one);
        }

        // A glossy surface is only as good as what it has to reflect, and the only reflection
        // source here was the procedural sky - which is blue, and which the room can't even see.
        // Raising smoothness without this paints a blue cast over every white panel; that is the
        // exact failure the old 0.03-smoothness-everywhere rule existed to dodge.
        //
        // Baked, and baked right here as part of the build. A Realtime probe was tried first, on
        // the reasoning that SceneBuilder rebuilds the scene every run so baked data would always
        // be stale - but a realtime probe renders nothing until play mode, so `probe.texture` came
        // back EMPTY and the glossy walls had nothing at all to reflect. Baking it during Build()
        // solves both: the cubemap is a real asset, and it is regenerated in lockstep with the
        // geometry it captures. It is two small cubemaps, so it costs no meaningful build time.
        //
        // Box projection matters more than usual for a room this shape - it reprojects the cubemap
        // onto the box bounds, so a reflected wall stays put on the wall instead of sliding around
        // as the camera moves.
        // xCenter and the swap flag are both for Room2's side rooms: they sit off the chain's axis, and
        // their long dimension runs along X where every other room's runs along Z - so the probe's box
        // has to be turned with the room or box projection reflects the wrong walls.
        // `sizeOverride` is for the one room that is not a standard shell - the tree hall is 21m of
        // run and 17.5m of headroom, and a probe boxed to a normal room would box-project the
        // reflection off walls that are nowhere near where it thinks they are. Left default, every
        // other room behaves exactly as before.
        private static void BuildReflectionProbe(Transform parent, string roomName, float zCenter,
                                                float xCenter = 0f, bool longAxisIsX = false,
                                                Vector3 sizeOverride = default, float yCenter = -1f)
        {
            GameObject go = new GameObject(roomName + "_ReflectionProbe");
            go.transform.SetParent(parent, false);
            go.transform.localPosition = new Vector3(
                xCenter, yCenter >= 0f ? yCenter : RoomHeight * 0.5f, zCenter);

            ReflectionProbe probe = go.AddComponent<ReflectionProbe>();
            // CUSTOM, NOT BAKED, and this one word is the whole bug. A Baked probe does not carry
            // its cubemap: the reference lives in the SCENE'S LIGHTING DATA ASSET, which this build
            // never generates, so `bakedTexture` was set in memory by the bake and came back NULL
            // the moment the scene was saved and reopened. A Custom probe holds the cubemap in a
            // field on the component, which serialises with everything else. Verified by reopening
            // the saved scene and reading it back - see BakeReflectionProbes.
            probe.mode = UnityEngine.Rendering.ReflectionProbeMode.Custom;
            probe.boxProjection = true;
            probe.size = sizeOverride != default
                ? sizeOverride
                : (longAxisIsX
                    ? new Vector3(RoomDepth, RoomHeight, RoomWidth)
                    : new Vector3(RoomWidth, RoomHeight, RoomDepth));
            // 512, not 256: at the wall smoothness used here the reflection is sharp enough that a
            // 256 cubemap shows the ceiling fixtures as vague smears rather than panels.
            probe.resolution = 512;
            probe.clearFlags = ReflectionProbeClearFlags.Skybox;
            probe.nearClipPlane = 0.05f;
            probe.farClipPlane = 40f;

            // NOT BAKED HERE. It used to be, and the reference did not survive to the saved scene -
            // see BakeReflectionProbes, called at the end of Build(), for what went wrong and why
            // last is the right place for it.
        }

        // Bake every probe in the scene, whatever built it. Walking the scene rather than taking a
        // list means a room added later cannot be forgotten - which is exactly how this would break
        // again, and quietly, since an unbaked probe looks like a slightly flat room rather than
        // like an error.
        //
        // `-nographics` cannot render, and a bake is a render: the whole pass is skipped there. That
        // leaves the previous .exr files in place, which is the same bargain CaptureMenuBackground
        // makes - stale reflection data is a far better outcome than a failed build.
        // MOVES EACH CYCLE OUT INTO ITS OWN SCENE, and then proves nothing was left pointing across the
        // gap. See CycleSceneLoader for why the cycles are split at all (build time, not frame time).
        //
        // The `Cycle` component's own GameObject becomes the PARENT of that cycle's world and its wall
        // panels, so one move takes everything and the scene has exactly one root. That is also what
        // `CycleSceneLoader` looks for on the way back in - a scene whose root carries a `Cycle`.
        //
        // WHAT THIS DELIBERATELY DOES NOT DO is repair the references it is about to break. Unity drops
        // a serialized reference across a scene boundary silently, and the answer to that is not to
        // hunt them here - it is `CycleBinding`, which re-establishes every one of them at runtime and
        // was written and proved BEFORE this method existed. All this does is check the work: anything
        // still crossing after the move is something CycleBinding does not yet know about, and the
        // build says so rather than shipping a null nobody will meet until they play that room.
        private static void SplitCyclesIntoScenes(Cycle[] cycles, WallPanelDisplay[] displays)
        {
            ExtractCalibrationRoom(cycles.Length > 0 ? cycles[0] : null);

            for (int i = 0; i < cycles.Length; i++)
            {
                Cycle cycle = cycles[i];
                if (cycle == null) continue;

                if (cycle.worldRoot != null) cycle.worldRoot.SetParent(cycle.transform, true);
                if (i < displays.Length && displays[i] != null)
                    displays[i].transform.SetParent(cycle.transform, true);

                string name = CycleSceneNames[i];
                Scene cycleScene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Additive);
                EditorSceneManager.MoveGameObjectToScene(cycle.gameObject, cycleScene);

                // **THE NEW SCENE HAS UNITY'S LIGHTING, NOT THIS GAME'S, AND NOTHING INHERITS IT.**
                // `RenderSettings` is per scene and these are born empty, so without this a cycle
                // runs on skybox ambient nobody chose - see `ApplyEnvironment` for what that cost.
                // The write goes to the ACTIVE scene, so it has to be made active first and put back
                // after, or the settings land on whichever scene happened to be active.
                Scene wasActive = SceneManager.GetActiveScene();
                SceneManager.SetActiveScene(cycleScene);
                ApplyEnvironment();
                EnsureProbeVolume(cycleScene);
                SceneManager.SetActiveScene(wasActive);
                EditorSceneManager.SaveScene(cycleScene, CycleScenePath(name));
                Debug.Log($"[SceneBuilder] Cycle scene '{name}' written to {CycleScenePath(name)}");
            }

            CrossSceneReferenceCheck.WriteReport();
        }

        // EVERYTHING CYCLE 2 IS, behind one call - the shell, its own wall display, the console at the
        // end of the ring and the `Cycle` component that names all of it.
        //
        // Extracted from `Build` so there is a way to build this cycle WITHOUT building the rest of the
        // game (see RebuildCycleTwo). That only became possible once the cycles were split into scenes
        // of their own: `shaker`, `hand` and `narration` all live in the core scene, and until
        // `CycleBinding` started re-establishing them at runtime they had to be present at build time.
        // They are still passed when the full build calls this, because passing the real thing costs
        // nothing - but NULL is now a legal answer, and that is the whole of why a cycle can be rebuilt
        // on its own.
        private static (Cycle cycle, WallPanelDisplay display) AssembleCycleTwo(
            Transform cycleTwoRoot, Transform bedSpawn, Door[] doors, RoomCondition[] conditions,
            GhostInteractable[] signals, ParticleSystem[] gasEmitters, Transform[] rooms,
            Transform[] loweredRooms, FinalRoomSequence finalRoom,
            Material floorMat, Material propMat, Texture2D testCard, Texture2D staticNoise,
            CameraShaker shaker, PlayerHand hand, NarrationDirector narration)
        {
            // ONE DISPLAY PER CYCLE. The ERROR spreading from a console means *this bed's cycle is
            // over*, so a panel in a cycle the player has not reached has no business failing - and
            // the gather is by name, which would otherwise sweep up every storey at once.
            var panels = new System.Collections.Generic.List<Renderer>();
            foreach (Renderer r in cycleTwoRoot.GetComponentsInChildren<Renderer>())
            {
                if (r.transform.parent == null || !r.transform.parent.name.EndsWith("_Panels")) continue;
                panels.Add(r);
            }
            WallPanelDisplay display = MakeWallPanelDisplay(
                "WallPanelDisplay_Cycle2", panels.ToArray(), testCard, staticNoise);

            GameObject cycleTwoGO = new GameObject("Cycle2");
            Cycle cycleTwo = cycleTwoGO.AddComponent<Cycle>();
            cycleTwo.bedSpawnPoint = bedSpawn;
            cycleTwo.doors = doors;
            cycleTwo.drawers = cycleTwoRoot.GetComponentsInChildren<Drawer>(true);
            // Shut at the top of every iteration with the drawers. A tap left running is world state
            // the loop would otherwise forget to rewind - and the most visible kind there is.
            cycleTwo.taps = cycleTwoRoot.GetComponentsInChildren<WaterTap>(true);
            cycleTwo.buckets = cycleTwoRoot.GetComponentsInChildren<Bucket>(true);
            cycleTwo.bucketStands = cycleTwoRoot.GetComponentsInChildren<BucketStand>(true);
            // THE FOUR WALL EMITTERS, BY NAME RATHER THAN BY TYPE. `CycleBinding.PointGasAt` used to
            // gather every ParticleSystem under the cycle instead, which swept the tap sprays in with
            // them - see Cycle.gasEmitters. The builder knows exactly which four these are, so it says
            // so here and nothing has to guess at runtime.
            cycleTwo.gasEmitters = gasEmitters;
            // Its own array, numbered from ZERO - where cycle 1's pad is also bit 0. Legal because
            // every ghost is destroyed at the boundary, so no surviving timeline refers to cycle 1's
            // bits, and the recorder is repointed at this array when the cycle starts.
            CheckGhostSignals("Cycle 2", signals);
            cycleTwo.ghostInteractables = signals;
            cycleTwo.conditions = conditions;

            // AND CYCLE 2 CAN BE FINISHED AGAIN. It shipped with `finalRoom` null for a day - a
            // supported state that `Cycle.Complete`, `LoopManager` and `CycleBinding` all guard, and
            // an honest way to say "this cycle has no end yet". room2-0 is that end: four pedestals,
            // four billiard balls, and the same break cycle 1 has.
            //
            // The three things it needed are all here now, which is what the old comment listed as
            // outstanding: a room0, a console in it, and carryables wearing the ids its recesses
            // declare. The ids are the nine billiard balls rather than the ShardA/B/C the old console
            // asked for and nothing ever wore.
            cycleTwo.finalRoom = finalRoom;
            if (finalRoom != null)
            {
                // THIS CYCLE'S PANELS, not the building's. The ERROR spreading out from a console
                // means *this bed's cycle is over*, and the display gathered above is the one built
                // from this root's own panel groups.
                finalRoom.wallPanels = display;
                // Both may be null on the cycle-2-only rebuild path, where there is no player and no
                // PA to point at - `CycleBinding` re-establishes them at runtime, which is the whole
                // reason that path is allowed to pass null for them at all.
                finalRoom.cameraShaker = shaker;
                finalRoom.narration = narration;
                if (finalRoom.slots != null)
                    foreach (FinalSlot slot in finalRoom.slots)
                        if (slot != null) slot.hand = hand;

                CheckCycleFinishable("Cycle 2", cycleTwoRoot, finalRoom);
            }

            cycleTwo.worldRoot = cycleTwoRoot;
            cycleTwo.wallPanels = display;

            // Everything down there stands on a floor one storey below zero, and every carryable has to
            // be told so or it falls through it.
            SetFloorBase(cycleTwoRoot, -StoreyDrop);

            // ...EXCEPT THE THREE THE SLIDE LANDS IN, which are a further `SlideRoomFloorY` down again.
            // A second pass rather than a smarter first one: the sweep above is a statement about the
            // CYCLE and this is a statement about three rooms inside it, and running them in this
            // order is what lets the second overwrite the first for exactly the objects it names.
            //
            // Left unsaid, `floorBaseY` is 3.7m too high for anything living down there - which is a
            // value that is simply untrue in the scene, whether or not anything currently reads it.
            // What used to read it was every drop (see `CarryableItem.DropAt`), and the symptom was a
            // duck put down on the water hopping 3.7m into the air first.
            if (loweredRooms != null)
                foreach (Transform room in loweredRooms)
                    SetFloorBase(room, -StoreyDrop + SlideRoomFloorY);

            return (cycleTwo, display);
        }

        // CYCLE 3, GATHERED ONTO ONE OBJECT. The same shape as `AssembleCycleTwo` and much less of it,
        // because the cycle is one sealed room: no doors to shut, no conditions to rewind, no final
        // room to finish. All three are supported states rather than gaps - see `Cycle.Complete`,
        // which is false forever without a `finalRoom`, and `LoopManager`, which simply keeps
        // iterating.
        private static (Cycle cycle, WallPanelDisplay display) AssembleCycleThree(
            Transform root, Transform bedSpawn, ParticleSystem[] gasEmitters,
            GhostInteractable[] signals, Texture2D testCard, Texture2D staticNoise,
            CrushingBarrier northBarrier, BeamLift[] lifts)
        {
            // ONE DISPLAY PER CYCLE, gathered by parent name exactly as cycle 2's is: the ERROR
            // spreading from a console means *this bed's cycle is over*, so a panel in a cycle the
            // player has not reached has no business failing.
            var panels = new System.Collections.Generic.List<Renderer>();
            foreach (Renderer r in root.GetComponentsInChildren<Renderer>())
            {
                if (r.transform.parent == null || !r.transform.parent.name.EndsWith("_Panels")) continue;
                panels.Add(r);
            }
            WallPanelDisplay display = MakeWallPanelDisplay(
                "WallPanelDisplay_Cycle3", panels.ToArray(), testCard, staticNoise);

            GameObject go = new GameObject("Cycle3");
            Cycle cycle = go.AddComponent<Cycle>();
            cycle.bedSpawnPoint = bedSpawn;
            // FOUR GATES, EIGHT LEAVES, TWO `Door`s EACH SIDE OF EACH WALL - gathered rather than
            // listed, because a gate is built as a pair of calls and naming sixteen of them here is
            // sixteen chances to miss one. They all have to be shut by the loop like any other door:
            // a leaf left open is a wall with a hole in it at the top of the next iteration.
            cycle.doors = root.GetComponentsInChildren<Door>(true);
            cycle.barriers = northBarrier != null ? new[] { northBarrier } : new CrushingBarrier[0];
            cycle.lifts = lifts ?? new BeamLift[0];
            cycle.drawers = root.GetComponentsInChildren<Drawer>(true);
            cycle.gasEmitters = gasEmitters;
            CheckGhostSignals("Cycle 3", signals);
            cycle.ghostInteractables = signals;
            // GATHERED BY TYPE, not listed. A room rule joins this array by existing, which is the
            // same reason `doors` and `drawers` above are gathered - and it is what `ResetRooms`
            // walks at the top of every iteration, so a rule missing from here is a puzzle that
            // stays solved through the rewind. Room3-2N's cube is the first entry cycle 3 has.
            cycle.conditions = root.GetComponentsInChildren<RoomCondition>(true);
            // **AND CYCLE 3 CAN BE FINISHED, since 2026-08-30.** room3-0 is off deck B, two storeys
            // up inside room3-2N, and it takes the one object the Bedlam cube pays out. Found rather
            // than threaded down through the shell's return, for the same reason the cube is: there
            // is exactly one, and another member on that tuple is another thing to keep in step.
            cycle.finalRoom = root.GetComponentInChildren<FinalRoomSequence>(true);
            cycle.worldRoot = root;
            cycle.wallPanels = display;

            // WHAT FINISHING ROOM3-2N'S CUBE COSTS. Built here rather than in the shell because it
            // needs the cycle's own `WallPanelDisplay`, which is assembled a few lines above out of
            // every panel in every room - and turning all of them red at once is half of what this
            // sequence is. The cube is found rather than threaded down through the shell's return:
            // there is exactly one, and a seventh member on that tuple would be a seventh thing to
            // keep in step for no gain.
            FacilityFailure failure = BuildFacilityFailure(
                root, root.GetComponentInChildren<BedlamCube>(true), display);
            // AND THE BREAK PLAYS IT INSTEAD OF ITS OWN DRESSING. Cycle 3 does not say "containment
            // failure" and glitch its panels; it comes apart and says something else. See
            // `FinalRoomSequence.facilityFailure`.
            if (cycle.finalRoom != null) cycle.finalRoom.facilityFailure = failure;

            // Everything down here stands on a floor two storeys below zero, and every carryable has
            // to be told so or it falls through it. Nothing is carryable in this room yet except the
            // chest's cube, which is exactly the kind of thing that would fall through it.
            SetFloorBase(root, CycleThreeFloorY);

            return (cycle, display);
        }

        // THE CALIBRATION ROOM BELONGS TO NO CYCLE, and the split is what made that structural rather
        // than merely true. It is built inside cycle 1's shell because it is a room and that is where
        // rooms are built - but it runs ONCE, before the first iteration, before there is a cycle to be
        // in at all. Left where it was, it moves into `Cycle1.unity` and takes five references with it:
        // `SensitivityCalibration` lives on the core's canvas and points at the readout, the walls and
        // the display INSIDE it, and its start button points back the other way.
        //
        // None of those wants a runtime rebinding, because none of them was ever a cycle's business.
        // Lifted into a root of its own, in the core scene, they all stay ordinary intra-scene
        // references and the whole cluster disappears from the report.
        //
        // Found by NAME, and the prefix is `Calibration` rather than `CalibrationRoom` - which is not a
        // detail, it is the bug the first attempt shipped. The shell is `CalibrationRoom`, but the
        // readout the player actually looks at is a sibling called `CalibrationWall`, and matching the
        // longer name moved the room while leaving the wall, its start button and the three wall groups
        // behind in cycle 1. The report said so: `Cycle1/Room/CalibrationWall/StartButton`.
        private static void ExtractCalibrationRoom(Cycle cycleOne)
        {
            if (cycleOne == null || cycleOne.worldRoot == null) return;

            var move = new System.Collections.Generic.List<Transform>();
            foreach (Transform child in cycleOne.worldRoot)
                if (child.name.StartsWith("Calibration")) move.Add(child);

            if (move.Count == 0) return;

            GameObject holder = new GameObject("CalibrationRoom_Root");
            foreach (Transform t in move) t.SetParent(holder.transform, true);

            // **THE TUNER IS BUILT HERE, INSIDE THE LIFT, AND NOT WHERE THE ROOM IS BUILT.** It holds
            // a reference to every wall panel, floor, ceiling and fixture in this room, so built with
            // the rest of cycle 1 it lands in `Cycle1.unity` pointing at objects that stay in the core
            // scene - ninety-odd cross-scene references, every one of them silently NULLED on save.
            // The panel then opened with its sliders attached to nothing and reported the fallback
            // defaults as though they were the room's values. Exactly the failure the comment above
            // describes for `CalibrationWall`, made a second time.
            BuildLightingTuner(holder.transform);

            // **AND ITS OWN SHADOW BUDGET**, for the same reason the tuner is built here: these
            // fixtures live in this scene now, and the component that switches them has to as well.
            // `WireShadowBudget` deliberately skips them - see there.
            var calibLights = new System.Collections.Generic.List<Light>();
            foreach (Light l in holder.GetComponentsInChildren<Light>(true))
                if (l.shadows != LightShadows.None) calibLights.Add(l);

            if (calibLights.Count > 0)
            {
                ShadowBudget calibBudget = holder.AddComponent<ShadowBudget>();
                calibBudget.fixtures = calibLights.ToArray();
                calibBudget.maxCasters = 4;
                Debug.Log($"[SceneBuilder] ShadowBudget on the calibration room: {calibLights.Count} "
                        + "fixture(s), in the scene they actually live in.");
            }
            Debug.Log($"[SceneBuilder] Calibration room lifted out of cycle 1 ({move.Count} object(s)); "
                    + "it runs before any cycle exists and stays in the core scene.");
        }

        private static void SleepCycle(Transform root)
        {
            if (root == null) return;
            root.gameObject.SetActive(false);
            Debug.Log($"[SceneBuilder] {root.name} starts asleep; LoopManager wakes it at the boundary.");
        }

        private static void BakeReflectionProbes()
        {
            if (SystemInfo.graphicsDeviceType == UnityEngine.Rendering.GraphicsDeviceType.Null)
            {
                Debug.Log("[SceneBuilder] Reflection probes NOT baked (-nographics); existing cubemaps left in place.");
                return;
            }

            int flagged = MarkReflectionProbeStatic();

            Directory.CreateDirectory(TexturesDir);
            ReflectionProbe[] probes = UnityEngine.Object.FindObjectsByType<ReflectionProbe>(
                FindObjectsInactive.Include);

            int wired = 0;
            foreach (ReflectionProbe probe in probes)
            {
                // The name carries the room, and the room names the cubemap - so a rebuild
                // overwrites the same asset rather than accumulating one per build.
                string roomName = probe.name.Replace("_ReflectionProbe", string.Empty);
                string path = $"{TexturesDir}/{roomName}_Reflection.exr";
                if (!Lightmapping.BakeReflectionProbe(probe, path)) continue;

                // THE ASSIGNMENT IS THE POINT, not the bake. The bake writes the .exr and that part
                // always worked - seven correct cubemaps sat on disk for as long as this was broken.
                // What was missing was a reference that survives the save, and on a Custom probe
                // that is this field. Imported explicitly first: the file has just been written
                // underneath the AssetDatabase, and loading it without the import returns null.
                AssetDatabase.ImportAsset(path);
                Cubemap cube = AssetDatabase.LoadAssetAtPath<Cubemap>(path);
                if (cube == null) continue;
                probe.customBakedTexture = cube;
                wired++;
            }

            // Reported as a count against a count, because the failure this exists to catch is a
            // probe that ends up with no cubemap - which renders as a room that looks very slightly
            // flat, and nothing else. If this ever says anything but n/n, the metal will go black.
            Debug.Log($"[SceneBuilder] Reflection probes baked and wired: {wired}/{probes.Length} " +
                      $"({flagged} renderers reflection-probe-static)");
        }

        // WHAT A BAKED PROBE CAPTURES IS STATIC GEOMETRY, AND NOTHING IN THIS SCENE WAS STATIC.
        //
        // This is the bottom of the reflection-probe bug and the last of three separate faults on
        // one feature. The other two - baking before SetupLighting invalidated it, and a Baked probe
        // keeping its cubemap in lighting data this build never generates - were both real, and
        // fixing them still left the objects mirroring a brown default skybox. The reason is that
        // `Lightmapping.BakeReflectionProbe` renders only renderers flagged ReflectionProbeStatic,
        // SceneBuilder creates every object from script and never flagged one, so all seven probes
        // were faithfully capturing an empty world. Proved by assigning the cubemap as the GLOBAL
        // reflection and getting the same brown: the probe was applying, its contents were sky.
        //
        // ONLY the ReflectionProbeStatic flag is set. ContributeGI would put this scene into
        // lightmapping it does not use, and BatchingStatic would change how it draws - neither is
        // being asked for, and a static flag set for the wrong reason is very hard to notice later.
        //
        // MOVERS ARE EXCLUDED, by the components that move them rather than by name. A door baked
        // open, or a plinth baked at the height SceneBuilder authors it at rather than the sunk
        // position it starts the game in, would put a thing in the reflection that is not in the
        // room. Everything else - shell, panels, fixtures, furniture, board - is genuinely fixed.
        private static int MarkReflectionProbeStatic()
        {
            int flagged = 0;
            int skipped = 0;
            Renderer[] renderers = UnityEngine.Object.FindObjectsByType<Renderer>(
                FindObjectsInactive.Include);

            foreach (Renderer r in renderers)
            {
                if (MovesDuringPlay(r.transform)) continue;

                // **CONTRIBUTE GI AS WELL, since 2026-08-25** - and the paragraph above, which used to
                // say ONLY the reflection flag is set, was right at the time and is what changed.
                //
                // Without this there is no bounce light anywhere in the building: a white room lit by
                // four downlights and a constant ambient term, which is most of why it reads as a
                // whitebox. Real white walls throw most of their light back at each other.
                //
                // The flag is inert until something bakes. It marks this renderer as a surface light
                // BOUNCES OFF and is BLOCKED BY - see `BakeLighting`.
                //
                // **BUT NOT ON A MESH WITH NO TRIANGLES, AND THAT IS NOT A NICETY - IT IS WHY CYCLE1
                // COULD NOT BE BAKED.** `chess.glb` ships a mesh named `Material3` with no triangle
                // sub-mesh at all. It bounces nothing and blocks nothing, so leaving it out costs the
                // bake exactly nothing; putting it IN took the Editor down. APV's Virtual Offset pass
                // builds a ray tracing acceleration structure out of every ContributeGI renderer, and
                // `HardwareRayTracingAccelStruct.AddInstance` refuses a mesh with no triangle topology
                // and then registers a zero handle for it anyway - so the second such mesh throws
                // `ArgumentException: An item with the same key has already been added. Key: 0`. That
                // aborts `DefaultVirtualOffset.Initialize` half-built, `Step()` NREs on what it left
                // behind, and the wreckage surfaces much later in `FinalizeBake`, where the real
                // exception is swallowed by a `catch` and the cleanup after it throws out of the bake
                // delegate instead - so `done` is never set and Unity calls the delegate again every
                // tick, forever. 29,757 exceptions and a hung Editor, with the only readable cause
                // 30,000 lines above the noise.
                //
                // **The chess pieces are in Room2West, which is why CYCLE1 ALONE crashed** while
                // IterationRoom and Cycle3 baked in seconds. A scene-shaped symptom with an
                // asset-shaped cause. `docs/gotchas.md`.
                bool bouncesLight = HasTriangles(r);
                if (!bouncesLight) skipped++;

                GameObjectUtility.SetStaticEditorFlags(r.gameObject,
                    bouncesLight
                        ? StaticEditorFlags.ReflectionProbeStatic | StaticEditorFlags.ContributeGI
                        : StaticEditorFlags.ReflectionProbeStatic);

                // **AND IT TAKES ITS GI FROM PROBES, NOT FROM A LIGHTMAP.** That is not a quality
                // compromise here, it is the only option: a lightmap needs a second UV set, and every
                // piece of this building is generated from script - Unity's primitives have no UV2
                // and a generated mesh has whatever it was given. Adaptive Probe Volumes need none,
                // which is why the bake goes that way.
                //
                // It also buys something lightmaps cannot: the ghosts, the carryables and the
                // player's own body sample the same volumes, so a past self walking through a room
                // is lit by that room instead of by a global constant.
                //
                // `receiveGI` is a `MeshRenderer` property, not a `Renderer` one - a skinned mesh has
                // no such choice to make, because it is never lightmapped in the first place. The
                // cast is the test, so nothing here needs to also ask what kind of renderer it is.
                if (r is MeshRenderer mesh) mesh.receiveGI = ReceiveGI.LightProbes;
                flagged++;
            }

            // **SAID OUT LOUD, because the failure it prevents has no other symptom.** A triangle-less
            // mesh that slips back into the GI set does not warn - it hangs the Editor twenty minutes
            // later inside Unity's own code. A count here means the next one is a line in the build
            // log rather than an afternoon.
            if (skipped > 0)
                Debug.Log($"[SceneBuilder] {skipped} renderer(s) held out of ContributeGI - no "
                        + "triangles to bounce light off. See MarkReflectionProbeStatic.");

            return flagged;
        }

        // Whether any probe volume in the project has actually been baked - the question the URP
        // asset's probe system now follows. See `ConfigureUrpAsset`.
        //
        // **REFLECTION, RELUCTANTLY, AND FAILING SAFE.** `ProbeVolumeBakingSet.HasBeenBaked()` is
        // `internal`, the same wall `BakeLighting.EnsureBakingSet` runs into and answers the same way:
        // look the member up, and report rather than assume when it is gone. A Unity version that
        // renames it makes this return false, which pins URP to legacy probes - the state that renders
        // correctly with no bake. The wrong answer in the safe direction.
        // **RETURNS FALSE ON PURPOSE: APV IS OFF** (2026-08-26, after two days of trying it).
        //
        // Everything needed to switch it back on is intact - the volumes are built, the bake works,
        // the data is on disk. This one line is the switch. What it is NOT is an accident, so the
        // reasoning has to live where the switch is:
        //
        // **1. It never lit the walls.** With ambient at zero, so bounce was the only indirect light,
        // the walls measured 13 of 255 and the ceiling 9, against a floor at 100. Converted to
        // linear that is 4.6% of the floor, where form-factor maths for a room this shape says
        // 25-30%. Switching APV on adds +101 to the floor and +166 to a dynamic prop while giving
        // the walls +2 - it piles light where there is already too much. Raising Virtual Offset past
        // the 25mm panels (the best hypothesis for why) changed nothing.
        //
        // **2. The menu background can never match the game while it is on.** `CaptureMenuBackground`
        // renders during the build, before any probe data is loaded, and its output is provably
        // identical with APV on and off. Measured on the same room: capture 81/89/141 against
        // in-game 114/72/181. The title screen would show a room the game does not render, and every
        // lighting tweak widens the gap. **This is the blocker to solve first if APV is retried.**
        //
        // **3. Play preferred it off, three separate times.** That is the strongest evidence here and
        // it outranks the theory.
        //
        // The `LegacyLightProbes` path this falls back to is what the building has always rendered
        // with: direct light from the fixtures plus the Trilight ambient constant.
        private static bool AnyBakedProbeVolumes()
        {
            return false;
#pragma warning disable 162
            MethodInfo baked = typeof(ProbeVolumeBakingSet).GetMethod("HasBeenBaked",
                BindingFlags.Instance | BindingFlags.NonPublic);
            if (baked == null)
            {
                Debug.LogWarning("[SceneBuilder] ProbeVolumeBakingSet.HasBeenBaked is gone - this "
                               + "Unity version has moved the API. Assuming no baked probe data.");
                return false;
            }

            foreach (string guid in AssetDatabase.FindAssets("t:ProbeVolumeBakingSet"))
            {
                var set = AssetDatabase.LoadAssetAtPath<ProbeVolumeBakingSet>(
                    AssetDatabase.GUIDToAssetPath(guid));
                if (set != null && baked.Invoke(set, null) is true) return true;
            }

            return false;
#pragma warning restore 162
        }

        // Whether a renderer has a surface the GI bake can actually use.
        //
        // **ASKED OF THE SUB-MESH TOPOLOGY, not the triangle count**, because that is the question
        // the ray tracing structure asks: a mesh can carry lines or points, report plenty of
        // vertices, and still have nothing to intersect. `GetTopology` reads the sub-mesh descriptor
        // rather than the index buffer, so it does not need the mesh to be readable - which matters,
        // since the imported `.glb` meshes are not.
        //
        // A renderer with no mesh at all (a line, a trail, a particle system) answers false, which is
        // the right answer for the same reason: nothing for light to bounce off.
        private static bool HasTriangles(Renderer r)
        {
            Mesh mesh = null;
            if (r is SkinnedMeshRenderer skinned) mesh = skinned.sharedMesh;
            else if (r.TryGetComponent(out MeshFilter filter)) mesh = filter.sharedMesh;

            if (mesh == null) return false;

            for (int i = 0; i < mesh.subMeshCount; i++)
                if (mesh.GetTopology(i) == MeshTopology.Triangles) return true;

            return false;
        }

        // Walks up, because the thing that moves is usually a parent of the thing that renders - a
        // door's slab, a plinth's key, a ghost's mesh.
        private static bool MovesDuringPlay(Transform t)
        {
            while (t != null)
            {
                // BEFORE the Door test, because a gate leaf carries both and this is the exception
                // to that rule rather than a separate case - see WallWhileShut for the argument.
                if (t.GetComponent<WallWhileShut>() != null) return false;

                if (t.GetComponent<CarryableItem>() != null) return true;
                if (t.GetComponent<Door>() != null) return true;
                if (t.GetComponent<RewardPlinth>() != null) return true;
                if (t.GetComponent<Balloon>() != null) return true;
                if (t.GetComponent<Drawer>() != null) return true;
                if (t.GetComponent<GhostReplayer>() != null) return true;
                // The cover over a cycle's way out. Authored closed and slid aside at the boundary,
                // so baked in it would leave a shut floor in every reflection of a room the player is
                // standing in with it open.
                if (t.GetComponent<CycleExit>() != null) return true;
                // ROOM2-5'S POOL, both halves of it. The balls drift, so a baked one is a ball frozen
                // where it was authored rather than where it floats; and the water itself is a
                // transparent surface that is reflecting the probe - baking it in would put the room's
                // reflection of the water inside the water's reflection of the room.
                if (t.GetComponent<WaterPool>() != null) return true;
                if (t.GetComponent<FloatingBalls>() != null) return true;
                // ROOM2-6'S VALVES AND ITS DRAIN. The wheels turn, the cover slides aside and the
                // funnel appears - all three baked into a probe would put a shut drain and a still
                // wheel in the reflection of a room the player has just changed.
                if (t.GetComponent<Valve>() != null) return true;
                if (t.GetComponent<PoolDrain>() != null) return true;
                // The gas. A particle system baked into a probe would put vapour in the reflection
                // of a room that has not been gassed yet.
                if (t.GetComponent<ParticleSystem>() != null) return true;
                if (t.CompareTag("Player")) return true;
                t = t.parent;
            }
            return false;
        }

        // THE CEILING, AND IT IS NOT THE FLOOR. They shared `floorMat` until 2026-08-20 - both are
        // white slabs, which is fair - and they are lit from opposite ends: the floor is directly
        // under four spots and the ceiling faces AWAY from every one of them, lit by ambient alone.
        // The albedo that stops one clipping is the albedo that kills the other.
        //
        // So: 1.0, the wall's own brightness, because a ceiling needs everything it can get.
        //
        // SMOOTHNESS 0.3, UP FROM 0 - settled 2026-08-20. The argument for
        // 0 was that there is nothing above a ceiling to reflect, so a specular response there is a
        // highlight of nothing. What that missed is the same thing the floor was fixed for: with no
        // direct light on it at all (the spots point down) and ambient ground as its only term, a
        // ceiling at smoothness 0 is a CONSTANT field across the whole slab - the grain cannot show,
        // because trilight's ground and equator are 0.075 apart and perturbing the normal moves it by
        // under a percent. 0.3 lets the probe put a faint gradient on it, which is the one thing that
        // can give it shape without touching how bright it is.
        //
        // Cached because it is asked for once per room and `MakeNoiseNormalMap` regenerates its
        // texture on every call rather than loading it.
        private static Material ceilingMaterial;

        private static Material CeilingMaterial()
        {
            if (ceilingMaterial != null) return ceilingMaterial;

            ceilingMaterial = MakeColorMaterial("CeilingWhite", PanelLitColor);
            // The floor's grain, at the floor's scale. It is the same slab built the same way; at the
            // 0.3 above it shows in the diffuse as the faint tooth a painted ceiling has, and now also
            // breaks up the probe's reflection so that reflection is not a second flat field.
            ApplySurfaceDetail(ceilingMaterial, MakeNoiseNormalMap("SurfaceGrain", 512, 2.5f),
                               1.8f, new Vector2(26f, 30f), 0.3f);
            return ceilingMaterial;
        }

        private static Material MakeEmissiveMaterial(string name, Color color, float emission)
        {
            string path = $"{MaterialsDir}/{name}.mat";
            Material mat = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (mat == null)
            {
                mat = new Material(OpaqueShader());
                AssetDatabase.CreateAsset(mat, path);
            }

            mat.shader = OpaqueShader();
            mat.color = color;
            SetSmoothness(mat, 0.1f);

            // The keyword matters as much as the colour: set _EmissionColor alone and URP leaves
            // the emission pass compiled out, so the panel renders as plain white.
            mat.EnableKeyword("_EMISSION");
            mat.SetColor("_EmissionColor", color * emission);

            // **REALTIME, WHICH IN THIS PROJECT MEANS "CONTRIBUTES NOTHING TO THE BAKE" - AND THAT
            // IS CORRECT, BECAUSE THE FIXTURE IS ALREADY IN THE BAKE AS A LIGHT.**
            //
            // Every ceiling fixture is TWO objects: this emissive panel, which is what you see, and a
            // spot light at `CeilingLightIntensity` inside it, which is what lights the room. They
            // are one physical thing modelled twice, so exactly one of them may contribute to GI.
            //
            // Switching this to `BakedEmissive` (2026-08-26) made both contribute, and the result was
            // a room lit about twice over: a 1.4m panel radiating 3.5 - three and a half times white -
            // stacked on top of a spot at 10.5. **It did not show up immediately**, because at the
            // time the probe volume was being deleted by every rebuild, so no baked data reached the
            // screen at all. The moment `EnsureProbeVolume` fixed that, the double count arrived with
            // it: play reported the bed blown to 255 across its whole frame and the calibration room
            // clipped to pure white, while APV switched off looked correct.
            //
            // **The panel is a light FIXTURE, not a light.** If these are ever to be real area
            // sources - which is the right fix for the hard-edged shadows `docs/rendering-notes.md`
            // complains about - the spot lights have to come out at the same time, and `ShadowBudget`
            // needs a different answer, since a baked emissive surface has no runtime shadow to
            // switch.
            mat.globalIlluminationFlags = MaterialGlobalIlluminationFlags.RealtimeEmissive;

            EditorUtility.SetDirty(mat);
            return mat;
        }

        // A POLISHED, COLOURED METAL with a glow still in it. The three escape objects wear this and
        // nothing else does.
        //
        // They were flat emissive at 2.4 with smoothness 0.1, which is a matte object with the light
        // turned up inside it: no highlight anywhere on the surface, the middle blown out to near
        // white, and the colour only readable at the silhouette. Three of those on a console read as
        // three coloured blocks rather than as the things the whole run was spent collecting.
        //
        // EVERY NUMBER HERE WAS RENDERED AND LOOKED AT, not reasoned to, and the first three
        // attempts were worse than what they replaced. What each one is and what it cost to find:
        //
        // - METALLIC 0.9. The project rule says a pure metal renders BLACK here, and that rule is a
        //   symptom: a metal is entirely reflection, and every reflection probe in this scene had a
        //   NULL baked texture, so a metal had nothing to be. Baking the probes (see
        //   BakeReflectionProbes) is what makes this value available at all. At 0.8 with an EMPTY
        //   probe the object came out darker and deader than the flat colour it replaced - worth
        //   knowing, because that is what this looks like if the bake ever silently breaks again.
        // - SMOOTHNESS 0.97, near-mirror, and this is the one that does the work. The obvious
        //   setting is the 0.85-0.88 the walls use, and it is wrong for a small object: at that
        //   roughness a featureless white room blurs into a flat wash and the thing reads as
        //   plastic. Near-mirror instead resolves the CEILING FIXTURES as two distinct bright
        //   shapes on the top face, which is the only structure this white box has to offer - and
        //   structure is what the eye reads as metal.
        // - REFLECTANCE IS THE ACCENT LIFTED 30% TOWARD WHITE, not the accent itself. Base colour
        //   means something different on a metal: it is what the surface reflects, not what it is
        //   painted. A real coloured metal's reflectance is high (gold is ~1.0/0.77/0.34), so
        //   feeding in a display colour like 0.16/0.40/0.95 gives a dark, muddy mirror. The lift
        //   keeps the hue - these three are told apart by colour, in a hurry, across a console.
        // - EMISSION 0.40, down from 2.4. The ORIGINAL reason for emission stands: each of these
        //   arrives in the same second as the biggest lighting change its room has. But 2.4 blew the
        //   middle out to near-white and left the colour readable only at the silhouette, which is
        //   what made these look like coloured blocks. At 0.40 the metal is what is seen and the
        //   glow is a floor under it - this object cannot go black however the probes behave.
        //
        // Emission takes the ACCENT, not the lifted reflectance: the glow should be the object's own
        // colour at full strength, where the mirror should not.
        private static Material MakePolishedMetalMaterial(string name, Color accent, float emission)
        {
            string path = $"{MaterialsDir}/{name}.mat";
            Material mat = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (mat == null)
            {
                mat = new Material(OpaqueShader());
                AssetDatabase.CreateAsset(mat, path);
            }

            Color reflectance = Color.Lerp(accent, Color.white, 0.30f);

            mat.shader = OpaqueShader();
            mat.color = reflectance;
            if (mat.HasProperty("_BaseColor")) mat.SetColor("_BaseColor", reflectance);
            SetSmoothness(mat, 0.97f);
            if (mat.HasProperty("_Metallic")) mat.SetFloat("_Metallic", 0.9f);

            // The keyword matters as much as the colour: set _EmissionColor alone and URP leaves the
            // emission pass compiled out - the same trap MakeEmissiveMaterial documents.
            mat.EnableKeyword("_EMISSION");
            mat.SetColor("_EmissionColor", accent * emission);
            mat.globalIlluminationFlags = MaterialGlobalIlluminationFlags.RealtimeEmissive;

            EditorUtility.SetDirty(mat);
            return mat;
        }

        // A lit material you can see through. The URP transparent set-up needs all of _Surface,
        // _SrcBlend, _DstBlend and _ZWrite AND the keyword -
        // the blend modes and the _SURFACE_TYPE_TRANSPARENT keyword are BOTH required, and setting
        // the alpha alone leaves the shader opaque - but on Lit rather than Unlit, because unlike a
        // ghost these are real objects in a lit room and have to take the ceiling lights.
        private static Material MakeTranslucentMaterial(string name, Color color, float smoothness)
        {
            string path = $"{MaterialsDir}/{name}.mat";
            Shader lit = OpaqueShader();

            Material mat = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (mat == null)
            {
                mat = new Material(lit);
                AssetDatabase.CreateAsset(mat, path);
            }
            mat.shader = lit;
            mat.color = color;
            if (mat.HasProperty("_BaseColor")) mat.SetColor("_BaseColor", color);
            SetSmoothness(mat, smoothness);

            mat.SetFloat("_Surface", 1f);
            mat.SetFloat("_ZWrite", 0f);
            mat.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");
            mat.DisableKeyword("_ALPHATEST_ON");

            // PREMULTIPLIED alpha, and all three of the keyword, the _Blend enum and the blend
            // factors have to say so together. They did not: the keyword had been on the asset
            // since before the first ship while this forced SrcAlpha, so a scene build left alpha
            // multiplied TWICE and URP's material validator undid it again on the next build-target
            // switch. The Editor showed duller balloons than the player did, and four .mat files
            // turned up modified after every WebGL build.
            //
            // Settled by capture, three ways: premultiplied + One reads as pink translucent
            // balloons; premultiplied + SrcAlpha washes them grey; keyword off makes the bodies
            // very nearly VANISH, because without it the diffuse no longer carries them and only
            // the opaque knots are left. So the keyword stays and everything else follows it.
            mat.EnableKeyword("_ALPHAPREMULTIPLY_ON");
            // _Blend stays 0 (Alpha). Writing 1 (Premultiply) makes URP re-derive the keywords on
            // save and it DISABLES _ALPHAPREMULTIPLY_ON, leaving One blending over non-premultiplied
            // colour - the balloons come out washed toward white. 0 with the keyword forced on is
            // the pairing that has always been on the asset and the one that renders correctly.
            mat.SetFloat("_Blend", 0f);
            mat.SetFloat("_SrcBlend", (float)UnityEngine.Rendering.BlendMode.One);
            mat.SetFloat("_DstBlend", (float)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);
            mat.renderQueue = (int)UnityEngine.Rendering.RenderQueue.Transparent;

            EditorUtility.SetDirty(mat);
            return mat;
        }

        // Clear glass - the cube room's cubes, 2026-08-13. Same transparent set-up
        // MakeTranslucentMaterial uses (both keywords, both blend factors, the premultiplied pairing
        // that actually renders instead of vanishing).
        //
        // `map` IS OPTIONAL AND IS NOW ALWAYS NULL. It used to carry the glyph as an alpha channel,
        // etching the symbol into the six faces; the symbol is a solid core suspended INSIDE the
        // glass now (BuildSymbolCube), so the body is one shared clear material for all six cubes
        // rather than six that differ only in what is printed on them.
        //
        // High smoothness reads as glass here for the same reason it reads as metal on the escape
        // objects: this project has no real refraction, so the ONLY thing selling a hard, clear
        // surface is a sharp reflection with real geometry (the ceiling fixtures) to catch in it -
        // see MakePolishedMetalMaterial and the reflection-probe notes in docs/rendering-notes.md.
        //
        // `tint` is deliberately the SAME colour for all six cubes - see CubeSymbols' own note on
        // "symbols, not colours" for why a per-cube tint would undo the room's one accessibility
        // rule - and its ALPHA is how much glass there is to see through. It came down when the
        // symbol moved inside: the body now has something behind it that has to be read.
        private static Material MakeGlassMaterial(string name, Texture2D map, Color tint, float smoothness)
        {
            string path = $"{MaterialsDir}/{name}.mat";
            Shader lit = OpaqueShader();

            Material mat = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (mat == null)
            {
                mat = new Material(lit);
                AssetDatabase.CreateAsset(mat, path);
            }
            mat.shader = lit;
            mat.color = tint;
            if (mat.HasProperty("_BaseColor")) mat.SetColor("_BaseColor", tint);
            mat.SetTexture("_BaseMap", map);
            mat.mainTexture = map;
            SetSmoothness(mat, smoothness);
            // A flat 0 metallic read as thin, flat plastic wrap rather than a hard cut surface -
            // play called it cheap. Real glass is not a metal, but this project has no refraction
            // (see the note above), so a weak dielectric specular is the wrong tool here for the
            // same reason it is the right one everywhere else: without it, the ceiling fixtures this
            // cube ought to be throwing back barely show up at all. Short of the escape objects' own
            // 0.9 - this still has to read as SEE-THROUGH, and a fully metallic surface would not.
            if (mat.HasProperty("_Metallic")) mat.SetFloat("_Metallic", 0.35f);

            mat.SetFloat("_Surface", 1f);
            mat.SetFloat("_ZWrite", 0f);
            mat.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");
            mat.DisableKeyword("_ALPHATEST_ON");
            mat.EnableKeyword("_ALPHAPREMULTIPLY_ON");
            mat.SetFloat("_Blend", 0f);
            mat.SetFloat("_SrcBlend", (float)UnityEngine.Rendering.BlendMode.One);
            mat.SetFloat("_DstBlend", (float)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);
            mat.renderQueue = (int)UnityEngine.Rendering.RenderQueue.Transparent;

            EditorUtility.SetDirty(mat);
            return mat;
        }

        private static Material MakeColorMaterial(string name, Color color)
        {
            string path = $"{MaterialsDir}/{name}.mat";
            Material mat = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (mat == null)
            {
                mat = new Material(OpaqueShader());
                AssetDatabase.CreateAsset(mat, path);
            }

            mat.shader = OpaqueShader();
            mat.color = color;
            // Matte: the default 0.5 smoothness mirrors the skybox onto the room surfaces.
            SetSmoothness(mat, 0.03f);
            EditorUtility.SetDirty(mat);
            return mat;
        }

        private static GameObject Prim(PrimitiveType type, string name, Transform parent, Vector3 localPos, Vector3 localScale, Material mat = null, bool trigger = false, bool removeCollider = false)
        {
            GameObject go = GameObject.CreatePrimitive(type);
            go.name = name;
            go.transform.SetParent(parent, false);
            go.transform.localPosition = localPos;
            go.transform.localScale = localScale;

            if (mat != null) go.GetComponent<Renderer>().sharedMaterial = mat;

            Collider col = go.GetComponent<Collider>();
            if (removeCollider && col != null) Object.DestroyImmediate(col);
            else if (col != null) col.isTrigger = trigger;

            return go;
        }

        // Instantiates an imported model (Kenney OBJ furniture) and repositions it so its
        // rendered bounds are centered on targetXZCenter with its base sitting at floorY -
        // needed because these models' pivots are at odd mesh corners, not their footprint center.
        // A MODEL HUNG ON SOMETHING, RATHER THAN STOOD ON THE FLOOR.
        //
        // **`PlaceModel` TAKES WORLD COORDINATES** - its `targetXZCenter` and `floorY` are compared
        // against world-space renderer bounds - and that is right for what it was written for: props
        // that stand somewhere in a room at a floor height. It is wrong, silently, for anything
        // mounted on a parent that already carries the position.
        //
        // Passing `Vector3.zero, 0f` to it does not mean "where the parent is". It means the WORLD
        // ORIGIN, which in this project is the middle of Room1 - and that is exactly what happened:
        // nine monitors and three camera housings all landed in cycle 1's bed room, in a heap, in
        // front of the camera that captures the title screen's photograph. The menu turned into a
        // close-up of a CCTV lens and the fault looked nothing like its cause.
        //
        // So this is the mounted version: everything local, centred on a point in the PARENT's frame,
        // sized by its longest side because a downloaded model's units are never the ones wanted.
        private static (GameObject instance, Bounds worldBounds) PlaceModelLocal(
            string assetPath, Transform parent, string name, Vector3 localPosition,
            Quaternion localRotation, float targetLongestSide)
        {
            GameObject source = AssetDatabase.LoadAssetAtPath<GameObject>(assetPath);
            if (source == null)
            {
                Debug.LogError($"[SceneBuilder] no model at {assetPath}");
                return (null, default);
            }

            GameObject instance = (GameObject)PrefabUtility.InstantiatePrefab(source, parent);
            instance.name = name;
            instance.transform.localRotation = localRotation;
            instance.transform.localScale = Vector3.one;
            instance.transform.localPosition = Vector3.zero;

            Bounds bounds = MeasuredBounds(instance);
            float longest = Mathf.Max(bounds.size.x, Mathf.Max(bounds.size.y, bounds.size.z));
            if (targetLongestSide > 0f && longest > 0.0001f)
                instance.transform.localScale = Vector3.one * (targetLongestSide / longest);

            // Re-measured after scaling, then moved so the model's CENTRE lands on the asked-for
            // point. Centre rather than base, because a thing on a wall has no base.
            bounds = MeasuredBounds(instance);
            Vector3 centreInParent = parent != null
                ? parent.InverseTransformPoint(bounds.center)
                : bounds.center;
            instance.transform.localPosition += localPosition - centreInParent;

            return (instance, MeasuredBounds(instance));
        }

        private static Bounds MeasuredBounds(GameObject instance)
        {
            Renderer[] renderers = instance.GetComponentsInChildren<Renderer>();
            if (renderers.Length == 0) return new Bounds(instance.transform.position, Vector3.zero);

            Bounds bounds = renderers[0].bounds;
            for (int i = 1; i < renderers.Length; i++) bounds.Encapsulate(renderers[i].bounds);
            return bounds;
        }

        private static (GameObject instance, Bounds worldBounds) PlaceModel(string objAssetPath, Transform parent, string name, Vector3 targetXZCenter, float floorY, float uniformScale, bool addBoxCollider, Quaternion rotation = default)
        {
            GameObject source = AssetDatabase.LoadAssetAtPath<GameObject>(objAssetPath);
            GameObject instance = (GameObject)PrefabUtility.InstantiatePrefab(source, parent);
            instance.name = name;
            instance.transform.localScale = Vector3.one * uniformScale;
            // Bounds are measured AFTER rotating, so a model authored Z-up or facing the wrong way
            // still lands centred and sitting on the floor.
            instance.transform.localRotation = rotation == default ? Quaternion.identity : rotation;
            instance.transform.localPosition = Vector3.zero;

            Renderer[] renderers = instance.GetComponentsInChildren<Renderer>();
            Bounds bounds = renderers[0].bounds;
            for (int i = 1; i < renderers.Length; i++) bounds.Encapsulate(renderers[i].bounds);

            // THE DELTA IS A WORLD VECTOR AND `localPosition` IS NOT, so it has to be brought into the
            // parent's frame before it is added. That was a no-op for as long as nothing this
            // function places sat under a rotated parent, and the comment on BuildBed said so out
            // loud. Cycle 2 is turned 180 degrees now (see CycleTwoYaw) and the unconverted delta
            // pushed the bed the wrong way down the room by twice its own offset.
            Vector3 delta = new Vector3(targetXZCenter.x - bounds.center.x, floorY - bounds.min.y, targetXZCenter.z - bounds.center.z);
            instance.transform.localPosition += parent != null
                ? parent.InverseTransformVector(delta)
                : delta;
            Vector3 finalCenter = bounds.center + delta;
            Bounds finalBounds = new Bounds(finalCenter, bounds.size);

            if (addBoxCollider)
            {
                BoxCollider box = instance.AddComponent<BoxCollider>();
                box.center = instance.transform.InverseTransformPoint(finalCenter);
                // The bounds are world-axis-aligned, so bring the size back into the instance's
                // own axes before assigning - otherwise a rotated model gets a collider with its
                // height and depth swapped.
                // The instance's WORLD rotation, not its local one - the two differ the moment a
                // parent carries a turn of its own, and `finalBounds` is world-axis-aligned.
                Vector3 localSize = Quaternion.Inverse(instance.transform.rotation) * finalBounds.size;
                box.size = new Vector3(Mathf.Abs(localSize.x), Mathf.Abs(localSize.y), Mathf.Abs(localSize.z)) / uniformScale;
            }

            return (instance, finalBounds);
        }

        // A WALL-MOUNTED SWITCH, wired to one ceiling fixture. `localPosition` is the point on the
        // wall it mounts flush against; `yaw` turns it to face into the room - 90 for a west wall
        // (faces +X), -90 for an east wall (faces -X). Everything under the holder is authored with
        // +Z pointing into the room, so no builder below has to know which wall it is on.
        private static LightSwitch BuildLightSwitch(Transform parent, string name, Vector3 localPosition,
                                                     float yaw, Light light, Renderer panel,
                                                     Material litFixtureMat, Material darkFixtureMat)
        {
            GameObject holder = new GameObject(name);
            holder.transform.SetParent(parent, false);
            holder.transform.localPosition = localPosition;
            holder.transform.localRotation = Quaternion.Euler(0f, yaw, 0f);

            // BUILT, NOT IMPORTED, and for the same reason the nightstand is: there is nothing to
            // animate in the model. `old_light_switch.glb` merges its plate and its lever into ONE
            // mesh, so "flip the switch" could only ever tilt the whole wall plate - which had to be
            // held down to 6 degrees to stop it reading as the plate coming off the wall, and at 6
            // degrees it reads as nothing at all. Two boxes and an empty give a lever that moves on
            // its own, and every number below is a number rather than a measurement off someone
            // else's topology.
            Material plateMat = MakeColorMaterial("SwitchPlate", new Color(0.90f, 0.90f, 0.88f));
            Material leverMat = MakeColorMaterial("SwitchLever", new Color(0.80f, 0.79f, 0.76f));

            // THE PLATE'S SIZE WAS SET BY HAND IN THE EDITOR and read back off the scene, which is why
            // these are not round numbers - 200 x 320 x 25mm, a good deal larger than the 90 x 150 this
            // started at. A domestic plate is correct and was too small to find across a dark room,
            // which is the only thing this fixture has to do before it is pressed.
            const float plateW = 0.19954f, plateH = 0.31926f, plateT = 0.0252f;
            Prim(PrimitiveType.Cube, "Plate", holder.transform, new Vector3(0f, 0f, plateT / 2f),
                new Vector3(plateW, plateH, plateT), plateMat, removeCollider: true);

            // THE LEVER TURNS ABOUT THIS, and the pivot is an empty rather than the lever itself so
            // the tilt happens at the plate face - a box rotated about its own centre would sink half
            // its body into the plate on the way over. Sat exactly on the plate's front face, so the
            // lever swings across it rather than through it.
            GameObject pivot = new GameObject("LeverPivot");
            pivot.transform.SetParent(holder.transform, false);
            pivot.transform.localPosition = new Vector3(0f, 0f, plateT);
            // AUTHORED IN THE OFF POSITION, tilted half of the throw. `LightSwitch` reads this pose as
            // "off" in Awake and takes the whole `flipAngle` from it, so the two ends come out
            // symmetrical about the plate - a lever that sat flat when off would not read as a toggle
            // at all, it would read as a switch with nothing in it.
            pivot.transform.localRotation = Quaternion.Euler(-15f, 0f, 0f);

            // Hung BELOW the pivot, so the pivot is the hinge at the top of the throw. Also measured
            // off the placed switch rather than chosen.
            Prim(PrimitiveType.Cube, "Lever", pivot.transform, new Vector3(0f, -0.0116f, 0.0104f),
                new Vector3(0.04545f, 0.08116f, 0.03246f), leverMat, removeCollider: true);

            // WHERE THE E DISC HANGS. Its own object, because the prompt has to sit ON the switch and
            // the lever pivot is at the plate's face - anchored there the disc drew low, under the
            // fixture it was labelling. Level with the plate's centre and clear of its face.
            GameObject anchor = new GameObject("HintAnchor");
            anchor.transform.SetParent(holder.transform, false);
            anchor.transform.localPosition = new Vector3(0f, 0f, plateT + 0.06f);

            // REACH, and it was far too tight: 0.6 x 0.6 x 0.5 centred ON the wall put most of the
            // volume inside the wall, so the half in front of it was about 250mm deep and the player
            // had to stand against the switch to press it. Pushed out into the room and made roughly
            // a person's reach - the volume is tested against the player's own bounds, so this is
            // "close enough to touch it", not "close enough to see it".
            BoxCollider trigger = holder.AddComponent<BoxCollider>();
            trigger.isTrigger = true;
            trigger.center = new Vector3(0f, 0f, 0.85f);
            trigger.size = new Vector3(1.7f, 2.4f, 1.8f);

            LightSwitch lightSwitch = holder.AddComponent<LightSwitch>();
            lightSwitch.switchVisual = pivot.transform;
            lightSwitch.hintAnchor = anchor.transform;
            lightSwitch.controlledLight = light;
            lightSwitch.controlledPanel = panel;
            lightSwitch.litMaterial = litFixtureMat;
            lightSwitch.darkMaterial = darkFixtureMat;
            // Positional, and that is the point rather than a detail: the room is dark and the switches
            // are on two walls, so the click is how you know WHICH one a past self just threw.
            lightSwitch.audioSource = MakeSource(holder.transform, "SwitchAudio", spatialBlend: 1f, volume: 0.8f);
            lightSwitch.onClip = LoadClip(SfxDir, "sfx_switch_on");
            lightSwitch.offClip = LoadClip(SfxDir, "sfx_switch_off");

            return lightSwitch;
        }

        // ROOM2-2'S TWO TAPS, one on the west wall and one standing on the floor. Press E at either to
        // turn it: the water shows, and pressing again shuts it off.
        //
        // NOT YET A GhostInteractable, so a past self cannot turn one on for you the way it can a
        // light switch. That is the next thing this wants, not an oversight to leave unsaid.
        //
        // `a_water_tap.glb` IS NO LONGER USED and nothing loads it. It was a floor-to-ceiling pipe with
        // a small hook two metres up, which at any scale that fits the room read as a thin column
        // standing in a corner - play reported it as "a water column in the middle" and, separately, as
        // the tap being missing. Those were the same observation twice, and no placement fixes a model
        // that has no body and no handle.
        private static WaterTap[] BuildWaterTap(Transform parent)
        {
            // BOTH PLACED BY HAND IN THE EDITOR AND READ BACK OFF THE SCENE, which is why none of these
            // is a round number. What was thrown away in the transfer is a degree or two of X tilt on
            // each - free-rotating with the gizmo picks that up, and a tap leaning off a wall is a
            // slip rather than a decision.
            //
            // The mixer hangs off the west wall. Its pivot sits well behind the wall face because the
            // model's body is authored ~0.09 in front of its own origin, and at this scale that is
            // more than half a metre.
            WaterTap wall = BuildWallMixer(parent, "WallTap", new Vector3(-4.311f, 1.979f, -1.600f), yaw: 90f);

            // TWO MORE, ON THE WALLS THAT HAD NONE. Same fixture, mirrored onto the east wall and hung
            // on the north one, each `WallMixerReach` in front of its own wall face so its stand sits
            // where the water lands (see the stands in BuildCycleTwoShell).
            //
            // FOUR TAPS IS A DIFFICULTY CHANGE, not decoration: the tank takes four bucketloads and
            // there are four buckets, so the room can now in principle be filled by four hands at
            // once. One player still cannot - they can only carry one bucket at a time - which is the
            // gap the past selves fill, and widening it is what makes room2-2 land sooner in a run
            // rather than easier within an iteration.
            //
            // The south wall is left bare on purpose: it carries the doorway out and, since the tank
            // moved beside it, the only other thing in the room worth looking at.
            WaterTap east = BuildWallMixer(parent, "EastTap", new Vector3(4.311f, 1.979f, 1.600f), yaw: 270f);
            WaterTap north = BuildWallMixer(parent, "NorthTap", new Vector3(-2.400f, 1.979f, 5.186f), yaw: 180f);

            // ~~And the standing one, out on the floor~~ REPLACED 2026-08-15 by a fourth wall mixer, on
            // the south wall. `boiling_water_tap` was a gooseneck standing in the middle of the floor,
            // and it was the odd one out in three ways at once: it was the only fixture in the room the
            // player could walk into, the only one whose stand was not against a wall (so the walking
            // line between the taps ran through it), and the only one that read as a free-standing
            // appliance rather than as the building's plumbing.
            //
            // One per wall now. The south wall carries the doorway and the tank, so this hangs on its
            // far side - the +X half, which the tank leaves clear.
            //
            // What is lost with it is a turning HANDLE: that import kept its parts as separate nodes
            // (`Water Knob_5` and the rest) while the mixer is one merged mesh, so the mixers animate
            // through a lever cut out of their own geometry instead. `BuildOneTap` still takes
            // `handleNode` and `spoutHeightFraction` for whatever model wants them next.
            WaterTap south = BuildWallMixer(parent, "SouthTap", new Vector3(2.500f, 1.979f, -5.186f), yaw: 0f);

            // ORDER IS A WIRE FORMAT. `taps[0]` and `taps[1]` are what the two original stands are
            // wired to, and the array's order is also its order in `ghostInteractables` - so the two
            // added ones stay APPENDED (CLAUDE.md §1.6) rather than slotted in beside the mixer they
            // are copies of, and the south mixer takes over slot 1 from the floor tap it replaced.
            return new[] { wall, south, east, north };
        }

        // THE WALL MIXER, and there are three of them now. Every number here was measured once against
        // the west one and is shared rather than re-typed, so a change to the spout nudge or the lever
        // split lands on all three instead of on whichever copy someone remembers.
        private static WaterTap BuildWallMixer(Transform parent, string name, Vector3 localPosition, float yaw)
        {
            return BuildOneTap(parent, name, $"{FurnitureDir}/modern_faucet_high_poly.glb",
                localPosition, yaw: yaw, scale: 6.4296f,
                spoutHeightFraction: 0f,
                // Nudged by hand after looking at it: the measured outlet is the lowest, front-most
                // point of the bounds, and on this model that lands a little low and a little proud of
                // where the water actually leaves. Applied to the SPOUT rather than to the flow root,
                // which matters - the root carries the puddle too, and moving that up would float the
                // spill ten centimetres above the floor.
                //
                // In the HOLDER's own frame, which is what lets one set of numbers serve three walls:
                // `yaw` turns the holder, and the nudge turns with it.
                spoutNudge: new Vector3(0f, 0.101f, -0.107f),
                handleNode: null,
                // This model has no handle NODE, so one is cut out of its mesh: above y = 0.04 the
                // geometry is the lever and nothing else. The hinge is at the back of that cluster.
                leverSplitY: 0.040f,
                leverPivotLocal: new Vector3(0f, 0.040f, 0.060f));
        }

        // CUTS A LEVER OFF A MERGED MESH, so a tap whose handle is welded to its body can still be
        // turned.
        //
        // `modern_faucet_high_poly` arrives as one node with one 39,000-vertex mesh: there is no handle
        // to animate, and turning the whole fixture swings it off the wall. But the lever is not mixed
        // INTO the body, it just shares a mesh with it - the vertices above the spout's dome are a
        // separate cluster in space (checked before writing this: above y = 0.04 the geometry narrows
        // to a band at z 0.045..0.156, which is the lever and nothing else). So the split is a plane.
        //
        // BY TRIANGLE CENTROID, not by vertex: classifying vertices would tear any triangle that
        // straddles the cut and leave a hole. A whole triangle goes one way or the other, so the two
        // meshes tile exactly as the original did, and the seam sits inside the body's dome where it
        // cannot be seen.
        private static (Mesh body, Mesh lever) SplitMeshAtHeight(Mesh source, string assetPrefix, float splitY)
        {
            string bodyPath = GeneratedDir + "/" + assetPrefix + "_Body.mesh";
            string leverPath = GeneratedDir + "/" + assetPrefix + "_Lever.mesh";
            Mesh cachedBody = AssetDatabase.LoadAssetAtPath<Mesh>(bodyPath);
            Mesh cachedLever = AssetDatabase.LoadAssetAtPath<Mesh>(leverPath);
            if (cachedBody != null && cachedLever != null) return (cachedBody, cachedLever);

            Vector3[] verts = source.vertices;
            Vector3[] norms = source.normals;
            Vector2[] uvs = source.uv;
            int[] tris = source.triangles;

            var bodyTris = new System.Collections.Generic.List<int>();
            var leverTris = new System.Collections.Generic.List<int>();
            for (int i = 0; i < tris.Length; i += 3)
            {
                float cy = (verts[tris[i]].y + verts[tris[i + 1]].y + verts[tris[i + 2]].y) / 3f;
                var target = cy > splitY ? leverTris : bodyTris;
                target.Add(tris[i]); target.Add(tris[i + 1]); target.Add(tris[i + 2]);
            }

            // BOTH KEEP THE FULL VERTEX ARRAY. Compacting it would mean remapping every index for a
            // saving that does not matter here - the mesh is written once at build time and the unused
            // vertices are never submitted, because no triangle references them.
            Mesh body = new Mesh { name = assetPrefix + "_Body", indexFormat = source.indexFormat };
            body.vertices = verts; body.normals = norms; body.uv = uvs;
            body.SetTriangles(bodyTris, 0);
            body.RecalculateBounds();

            Mesh lever = new Mesh { name = assetPrefix + "_Lever", indexFormat = source.indexFormat };
            lever.vertices = verts; lever.normals = norms; lever.uv = uvs;
            lever.SetTriangles(leverTris, 0);
            lever.RecalculateBounds();

            if (!Directory.Exists(GeneratedDir)) Directory.CreateDirectory(GeneratedDir);
            AssetDatabase.CreateAsset(body, bodyPath);
            AssetDatabase.CreateAsset(lever, leverPath);
            AssetDatabase.SaveAssets();

            Debug.Log($"[SceneBuilder] {assetPrefix}: lever split at y={splitY:0.###} - "
                    + $"{bodyTris.Count / 3} body triangles, {leverTris.Count / 3} lever triangles.");
            return (AssetDatabase.LoadAssetAtPath<Mesh>(bodyPath), AssetDatabase.LoadAssetAtPath<Mesh>(leverPath));
        }

        // A GENERATED MESH HAS TO LIVE SOMEWHERE, and the water shipped once without knowing it.
        //
        // A `Mesh` built at edit time and assigned straight to a scene object is GONE when the scene is
        // reloaded - the reference serialises, the mesh does not, and the object comes back with
        // `MeshFilter.sharedMesh == null`. It looks like the water simply failing to render, which is
        // exactly how it was found. `RingShardMesh` and `BevelledPrismMesh` already write to
        // `GeneratedDir` for this reason; this is the same thing with the build step factored out, so
        // the next generated mesh cannot repeat it.
        //
        // ALSO A CACHE. Rebuilt only when the asset is missing, so a rebuild does not re-author four
        // meshes it already has - and the name carries the tap, since the two streams differ by seed.
        private static Mesh SaveGeneratedMesh(string assetName, System.Func<Mesh> build)
        {
            string path = GeneratedDir + "/" + assetName + ".mesh";
            Mesh existing = AssetDatabase.LoadAssetAtPath<Mesh>(path);
            if (existing != null) return existing;

            Mesh mesh = build();
            mesh.name = assetName;
            if (!Directory.Exists(GeneratedDir)) Directory.CreateDirectory(GeneratedDir);
            AssetDatabase.CreateAsset(mesh, path);
            AssetDatabase.SaveAssets();
            return AssetDatabase.LoadAssetAtPath<Mesh>(path);
        }

        // ROOM2-2'S TANK: a glass column that has to be filled to a mark before its door will open.
        //
        // THE NUMBERS ARE THE PUZZLE, so they live here rather than on the component (CLAUDE.md §2).
        // With `fillPerTapPerSecond` at 0.009 and a target of 0.75:
        //
        //   one tap  -> 0.75 / 0.009      = 83 seconds. LONGER THAN THE LOOP. Cannot be done.
        //   two taps -> 0.75 / 0.018      = 42 seconds. Comfortably inside it, with time to walk.
        //
        // So the room cannot be solved by one person however well they play it, and is easy the moment
        // a past self is running the other tap. That gap IS the design - see WaterTank.
        //
        // The 42 seconds assumes both taps open at the start of the iteration, which the player cannot
        // do alone: they are at opposite ends of the room. What they can do is open one, let the
        // iteration end, and arrive next time to find that self already opening it.
        private static WaterTank BuildWaterTank(Transform parent, Material propMat)
        {
            // WIDER AND SHORTER THAN IT WAS (2.2m tall, 0.45 radius). A narrow column that height
            // reads as a pipe rather than as a vessel, and it put the target mark at 1.77m - above
            // a 1.6m eye, so the one thing in the room the player is aiming at was sighted upward at
            // arm's length. Squat and broad, the waterline is a surface seen from above rather than
            // an edge seen side-on, and the mark lands at chest height.
            const float innerHeight = 1.45f;
            const float radius = 0.72f;
            const float targetLevel = 0.75f;
            // The plinth's top, and where the water therefore starts. Named because `WaterTank` needs
            // the same number to put its column in the right place - see WaterTank.baseLocalY.
            const float baseY = 0.12f;
            // How far the plinth oversails the glass. Named because the PLINTH is the widest part of
            // this object, so it - not the glass - is what has to clear the doorway below.
            const float baseSpread = 2.3f;
            const float baseRadius = radius * baseSpread / 2f;

            GameObject tank = new GameObject("WaterTank");
            tank.transform.SetParent(parent, false);

            // BESIDE THE WAY OUT, ON ITS RIGHT - not in the middle of the floor, where it stood until
            // 2026-08-15. A vessel this wide in the centre of the room is something to walk around on
            // every trip between the two taps, and it put the thing the player is filling behind them
            // for most of the errand.
            //
            // DERIVED FROM THE DOORWAY rather than typed: room2-2 leaves by its SOUTH wall (`Door2_2`
            // is built at yaw 180), and a player walking at that door has -X on their right. So the
            // tank sits half a doorway plus its own PLINTH off the centre line, and that plinth in
            // from the wall, with a hand's clearance on both - which keeps the door's swept width
            // clear whatever `DoorWidth` or the tank's own size later become.
            const float clearance = 0.4f;
            tank.transform.localPosition = new Vector3(
                -(DoorWidth / 2f + baseRadius + clearance),
                0f,
                -(RoomDepth / 2f - baseRadius - clearance));

            // A plinth, so the glass is not growing out of the floor and the waterline starts at a
            // height the player can read without crouching.
            Prim(PrimitiveType.Cylinder, "Base", tank.transform, new Vector3(0f, 0.06f, 0f),
                new Vector3(baseRadius * 2f, 0.06f, baseRadius * 2f), propMat, removeCollider: true);

            // THE GLASS. Translucent rather than the water shader: this is a container and has to read
            // as a hard surface with the water clearly INSIDE it, so it wants no refraction of its own
            // fighting the column's.
            Material glassMat = MakeTranslucentMaterial("TankGlass", new Color(0.86f, 0.92f, 0.95f, 0.16f), 0.94f);
            // OPEN AT THE TOP AND HOLLOW, which a primitive cylinder cannot be: it is capped at both
            // ends and its collider is a capsule filling the whole volume. As a tank that made it a
            // solid lump with a lid - water was poured into a closed vessel and the inside was
            // somewhere that did not exist.
            //
            // The Y scale is no longer halved: a primitive cylinder is two units tall and
            // `WaterMeshes.Tube` is one.
            GameObject glass = new GameObject("Glass");
            glass.transform.SetParent(tank.transform, false);
            glass.transform.localPosition = new Vector3(0f, baseY + innerHeight / 2f, 0f);
            glass.transform.localScale = new Vector3(radius * 2f, innerHeight, radius * 2f);
            // Wall thickness is a fraction of the UNIT radius (0.5), so 0.045 comes out at 6.5cm of
            // glass at this size - thick enough for the rim to be a visible edge from standing height.
            Mesh tube = SaveGeneratedMesh("TankGlassTube",
                () => WaterMeshes.Tube(segments: 48, wallThickness: 0.045f));
            glass.AddComponent<MeshFilter>().sharedMesh = tube;
            glass.AddComponent<MeshRenderer>().sharedMaterial = glassMat;

            // SOLID WALL, EMPTY MIDDLE. Still a collider, unlike most props here - this is a real
            // object standing in a room people walk through, and walking through a glass tank would
            // say it is not really there - but the collider is now the WALL rather than the volume, so
            // the inside is a place. Non-convex, which is legal because nothing ever moves it.
            MeshCollider shell = glass.AddComponent<MeshCollider>();
            shell.sharedMesh = tube;
            shell.convex = false;

            // THE WATER, inside the glass and a little narrower so the two surfaces never z-fight.
            Material waterMat = AssetDatabase.LoadAssetAtPath<Material>("Assets/Materials/WaterStream.mat");
            GameObject body = new GameObject("Water");
            body.transform.SetParent(tank.transform, false);
            body.transform.localPosition = new Vector3(0f, baseY, 0f);
            body.transform.localScale = new Vector3(radius * 1.94f, 0.0001f, radius * 1.94f);
            body.AddComponent<MeshFilter>().sharedMesh = PrimitiveMesh(PrimitiveType.Cylinder);
            body.AddComponent<MeshRenderer>().sharedMaterial = waterMat;

            // THE MARK the player is filling to. Without it the target is invisible and the puzzle is
            // "keep going and hope" - which is not a puzzle, it is a wait.
            //
            // RED, AND DRAWN ON THE GLASS. It was yellow and stood 4cm proud of the tube, which made
            // it a shelf bolted round the tank rather than a line marked on it - and yellow against a
            // pale blue column is the same warm-on-cool contrast the ceiling fixtures already own, so
            // it read as lighting rather than as instruction. Red belongs to nothing else in this
            // building, and a band that hugs the glass reads as a graduation on the vessel.
            //
            // Emission is higher than the yellow's for the same apparent brightness: red is the
            // dimmest primary to the eye, and matching a number here would not match what is seen.
            // A BAND, NOT A DISC. A primitive cylinder has a top and a bottom face, so however thin it
            // was scaled it stayed a plate bolted round the tank - and from above the whole lid of it
            // was in view. `WaterMeshes.Band` is that cylinder's WALL and nothing else: a line drawn
            // round the vessel, which is what a graduation is.
            Material markMat = MakeEmissiveMaterial("TankMark", new Color(1f, 0.16f, 0.12f), 2.4f);
            GameObject mark = new GameObject("TargetMark");
            mark.transform.SetParent(tank.transform, false);
            mark.transform.localPosition = new Vector3(0f, baseY + innerHeight * targetLevel, 0f);
            // Barely proud of the glass (radius * 2 is the tube itself). The band mesh is one unit
            // tall, so the Y scale IS the height of the line in metres.
            mark.transform.localScale = new Vector3(radius * 2.045f, 0.038f, radius * 2.045f);
            mark.AddComponent<MeshFilter>().sharedMesh =
                SaveGeneratedMesh("TankMarkBand", () => WaterMeshes.Band(segments: 48));
            mark.AddComponent<MeshRenderer>().sharedMaterial = markMat;

            // WHAT THE PLAYER IS AIMING AT: the mark, which is the thing they are actually looking at
            // when they carry a bucket over. The tank's own transform is on the floor - see
            // WaterTank.aimAnchor.
            GameObject aim = new GameObject("Aim");
            aim.transform.SetParent(tank.transform, false);
            aim.transform.localPosition = new Vector3(0f, baseY + innerHeight * targetLevel, 0f);

            WaterTank comp = tank.AddComponent<WaterTank>();
            comp.aimAnchor = aim.transform;
            comp.waterBody = body.transform;
            comp.innerHeight = innerHeight;
            comp.targetLevel = targetLevel;
            // The plinth the glass stands on. Without it the column fills from the tank's ORIGIN,
            // which is the floor, and the waterline sits this far below the mark it is being
            // compared against - see WaterTank.baseLocalY.
            comp.baseLocalY = baseY;

            // WHERE A POUR IS RECORDED. Not a socket: pouring hands nothing over, so there is no
            // custody change for `CarryKind.Surrender` to carry, and without this a past self walks
            // to the tank with a full bucket and stands there. See PourPoint.
            PourPoint pour = tank.AddComponent<PourPoint>();
            pour.tank = comp;
            pour.bucketItemId = BucketItemId;
            comp.pourPoint = pour;
            // A fifth of the tank per bucket, against a target of 0.75 - so FOUR full bucketloads open
            // the door. Four is chosen against the minute rather than picked: a bucket takes 14s under
            // a tap and the round trip to the tank is a few seconds more, so one iteration delivers
            // about two. The room therefore needs a past self running the other tap and the other
            // bucket, which is the whole reason it is here.
            comp.bucketFraction = 0.2f;
            return comp;
        }

        // A PLACE TO STAND A BUCKET, under a tap, wired to the tap that fills it. See BucketStand for
        // why the spot is named rather than "anywhere under falling water".
        private static void BuildBucketStand(Transform parent, string name, WaterTap tap, Vector3 localPosition)
        {
            GameObject stand = new GameObject(name);
            stand.transform.SetParent(parent, false);
            stand.transform.localPosition = localPosition;

            // A shallow tray, so the spot is visibly A SPOT rather than a patch of floor the player is
            // supposed to guess at.
            Material trayMat = MakeColorMaterial("BucketTray", new Color(0.55f, 0.56f, 0.58f));
            Prim(PrimitiveType.Cylinder, "Tray", stand.transform, new Vector3(0f, 0.015f, 0f),
                new Vector3(0.62f, 0.015f, 0.62f), trayMat, removeCollider: true);

            GameObject seat = new GameObject("Seat");
            seat.transform.SetParent(stand.transform, false);
            seat.transform.localPosition = new Vector3(0f, 0.03f, 0f);

            // WHAT THE PLAYER IS AIMING AT - roughly where a bucket standing here would be, rather
            // than the tray it stands on. See BucketStand.aimAnchor: at floor level the target point
            // fell below the screen the moment the player walked up to it.
            GameObject aim = new GameObject("Aim");
            aim.transform.SetParent(stand.transform, false);
            aim.transform.localPosition = new Vector3(0f, 0.45f, 0f);

            // WHERE AN OVERFLOWING PAIL PUTS THE WATER. A full bucket under a running tap spills over
            // its rim - `Bucket.overflow` already draws that running down the staves - and until now
            // it reached the floor and stopped existing. Water does not do that.
            //
            // The same `SpreadingPuddle` the taps' own spill uses, so an overflow behaves like every
            // other loose water in the building: it grows while it is fed, stops when the tap does,
            // lingers and dries. It is on the STAND rather than on the bucket because a puddle is a
            // property of the FLOOR - a bucket that is picked up mid-overflow leaves the water behind,
            // which is what would happen.
            Material spillMat = AssetDatabase.LoadAssetAtPath<Material>("Assets/Materials/WaterStream.mat");
            GameObject spill = new GameObject("Overflow");
            spill.transform.SetParent(stand.transform, false);
            spill.transform.localPosition = new Vector3(0f, 0.008f, 0f);
            spill.AddComponent<MeshFilter>().sharedMesh = SaveGeneratedMesh(
                "WaterSpill_" + name + "_d20",
                // Shallower than a tap's own spill: this is what runs off a rim, not what a tap
                // pours straight at the floor.
                () => WaterMeshes.Spill(rings: 8, segments: 40, irregularity: 0.24f, depth: 0.020f,
                                        seed: name.GetHashCode() ^ 0x5177));
            spill.AddComponent<MeshRenderer>().sharedMaterial = spillMat;
            SpreadingPuddle spreading = spill.AddComponent<SpreadingPuddle>();
            // Slower and smaller than a tap's: a rim overflow is a trickle, and one that raced out to
            // three metres would say the bucket was the leak rather than the thing being filled.
            spreading.growthRate = 0.16f;
            spreading.maxRadius = 1.1f;

            BucketStand comp = stand.AddComponent<BucketStand>();
            comp.tap = tap;
            comp.seat = seat.transform;
            comp.aimAnchor = aim.transform;
            comp.bucketItemId = BucketItemId;
            comp.overflowPuddle = spreading;
        }

        // A MODEL'S BOUNDS IN SOME OTHER TRANSFORM'S FRAME, exactly.
        //
        // **`Renderer.bounds` IS WORLD SPACE**, and forgetting it is a mistake that hides, because
        // half of what comes back is still right: a SIZE cannot be changed by a translation, so
        // anything measured that way looks correct. A CENTRE or a MIN carries wherever in the
        // building the object happened to be built - and fed back in as a `localPosition` it displaces
        // the model by its own room's world position, scaled.
        //
        // That is what happened to the buckets, and all three of its symptoms looked like different
        // faults: room2-2 stands 43.4m along the corridor and one storey down, so every pail was
        // drawn 1.6m behind and a quarter of a metre above the object the game was carrying, seating
        // and dropping. Hence a bucket floating in mid-air, a bucket that "went somewhere else" when
        // stood on a perch it was in fact standing on, and a bucket that vanished when picked up -
        // 1.6m behind the hold anchor is 1.6m behind the camera.
        //
        // The eight corners of each MESH's own bounds are mapped, rather than the two corners of its
        // world box: re-boxing a world box in a rotated frame grows it, and this number decides how
        // big the object is. `BuildOneTap` measures in its holder's frame for the same reason and got
        // it right; this is that idea with the rotation case closed.
        private static Bounds ModelBounds(Transform frame, GameObject model)
        {
            bool any = false;
            Bounds local = new Bounds();

            foreach (Renderer r in model.GetComponentsInChildren<Renderer>())
            {
                Mesh mesh = r is SkinnedMeshRenderer skinned
                    ? skinned.sharedMesh
                    : r.GetComponent<MeshFilter>()?.sharedMesh;
                if (mesh == null) continue;

                Bounds mb = mesh.bounds;
                for (int c = 0; c < 8; c++)
                {
                    Vector3 corner = mb.center + Vector3.Scale(mb.extents, new Vector3(
                        (c & 1) == 0 ? -1f : 1f,
                        (c & 2) == 0 ? -1f : 1f,
                        (c & 4) == 0 ? -1f : 1f));
                    Vector3 point = frame.InverseTransformPoint(r.transform.TransformPoint(corner));

                    if (any) local.Encapsulate(point);
                    else { local = new Bounds(point, Vector3.zero); any = true; }
                }
            }

            return local;
        }

        // ONE BUCKET: the model, the water it holds, and the overflow when it holds no more.
        //
        // MEASURED ONCE, AT IDENTITY, AND NEVER AGAIN. Every earlier version of this re-measured the
        // object after it had been scaled, rotated or given children, and every one of those
        // measurements was wrong in a different way:
        //
        //   - measured after the ROOT was scaled, the model's own scale came out divided by it, so the
        //     two cancelled and the bucket was the same size whatever the root said;
        //   - measured after the water and overflow cylinders existed, the bounds were THEIRS - a unit
        //     cylinder is 2 tall, so the "bucket" measured 2 units high and the water was sized to a
        //     bucket that does not exist. That is where the thin column came from.
        //
        // So the model is measured exactly once, while it is alone and untransformed, and every number
        // after that is arithmetic on that one measurement. Nothing is re-read.
        //
        // `tipDegrees` lays it on its side. Some of these are knocked over on purpose - four buckets
        // standing in a tidy row is a set of equipment issued to the player, and four lying about the
        // floor is a room somebody left in a hurry, which is the one this game is set in.
        private static void BuildBucket(Transform parent, string name, Vector3 localPosition,
                                        float yaw, float tipDegrees)
        {
            // SIZED IN TWO STEPS, and both are here rather than one combined number so each says what
            // it is for. The model is authored at 16.4 units, so it is first brought to a real bucket's
            // 300mm - the step a different bucket model would also need. `rootScale` is then the size
            // this GAME wants it at.
            const float wantedHeight = 0.30f;
            const float rootScale = 2.0f;

            GameObject root = new GameObject(name);
            root.transform.SetParent(parent, false);

            // TWO OBJECTS BETWEEN THE ROOT AND EVERYTHING THE BUCKET IS MADE OF, so it can be tipped
            // over its own lip. `PourPivot` is placed AT the rim and is the thing that rotates;
            // `Body` cancels that placement, so the frame everything below it sits in is the root's
            // frame exactly as before - every measurement further down is unaffected, and
            // `Bucket.Apply` goes on positioning the water in the coordinates it always used.
            //
            // Rotating the root instead would tip the object the player's hand is holding, and the
            // hand pose is what decides where a carried thing sits on screen (CarryableItem.AttachTo).
            GameObject pivot = new GameObject("PourPivot");
            pivot.transform.SetParent(root.transform, false);
            GameObject bodyRoot = new GameObject("Body");
            bodyRoot.transform.SetParent(pivot.transform, false);

            GameObject source = AssetDatabase.LoadAssetAtPath<GameObject>($"{FurnitureDir}/wooden_bucket.glb");
            GameObject model = (GameObject)PrefabUtility.InstantiatePrefab(source, bodyRoot.transform);
            model.name = "Visual";
            model.transform.localPosition = Vector3.zero;

            // THE ONE MEASUREMENT, AND IT IS TAKEN IN THE ROOT'S OWN FRAME. `Renderer.bounds` is
            // WORLD space - see ModelBounds for what taking it raw did to this object.
            Bounds raw = ModelBounds(root.transform, model);

            float modelScale = wantedHeight / Mathf.Max(0.0001f, raw.size.y);
            model.transform.localScale = Vector3.one * modelScale;

            // Everything below is that measurement times the scale - never a second look at the object.
            Vector3 size = raw.size * modelScale;
            // Loud, because this is the number every other number here is derived from and a silent
            // wrong one is what shipped. **The centre offset is the tell**: it is the model's own
            // middle in the ROOT's frame, so it belongs at zero, and anything else means the
            // measurement has picked up the world again (see ModelBounds).
            //
            // `lift` is whatever this model needs to stand on the root and is NOT expected to be any
            // particular value - `wooden_bucket` sits on its own origin, so it is zero. The comment
            // that used to say the model "hangs entirely below its origin" was itself an artifact of
            // the broken measurement: what it was describing was the storey, not the mesh.
            Debug.Log($"[SceneBuilder] {name}: size={size} "
                    + $"centre-offset={new Vector2(raw.center.x, raw.center.z) * modelScale} (expects 0,0) "
                    + $"lift={-raw.min.y * modelScale:0.000}");
            // STOOD ON THE ROOT and centred on it, whatever the mesh's own origin happens to be.
            //
            // This used to claim the model "hangs entirely below its own origin", which was never true
            // of this mesh - it was reading the STOREY. The bounds were world-space, so `min.y` was
            // seven metres down and `center.z` forty-three along, and the correction those produced
            // was mistaken for the model's own shape.
            model.transform.localPosition = new Vector3(
                -raw.center.x * modelScale, -raw.min.y * modelScale, -raw.center.z * modelScale);

            float outerRadius = Mathf.Min(size.x, size.z) * 0.5f;
            // The inside of a pail, as fractions of the outside: staves have thickness and the base is
            // not at the very bottom of the silhouette.
            float innerRadius = outerRadius * 0.84f;
            float innerBottom = size.y * 0.10f;
            float innerHeight = size.y * 0.80f;

            Material waterMat = AssetDatabase.LoadAssetAtPath<Material>("Assets/Materials/WaterStream.mat");

            GameObject water = new GameObject("Water");
            water.transform.SetParent(bodyRoot.transform, false);
            water.AddComponent<MeshFilter>().sharedMesh = PrimitiveMesh(PrimitiveType.Cylinder);
            water.AddComponent<MeshRenderer>().sharedMaterial = waterMat;

            // OVERFLOW: water going over the rim because there is nowhere else for it. A thin skirt
            // around the outside rather than a second stream - it is not falling from anywhere, it is
            // running down the staves.
            GameObject spill = new GameObject("Overflow");
            spill.transform.SetParent(bodyRoot.transform, false);
            spill.transform.localPosition = new Vector3(0f, size.y * 0.5f, 0f);
            spill.transform.localScale = new Vector3(outerRadius * 2.06f, size.y * 0.5f, outerRadius * 2.06f);
            spill.AddComponent<MeshFilter>().sharedMesh = PrimitiveMesh(PrimitiveType.Cylinder);
            spill.AddComponent<MeshRenderer>().sharedMaterial = waterMat;
            spill.SetActive(false);

            // THE PIVOT'S PLACE: the front lip, at the top of the pail on the side it tips over. The
            // body hangs below and behind it, so a rotation about the pivot's own X swings the bucket
            // up and over that edge - which is what pouring looks like - rather than rolling it about
            // its middle.
            pivot.transform.localPosition = new Vector3(0f, size.y, outerRadius);
            bodyRoot.transform.localPosition = -pivot.transform.localPosition;

            // THE WATER LEAVING IT. Off until there is some; positioned in world space by `Bucket`
            // while it pours, because it has to hang straight down from a lip that is riding a hand.
            // One shared mesh across all four buckets - `SaveGeneratedMesh` serves the second and
            // later calls from the asset the first one wrote.
            GameObject pourStream = new GameObject("PourStream");
            pourStream.transform.SetParent(root.transform, false);
            pourStream.AddComponent<MeshFilter>().sharedMesh = SaveGeneratedMesh(
                "WaterStream_BucketPour",
                () => WaterMeshes.Stream(rings: 16, segments: 16, bottomScale: 0.78f,
                                         irregularity: 0.13f, seed: 20260815));
            pourStream.AddComponent<MeshRenderer>().sharedMaterial = waterMat;
            pourStream.SetActive(false);

            BoxCollider reach = root.AddComponent<BoxCollider>();
            reach.isTrigger = true;
            reach.center = new Vector3(0f, size.y / 2f, 0f);
            reach.size = new Vector3(size.x + 0.35f, size.y + 0.35f, size.z + 0.35f);

            // A SOLID BODY, like every other carryable: a bucket you can walk through is not in the
            // room. Switched off while it is in the hand by `CarryableItem.blocker`.
            GameObject solid = new GameObject("Blocker");
            solid.transform.SetParent(root.transform, false);
            BoxCollider block = solid.AddComponent<BoxCollider>();
            block.center = new Vector3(0f, size.y / 2f, 0f);
            block.size = size;

            CarryableItem item = root.AddComponent<CarryableItem>();
            item.blocker = block;
            item.itemId = BucketItemId;
            // **~~Weighable~~ NOT ANY MORE** (2026-08-29, by request: the bucket leaves the weighing
            // room). It read 1.8 empty and 12.0 full, which was the room2-2 puzzle's knowledge paying
            // off two doors away and is a connection worth mourning.
            //
            // It is also why room2-7 was never single-solution. **A partly filled pail is a
            // CONTINUOUS weight** - `Weighable` reads `Bucket.Level`, which is anything at all while
            // a bucket stands under a running tap - so a player who knew the numbers could dial in
            // any total the scale asked for. Every other object in that room is a fixed value; this
            // was the one that made the uniqueness proof a caveat instead of a proof. Off the pan,
            // it is a proof again. See the weight table.
            item.displayName = "BUCKET";
            item.icon = BucketIcon();
            item.floorY = 0f;
            item.handLocalPosition = HandPoseFor(size.y * rootScale);
            // The ROOT's scale, which is this object's world size - not the model child's. Passing the
            // child's put a fraction-of-a-millimetre bucket in the hand.
            item.handLocalScale = Vector3.one * rootScale;
            // STANDS ON ITS BASE WHEN IT IS PUT DOWN, whatever pose it was BUILT in. Two of these are
            // knocked over on purpose, and without this putting one down restored that built pose -
            // on its side, floating, because the lift a tipped bucket needs is part of its origin
            // POSITION and a drop restores only the rotation. See CarryableItem.restsUpright.
            item.restsUpright = true;
            item.audioSource = MakeSource(root.transform, "PickupAudio", 1f, 0.85f);
            item.pickupClip = LoadClip(SfxDir, "sfx_item_pickup");

            Bucket bucket = root.AddComponent<Bucket>();
            // ~~The scale reads the water through the bucket~~ - it does not read this pail at all
            // any more (see the `Weighable` note above). The bucket still owns how full it is, which
            // is what the tank and the pour need; nothing weighs it.
            // TWICE THE OLD RATE, by request: play found the tank the bottleneck of room2-2, and a
            // wait that is the slowest thing in a sixty-second loop is a wait the player spends
            // standing still. The number lives here rather than on the component for the reason every
            // tuned value does (CLAUDE.md §2) - it was taking the component's own default, which is
            // how it stayed unexamined.
            // HALVED, 2026-08-19: play reported that even with past selves running the taps there
            // was always dead time before the room could be left. Seven seconds under a tap is seven
            // seconds of STANDING THERE - one object in the hand means the bucket cannot be left to
            // fill while its carrier does something else, so every second of it is a second of the
            // sixty spent watching.
            //
            // The room's LENGTH is unchanged: it is still four bucketloads into the tank
            // (`bucketFraction` 0.2 against a 0.75 mark), so it still cannot be finished by one pair
            // of hands. What is gone is the waiting, which was never the interesting part - the
            // interesting part is that there are two taps and one of you.
            bucket.fillSeconds = 3.5f;
            bucket.waterBody = water.transform;
            bucket.innerBottom = innerBottom;
            bucket.innerHeight = innerHeight;
            bucket.innerRadius = innerRadius;
            bucket.overflow = spill;
            bucket.pourPivot = pivot.transform;
            bucket.pourStream = pourStream.transform;
            // In METRES, like every other size here - the stream mesh is a unit column, so this is
            // the width it comes out at. Taken off the pail's own mouth (which is `outerRadius` at
            // model scale, so twice that in the world) rather than picked, so a different bucket
            // pours a stream in proportion to itself.
            bucket.streamWidth = outerRadius * rootScale * 0.30f;
            bucket.audioSource = MakeSource(root.transform, "PourAudio", spatialBlend: 1f, volume: 0.75f);
            bucket.pourClip = LoadClip(SfxDir, "sfx_water_splash_1");

            // POSE AND SIZE LAST, once every measurement is safely in hand.
            root.transform.localPosition = localPosition;
            root.transform.localRotation = Quaternion.Euler(tipDegrees, yaw, 0f);
            root.transform.localScale = Vector3.one * rootScale;
            // Knocked over, and lifted onto its side so it rests on the rim rather than sinking in.
            if (!Mathf.Approximately(tipDegrees, 0f))
                root.transform.localPosition = localPosition + new Vector3(0f, outerRadius * rootScale, 0f);
        }

        // The shared mesh behind a primitive, without leaving the throwaway GameObject in the scene.
        private static Mesh PrimitiveMesh(PrimitiveType type)
        {
            GameObject temp = GameObject.CreatePrimitive(type);
            Mesh mesh = temp.GetComponent<MeshFilter>().sharedMesh;
            Object.DestroyImmediate(temp);
            return mesh;
        }

        // ~~PROPS DROPPED IN ROOM2-2 TO BE ARRANGED BY HAND~~ REMOVED 2026-08-15, by request: the
        // pipe kit, the gear clock and the valve are out of the room, along with `PlaceProp`, which
        // had no other caller.
        //
        // They were three imports with no job, parked at placeholder positions until somebody designed
        // something for them. Nobody did, and an unplaced prop is not neutral - it is scenery the
        // player reads as a fixture and tries to use. The room's own fixtures (two taps, four buckets,
        // the tank) are all operable, so a valve that is only a decoration teaches exactly the wrong
        // thing about what E is for.
        //
        // The `.glb` files are still in `Assets/ArtAssets/Furniture` and still listed in
        // `docs/asset-licences.md`; nothing but the placing is gone, so putting one back is a call to
        // whatever places it.

        // ONE TAP: the model, the water it lets out, and the volume that answers E.
        //
        // `localPosition` is where the fixture sits and `yaw` turns it to face into the room. The
        // SPOUT IS MEASURED rather than passed in - each of these models has its outlet somewhere
        // different, and a hand-written offset is a number that silently stops being true the day the
        // model is swapped. The water falls from the front-bottom of the model's own bounds, which is
        // where a spout is on both of them.
        private static WaterTap BuildOneTap(Transform parent, string name, string modelPath,
                                            Vector3 localPosition, float yaw, float scale,
                                            float spoutHeightFraction, Vector3 spoutNudge,
                                            string handleNode,
                                            float leverSplitY = -999f,
                                            Vector3 leverPivotLocal = default)
        {
            GameObject holder = new GameObject(name);
            holder.transform.SetParent(parent, false);
            holder.transform.localPosition = localPosition;
            holder.transform.localRotation = Quaternion.Euler(0f, yaw, 0f);

            GameObject source = AssetDatabase.LoadAssetAtPath<GameObject>(modelPath);
            GameObject model = (GameObject)PrefabUtility.InstantiatePrefab(source, holder.transform);
            model.name = "Visual";
            model.transform.localPosition = Vector3.zero;
            // ITS OWN IMPORT ROTATION IS LEFT ALONE, and forcing identity here was a real bug: both of
            // these glTF imports carry (270, 0, 0) on their root to bring a Z-up export into Unity's
            // Y-up, so overwriting it laid each tap on its back. The holder's yaw is what aims the
            // fixture; the model's own rotation is what makes it stand up at all.
            model.transform.localScale = Vector3.one * scale;

            // Measured in the HOLDER's frame, so the answer comes back in the same space the stream is
            // built in and no rotation has to be undone afterwards.
            Renderer[] renderers = model.GetComponentsInChildren<Renderer>();
            Bounds local = new Bounds(holder.transform.InverseTransformPoint(renderers[0].bounds.center), Vector3.zero);
            foreach (Renderer r in renderers)
            {
                local.Encapsulate(holder.transform.InverseTransformPoint(r.bounds.min));
                local.Encapsulate(holder.transform.InverseTransformPoint(r.bounds.max));
            }

            // THE OUTLET. Across and front-to-back it can be measured - a spout is centred on its
            // fixture and points into the room. Its HEIGHT cannot: under a wall mixer the outlet is the
            // lowest thing on the model, and on a gooseneck it is near the top with the whole column
            // below it. That one number is the caller's to state.
            Vector3 spout = new Vector3(
                local.center.x,
                Mathf.Lerp(local.min.y, local.max.y, spoutHeightFraction),
                local.max.z - 0.03f) + spoutNudge;

            Material streamMat = AssetDatabase.LoadAssetAtPath<Material>("Assets/Materials/WaterStream.mat");

            // ONE ROOT FOR THE WHOLE FLOW - but NOT one switch: see WaterFlow. The stream stops with
            // the valve and the puddle it left behind dries in its own time, which one SetActive
            // cannot express.
            GameObject flow = new GameObject("WaterFlow");
            flow.transform.SetParent(holder.transform, false);

            // The floor, in the holder's own frame - below it by however high the fixture is mounted -
            // and how far the water has to fall to reach it.
            float floorY = -localPosition.y;
            float drop = spout.y - floorY;

            // THE FALL. A generated tube rather than a primitive cylinder: a cylinder is one segment
            // tall, so there is nothing down its length to taper or to break, and a stream of constant
            // width is the clearest possible statement that nothing is moving. See WaterMeshes.Stream.
            //
            // Width follows the tap, and the mesh is unit height so the drop is the Y scale.
            float streamWidth = Mathf.Max(0.05f, local.size.x * 0.10f);
            GameObject stream = new GameObject("Stream");
            stream.transform.SetParent(flow.transform, false);
            stream.transform.localPosition = new Vector3(spout.x, floorY + drop / 2f, spout.z);
            stream.transform.localScale = new Vector3(streamWidth, drop, streamWidth);
            stream.AddComponent<MeshFilter>().sharedMesh = SaveGeneratedMesh(
                "WaterStream_" + name,
                () => WaterMeshes.Stream(rings: 26, segments: 20, bottomScale: 0.62f,
                                         irregularity: 0.10f, seed: name.GetHashCode()));
            stream.AddComponent<MeshRenderer>().sharedMaterial = streamMat;

            // THE RUN, ON THE STREAM ITSELF, so it starts and stops with the water for free - the
            // source is under what `WaterFlow` switches, and nothing has to remember to stop it.
            //
            // LOST ONCE ALREADY, when the stream was rebuilt from a primitive into a generated mesh:
            // the audio lived on the object that was replaced, and a silent tap looks exactly like a
            // working one. It is attached here, next to the object it belongs to, for that reason.
            // Volume came back DOWN to 0.5 once the two AudioListeners were sorted out. It had been
            // pushed to 1 while the sound was not arriving at all, which was never a volume problem -
            // turning a broken thing up is how it ends up too loud the moment it is fixed.
            //
            // AND DOWN AGAIN TO 0.24, because the room grew. 0.5 was set against TWO taps; there are
            // four now and past selves leave them running, so late in a run every one of them can be
            // going at once - four copies of a loop that was tuned to be audible on its own. The
            // rolloff below is what keeps a running tap findable, so this is the number to spend,
            // not the range.
            AudioSource runSource = MakeSource(stream.transform, "RunAudio", spatialBlend: 1f,
                                               volume: 0.24f, loop: true);
            runSource.clip = LoadClip(SfxDir, "sfx_water_run");
            // Started by WaterFlow when the tap is opened, not by this flag - see WaterFlow.runSource.
            runSource.playOnAwake = false;
            // ROLLOFF, NOT JUST VOLUME. Unity's default logarithmic curve had this inaudible a couple
            // of metres out however loud it was set. Linear over a room's width means it is loud at the
            // tap and still clearly there from the doorway - which is the job, because a tap a past
            // self left running has to be findable by ear.
            runSource.rolloffMode = AudioRolloffMode.Linear;
            runSource.minDistance = 1.5f;
            runSource.maxDistance = 18f;

            // THE SPILL. Flat, and NOT A CIRCLE - see WaterMeshes.Spill. The ripple surface that used
            // to be here is gone: play called the moving water less natural than still water, which is
            // correct. Standing water in a sealed room does not undulate; what moves on it is the
            // highlight, and that now comes from the shader's noise rather than from the mesh.
            //
            // A millimetre off the floor, since two coplanar surfaces fight over the same depth.
            GameObject puddle = new GameObject("Spill");
            puddle.transform.SetParent(flow.transform, false);
            puddle.transform.localPosition = new Vector3(spout.x, floorY + 0.008f, spout.z);
            // THE DEPTH IS IN THE ASSET NAME, and it has to be: `SaveGeneratedMesh` serves from cache,
            // so changing a shape parameter without changing the name gets you the OLD mesh back and
            // the change silently does nothing. `BevelledPrismMesh` puts its chamfer in the name for
            // exactly this reason.
            puddle.AddComponent<MeshFilter>().sharedMesh = SaveGeneratedMesh(
                "WaterSpill_" + name + "_d45",
                // 45mm of standing water. Deep enough that the rim is a visible waterline from
                // standing height, which is the whole point of giving it a depth at all.
                () => WaterMeshes.Spill(rings: 8, segments: 40, irregularity: 0.22f, depth: 0.045f,
                                        seed: name.GetHashCode() ^ 77));
            puddle.AddComponent<MeshRenderer>().sharedMaterial = streamMat;
            SpreadingPuddle spreading = puddle.AddComponent<SpreadingPuddle>();

            // AND THE SPLASH WHEN IT IS WALKED THROUGH, on the spill rather than on the player: the
            // puddle is the only thing that knows how far it has spread, so it is the only thing that
            // can answer "is someone standing in me". Lost in the same rewrite as the run above.
            PuddleSplash splash = puddle.AddComponent<PuddleSplash>();
            splash.audioSource = MakeSource(puddle.transform, "SplashAudio", spatialBlend: 1f, volume: 0.7f);
            splash.splashClips = new[]
            {
                LoadClip(SfxDir, "sfx_water_splash_1"),
                LoadClip(SfxDir, "sfx_water_splash_2"),
                LoadClip(SfxDir, "sfx_water_splash_3"),
            };

            // DROPLETS, AND THEY ARE THE ONE SIMULATED THING IN THIS GAME. The exception is safe for
            // exactly the reason the no-physics rule exists: that rule is about objects the LOOP HAS
            // TO PUT BACK, and a settle that lands differently each iteration would break "a past self
            // does what you did". Spray is not put back, carried, recorded or interacted with.
            //
            // What it buys is the arc. A droplet thrown up and turned over by gravity is the thing no
            // scrolling texture can fake, and it is what says the water has weight.
            GameObject sprayGO = new GameObject("Spray");
            sprayGO.transform.SetParent(flow.transform, false);
            sprayGO.transform.localPosition = new Vector3(spout.x, floorY + 0.02f, spout.z);
            ParticleSystem spray = sprayGO.AddComponent<ParticleSystem>();

            ParticleSystem.MainModule sprayMain = spray.main;
            sprayMain.loop = true;
            sprayMain.startLifetime = new ParticleSystem.MinMaxCurve(0.30f, 0.95f);
            // FASTER AND FURTHER, because play could not see it at all. Water hitting a hard floor at
            // this height throws a long way sideways, and the first pass was so slow and short-lived
            // that the droplets never cleared the stream they came out of.
            sprayMain.startSpeed = new ParticleSystem.MinMaxCurve(1.4f, 4.2f);
            // A WIDE RANGE OF SIZES, not one size jittered. Real spray is a few big slow drops among a
            // lot of fine fast ones, and a narrow range is what makes particles read as a "system".
            sprayMain.startSize = new ParticleSystem.MinMaxCurve(0.014f, 0.075f);
            sprayMain.gravityModifier = 1f;
            // Nearly opaque. Droplets are small and moving fast, and at low alpha against a white wall
            // they were invisible however many there were - the count was never the problem.
            sprayMain.startColor = new ParticleSystem.MinMaxGradient(new Color(0.90f, 0.95f, 1f, 0.92f));
            sprayMain.simulationSpace = ParticleSystemSimulationSpace.World;
            sprayMain.maxParticles = 600;

            ParticleSystem.EmissionModule sprayEmit = spray.emission;
            sprayEmit.rateOverTime = 150f;
            // Bursts on top of the steady rate, so the spray gusts instead of ticking over - the
            // regularity of a constant emitter is the tell.
            sprayEmit.SetBursts(new[]
            {
                new ParticleSystem.Burst(0f, new ParticleSystem.MinMaxCurve(10f, 26f), 1000, 0.15f),
            });

            // A shallow skirt rather than a cone from a point: the water arrives as a column and leaves
            // sideways, so droplets start at the stream's edge and go outward from there.
            ParticleSystem.ShapeModule sprayShape = spray.shape;
            sprayShape.shapeType = ParticleSystemShapeType.Cone;
            // Flatter, so the droplets go OUT rather than up: a narrow cone fires them back through
            // the falling stream, where they are lost against it.
            sprayShape.angle = 84f;
            sprayShape.radius = streamWidth * 0.6f;
            sprayShape.rotation = new Vector3(-90f, 0f, 0f);

            ParticleSystem.SizeOverLifetimeModule spraySize = spray.sizeOverLifetime;
            spraySize.enabled = true;
            spraySize.size = new ParticleSystem.MinMaxCurve(1f, AnimationCurve.EaseInOut(0f, 1f, 1f, 0.1f));

            ParticleSystemRenderer sprayRend = sprayGO.GetComponent<ParticleSystemRenderer>();
            sprayRend.sharedMaterial = streamMat;
            sprayRend.renderMode = ParticleSystemRenderMode.Billboard;
            sprayRend.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
            sprayRend.receiveShadows = false;

            // WHAT THE TAP ACTUALLY SWITCHES. The stream and its impact go the instant the valve shuts;
            // the spill is handed to `SpreadingPuddle` and dries in its own time. The flow root itself
            // stays ACTIVE - switching it off would take the drying puddle with it, which is exactly
            // the behaviour this replaced.
            WaterFlow waterFlow = flow.AddComponent<WaterFlow>();
            waterFlow.falling = new[] { stream, sprayGO };
            waterFlow.puddle = spreading;
            waterFlow.runSource = runSource;
            // What a bucket standing under the tap changes - see WaterFlow.SetCatch. The spray is
            // "floor only" because it is water bouncing off a floor; caught in a bucket there is no
            // bounce, and the fall simply ends at the rim.
            waterFlow.stream = stream.transform;
            waterFlow.floorOnly = new[] { sprayGO };
            waterFlow.spoutLocalY = spout.y;
            waterFlow.floorLocalY = floorY;

            // WHERE THE E DISC HANGS, and where the press is answered from. On the fixture rather than
            // at the holder's origin, which for the wall tap is inside the wall.
            GameObject anchor = new GameObject("HintAnchor");
            anchor.transform.SetParent(holder.transform, false);
            anchor.transform.localPosition = local.center;

            GameObject interact = new GameObject(name + "Interact");
            interact.transform.SetParent(holder.transform, false);
            interact.transform.localPosition = local.center;
            BoxCollider trigger = interact.AddComponent<BoxCollider>();
            trigger.isTrigger = true;
            // Reach, not sight: tested against the player's own bounds, and it was tight enough before
            // that the player had to stand against the fixture for E to answer at all.
            trigger.center = new Vector3(0f, 0f, 0.8f);
            trigger.size = new Vector3(1.8f, 2.6f, 2.0f);

            WaterTap waterTap = interact.AddComponent<WaterTap>();
            waterTap.tapVisual = model.transform;
            waterTap.hintAnchor = anchor.transform;
            waterTap.waterFlow = waterFlow;
            // The valve itself - a short knock at the tap, separate from the run. It has to live
            // OUTSIDE the flow root, or the sound for shutting the water off would be switched off
            // by the same press that asks for it.
            waterTap.audioSource = MakeSource(interact.transform, "TapAudio", spatialBlend: 1f, volume: 0.7f);
            waterTap.openClip = LoadClip(SfxDir, "sfx_tap_open");
            waterTap.closeClip = LoadClip(SfxDir, "sfx_tap_close");

            // THE HANDLE, and the axis it turns about is MEASURED rather than assumed. A knob turns on
            // the spindle it is mounted on, which points away from the body of the tap - but which of
            // the node's own axes that is depends entirely on how the model was authored, and guessing
            // it wrong makes the handle scythe through the fixture instead of turning on it.
            // NO HANDLE NODE, SO ONE IS CUT OUT OF THE MESH. See SplitMeshAtHeight - the lever is a
            // separate cluster of geometry that merely shares a mesh with the body, and a plane through
            // it separates the two cleanly.
            if (string.IsNullOrEmpty(handleNode) && leverSplitY > -900f)
            {
                MeshFilter big = null;
                foreach (MeshFilter mf in model.GetComponentsInChildren<MeshFilter>())
                    if (mf.sharedMesh != null && (big == null || mf.sharedMesh.vertexCount > big.sharedMesh.vertexCount))
                        big = mf;

                if (big != null)
                {
                    (Mesh bodyMesh, Mesh leverMesh) = SplitMeshAtHeight(big.sharedMesh, name + "Faucet", leverSplitY);
                    Material shared = big.GetComponent<MeshRenderer>().sharedMaterial;
                    big.sharedMesh = bodyMesh;

                    // The pivot goes at the BASE of the lever, in the mesh's own space, and the lever
                    // is offset back by the same amount - so it renders exactly where it always did
                    // and turning the pivot swings it about its hinge rather than about the origin.
                    GameObject pivotGO = new GameObject("LeverPivot");
                    pivotGO.transform.SetParent(big.transform, false);
                    pivotGO.transform.localPosition = leverPivotLocal;

                    GameObject leverGO = new GameObject("Lever");
                    leverGO.transform.SetParent(pivotGO.transform, false);
                    leverGO.transform.localPosition = -leverPivotLocal;
                    leverGO.AddComponent<MeshFilter>().sharedMesh = leverMesh;
                    leverGO.AddComponent<MeshRenderer>().sharedMaterial = shared;

                    waterTap.handle = pivotGO.transform;
                    // A mixer lever goes UP and DOWN, which is a turn about the axis running across
                    // the fixture - the mesh's own X.
                    waterTap.handleAxis = Vector3.right;
                    waterTap.handleAngle = -28f;
                }
            }
            else if (!string.IsNullOrEmpty(handleNode))
            {
                Transform knob = FindDeep(model.transform, handleNode);
                if (knob == null)
                {
                    Debug.LogWarning($"[SceneBuilder] {name}: no '{handleNode}' node - handle will not turn.");
                }
                else
                {
                    waterTap.handle = knob;
                    // Outward, horizontally, from the fixture's centre line to the knob.
                    Vector3 outward = knob.position - holder.transform.TransformPoint(
                        new Vector3(local.center.x, knob.localPosition.y, local.center.z));
                    outward.y = 0f;
                    // Degenerate when the knob sits on the centre line - fall back to the column's own
                    // up, which is the other axis a tap handle ever turns about.
                    Vector3 worldAxis = outward.sqrMagnitude > 1e-6f ? outward.normalized : holder.transform.up;
                    waterTap.handleAxis = knob.InverseTransformDirection(worldAxis);
                }
            }

            return waterTap;
        }

        // CYCLE 2'S BUILDING, one storey below cycle 1's and running back the other way.
        //
        // THE Y OFFSET IS ON THE ROOT, and that is what made a second storey cheap. Every builder in
        // this file places its output with `localPosition` under the parent it is handed, so a parent
        // moved down carries all of them with it - `BuildRoomShell`, `BuildCeilingLights` and
        // `BuildReflectionProbe` needed no Y parameter and no change at all. The alternative was
        // threading a storey height through five signatures and every call site.
        //
        // A SIBLING OF "Room", not a child, and that is load-bearing rather than tidiness: the wall
        // panel gather in `Build` walks everything under `Room` and takes anything parented to a
        // "*_Panels" node. Built inside it, cycle 2's panels would silently join cycle 1's `ERROR`
        // glitch - a cycle failing in a room the player has not reached yet. Outside it, the two sets
        // are separate for free and each cycle gets its own display.
        //
        // Cycle 2 has ONE room and no puzzles yet. Its rooms are sealed on both walls for now; the
        // switchback means the next one goes at 4 * RoomPitch and this room grows a SOUTH doorway when
        // it does.
        // One cycle's wall panels, as the thing that boots them, flares them and finally fails them.
        private static WallPanelDisplay MakeWallPanelDisplay(string name, Renderer[] panels,
                                                             Texture2D testCard, Texture2D staticNoise)
        {
            GameObject go = new GameObject(name);
            WallPanelDisplay display = go.AddComponent<WallPanelDisplay>();
            display.panels = panels;
            display.offColor = WallPanelColor;
            display.onColor = PanelLitColor;   // must equal PanelWhite's albedo - see PanelLitColor
            display.testCard = testCard;
            display.staticNoise = staticNoise;
            return display;
        }

        // ONE ROOM OF THE RING: a parent carrying its world position and facing, with the room built
        // at local zero inside it.
        //
        // **A parent per room rather than a parent per leg**, which is what makes the whole ring
        // reuse builders that only ever take a `zCenter`. `BuildRoomShell`, `BuildCeilingLights` and
        // `BuildReflectionProbe` know nothing about X or rotation; handed a rotated, positioned parent
        // and a zCenter of zero, every one of them lands correctly with no new parameters. The
        // alternative was threading an X and a yaw through five signatures and every call site.
        //
        // Travel is always local -Z, so every room's NORTH wall is where you came in and its SOUTH
        // wall is where you leave - except at a corner, where you leave through the WEST wall.
        // **West is always the way on**, either to the next room or, mid-leg, onto the core.
        private static Transform BuildRingRoom(Transform parent, string name, float x, float z, float yaw,
                                               Material floorMat, Material grooveMat, Material panelMat,
                                               Rect south, Rect north, Rect west,
                                               Rect ceilingHole = default)
        {
            GameObject holder = new GameObject(name + "_Root");
            holder.transform.SetParent(parent, false);
            holder.transform.localPosition = new Vector3(x, 0f, z);
            holder.transform.localRotation = Quaternion.Euler(0f, yaw, 0f);

            BuildRoomShell(holder.transform, name, 0f, floorMat, grooveMat, panelMat,
                south, north, west, Rect.zero, Rect.zero, ceilingHole);

            return holder.transform;
        }

        // A floor or ceiling piece of arbitrary footprint, optionally holed.
        //
        // `BuildSlab` is the room-shaped version and is left exactly as it was, so every standard
        // shell goes on emitting the single cube it always emitted. This one exists because the tree
        // hall is not a room shape: a 9m bay and a 21m run at two different ceiling heights.
        private static void BuildSlabRect(Transform t, string name, float yCenter, Rect xz,
                                          Material mat, Rect hole = default)
        {
            var parts = SubtractRect(xz, hole);

            if (parts.Count == 1)
            {
                Prim(PrimitiveType.Cube, name, t, new Vector3(xz.center.x, yCenter, xz.center.y),
                     new Vector3(xz.width, WallThickness, xz.height), mat);
                return;
            }

            int piece = 0;
            foreach (Rect part in parts)
            {
                if (part.width <= 0.001f || part.height <= 0.001f) continue;
                Prim(PrimitiveType.Cube, $"{name}_{++piece}", t,
                     new Vector3(part.center.x, yCenter, part.center.y),
                     new Vector3(part.width, WallThickness, part.height), mat);
            }
        }


        // ROOM2-5'S SLIDE - and this one is not scenery.
        //
        // It furnished room2-6 until 2026-08-19, when it was dragged onto the tree hall's far ledge
        // by hand and set against the south wall with its chute going THROUGH it. That makes it the
        // way into the room beyond, and the only way: see BuildSlideRoom for what is on the other
        // side and SlideRide for what riding it does.
        //
        // THE POSE IS A READ-BACK, NOT A FIT. The old `BuildPlayground` derived its scale from the
        // room's door lanes, which is the right rule for scenery standing in an empty shell and the
        // wrong one for a prop that has to line up with a hole in a wall. This one was placed by eye
        // and measured afterwards - see SlideLocalPosition for the three things those numbers mean.
        //
        private static void BuildSlide(Transform hall)
        {
            string path = PlayDir + "/slide_playground.glb";
            GameObject source = AssetDatabase.LoadAssetAtPath<GameObject>(path);
            if (source == null)
            {
                Debug.LogError($"[SceneBuilder] {path} is missing - room2-5 keeps the hole in its "
                             + "wall and loses the only thing leading through it.");
                return;
            }

            ShrinkModelTextures(path, 1024);

            GameObject root = new GameObject("Room2_5_Slide");
            root.transform.SetParent(hall, false);
            root.transform.localPosition = SlideLocalPosition;

            GameObject model = (GameObject)PrefabUtility.InstantiatePrefab(source, root.transform);
            model.name = "Slide";

            // WRITTEN ONTO THE IMPORTED INSTANCE, which is the one case where that is the right thing
            // to do. The usual rule is a wrapper - a glTF root's own rotation is load-bearing and
            // overwriting it makes the model answer a rotation with a translation. What is written
            // here is that node's OWN pose, read back off the editor with the correction already in
            // it, so it reproduces the hand placement exactly instead of composing with it.
            model.transform.localPosition = Vector3.zero;
            model.transform.localRotation = Quaternion.Euler(SlideLocalEuler);
            model.transform.localScale = Vector3.one * SlideLocalScale;

            // SOLID: a slide you walk through is a poster, the stairs are how the head of the chute is
            // reached at all, and the ride below is measured by raycasting these very colliders. Mesh
            // colliders on the parts as they are - convex would swallow the space under the deck and
            // fill in the chute itself.
            int solid = 0;
            foreach (MeshFilter mf in model.GetComponentsInChildren<MeshFilter>(true))
            {
                if (mf.sharedMesh == null) continue;
                MeshCollider mc = mf.gameObject.AddComponent<MeshCollider>();
                mc.sharedMesh = mf.sharedMesh;
                solid++;
            }

            Vector3[] ride = SampleRidePath(hall, model.transform);
            if (ride == null) return;

            // THE TRIGGER IS THE HEAD OF THE CHUTE, not the stairs and not the deck. The stairs' top
            // step is a metre east of it, so climbing does not commit you to anything; stepping off
            // that step onto the chute's platform does, which is what getting on a slide is.
            //
            // Tall enough to catch a standing player's capsule from the feet up - the ride starts on
            // ENTRY, so a volume that only reached the knees would be walked over between frames.
            const float triggerHeight = 2.2f;
            GameObject rideGO = new GameObject("Room2_5_SlideRide");
            rideGO.transform.SetParent(hall, false);

            // **THE WHOLE CHUTE ANSWERS, NOT JUST ITS TOP** (2026-08-29, by request: getting on
            // halfway down should work).
            //
            // One box at `ride[0]` meant the only way onto the slide was over the lip at the head of
            // it - step onto the middle of the chute, which is a solid surface a player can simply
            // walk onto, and nothing happened at all.
            //
            // **A BOX PER SAMPLE RATHER THAN ONE BIG ONE.** The chute DESCENDS, so a single box round
            // the whole run would be metres tall and would catch anybody walking underneath it. These
            // follow the surface instead. They can be axis-aligned and unrotated because the chute is
            // a straight line in XZ with only its height changing - which is a fact about this slide,
            // and the reason it is safe to say so here rather than in `SlideRide`.
            //
            // **ONLY THE CHUTE.** `SlideRideSamples` of the path is chute and the rest is the plunge
            // into the water; a trigger over the plunge would restart a ride on somebody standing in
            // the pool where the last one dropped them.
            int chutePoints = Mathf.Min(SlideRideSamples, ride.Length);
            float step = chutePoints > 1
                ? Vector3.Distance(ride[0], ride[chutePoints - 1]) / (chutePoints - 1) : 1f;

            int boxes = 0;
            for (int i = 0; i < chutePoints; i += 3)
            {
                BoxCollider box = rideGO.AddComponent<BoxCollider>();
                box.isTrigger = true;
                box.center = new Vector3(ride[i].x, ride[i].y + triggerHeight / 2f, ride[i].z);
                // Deep enough to overlap its neighbours: a gap between two of these is a stretch of
                // chute that does nothing, which is the bug being fixed.
                box.size = new Vector3(1.0f, triggerHeight, Mathf.Max(1.0f, step * 4.2f));
                boxes++;
            }

            // The path is in the hall's frame and this object sits at the hall's origin, so what the
            // component stores and what was measured are the same numbers.
            SlideRide rideComp = rideGO.AddComponent<SlideRide>();
            rideComp.path = ride;

            Debug.Log($"[SceneBuilder] Slide: {solid} solid part(s); ride of {ride.Length} points, "
                    + $"{ride[0].y:0.00}m down to {ride[ride.Length - 1].y:0.00}m over "
                    + $"{Mathf.Abs(SlideRideLanding.y - SlideRideHead.y):0.00}m. "
                    + $"{boxes} entry box(es) along {chutePoints} chute point(s) - one would mean the "
                    + "slide can only be joined at the top again.");
        }

        // THE RIDE, MEASURED OFF THE CHUTE RATHER THAN DESCRIBED.
        //
        // A downward ray at every step along the line the rider takes, so each height in the path is
        // whatever is actually underneath it: the chute's surface while there is chute, the landing
        // room's floor once there is not. The only numbers written down are where the line starts,
        // where it leaves the hall and where it stops.
        //
        // IT FAILS THE BUILD IF THE CHUTE IS NO LONGER UNDER IT, because that is not a visible fault:
        // the ride would still run and the player would still arrive in the room, and the only
        // symptom is a rider gliding through the air a foot above the slide.
        private static Vector3[] SampleRidePath(Transform hall, Transform slide)
        {
            // Colliders built this frame are not in the physics scene until it is told about them -
            // the same line `AssertWalkable` opens with, and for the same reason.
            Physics.SyncTransforms();

            // WHERE THE RAY STARTS, and it is a narrower window than it looks - and now TWO windows,
            // one per leg, because the two legs are no longer under the same ceiling.
            //
            // LEG 0, the chute, is still entirely inside the hall: has to clear the head of the chute
            // at 2.8m and stay UNDER the hall's own ceiling - the first version dropped from 6m, which
            // is fine for the 17.5m hall but lands on the roof of a same-level room the run-out used
            // to cross, and the ride came out sloping UP to 5.51m.
            //
            // LEG 1, the plunge, is inside room2-5's landing room, which sits BELOW the hall with its
            // ceiling at the top of the mouth - so a ray dropped from hall height would hit that
            // ceiling before it ever reached the floor beneath it. Starting just under it instead
            // keeps the ray inside the room it is actually meant to be measuring.
            const float probeFromHall = 4.5f;
            float probeFromRoom = SlideRoomFloorY + RoomHeight - 0.05f;
            // Generous rather than derived from either probe height: leg 0 drops a few metres to the
            // hall's own floor, leg 1 drops the better part of a storey to room2-5's - one constant
            // that comfortably clears both beats two numbers each tied to a probe height that used to
            // double as "how far below the floor is safe to still call a hit".
            const float probeMaxDistance = 12f;
            var points = new System.Collections.Generic.List<Vector3>();
            int onChute = 0, missed = 0;

            // The chute, then the plunge. Two passes rather than one because they are two different
            // things: leg 0 is measured off the slide, and leg 1 is a fall to a floor that is measured
            // only to know where it ENDS.
            //
            // LEG 0 TAKES THE SLIDE'S OWN SURFACE, not the first thing under the line. A single
            // `Raycast` takes the highest hit, and once the landing room came up to meet the mouth its
            // CEILING SLAB is the highest thing under the last two samples - so the measured path
            // climbed from the chute at 0.53m onto the roof of the room at 1.80m and the ride carried
            // the player over the top of the level, outside it, before dropping them in. It played
            // exactly as it reads. `RaycastAll` and prefer the slide.
            float chuteExitY = 0f;
            for (int leg = 0; leg < 2; leg++)
            {
                Vector2 from = leg == 0 ? SlideRideHead : SlideRideFoot;
                Vector2 to = leg == 0 ? SlideRideFoot : SlideRideLanding;
                int steps = leg == 0 ? SlideRideSamples : SlideRidePlungeSamples;
                float probeFrom = leg == 0 ? probeFromHall : probeFromRoom;

                for (int i = leg == 0 ? 0 : 1; i <= steps; i++)
                {
                    float t = i / (float)steps;
                    Vector2 xz = Vector2.Lerp(from, to, t);
                    Vector3 at = hall.TransformPoint(new Vector3(xz.x, probeFrom, xz.y));

                    RaycastHit[] hits = Physics.RaycastAll(at, hall.TransformDirection(Vector3.down),
                                                           probeMaxDistance, ~0,
                                                           QueryTriggerInteraction.Ignore);
                    bool found = false;
                    float surfaceY = 0f;
                    float best = float.NegativeInfinity;
                    bool bestIsChute = false;

                    foreach (RaycastHit hit in hits)
                    {
                        float y = hall.InverseTransformPoint(hit.point).y;
                        bool isChute = slide != null && hit.transform.IsChildOf(slide);
                        // On leg 0 the slide wins outright, whatever is above it. Everywhere else the
                        // highest surface wins, which is the floor of whichever room the ray is in.
                        bool better = !found
                                   || (leg == 0 && isChute && !bestIsChute)
                                   || (y > best && (leg != 0 || isChute == bestIsChute));
                        if (!better) continue;

                        found = true;
                        surfaceY = y;
                        best = y;
                        bestIsChute = isChute;
                    }

                    if (found)
                    {
                        if (leg == 0)
                        {
                            if (bestIsChute) { onChute++; chuteExitY = surfaceY; }
                            // ON THE CHUTE OR NOWHERE. A leg-0 sample that found something else has
                            // found a surface the rider must not be put on - it is what happened with
                            // the landing room's ceiling - so the height is HELD at the last known one
                            // rather than stepped up onto it. The `onChute` count below is what says
                            // so out loud.
                            else if (points.Count > 0) surfaceY = points[points.Count - 1].y;
                        }
                    }
                    else
                    {
                        // Nothing under the ride at all. Carried at the last known height rather than
                        // dropped to zero, which would put a step in the path instead of a warning.
                        missed++;
                        surfaceY = points.Count > 0 ? points[points.Count - 1].y : 0f;
                    }

                    // LEG 1 IS AN ARC, NOT A FLOOR. Every sample of it raycasts the same floor, so
                    // taking the surface directly gave a path that stood at the mouth and then fell
                    // four metres straight down between two waypoints - a drop with a slide attached
                    // to it. The height is interpolated from the chute's exit down to the floor on a
                    // SQUARED curve instead: shallow where it leaves the chute, steepening as it goes,
                    // which is the shape of something thrown rather than something released. The
                    // raycast still decides where it ends and still clamps it - nothing may pass
                    // through the floor.
                    if (leg == 1)
                    {
                        float arc = Mathf.Lerp(chuteExitY, surfaceY, t * t);
                        surfaceY = Mathf.Max(surfaceY, arc);
                    }

                    points.Add(new Vector3(xz.x, surfaceY, xz.y));
                }
            }

            if (points.Count < 2)
            {
                Debug.LogError("[SceneBuilder] the slide's ride path came out empty.");
                return null;
            }

            if (onChute < SlideRideSamples / 2)
                Debug.LogError($"[SceneBuilder] the slide's ride path only touches the chute at "
                             + $"{onChute} of {SlideRideSamples + 1} samples - it has moved out from "
                             + "under the line in SlideRideHead/SlideRideFoot.");

            if (missed > 0)
                Debug.LogError($"[SceneBuilder] the slide's ride path has {missed} sample(s) with "
                             + "nothing underneath - the run-out is off the landing room's floor.");

            // A SLIDE GOES DOWN. Anything the sampler found ABOVE the head it started at is something
            // it was never meant to be measuring - a ceiling, a rail, the underside of a deck - and
            // the symptom is a ride that carries the player upward through the room. See probeFrom
            // for the version of this that actually happened.
            foreach (Vector3 point in points)
            {
                if (point.y <= points[0].y + 0.05f) continue;
                Debug.LogError($"[SceneBuilder] the slide's ride path climbs to {point.y:0.00}m, "
                             + $"above the {points[0].y:0.00}m it starts at - it is measuring "
                             + "something that is not the chute.");
                break;
            }

            return points.ToArray();
        }

        // WHAT THE SLIDE LANDS IN. Room2-5's own room, south of the tree hall's west end, reached by
        // riding the slide through the hall's south wall and left through a door back into the hall.
        //
        // BUILT HERE RATHER THAN THROUGH `BuildRingRoom` for one reason: its north wall needs TWO
        // openings - the chute's mouth and the doorway back - and `BuildPanelWall` takes one cutout.
        // Everything else is the standard helpers at the standard sizes, so it is the same floor, the
        // same panelling, the same lighting and the same probe as every other room in the building.
        //
        // NO PUZZLE, NO CARRYABLE, NO SIGNAL: it touches neither the loop nor the reset. What goes in
        // it is a later decision, and until then it is a room that exists.
        private static (Transform room, Door door, PoolDrain drain, Valve[] valves)
            BuildPoolRoom(Transform parent, Material floorMat, Material grooveMat, Material panelMat,
                          Material propMat, Material fixtureMat)
        {
            GameObject rootGO = new GameObject("Room2_6_Root");
            rootGO.transform.SetParent(parent, false);
            // BELOW THE HALL, BY EXACTLY WHAT PUTS ITS CEILING AT THE TOP OF THE MOUTH. It sat beside
            // the hall at the hall's own floor height, then a full `StoreyDrop` under it, and neither
            // connected: see `SlideRoomFloorY` for why the depth is derived from the opening now
            // rather than picked.
            rootGO.transform.localPosition =
                new Vector3(SlideRoomCentreX, SlideRoomFloorY, SlideRoomCentreZ);

            GameObject roomGO = new GameObject("Room2_6");
            roomGO.transform.SetParent(rootGO.transform, false);
            Transform t = roomGO.transform;

            // THE FLOOR IS CUT FOR THE DRAIN. `BuildSlab` subtracts one Rect, which is why the hole is
            // square and the grate is what makes it read as a drain.
            BuildSlab(t, "Floor", -WallThickness / 2f, 0f, floorMat,
                      new Rect(-DrainSize / 2f, -DrainSize / 2f, DrainSize, DrainSize));
            BuildSlab(t, "Ceiling", RoomHeight + WallThickness / 2f, 0f, CeilingMaterial(), default);

            // THE NORTH WALL IS THE SHARED ONE, and its one opening sits AGAINST THE CEILING - the top
            // 1.7m of the wall, which is now the same 1.7m band the hall's own opening covers, because
            // the room's height below the hall is derived from exactly that (`SlideRoomFloorY`). The
            // two cut the same rectangle out of two walls a pocket apart, so they are one hole with a
            // short tunnel in it. Same X as the hall's opening, shifted into this room's frame by the
            // one offset below rather than written down twice.
            //
            // NO DOOR YET, and the wall is back to ONE span rather than two because of it: the old
            // "way back" doorway assumed the room on the other side was at the same height, and it no
            // longer is. Its doorway, its pocket and the walkability asserts that checked it are gone
            // with the floor-level entrance - `SlideRoomDoorX`/`SlideRoomWallSplitX` are unused until
            // the exit is designed for a room that is now a storey down instead of next door.
            float mouthFrom = TreeHallWestFace - SlideRoomCentreX;
            float mouthTo = SlideMouthEast - SlideRoomCentreX;

            BuildPanelWall(t, "Wall_North", new Vector3(0f, 0f, RoomDepth / 2f),
                Vector3.right, Vector3.back, RoomWidth, grooveMat, panelMat,
                Rect.MinMaxRect(mouthFrom, RoomHeight - SlideMouthHeight, mouthTo, RoomHeight));

            // THE TUNNEL BETWEEN THE TWO WALLS. The hall's wall and this one are a door pocket apart,
            // and with a hole cut through both that gap is open on all four sides - looking through the
            // mouth at any angle but straight ahead you see along a slot with the sky at the end of it.
            // Thin pieces line it, so the hole reads as a hole through a thick wall, which is what it is.
            //
            // EVERY PIECE IS SIZED TO WHAT IS ACTUALLY OPEN, and the first version was not: it spanned
            // the whole pocket and so lay ON TOP of two slabs that already reach into it, which is two
            // pairs of coplanar faces and the flicker play reported at the mouth. What reaches in:
            //   - `BuildSlab` runs to the room PITCH, not its depth, so this room's ceiling already
            //     covers half a pocket past its own north wall;
            //   - the walls themselves have bodies - the hall's south wall hangs a `WallDepth` south of
            //     its face, which is the north end of the gap.
            // So the genuinely open span is from this room's wall face to the hall's, and the head only
            // has to close what the ceiling slab does not reach. Both are derived below rather than
            // measured, so a change to the pocket or the wall depth cannot re-open the slot.
            //
            // NOT a `BuildPanelWall`: these are the reveals of an opening rather than a surface of the
            // room, and panelling them would put grooves on strips nobody stands square to.
            float pocket = 2f * WallDepth + DoorPocketDepth;
            // FROM THE BACK OF ONE WALL TO THE BACK OF THE OTHER, which is a much narrower span than
            // the one between their FACES - 0.1m rather than 0.35 - and getting that wrong is what
            // play saw flickering at the mouth twice.
            //
            // **A WALL'S BACKING SLAB SITS BEHIND ITS FACE, OUTSIDE THE ROOM**: `BuildPanelWall` puts
            // it at `GrooveDepth + WallThickness/2` back from the face it is given, so the wall's body
            // is in the pocket rather than in the room. Two of them, one per side, eat 0.25 of the
            // 0.35, and anything lining the pocket across the whole of it is laid straight through
            // both - coplanar faces, and the flicker moves with the camera. Measured off the built
            // scene rather than reasoned about, after reasoning about it got it wrong once.
            float wallBody = GrooveDepth + WallThickness;
            float gapFrom = RoomDepth / 2f + wallBody;                        // back of this room's wall
            float gapTo = RoomDepth / 2f + pocket - wallBody;                 // back of the hall's
            float ceilingReach = RoomPitch / 2f;                   // how far the ceiling slab overruns
            float mouthMid = (mouthFrom + mouthTo) / 2f, mouthSpan = mouthTo - mouthFrom;
            // The sill is level with the hall's floor, which in this room's frame is `-SlideRoomFloorY`
            // - the one conversion between the two storeys.
            float sillY = -SlideRoomFloorY;

            GameObject tunnel = new GameObject("MouthTunnel");
            tunnel.transform.SetParent(t, false);

            if (gapTo - ceilingReach > 0.001f)
                Prim(PrimitiveType.Cube, "Head", tunnel.transform,
                     new Vector3(mouthMid, RoomHeight + WallThickness / 2f,
                                 (ceilingReach + gapTo) / 2f),
                     new Vector3(mouthSpan + WallThickness * 2f, WallThickness,
                                 gapTo - ceilingReach), floorMat);

            Prim(PrimitiveType.Cube, "Sill", tunnel.transform,
                 new Vector3(mouthMid, sillY - WallThickness / 2f, (gapFrom + gapTo) / 2f),
                 new Vector3(mouthSpan + WallThickness * 2f, WallThickness, gapTo - gapFrom), floorMat);

            for (int side = 0; side < 2; side++)
            {
                float x = side == 0 ? mouthFrom - WallThickness / 2f : mouthTo + WallThickness / 2f;
                Prim(PrimitiveType.Cube, side == 0 ? "Reveal_West" : "Reveal_East", tunnel.transform,
                     new Vector3(x, (sillY + RoomHeight) / 2f, (gapFrom + gapTo) / 2f),
                     new Vector3(WallThickness, RoomHeight - sillY, gapTo - gapFrom), floorMat);
            }

            // THE WAY ON IS THE SOUTH WALL - straight ahead of the slide. The chute comes through the
            // north wall heading south, so a rider lands facing this door: the room says where it goes
            // before the player has turned round.
            BuildPanelWall(t, "Wall_South", new Vector3(0f, 0f, -RoomDepth / 2f),
                Vector3.right, Vector3.forward, RoomWidth, grooveMat, panelMat,
                new Rect(-DoorWidth / 2f, 0f, DoorWidth, DoorHeight));
            BuildPanelWall(t, "Wall_West", new Vector3(-RoomWidth / 2f, 0f, 0f),
                Vector3.forward, Vector3.right, RoomDepth, grooveMat, panelMat, Rect.zero);
            BuildPanelWall(t, "Wall_East", new Vector3(RoomWidth / 2f, 0f, 0f),
                Vector3.forward, Vector3.left, RoomDepth, grooveMat, panelMat, Rect.zero);

            BuildCeilingLights(t, "Room2_6", 0f, fixtureMat, castShadows: true);
            BuildReflectionProbe(t, "Room2_6", 0f);

            // AND IT IS FULL OF WATER, which is what the slide lands in.
            WaterPool pool = BuildWaterPool(t);

            // --- the door ---------------------------------------------------------------------------
            // **NOT CAPPED.** It was, for the one build where there was nothing on the other side, and
            // `capFarSide` does exactly what it says: it puts a SOLID WALL across the far mouth of the
            // pocket. Room2-7 was built behind this door and the cap was left on, so the room existed,
            // was lit, was probed - and was invisible and unreachable behind a wall in the doorway.
            //
            // The rule: `capFarSide` is true only where the walk ENDS. Every join with a room through
            // it is false.
            Door door = BuildPadDoor(t, "Door2_6", 0f, new FloorButton[0], propMat, yaw: 180f);
            BuildDoorPocketFill(t, "Pocket2_6", 0f, grooveMat, capFarSide: false, yaw: 180f);

            // --- the three valves -------------------------------------------------------------------
            // ONE PER WALL THAT HAS NO DOOR, centred, at a height a standing player turns a wheel at.
            // Spread as far apart as this room allows on purpose: six turns is more than one iteration
            // holds, and what makes that interesting rather than tedious is that the three of them
            // cannot be reached by one person in one minute. A past self at the east wheel is the
            // room being solved.
            var valves = new Valve[3];
            valves[0] = BuildValve(t, "Valve2_6_North", new Vector3(0f, ValveHeight, RoomDepth / 2f), 180f);
            valves[1] = BuildValve(t, "Valve2_6_East", new Vector3(RoomWidth / 2f, ValveHeight, 0f), 270f);
            valves[2] = BuildValve(t, "Valve2_6_West", new Vector3(-RoomWidth / 2f, ValveHeight, 0f), 90f);

            // --- the drain, and the rule ------------------------------------------------------------
            PoolDrain drain = BuildDrain(t, pool, valves, floorMat, propMat);
            door.condition = drain;

            return (t, door, drain, valves);
        }

        // ROOM2-7: THE WEIGHING ROOM, through room2-6's door.
        //
        // ONE ROOM, ONE SCALE, ONE NUMBER. Everything the player has learned to carry is worth
        // something here and they are told none of it - see the weight constants for why the numbers
        // are what they are, and `WeighScale` for why the room is a measuring instrument before it is
        // a lock.
        //
        // BUILT LIKE ROOM2-6 rather than through `BuildRingRoom`: it is off the ring entirely, hung
        // south of the pool at the pool's own depth, so it takes its parent's frame and its own
        // lights and probe. Its NORTH wall carries the doorway, which is the same opening room2-6's
        // south wall has - one door, two rooms, and the pocket between them belongs to room2-6.
        // A PLAIN SHELL, one room further on, so room2-7's door has somewhere to lead. Empty by
        // design and by admission: it is where cycle 2 continues, and what goes in it is the next
        // decision rather than something to guess at now. Its own door is the capped end of the walk.
        // `doorwayNorth` is the original one-doorway form and stays for every caller that has one.
        // The four explicit cutouts are for a room whose openings are not doorways at all - room3-1
        // has a gate in all four walls (see BuildPanelGate) - and they are separate arguments rather
        // than a replacement so that a room asking for the ordinary thing still says so in one word.
        private static Transform BuildEmptyRoom(Transform parent, string name, Vector3 at,
                                                Material floorMat, Material grooveMat,
                                                Material panelMat, Material fixtureMat,
                                                bool doorwayNorth, Rect floorHole = default,
                                                Rect ceilingHole = default,
                                                Rect northCutout = default, Rect southCutout = default,
                                                Rect westCutout = default, Rect eastCutout = default)
        {
            GameObject rootGO = new GameObject(name + "_Root");
            rootGO.transform.SetParent(parent, false);
            rootGO.transform.localPosition = at;

            GameObject roomGO = new GameObject(name);
            roomGO.transform.SetParent(rootGO.transform, false);
            Transform t = roomGO.transform;

            Rect doorway = new Rect(-DoorWidth / 2f, 0f, DoorWidth, DoorHeight);

            BuildSlab(t, "Floor", -WallThickness / 2f, 0f, floorMat, floorHole);
            BuildSlab(t, "Ceiling", RoomHeight + WallThickness / 2f, 0f, CeilingMaterial(), ceilingHole);

            BuildPanelWall(t, "Wall_North", new Vector3(0f, 0f, RoomDepth / 2f),
                Vector3.right, Vector3.back, RoomWidth, grooveMat, panelMat,
                doorwayNorth ? doorway : northCutout);
            BuildPanelWall(t, "Wall_South", new Vector3(0f, 0f, -RoomDepth / 2f),
                Vector3.right, Vector3.forward, RoomWidth, grooveMat, panelMat, southCutout);
            BuildPanelWall(t, "Wall_West", new Vector3(-RoomWidth / 2f, 0f, 0f),
                Vector3.forward, Vector3.right, RoomDepth, grooveMat, panelMat, westCutout);
            BuildPanelWall(t, "Wall_East", new Vector3(RoomWidth / 2f, 0f, 0f),
                Vector3.forward, Vector3.left, RoomDepth, grooveMat, panelMat, eastCutout);

            BuildCeilingLights(t, name, 0f, fixtureMat, castShadows: true);
            BuildReflectionProbe(t, name, 0f);
            return t;
        }

        // ROOM2-0: THE LAST ROOM OF CYCLE 2, AND THE ONE THAT BREAKS IT.
        //
        // The same white cell as every other, and the same argument cycle 1's room4 makes for that:
        // the room the player finally gets out into looks exactly like the ones they have been trying
        // to get out of. What makes it the end is that nothing is in it until they walk in.
        //
        // FOUR PEDESTALS ON ONE MOVER, not four movers. `RewardPlinth` raises a single Transform, and
        // the four are children of it - so they come up together as one machine rather than as four
        // props that happen to agree, and `MovesDuringPlay` (which walks UP from each renderer) finds
        // the plinth above all of them without any of them being named.
        //
        // WHAT EACH ONE WANTS is the count of the object drawn on its side: five axes, three ducks,
        // four buckets, two beach balls. The number is never written down anywhere in the building
        // and cannot be - it is the player's own memory of four rooms they have already crossed, which
        // is the only kind of key a time loop can ask for that a past self cannot fetch for them.
        //
        // THE ORDER OF THE ROW IS NOT THE ORDER OF THE ANSWERS (5, 3, 4, 2 left to right). A row that
        // read 2, 3, 4, 5 would be solvable by noticing that it counts.
        // CYCLE 3'S FIRST ROOM, AND SO FAR ITS ONLY ONE.
        //
        // A bed, a chest with nothing in it, and four gas emitters - which is exactly what room2-1 was
        // on the day cycle 2 was started, and deliberately so: what a cycle opens with is a person
        // waking up in a cell, and that is the same sentence every time. The chest is the cycle 2
        // build (`BuildDresser`, two opening bays and a cube on top) with `withBilliards` off, because
        // what goes in a drawer belongs to a puzzle that has not been designed.
        //
        // NO DOORWAY, NO DOOR, NO CONDITION. The room is sealed, `Cycle.finalRoom` is null and the
        // cycle cannot be finished - all three are supported states that cycle 2 shipped in for weeks
        // (see `AssembleCycleTwo`). The loop simply keeps iterating here, which is the honest state of
        // a cycle with no puzzles in it.
        private static (Transform root, Transform bedSpawn, ParticleSystem[] gas, Transform room,
                        GhostInteractable[] signals, CrushingBarrier northBarrier, BeamLift[] lifts)
            BuildCycleThreeShell(Material floorMat, Material grooveMat, Material panelMat,
                                 Material propMat)
        {
            // ITS OWN FIXTURE MATERIAL, like cycle 2's. `CeilingFixture` is one emissive material
            // shared by every room in a cycle, and `ChessReward` dims cycle 1's through a property
            // block - a third cycle borrowing either would be a third cycle that goes dark when a
            // board on another storey is finished.
            Material fixtureMat = MakeEmissiveMaterial("CeilingFixtureCycle3", Color.white, 3.5f);

            GameObject root = new GameObject("Room_Cycle3");
            // AXIS-ALIGNED, unlike cycle 2. That cycle turns 180 about its own bed so its hall can be
            // tall without switchbacking under cycle 1; cycle 3 has one room and nothing to avoid, so
            // it is left square to the world and the next room it grows can decide for itself.
            root.transform.position = new Vector3(CycleThreeX, CycleThreeFloorY, CycleThreeZ);

            // THE HOLE THE PLAYER ARRIVES THROUGH. Its lid is NOT here - it lives on the join in the
            // core scene with the floor lid above it, exactly as cycle 1's does, because one
            // `CycleExit` drives both and a reference across a scene boundary comes back null. What
            // this room owns is the absence.
            // A GATE IN ALL FOUR WALLS, and no door anywhere in the room.
            //
            // A gate is measured off the wall's own grid rather than off the room - see `GateSpan`.
            // TWO CUTOUTS, NOT ONE. The north and south walls are 8.75 across and the east and west
            // 10.5, which is five cells against six - and `GateSpan` places the opening on the grid,
            // so the two are not the same rect. Both sides of a shared wall take the SAME one, which
            // is why it is computed from the wall's width rather than written twice.
            Rect gateNS = GateCutout(RoomWidth);
            Rect gateEW = GateCutout(RoomDepth);

            Transform r1 = BuildEmptyRoom(root.transform, "Room3_1", Vector3.zero,
                                          floorMat, grooveMat, panelMat, fixtureMat,
                                          doorwayNorth: false, ceilingHole: CycleTwoExitHole,
                                          northCutout: gateNS, southCutout: gateNS,
                                          westCutout: gateEW, eastCutout: gateEW);

            // THE FOUR ROOMS THE GATES OPEN ONTO. Empty shells for now - what goes in them is the
            // puzzle, and this is the way in.
            //
            // Each carries the matching cutout on the wall it shares with room3-1 and nothing else,
            // so a room is sealed except through its own gate. Their walls run the same way room3-1's
            // do (they are not turned to face it): a room to the east is still 8.75 across and 10.5
            // deep, which is what makes `RoomPitchX` the room's WIDTH plus the shared build-up.
            // TWICE ACROSS, TWICE DEEP, THREE TIMES TALL - ten cells, twelve cells, twelve rows,
            // every one an exact multiple of the grid the rest of the building uses.
            //
            const float bigWidth = 2f * RoomWidth;      // 17.5, ten cells
            const float bigDepth = 2f * RoomDepth;      // 21.0, twelve cells
            const float bigHeight = 3f * RoomHeight;    // 16.2234, twelve rows

            // **THE ROOM IS OFFSET HALF A CELL, and the corridor is not.** Room3-1's north wall has an
            // ODD cell count, so its middle cell is centred on the building's axis and the corridor
            // sits on it exactly. This room's south wall has an EVEN one - ten cells - so that axis
            // falls on a cell BOUNDARY here, and a centred opening straddled two cells and left a
            // half-panel either side. Play saw it immediately.
            //
            // Moving the ROOM rather than the corridor is what fixes it: shifted by half a cell, the
            // building's axis lands on the middle of one of this wall's cells and the mouth is exactly
            // one whole panel. A full cell would have changed nothing - the parity is what matters,
            // not the distance. The corridor stays where it is, so it is still centred in room3-1 and
            // merely enters this room half a cell off its centreline, which nothing can see.
            const float bigOffsetX = GridCellWidth / 2f;
            float mouthLocalX = -bigOffsetX;
            float halfMouth = gateNS.width / 2f;
            Rect corridorMouth = Rect.MinMaxRect(mouthLocalX - halfMouth, 0f,
                                                  mouthLocalX + halfMouth, GateHeight);

            // PLANNED BEFORE THE ROOM IS BUILT, because the walls have to be holed where the steps
            // go and the steps have to land in those holes. One plan, read twice.
            // TWO HOLES IN THIS ROOM, and they are its two ways on. The ceiling carries the ladder
            // shaft up to room3-0; the floor is room4-1's whole ceiling and opens at the break.
            Rect ladderHole = LadderShaftHole(LadderShaftXZ.x, LadderShaftXZ.y);

            Transform rN = BuildBigRoom(root.transform, "Room3_2N",
                           new Vector3(bigOffsetX, 0f, NorthRoomZ),
                           bigWidth, bigDepth, bigHeight,
                           floorMat, grooveMat, panelMat, fixtureMat, corridorMouth, Rect.zero,
                           CycleFourHole, ladderHole);
            Transform rS = BuildEmptyRoom(root.transform, "Room3_2S", new Vector3(0f, 0f, -RoomPitch),
                           floorMat, grooveMat, panelMat, fixtureMat,
                           doorwayNorth: false, northCutout: gateNS);
            Transform rE = BuildEmptyRoom(root.transform, "Room3_2E", new Vector3(RoomPitchX, 0f, 0f),
                           floorMat, grooveMat, panelMat, fixtureMat,
                           doorwayNorth: false, westCutout: gateEW);
            Transform rW = BuildEmptyRoom(root.transform, "Room3_2W", new Vector3(-RoomPitchX, 0f, 0f),
                           floorMat, grooveMat, panelMat, fixtureMat,
                           doorwayNorth: false, eastCutout: gateEW);

            // THE BED, and the point the loop teleports to at the top of every iteration.
            (_, Transform spawn) = BuildBed(r1, propMat, floorY: CycleThreeFloorY, zCentre: CycleThreeZ,
                                            yaw: 0f, xCentre: CycleThreeX);

            // Cycle 2's chest, in cycle 2's place, with cycle 2's lamp - and empty. Both bays are
            // wired as `GhostInteractable`s by `BuildDresser` whatever is in them, which is what makes
            // putting something in one later a one-line change rather than a signal-bit problem
            // (CLAUDE.md SS1.6).
            Drawer[] drawers = BuildDresser(r1, "Dresser3_1", new Vector3(-0.95f, 0f, 1.35f),
                                            yaw: 0f, withLamp: true);

            ParticleSystem[] gas = BuildGasEmitters(r1, "Room3_1_Gas", 0f);

            // ONE PAD PER DIRECTION, each on the axis of the wall it opens and 3.2m out from the
            // centre - clear of the bed, which sits in the middle of the room, and near enough to its
            // own gate that stepping on it and watching that wall open is one glance rather than a
            // hunt. The pads are otherwise identical and unlabelled: which one opens which wall is
            // meant to be learned by standing on one.
            Material padMat = MakeColorMaterial("Room3PadWhite", new Color(0.85f, 0.85f, 0.86f));
            const float padOut = 3.2f;
            var pads = new[]
            {
                BuildFloorButton(r1, padMat, "Pad3_1_North", new Vector3(0f, 0f, padOut)),
                BuildFloorButton(r1, padMat, "Pad3_1_South", new Vector3(0f, 0f, -padOut)),
                BuildFloorButton(r1, padMat, "Pad3_1_East", new Vector3(padOut, 0f, 0f)),
                BuildFloorButton(r1, padMat, "Pad3_1_West", new Vector3(-padOut, 0f, 0f)),
            };

            // EACH GATE TAKES ONE PAD, not all four. `Door.requiredFloorButtons` wants EVERY pad in
            // the array held at once - which is Room3's puzzle - and here the four walls are four
            // separate offers, so each array is one pad long.
            // **NORTH HAS NO GATE.** Its cutout is a permanent opening - the mouth of the corridor -
            // and pad 0 drives the slab partway down it instead. The other three walls are gates that
            // are not meant to be found; this one is a hole you can see down, with a mechanism in it
            // you are meant to see coming.
            CrushingBarrier northBarrier =
                BuildNorthCorridor(root.transform, floorMat, grooveMat, panelMat, pads[0]);

            // ROOM3-1'S FACE OF EACH GATE, and then the far room's face of the same gate. Both take
            // the same pad, so one wall opens; the far side skips the cavity liner because the near
            // side has already built it.
            BuildPanelGate(r1, "Gate3_1_South", new Vector3(0f, 0f, -RoomDepth / 2f),
                           Vector3.right, Vector3.forward, RoomWidth, panelMat, grooveMat,
                           new[] { pads[1] });
            BuildPanelGate(rS, "Gate3_2S_North", new Vector3(0f, 0f, RoomDepth / 2f),
                           Vector3.right, Vector3.back, RoomWidth, panelMat, grooveMat,
                           new[] { pads[1] }, withCavityLiner: false);

            BuildPanelGate(r1, "Gate3_1_East", new Vector3(RoomWidth / 2f, 0f, 0f),
                           Vector3.forward, Vector3.left, RoomDepth, panelMat, grooveMat,
                           new[] { pads[2] });
            BuildPanelGate(rE, "Gate3_2E_West", new Vector3(-RoomWidth / 2f, 0f, 0f),
                           Vector3.forward, Vector3.right, RoomDepth, panelMat, grooveMat,
                           new[] { pads[2] }, withCavityLiner: false);

            BuildPanelGate(r1, "Gate3_1_West", new Vector3(-RoomWidth / 2f, 0f, 0f),
                           Vector3.forward, Vector3.right, RoomDepth, panelMat, grooveMat,
                           new[] { pads[3] });
            BuildPanelGate(rW, "Gate3_2W_East", new Vector3(RoomWidth / 2f, 0f, 0f),
                           Vector3.forward, Vector3.left, RoomDepth, panelMat, grooveMat,
                           new[] { pads[3] }, withCavityLiner: false);

            // EVERY GATE PROVED CLEAR, which is the one thing this room can get silently wrong. The
            // opening is cut out of two walls' collision and two liners are built into the cavity
            // beside it, and any of the four rects being a hair off leaves a gate you can see through
            // and not walk through. `AssertWalkable` ignores the leaves themselves (they carry
            // `Door`), so what it is really testing is everything AROUND them.
            // THROUGH THE OPENING, WHICH IS NOT THE MIDDLE OF THE WALL on the five-cell north and
            // south - a probe down the wall's centreline there would sweep half a metre of solid
            // panel and report a blockage that is the wall doing its job.
            float nsCentre = gateNS.center.x, ewCentre = gateEW.center.x;
            // The corridor end to end, which also proves its mouth and its far doorway. The slab is
            // ignored like any `Door`-shaped obstruction would not be - it is NOT a Door, so it has to
            // be authored raised for this to pass, and it is authored SHUT. Probing the two halves
            // separately is what tests the geometry rather than the mechanism.
            // §CYCLE 3'S BEAM. The emitter, the five mirrors and the one thing the light has to
            // reach. None of it costs a signal bit - a mirror is a `CarryableItem`, so a past self
            // holding one is a `CarryEvent` and a recorded position, both of which already exist.
            LaserBeam beam = BuildLaserEmitter(rE, propMat);
            CarryableItem[] mirrors = BuildMirrorRack(rW, propMat);
            // **A HAND-OVER OF A MIRROR IS WORTH REPRODUCING**, and until 2026-08-30 no ghost could
            // do one: `GhostReplayer.Eligible` allowed a take off another past self only for objects
            // with a SOCKET, and a mirror has none. So a player who took a pane off a ghost and stood
            // in its place had that take refused in every later iteration - the one thing this cycle
            // is about, silently not accumulating. See `CarryableItem.ghostHandover`.
            foreach (CarryableItem pane in mirrors) if (pane != null) pane.ghostHandover = true;
            // THE WEST PLATE, which is where the beam has had to arrive since 2026-08-21.
            LaserReceiver receiver = BuildLaserReceiver(rN, "LaserReceiver",
                new Vector3(-bigWidth / 2f + 0.18f, BeamHeight, 5f), Vector3.right, propMat);
            // **AND ONE DIRECTLY OPPOSITE IT** (2026-08-28, by request). Same height, same z, the
            // other wall - so one pane held between them answers either by turning round, and which
            // storey the player is buying is a decision made with their body rather than with a
            // different object. Neither plate can be lit by the same beam as the other: each is a
            // solid that stops the light, so a beam has one of them or the other and never both.
            LaserReceiver receiverEast = BuildLaserReceiver(rN, "LaserReceiver_East",
                new Vector3(bigWidth / 2f - 0.18f, BeamHeight, 5f), Vector3.left, propMat);

            // §ROOM3-2N'S GROUND FLOOR. The beam and the lifts are what the room's HEIGHT is for;
            // this is what its floor is for, and it costs no signal bit - a block is a
            // `CarryableItem`, so a past self carrying one is a `CarryEvent` and a recorded
            // position, both of which already exist.
            BedlamCube bedlam = BuildBedlamCube(rN, bigWidth, bigDepth, mouthLocalX, propMat);
            // ROOM3-0, ON TOP OF THIS ROOM. Cycle 3 can be finished from here on: `AssembleCycleThree`
            // finds this sequence and hands it to the `Cycle`, and `Build` gives it the way down.
            (Transform r0, FinalRoomSequence finalRoom) = BuildBreakRoomThree(
                root.transform, floorMat, grooveMat, panelMat, propMat, fixtureMat);

            // THE LADDER, IN ROOM3-2S, AND THE SPOT IT GOES IN, ON DECK B. Two rooms apart on
            // purpose: what this cycle charges for is trips.
            CarryableItem ladder = BuildLadder(rS, propMat);
            LadderMount ladderMount = BuildLadderMount(rN, propMat, r0.Find("Dismounts"));

            // THE SIGN THAT SAYS WHAT IS MISSING. On deck B's wall beside the shaft, and it is the
            // only thing in the room that explains the hole in the ceiling - a pictogram of a ladder
            // over a spot with no ladder in it is a sentence.
            // ON THE WEST WALL, beside the shaft. The shaft is at the north end of deck B's west
            // strip and the south wall is seventeen metres away - a sign that far from the thing it
            // is about is a sign about nothing. Yawed to face east, into the room.
            BuildLadderSign(rN, new Vector3(-bigWidth / 2f + 0.06f, DeckBSurfaceY + 1.7f,
                                            LadderShaftXZ.y),
                            Quaternion.Euler(0f, -90f, 0f));

            // THE LADDER SHAFT: room3-2N's ceiling, one service void, room3-0's floor. The tube's
            // walls are what stop the gap between two storeys being visible through the hole.
            GameObject shaft = new GameObject("LadderShaft");
            shaft.transform.SetParent(rN, false);
            shaft.transform.localPosition = new Vector3(LadderShaftXZ.x, bigHeight + WallThickness,
                                                        LadderShaftXZ.y);
            float outer = GridCellWidth + 2f * WallThickness;
            float halfCell = GridCellWidth / 2f;
            Prim(PrimitiveType.Cube, "Shaft_West", shaft.transform,
                new Vector3(-halfCell - WallThickness / 2f, LadderVoid / 2f, 0f),
                new Vector3(WallThickness, LadderVoid, outer), panelMat);
            Prim(PrimitiveType.Cube, "Shaft_East", shaft.transform,
                new Vector3(halfCell + WallThickness / 2f, LadderVoid / 2f, 0f),
                new Vector3(WallThickness, LadderVoid, outer), panelMat);
            Prim(PrimitiveType.Cube, "Shaft_South", shaft.transform,
                new Vector3(0f, LadderVoid / 2f, -halfCell - WallThickness / 2f),
                new Vector3(GridCellWidth, LadderVoid, WallThickness), panelMat);
            Prim(PrimitiveType.Cube, "Shaft_North", shaft.transform,
                new Vector3(0f, LadderVoid / 2f, halfCell + WallThickness / 2f),
                new Vector3(GridCellWidth, LadderVoid, WallThickness), panelMat);

            // THE ROUTE AS NUMBERS, because "does the light have anywhere to go" is exactly the kind
            // of thing that is obvious in a plan and wrong in a build. Every figure here is read off
            // the objects rather than restated from the constants that placed them.
            Mirror firstMirror = mirrors.Length > 0 && mirrors[0] != null
                ? mirrors[0].GetComponent<Mirror>() : null;
            // THE BED'S FOOTPRINT, because the beam's lane is placed to miss it and "does it" is
            // not answerable from a plan. The corner mirror has to be STOOD at, on the corridor's
            // axis, so whether the lane can be centred is a question about this box.
            Transform bedT = r1.Find("Bed") ?? r1;
            Bounds bedBox = MeasuredBounds(bedT.gameObject);
            Debug.Log($"[SceneBuilder] Cycle 3 bed: centre {bedBox.center}, size {bedBox.size}");

            Debug.Log($"[SceneBuilder] Cycle 3 beam: emitter at {beam.muzzle.position}, "
                    + $"firing {beam.muzzle.forward}, plane y={CycleThreeFloorY + BeamHeight:0.###}, "
                    + $"wall offset {BeamLane:0.##}, west leg must leave within "
                    + $"+-{GateCutout(RoomDepth).width / 2f:0.##} of the gate's centre. "
                    + $"{mirrors.Length} mirrors, glass {(firstMirror != null ? firstMirror.radius * 2f : 0f):0.###}m "
                    + $"across. Receiver at {receiver.transform.position}, target radius "
                    + $"{receiver.radius:0.##}m.");

            // **THE CCTV SYSTEM IS GONE** (2026-08-28, by request), and with it the only asset in the
            // project that could not be sold: `cctv_camera.glb` is CC-BY-NC-4.0. Three cameras in
            // room3-2N and three screens on room3-2S's walls, watching a coloured staircase that was
            // deleted in 2026-08-21 - the feeds had outlived their subject by a week and were being
            // kept because they worked, not because anything needed them.
            //
            // WHAT ROOM3-2S IS FOR NOW: the pane that leaves the horizontal plane starts here. That
            // keeps the four-rooms-four-jobs split the screens were bought to make -
            //
            //     room3-2E  the source          room3-2W  the flat mirrors
            //     room3-2S  the riser           room3-2N  where the light has to arrive
            //
            // - and it turns the control room from somewhere you LOOK into somewhere you FETCH from,
            // which is a better use of a room in a game whose currency is trips.
            //
            // **IT IS CARRIED, NOT INSTALLED.** A pane bolted to room3-2S's wall would send the beam
            // into a 5.4m ceiling and nothing else; carried, it goes wherever the player takes it,
            // and the room that wants a beam going up is the 16.2m one down the corridor.
            // §THE LIFT, AND THE FIRST THING `LaserReceiver.Lit` HAS EVER DRIVEN (2026-08-28, by
            // request). Room3-2N is three storeys tall with two decks and no way onto either; this is
            // the way onto deck A, and it is worked entirely by light.
            //
            // **THE LOW CALL IS THE PLATE THAT WAS ALREADY THERE.** The beam has had a destination
            // since 2026-08-21 and nothing at the far end of it - `Lit` was deliberately left driving
            // nothing until somebody had bounced the light by hand. That has happened, so the plate
            // gets its consumer rather than a second plate being built beside it.
            // **~~THE CEILING CALL~~ GONE 2026-08-30, by request.** It was a plate on room3-2N's
            // ceiling that only the riser pane could reach, and it drove lift A from above so the
            // ride was not one-way. What replaced the reason for it is the LADDER: the way up out of
            // deck B is a thing you carry, not a thing you light.
            //
            // Lift A keeps the west plate, so it can still be called from the ground floor by a past
            // self holding a mirror - which is what brings it DOWN with somebody on it. Nothing about
            // the ride is lost; what is gone is the second way to ask for it.

            // **LIFT 1: THE FLOOR TO DECK A.** Butted against deck A's inner edge - deck A is an L two
            // cells deep down the west wall, so its edge is at `-width/2 + 2 * GridCellWidth` and
            // anywhere else lands the ride BESIDE the deck instead of on it.
            BeamLift liftA = BuildBeamLift(rN, "BeamLift_A",
                new Vector2(DeckALiftX, DeckALiftZ), DeckALiftPad,
                LiftRestingStep, DeckARows * GridCellHeight,
                propMat, grooveMat, shaftFootY: null, receiver);

            // **LIFT 2: DECK A TO DECK B, AND IT RISES THROUGH THE HOLE THAT WAS ALREADY THERE.**
            //
            // Deck B has a 1.75 x 3.5 void cut clean out of it, put there in 2026-08-21 so that
            // standing on deck B you look through onto deck A and past deck A's open side to the floor
            // - three storeys in one glance. A shaft between the two decks has to come up through
            // SOMETHING, and a hole whose whole purpose is to be looked down is the one place in this
            // room where a rising slab is not an intrusion. So the shaft is the void, and no geometry
            // had to be cut for it.
            //
            // **WHERE INSIDE THE VOID IS FORCED, not chosen.** The panel is pushed to the void's NORTH
            // end so that at the top its north edge meets deck B's slab and you step off across.
            // Centred, it would arrive surrounded by hole on the south and 7.5cm gaps elsewhere -
            // standing on a platform you cannot get off. Its footprint also has to have deck A UNDER
            // it at the bottom, and deck A only reaches this x through its north strip (z >= 7).
            BeamLift liftB = BuildBeamLift(rN, "BeamLift_B",
                new Vector2(DeckBLiftX, DeckBVoidMaxZ - DeckBLiftPad / 2f), DeckBLiftPad,
                DeckARows * GridCellHeight + LiftRestingStep, DeckBRows * GridCellHeight,
                // **ITS COLUMN GOES ALL THE WAY DOWN TO THE GROUND, THROUGH DECK A** (2026-08-28, by
                // request). It stood on deck A, which is honest engineering and reads as a lift with
                // no visible reason to exist - a machine that begins one storey up begs the question
                // of what holds THAT up. Taken to the floor it becomes the room's one full-height
                // object, and standing under deck A you can see the thing that serves the storey
                // above you. `PlanMezzanines` cuts deck A open for it.
                propMat, grooveMat, shaftFootY: 0f, receiverEast);

            // AND THE LINES THAT SAY WHICH PLATE WORKS WHICH LIFT. Painted on the wall under each
            // plate and along the floor to the lift it calls - the east one has to cross most of a
            // 17.5m room to reach lift B, which is exactly why the mapping needed saying.
            //
            // The ceiling call gets none: it drives lift A, whose line is already drawn, and a second
            // stripe to the same slab would suggest a second machine.
            BuildCallConduit(rN, "Marking_A",
                new Vector3(-bigWidth / 2f + 0.18f, BeamHeight, 5f), Vector3.right,
                new Vector2(DeckALiftX, DeckALiftZ));
            BuildCallConduit(rN, "Marking_B",
                new Vector3(bigWidth / 2f - 0.18f, BeamHeight, 5f), Vector3.left,
                new Vector2(DeckBLiftX, DeckBVoidMaxZ - DeckBLiftPad / 2f));

            BeamLift[] lifts = { liftA, liftB };

            // **~~THE 45-DEGREE RISER PANE~~ GONE 2026-08-30, by request**, and it had already lost
            // its job. Its one purpose was to take the beam out of the horizontal plane and up to the
            // ceiling call, and that plate went two days earlier when the ladder replaced it as the
            // way off deck B. A pane that can only reach a target nothing has is a pane that teaches
            // the player a trick with nothing to use it on.
            //
            // Room3-2S keeps its job and it is a better one: it is where the LADDER is fetched from.
            // The four-rooms-four-jobs split the cycle is built on is unchanged -
            //
            //     room3-2E  the source          room3-2W  the flat mirrors
            //     room3-2S  the ladder          room3-2N  where the light has to arrive

            AssertWalkable(r1, "room3-1 north corridor mouth",
                new Vector3(nsCentre, 0f, RoomDepth / 2f - 1.2f), new Vector3(nsCentre, 0f, RoomDepth / 2f + 4f));
            AssertWalkable(r1, "room3-1 south gate",
                new Vector3(nsCentre, 0f, -RoomDepth / 2f + 1.2f), new Vector3(nsCentre, 0f, -RoomDepth / 2f - 1.2f));
            AssertWalkable(r1, "room3-1 east gate",
                new Vector3(RoomWidth / 2f - 1.2f, 0f, ewCentre), new Vector3(RoomWidth / 2f + 1.2f, 0f, ewCentre));
            AssertWalkable(r1, "room3-1 west gate",
                new Vector3(-RoomWidth / 2f + 1.2f, 0f, ewCentre), new Vector3(-RoomWidth / 2f - 1.2f, 0f, ewCentre));

            Debug.Log($"[SceneBuilder] Cycle 3: Room3_1 at ({CycleThreeX:0.##}, {CycleThreeFloorY:0.###}, "
                    + $"{CycleThreeZ:0.##}), 4 pads: 3 gates ({gateEW.width:0.##} E/W, "
                    + $"{gateNS.width:0.##} S) and a {CorridorRun:0.##}m "
                    + $"filled corridor north into Room3_2N ({2f * RoomWidth:0.##}x{2f * RoomDepth:0.##}"
                    + $"x{3f * RoomHeight:0.###})");
            // THE TWO DRAWER BAYS ARE THE WHOLE SIGNAL ARRAY, and they are in it before anything is
            // in THEM - the same order cycle 2's chest was wired in, and for the reason CLAUDE.md
            // SS1.6 gives: an entry's index IS its bit, so appending one later is the one change this
            // array makes awkward. Numbered from zero, which is legal because every ghost is destroyed
            // at a cycle boundary and no surviving timeline refers to another cycle's bits.
            // THE DRAWERS FIRST, THEN THE FOUR PADS, and the order is the wire format. An entry's
            // index IS its bit in `RecordedFrame.signals` (CLAUDE.md SS1.6), so this array is
            // append-only - a pad inserted ahead of the drawers would make every timeline recorded
            // before it replay the wrong fixture. Six of the thirty-two bits are spent.
            //
            // The pads MUST be in here or the whole room does not work: a `FloorButton` outside the
            // signal array is a pad no past self ever stands on, and every gate in this room is
            // opened by a past self.
            // Drawers, then pads, then levers - APPEND ONLY, because an entry's index is its bit in
            // `RecordedFrame.signals` (CLAUDE.md SS1.6). Nine of the thirty-two are spent.
            //
            // **THE LEVERS MUST BE IN HERE or room3-2N cannot be climbed at all.** A `GhostInteractable`
            // outside this array is a fixture no past self ever operates, and every step in that room
            // is held up by a past self.
            var signals = new GhostInteractable[drawers.Length + pads.Length];
            for (int i = 0; i < drawers.Length; i++) signals[i] = drawers[i];
            for (int i = 0; i < pads.Length; i++) signals[drawers.Length + i] = pads[i];

            return (root.transform, spawn, gas, r1, signals, northBarrier, lifts);
        }

        // THE BED A PLAYER FALLS INTO HAS TO BE UNDER THE HATCH THEY FELL THROUGH, and nothing else in
        // the build checks that. `CycleThreeX`/`Z` are read off room2-0 by hand (see their comment), so
        // this is the line that notices when room2-0 moves and they do not.
        private static void AssertUnderHatch(Transform breakRoom)
        {
            if (breakRoom == null) return;

            Vector3 hatch = breakRoom.position;
            float dx = Mathf.Abs(hatch.x - CycleThreeX), dz = Mathf.Abs(hatch.z - CycleThreeZ);
            if (dx < 0.05f && dz < 0.05f) return;

            Debug.LogError($"[SceneBuilder] Cycle 3's bed room is not under room2-0's hatch: the hatch "
                + $"is at ({hatch.x:0.##}, {hatch.z:0.##}) and CycleThreeX/Z say "
                + $"({CycleThreeX:0.##}, {CycleThreeZ:0.##}). A player dropping through would land "
                + "outside the room, or inside a wall. Update the two constants.");
        }

        private static (Transform room, FinalRoomSequence final, CycleExit exit) BuildBreakRoom(
            Transform parent, Vector3 at, Material floorMat, Material grooveMat, Material panelMat,
            Material propMat, Material fixtureMat)
        {
            Transform t = BuildEmptyRoom(parent, "Room2_0", at, floorMat, grooveMat, panelMat,
                                         fixtureMat, doorwayNorth: true, floorHole: CycleTwoExitHole);

            // --- the four pedestals -----------------------------------------------------------------
            GameObject rack = new GameObject("Room2_0_Pedestals");
            rack.transform.SetParent(t, false);

            // AUTHORED RAISED and sunk in `RewardPlinth.Awake`, like every other plinth in the game:
            // a scene whose only props are invisible cannot be checked without pressing Play.
            RewardPlinth risen = rack.AddComponent<RewardPlinth>();
            risen.plinth = rack.transform;
            risen.riseHeight = PedestalHeight + 0.06f;
            risen.riseSeconds = 2.4f;

            // ALL FOUR RIMS ARE THE SAME COLOUR, and that is the design rather than an omission.
            //
            // The first build gave each pedestal an accent of its own, and play reported the obvious
            // thing: the rim colour and the ball that goes in it disagree. Billiard balls are a
            // standard set - 2 blue, 3 red, 4 purple, 5 orange - so there are only two ways to stop
            // them disagreeing, and MATCHING them is the one that costs the puzzle. A purple rim over
            // a purple ball turns "how many buckets are there" into "find the purple one", and the
            // pictogram on the side becomes decoration.
            //
            // Identical neutral rims say nothing instead. Every one of them lights the same way for
            // every ball, because `offerItemIds` is the whole family - so the row answers a press and
            // never a question, and the only thing in the room that distinguishes one pedestal from
            // another is the object drawn on it.
            Color rim = new Color(0.78f, 0.79f, 0.82f);

            // **THREE, DOWN FROM FOUR** (2026-08-29, by request: the beach ball's pedestal is gone,
            // the bucket, the axe and the duck stay).
            //
            // Every entry here is a WHOLE ROUND TRIP - one hand, sixty seconds, and a ball that has
            // to be found in the chest and carried to room2-0 - so the count is the room's length
            // rather than its difficulty. Cycle 2 measured at 22 iterations against cycle 1's 9, and
            // this is one of the two places that number is set (the other is room2-7's latch, see
            // `TODO.md`). Nothing about the puzzle changes: the chest still holds nine balls, three
            // of which are wanted, so reading the pictogram is still the whole of it.
            //
            // `wants.Length` drives the pedestals, the slots and the completion count, so removing a
            // row is the entire change.
            var wants = new (string name, string ball, Sprite icon)[]
            {
                ("Axe",    BilliardIdPrefix + "5", AxeIcon()),
                ("Duck",   BilliardIdPrefix + "3", DuckIcon()),
                ("Bucket", BilliardIdPrefix + "4", FullBucketIcon()),
            };

            string[] family = BilliardIds();
            var slots = new FinalSlot[wants.Length];

            for (int i = 0; i < wants.Length; i++)
            {
                float x = (i - (wants.Length - 1) / 2f) * PedestalPitch;

                GameObject unit = new GameObject("Pedestal_" + wants[i].name);
                unit.transform.SetParent(rack.transform, false);
                unit.transform.localPosition = new Vector3(x, 0f, PedestalRowZ);

                // THE BODY STOPS SHORT OF THE TOP, and the socket cap makes up the difference. The
                // cap is where the bowl is cut, so the material the bowl is cut OUT of has to be the
                // cap and not the body - a box primitive cannot have a hole in it.
                //
                // Its collider goes on the unit instead, at full height, so the pedestal is still one
                // solid object to walk into. Rising through somebody standing exactly on it is not
                // reachable: the rise starts as they clear a doorway eight metres away.
                Prim(PrimitiveType.Cube, "Body", unit.transform,
                     new Vector3(0f, (PedestalHeight - SocketCapThickness) / 2f, 0f),
                     new Vector3(PedestalWidth, PedestalHeight - SocketCapThickness, PedestalDepth),
                     propMat, removeCollider: true);

                BoxCollider solid = unit.AddComponent<BoxCollider>();
                solid.center = new Vector3(0f, PedestalHeight / 2f, 0f);
                solid.size = new Vector3(PedestalWidth, PedestalHeight, PedestalDepth);

                // A HEMISPHERE CUT TO THE BALL'S OWN RADIUS, 2026-08-20 by request. It was a flat
                // disc, and a flat disc says "something round belongs here" where this room has to
                // say "a BILLIARD BALL belongs here" - a bowl a ball drops half into is a shape that
                // can be for nothing else. `SlotShape.Dish` builds the cap, the bowl and the lit ring
                // round its mouth as one thing; see BallSocketMesh.
                //
                // All four are identical, which is exactly right: they take the same KIND of object
                // and differ only in WHICH one, and that difference is carried by the pictogram on
                // the side and by nothing else in the room (see `rim` above).
                slots[i] = BuildFinalSlot(unit.transform, "Slot", SlotShape.Dish,
                    new Vector3(0f, PedestalHeight, 0f), SocketBowlRadius * 2f, rim,
                    reachCentre: new Vector3(0f, -0.55f, 0.42f),
                    reachSize: new Vector3(1.30f, 2.60f, 2.00f),
                    dishPlateHalf: new Vector2(PedestalWidth / 2f, PedestalDepth / 2f));
                slots[i].acceptedItemId = wants[i].ball;
                // ...AND IT WILL TAKE A PRESS FOR ANY OF THEM. Without this the rim would light for
                // the right ball and stay dark for the other eight, which hands the player the answer
                // for the cost of carrying each ball past each pedestal. See FinalSlot.offerItemIds.
                slots[i].offerItemIds = family;
                // The sound of no. Nothing in this project is a buzzer, so the switch's off-click is
                // borrowed - short, mechanical, and audibly not the sound an object landing makes.
                slots[i].refuseClip = LoadClip(SfxDir, "sfx_switch_off");

                BuildPedestalSign(unit.transform, wants[i].name, wants[i].icon);
            }

            // --- the way in, and the way down --------------------------------------------------------
            //
            // "The player got through the last door", which is what raises the rack. A latch, cleared
            // by the loop at the top of an iteration, so each run has to arrive for itself. Its
            // `door` is wired at the call site - the door is room2-7's and is built later.
            GameObject escapeGO = new GameObject("EscapeTrigger_Cycle2");
            escapeGO.transform.SetParent(t, false);
            escapeGO.transform.localPosition = new Vector3(0f, 0f, RoomDepth / 2f);
            EscapeTrigger escape = escapeGO.AddComponent<EscapeTrigger>();
            escape.halfWidth = DoorWidth / 2f + 0.05f;

            // **THE HATCH IS NOT BUILT HERE ANY MORE, since cycle 3 exists.** It was, while there was
            // nothing underneath: a lid in this room's floor and a capped shaft under it, all owned by
            // room2-0 because there was no storey for it to join TO.
            //
            // There is one now, and a `CycleExit` drives BOTH lids - the floor above and the ceiling
            // below - so it cannot live in either cycle's scene: a reference across a scene boundary
            // comes back null and Unity does not say so. It moves to `CycleJoin_2_3` in the core
            // scene, which is where cycle 1's has always been and for exactly this reason. See Build.
            CycleExit exit = null;

            GameObject seqGO = new GameObject("BreakSequence");
            seqGO.transform.SetParent(t, false);
            FinalRoomSequence sequence = seqGO.AddComponent<FinalRoomSequence>();
            sequence.console = risen;
            sequence.slots = slots;
            // AND EACH RECESS POINTS BACK, which it did not for the first two builds of this room.
            // `FinalSlot.Live` is `sequence != null && sequence.Active`, so four null sequences meant
            // four recesses that were never live: no prompt, and E did nothing at any of them. The
            // room looked finished and could not be finished. Cycle 1's builder has always had this
            // line; this one was written without it, which is why `CycleBinding` now re-establishes
            // it at runtime as well.
            foreach (FinalSlot slot in slots) if (slot != null) slot.sequence = sequence;
            sequence.arrival = escape;
            // `wayOut` is wired in `Build` along with the hatch itself, and `CycleBinding` writes it
            // again at runtime from `wayOuts`.
            //
            // **AND THE BREAK NO LONGER OPENS THE FLOOR**, which it did for exactly as long as there
            // was nothing under it. `LoopManager.CrossToNextCycle` owns the hatch now: it wakes cycle
            // 3, repoints the gas at it and THEN opens the way down, because a player must not be able
            // to drop into a storey that is still asleep.
            sequence.opensWayOutOnBreak = false;
            sequence.breakDuration = 10f;

            return (t, sequence, exit);
        }

        // ONE OBJECT DRAWN ON THE FRONT OF A PEDESTAL, and it is the whole of what the pedestal says.
        //
        // No word, no number, no rim colour that means anything - the four accents differ so the row
        // is four objects rather than one repeated, and none of them is a clue. A pictogram is the
        // only instrument in this building that can ask "how many of these are there" without also
        // answering it.
        //
        // FACING THE DOOR. A canvas's forward must match the direction the VIEWER is looking rather
        // than point at them (see MakeWallFace), and a player reading this is walking south - so yaw
        // 180, the same as the sign over room2-7's south door.
        private static void BuildPedestalSign(Transform unit, string name, Sprite icon)
        {
            CanvasGroup face = MakeWallFace(unit, "Sign",
                new Vector3(0f, PedestalHeight * 0.55f, PedestalDepth / 2f + 0.02f),
                Quaternion.Euler(0f, 180f, 0f),
                f => MakeWallIcon(f, name, icon, Vector2.zero, 1280f,
                                  new Color(0.20f, 0.20f, 0.23f, 0.88f)),
                worldWidth: 0.78f, withPlate: false, authoredHeight: 1600f);

            // MakeWallFace authors every sign at alpha 0, because the ones it was built for are faded
            // in and retired by `PanelMessage`. These never go: they are true for as long as the room
            // is unsolved.
            if (face != null) face.alpha = 1f;
        }

        private static (Transform room, WeighScale scale)
            BuildWeighRoom(Transform parent, Material floorMat, Material grooveMat, Material panelMat,
                           Material propMat, Material fixtureMat)
        {
            GameObject rootGO = new GameObject("Room2_7_Root");
            rootGO.transform.SetParent(parent, false);
            rootGO.transform.localPosition = new Vector3(SlideRoomCentreX, SlideRoomFloorY,
                                                          SlideRoomCentreZ - RoomPitch);

            GameObject roomGO = new GameObject("Room2_7");
            roomGO.transform.SetParent(rootGO.transform, false);
            Transform t = roomGO.transform;

            BuildSlab(t, "Floor", -WallThickness / 2f, 0f, floorMat, default);
            BuildSlab(t, "Ceiling", RoomHeight + WallThickness / 2f, 0f, CeilingMaterial(), default);

            BuildPanelWall(t, "Wall_North", new Vector3(0f, 0f, RoomDepth / 2f),
                Vector3.right, Vector3.back, RoomWidth, grooveMat, panelMat,
                new Rect(-DoorWidth / 2f, 0f, DoorWidth, DoorHeight));
            // THE SOUTH WALL IS CUT FOR THE WAY ON, and it was NOT - which is why room2-7 appeared to
            // have neither a door nor a sign. `BuildPadDoor` places a door slab and `MakeWallFace`
            // hangs the target number over it, and both were doing exactly that INSIDE a solid wall:
            // the door had no opening to slide across and the number was behind the panelling.
            //
            // The lesson generalises past this room: a door and its opening are two separate calls in
            // two different places, and nothing in the build checks that a door has a hole. If a door
            // is invisible, look for the Rect before looking at the door.
            BuildPanelWall(t, "Wall_South", new Vector3(0f, 0f, -RoomDepth / 2f),
                Vector3.right, Vector3.forward, RoomWidth, grooveMat, panelMat,
                new Rect(-DoorWidth / 2f, 0f, DoorWidth, DoorHeight));
            BuildPanelWall(t, "Wall_West", new Vector3(-RoomWidth / 2f, 0f, 0f),
                Vector3.forward, Vector3.right, RoomDepth, grooveMat, panelMat, Rect.zero);
            BuildPanelWall(t, "Wall_East", new Vector3(RoomWidth / 2f, 0f, 0f),
                Vector3.forward, Vector3.left, RoomDepth, grooveMat, panelMat, Rect.zero);

            BuildCeilingLights(t, "Room2_7", 0f, fixtureMat, castShadows: true);
            BuildReflectionProbe(t, "Room2_7", 0f);

            WeighScale scale = BuildWeighScale(t, propMat);
            BuildWeighPictogram(t, scale);
            return (t, scale);
        }

        // A FLAT PANEL WHERE THE MODEL HAD ITS OWN NUMBER.
        //
        // **THE SCALE'S DIGITS ARE GEOMETRY, NOT A TEXTURE**, and that took looking at the file to
        // find: `weigh_scale.glb` has no textures at all - four flat-colour materials - and its green
        // display is a single connected surface of 45 vertices and 54 triangles, 0.1 deep, with a
        // fixed number embossed into it. A first pass rebuilt that mesh's UVs and drew the live
        // reading onto it, which mapped a picture of digits across a surface that IS digits: play
        // reported it as the panel overlapping the number behind it, and that is exactly what it was.
        //
        // So the submesh is REPLACED rather than re-mapped. The model's fixed number goes with it -
        // asked for, and unavoidable anyway, since it is the same triangles - and what stands in its
        // place is a quad across the same footprint, at the same outer face, with clean 0..1 UVs. The
        // display is still the model's own display part, in the model's own place; it is simply a
        // surface something can be drawn on now.
        //
        // DOUBLE-SIDED, as eight vertices rather than four. Which way the panel's outer face points
        // is decided by the model's import rotation, and a single-sided quad that guessed wrong would
        // be invisible from above with nothing to say why.
        //
        // Saved as an asset, like every other generated mesh here: a `Mesh` built at edit time and
        // assigned straight to a scene object does not survive the scene being reloaded.
        private static Mesh FlatPanelMesh(Mesh source, string assetName)
        {
            if (source == null) return null;

            Bounds b = source.bounds;
            return SaveGeneratedMesh(assetName + "_panel", () =>
            {
                // The two widest axes are the face; the third is its thickness.
                int thin = b.size.x <= b.size.y && b.size.x <= b.size.z ? 0
                         : b.size.y <= b.size.z ? 1 : 2;
                int across = thin == 0 ? 2 : 0;
                int up = thin == 1 ? 2 : 1;

                // At the OUTER face rather than the middle: the digits were embossed toward the top of
                // the scale, so that is the side anything replacing them has to be on.
                float at = b.max[thin];

                Vector3 Corner(float u, float v)
                {
                    Vector3 c = Vector3.zero;
                    c[across] = Mathf.Lerp(b.min[across], b.max[across], u);
                    c[up] = Mathf.Lerp(b.min[up], b.max[up], v);
                    c[thin] = at;
                    return c;
                }

                Vector3 normal = Vector3.zero;
                normal[thin] = 1f;

                var verts = new Vector3[8];
                var norms = new Vector3[8];
                var uvs = new Vector2[8];
                var tris = new int[12];

                for (int side = 0; side < 2; side++)
                {
                    int o = side * 4;
                    verts[o + 0] = Corner(0f, 0f);
                    verts[o + 1] = Corner(1f, 0f);
                    verts[o + 2] = Corner(1f, 1f);
                    verts[o + 3] = Corner(0f, 1f);

                    for (int i = 0; i < 4; i++) norms[o + i] = side == 0 ? normal : -normal;

                    // **THE BACK FACE IS MIRRORED, AND IT IS THE ONE BEING LOOKED AT.**
                    //
                    // Two sides of a quad see the same texture from opposite directions, so whichever
                    // one the player is on, one of them reads back to front. Play saw exactly that -
                    // the number as if in a mirror - which also settles which face is up: the panel's
                    // outward normal points AWAY from the player, so it is the back set they see.
                    //
                    // Giving the two sides opposite U fixes it for both at once, which is better than
                    // flipping the whole thing and hoping: read from above or from underneath, the
                    // number runs the right way.
                    bool mirrored = side == 1;
                    float u0 = mirrored ? 1f : 0f, u1 = mirrored ? 0f : 1f;
                    uvs[o + 0] = new Vector2(u0, 0f);
                    uvs[o + 1] = new Vector2(u1, 0f);
                    uvs[o + 2] = new Vector2(u1, 1f);
                    uvs[o + 3] = new Vector2(u0, 1f);
                }

                // Front wound one way, back the other, so both faces are lit and drawn correctly.
                int[] front = { 0, 2, 1, 0, 3, 2 };
                int[] back = { 4, 5, 6, 4, 6, 7 };
                System.Array.Copy(front, 0, tris, 0, 6);
                System.Array.Copy(back, 0, tris, 6, 6);

                var mesh = new Mesh { name = assetName + "_panel" };
                mesh.vertices = verts;
                mesh.normals = norms;
                mesh.uv = uvs;
                mesh.triangles = tris;
                mesh.RecalculateBounds();
                return mesh;
            });
        }

        // AN UNLIT SURFACE. Used for the scale's display, which carries its own brightness in its
        // texture and must not be shaded by the room - a lit panel goes grey in a shadow, and an LCD
        // that dims when you lean over it is a painted one.
        private static Material MakeUnlitMaterial(string name, Color colour)
        {
            string path = $"{MaterialsDir}/{name}.mat";
            Shader unlit = Shader.Find("Universal Render Pipeline/Unlit");
            if (unlit == null) unlit = OpaqueShader();

            Material mat = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (mat == null)
            {
                mat = new Material(unlit);
                AssetDatabase.CreateAsset(mat, path);
            }
            mat.shader = unlit;
            mat.color = colour;
            EditorUtility.SetDirty(mat);
            return mat;
        }

        // ROOM2-7'S SIGNS: what can be weighed, and what the total has to come to.
        //
        // THE ROOM CANNOT BE SOLVED WITHOUT THEM, and that is why they exist rather than as decoration.
        // The design is that a player is told no WEIGHTS - they learn those on the scale - but a player
        // told nothing at all has no reason to think this room wants a sum at all, let alone which
        // objects are eligible or what number to hit. So the signs say exactly the two things that are
        // not discoverable by experiment and nothing else:
        //
        //   - the SIDE WALLS carry the shape of the answer: `A + B + C = ?`, drawn from the objects
        //     themselves, so "bring things here and add them up" is stated without a word;
        //   - the WALL OVER THE DOOR carries the target, `= 23.0`, over the thing it opens.
        //
        // The question mark is the point of the side walls. It says the total is the unknown, which
        // makes the scale's readout the place to look - and it leaves every weight, and which three
        // objects to use, entirely to the player.
        //
        // DRAWN, NOT WRITTEN. Everything but the number is an icon, for the reason the balloon
        // pictogram gives: this facility does not explain itself in sentences, and a caption in among
        // the objects reads as a different kind of thing on the wall.
        private static void BuildWeighPictogram(Transform room, WeighScale scale)
        {
            GameObject root = new GameObject("WeighPictogram");
            root.transform.SetParent(room, false);

            const float standoff = 0.05f;
            float halfWidth = RoomWidth / 2f;
            float halfDepth = RoomDepth / 2f;

            // --- the equation, on both side walls ---------------------------------------------------
            // WHAT CAN BE WEIGHED, AND THAT THE ANSWER IS A SUM. Restored 2026-08-19 after a pass that
            // cut it back to the number alone: without it the room says what total it wants and
            // nothing about what to bring, and the objects it names are scattered across four rooms
            // the player has already walked through.
            //
            // FIVE OBJECTS, not the three that make the cheapest solution. That is the difference
            // between a sign and an answer: this one lists what the scale ACCEPTS - cube, full bucket,
            // axe, beach ball, rubber duck - and the question mark says the total is the unknown. Which
            // of them add up to the number over the door is left entirely to the player.
            //
            // BOTH SIDE WALLS, because the player is turning on the spot at a scale in the middle of
            // the room: whichever way they face, one of the two is in front of them.
            const float sideWidth = GridCellWidth * 5f;
            const float sideAuthoredHeight = 618f;
            // Above head height, and above the scale - which is 5.7m across and sits between the
            // player and both of these.
            const float sideY = 3.4f;

            System.Action<Transform> equation = f => FillWeighEquation(f);

            CanvasGroup west = MakeWallFace(root.transform, "West",
                new Vector3(-halfWidth + standoff, sideY, 0f), Quaternion.Euler(0f, -90f, 0f),
                equation, sideWidth, withPlate: false, authoredHeight: sideAuthoredHeight);
            CanvasGroup east = MakeWallFace(root.transform, "East",
                new Vector3(halfWidth - standoff, sideY, 0f), Quaternion.Euler(0f, 90f, 0f),
                equation, sideWidth, withPlate: false, authoredHeight: sideAuthoredHeight);

            // OVER THE DOOR ONTO ROOM2-8, in the SOUTH wall - which is the door this scale opens, so
            // the number is written on the thing it is the price of. Facing back into the room, which
            // is where somebody who has just weighed something is standing: a canvas's forward must
            // match the direction the VIEWER is looking, not point at them (see MakeWallFace).
            //
            // THE EQUATION IS GONE, 2026-08-19 by request. It drew `full bucket + cube + axe = ?` on
            // the side walls, which named the three objects that work - the number alone leaves that
            // to the player, and it is the only part of this that experiment cannot supply.
            //
            // NO PLATE. `withPlate` draws the near-black backing every other sign in this building
            // sits on, and it is what makes those read as DISPLAYS. This one is meant to read as
            // painted on the wall - a number stencilled over a doorway - so the plate is off and the
            // wall shows through behind the figures.
            float overDoorY = DoorHeight + 0.95f;
            CanvasGroup target = MakeWallFace(root.transform, "Target",
                new Vector3(0f, overDoorY, -halfDepth + standoff), Quaternion.Euler(0f, 180f, 0f),
                f => FillWeighTarget(f, scale != null ? scale.targetKilograms : WeighTarget),
                worldWidth: 3.6f, withPlate: false, authoredHeight: 440f);

            // FULLY VISIBLE, AND PERMANENT. `MakeWallFace` authors every sign at alpha 0 because the
            // ones it was built for are faded in and retired by `PanelMessage` - room2's pictogram
            // goes when the player pops a balloon. These never go: what they say is true for as long
            // as the room is unsolved, and a player who has forgotten it has to be able to look up
            // again.
            foreach (CanvasGroup group in new[] { west, east, target })
                if (group != null) group.alpha = 1f;
        }

        // `CUBE + BUCKET + AXE + BEACH BALL + DUCK = ?`, in objects.
        //
        // EVERYTHING THE SCALE ACCEPTS, not a solution. The objects, a plus between each, and a
        // question mark at the end saying the total is the unknown - so the sign names the
        // INGREDIENTS and the number over the door names the answer, and what adds up to it is the
        // player's to work out. That is the whole puzzle: they are told no weights.
        //
        // **~~The bucket~~ GONE 2026-08-29**, and with it the one thing on this sign that could not be
        // drawn honestly: an empty pail and a full one are the same carryable at two very different
        // weights, so the icon had to pick one and mean it.
        private static void FillWeighEquation(Transform face)
        {
            // FOUR NOW, the bucket having left the equation - see the weight table for why. The
            // layout below is derived from the count rather than written down, so a row that names
            // one fewer object simply comes out wider per icon.
            Sprite[] objects = { CubeIcon(), AxeIcon(), BeachBallIcon(), DuckIcon() };
            string[] names = { "Cube", "Axe", "BeachBall", "Duck" };

            // N objects, N-1 pluses, an equals and a question mark, across a sign authored 1600 wide.
            // The icon size is DERIVED from that rather than written down, so the row fills the sign
            // however many objects it ends up naming - which is what made dropping one a one-line
            // change here.
            const float authoredWidth = 1600f;
            const float opRatio = 90f / 190f;                     // the balloon pictogram's proportion
            int ops = objects.Length;                             // four pluses plus the equals
            float icon = authoredWidth / (objects.Length + 1f + ops * opRatio);
            float op = icon * opRatio;

            float x = -authoredWidth / 2f;

            Color ink = new Color(0.20f, 0.20f, 0.23f, 0.72f);
            // The operators are RED while the things they join stay charcoal, exactly as room2's
            // pictogram does it: the eye gets the shape of the sum before it has identified any of the
            // objects in it.
            Color punctuation = new Color(0.82f, 0.12f, 0.12f, 0.85f);

            for (int i = 0; i < objects.Length; i++)
            {
                MakeWallIcon(face, names[i], objects[i], new Vector2(x + icon / 2f, 0f), icon, ink);
                x += icon;

                Sprite between = i < objects.Length - 1 ? PlusIcon() : EqualsIcon();
                string label = i < objects.Length - 1 ? $"Plus{i}" : "Equals";
                MakeWallIcon(face, label, between, new Vector2(x + op / 2f, 0f), op, punctuation);
                x += op;
            }

            // The unknown, in the same red as the operators - it is punctuation about the sum rather
            // than another object in it.
            MakeWallIcon(face, "Question", QuestionIcon(), new Vector2(x + icon / 2f, 0f), icon, punctuation);
        }

        // The target, over the door it opens. Written to ONE DECIMAL like the scale's own readout,
        // so the two are visibly the same kind of value and a player can compare them without
        // wondering whether "23" and "23.0" mean the same thing.
        //
        // DARK ON A WHITE WALL, because there is no plate behind it any more: the pale grey it used to
        // be was legible against near-black and would be invisible against the panelling. Same
        // charcoal every other mark in this facility is printed in.
        private static void FillWeighTarget(Transform face, float kilograms)
        {
            MakeWallLine(face, "Target", $"{kilograms:0.0} KG", 260,
                         new Color(0.17f, 0.17f, 0.20f, 0.88f), Vector2.zero,
                         new Vector2(1400f, 320f));
        }

        // How wide the scale is. A bathroom scale is 0.3m across and would be a coaster in this
        // building; this is a PLATFORM scale, big enough to stand on with an axe beside your feet,
        // which is what the room asks of it.
        //
        // TRIPLED, 2026-08-19 by request: 5.7m across in a room 8.75m wide, so it is most of the
        // floor and the room reads as being BUILT around the weighing rather than as a room with a
        // scale in it. Two consequences worth knowing, both accepted:
        //   - the PAN is derived from this (0.95 of it), so the volume that counts as "on the scale"
        //     is now 5.4m across. Anything put down near the middle of the room is being weighed,
        //     which is generous - but the room contains nothing else, so there is nothing to put down
        //     near the middle by accident;
        //   - the readout is sized off the model's own display panel, so it grows with it and the
        //     digits stay legible from the doorway.
        private const float WeighScaleWidth = 5.7f;

        // THE SCALE, and its readout.
        //
        // THE MODEL IS A BATHROOM SCALE and it is scaled up by roughly six. That is not a fudge: every
        // dimension in this building is oversized (a 220mm ball-pit ball, a 10.5m room, a 13m tree),
        // and a scale you can put a full bucket AND an axe AND a cube on has to be a pallet, not a
        // tile.
        //
        // THE READOUT IS OURS, NOT THE MODEL'S. The model has a green display panel painted on it,
        // which cannot show a number; the digits are a world-space canvas laid flat just above that
        // panel, found by its material name and fallen back to the model's own top face. UI text is
        // unlit, which is what makes it read as a lit LCD rather than as paint.
        private static WeighScale BuildWeighScale(Transform room, Material propMat)
        {
            GameObject root = new GameObject("WeighScale2_7");
            root.transform.SetParent(room, false);

            float top = 0.18f;
            Bounds raw = new Bounds();
            Transform display = null;

            string path = PlayDir + "/weigh_scale.glb";
            GameObject source = AssetDatabase.LoadAssetAtPath<GameObject>(path);
            if (source != null)
            {
                ShrinkModelTextures(path, 1024);

                GameObject model = (GameObject)PrefabUtility.InstantiatePrefab(source, root.transform);
                model.name = "Scale";
                model.transform.localPosition = Vector3.zero;

                raw = ModelBounds(root.transform, model);
                float across = Mathf.Max(0.001f, Mathf.Max(raw.size.x, raw.size.z));
                float scale = WeighScaleWidth / across;
                model.transform.localScale = Vector3.one * scale;

                raw = ModelBounds(root.transform, model);
                model.transform.localPosition = new Vector3(-raw.center.x, -raw.min.y, -raw.center.z);
                raw = ModelBounds(root.transform, model);
                top = raw.max.y;

                // SOLID, so things put on it stay on it. A mesh collider on the parts as they are -
                // convex would swallow the dish the platform makes and objects would slide off a dome.
                foreach (MeshFilter mf in model.GetComponentsInChildren<MeshFilter>(true))
                {
                    if (mf.sharedMesh == null) continue;
                    MeshCollider mc = mf.gameObject.AddComponent<MeshCollider>();
                    mc.sharedMesh = mf.sharedMesh;
                }

                // The display is the part wearing the model's own `Green` material. Found by name
                // because that is what the export calls it, and harmless if it ever stops being true:
                // the readout falls back to the middle of the platform's top face.
                foreach (Renderer r in model.GetComponentsInChildren<Renderer>())
                {
                    if (r.sharedMaterial == null || !r.sharedMaterial.name.Contains("Green")) continue;
                    display = r.transform;
                    break;
                }
            }
            else
            {
                Debug.LogWarning($"[SceneBuilder] {path} is missing - room2-7 gets a scale with no scale.");
                Prim(PrimitiveType.Cube, "Platform", root.transform, new Vector3(0f, 0.09f, 0f),
                     new Vector3(WeighScaleWidth, 0.18f, WeighScaleWidth * 0.9f), propMat);
            }

            // --- the digits ---------------------------------------------------------------------
            // ON THE MODEL'S OWN DISPLAY PANEL, and nothing is added to the scene to do it. Two
            // earlier versions put something over the panel instead - a world-space `Canvas`, then a
            // grid of quads - and both are the same mistake: a thing stuck on the prop rather than the
            // prop showing something.
            //
            // THE MODEL'S OWN NUMBER HAS TO GO FIRST, and it is not a texture - it is GEOMETRY.
            // `weigh_scale.glb` ships no textures at all and its green display is one connected
            // surface with a fixed number embossed into it, so drawing the live reading onto that
            // surface put a picture of digits across a thing that already was digits. The submesh is
            // replaced with a clean quad over the same footprint - see FlatPanelMesh.
            Bounds panel = display != null
                ? ModelBounds(root.transform, display.gameObject)
                : new Bounds(new Vector3(0f, top, -WeighScaleWidth * 0.28f),
                             new Vector3(WeighScaleWidth * 0.42f, 0.01f, WeighScaleWidth * 0.20f));

            PanelDigits digits = null;
            if (display != null)
            {
                MeshFilter panelFilter = display.GetComponent<MeshFilter>();
                if (panelFilter != null && panelFilter.sharedMesh != null)
                    panelFilter.sharedMesh = FlatPanelMesh(panelFilter.sharedMesh, "ScalePanel");

                // UNLIT, because an LCD is not lit by the room - and the texture carries its own dark
                // background and bright bars, so there is nothing for the room's light to add.
                Renderer panelRenderer = display.GetComponent<Renderer>();
                if (panelRenderer != null)
                    panelRenderer.sharedMaterial = MakeUnlitMaterial("ScalePanel", Color.white);

                digits = display.gameObject.AddComponent<PanelDigits>();
                digits.panel = panelRenderer;
                digits.digitCount = 4;
                digits.decimalsAfter = 1;
            }
            else
            {
                Debug.LogWarning("[SceneBuilder] the scale has no display panel - its readout is gone.");
            }

            WeighScale weigh = root.AddComponent<WeighScale>();
            weigh.display = digits;
            weigh.targetKilograms = WeighTarget;
            weigh.playerKilograms = WeightPlayer;
            // THE PAN, and it is generous on purpose. It has to hold a person standing up, so it is
            // taller than a person; anything within the platform's footprint and under two metres of
            // it counts as being on the scale.
            weigh.panCentre = new Vector3(0f, top + 1.0f, 0f);
            weigh.panSize = new Vector3(WeighScaleWidth * 0.95f, 2.0f, WeighScaleWidth * 0.9f);
            weigh.audioSource = MakeSource(root.transform, "ScaleAudio", spatialBlend: 1f, volume: 0.9f);
            weigh.acceptClip = MakeValveStopClip("sfx_valve_stop");

            Debug.Log($"[SceneBuilder] Room2_7 scale: {WeighScaleWidth:0.00}m platform, "
                    + $"target {WeighTarget:0.0}kg, top at {top:0.00}m, display panel "
                    + $"{panel.size.x:0.00}x{panel.size.z:0.00}"
                    + (digits != null ? " (panel replaced)" : " - MISSING"));
            return weigh;
        }

        // THE POOL AT THE BOTTOM OF THE SLIDE, and the plastic balls floating on it.
        //
        // WHAT IT IS FOR. The chute comes through this room's CEILING, so whoever rides it arrives
        // falling - and a fall that ends on a hard floor is a landing, while one that ends in water is
        // a plunge. That is the whole ask: the ride has somewhere to go that answers it.
        //
        // NOT SOLID, NOT FATAL, NOT RECORDED. There is no collider on any of it (see WaterPool for why
        // one would break the slide's own measured path), no `KillVolume` under it, no signal bit and
        // nothing for `Cycle.ResetRooms` to put back. The player wades out; a past self wades out the
        // same way, because walking is already recorded and this changes nothing about walking.
        //
        // THREE OBJECTS, THREE JOBS: the surface is a mesh with the water shader on it, `WaterPool`
        // owns where the waterline is and the splash when somebody is in it, and `FloatingBalls` owns
        // the drift. None of the three knows what the other two are doing.
        private static WaterPool BuildWaterPool(Transform room)
        {
            GameObject root = new GameObject("Room2_SlideRoom_Pool");
            root.transform.SetParent(room, false);

            WaterPool pool = root.AddComponent<WaterPool>();
            pool.surfaceLocalY = PoolDepth;
            pool.halfExtents = new Vector2(RoomWidth / 2f, RoomDepth / 2f);
            // Everything from the floor to the surface is "in the water". Half a metre of slack under
            // the floor, so a frame in which the controller is a hair through it still counts.
            pool.floorDrop = PoolDepth + 0.5f;

            // --- the surface ----------------------------------------------------------------------
            // PUSHED INTO THE WALLS by a few centimetres. A sheet cut exactly to the room leaves a
            // hairline of floor showing at every wall as soon as the vertex wobble pulls an edge
            // vertex inward, and a gap at the waterline is the one place the eye is guaranteed to look.
            const float wallOverlap = 0.06f;

            GameObject surface = new GameObject("Surface");
            surface.transform.SetParent(root.transform, false);
            surface.transform.localPosition = new Vector3(0f, PoolDepth, 0f);
            // THE SIZE IS IN THE ASSET NAME. `SaveGeneratedMesh` serves from cache, so a shape
            // parameter changed without the name changing gets the OLD mesh back and the change
            // silently does nothing - the same trap `WaterSpill_..._d45` names itself against.
            surface.AddComponent<MeshFilter>().sharedMesh = SaveGeneratedMesh(
                "WaterSheet_SlideRoom_c25",
                () => WaterMeshes.Sheet(RoomWidth + wallOverlap * 2f,
                                        RoomDepth + wallOverlap * 2f, PoolSurfaceCell));

            MeshRenderer surfaceRend = surface.AddComponent<MeshRenderer>();
            surfaceRend.sharedMaterial = MakePoolWaterMaterial();
            surfaceRend.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
            surfaceRend.receiveShadows = false;

            // --- the splash -----------------------------------------------------------------------
            // The tap's spray with the tap taken off it: no rate, no bursts, nothing playing on its
            // own. `WaterPool` moves it to the waterline and calls `Emit`, so one system serves the
            // arrival and every wading step after it.
            GameObject splashGO = new GameObject("Splash");
            splashGO.transform.SetParent(root.transform, false);
            splashGO.transform.localPosition = new Vector3(0f, PoolDepth, 0f);

            ParticleSystem splash = splashGO.AddComponent<ParticleSystem>();
            ParticleSystem.MainModule splashMain = splash.main;
            // PLAYING FOREVER AND EMITTING NOTHING, which is not the contradiction it reads as: a
            // STOPPED system does not simulate, so particles pushed into one by `Emit` are created and
            // then never move. Looping with the emission module switched off is how a system is kept
            // running for a caller that supplies every particle itself.
            splashMain.loop = true;
            splashMain.playOnAwake = true;
            splashMain.startLifetime = new ParticleSystem.MinMaxCurve(0.35f, 1.05f);
            splashMain.startSpeed = new ParticleSystem.MinMaxCurve(1.6f, 4.6f);
            splashMain.startSize = new ParticleSystem.MinMaxCurve(0.02f, 0.09f);
            splashMain.gravityModifier = 1f;
            splashMain.startColor = new ParticleSystem.MinMaxGradient(new Color(0.90f, 0.95f, 1f, 0.92f));
            // World space, or the droplets ride the emitter as it is moved to the next splash.
            splashMain.simulationSpace = ParticleSystemSimulationSpace.World;
            splashMain.maxParticles = 400;

            ParticleSystem.EmissionModule splashEmit = splash.emission;
            // NOTHING ON ITS OWN. Every particle this ever makes comes from an `Emit` call.
            splashEmit.enabled = false;

            // A flat skirt: water thrown up by something dropping into it goes out and over, not up in
            // a column - a narrow cone reads as a fountain.
            ParticleSystem.ShapeModule splashShape = splash.shape;
            splashShape.shapeType = ParticleSystemShapeType.Cone;
            splashShape.angle = 72f;
            splashShape.radius = 0.22f;
            splashShape.rotation = new Vector3(-90f, 0f, 0f);

            ParticleSystem.SizeOverLifetimeModule splashSize = splash.sizeOverLifetime;
            splashSize.enabled = true;
            splashSize.size = new ParticleSystem.MinMaxCurve(1f, AnimationCurve.EaseInOut(0f, 1f, 1f, 0.1f));

            ParticleSystemRenderer splashRend = splashGO.GetComponent<ParticleSystemRenderer>();
            splashRend.sharedMaterial = AssetDatabase.LoadAssetAtPath<Material>("Assets/Materials/WaterStream.mat");
            splashRend.renderMode = ParticleSystemRenderMode.Billboard;
            splashRend.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
            splashRend.receiveShadows = false;

            pool.splash = splash;
            pool.audioSource = MakeSource(root.transform, "SplashAudio", spatialBlend: 1f, volume: 0.9f);
            // ARRIVING IS A BODY GOING THROUGH THE SURFACE, not water hitting a floor. The three
            // `sfx_water_splash_*` clips were here and played as an effect laid over the room - they
            // are the tap's, and a tap's water lands on tiles from above. This is the wade sound at
            // twice the length, slower to die and with more of it low: the same event, person-sized.
            pool.splashClips = new[]
            {
                MakeWadeClip("sfx_water_plunge", 20260822, seconds: 1.15f, decay: 2.9f,
                             fizzLevel: 0.5f, lowWeight: 3.4f),
            };

            // --- the rings ----------------------------------------------------------------------
            pool.ripples = BuildWaterRipples(root.transform);

            pool.surface = surface.transform;

            // --- what floats on it -------------------------------------------------------------------
            // Three kinds, smallest first, and the count of the small one is what leaves room for the
            // other two to be seen at all (2026-08-19, by request: fewer balls, and beach balls in
            // among them).
            FloatingBalls balls = BuildFloatingBalls(root.transform);

            // THE DUCKS. Rocking and turning, which a plastic sphere cannot show and a duck must - see
            // FloatingBalls' turn fields. Slow: this is still water in a sealed room.
            FloatingBalls ducks = BuildFloatingProps(root.transform, "Ducks", "rubber_duck.glb",
                PoolDuckLength, sinkFraction: 0.34f,
                spots: new[] { new Vector2(-2.35f, 2.60f), new Vector2(1.70f, -0.40f),
                               new Vector2(-0.90f, -3.40f) },
                yaws: new[] { 34f, 205f, 128f },
                idPrefix: DuckItemId, displayName: "RUBBER DUCK", kilograms: WeightDuck,
                icon: DuckIcon());
            if (ducks != null)
            {
                ducks.bobHeight = 0.030f;
                ducks.bobPeriod = 4.2f;
                // An ACCELERATION now, not a radius: against the mooring it settles into a wander of
                // about a third of a metre, and the turning that used to be written here is the
                // rigidbody's own - a duck shouldered by a beach ball turns because it was shouldered.
                // LESS THAN IT WAS. A duck that wanders is charming and is also a thing the player
                // has to chase in water that halves their speed; the drift is now small enough to
                // read as the water moving under it rather than as the duck going somewhere.
                ducks.drift = 0.045f;
                ducks.driftPeriod = 21f;
            }

            // THE BEACH BALLS. Bigger and lighter than anything else on the water, so they sit HIGH -
            // a beach ball is a bag of air and barely breaks the surface - and they wander furthest,
            // because the bigger the sail the more the room's nothing-at-all moves it.
            FloatingBalls beach = BuildFloatingProps(root.transform, "BeachBalls", "beach_ball.glb",
                PoolBeachBallSize, sinkFraction: 0.16f,
                spots: new[] { new Vector2(2.60f, 3.30f), new Vector2(-2.90f, -1.60f) },
                yaws: new[] { 62f, 241f },
                idPrefix: BeachBallItemId, displayName: "BEACH BALL", kilograms: WeightBeachBall,
                icon: BeachBallIcon());
            if (beach != null)
            {
                beach.bobHeight = 0.045f;
                beach.bobPeriod = 5.1f;
                // Furthest, because the bigger the sail the more the room's nothing-at-all moves it.
                // An ACCELERATION now, not a radius - against the mooring it settles into a wander of
                // about half a metre, and the rolling that used to be written here is the rigidbody's
                // own: a beach ball turns because something turned it.
                beach.drift = 0.07f;
                beach.driftPeriod = 26f;
            }

            // EVERY GROUP, NAMED HERE. The pool moves them all when it drains, and gathering them by
            // type at runtime is the thing CLAUDE.md §2 says a cycle must not do - a `FloatingBalls`
            // in some later room would be dragged down with this room's water.
            pool.floats = new[] { balls, ducks, beach };
            return pool;
        }

        // How long a duck is, nose to tail. A real bath duck is about 80mm; this building is oversized
        // throughout (a 220mm ball-pit ball, a 10.5m room) and at bath size these would be specks on a
        // ninety-square-metre pool. 0.42m puts one at about two plastic balls long, which is what reads.
        private const float PoolDuckLength = 0.42f;
        // And a beach ball, which is the biggest thing on the water: three plastic balls across.
        private const float PoolBeachBallSize = 0.66f;

        // ONE KIND OF THING FLOATING ON THE POOL: an imported model, placed at named spots, riding the
        // same `FloatingBalls` component the plastic balls do. The ducks and the beach balls differ by
        // their file, their size, how deep they sit and how they move - so those are the arguments, and
        // the motion is set by the caller on the component this returns.
        //
        // A WRAPPER PER OBJECT, with the model inside it untouched. `FloatingBalls` writes the
        // wrapper's local position and rotation; the model keeps the pose its import gave it, which is
        // the rule every glTF in this project is placed by (see BuildSlide for what overwriting one
        // costs).
        private static FloatingBalls BuildFloatingProps(Transform poolRoot, string name, string file,
                                                        float size, float sinkFraction,
                                                        Vector2[] spots, float[] yaws,
                                                        string idPrefix, string displayName,
                                                        float kilograms, Sprite icon)
        {
            string path = PlayDir + "/" + file;
            GameObject source = AssetDatabase.LoadAssetAtPath<GameObject>(path);
            if (source == null)
            {
                Debug.LogWarning($"[SceneBuilder] {path} is missing - the pool keeps everything else "
                               + $"and loses its {name}.");
                return null;
            }

            ShrinkModelTextures(path, 1024);

            GameObject root = new GameObject(name);
            root.transform.SetParent(poolRoot, false);

            // THE SPOTS ARE WRITTEN DOWN rather than scattered randomly. Two or three objects are too
            // few for a random scatter to look scattered - a pair lands beside each other often enough
            // to matter, and the pool is nine metres across.
            Random.State entry = Random.state;
            Random.InitState(20260819 + name.GetHashCode());

            int floatLayer = EnsureLayer(BalloonLayerName);
            int count = Mathf.Min(spots.Length, yaws.Length);
            var bodies = new Rigidbody[count];
            var homes = new Vector3[count];
            var carriedItems = new CarryableItem[count];

            for (int i = 0; i < count; i++)
            {
                GameObject holder = new GameObject($"{name}_{i}");
                holder.transform.SetParent(root.transform, false);
                holder.layer = floatLayer;

                GameObject model = (GameObject)PrefabUtility.InstantiatePrefab(source, holder.transform);
                model.name = "Model";
                model.transform.localPosition = Vector3.zero;

                Bounds raw = ModelBounds(holder.transform, model);
                float footprint = Mathf.Max(0.001f, Mathf.Max(raw.size.x, raw.size.z));
                float scale = size / footprint * Random.Range(0.92f, 1.08f);
                model.transform.localScale = Vector3.one * scale;

                // FLOATING, NOT SITTING ON THE SURFACE. Whatever it is displaces some of itself, so
                // the waterline crosses the body - anything resting with its lowest point exactly on
                // the surface reads as an object on a glass table. How much is the caller's, because
                // a duck sits deep and a bag of air does not.
                float sink = raw.size.y * scale * sinkFraction;
                model.transform.localPosition = new Vector3(-raw.center.x * scale,
                                                            -raw.min.y * scale - sink,
                                                            -raw.center.z * scale);

                homes[i] = new Vector3(spots[i].x, PoolDepth, spots[i].y);
                holder.transform.localPosition = homes[i];
                holder.transform.localRotation = Quaternion.Euler(0f, yaws[i], 0f);

                // The collider is a sphere the size of the FOOTPRINT, not of the model. A duck is
                // mostly a body with a head on it, and a collider drawn round the head as well is a
                // duck that fends other things off with a bubble it does not appear to have.
                float radius = footprint * scale * 0.45f;
                (Rigidbody body, SphereCollider solid) = MakeFloatBody(holder, radius, PoolPropMass,
                                                                        upright: true);
                bodies[i] = body;

                // AND IT CAN BE PICKED UP AND CARRIED OUT. The ducks and the beach balls are the only
                // things in this game that are both physics props and carryables, and the handover is
                // in `FloatingBalls`: while a hand has it, or once it is further from home than the
                // pool is wide, its body goes kinematic and the ordinary carryable machinery owns it -
                // including `FallingItem`, so its drop is SCRIPTED and lands in the same place every
                // iteration, which is what room2-7's scale needs of it (CLAUDE.md §4).
                //
                // The reach trigger goes on the HOLDER, which is what `CarryableItem` has to live on -
                // it is the transform that gets parented into a hand, and the physics sphere is a
                // child so the two colliders cannot be confused for each other (see MakeFloatBody).
                //
                // MUCH BIGGER THAN A SHELF ITEM'S, and it has to be. Everything else in this game is
                // picked up off a floor by a player walking at 2.5m/s; these are picked up out of
                // waist-deep water, which halves the walk, while the object itself DRIFTS. At the
                // 0.55m clearance the rest of the game uses, closing the last metre on a duck that is
                // wandering took several attempts - play reported it twice as "잘 안 잡혀". 1.25m is
                // about an arm and a step, and nothing else is close enough to lose the press to.
                SphereCollider reach = holder.AddComponent<SphereCollider>();
                reach.isTrigger = true;
                reach.radius = radius + 1.25f;

                // WHERE THE PROMPT HANGS, AND WHAT THE AIM IS MEASURED AGAINST - above the waterline
                // rather than at the object's centre, which sits ON it. `CarryableItem.HintAnchor` is
                // its own transform by default, and for a duck that point is half under the surface:
                // the disc was drawn inside the water and the aim test was asking about a point the
                // player cannot really see. Everything else in the game rests on a floor, where the
                // two are the same place.
                GameObject aim = new GameObject("Aim");
                aim.transform.SetParent(holder.transform, false);
                aim.transform.localPosition = new Vector3(0f, radius + 0.10f, 0f);

                CarryableItem item = holder.AddComponent<CarryableItem>();
                item.hintAnchor = aim.transform;
                // The physics sphere is also what makes it SOLID, so it is the blocker: switched off
                // while it is in a hand, exactly like a cube's.
                item.blocker = solid;
                // **ONE ID PER OBJECT, NOT ONE PER KIND** (2026-08-28, by request, after play found
                // the beach balls swapping between hands). A shared id makes a SUPPLY, and
                // `ItemRegistry` then resolves it to "any free one" - so a ghost replaying "took a
                // BeachBall" takes whichever of the two is going spare rather than the one it
                // actually took. With two of them adrift on moving water that reads as the pair
                // trading places every iteration.
                //
                // A supply is the right shape for the three pins, where the id names a stock of
                // interchangeable tools and CLAUDE.md §4 says so. It is the wrong shape here: these
                // are two distinct objects a player picks out by eye, and §1.4's whole argument -
                // identity, never position - wants the id to name the OBJECT. The chess pieces
                // already do exactly this (`item.itemId = piece.gameObject.name`).
                //
                // `GhostReplayer.TryTake`'s "any free one" fallback simply stops applying, which is
                // the honest outcome: a past self whose own ball is unavailable does not take a
                // different one.
                item.itemId = $"{idPrefix}_{i}";
                item.displayName = displayName;
                item.icon = icon;
                item.floorY = radius;
                item.handLocalPosition = HandPoseFor(size);
                item.handLocalScale = Vector3.one;
                item.audioSource = MakeSource(holder.transform, "PickupAudio", 1f, 0.8f);
                item.pickupClip = LoadClip(SfxDir, "sfx_item_pickup");
                // THE ONLY CARRYABLES IN THE GAME THAT ARE NOT WHERE THEY WERE PUT - they drift, the
                // plastic balls shove them, and the drain's vortex drags every one of them to the
                // middle of the room. See PoolPropTakeReach and CarryableItem.ghostTakeReach.
                item.ghostTakeReach = PoolPropTakeReach;
                MakeWeighable(item, kilograms);
                carriedItems[i] = item;
            }

            Random.state = entry;

            FloatingBalls floating = root.AddComponent<FloatingBalls>();
            floating.bodies = bodies;
            floating.homes = homes;
            floating.carried = carriedItems;

            Debug.Log($"[SceneBuilder] Room2_6 pool: {count} x {name} at {size:0.00}m, {kilograms:0.0}kg each.");
            return floating;
        }

        // A STILL BODY OF WATER, which is not the same material as a falling one.
        //
        // `WaterStream.mat` is tuned for a column half a metre across dropping two metres: its noise is
        // fine and fast because a stream is moving, and at that scale on a ten-metre pool the surface
        // crawls with a rash of tiny ripples that reads as static. This is the same shader with the
        // noise an order of magnitude broader and ten times slower, more body to it (a metre of water
        // absorbs where a 45mm spill does not), and a softer meeting where it reaches the walls and the
        // player's legs - a hard line around a pair of knees is the tell that the water is a decal.
        private static Material MakePoolWaterMaterial()
        {
            const string path = MaterialsDir + "/PoolWater.mat";
            Shader shader = Shader.Find("IterationRoom/WaterSurface");
            if (shader == null)
            {
                Debug.LogWarning("[SceneBuilder] IterationRoom/WaterSurface is missing - the pool "
                               + "falls back to the stream material.");
                return AssetDatabase.LoadAssetAtPath<Material>("Assets/Materials/WaterStream.mat");
            }

            Material mat = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (mat == null)
            {
                mat = new Material(shader);
                AssetDatabase.CreateAsset(mat, path);
            }
            mat.shader = shader;

            mat.SetColor("_BaseColor", new Color(0.78f, 0.88f, 0.93f, 0.16f));
            mat.SetFloat("_Refraction", 0.030f);
            mat.SetFloat("_Reflection", 0.62f);
            mat.SetFloat("_Smoothness", 0.96f);
            mat.SetFloat("_SpecPower", 220f);
            mat.SetFloat("_SpecGain", 2.2f);
            mat.SetFloat("_FresnelPower", 3.2f);
            // MORE BODY THAN THE STREAM HAS, and it is depth that buys it: looking down into 1.2m of
            // water you are looking through 1.2m of water, and a pool as clear as a tap's output is a
            // sheet of glass over a white floor.
            mat.SetFloat("_EdgeAlpha", 0.80f);
            mat.SetFloat("_CoreAlpha", 0.22f);
            mat.SetColor("_DeepColor", new Color(0.30f, 0.50f, 0.60f, 1f));
            mat.SetFloat("_DeepStrength", 0.62f);
            // BROAD AND SLOW. This is the whole difference between a pool and a stream.
            mat.SetFloat("_NoiseScale", 3.6f);
            mat.SetFloat("_NoiseSpeed", 0.22f);
            mat.SetFloat("_NoiseAmount", 0.26f);
            mat.SetFloat("_WobbleAmp", 0.014f);
            mat.SetFloat("_WobbleFreq", 1.6f);
            mat.SetFloat("_WobbleSpeed", 0.45f);
            mat.SetFloat("_DepthFade", 0.25f);

            EditorUtility.SetDirty(mat);
            return mat;
        }

        // THE BALLS ON THE POOL. The same six hues as room2-7's pit and the opposite construction -
        // three hundred separate objects rather than six merged meshes, because these have to move
        // independently. See FloatingBalls.
        //
        // THEY LOOKED CHEAP ON THE FIRST PASS, and "cheap" was three specific things (2026-08-19):
        //
        //  - **Too bright.** The pit's colours are display colours at full value, and full value under
        //    six ceiling fixtures in a white room is a flat bright patch with no shading left in it.
        //    A real ball has its colour in the MIDTONES and gets its brightness from the highlight.
        //  - **Too uniform.** Six colours across three hundred balls, every one the same shade of its
        //    colour and every one the same size. Nothing manufactured is that consistent, and the eye
        //    reads the repetition long before it reads the objects.
        //  - **Too faceted.** 96 triangles is right for a ball pit seen as a mass from two metres up;
        //    these float at knee height under the player's nose, and at that range a 96-triangle
        //    sphere has a visible polygon silhouette.
        // HOW MANY RINGS CAN BE IN FLIGHT AT ONCE. A ring lives 1.9s and the player makes one every
        // 0.55s of walking, so four covers a walk and the rest is headroom for the entry plus a player
        // turning circles. The cost of the cap is that a ninth ring recycles the oldest, which is the
        // one already almost invisible.
        private const int PoolRippleCount = 8;

        // THE RINGS THE PLAYER LEAVES IN THE WATER. Quads lying on the surface with a ripple painted
        // on them, expanded and faded by `WaterRipples`.
        //
        // DRAWN RATHER THAN SHADED. The water shader already has moving noise in it, but that noise is
        // the same everywhere and answers to nothing - a ripple has to start where the player is. The
        // alternative is feeding the surface shader a list of disturbance centres and ages; this is a
        // texture and eight quads, and it composes with a shader nobody has to touch.
        //
        // A MILLIMETRE ABOVE THE WATER, because two coplanar transparent surfaces is the same flicker
        // the mouth's tunnel just had.
        private static WaterRipples BuildWaterRipples(Transform poolRoot)
        {
            GameObject root = new GameObject("Ripples");
            root.transform.SetParent(poolRoot, false);
            root.transform.localPosition = new Vector3(0f, PoolDepth + 0.012f, 0f);

            Material mat = MakeRippleMaterial();
            Mesh quad = PrimitiveMesh(PrimitiveType.Quad);

            var rings = new Transform[PoolRippleCount];
            var renderers = new Renderer[PoolRippleCount];

            for (int i = 0; i < PoolRippleCount; i++)
            {
                GameObject go = new GameObject($"Ring_{i}");
                go.transform.SetParent(root.transform, false);
                // FLAT, and authored that way once. A quad faces -Z; ninety degrees about X lays it
                // face-up. `WaterRipples` never writes a rotation, precisely so this survives.
                go.transform.localRotation = Quaternion.Euler(90f, 0f, 0f);
                go.transform.localScale = Vector3.one * 0.5f;

                go.AddComponent<MeshFilter>().sharedMesh = quad;
                MeshRenderer rend = go.AddComponent<MeshRenderer>();
                rend.sharedMaterial = mat;
                rend.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
                rend.receiveShadows = false;
                rend.enabled = false;

                rings[i] = go.transform;
                renderers[i] = rend;
            }

            WaterRipples ripples = root.AddComponent<WaterRipples>();
            ripples.rings = rings;
            ripples.renderers = renderers;
            return ripples;
        }

        // UNLIT AND TRANSPARENT. A ripple is not a surface being lit - it is the water's own highlight
        // rearranged - so a lit material would put the room's six fixtures on it and make each ring a
        // shiny disc. Unlit also means the per-ring alpha can ride in a `MaterialPropertyBlock` without
        // eight materials, which is what `WaterRipples` fades.
        private static Material MakeRippleMaterial()
        {
            const string path = MaterialsDir + "/WaterRipple.mat";
            Shader unlit = Shader.Find("Universal Render Pipeline/Unlit");
            if (unlit == null) unlit = OpaqueShader();

            Material mat = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (mat == null)
            {
                mat = new Material(unlit);
                AssetDatabase.CreateAsset(mat, path);
            }
            mat.shader = unlit;

            mat.SetTexture("_BaseMap", MakeRippleTexture("WaterRipple", 128));
            mat.SetColor("_BaseColor", new Color(1f, 1f, 1f, 0f));

            // The blend modes AND the keyword - alpha alone does nothing in URP (CLAUDE.md §3).
            mat.SetFloat("_Surface", 1f);
            mat.SetFloat("_Blend", 0f);
            mat.SetFloat("_SrcBlend", (float)UnityEngine.Rendering.BlendMode.SrcAlpha);
            mat.SetFloat("_DstBlend", (float)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);
            mat.SetFloat("_ZWrite", 0f);
            mat.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");
            mat.renderQueue = (int)UnityEngine.Rendering.RenderQueue.Transparent + 10;

            EditorUtility.SetDirty(mat);
            return mat;
        }

        // TWO RINGS, NOT ONE. A single ring reads as a stamp; a bright leading edge with a fainter one
        // chasing it reads as a wave that has been travelling. Both are soft-edged gaussians - a hard
        // ring is a drawn circle, and the eye finds the line before it finds the water.
        private static Texture2D MakeRippleTexture(string name, int size)
        {
            Color[] px = new Color[size * size];
            for (int y = 0; y < size; y++)
            {
                for (int x = 0; x < size; x++)
                {
                    float dx = (x + 0.5f) / size * 2f - 1f;
                    float dy = (y + 0.5f) / size * 2f - 1f;
                    float r = Mathf.Sqrt(dx * dx + dy * dy);

                    float lead = Mathf.Exp(-Mathf.Pow((r - 0.82f) / 0.085f, 2f));
                    float trail = Mathf.Exp(-Mathf.Pow((r - 0.58f) / 0.13f, 2f)) * 0.42f;
                    // Cut at the edge of the disc, or the outer ring is clipped by the quad and the
                    // ripple has four straight sides.
                    float alpha = r > 1f ? 0f : Mathf.Clamp01(lead + trail);

                    px[y * size + x] = new Color(1f, 1f, 1f, alpha);
                }
            }

            return WriteTexture(name, size, size, px, TextureWrapMode.Clamp, FilterMode.Bilinear);
        }

        // HANGS A WEIGHT ON A CARRYABLE. One line at each call site, and the weight lives on the
        // object rather than in a table inside the room that reads it - see Weighable.
        private static Weighable MakeWeighable(Component item, float kilograms)
        {
            if (item == null) return null;
            Weighable w = item.gameObject.AddComponent<Weighable>();
            w.kilograms = kilograms;
            return w;
        }

        // ONE VALVE ON A WALL. The model is a handwheel and nothing else, so the WHOLE of it spins -
        // there is no body to hold still (checked: `industrial_valve.glb` is one `Torus001` group of
        // five parts).
        //
        // WHICH WAY IT FACES IS MEASURED, NOT WRITTEN DOWN. A handwheel is a disc, so its axle is its
        // THINNEST axis - found from the bounds and rotated to point out of the wall. That survives a
        // different model, a re-export, or the glTF Z-up correction changing under us, all of which
        // have cost this project a day each before (see the seesaw and the slide).
        private static Valve BuildValve(Transform room, string name, Vector3 wallPoint, float yaw)
        {
            GameObject holder = new GameObject(name);
            holder.transform.SetParent(room, false);
            holder.transform.localPosition = wallPoint;
            // Yaw so local +Z points INTO the room, whichever wall this is.
            holder.transform.localRotation = Quaternion.Euler(0f, yaw, 0f);

            // BUILT BEFORE THE MODEL, because the model hangs under it - see the note on the reach
            // collider below for why the wheel has to be a descendant of the thing that turns it.
            GameObject spin = new GameObject(name + "Interact");
            spin.transform.SetParent(holder.transform, false);

            string path = PlayDir + "/industrial_valve.glb";
            GameObject source = AssetDatabase.LoadAssetAtPath<GameObject>(path);
            Transform wheel = null;
            Vector3 axle = Vector3.forward;
            float thickness = 0.18f;

            if (source != null)
            {
                ShrinkModelTextures(path, 1024);

                GameObject model = (GameObject)PrefabUtility.InstantiatePrefab(source, spin.transform);
                model.name = "Wheel";
                model.transform.localPosition = Vector3.zero;

                Bounds raw = ModelBounds(spin.transform, model);
                // The thinnest of the three is the axle. Measured on the model as imported, so the
                // correction below is expressed in the model's own axes.
                axle = raw.size.x <= raw.size.y && raw.size.x <= raw.size.z ? Vector3.right
                     : raw.size.y <= raw.size.z ? Vector3.up : Vector3.forward;
                // TURNED TO FACE THE ROOM, AND THEN TURNED RIGHT ROUND. Aligning the axle to +Z is a
                // choice of AXIS, not of direction - it lands the wheel's face either toward the room
                // or into the wall, and this model comes out the wrong way. The extra half turn is
                // about the room's up axis so the wheel's front is what the player walks up to.
                model.transform.localRotation = Quaternion.AngleAxis(180f, Vector3.up)
                                              * Quaternion.FromToRotation(axle, Vector3.forward)
                                              * model.transform.localRotation;

                // Re-measured AFTER the turn: the fit is of the FACE of the wheel, which is a
                // different pair of axes once it has been stood up.
                raw = ModelBounds(spin.transform, model);
                float across = Mathf.Max(0.001f, Mathf.Max(raw.size.x, raw.size.y));
                float scale = ValveDiameter / across;
                model.transform.localScale = Vector3.one * scale;

                raw = ModelBounds(spin.transform, model);
                thickness = Mathf.Max(0.05f, raw.size.z);
                // Centred on the mount and standing PROUD of the wall by its own depth, so it is a
                // thing bolted on rather than a decal.
                model.transform.localPosition = new Vector3(-raw.center.x, -raw.center.y,
                                                            thickness / 2f + 0.02f - raw.center.z);

                // ONLY THE HANDWHEEL TURNS, not the whole fixture. A valve whose BODY spins with its
                // wheel is a valve nobody has ever seen: the body is bolted to the wall and the red
                // wheel is the part a pair of hands moves.
                //
                // FOUND BY SHAPE, not by name or material. The wheel is a disc, so it is the part with
                // the largest span across the face and the smallest along the axle - which stays true
                // of a re-export that renames every node, and of a different valve model entirely.
                // (Checked against this one: five parts, and the wheel is 1131 x 1131 x 170 where the
                // body is 477 x 477 x 809.)
                wheel = WidestFlattestPart(spin.transform, model) ?? model.transform;
            }
            else
            {
                Debug.LogWarning($"[SceneBuilder] {path} is missing - {name} is an invisible valve.");
            }

            // WHERE THE E DISC HANGS: on the wheel's face, not at the mount inside the wall.
            GameObject anchorGO = new GameObject("HintAnchor");
            anchorGO.transform.SetParent(holder.transform, false);
            anchorGO.transform.localPosition = new Vector3(0f, 0f, thickness + 0.05f);

            // Reach, like every other E fixture: a box in front of the wheel deep enough to stand in.
            //
            // THE REACH IS AN OFFSET ON THE COLLIDER, not on the object - the object sits at the
            // holder's origin so that it can be the WHEEL'S PARENT. That matters for one reason:
            // `MarkReflectionProbeStatic` decides what is a mover by walking UP from each renderer
            // looking for a component that moves it, so a spinning wheel whose `Valve` is a SIBLING
            // reads as scenery and gets baked into the room's reflection mid-turn.
            GameObject interact = spin;
            BoxCollider trigger = interact.AddComponent<BoxCollider>();
            trigger.isTrigger = true;
            trigger.center = new Vector3(0f, 0f, 0.9f);
            trigger.size = new Vector3(1.9f, 2.4f, 2.0f);

            Valve valve = interact.AddComponent<Valve>();
            valve.wheel = wheel;
            valve.hintAnchor = anchorGO.transform;
            // THE AXIS IS THE HOLDER'S, NOT THE MODEL'S, now that what spins is a part INSIDE the
            // model rather than the model itself: that part carries the import's own rotation, and
            // the one thing known about it is that its face has been turned to look into the room.
            valve.spinAxis = wheel != null && wheel.parent != null
                ? wheel.parent.InverseTransformDirection(holder.transform.forward).normalized
                : axle;
            valve.audioSource = MakeSource(holder.transform, "ValveAudio", spatialBlend: 1f, volume: 0.85f);
            valve.turnClip = MakeValveTurnClip("sfx_valve_turn");
            valve.lockClip = MakeValveStopClip("sfx_valve_stop");
            return valve;
        }

        // THE FLATTEST, WIDEST PART OF A MODEL - which for a handwheel is the wheel. Compares each
        // renderer on its own bounds in the given frame: widest across the two long axes, thinnest
        // along the third. Returns null for a model with nothing in it.
        private static Transform WidestFlattestPart(Transform frame, GameObject model)
        {
            Transform best = null;
            float bestScore = float.NegativeInfinity;

            foreach (Renderer r in model.GetComponentsInChildren<Renderer>())
            {
                Mesh mesh = r.GetComponent<MeshFilter>() != null ? r.GetComponent<MeshFilter>().sharedMesh : null;
                if (mesh == null) continue;

                Bounds b = ModelBounds(frame, r.gameObject);
                float[] size = { b.size.x, b.size.y, b.size.z };
                System.Array.Sort(size);                       // thinnest first
                if (size[2] < 0.0001f) continue;
                // Flat AND big: the ratio alone would pick a washer, the span alone the body.
                float score = size[2] / Mathf.Max(0.0001f, size[0]) * size[2];
                if (score <= bestScore) continue;

                bestScore = score;
                best = r.transform;
            }

            return best;
        }

        // THE DRAIN IN THE MIDDLE OF THE FLOOR, and what the three valves are for.
        //
        // THREE PARTS AND THEY ARE NOT INTERCHANGEABLE:
        //   - the SUMP, a dark box under the hole. It is what makes the drain a hole rather than a
        //     dark square painted on the floor - you can see down it;
        //   - the GRATE, bars across the top at floor level. SOLID, and that is a safety rule rather
        //     than a decoration: the floor has a real hole in it, and a player who could fall in would
        //     be stuck in a sump they cannot climb out of, in a room with a sixty-second clock;
        //   - the COVER, the one moving part, sliding aside when the valves are all open.
        private static PoolDrain BuildDrain(Transform room, WaterPool pool, Valve[] valves,
                                            Material floorMat, Material propMat)
        {
            GameObject root = new GameObject("Drain2_6");
            root.transform.SetParent(room, false);

            Material dark = MakeColorMaterial("DrainDark", new Color(0.045f, 0.05f, 0.055f));
            Material metal = MakeColorMaterial("DrainGrate", new Color(0.28f, 0.30f, 0.32f));
            SetSmoothness(metal, 0.55f);

            float half = DrainSize / 2f;

            // --- the sump ---------------------------------------------------------------------------
            // HUNG FROM THE FLOOR SLAB'S UNDERSIDE, not run up to its top face - which is the fix
            // `docs/gotchas.md` already records for the tree pit's lip, arrived at again here. The
            // sides used to start at y=0, so their top 0.1m occupied exactly the floor slab's volume
            // and their outer faces sat on exactly the plane of the slab's cut edge: two coplanar
            // surfaces fighting for the same pixels all the way round the hole, which is the flicker
            // play saw once the cover slid off it.
            //
            // Starting them a slab's thickness lower removes the shared plane rather than biasing it.
            // A depth offset only moves a z-fight somewhere else.
            float shaftTop = -WallThickness;
            float shaftDepth = DrainDepth - WallThickness;

            Prim(PrimitiveType.Cube, "Sump_Bottom", root.transform,
                 new Vector3(0f, -DrainDepth - WallThickness / 2f, 0f),
                 new Vector3(DrainSize + 2f * WallThickness, WallThickness, DrainSize + 2f * WallThickness),
                 dark);
            for (int i = 0; i < 4; i++)
            {
                bool alongX = i < 2;
                float sign = i % 2 == 0 ? 1f : -1f;
                float midY = shaftTop - shaftDepth / 2f;
                Vector3 at = alongX ? new Vector3(sign * (half + WallThickness / 2f), midY, 0f)
                                    : new Vector3(0f, midY, sign * (half + WallThickness / 2f));
                Vector3 size = alongX ? new Vector3(WallThickness, shaftDepth, DrainSize + 2f * WallThickness)
                                      : new Vector3(DrainSize, shaftDepth, WallThickness);
                Prim(PrimitiveType.Cube, "Sump_Side_" + i, root.transform, at, size, dark);
            }

            // --- the grate --------------------------------------------------------------------------
            // Seven bars with six gaps between them. The gaps read as a grate from standing height and
            // are far narrower than the player's own capsule.
            const int bars = 7;
            float pitch = DrainSize / bars;
            for (int i = 0; i < bars; i++)
            {
                float x = -half + pitch * (i + 0.5f);
                Prim(PrimitiveType.Cube, "Grate_" + i, root.transform,
                     new Vector3(x, -WallThickness / 2f, 0f),
                     new Vector3(pitch * 0.45f, WallThickness, DrainSize), metal);
            }

            // --- the cover --------------------------------------------------------------------------
            // Sitting ON the floor rather than recessed into it, which needs no second hole and reads
            // as a plate somebody laid over the drain. Its underside is level with the floor's top
            // face - two surfaces that touch and never share a visible plane.
            GameObject cover = Prim(PrimitiveType.Cube, "Cover", root.transform,
                new Vector3(0f, 0.025f, 0f),
                new Vector3(DrainSize + 0.12f, 0.05f, DrainSize + 0.12f), metal);

            // --- what goes down it ------------------------------------------------------------------
            GameObject vortexGO = new GameObject("Vortex");
            vortexGO.transform.SetParent(root.transform, false);
            vortexGO.transform.localPosition = new Vector3(0f, 0.05f, 0f);
            ParticleSystem vortex = vortexGO.AddComponent<ParticleSystem>();
            ParticleSystem.MainModule vm = vortex.main;
            vm.loop = true;
            vm.playOnAwake = false;
            vm.startLifetime = new ParticleSystem.MinMaxCurve(0.35f, 0.9f);
            vm.startSpeed = new ParticleSystem.MinMaxCurve(0.4f, 1.4f);
            vm.startSize = new ParticleSystem.MinMaxCurve(0.02f, 0.08f);
            vm.gravityModifier = 1.4f;
            vm.startColor = new ParticleSystem.MinMaxGradient(new Color(0.90f, 0.95f, 1f, 0.85f));
            vm.simulationSpace = ParticleSystemSimulationSpace.World;
            vm.maxParticles = 300;
            ParticleSystem.EmissionModule ve = vortex.emission;
            ve.rateOverTime = 90f;
            ParticleSystem.ShapeModule vs = vortex.shape;
            vs.shapeType = ParticleSystemShapeType.Circle;
            vs.radius = half * 0.9f;
            ParticleSystemRenderer vr = vortexGO.GetComponent<ParticleSystemRenderer>();
            vr.sharedMaterial = AssetDatabase.LoadAssetAtPath<Material>("Assets/Materials/WaterStream.mat");
            vr.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;

            // --- the whirlpool ----------------------------------------------------------------------
            // A FUNNEL, not a spinning texture. The dip in the surface is the thing that says the
            // water is going somewhere - a flat sheet that shrinks reads as the water being switched
            // off - so this is real geometry with the water shader on it, rotating and narrowing as
            // the room empties. Hidden until the drain opens; `PoolDrain` owns both.
            GameObject funnel = new GameObject("Funnel");
            funnel.transform.SetParent(root.transform, false);
            funnel.AddComponent<MeshFilter>().sharedMesh = SaveGeneratedMesh(
                "WaterFunnel_r24",
                () => WaterMeshes.Funnel(rings: 14, segments: 24, throat: 0.16f, swirl: 1.35f));
            MeshRenderer funnelRend = funnel.AddComponent<MeshRenderer>();
            funnelRend.sharedMaterial = MakePoolWaterMaterial();
            funnelRend.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
            funnelRend.receiveShadows = false;
            funnel.SetActive(false);

            PoolDrain drain = root.AddComponent<PoolDrain>();
            drain.funnel = funnel.transform;
            drain.valves = valves;
            drain.pool = pool;
            drain.cover = cover.transform;
            // Aside by its own width plus a hand's breadth, so the hole is completely clear.
            drain.coverOpenOffset = new Vector3(DrainSize + 0.2f, 0f, 0f);
            drain.vortex = vortex;
            drain.audioSource = MakeSource(root.transform, "DrainAudio", spatialBlend: 1f, volume: 0.8f);
            // A room emptying is long, low and continuous - so it is the wade sound stretched out and
            // looped rather than a splash. See MakeWadeClip for why nothing in this room is a splash.
            drain.drainClip = MakeWadeClip("sfx_drain_run", 20260823, seconds: 1.6f, decay: 0.9f,
                                           fizzLevel: 0.62f, lowWeight: 3.0f);
            // What the water drags with it. Named by the caller, because the pool knows its float
            // groups and this does not - see BuildPoolRoom.
            drain.floats = pool != null ? pool.floats : null;
            return drain;
        }

        // WHAT EVERYTHING WEIGHS, and what room2-7's scale is looking for. **The player is never told
        // any of this** - the only way to learn a weight is to carry the thing to the scale and put it
        // down, which is what makes that room a measuring instrument rather than a keypad.
        //
        // HOW THE NUMBERS WERE CHOSEN, and they were SOLVED FOR rather than picked (2026-08-19).
        //
        // The room's rule is "bring all of them", so the target is the sum of one of each - and the
        // weights are chosen so that **no other combination in the whole cycle reaches it.**
        //
        //     cube 8.3  +  axe 4.7  +  beach ball 1.3  +  duck 0.4  =  14.7
        //
        // **THE BUCKET IS OUT** (2026-08-29, by request), and taking it out CLOSED THE ONE HOLE THIS
        // PROOF HAD. A partly filled pail is a CONTINUOUS weight - `Weighable` reads `Bucket.Level`,
        // which is anything at all while a bucket sits under a tap - so a player who knew the weights
        // could dial in any total they liked and the room was never single-solution. Every other
        // object here is a fixed number. With no bucket on the pan the exhaustive check is exhaustive
        // again.
        //
        // **THE WEIGHTS DID NOT HAVE TO CHANGE.** Re-run against everything cycle 2 still contains
        // (5 axes, 1 cube, 2 beach balls, 3 ducks), 14.7 has exactly one solution - and the nearest
        // miss is 0.2 rather than the old 0.1, so the room got slightly MORE readable by losing an
        // ingredient. What changed is the target, which the sign and the door both derive.
        //
        // ~~cube 8.3 + full bucket 12.0 + axe 4.7 + beach ball 1.3 + duck 0.4 = 26.7~~
        //
        // That is what the side walls draw and what the number over the door asks for. The player is
        // still told no weights: the sign names the INGREDIENTS and the door names the ANSWER, and
        // which of them add up is the thing to work out on the scale.
        //
        // THE REAL COST IS TRIPS. One object in the hand (CLAUDE.md §4), a 60-second clock, and
        // `ItemRegistry.ReturnAllToOrigin` sweeping everything home at the boundary - so four objects
        // on the pan at once is four past selves each carrying one. Still the largest headcount any
        // room in this game asks for, and one less than it was: the bucket's leg was also the longest,
        // since a full one had to be filled at a tap in room2-2 before it could be carried anywhere.
        private const float WeightDuck = 0.4f;
        private const float WeightBeachBall = 1.3f;
        // ~~The bucket's weights~~ UNUSED since 2026-08-29 - it is no longer `Weighable`. Kept
        // rather than deleted because they are the only record of what a full pail weighed, and the
        // decision that took it off the scale is one somebody may want to reverse.
        private const float WeightBucket = 2.1f;
        private const float WeightBucketWater = 9.9f;       // a full bucket read 12.0
        private const float WeightAxe = 4.7f;
        private const float WeightCube = 8.3f;
        private const float WeightPlayer = 71f;
        private const float WeighTarget = 14.7f;

        // ROOM2-6'S PUZZLE, and the numbers are here for the reason every tuned number is (CLAUDE.md
        // §2): the components own the mechanism, this owns how much of it there is.
        //
        // WHEEL HEIGHT. A valve is turned with both hands at chest height - lower and the player is
        // looking down at their own feet to find it, higher and it is a thing on a wall rather than a
        // thing you operate.
        private const float ValveHeight = 1.45f;
        // How big the wheel is across. Deliberately large: it has to be findable from the far side of
        // a nine-metre room through waist-deep water, and it is the only fixture in here.
        private const float ValveDiameter = 0.62f;
        // THE DRAIN in the middle of the floor. A square hole, because `BuildSlab` subtracts a Rect -
        // the grate over it is what gives it a shape.
        private const float DrainSize = 0.95f;
        // How deep the sump under it is. Only ever seen through the grate, so it is depth enough to
        // read as a shaft and no more.
        private const float DrainDepth = 0.9f;

        // How heavy a floating thing is. All three are light and within a factor of three of each
        // other, so the player's push (`FirstPersonController.pushSpeed`, tuned on the balloons) moves
        // any of them and none of them barges the others aside.
        private const float PoolBallMass = 0.05f;
        private const float PoolPropMass = 0.09f;

        // ONE BODY, ONE COLLIDER, ONE LAYER - everything that floats gets the same treatment.
        //
        // NO GRAVITY. Buoyancy is a spring in `FloatingBalls` rather than gravity fought by a water
        // volume: nothing can sink, nothing can be knocked out of the pool, and there is no settling
        // for a hard shove to get wrong.
        //
        // ON THE BALLOON LAYER, which is not a borrow of convenience. That layer means exactly "a light
        // thing the player wades THROUGH and shoves aside": the CharacterController excludes it, so
        // there is no invisible wall in the pool, and `pushLayers` already contains it, so the push
        // sweep works with nothing rewired. The Balloon COMPONENT is what balloon code looks for, and
        // none of these carry one.
        private static (Rigidbody body, SphereCollider solid) MakeFloatBody(GameObject go, float radius,
                                                                             float mass, bool upright)
        {
            // THE SOLID PART IS A CHILD, and that is load-bearing rather than tidy. The ducks and the
            // beach balls also carry a `CarryableItem`, which takes `GetComponent<Collider>()` on its
            // own object as its REACH trigger - with the physics sphere on the same object, which of
            // the two it picks is a coin toss. Same trap `BuildKeyPlinth` and the symbol cubes
            // document, and the same answer: one collider per object, and the rigidbody is happy to
            // own a collider a level down.
            GameObject solidGO = new GameObject("Solid");
            solidGO.transform.SetParent(go.transform, false);
            solidGO.layer = go.layer;

            SphereCollider col = solidGO.AddComponent<SphereCollider>();
            col.radius = radius;
            col.sharedMaterial = AssetDatabase.LoadAssetAtPath<PhysicsMaterial>(
                MaterialsDir + "/BalloonRubber.physicMaterial");

            Rigidbody rb = go.AddComponent<Rigidbody>();
            rb.mass = mass;
            rb.useGravity = false;
            // Enough that a shoved float coasts to a stop in a second or so, which is water, and
            // enough damping that the mooring cannot set up a slow oscillation across the pool.
            rb.linearDamping = 1.4f;
            rb.angularDamping = 1.6f;
            rb.interpolation = RigidbodyInterpolation.Interpolate;
            // UPRIGHT for anything with a top - a duck rolled onto its side by a ball is a dead duck.
            // A plastic ball is a single-coloured sphere, so its rotation is invisible and freezing it
            // is free solver work saved.
            rb.constraints = upright
                ? RigidbodyConstraints.FreezeRotationX | RigidbodyConstraints.FreezeRotationZ
                : RigidbodyConstraints.FreezeRotation;
            return (rb, col);
        }

        private static FloatingBalls BuildFloatingBalls(Transform poolRoot)
        {
            int floatLayer = EnsureLayer(BalloonLayerName);
            // A HIGHER-RESOLUTION BALL THAN THE PIT'S, and its own asset - the resolution is in the
            // name because `SaveGeneratedMesh` caches by name (see the note on it). 384 triangles at
            // 300 balls is 115k for the room, against the pit's 554k for its 5,772.
            Mesh ball = SaveGeneratedMesh("PoolBall_r12s16",
                () => LowPolySphereMesh(PoolBallRadius, 12, 16));
            if (ball == null) return null;

            GameObject root = new GameObject("FloatingBalls");
            root.transform.SetParent(poolRoot, false);

            // TWO TONES PER HUE, so twelve materials carry the six colours. The variation is what the
            // eye reads as "a lot of balls" rather than "six balls repeated", and two shades is enough
            // - the tones are half a stop apart, not a different colour.
            Material[] mats = new Material[PlasticBallColours.Length * 2];
            for (int i = 0; i < PlasticBallColours.Length; i++)
            {
                for (int tone = 0; tone < 2; tone++)
                {
                    Color hue = PlasticBallColours[i];
                    // DOWN, not up. The colour is what the ball is made of and the room is what lights
                    // it; a base colour near 1.0 leaves the light nowhere to go and the ball reads as
                    // if it is emitting.
                    //
                    // THE TONE, and it is a scale on a SATURATED hue rather than a wash toward grey -
                    // which is the whole reason 0.55/0.72 read as too bright and 0.30/0.42 as too
                    // dull. Scaling a pure hue keeps the chroma and only takes the light out of it, so
                    // these are plastic in a brightly lit white room: definitely red, definitely blue,
                    // and not glowing.
                    float level = tone == 0 ? 0.52f : 0.68f;
                    Material mat = MakeColorMaterial($"PoolBall_{i}_{tone}", hue * level);
                    // WET PLASTIC. High enough to resolve the ceiling fixtures as distinct shapes in
                    // the reflection - which is the structure that reads as a hard shiny surface, the
                    // same reasoning the escape objects' 0.97 is chosen on (CLAUDE.md §3). A ball that
                    // has just come out of the water is glossier than a dry one, not duller.
                    // A HARD SMALL HIGHLIGHT, NOT A MIRROR. At 0.88 the whole white ceiling sat on
                    // every ball and drank the colour; at 0.62 the highlight is a spot and the rest of
                    // the sphere is its own colour, which is what a wet moulded ball looks like.
                    SetSmoothness(mat, 0.62f);
                    // Three hundred renderers on twelve materials: instancing is what keeps that a
                    // handful of draws rather than three hundred.
                    mat.enableInstancing = true;
                    EditorUtility.SetDirty(mat);
                    mats[i * 2 + tone] = mat;
                }
            }

            // A JITTERED GRID RATHER THAN FREE RANDOM POSITIONS. Uniform random scatter clumps - it
            // puts three balls inside each other and leaves a two-metre hole across the room - and the
            // one thing floating objects reliably do is push each other apart. One ball per cell with a
            // jitter inside it is that spacing, for free and without a relaxation pass.
            float inset = PoolBallRadius * 2f + 0.15f;
            float spanX = RoomWidth - inset * 2f, spanZ = RoomDepth - inset * 2f;
            // Half again as many cells as balls, so which cells are empty is itself part of the
            // scatter - a grid with one ball in every cell is visibly a grid.
            float cell = Mathf.Sqrt(spanX * spanZ / (PoolBallCount * 1.5f));
            int columns = Mathf.Max(1, Mathf.FloorToInt(spanX / cell));
            int rows = Mathf.Max(1, Mathf.FloorToInt(spanZ / cell));
            float cellX = spanX / columns, cellZ = spanZ / rows;

            // A FIXED SEED, like the balloon field's and the ball pit's: the room has to be the same
            // room every time it is built, or a rebuild quietly reshuffles a scene somebody has already
            // looked at.
            Random.State entry = Random.state;
            Random.InitState(20260819);

            int cells = columns * rows;
            int[] order = new int[cells];
            for (int i = 0; i < cells; i++) order[i] = i;
            for (int i = cells - 1; i > 0; i--)
            {
                int j = Random.Range(0, i + 1);
                (order[i], order[j]) = (order[j], order[i]);
            }

            int count = Mathf.Min(PoolBallCount, cells);
            var bodies = new Rigidbody[count];
            var homes = new Vector3[count];

            // How high the centre sits: a ball `PoolBallFloat` of the way out of the water has its
            // centre that fraction of a radius above the surface. Written as the arithmetic rather than
            // as a number, so changing how buoyant they look is one constant.
            float centreOffset = PoolBallRadius * (2f * PoolBallFloat - 1f);
            float jitterX = Mathf.Max(0f, cellX * 0.5f - PoolBallRadius);
            float jitterZ = Mathf.Max(0f, cellZ * 0.5f - PoolBallRadius);

            for (int i = 0; i < count; i++)
            {
                int c = order[i] % columns, r = order[i] / columns;
                float x = -spanX / 2f + (c + 0.5f) * cellX + Random.Range(-jitterX, jitterX);
                float z = -spanZ / 2f + (r + 0.5f) * cellZ + Random.Range(-jitterZ, jitterZ);

                GameObject go = new GameObject($"Ball_{i}");
                go.transform.SetParent(root.transform, false);
                go.layer = floatLayer;
                go.AddComponent<MeshFilter>().sharedMesh = ball;
                MeshRenderer rend = go.AddComponent<MeshRenderer>();
                rend.sharedMaterial = mats[Random.Range(0, mats.Length)];
                rend.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;

                // NOT ALL THE SAME BALL. A tenth either way, which is under the threshold at which any
                // one of them looks wrong and over the one at which three hundred identical spheres
                // look printed. It rides in the transform rather than in the mesh, so it is free.
                float scale = Random.Range(0.90f, 1.10f);
                go.transform.localScale = Vector3.one * scale;

                homes[i] = new Vector3(x, PoolDepth + centreOffset * scale, z);
                go.transform.localPosition = homes[i];
                (bodies[i], _) = MakeFloatBody(go, PoolBallRadius * scale, PoolBallMass, upright: false);
            }

            Random.state = entry;

            FloatingBalls floating = root.AddComponent<FloatingBalls>();
            floating.bodies = bodies;
            floating.homes = homes;
            // STILL WATER, AND STILL BALLS. No bob and no drift, which is what lets a settled ball
            // sleep - see FloatingBalls. What moves them is the player walking through, and then the
            // mooring walks them back.
            floating.bobHeight = 0f;
            floating.drift = 0f;

            Debug.Log($"[SceneBuilder] Room2_6 pool: {PoolDepth:0.00}m of water, {count} floating "
                    + $"balls of {PoolBallRadius * 2f:0.00}m on a {columns}x{rows} grid.");
            return floating;
        }

        // ROOM2-7: THE BALL PIT, and the room IS the pit.
        //
        // The prop is a 0.68m box of balls; the room is 8.75 x 10.5. So the model is placed as the
        // thing the balls came out of, and the floor of the room is filled separately - to hip height
        // on a standing player, which is what "up to half the body" comes to at this eye height.
        //
        // THE BALLS ARE GENERATED RATHER THAN TILED FROM THE MODEL, and the reason is arithmetic. Each
        // of the prop's colour clusters is ~3,500 triangles for a 0.62m square of balls; tiling that
        // across this floor three deep is over two million triangles for one room, which is the scale
        // of the stump this project already replaced once for exactly that reason. A generated ball is
        // 96 triangles, and the whole pit comes out around 400k - built as ONE MESH PER COLOUR, so the
        // room costs six draw calls rather than five thousand.
        //
        // NOTHING ABOUT THEM IS SOLID. The player wades: they walk on the real floor with the mass at
        // their waist, which is both what a ball pit feels like and the only version that does not need
        // five thousand colliders. It also keeps them out of the loop entirely - no carryables, no
        // recorded state, nothing to rewind.
        private static void BuildBallPit(Transform room, Material propMat)
        {
            GameObject root = new GameObject("Room2_7_BallPit");
            root.transform.SetParent(room, false);

            // --- the prop -------------------------------------------------------------------------
            string path = PlayDir + "/ball_pit.glb";
            GameObject source = AssetDatabase.LoadAssetAtPath<GameObject>(path);
            if (source != null)
            {
                ShrinkModelTextures(path, 1024);

                GameObject model = (GameObject)PrefabUtility.InstantiatePrefab(source, root.transform);
                model.name = "PitProp";

                Bounds raw = ModelBounds(root.transform, model);
                // A ball pit somebody could climb into rather than a desk toy: 1.9m across, which is
                // where the model's own 0.68m lands when its FOOTPRINT is fitted rather than its
                // height. Measured, so a different prop re-fits itself.
                const float propAcross = 1.9f;
                float scale = propAcross / Mathf.Max(0.001f, Mathf.Max(raw.size.x, raw.size.z));
                model.transform.localScale = Vector3.one * scale;

                // In the corner away from both doorways - the doors are in the Z walls at x=0, so a
                // prop pushed into +X and +Z stands clear of both approaches.
                Vector3 stand = new Vector3(RoomWidth / 2f - 1.6f, 0f, RoomDepth / 2f - 1.7f);
                model.transform.localPosition = new Vector3(stand.x - raw.center.x * scale,
                                                            stand.y - raw.min.y * scale,
                                                            stand.z - raw.center.z * scale);

                Debug.Log($"[SceneBuilder] Ball pit prop: scale {scale:0.000} -> {raw.size.x * scale:0.00}m across");
            }
            else
            {
                Debug.LogWarning($"[SceneBuilder] {path} is missing - room2-7 gets the loose balls only.");
            }

            // --- the fill -------------------------------------------------------------------------
            BuildBallFill(root.transform, propMat);
        }

        // HOW DEEP THE BALLS COME. The player's eye is at 1.6m and their body is 1.8m, so 0.9m is the
        // waist - "half the body", which is what was asked for. It is also the depth at which a
        // standing player can never see the floor of the pit, which is what keeps three layers enough.
        private const float BallFillDepth = 0.9f;
        // 220mm - twice a real ball-pit ball. Deliberately: at 70mm this room needs fifty thousand of
        // them to fill, and a bigger ball reads correctly in a building whose every other dimension is
        // oversized already.
        private const float BallRadius = 0.11f;
        // THREE LAYERS, NOT THE FULL DEPTH. Five would fill the volume honestly and cost 60% more
        // triangles for a thing nobody can see: the mass is only ever looked at from above, because a
        // 1.6m eye is above a 0.9m surface from every position in the room. Each layer is offset by
        // half a pitch from the one under it, so the gaps between three of them line up with nothing.
        private const int BallLayers = 3;

        // The colours the ball-pit prop wears - blue, purple, yellow, green, red, orange. Values live
        // here like every other tuned number in this project, and they are SHARED with the balls
        // floating on room2-5's pool: the two rooms are meant to be the same plastic out of the same
        // building, and two copies of six colours is two copies that can drift apart.
        // SATURATED RATHER THAN BRIGHT, which is the distinction the pool's balls took three passes to
        // land on. "Too bright" and "not distinct enough" sound like opposites and are not: what was
        // wrong both times was CHROMA. A colour near white in one channel and mid in the others is
        // pale - it renders as a bright pastel under this building's flat white light, and pale
        // colours are also the ones hardest to tell apart. These are close to pure hues, with the
        // off-channels pushed down rather than the on-channel pushed up, so they can be darkened for
        // the room (see the tone below) and still read as red, blue, yellow.
        private static readonly Color[] PlasticBallColours =
        {
            new Color(0.05f, 0.28f, 0.95f),   // blue
            new Color(0.60f, 0.06f, 0.80f),   // purple
            new Color(1.00f, 0.80f, 0.02f),   // yellow
            new Color(0.05f, 0.70f, 0.16f),   // green
            new Color(0.92f, 0.05f, 0.07f),   // red
            new Color(1.00f, 0.40f, 0.02f),   // orange
        };

        private static void BuildBallFill(Transform root, Material propMat)
        {
            Color[] colours = PlasticBallColours;

            Mesh ball = SaveGeneratedMesh("BallPitBall", () => LowPolySphereMesh(BallRadius, 6, 8));
            if (ball == null) return;

            // INSET FROM THE WALLS by a ball's own width, so nothing pokes through a wall or through a
            // door slab sitting in its pocket.
            float inset = BallRadius * 2f;
            float halfX = RoomWidth / 2f - inset, halfZ = RoomDepth / 2f - inset;

            // Hexagonal packing: rows offset by half a pitch, which is how balls actually settle and
            // what stops the grid reading as a grid.
            float pitch = BallRadius * 2f;
            float rowPitch = pitch * 0.87f;                 // sqrt(3)/2, the hex row spacing
            float layerDrop = BallRadius * 1.55f;           // layers sit in each other's hollows

            int columns = Mathf.FloorToInt(2f * halfX / pitch);
            int rows = Mathf.FloorToInt(2f * halfZ / rowPitch);

            var byColour = new System.Collections.Generic.List<CombineInstance>[colours.Length];
            for (int i = 0; i < colours.Length; i++) byColour[i] = new System.Collections.Generic.List<CombineInstance>();

            // A FIXED SEED, like the balloon field's: the room has to be the same room every time it is
            // built, or a rebuild quietly reshuffles a scene somebody has already looked at.
            Random.State entry = Random.state;
            Random.InitState(20260817);

            int placed = 0;
            for (int layer = 0; layer < BallLayers; layer++)
            {
                float y = BallFillDepth - BallRadius - layer * layerDrop;
                if (y < BallRadius) break;

                for (int r = 0; r < rows; r++)
                {
                    for (int c = 0; c < columns; c++)
                    {
                        // Each layer is shifted half a pitch in both axes from the one above, so no
                        // column of gaps ever runs straight through the mass.
                        float ox = (r % 2 == 0 ? 0f : pitch * 0.5f) + (layer % 2 == 0 ? 0f : pitch * 0.25f);
                        float oz = layer % 2 == 0 ? 0f : rowPitch * 0.5f;

                        float x = -halfX + pitch * 0.5f + c * pitch + ox;
                        float z = -halfZ + rowPitch * 0.5f + r * rowPitch + oz;
                        if (x > halfX || z > halfZ) continue;

                        // Loose balls do not sit level. Only the top layer is jittered upward - the
                        // ones underneath are held down by the ones on top.
                        float jitter = layer == 0 ? Random.Range(-0.35f, 0.55f) * BallRadius
                                                  : Random.Range(-0.2f, 0.2f) * BallRadius;

                        var ci = new CombineInstance();
                        ci.mesh = ball;
                        ci.transform = Matrix4x4.TRS(
                            new Vector3(x, y + jitter, z),
                            Random.rotationUniform,
                            Vector3.one);
                        byColour[Random.Range(0, colours.Length)].Add(ci);
                        placed++;
                    }
                }
            }

            Random.state = entry;

            int tris = 0;
            for (int i = 0; i < colours.Length; i++)
            {
                if (byColour[i].Count == 0) continue;

                Mesh merged = new Mesh { name = $"BallPitFill_{i}" };
                // A merged ball field runs past 65,535 vertices in one colour, and the default index
                // format silently wraps rather than failing - the symptom is a mesh that renders as
                // garbage triangles across the room.
                merged.indexFormat = UnityEngine.Rendering.IndexFormat.UInt32;
                merged.CombineMeshes(byColour[i].ToArray(), true, true);
                merged.RecalculateBounds();

                string meshPath = GeneratedDir + "/BallPitFill_" + i + ".mesh";
                AssetDatabase.DeleteAsset(meshPath);
                if (!Directory.Exists(GeneratedDir)) Directory.CreateDirectory(GeneratedDir);
                AssetDatabase.CreateAsset(merged, meshPath);

                Material mat = MakeColorMaterial($"BallPit_{i}", colours[i]);
                SetSmoothness(mat, 0.72f);

                GameObject go = new GameObject($"Balls_{i}");
                go.transform.SetParent(root, false);
                go.AddComponent<MeshFilter>().sharedMesh = AssetDatabase.LoadAssetAtPath<Mesh>(meshPath);
                go.AddComponent<MeshRenderer>().sharedMaterial = mat;

                tris += merged.triangles.Length / 3;
            }

            AssetDatabase.SaveAssets();

            Debug.Log($"[SceneBuilder] Ball pit: {placed} balls of {BallRadius * 2f:0.00}m in "
                    + $"{BallLayers} layers to {BallFillDepth:0.00}m, {tris} triangles in "
                    + $"{colours.Length} draw calls");
        }

        // A BALL, cheap enough to have five thousand of. Unity's own sphere primitive is 515 triangles,
        // which is 2.7 million for this room; this is 96, and at 220mm across seen from a metre or more
        // the difference is not visible.
        private static Mesh LowPolySphereMesh(float radius, int rings, int segments)
        {
            var verts = new System.Collections.Generic.List<Vector3>();
            var norms = new System.Collections.Generic.List<Vector3>();
            var tris = new System.Collections.Generic.List<int>();

            for (int y = 0; y <= rings; y++)
            {
                float v = (float)y / rings;
                float phi = v * Mathf.PI;
                for (int x = 0; x <= segments; x++)
                {
                    float u = (float)x / segments;
                    float theta = u * Mathf.PI * 2f;
                    Vector3 n = new Vector3(Mathf.Sin(phi) * Mathf.Cos(theta),
                                            Mathf.Cos(phi),
                                            Mathf.Sin(phi) * Mathf.Sin(theta));
                    norms.Add(n);
                    verts.Add(n * radius);
                }
            }

            int stride = segments + 1;
            for (int y = 0; y < rings; y++)
            {
                for (int x = 0; x < segments; x++)
                {
                    int a = y * stride + x, b = a + stride;
                    tris.Add(a); tris.Add(b); tris.Add(a + 1);
                    tris.Add(a + 1); tris.Add(b); tris.Add(b + 1);
                }
            }

            Mesh mesh = new Mesh();
            mesh.SetVertices(verts);
            mesh.SetNormals(norms);
            mesh.SetTriangles(tris, 0);
            mesh.RecalculateBounds();
            return mesh;
        }

        // THE TREE HALL - room2-3, room2-4 and room2-5 as ONE ROOM: 10.5m across, 30.45m along and
        // 17.57m to the ceiling, at one width and one height throughout. See the constants block.
        //
        // Built at the hall's own origin with Z relative and X absolute, which is the frame the ring
        // already works in for this leg - so both openings land in the walls their neighbours meet.
        private static (Transform root, TreeTrunk trunk, TreeFelled felled,
                        Transform poolRoom, Door poolDoor, PoolDrain poolDrain, Valve[] poolValves,
                        Transform weighRoom, WeighScale weighScale,
                        Transform breakRoom, FinalRoomSequence breakSequence, CycleExit cycleTwoExit)
            BuildTreeHall(Transform parent, float z0, Material floorMat, Material grooveMat,
                          Material panelMat, Material propMat, Material fixtureMat)
        {
            GameObject rootGO = new GameObject("Room2_TreeHall_Root");
            rootGO.transform.SetParent(parent, false);
            rootGO.transform.localPosition = new Vector3(0f, 0f, z0);

            GameObject hallGO = new GameObject("Room2_TreeHall");
            hallGO.transform.SetParent(rootGO.transform, false);
            Transform t = hallGO.transform;

            float spanX = TreeHallEastFace - TreeHallWestFace;      // 30.45
            float centreX = (TreeHallEastFace + TreeHallWestFace) / 2f;

            // Slabs overrun the interior by a wall's depth so they meet the neighbouring rooms' own
            // under the shared dividers - the same reason BuildSlab runs to the room PITCH.
            Rect floorXZ = Rect.MinMaxRect(TreeHallWestFace - WallDepth, TreeHallSouthFace - WallDepth,
                                           TreeHallEastFace + WallDepth, TreeHallNorthFace + WallDepth);
            // THE PIT IS CUT WALL TO WALL - to the walls' FACES, and not one centimetre past them.
            //
            // It used to be cut across the whole floor slab, and the slab deliberately overruns the
            // interior by a `WallDepth` at each end so that it meets the neighbouring rooms' slabs
            // under the shared dividers. Cutting the pit over that overrun takes the floor out from
            // UNDER the hall's own north and south walls, which leaves a 0.125m slot running along the
            // base of each of them with nothing but shaft on the other side - play saw it as the
            // outside of the level showing through at the pit's ends.
            //
            // Stopping at the faces costs nothing the original note was protecting: the ledge it warns
            // about would be a ledge you could stand on INSIDE the room, and this one is buried in the
            // wall's own body where nobody can reach it or see it. The pit is still the full width of
            // the space, and the tree is still the only way across.
            Rect pitXZ = Rect.MinMaxRect(TreePitWestEdge, TreeHallSouthFace,
                                         TreePitEastEdge, TreeHallNorthFace);

            BuildSlabRect(t, "Floor", -WallThickness / 2f, floorXZ, floorMat, pitXZ);

            // ~~THE CEILING FADED TO VOID~~ REVERTED 2026-08-16, by request. The upper walls were
            // darkened in four bands and the ceiling made near-black, so the hall had no findable
            // top. It works, and it was judged the wrong feeling for this room - so the ceiling is an
            // ordinary ceiling again. `DarkenAbove` is gone with it; the panel-display exclusion it
            // needed is documented in docs/gotchas.md, because the trap is real for the next thing
            // that tries to recolour a wall panel.
            BuildSlabRect(t, "Ceiling", TreeHallHeight + WallThickness / 2f, floorXZ, CeilingMaterial());

            // THE NORTH WALL CARRIES BOTH DOORWAYS, which is what a single width bought - they used
            // to be in two walls 0.875m apart. `SubtractRect` takes one hole, so the wall is emitted
            // as two spans split between them; each span is a plain wall with one opening.
            float splitX = (TreeHallEntranceX + TreeHallExitX) / 2f;    // -10.4125, between the two

            BuildPanelWallSpan(t, "Wall_North_East", new Vector3(0f, 0f, TreeHallNorthFace),
                Vector3.right, Vector3.back, splitX, TreeHallEastFace, grooveMat, panelMat,
                Rect.MinMaxRect(TreeHallEntranceX - DoorWidth / 2f, 0f,
                                TreeHallEntranceX + DoorWidth / 2f, DoorHeight), TreeHallHeight);
            // THE WEST SPAN IS SOLID NOW. It carried the way out onto room2-6, and 2026-08-19's
            // second pass deleted that room along with the whole of leg 3 - the way on is the SLIDE,
            // through the south wall and a storey down. A doorway onto nothing is worse than a wall:
            // it is a promise the building cannot keep.
            BuildPanelWallSpan(t, "Wall_North_West", new Vector3(0f, 0f, TreeHallNorthFace),
                Vector3.right, Vector3.back, TreeHallWestFace, splitX, grooveMat, panelMat,
                Rect.zero, TreeHallHeight);

            // THE SOUTH WALL CARRIES ONE OPENING - the slide's mouth at the west corner. It carried a
            // second, the way back out of the room the slide lands in, until that room moved a storey
            // down on 2026-08-19: a same-level doorway stopped making sense the moment the floor on
            // the other side of it was no longer at this floor's height, so it is gone with the room
            // move rather than repositioned. Back to one span until the exit is designed.
            BuildPanelWallSpan(t, "Wall_South", new Vector3(0f, 0f, TreeHallSouthFace),
                Vector3.right, Vector3.forward, TreeHallWestFace, TreeHallEastFace,
                grooveMat, panelMat,
                Rect.MinMaxRect(TreeHallWestFace, 0f, SlideMouthEast, SlideMouthHeight),
                TreeHallHeight);
            BuildPanelWall(t, "Wall_East", new Vector3(TreeHallEastFace, 0f, 0f),
                Vector3.forward, Vector3.left, TreeHallWidth, grooveMat, panelMat, Rect.zero, TreeHallHeight);
            BuildPanelWall(t, "Wall_West", new Vector3(TreeHallWestFace, 0f, 0f),
                Vector3.forward, Vector3.right, TreeHallWidth, grooveMat, panelMat, Rect.zero, TreeHallHeight);

            BuildTreePitShaft(t, pitXZ);

            // --- the tree ---------------------------------------------------------------------------
            // BUILT BEFORE THE LIGHTS, so the lights can be told where its canopy is. Nothing else
            // about the order matters; this does.
            TreeTrunk trunk = BuildTree(t, propMat);

            Bounds canopy = new Bounds(Vector3.zero, Vector3.zero);
            bool hasCanopy = false;
            if (trunk != null)
            {
                foreach (Renderer r in trunk.transform.parent.GetComponentsInChildren<Renderer>(true))
                {
                    if (hasCanopy) canopy.Encapsulate(r.bounds); else { canopy = r.bounds; hasCanopy = true; }
                }
            }

            // --- light ---------------------------------------------------------------------------
            // SINGLE FIXTURES ON THE HALL'S CENTRE LINE, not the 2x2 cluster every other room gets.
            //
            // `BuildCeilingLights` lays four fixtures at xCentre +/- 1.75 and z +/- 2.6, which is a
            // 3.5 x 5.2m footprint sized for an 8.75 x 10.5 room. In a 30m hall that block is both
            // the wrong shape and impossible to place: the near one put a fixture 0.6m THROUGH the
            // east wall, and the far one hung a fixture over the pit's lip - the "odd positions" play
            // reported. A hall this long wants a row, and a row is what this is.
            //
            // ROOM5'S END ONLY, by request. The near ledge and the pit are unlit from above: you walk
            // in under a dark canopy, and the far side of the hole is the lit thing you are heading
            // for. That is the room telling you where to go with light instead of with a sign.
            // ROOM3 IS LIT AGAIN, and where its fixtures can go is decided entirely by the canopy.
            // The crown is 12m across and its underside is 3.4m up, so a fixture hanging at 5.4m
            // anywhere inside that footprint is buried in leaves and lights nothing. What is left is
            // the strip between the east wall and the crown's edge - which is also where the player
            // walks in, so the room lights the way you came from and leaves the tree in shadow.
            //
            // Local x here; the canopy sits at local -1.35..-10.65 (world +1.35..+10.65).
            float[] lightX = { 3.6f, 1.9f, -18.6f, -23.4f };
            foreach (float x in lightX)
            {
                if (x < TreePitEastEdge && x > TreePitWestEdge)
                {
                    Debug.LogError($"[SceneBuilder] tree hall: a light at x={x} hangs over the pit.");
                    continue;
                }

                GameObject fixture = new GameObject($"TreeHall_Fixture_{x:0.0}");
                fixture.transform.SetParent(t, false);
                fixture.transform.localPosition = new Vector3(x, RoomHeight, 0f);

                Prim(PrimitiveType.Cube, "Panel", fixture.transform,
                    new Vector3(0f, -0.02f, 0f), new Vector3(1.4f, 0.04f, 1.4f),
                    fixtureMat, removeCollider: true);

                GameObject lightGO = new GameObject("Light");
                lightGO.transform.SetParent(fixture.transform, false);
                lightGO.transform.localPosition = new Vector3(0f, -0.04f, 0f);
                lightGO.transform.localRotation = Quaternion.Euler(90f, 0f, 0f);
                Light light = lightGO.AddComponent<Light>();
                light.type = LightType.Spot;
                light.spotAngle = CeilingSpotAngle;
                light.innerSpotAngle = 45f;
                light.range = 11f;
                // The same intensity every other fixture in the building carries - see
                // BuildCeilingLights for how that number was derived and why it is not re-tuned here.
                light.intensity = CeilingLightIntensity;
                light.shadows = LightShadows.None;

                // The stem up to the real ceiling, which is three times further away than this
                // fixture hangs. Without it a lit square floats with nothing holding it.
                float drop = TreeHallHeight - RoomHeight;
                Prim(PrimitiveType.Cylinder, "Stem", fixture.transform,
                     new Vector3(0f, drop / 2f, 0f), new Vector3(0.06f, drop / 2f, 0.06f),
                     propMat, removeCollider: true);
            }

            BuildReflectionProbe(t, "Room2_TreeHall", 0f, centreX,
                sizeOverride: new Vector3(spanX, TreeHallHeight, TreeHallWidth),
                yCenter: TreeHallHeight * 0.5f);

            // --- what the tree opens, and the five axes ---------------------------------------------
            //
            // THE TREE NO LONGER OPENS A DOOR, AND STILL GATES THE ROOM. `Door2_3` used to hang on
            // this condition in the north wall above; that wall is solid now (see the span above) and
            // the way on is the slide, on the FAR ledge. The pit is what keeps it shut: the tree is
            // the only bridge, so felling it is still the price of getting out of this room, and it is
            // enforced by the hole in the floor rather than by a lock.
            //
            // `TreeFelled` is kept and still handed back as a `RoomCondition`, which is what rewinds it
            // at the top of an iteration - and is what a door built here later would ask.
            GameObject felledGO = new GameObject("TreeFelled");
            felledGO.transform.SetParent(t, false);
            TreeFelled felled = felledGO.AddComponent<TreeFelled>();
            felled.trunk = trunk;

            // SCATTERED, AND TWO OF THEM KNOCKED OVER, for the reason the buckets are: five axes in a
            // row is equipment issued to the player, five lying about is a room somebody left in a
            // hurry. All of them on the NEAR ledge, clear of the entrance and well back from the lip -
            // an axe kicked into the pit is a loss this room must not be able to inflict.
            // ALL FLAT, NONE TIPPED. `tipDegrees` rolled an axe onto its edge, which for a shape this
            // thin stood it up and drove it into the floor - two of the five were planted like
            // grave markers. Scatter is carried entirely by YAW now, which is the only axis that can
            // vary without lifting the object off the ground.
            BuildFireAxe(t, "FireAxe_0", new Vector3(2.30f, 0f, -2.40f), yaw: 37f);
            BuildFireAxe(t, "FireAxe_1", new Vector3(-0.40f, 0f, -3.55f), yaw: -108f);
            BuildFireAxe(t, "FireAxe_2", new Vector3(3.35f, 0f, 1.60f), yaw: 74f);
            BuildFireAxe(t, "FireAxe_3", new Vector3(-1.10f, 0f, 3.30f), yaw: 152f);
            BuildFireAxe(t, "FireAxe_4", new Vector3(-3.20f, 0f, -0.60f), yaw: -21f);

            // --- the far ledge, room2-5 ---------------------------------------------------------------
            //
            // ORDER MATTERS FOR EXACTLY ONE REASON: the ride's path is raycast off whatever is under
            // it, and the last few metres of that path are the landing room's FLOOR. Build the room,
            // then the slide, then measure the ride - anything else measures a hole.
            (Transform poolRoom, Door poolDoor, PoolDrain poolDrain, Valve[] poolValves) =
                BuildPoolRoom(rootGO.transform, floorMat, grooveMat, panelMat, propMat, fixtureMat);
            (Transform weighRoom, WeighScale weighScale) =
                BuildWeighRoom(rootGO.transform, floorMat, grooveMat, panelMat, propMat, fixtureMat);
            // ROOM2-0, one further south again - the last room of the walk, and the `-0` of the
            // cycle by the naming rule: a cycle always ends in its -0 (docs/cycle-design.md SS4a).
            // It was a bare shell for one day; it is the console room now.
            (Transform breakRoom, FinalRoomSequence breakSequence, CycleExit cycleTwoExit) =
                BuildBreakRoom(rootGO.transform,
                    new Vector3(SlideRoomCentreX, SlideRoomFloorY, SlideRoomCentreZ - 2f * RoomPitch),
                    floorMat, grooveMat, panelMat, propMat, fixtureMat);
            BuildSeesaw(t);
            BuildSlide(t);

            // NO WAY BACK. The slide is one-way and the pool room's own door leads ON rather than
            // back - see BuildPoolRoom. A player who rides down without solving it waits out the
            // clock, which is what every room in this game does to somebody who is not finished.

            return (rootGO.transform, trunk, felled, poolRoom, poolDoor, poolDrain, poolValves,
                    weighRoom, weighScale, breakRoom, breakSequence, cycleTwoExit);
        }

        // ROOM2-5: THE SEESAW, and the only thing on the far ledge that IS scenery. A child's thing
        // at full size in a building that has none of them, next to the slide it was placed beside.
        //
        // PLACED BY HAND AND READ BACK, like the slide - see SeesawLocalPosition. Note that it does
        // NOT stand on the floor: the hand placement left it about half a metre up, and that is
        // reproduced here as it was found rather than quietly corrected. Dropping it is one number.
        private static void BuildSeesaw(Transform hall)
        {
            string path = PlayDir + "/seesaw.glb";
            GameObject source = AssetDatabase.LoadAssetAtPath<GameObject>(path);
            if (source == null)
            {
                Debug.LogWarning($"[SceneBuilder] {path} is missing - room2-5 loses its seesaw.");
                return;
            }

            ShrinkModelTextures(path, 1024);

            GameObject root = new GameObject("Room2_5_Seesaw");
            root.transform.SetParent(hall, false);
            root.transform.localPosition = SeesawLocalPosition;

            GameObject model = (GameObject)PrefabUtility.InstantiatePrefab(source, root.transform);
            model.name = "Seesaw";
            model.transform.localPosition = Vector3.zero;
            model.transform.localRotation = Quaternion.Euler(SeesawLocalEuler);
            model.transform.localScale = Vector3.one * SeesawLocalScale;

            // SOLID, for the reason the slide is: a seesaw you walk through is a poster. Mesh colliders
            // on the parts as they are - the plank is held up by nothing at its ends, and convex would
            // fill that in and turn the whole thing into one box.
            int solid = 0;
            foreach (MeshFilter mf in model.GetComponentsInChildren<MeshFilter>(true))
            {
                if (mf.sharedMesh == null) continue;
                MeshCollider mc = mf.gameObject.AddComponent<MeshCollider>();
                mc.sharedMesh = mf.sharedMesh;
                solid++;
            }

            Debug.Log($"[SceneBuilder] Seesaw: scale {SeesawLocalScale:0.000} at "
                    + $"x={SeesawLocalPosition.x:0.00}, z={SeesawLocalPosition.z:0.00}, "
                    + $"{solid} solid part(s)");
        }

        // A wall between two points along its own axis, rather than one centred on its parent.
        //
        // `BuildPanelWall` takes a centre and a width, which is every wall in the building until a
        // 30m wall needs TWO doorways in it and `SubtractRect` only takes one hole. Splitting the
        // wall into two spans, each with its own opening, is cheaper than teaching the subtraction to
        // take a list - and the seam between them falls inside a groove either way.
        private static void BuildPanelWallSpan(Transform parent, string name, Vector3 faceAtBase,
                                               Vector3 rightDir, Vector3 inward,
                                               float fromAlong, float toAlong,
                                               Material backingMat, Material panelMat,
                                               Rect cutoutAlongHeight, float wallHeight)
        {
            float width = toAlong - fromAlong;
            float centre = (fromAlong + toAlong) / 2f;
            // The cutout arrives in the coordinates the span itself is given in, so it is shifted
            // into the wall's own centred frame here rather than at every call site.
            Rect local = cutoutAlongHeight.width > 0f
                ? Rect.MinMaxRect(cutoutAlongHeight.xMin - centre, cutoutAlongHeight.yMin,
                                  cutoutAlongHeight.xMax - centre, cutoutAlongHeight.yMax)
                : Rect.zero;

            BuildPanelWall(parent, name, faceAtBase + rightDir * centre, rightDir, inward,
                           width, backingMat, panelMat, local, wallHeight);
        }

        // WHAT "BOTTOMLESS" IS MADE OF. There is no kill plane, no fall damage and no Y bound
        // anywhere in this project, so the pit is a shaft deeper than the player can see into with
        // nothing at the end of it - and a floor at the bottom regardless, because the probes clear
        // to SKYBOX and an open-ended hole would glow.
        //
        // What happens to somebody who falls in is NOT decided here. Today they land on that floor,
        // twenty-six metres down, in the dark, with no way out until the iteration ends.
        private static void BuildTreePitShaft(Transform parent, Rect pitXZ)
        {
            Material shaftMat = MakeColorMaterial("TreePitShaft", new Color(0.048f, 0.049f, 0.055f));
            SetSmoothness(shaftMat, 0.08f);

            GameObject shaft = new GameObject("TreePit");
            shaft.transform.SetParent(parent, false);

            float cx = pitXZ.center.x, cz = pitXZ.center.y;
            float halfX = pitXZ.width / 2f, halfZ = pitXZ.height / 2f;
            float outerZ = pitXZ.height + 2f * WallThickness;

            // THE SHAFT HANGS BELOW THE FLOOR SLAB, NOT ALONGSIDE IT - which is what stops the lip
            // flickering. The walls used to run from y=0 down, so their top 0.1m shared exactly the
            // volume the floor slab occupies, and their outer face sat on exactly the plane of the
            // slab's cut edge: two coplanar faces fighting for the same pixels all the way round the
            // hole. Starting at the slab's underside removes the shared plane rather than biasing it.
            float top = -WallThickness;
            float mid = top - TreePitDepth / 2f;

            Prim(PrimitiveType.Cube, "Shaft_East", shaft.transform,
                new Vector3(cx + halfX + WallThickness / 2f, mid, cz),
                new Vector3(WallThickness, TreePitDepth, outerZ), shaftMat);
            Prim(PrimitiveType.Cube, "Shaft_West", shaft.transform,
                new Vector3(cx - halfX - WallThickness / 2f, mid, cz),
                new Vector3(WallThickness, TreePitDepth, outerZ), shaftMat);
            Prim(PrimitiveType.Cube, "Shaft_North", shaft.transform,
                new Vector3(cx, mid, cz + halfZ + WallThickness / 2f),
                new Vector3(pitXZ.width, TreePitDepth, WallThickness), shaftMat);
            Prim(PrimitiveType.Cube, "Shaft_South", shaft.transform,
                new Vector3(cx, mid, cz - halfZ - WallThickness / 2f),
                new Vector3(pitXZ.width, TreePitDepth, WallThickness), shaftMat);
            Prim(PrimitiveType.Cube, "Shaft_Bottom", shaft.transform,
                new Vector3(cx, top - TreePitDepth - WallThickness / 2f, cz),
                new Vector3(pitXZ.width + 2f * WallThickness, WallThickness, outerZ), shaftMat);

            // FALLING IN IS FATAL. The volume starts 2m below the lip rather than at it, so that
            // clipping the edge on the way past is not a death - you have to be in the shaft. It
            // fills the rest of it, because a thin plate can be fallen through between two fixed
            // steps and there is nothing below this to catch anybody.
            GameObject kill = new GameObject("PitKillVolume");
            kill.transform.SetParent(shaft.transform, false);
            kill.transform.localPosition = new Vector3(cx, -(TreePitDepth + 2f) / 2f, cz);
            BoxCollider killBox = kill.AddComponent<BoxCollider>();
            killBox.isTrigger = true;
            killBox.size = new Vector3(pitXZ.width, TreePitDepth - 2f, pitXZ.height);
            kill.AddComponent<KillVolume>();
        }

        // THE TREE, WHICH IS TWO OBJECTS MADE FROM ONE MODEL, AND A NOTCH THAT IS REAL GEOMETRY.
        //
        // `realistic_tree.glb` is a single 16m piece and this room needs a stump that stays and an
        // upper trunk that goes over, so the meshes are CUT at build time. Cutting by triangle
        // centroid leaves a ragged edge, and a ragged edge is what a chopped trunk has, so the cheap
        // way is also the right-looking one.
        //
        // THE NOTCH IS CUT, NOT DRAWN, and that is the second version of it. The first was a dark
        // wedge laid ON the trunk, which reads as something stuck to the tree rather than as wood
        // taken out of it - play called it "a vertical groove". Wood cannot be taken out of a mesh at
        // runtime for the price of a keypress, so all `TreeNotchStages` of it are cut HERE and the
        // stage is switched by enabling one of them. A dark core cylinder sits just inside the bark,
        // invisible until a notch opens onto it, and is what the player sees in the cut.
        //
        // SCALED TO FIT rather than set to a number: the crown is 11.72m across at native size and
        // the hall is 10.5m, so a native tree grows through both side walls. The scale is derived
        // from the measurement so that changing the hall's width cannot silently leave the tree
        // poking through it.
        private static TreeTrunk BuildTree(Transform parent, Material propMat)
        {
            string assetPath = $"{NatureDir}/realistic_tree.glb";
            // BEFORE ANYTHING IS INSTANTIATED. These two models between them carry 645MB of
            // uncompressed texture, which is the stutter this room was reported to have - see
            // ShrinkModelTextures. 1024 is well past what a tree read at three metres needs.
            ShrinkModelTextures(assetPath, 1024);
            GameObject source = AssetDatabase.LoadAssetAtPath<GameObject>(assetPath);
            if (source == null)
            {
                Debug.LogError($"[SceneBuilder] {assetPath} is missing - the tree hall has no tree.");
                return null;
            }

            GameObject root = new GameObject("Tree");
            root.transform.SetParent(parent, false);
            root.transform.localPosition = new Vector3(TreeStandX, -TreeSinkDepth, 0f);

            // One throwaway instance so the real ones are PLACED rather than probed. Bounds are taken
            // in the tree's own frame - see ModelBounds for what taking them raw does.
            GameObject probe = (GameObject)PrefabUtility.InstantiatePrefab(source, root.transform);
            Bounds raw = ModelBounds(root.transform, probe);
            Object.DestroyImmediate(probe);

            float scale = Mathf.Min(1f, (TreeHallWidth - 2f * TreeWallClearance) / raw.size.z);
            // THE CROWN IS NOT CENTRED ON THE TRUNK - it leans, by 0.33m at this scale - so standing
            // the TRUNK in the middle of the hall spends all the clearance on one side and leaves
            // 20mm on the other. What has to be centred is the thing that nearly touches the walls.
            root.transform.localPosition -= new Vector3(0f, 0f, raw.center.z * scale);
            float lift = -raw.min.y * scale;
            float height = raw.size.y * scale;

            // THREE INSTANCES, and the third is the point. `whole` is never split and never falls:
            // it is the source for the notch stages, which are what the player looks at right up
            // until the tree goes over. `stump` and `faller` are split, and exist only to source the
            // felled pair.
            GameObject whole = (GameObject)PrefabUtility.InstantiatePrefab(source, root.transform);
            whole.name = "WholeSource";
            whole.transform.localScale = Vector3.one * scale;
            whole.transform.localPosition = new Vector3(0f, lift, 0f);

            GameObject stump = (GameObject)PrefabUtility.InstantiatePrefab(source, root.transform);
            stump.name = "Stump";
            stump.transform.localScale = Vector3.one * scale;
            stump.transform.localPosition = new Vector3(0f, lift, 0f);

            GameObject pivotGO = new GameObject("FallPivot");
            pivotGO.transform.SetParent(root.transform, false);
            pivotGO.transform.localPosition = new Vector3(0f, TreeCutHeight, 0f);

            GameObject faller = (GameObject)PrefabUtility.InstantiatePrefab(source, pivotGO.transform);
            faller.name = "Faller";
            faller.transform.localScale = Vector3.one * scale;
            faller.transform.localPosition = new Vector3(0f, lift - TreeCutHeight, 0f);

            // NEITHER INSTANCE'S OWN ROTATION IS TOUCHED, and that is load-bearing. This model is
            // authored Z-UP and the glTF importer carries the correction inside the prefab, so
            // overwriting the instance's rotation - even with identity - destroys it, and the tree
            // then answers a rotation with a pure translation. The pivot above it is a plain
            // GameObject of ours and turns cleanly. See docs/gotchas.md.
            SplitTreeMeshes(root.transform, stump, TreeCutHeight, keepAbove: false, tag: "stump");
            SplitTreeMeshes(root.transform, faller, TreeCutHeight, keepAbove: true, tag: "faller");

            // `whole` IS A TRUNK SOURCE AND NOTHING ELSE. It is an unsplit copy of the entire tree, so
            // it arrives carrying a second set of branches and a second CROWN - and those sit on the
            // tree's root rather than on the fall pivot, so when the tree went over its canopy stayed
            // hanging in the room. Everything but its trunk is switched off here; the canopy the
            // player sees is `faller`'s, which rides the pivot and goes with it.
            {
                MeshFilter keep = TrunkMeshOf(root.transform, whole, TreeCutHeight);
                int hidden = 0;
                foreach (MeshFilter mf in whole.GetComponentsInChildren<MeshFilter>(true))
                    if (mf != keep) { mf.gameObject.SetActive(false); hidden++; }
                Debug.Log($"[SceneBuilder] Tree: {hidden} duplicate canopy/branch mesh(es) hidden on the whole-trunk source");
            }

            // THE TRUNK'S OWN SIZE AT THE CUT, measured off the split meshes rather than assumed -
            // the notch, the core and the bridge deck are all sized from it.
            float halfWidth = TrunkHalfWidthAt(root.transform, stump, TreeCutHeight);
            float westFace = -halfWidth;
            Debug.Log($"[SceneBuilder] Tree: native {raw.size.y:0.00}m -> scale {scale:0.000} "
                    + $"= {height:0.00}m tall, crown {raw.size.x * scale:0.00}x{raw.size.z * scale:0.00}, "
                    + $"trunk {halfWidth * 2f:0.00}m thick at the {TreeCutHeight:0.00}m cut");

            // --- the notch: TreeNotchStages real cuts, one shown at a time ------------------------
            //
            // A V lying on its side, widest where the axe lands and closing at its apex, deepening
            // stage by stage. Both halves are cut with the same wedge, because the wedge straddles
            // the plane the tree separates on - which is the point: the notch IS where it breaks.
            // --- the notch: TreeNotchStages real cuts, one shown at a time ------------------------
            //
            // A V lying on its side, widest where the axe lands and closing at its apex, deepening
            // stage by stage - the triangular bite an axe actually makes.
            //
            // **THE STANDING TREE IS ONE UNBROKEN MESH.** This is the second version, and the first
            // shipped the tree looking already felled: the stages were built from the SPLIT halves,
            // so even stage zero showed the ragged seam where the centroid test had divided the
            // trunk in two. A tree that is visibly cut before anybody has swung at it gives the whole
            // puzzle away and looks broken.
            //
            // So a stage is now ONE mesh - the whole trunk minus the wedge - and the trunk does not
            // come apart at all until it goes over. The split pair is built too, but it is only
            // switched on at the moment of the fall, which is the moment it should first be visible.
            GameObject stages = new GameObject("NotchStages");
            stages.transform.SetParent(root.transform, false);

            // WHICH MESH THE NOTCH IS IN. Only the trunk is copied: the crown and the branches are
            // metres above the cut and would be `TreeNotchStages` duplicates of the heaviest meshes
            // in the scene - and, in an earlier version, they were switched OFF with the half that
            // owned them, so chopping made the canopy disappear.
            MeshFilter wholeTrunkMesh = TrunkMeshOf(root.transform, whole, TreeCutHeight);
            MeshFilter stumpTrunk = TrunkMeshOf(root.transform, stump, TreeCutHeight);
            MeshFilter fallerTrunk = TrunkMeshOf(root.transform, faller, TreeCutHeight);

            // SEEN FROM BOTH SIDES, which is half of what stands in for exposed heartwood.
            //
            // A cut into a mesh shows its inside, and an inside is back-faces, and back-faces are not
            // drawn - so the notch looked straight through the tree. The other half is the nested
            // fill below; this is what stops a deep cut showing daylight.
            Material barkCut = null;
            if (wholeTrunkMesh != null)
            {
                Material src = wholeTrunkMesh.GetComponent<MeshRenderer>().sharedMaterial;
                barkCut = new Material(src) { name = "TreeBark_Cut" };
                if (barkCut.HasProperty("_Cull")) barkCut.SetFloat("_Cull", 0f);
                if (barkCut.HasProperty("_CullMode")) barkCut.SetFloat("_CullMode", 0f);
                barkCut.doubleSidedGI = true;
                AssetDatabase.CreateAsset(barkCut, $"{MaterialsDir}/TreeBark_Cut.mat");
            }

            float maxDepth = halfWidth * 1.55f;   // past the centre, so the last stage is nearly through

            // WHAT THE CUT LOOKS INTO. A trunk is a SHELL, so a notch opened into it shows the inside
            // of the far wall - hollow, which is what play reported. The fill is the trunk's own mesh,
            // shrunk toward its own centre-line over the notch's height band: the one construction
            // that cannot be the wrong shape here, because this trunk tapers by a third across the
            // band AND leans off the tree's origin, which defeated a cylinder twice.
            //
            // Nested, because the last stage cuts past the centre - one shell would be cut through as
            // well, and the innermost is small enough that the cut never reaches it.
            GameObject fills = new GameObject("TrunkFill");
            fills.transform.SetParent(root.transform, false);
            float fillBand = maxDepth * TreeNotchHalfAngleTan + 0.12f;
            foreach (float shrink in new[] { 0.86f, 0.62f, 0.40f })
            {
                BuildTrunkFill(root.transform, fills.transform, stumpTrunk, $"Fill_Lower_{shrink:0.00}",
                               TreeCutHeight - fillBand, TreeCutHeight, shrink, barkCut);
                BuildTrunkFill(root.transform, pivotGO.transform, fallerTrunk, $"Fill_Upper_{shrink:0.00}",
                               TreeCutHeight, TreeCutHeight + fillBand, shrink, barkCut);
            }

            // The stages themselves: whole trunk, one wedge, no seam.
            var notchStages = new GameObject[TreeNotchStages];
            for (int i = 0; i < TreeNotchStages; i++)
            {
                float depth = maxDepth * (i + 1) / TreeNotchStages;
                notchStages[i] = BuildNotchStage(root.transform, stages.transform, wholeTrunkMesh,
                    $"Notch_{i}", westFace, depth, TreeCutHeight, keepAbove: null, cutMat: barkCut);
            }

            // AND THE PAIR THAT ONLY EXISTS ONCE IT IS DOWN, carved to the deepest stage so the
            // severed faces match the notch that severed them.
            //
            // BOTH HALVES ARE THE TREE'S OWN MESH AGAIN (2026-08-17, by request: "remove the roots,
            // leave only the tree model"). A separate `tree_roots.glb` used to stand at the base as
            // the thing left behind, which meant the room contained two different trees' geometry
            // meeting at the floor. What remains after the cut is now the trunk the player has been
            // chopping, carved by the same wedge that severed it - so the stump and the log are two
            // halves of one object, which is what they are.
            GameObject felledLower = BuildNotchStage(root.transform, stages.transform, stumpTrunk,
                "Felled_Stump", westFace, maxDepth, TreeCutHeight, keepAbove: false, cutMat: barkCut);
            GameObject felledUpper = BuildNotchStage(root.transform, stages.transform, fallerTrunk,
                "Felled_Faller", westFace, maxDepth, TreeCutHeight, keepAbove: true, cutMat: barkCut);
            felledUpper.transform.SetParent(pivotGO.transform, true);

            // Something solid to walk into while it stands. On the STUMP only - the faller is in the
            // air until it is not, and a collider swinging through the room during the fall would
            // shove the player.
            GameObject stumpSolid = new GameObject("StumpBlocker");
            stumpSolid.transform.SetParent(root.transform, false);
            stumpSolid.transform.localPosition = new Vector3(0f, TreeCutHeight / 2f, 0f);
            BoxCollider stumpBox = stumpSolid.AddComponent<BoxCollider>();
            stumpBox.size = new Vector3(halfWidth * 2f, TreeCutHeight, halfWidth * 2f);

            // EVERY PART OF THE FELLED TREE IS SOLID, by request: the trunk, the branches and the
            // crown all take weight once it is down. They were pass-through, so a player crossing
            // walked over an invisible deck with the tree they were supposedly on going through them.
            //
            // Non-convex mesh colliders, built disabled and switched on when the fall lands - never
            // during it, because a mesh collider sweeping through the player is exactly the shove
            // §1.7 keeps ghosts from delivering.
            // WHAT IS SOLID ON THE FELLED TREE, AND WHAT IS NOT - and the split is the whole answer
            // to "crossing it is hard".
            //
            // Everything was solid in the first version, leaves included, and that is what made the
            // crossing a scramble: the canopy is a 10m tangle of round branches, the clear trunk is
            // only 2.4m of a 10.5m span, and falling off is now fatal. Making the leaves solid is also
            // the wrong reading of what foliage IS - you push through leaves, you do not stand on them
            // - and it put a 18,500-vertex mesh collider in the scene for the privilege.
            //
            // So: the TRUNK and the BRANCHES take weight, the LEAVES do not. Crossing is walking the
            // trunk line and pushing through canopy, which is what crossing a fallen tree is.
            var branchColliders = new System.Collections.Generic.List<Collider>();
            int leafMeshes = 0;
            foreach (MeshFilter mf in faller.GetComponentsInChildren<MeshFilter>(true))
            {
                if (mf.sharedMesh == null) continue;
                Material mat = mf.GetComponent<MeshRenderer>() != null
                    ? mf.GetComponent<MeshRenderer>().sharedMaterial : null;
                // By MATERIAL, not by name: the leaf material is the one the model itself marks as
                // foliage, and a re-export is free to rename the mesh but not to change what it is.
                if (mat != null && mat.name.ToLowerInvariant().Contains("leaves")) { leafMeshes++; continue; }

                MeshCollider mc = mf.gameObject.AddComponent<MeshCollider>();
                mc.sharedMesh = mf.sharedMesh;
                mc.enabled = false;
                branchColliders.Add(mc);
            }
            // The severed upper trunk itself, which is the surface most of the crossing happens on.
            if (felledUpper != null)
            {
                MeshFilter mf = felledUpper.GetComponent<MeshFilter>();
                if (mf != null && mf.sharedMesh != null)
                {
                    MeshCollider mc = felledUpper.AddComponent<MeshCollider>();
                    mc.sharedMesh = mf.sharedMesh;
                    mc.enabled = false;
                    branchColliders.Add(mc);
                }
            }
            Debug.Log($"[SceneBuilder] Tree bridge: {branchColliders.Count} solid part(s), "
                    + $"{leafMeshes} leaf mesh(es) left to push through");

            // THE DECK: one flat walkway the length of the span, and it is not redundant with the
            // colliders above. What has to be reliable is that a player who steps onto a felled tree
            // gets across; bark over a fatal drop is the wrong place to discover a gap between two
            // branches. Its top is level with the log's, so it reads as the log rather than as a
            // plank - and it is WIDE, because the alternative to a wide deck over a fatal pit is
            // dying to a sidestep.
            GameObject bridge = new GameObject("TreeBridge");
            bridge.transform.SetParent(parent, false);
            float minX = TreePitWestEdge - 1.0f, maxX = TreePitEastEdge + 1.0f;
            float deckTop = halfWidth;      // the felled trunk rests with its axis on the floor
            bridge.transform.localPosition = new Vector3((minX + maxX) / 2f, deckTop / 2f, 0f);
            BoxCollider deck = bridge.AddComponent<BoxCollider>();
            deck.size = new Vector3(maxX - minX, deckTop, halfWidth * 5.4f);

            // A RAMP AT EACH LIP, because the deck's top is 0.6m up and the player's step is not.
            // Without them the crossing opens with a jump onto a narrow surface over a fatal drop,
            // which is the least forgiving moment in the room and the least deliberate.
            //
            // A rotated box rather than a slope mesh: the CharacterController walks a collider, and
            // its `slopeLimit` is what decides whether this is a ramp or a wall - about 26 degrees
            // here, which is a walk rather than a climb.
            for (int side = 0; side < 2; side++)
            {
                float lipX = side == 0 ? TreePitEastEdge + 1.0f : TreePitWestEdge - 1.0f;
                float dir = side == 0 ? 1f : -1f;
                const float rampRun = 1.3f;
                GameObject ramp = new GameObject($"TreeBridge_Ramp_{side}");
                ramp.transform.SetParent(bridge.transform, true);
                ramp.transform.localScale = Vector3.one;
                ramp.transform.position = bridge.transform.TransformPoint(
                    new Vector3(lipX - bridge.transform.localPosition.x + dir * rampRun / 2f,
                                deckTop / 2f - deckTop / 2f, 0f));
                ramp.transform.localRotation = Quaternion.Euler(
                    0f, 0f, dir * -Mathf.Atan2(deckTop, rampRun) * Mathf.Rad2Deg);
                BoxCollider rampBox = ramp.AddComponent<BoxCollider>();
                rampBox.size = new Vector3(Mathf.Sqrt(rampRun * rampRun + deckTop * deckTop),
                                           0.12f, halfWidth * 5.4f);
            }
            bridge.SetActive(false);

            // The volume you have to be standing in to swing. Generous on purpose: the player is
            // holding a metre of axe at true size and should not have to hunt for a spot.
            GameObject chop = new GameObject("TreeTrunk");
            chop.transform.SetParent(root.transform, false);
            chop.transform.localPosition = new Vector3(-halfWidth * 0.6f, 1.2f, 0f);
            BoxCollider reach = chop.AddComponent<BoxCollider>();
            reach.isTrigger = true;
            reach.size = new Vector3(halfWidth * 2f + 2.4f, 2.8f, halfWidth * 2f + 2.4f);

            GameObject hint = new GameObject("HintAnchor");
            hint.transform.SetParent(root.transform, false);
            hint.transform.localPosition = new Vector3(westFace - 0.25f, TreeCutHeight + 0.35f, 0f);

            TreeTrunk trunk = chop.AddComponent<TreeTrunk>();
            trunk.axeItemId = CycleTwoToolItemId;
            // THIRTY, down from forty, and it is paying for the swing rather than making the room
            // easier. A blow takes 0.78s to read now instead of 0.52, so forty of them is the same
            // wall of time it always was with fewer of them landing - the count comes down by ten to
            // hold the room where it was. It is still out of one player's reach inside sixty seconds
            // and still comfortable for five pairs of hands, which is the only thing it has to be.
            // TWENTY, down from twenty-five and forty before that (2026-08-19, by request). The
            // number only has to be well past what one pair of hands fits into a minute, which twenty
            // still is; past that, more of them is more waiting rather than more accumulation.
            // `TreeNotchStages` is unchanged at 8, so the notch deepens faster per swing.
            trunk.chopsToFell = 20;
            // WHAT IS SHOWN WHEN, and it is three states rather than two. `wholeTrunk` is the
            // untouched trunk before any chop has landed; `notchStages` are the bitten-but-unbroken
            // trunk while it is being cut; `felledLower`/`felledUpper` are the severed pair, and they
            // are the only ones that show a seam - which they earn, because by then it is severed.
            trunk.wholeTrunk = new[] { wholeTrunkMesh != null ? wholeTrunkMesh.gameObject : null };
            trunk.notchStages = notchStages;
            trunk.felledLower = felledLower;
            trunk.felledUpper = felledUpper;
            // The split halves are only ever sources for the pair above - never shown.
            if (stumpTrunk != null) stumpTrunk.gameObject.SetActive(false);
            if (fallerTrunk != null) fallerTrunk.gameObject.SetActive(false);
            trunk.fallPivot = pivotGO.transform;
            // Over to the WEST, across the pit. Euler Z+90 takes the trunk's own up to -X.
            trunk.fallEuler = new Vector3(0f, 0f, 90f);
            // AND DOWN, by the height of the cut. A tree cut at 1.2m does not stay 1.2m up: the butt
            // slips off the stump as it goes and the log ends up ON the ground. That is also the only
            // way it is crossable - the player's jump clears 0.9m, and a log left at the cut height
            // would have put its walking surface at 1.9m, which is a wall rather than a bridge.
            trunk.fallDrop = TreeCutHeight;
            trunk.bridgeSurface = bridge;
            trunk.branchColliders = branchColliders.ToArray();
            trunk.hintAnchor = hint.transform;
            trunk.audioSource = MakeSource(root.transform, "ChopAudio", spatialBlend: 1f, volume: 0.9f);
            trunk.chopClip = MakeChopClip("sfx_axe_chop");
            trunk.fallClip = LoadClip(SfxDir, "sfx_door_open");

            // DOES IT ACTUALLY REACH? The whole room turns on it, it depends on four numbers that are
            // each free to move, and a tree that lands short is a hall with no way across and no
            // other symptom. Measured off the real geometry, not the nominal height.
            float reachFromCut = height - TreeCutHeight;
            float landsAtX = TreeStandX - reachFromCut;
            if (landsAtX > TreePitWestEdge)
                Debug.LogError($"[SceneBuilder] the felled tree stops at x={landsAtX:0.00}, short of the "
                             + $"far lip at {TreePitWestEdge:0.00} - the pit cannot be crossed.");
            else
                Debug.Log($"[SceneBuilder] Tree bridge: {reachFromCut:0.00}m of tree over a "
                        + $"{TreePitWidth:0.00}m pit, landing {TreePitWestEdge - landsAtX:0.00}m past the far lip.");

            return trunk;
        }

        // The trunk's half-width at a height, taken off the mesh that is actually there. Used for the
        // notch depth, the heartwood radius, the stump's collider and the bridge deck - all of which
        // were magic numbers once and all of which have to move together when the tree is rescaled.
        private static float TrunkHalfWidthAt(Transform frame, GameObject instance, float y,
                                              float band = 0.06f)
        {
            float best = 0f;
            foreach (MeshFilter mf in instance.GetComponentsInChildren<MeshFilter>(true))
            {
                if (mf.sharedMesh == null || !mf.sharedMesh.isReadable) continue;
                Matrix4x4 toFrame = frame.worldToLocalMatrix * mf.transform.localToWorldMatrix;
                foreach (Vector3 v in mf.sharedMesh.vertices)
                {
                    Vector3 p = toFrame.MultiplyPoint3x4(v);
                    if (Mathf.Abs(p.y - y) > band) continue;
                    best = Mathf.Max(best, new Vector2(p.x, p.z).magnitude);
                }
            }
            return best > 0.01f ? best : 0.7f;
        }

        // ONE STAGE OF THE NOTCH: a copy of the trunk with a wedge of wood genuinely gone.
        //
        // Only the mesh the notch passes through is copied - the crown and the branches are metres
        // away and would be `TreeNotchStages` wasted duplicates of the heaviest meshes in the scene.
        private static GameObject BuildNotchStage(Transform frame, Transform parent, MeshFilter chosen,
                                                  string name, float westFace, float depth,
                                                  float cutY, bool? keepAbove, Material cutMat)
        {
            GameObject stage = new GameObject(name);
            stage.transform.SetParent(parent, false);
            if (chosen == null) return stage;

            Matrix4x4 toFrame = frame.worldToLocalMatrix * chosen.transform.localToWorldMatrix;
            Mesh cut = CarveNotch(chosen.sharedMesh, toFrame, westFace, depth, cutY, keepAbove);
            if (cut == null) return stage;

            // The stage sits in the SAME pose as the mesh it copies, so the carved mesh lands exactly
            // on top of the whole one it replaces.
            stage.transform.SetPositionAndRotation(chosen.transform.position, chosen.transform.rotation);
            stage.transform.localScale = chosen.transform.lossyScale;

            stage.AddComponent<MeshFilter>().sharedMesh = SaveGeneratedMesh(
                $"tree_notch_{name}_{depth:0.000}".Replace(' ', '_'), () => cut);
            stage.AddComponent<MeshRenderer>().sharedMaterial =
                cutMat != null ? cutMat : chosen.GetComponent<MeshRenderer>().sharedMaterial;
            stage.SetActive(false);
            return stage;
        }

        // A SHRUNKEN COPY OF THE TRUNK over one band of its height, so a cut into the trunk has
        // something behind it. See the call site for why this shape and not a primitive.
        //
        // Shrunk in X and Z about the band's own centroid and NOT in Y, so it keeps the trunk's
        // taper and lean and simply sits inside the bark.
        private static void BuildTrunkFill(Transform frame, Transform parent, MeshFilter chosen,
                                           string name, float fromY, float toY, float shrink,
                                           Material mat)
        {
            if (chosen == null || chosen.sharedMesh == null) return;

            Matrix4x4 toFrame = frame.worldToLocalMatrix * chosen.transform.localToWorldMatrix;
            Mesh band = FilterTriangles(chosen.sharedMesh, (a, b, c) =>
            {
                float y = toFrame.MultiplyPoint3x4((a + b + c) / 3f).y;
                return y >= fromY && y <= toY;
            });
            if (band == null) return;

            // The centroid is taken in the FRAME the shrink has to happen in, then carried back into
            // the mesh's own space - the model is authored Z-up and its local axes are not the room's.
            Matrix4x4 fromFrameM = toFrame.inverse;
            Vector3[] verts = band.vertices;
            Vector3 centre = Vector3.zero;
            for (int i = 0; i < verts.Length; i++) centre += toFrame.MultiplyPoint3x4(verts[i]);
            centre /= Mathf.Max(1, verts.Length);

            for (int i = 0; i < verts.Length; i++)
            {
                Vector3 p = toFrame.MultiplyPoint3x4(verts[i]);
                p.x = centre.x + (p.x - centre.x) * shrink;
                p.z = centre.z + (p.z - centre.z) * shrink;
                verts[i] = fromFrameM.MultiplyPoint3x4(p);
            }
            band.vertices = verts;
            band.RecalculateNormals();
            band.RecalculateBounds();

            GameObject go = new GameObject(name);
            go.transform.SetParent(parent, true);
            go.transform.SetPositionAndRotation(chosen.transform.position, chosen.transform.rotation);
            go.transform.localScale = chosen.transform.lossyScale;
            go.AddComponent<MeshFilter>().sharedMesh = SaveGeneratedMesh(
                $"tree_fill_{name}_{fromY:0.00}".Replace(' ', '_'), () => band);
            go.AddComponent<MeshRenderer>().sharedMaterial =
                mat != null ? mat : chosen.GetComponent<MeshRenderer>().sharedMaterial;
        }

        // The mesh the cut passes through - the trunk, found by which mesh's middle is nearest the
        // cut height rather than by name, because the name is the exporter's business.
        private static MeshFilter TrunkMeshOf(Transform frame, GameObject instance, float cutY)
        {
            MeshFilter best = null;
            float nearest = float.MaxValue;
            foreach (MeshFilter mf in instance.GetComponentsInChildren<MeshFilter>(true))
            {
                if (mf.sharedMesh == null || !mf.sharedMesh.isReadable) continue;
                Matrix4x4 m = frame.worldToLocalMatrix * mf.transform.localToWorldMatrix;
                float dy = Mathf.Abs(m.MultiplyPoint3x4(mf.sharedMesh.bounds.center).y - cutY);
                if (dy < nearest) { nearest = dy; best = mf; }
            }
            return best;
        }

        // The trunk minus a horizontal V, and minus everything on the wrong side of the cut plane.
        //
        // The V is widest where the axe lands and closes at its apex `depth` in, which is the shape a
        // real notch has and the reason it reads as deepening rather than as a slot: as the apex
        // travels in, the OPENING gets taller as well as deeper.
        // `keepAbove` NULL means keep both sides - one unbroken trunk with a bite out of it, which
        // is what the tree looks like for every chop but the last. Only the felled pair asks for a
        // side, and only because it has genuinely come apart by then.
        private static Mesh CarveNotch(Mesh src, Matrix4x4 toFrame, float westFace, float depth,
                                       float cutY, bool? keepAbove)
        {
            return FilterTriangles(src, (a, b, c) =>
            {
                Vector3 p = toFrame.MultiplyPoint3x4((a + b + c) / 3f);
                if (keepAbove.HasValue && (p.y >= cutY) != keepAbove.Value) return false;

                float into = p.x - westFace;                       // 0 at the bark, growing inward
                if (into < 0f || into > depth) return true;        // outside the wedge's reach
                float opening = (depth - into) * TreeNotchHalfAngleTan;   // the V, closing at its apex
                return Mathf.Abs(p.y - cutY) > opening;
            });
        }

        // Keeps the triangles a predicate accepts, remapping the vertices it actually uses.
        //
        // THE REMAP IS NOT AN OPTIMISATION. Carrying the whole vertex array over was tried first and
        // is wrong in a way nothing renders: `RecalculateBounds` measures EVERY vertex, referenced or
        // not, so each half came back claiming the whole tree's bounds - never culled, and unable to
        // answer whether the cut had happened at all.
        private static Mesh FilterTriangles(Mesh src, System.Func<Vector3, Vector3, Vector3, bool> keep)
        {
            Vector3[] verts = src.vertices;
            Vector3[] normals = src.normals;
            Vector2[] uvs = src.uv;
            Vector4[] tangents = src.tangents;
            int[] tris = src.triangles;

            bool hasNormals = normals != null && normals.Length == verts.Length;
            bool hasUvs = uvs != null && uvs.Length == verts.Length;
            bool hasTangents = tangents != null && tangents.Length == verts.Length;

            var remap = new System.Collections.Generic.Dictionary<int, int>();
            var newVerts = new System.Collections.Generic.List<Vector3>();
            var newNormals = new System.Collections.Generic.List<Vector3>();
            var newUvs = new System.Collections.Generic.List<Vector2>();
            var newTangents = new System.Collections.Generic.List<Vector4>();
            var kept = new System.Collections.Generic.List<int>(tris.Length);

            for (int i = 0; i < tris.Length; i += 3)
            {
                if (!keep(verts[tris[i]], verts[tris[i + 1]], verts[tris[i + 2]])) continue;
                for (int c = 0; c < 3; c++)
                {
                    int old = tris[i + c];
                    if (!remap.TryGetValue(old, out int fresh))
                    {
                        fresh = newVerts.Count;
                        remap[old] = fresh;
                        newVerts.Add(verts[old]);
                        if (hasNormals) newNormals.Add(normals[old]);
                        if (hasUvs) newUvs.Add(uvs[old]);
                        if (hasTangents) newTangents.Add(tangents[old]);
                    }
                    kept.Add(fresh);
                }
            }

            if (kept.Count == 0) return null;

            Mesh mesh = new Mesh();
            mesh.indexFormat = UnityEngine.Rendering.IndexFormat.UInt32;
            mesh.SetVertices(newVerts);
            if (hasNormals) mesh.SetNormals(newNormals);
            if (hasUvs) mesh.SetUVs(0, newUvs);
            if (hasTangents) mesh.SetTangents(newTangents);
            mesh.SetTriangles(kept, 0);
            mesh.RecalculateBounds();
            return mesh;
        }

        // Replaces every mesh under `instance` with just the half of it on one side of `cutY`,
        // measured in `frame`'s space. A mesh with nothing left is switched off rather than left as
        // an empty renderer.
        private static void SplitTreeMeshes(Transform frame, GameObject instance, float cutY,
                                            bool keepAbove, string tag)
        {
            foreach (MeshFilter mf in instance.GetComponentsInChildren<MeshFilter>())
            {
                Mesh src = mf.sharedMesh;
                if (src == null) continue;
                if (!src.isReadable)
                {
                    Debug.LogError($"[SceneBuilder] {src.name} is not readable - the tree cannot be cut.");
                    continue;
                }

                Matrix4x4 toFrame = frame.worldToLocalMatrix * mf.transform.localToWorldMatrix;
                Mesh built = FilterTriangles(src, (a, b, c) =>
                    (toFrame.MultiplyPoint3x4((a + b + c) / 3f).y >= cutY) == keepAbove);

                if (built == null)
                {
                    mf.gameObject.SetActive(false);
                    continue;
                }

                // THE CUT HEIGHT IS IN THE ASSET NAME on purpose. `SaveGeneratedMesh` serves a second
                // call from the asset the first one wrote, so without it a changed TreeCutHeight
                // would silently keep building the old cut.
                mf.sharedMesh = SaveGeneratedMesh(
                    $"tree_{tag}_{src.name}_{cutY:0.000}".Replace(' ', '_'), () => built);
            }
        }

        // ONE OF FIVE, and five is what makes this room's accumulation possible at all - see
        // ItemRegistry on an id naming a SUPPLY. Each axe still obeys the one-object rule and
        // returns to its own origin; what is forbidden is two holders of one axe, never five axes
        // of one id.
        private static CarryableItem BuildFireAxe(Transform parent, string name, Vector3 localPosition,
                                                  float yaw)
        {
            // A real fire axe. The model is already authored at 0.817m, so this is barely a
            // correction - but it is here rather than assumed, because a different axe would need it.
            const float wantedLength = 0.90f;

            GameObject root = new GameObject(name);
            root.transform.SetParent(parent, false);

            GameObject source = AssetDatabase.LoadAssetAtPath<GameObject>($"{ToolsDir}/fire_axe.glb");
            GameObject model = (GameObject)PrefabUtility.InstantiatePrefab(source, root.transform);
            model.name = "Visual";
            model.transform.localPosition = Vector3.zero;

            Bounds raw = ModelBounds(root.transform, model);
            float longest = Mathf.Max(raw.size.x, Mathf.Max(raw.size.y, raw.size.z));
            float modelScale = wantedLength / Mathf.Max(0.0001f, longest);
            model.transform.localScale = Vector3.one * modelScale;

            Vector3 size = raw.size * modelScale;
            model.transform.localPosition = new Vector3(
                -raw.center.x * modelScale, -raw.min.y * modelScale, -raw.center.z * modelScale);

            BoxCollider reach = root.AddComponent<BoxCollider>();
            reach.isTrigger = true;
            reach.center = new Vector3(0f, size.y / 2f, 0f);
            reach.size = size + new Vector3(0.35f, 0.35f, 0.35f);

            GameObject solid = new GameObject("Blocker");
            solid.transform.SetParent(root.transform, false);
            BoxCollider block = solid.AddComponent<BoxCollider>();
            block.center = new Vector3(0f, size.y / 2f, 0f);
            block.size = size;

            CarryableItem item = root.AddComponent<CarryableItem>();
            item.blocker = block;
            item.itemId = CycleTwoToolItemId;
            item.displayName = "FIRE AXE";
            item.icon = AxeIcon();
            item.floorY = 0f;
            item.handLocalPosition = HandPoseFor(wantedLength);
            item.handLocalScale = Vector3.one;
            // Three of the five are knocked over, and without this putting one down restored the
            // pose it was BUILT in - see the buckets, which found this first.
            item.restsUpright = true;
            item.audioSource = MakeSource(root.transform, "PickupAudio", 1f, 0.85f);
            item.pickupClip = LoadClip(SfxDir, "sfx_item_pickup");
            MakeWeighable(item, WeightAxe);

            root.transform.localPosition = localPosition;
            root.transform.localRotation = Quaternion.Euler(0f, yaw, 0f);
            return item;
        }

        // AN AXE, AND THE POINT IS THAT IT IS NOT A HAMMER.
        //
        // Two things separate the shapes at icon size, and neither is detail:
        //   - **SYMMETRY.** A hammer's head sits centred on its haft; an axe's hangs off ONE SIDE.
        //   - **THE EDGE IS A CURVE.** A blade is a crescent - convex where it cuts, and swept back
        //     to a point at each end. A straight-ended block is a mallet however it is attached.
        //
        // Built in the AXE'S OWN FRAME - `along` up the haft, `side` across it - so the shape is
        // described once and the 45-degree lie of it is a rotation applied to the samples. The first
        // version stacked rectangles to fake the flare, which is what left it reading as a block.
        private static Sprite AxeIcon()
        {
            var icon = new IconCanvas(128);
            Vector2 mid = new Vector2(0.5f, 0.5f);
            const float turn = 45f * Mathf.Deg2Rad;
            float cos = Mathf.Cos(turn), sin = Mathf.Sin(turn);

            // World point -> axe frame. x is across the haft (the blade hangs at +x), y is up it.
            System.Func<Vector2, Vector2> local = pt =>
            {
                Vector2 d = pt - mid;
                return new Vector2(d.x * cos + d.y * sin, -d.x * sin + d.y * cos);
            };
            // ...and back, for placing things by hand in the axe's own terms.
            System.Func<float, float, Vector2> world = (x, y) =>
                mid + new Vector2(x * cos - y * sin, x * sin + y * cos);

            // THE HAFT, with a swell at the butt - the knob that stops a hand sliding off is most of
            // what says "handle" at this size.
            icon.Capsule(world(0f, -0.375f), world(0f, 0.255f), 0.042f);
            icon.Disc(world(0f, -0.395f), 0.062f);

            // THE HEAD. Everything to one side of the haft:
            //   - the EYE, the block the haft passes through, squared off;
            //   - the BIT, flaring out and ending in a convex edge struck from a centre well behind
            //     it, which is what gives the curve its shallow, weapon-like sweep;
            //   - the BEARD, a bite taken out under the bit where a real axe is cut away.
            icon.Shape(pt =>
            {
                Vector2 l = local(pt);
                if (l.x < -0.055f) return false;

                // The eye: a short block around the haft.
                bool eye = l.x <= 0.075f && l.y >= 0.115f && l.y <= 0.315f;

                // The bit: half-height grows with reach, so it flares.
                float reach = Mathf.InverseLerp(0.055f, 0.315f, l.x);
                float half = Mathf.Lerp(0.105f, 0.185f, reach);
                bool bit = l.x >= 0.055f
                        && Mathf.Abs(l.y - 0.215f) <= half
                        // The cutting edge, convex: struck from a long way back so the arc is shallow.
                        && (l - new Vector2(-0.42f, 0.215f)).sqrMagnitude <= 0.735f * 0.735f;

                return eye || bit;
            });

            // The beard, cut out: the underside of the bit is hollowed where it meets the haft.
            icon.Disc(world(0.105f, 0.010f), 0.115f, -1f);
            return SaveSprite(icon, "icon_axe");
        }


        // THE MACHINE THE RING IS BUILT AROUND.
        //
        // A sealed casing the player never enters, seen only through four windows. Inset from the
        // rooms' inner faces rather than flush with them, which does two things: it avoids two
        // coplanar walls fighting over the same plane, and it leaves a shallow chamber so the core
        // reads as a thing standing in a shaft rather than as a solid block of building.
        //
        // Deliberately plain at this stage. What the core DOES - clamps releasing, an axle turning,
        // shards pushed out through hatches - belongs with the puzzles that drive it, and a casing
        // that already moved would be machinery with nothing operating it.
        // Returns the AXLE, not the casing - the axle is the only part anything else drives.
        private static Transform BuildCore(Transform parent, Vector3 centre, float span, Material propMat)
        {
            GameObject core = new GameObject("Core");
            core.transform.SetParent(parent, false);
            core.transform.localPosition = centre;

            Material casing = MakeColorMaterial("CoreCasing", new Color(0.17f, 0.18f, 0.21f));
            SetSmoothness(casing, 0.55f);

            // Solid, and the only thing between the player and the core's insides.
            Prim(PrimitiveType.Cube, "Casing", core.transform,
                new Vector3(0f, RoomHeight / 2f, 0f),
                new Vector3(span, RoomHeight, span), casing);

            // Something to look at through the glass: a lit column standing in the casing's mouth on
            // each of the four window faces. Emissive rather than lit, so it reads through glass in a
            // room whose own lights are behind the viewer.
            // THE AXLE, which is what room4's ratchet turns. The rotors hang off it rather than off
            // the casing, so eight notches of cranking is eight visible eighths of a turn seen
            // through four different windows - the core reacting rather than a number going up.
            GameObject axle = new GameObject("CoreAxle");
            axle.transform.SetParent(core.transform, false);

            Material glow = MakeEmissiveMaterial("CoreGlow", new Color(0.45f, 0.75f, 1f), 2.6f);
            float face = span / 2f;
            var faces = new[]
            {
                new Vector3( face, 0f, 0f), new Vector3(-face, 0f, 0f),
                new Vector3(0f, 0f,  face), new Vector3(0f, 0f, -face),
            };
            for (int i = 0; i < faces.Length; i++)
            {
                Vector3 inward = -faces[i].normalized * 0.28f;
                Prim(PrimitiveType.Cylinder, $"CoreRotor_{i}", axle.transform,
                    faces[i] + inward + Vector3.up * (GridCellHeight * 2f),
                    new Vector3(0.55f, GridCellHeight * 0.9f, 0.55f), glow, removeCollider: true);
            }

            return axle.transform;
        }

        // Returns `rooms` in ring order - room1 first, room0 last - because room0's console needs
        // things that do not exist yet when the shell is built: this cycle's wall panels are gathered
        // FROM the shell, and the shaker and the hand belong to the player, who is built later.
        // Handing the transforms back and finishing room0 at the call site is what keeps that
        // ordering honest rather than shuffling half of `Build` around it.
        private static (Transform root, Transform bedSpawn, ParticleSystem[] gas,
                        Door[] doors, RoomCondition[] conditions, GhostInteractable[] signals,
                        Transform[] rooms, Transform[] loweredRooms,
                        FinalRoomSequence finalRoom, CycleExit wayOut)
            BuildCycleTwoShell(
            Material floorMat, Material grooveMat, Material panelMat, Material propMat,
            Transform ghostParent)
        {
            GameObject root = new GameObject("Room_Cycle2");
            // TURNED ROUND ABOUT THE BED. See CycleTwoYaw for why. The pivot is folded into the
            // position - a child at local z maps to world `2 * CycleTwoFirstRoomZ - z`, so the bed
            // room at local `CycleTwoFirstRoomZ` lands on itself and stays under the exit shaft
            // while every other room swings out past the end of cycle 1.
            root.transform.position = new Vector3(0f, -StoreyDrop, 2f * CycleTwoFirstRoomZ);
            root.transform.rotation = CycleTwoYaw;

            Rect doorway = new Rect(-DoorWidth / 2f, 0f, DoorWidth, DoorHeight);

            // THE RING. Eight rooms around the perimeter of a 3x3 block with the core in the middle,
            // turning WEST three times - at room3, room5 and room7, which are its corners.
            //
            // Room1 keeps the position it already had, so the drop from `room1-0` lands exactly where
            // it did. Everything else is walked out from there: `RoomPitch` along a leg, `CornerPitch`
            // across a turn, and a quarter turn of yaw at each corner.
            //
            // **Only four rooms share a wall with the core** - 2, 4, 6 and 0, the mid-leg ones. The
            // corners touch it diagonally and cannot see in at all. That is not a limitation to work
            // around; it is the rhythm the layout hands over for free: one glass room and one corner
            // room per leg.
            float ringZ = CycleTwoFirstRoomZ;

            Transform r1 = BuildRingRoom(root.transform, "Room2_1", 0f, ringZ, 0f,
                floorMat, grooveMat, panelMat, doorway, Rect.zero, Rect.zero, CycleExitHoleFromBelow);
            Transform r2 = BuildRingRoom(root.transform, "Room2_2", 0f, ringZ - RoomPitch, 0f,
                floorMat, grooveMat, panelMat, doorway, doorway, Rect.zero);
            // ~~r3, r4 and r5~~ MERGED 2026-08-16 into one space, `BuildTreeHall`. They were already
            // a straight line along this leg, so the ring's shape is unchanged and both neighbours -
            // r2 through the bay's north wall, r6 through the run's - meet exactly the walls they
            // always met. The hall is built further down, once `fixtureMat` exists.
            float legTwoZ = ringZ - 2f * RoomPitch;

            // LEG 3 MOVED NORTH BY 0.875m, which is the whole price of the hall being one width.
            //
            // It used to sit at `legTwoZ + CornerPitch`, the corner spacing between a room presenting
            // its width and one presenting its depth. That put r6's doorway in a wall 0.875m south of
            // r2's, and a hall joining both had to step between the two - the step the soffit covered.
            // Putting r6 on the SAME Z as r2 lets one straight wall carry both openings, and a corner
            // room is free to sit wherever its own door needs it to.
            // LEG 3 IS GONE, 2026-08-19 by request: the old room2-6, room2-7 and room2-0 are deleted
            // and the SLIDE'S LANDING ROOM is room2-6 now, with the weighing room behind it as room2-7
            // and the console room as room2-0. The walk is room2-1, room2-2, the tree hall - and then
            // down the chute into the pool, which is a way on that no door provides.
            //
            // The two numbers survive because the CORE is still measured off them (below): the shaft
            // in the middle is placed by the four legs' inner faces, and leg 3's is still where the
            // building's west side is even with no rooms standing on it.
            float legThreeX = -CornerPitch - RoomPitch;
            float legThreeZ = ringZ - RoomPitch;                 // 43.4, level with r2

            // TWO SHELLS AND A HALL. The hall is not in this list because it is not a shell - it
            // builds its own floor, walls, lights and probes at two different ceiling heights - and
            // neither are room2-6, room2-7 and room2-0, which are built with the hall (the slide has
            // to be measured against room2-6's floor) and light and probe themselves for the same
            // reason.
            var rooms = new[] { r1, r2 };
            var names = new[] { "Room2_1", "Room2_2" };

            // THE WINDOWS ARE GONE, with the puzzles that looked through them. They were built as
            // translucent panes at 0.94 smoothness, and in a lit white room that reads as a MIRROR
            // rather than as a window - which is what play reported. The casing stays: the ring is
            // still wrapped around something, and cutting a window back in is one Rect.
            const float coreInset = 0.15f;
            // MEASURED OFF THE FOUR LEGS' INNER FACES, not derived from a pitch. The pitch formula it
            // replaces happened to agree while every leg sat at its corner spacing; leg 3 has moved
            // (above), and a formula that no longer describes the building is worse than no formula.
            float coreEastFace = -RoomWidth / 2f;                  // leg 1's west wall
            float coreWestFace = legThreeX + RoomWidth / 2f;       // leg 3's east wall
            float coreSouthFace = legTwoZ + TreeHallNorthFace;     // the hall's north wall
            float coreNorthFace = legThreeZ + RoomPitch - RoomWidth / 2f;   // leg 4's south wall
            float coreSpan = Mathf.Min(coreEastFace - coreWestFace,
                                       coreNorthFace - coreSouthFace) - 2f * coreInset;
            Vector3 coreCentre = new Vector3((coreEastFace + coreWestFace) / 2f, 0f,
                                             (coreNorthFace + coreSouthFace) / 2f);
            BuildCore(root.transform, coreCentre, coreSpan, propMat);

            // THE DOORS, each built under the room it leaves FROM and set in that room's exit wall.
            // Straight joins use the south wall (yaw 180 from the builder's default north); the three
            // corners use the west wall (yaw 270) and the room's narrower half-extent.
            // FIVE, NOT SEVEN. Door2_3, Door2_4 and Door2_5 were the joins between the three rooms
            // the hall absorbed; two of those joins no longer exist and the third - the way out onto
            // r6 - is built by `BuildTreeHall` itself, in the same wall at the same x, because the
            // door has to be positioned along a 21m wall rather than at a room's centre.
            var ringDoors = new Door[2];
            ringDoors[0] = BuildPadDoor(r1, "Door2_1", 0f, new FloorButton[0], propMat, yaw: 180f);
            ringDoors[1] = BuildPadDoor(r2, "Door2_2", 0f, new FloorButton[0], propMat, yaw: 180f);

            // EVERY DOOR WHOSE ROOM HAS NO PUZZLE YET STANDS OPEN, and this flag is the to-do list kept
            // in the scene - it comes off as each room is designed. Door2_1 is the one that has come
            // off: its room is the four light switches, and it hangs on that condition instead.
            //
            // WITHOUT THIS THE RING IS NOT WALKABLE. A door with no condition, no pads and no flag asks
            // `FloorButton.AllActive` of an empty array, which deliberately refuses - so it never opens
            // and cycle 2 dead-ends at room2-2. That is the right default for a MIS-WIRED door and the
            // wrong one for a door whose room simply has not been built, which is exactly why the two
            // are different facts and this one is said out loud.
            // BOTH DOORS THE RING STILL HAS HANG ON A PUZZLE, so nothing is flagged here any more -
            // Door2_1 on the four switches, Door2_2 on the tank, both set below. The flag stays in
            // `Door` because it is the to-do list kept in the scene and the next unfinished room will
            // want it again.
            ringDoors[1].openUntilPuzzled = true;

            // One pocket per join, all uncapped: every one has a room through it.
            BuildDoorPocketFill(r1, "Pocket2_1", 0f, grooveMat, capFarSide: false, yaw: 180f);
            BuildDoorPocketFill(r2, "Pocket2_2", 0f, grooveMat, capFarSide: false, yaw: 180f);

            Material fixtureMat = MakeEmissiveMaterial("CeilingFixtureCycle2", Color.white, 3.5f);
            Light[] room1Lights = null;
            Renderer[] room1Panels = null;
            for (int i = 0; i < rooms.Length; i++)
            {
                (Light[] lights, Renderer[] panels) =
                    BuildCeilingLights(rooms[i], names[i], 0f, fixtureMat, castShadows: true);
                if (i == 0) { room1Lights = lights; room1Panels = panels; }
                BuildReflectionProbe(rooms[i], names[i], 0f);
            }

            // THE TREE HALL, on this leg where r3, r4 and r5 used to be. It lights and probes itself
            // - see BuildTreeHall - which is why it sits outside the loop above rather than in it.
            (Transform hall, TreeTrunk treeTrunk, TreeFelled treeFelled,
             Transform poolRoom, Door poolDoor, PoolDrain poolDrain, Valve[] poolValves,
             Transform weighRoom, WeighScale weighScale,
             Transform breakRoom, FinalRoomSequence breakSequence, CycleExit cycleTwoExit) =
                BuildTreeHall(root.transform, legTwoZ, floorMat, grooveMat, panelMat, propMat,
                              fixtureMat);

            // ROOM2-1'S PUZZLE: four switches scattered on its sealed walls, each wired to one of
            // the four ceiling fixtures just built. All four dark at rest - see AllLightsOn for why
            // this reads as latched without the condition itself remembering anything, and
            // LightSwitch for why a flip is an event a ghost replays once rather than a level.
            // Dark through a SHARED material rather than `renderer.material`, which instantiates a
            // copy per panel at build time and leaves four orphans in the scene file - Unity says so
            // in a warning. The lit material is the one every other room's fixtures already wear, so
            // a switch coming on simply hands the panel back to it.
            Material fixtureOffMat = MakeEmissiveMaterial("CeilingFixtureCycle2Off", Color.white, 0f);
            foreach (Light l in room1Lights) l.enabled = false;
            foreach (Renderer p in room1Panels) p.sharedMaterial = fixtureOffMat;

            // THE HEIGHT WAS PLACED BY HAND IN THE EDITOR AND READ BACK, which is why it is not round.
            // 1.2m is a light switch's real height and read as low and easy to miss in a dark room.
            //
            // THE SPREAD IS UNCHANGED, deliberately. Moving one switch out to 2.617 while placing it
            // said nothing about wanting all four moved - only the height was being judged.
            const float switchHeight = 1.851f;
            const float switchSpread = 1.8f;
            const float switchInset = RoomWidth / 2f;
            var lightSwitches = new LightSwitch[4];
            lightSwitches[0] = BuildLightSwitch(r1, "LightSwitch2_1_A",
                new Vector3(-switchInset, switchHeight, -switchSpread), 90f, room1Lights[0], room1Panels[0],
                fixtureMat, fixtureOffMat);
            lightSwitches[1] = BuildLightSwitch(r1, "LightSwitch2_1_B",
                new Vector3(-switchInset, switchHeight, switchSpread), 90f, room1Lights[1], room1Panels[1],
                fixtureMat, fixtureOffMat);
            lightSwitches[2] = BuildLightSwitch(r1, "LightSwitch2_1_C",
                new Vector3(switchInset, switchHeight, -switchSpread), -90f, room1Lights[2], room1Panels[2],
                fixtureMat, fixtureOffMat);
            lightSwitches[3] = BuildLightSwitch(r1, "LightSwitch2_1_D",
                new Vector3(switchInset, switchHeight, switchSpread), -90f, room1Lights[3], room1Panels[3],
                fixtureMat, fixtureOffMat);

            GameObject allLightsGO = new GameObject("AllLightsOn2_1");
            allLightsGO.transform.SetParent(r1, false);
            AllLightsOn allLightsOn = allLightsGO.AddComponent<AllLightsOn>();
            allLightsOn.switches = lightSwitches;

            // THE ROOM IS NOT DIMMED, and a `RoomDimmer` that multiplied every surface down was tried
            // and REMOVED on 2026-08-15. Recorded because the idea is an obvious one to have again.
            //
            // The problem it aimed at is real: this building is lit almost entirely by ambient standing
            // in for the bounce URP does not compute, ambient reaches every surface in the scene
            // equally, and so switching four fixtures off leaves the room only slightly less lit.
            //
            // Multiplying the surfaces down does not fix that, it breaks something else. These walls
            // read as white PAINT because of how brightly and evenly they are lit; take that away and
            // they stop looking like the same building with its lights off and start looking like a
            // different, darker material. Play called it at 0.16 and again at 0.38 - the second was
            // "about one light on", and it still read as wrong rather than as dark.
            //
            // If the room genuinely has to go dark later, the fix is in the LIGHTING rather than in the
            // surfaces: lower the global ambient and give the fixtures back the difference, which keeps
            // lit rooms looking as they do now and lets an unlit one actually fall away. That is a
            // change to numbers cycle 1 is tuned around, so it is not a small one.
            // Door2_1 is ringDoors[0] - the south door r1 built above, the only way out of this room.
            ringDoors[0].condition = allLightsOn;

            // ROOM2-2'S TAPS. Not gating anything yet - see BuildWaterTap.
            WaterTap[] taps = BuildWaterTap(r2);

            // THE TANK, AND THE DOOR IT OPENS. Room2-2 is no longer a room you walk through.
            WaterTank tank = BuildWaterTank(r2, propMat);

            // A STAND UNDER EACH TAP, and four buckets to run between them and the tank. The stands
            // are placed where each tap's water actually lands, so "put the bucket under the tap"
            // means the thing it looks like.
            // Both placed by hand in the Editor and read back off the scene, which is why neither is a
            // round number: they sit exactly where each tap's water lands.
            // ONE PER WALL, each 1.151m in front of its own wall face - the reach measured off the
            // west mixer by hand, mirrored rather than re-eyeballed because the fixture is identical
            // on all four and so is the fall.
            BuildBucketStand(r2, "Stand_Wall", taps[0], new Vector3(-3.160f, 0f, -1.600f));
            BuildBucketStand(r2, "Stand_South", taps[1], new Vector3(2.500f, 0f, -4.035f));
            BuildBucketStand(r2, "Stand_East", taps[2], new Vector3(3.160f, 0f, 1.600f));
            BuildBucketStand(r2, "Stand_North", taps[3], new Vector3(-2.400f, 0f, 4.035f));

            // FOUR, which is the tank's four bucketloads - so the room can in principle be finished
            // in one pass if there were four pairs of hands, and cannot be with one. They share an id,
            // which ItemRegistry has supported since the pin drawer: an id can name a SUPPLY, and each
            // instance still obeys the one-object rule and returns to its own origin (CLAUDE.md §1.2).
            //
            // SCATTERED, AND TWO OF THEM KNOCKED OVER. Four buckets in a row is equipment issued to the
            // player; four lying about is a room somebody left in a hurry, which is the one this game
            // is set in. The positions dodge the tank, both stands and both doorways - a bucket in a
            // doorway is the first thing a player kicks and the last thing they find again.
            BuildBucket(r2, "Bucket_0", new Vector3(-2.70f, 0f, 2.95f), yaw: 34f, tipDegrees: 0f);
            BuildBucket(r2, "Bucket_1", new Vector3(1.85f, 0f, 3.55f), yaw: -68f, tipDegrees: 90f);
            // MOVED OUT OF THE NEW EAST STAND, which landed 0.53m from where this one used to lie -
            // close enough that the tray and the pail overlapped. A bucket sitting inside the spot it
            // is supposed to be carried TO is the one arrangement this room must not ship with.
            BuildBucket(r2, "Bucket_2", new Vector3(3.60f, 0f, 3.30f), yaw: 12f, tipDegrees: 0f);
            BuildBucket(r2, "Bucket_3", new Vector3(-3.45f, 0f, 0.85f), yaw: 121f, tipDegrees: 78f);
            // Door2_2 is ringDoors[1] - the way out of room2-2 - and its `openUntilPuzzled` comes off here,
            // which is what that flag is for: it is the to-do list kept in the scene, and a room with a
            // puzzle in it must not stand open.
            ringDoors[1].openUntilPuzzled = false;
            ringDoors[1].condition = tank;


            // THE BEDSIDE, LAID OUT EXACTLY AS CYCLE 1'S IS - same numbers, same builder calls.
            //
            // It was not, and the reason is the cycle turning round: `CycleTwoYaw` puts 180 degrees on
            // the whole cycle, so the same call that reads "bed against this wall" in cycle 1 came out
            // mirrored here - headboard the other way, chest on the other side. The two rooms are the
            // same room in the fiction and every iteration opens in one of them, so having them differ
            // is the kind of wrong that is felt without being noticed.
            //
            // A WRAPPER THAT CANCELS THE CYCLE'S TURN is what fixes it, rather than mirrored numbers.
            // Inside `BedFrame` the net rotation is identity again, so cycle 1's figures can be used
            // verbatim below and stay correct if the cycle's yaw ever changes.
            GameObject bedFrame = new GameObject("Room2_1_Bedside");
            bedFrame.transform.SetParent(r1, false);
            bedFrame.transform.localRotation = Quaternion.Inverse(CycleTwoYaw);

            // `zCentre` is a WORLD z, because `PlaceModel` measures world bounds - and r1's world z is
            // its local one, since the cycle's rotation pivots on this very room.
            (_, Transform spawn) = BuildBed(bedFrame.transform, propMat,
                                            floorY: -StoreyDrop, zCentre: ringZ, yaw: 0f);

            // ~~BuildNightstand~~ REPLACED 2026-08-15 by the chest of drawers, which is what this
            // bedside was asked for in the first place. The nightstand brought THREE pins with it and
            // cycle 2 has nothing to use a pin on.
            //
            // AND IT IS NO LONGER EMPTY, 2026-08-19: nine billiard balls across the two trays, which
            // are room2-0's keys. That is why the chest was built with two OPENING bays rather than
            // one and a shelf - see BuildDresser - and why both were wired as `GhostInteractable`s
            // from the first build, before there was anything to open them for.
            //
            // Cycle 1's own nightstand position, unchanged, now that the frame above makes it mean
            // the same thing here.
            Drawer[] dresserDrawers = BuildDresser(bedFrame.transform, "Dresser2_1",
                new Vector3(-0.95f, 0f, 1.35f), yaw: 0f, withLamp: true, withBilliards: true);

            // The last couple of metres up to each opening, from inside the room. Short on purpose:
            // see AssertWalkable for why this is not a path across the room.
            float outZ = RoomDepth / 2f - 0.7f, outX = RoomWidth / 2f - 0.7f;
            Vector3 nIn = new Vector3(0f, 0f, outZ - 2.2f), nOut = new Vector3(0f, 0f, outZ);
            Vector3 sIn = new Vector3(0f, 0f, -outZ + 2.2f), sOut = new Vector3(0f, 0f, -outZ);
            Vector3 wIn = new Vector3(-outX + 2.2f, 0f, 0f), wOut = new Vector3(-outX, 0f, 0f);

            AssertWalkable(rooms[0], "room2-1 south door", sIn, sOut);
            AssertWalkable(rooms[1], "room2-2 north door", nIn, nOut);
            AssertWalkable(rooms[1], "room2-2 south door", sIn, sOut);
            // ROOM2-6 IS ENTERED BY FALLING INTO IT, so there is no approach to walk. What is checked
            // instead is the way OUT: from the middle of the pool to its door, which is the walk the
            // drain has to leave possible.
            AssertWalkable(poolRoom, "room2-6 south door", sIn, sOut);
            AssertWalkable(weighRoom, "room2-7 north door", nIn, nOut);
            AssertWalkable(weighRoom, "room2-7 south door", sIn, sOut);
            AssertWalkable(breakRoom, "room2-0 north door", nIn, nOut);

            // THE HALL'S OWN CHECKS, in its own frame rather than a room's: both openings are in
            // the north wall now, one at x=0 and one at x=-20.825, twenty metres apart.
            //
            // THE THIRD IS THE POINT, and it is the only assert in this project that expects its walk
            // to FAIL: the near ledge to the far ledge, straight across the pit. If that ever comes
            // back walkable, the hole is not a hole and the tree is decoration.
            float hallOut = TreeHallNorthFace - 0.7f;
            AssertWalkable(hall, "tree hall entrance",
                new Vector3(TreeHallEntranceX, 0f, hallOut - 2.2f),
                new Vector3(TreeHallEntranceX, 0f, hallOut));
            AssertWalkable(hall, "tree hall exit",
                new Vector3(TreeHallExitX, 0f, hallOut - 2.2f),
                new Vector3(TreeHallExitX, 0f, hallOut));
            AssertNotWalkable(hall, "tree hall pit",
                new Vector3(TreePitEastEdge - 0.6f, 0f, 0f),
                new Vector3(TreePitWestEdge + 0.6f, 0f, 0f));

            ParticleSystem[] gas = BuildGasEmitters(r1, "Room2_1_Gas", 0f);

            // WHAT A GHOST CAN OPERATE IN CYCLE 2: room2-1's four switches at bits 0-3, room2-2's
            // FOUR taps at 4-7, and the tank's pour point at 8. **APPEND ONLY, NEVER REORDER** - an
            // entry's index IS its bit in RecordedFrame.signals, so moving one changes what every
            // recorded frame means.
            //
            // The two new taps are appended INSIDE the tap array (BuildWaterTap returns them last),
            // which keeps the original pair on bits 4 and 5. The pour point does shift from 6 to 8,
            // and that is safe for the reason the rule is really about: a timeline is runtime-only and
            // nothing serialises one, so a REBUILD has no surviving recordings to invalidate. What the
            // rule forbids is mutating the array while ghosts born against it are alive.
            //
            // The taps matter more than the switches here. A tap is the first thing in this game that
            // a past self can leave RUNNING while you are elsewhere, which is the only way anything
            // that takes longer than sixty seconds ever gets done.
            //
            // The pour is a signal for a reason that took a while to see: it is the only thing a past
            // self does in this room that hands nothing over, so no carry event describes it, and
            // without a bit of its own the tank could only ever be filled by the living player - see
            // PourPoint.
            var cycleTwoSignalList = new System.Collections.Generic.List<GhostInteractable>(lightSwitches);
            cycleTwoSignalList.AddRange(taps);
            if (tank.pourPoint != null) cycleTwoSignalList.Add(tank.pourPoint);
            // Room2-3's two drawers, at 9 and 10. Wired BEFORE anything is in them, deliberately: a
            // drawer with something in it that a past self cannot open is a room that quietly needs
            // the living player for an errand the loop was supposed to absorb, and appending a bit
            // later is the one change this array makes awkward.
            cycleTwoSignalList.AddRange(dresserDrawers);
            // THE TREE, at bit 11 - ONE bit for any number of choppers. Each ghost carries its own
            // timeline, so "this past self was swinging at this moment" is per-ghost already; the
            // bit says only that, and whether the swing lands is asked of that ghost's own hands at
            // replay (TreeTrunk.SetGhostSignal). Five simultaneous axes cost one bit, not five.
            if (treeTrunk != null) cycleTwoSignalList.Add(treeTrunk);
            // ROOM2-6'S THREE VALVES, at 12, 13 and 14. One bit each rather than one for the room,
            // because they are three separate things a past self can be doing - and the whole design
            // of that room is that six turns is more than one pair of hands fits in a minute, so a
            // ghost standing at the far wheel IS the solution. Appended, like everything else here.
            if (poolValves != null) cycleTwoSignalList.AddRange(poolValves);

            // The hall's exit joins the ring's four here rather than being wired separately: `Cycle`
            // shuts every door it is handed at the top of an iteration, and one left out of the list
            // is one that stays open into the next.
            //
            // IN WALK ORDER, which is what makes the LAST one the door into room0 - the one
            // `BuildFinalRoom` seals at the break. Appending the hall's exit on the end instead would
            // have been silently wrong there, and it is not the kind of wrong that shows up until
            // somebody finishes the cycle.
            // ROOM2-7'S DOOR, ONTO ROOM2-8. **NOT capped** - there is a room through it, and
            // `capFarSide` puts a solid wall across the pocket, which is exactly how room2-7 came to
            // be invisible behind room2-6's door for a build. The flag is a statement about where the
            // WALK ENDS, and the walk ends at room2-0 now - the room that breaks the cycle.
            Door weighDoor = BuildPadDoor(weighRoom, "Door2_7", 0f, new FloorButton[0], propMat,
                                          yaw: 180f);
            weighDoor.condition = weighScale;
            BuildDoorPocketFill(weighRoom, "Pocket2_7", 0f, grooveMat, capFarSide: false, yaw: 180f);

            // FOUR DOORS. The hall's own exit is gone with leg 3 - the tree opens no door, it opens
            // the only bridge across the pit (see BuildTreeHall) - and room2-7's is the LAST, which
            // makes it the one room2-0 seals at the break. That ordering is load-bearing and silently
            // so: `Cycle` shuts every door it is handed, and the break shuts this one in the player's
            // view. Appending anything after it would put the wrong door on that line.
            var doors = new[] { ringDoors[0], ringDoors[1], poolDoor, weighDoor };

            // ROOM2-0'S TWO REFERENCES BACK UP THE WALK, wired here because the room is built with
            // the hall and the door it hangs on is built with the ring. The trigger sits on room2-0's
            // own threshold and only counts a player who came through an OPEN door - so walking up to
            // a shut one arms nothing, and the scale is what opens it.
            if (breakSequence != null)
            {
                breakSequence.doorBehind = weighDoor;
                if (breakSequence.arrival != null) breakSequence.arrival.door = weighDoor;
            }

            // AND THE NEW ROOMS ARE IN THE ROOM LIST, appended rather than built into it: the loop
            // above lights and probes the shells, and these three did both for themselves when the
            // hall built them.
            var allRooms = new[] { r1, r2, poolRoom, weighRoom, breakRoom };

            // THE THREE HUNG A FURTHER STOREY DOWN. Named here, where the names still mean something,
            // rather than found by string at the far end: `AssembleCycleTwo` sets one floor base over
            // the whole cycle and these three do not share it - their floors are `SlideRoomFloorY`
            // below the rest of it, because the slide has to arrive somewhere lower than it leaves.
            var loweredRooms = new[] { poolRoom, weighRoom, breakRoom };

            return (root.transform, spawn, gas, doors,
                    new RoomCondition[] { allLightsOn, tank, treeFelled, poolDrain, weighScale },
                    cycleTwoSignalList.ToArray(), allRooms, loweredRooms, breakSequence,
                    cycleTwoExit);
        }

        // WHAT A RETRACTED PLINTH RETRACTS INTO.
        //
        // Every `RewardPlinth` is authored raised and sunk by `riseHeight` in Awake, so when it is
        // down it sits about a metre BELOW the floor. That was invisible for as long as there was
        // nothing under the floor to see it from. With a storey below, room1-0's console hangs a
        // metre out of room2-1's ceiling - the reported "cycle 1's structures are visible in cycle
        // 2's ceiling".
        //
        // Five sides, open at the top, so the plinth still rises straight out of it. From above
        // nothing changes: the floor slab is opaque and the housing is under it. From below it reads
        // as building services, which is what a retracting plinth would actually need.
        //
        // Only built where a room exists underneath. The other three plinths - Room3's, the cube
        // room's, and the chess reward - sink into nothing today, and will want this when cycle 2
        // grows rooms beneath them.
        private static void BuildPlinthHousing(Transform parent, string name, Vector3 centreXZ,
                                               float footprintX, float footprintZ, float depth, Material mat)
        {
            GameObject well = new GameObject(name);
            well.transform.SetParent(parent, false);
            // Hung from the underside of the floor slab, which is where its open top belongs.
            well.transform.localPosition = new Vector3(centreXZ.x, -WallThickness, centreXZ.z);

            float halfX = footprintX / 2f, halfZ = footprintZ / 2f;

            Prim(PrimitiveType.Cube, "Bottom", well.transform,
                new Vector3(0f, -depth - WallThickness / 2f, 0f),
                new Vector3(footprintX + 2f * WallThickness, WallThickness, footprintZ + 2f * WallThickness), mat);

            Prim(PrimitiveType.Cube, "Side_West", well.transform,
                new Vector3(-halfX - WallThickness / 2f, -depth / 2f, 0f),
                new Vector3(WallThickness, depth, footprintZ + 2f * WallThickness), mat);
            Prim(PrimitiveType.Cube, "Side_East", well.transform,
                new Vector3(halfX + WallThickness / 2f, -depth / 2f, 0f),
                new Vector3(WallThickness, depth, footprintZ + 2f * WallThickness), mat);
            Prim(PrimitiveType.Cube, "Side_South", well.transform,
                new Vector3(0f, -depth / 2f, -halfZ - WallThickness / 2f),
                new Vector3(footprintX, depth, WallThickness), mat);
            Prim(PrimitiveType.Cube, "Side_North", well.transform,
                new Vector3(0f, -depth / 2f, halfZ + WallThickness / 2f),
                new Vector3(footprintX, depth, WallThickness), mat);
        }

        // A SOFT ROUND BLOB, which is the whole of what a vapour particle needs to be. Generated
        // like every other texture here rather than sourced.
        //
        // The falloff is squared rather than linear: a linear ramp gives a disc with a visible rim,
        // and what has to be invisible is the EDGE of the sprite - a hundred overlapping billboards
        // only read as one cloud if none of them has a boundary you can find.
        private static Texture2D MakeSoftBlobTexture(string name, int size)
        {
            Color[] px = new Color[size * size];
            float half = size / 2f;

            for (int y = 0; y < size; y++)
            {
                for (int x = 0; x < size; x++)
                {
                    float dx = (x + 0.5f - half) / half;
                    float dy = (y + 0.5f - half) / half;
                    float d = Mathf.Sqrt(dx * dx + dy * dy);
                    float a = Mathf.Clamp01(1f - d);
                    a *= a;
                    px[y * size + x] = new Color(1f, 1f, 1f, a);
                }
            }

            return WriteTexture(name, size, size, px, TextureWrapMode.Clamp, FilterMode.Bilinear);
        }

        // WHERE THE GAS COMES FROM: the top of every wall, all four sides, nowhere to stand that is
        // not under one.
        //
        // PARTICLES, after two simpler attempts failed for the same reason. A lit slot along each
        // wall left four near-black strips in a white room permanently, in exchange for a moment; a
        // translucent box that grew downward left a zero-height quad at the wall head that still
        // caught a specular highlight. Both were trying to fake a volume with a surface, and a
        // surface always has an edge you can find.
        //
        // What makes this read as vapour rather than as sprites is the NOISE module - without it a
        // hundred soft blobs drifting on straight lines look exactly like a hundred soft blobs. The
        // damping is the other half: the gas decelerates as it comes off the wall, so it pours in
        // and then hangs, which is what a heavier-than-air gas does in a sealed room.
        private static ParticleSystem[] BuildGasEmitters(Transform parent, string name, float roomCenterZ)
        {
            GameObject root = new GameObject(name);
            root.transform.SetParent(parent, false);
            root.transform.localPosition = new Vector3(0f, 0f, roomCenterZ);

            Texture2D blob = MakeSoftBlobTexture("GasBlob", 128);
            Material gasMat = MakeParticleMaterial("GasVapour", blob);

            float y = RoomHeight - 0.25f;
            float halfX = RoomWidth / 2f;
            float halfZ = RoomDepth / 2f;

            // Position, the direction it blows, and how wide the emitter slot is along the wall.
            var walls = new (Vector3 at, Vector3 inward, float run)[]
            {
                (new Vector3(0f, y, -halfZ + 0.3f), Vector3.forward, RoomWidth * 0.8f),
                (new Vector3(0f, y,  halfZ - 0.3f), Vector3.back,    RoomWidth * 0.8f),
                (new Vector3(-halfX + 0.3f, y, 0f), Vector3.right,   RoomDepth * 0.8f),
                (new Vector3( halfX - 0.3f, y, 0f), Vector3.left,    RoomDepth * 0.8f),
            };

            var systems = new System.Collections.Generic.List<ParticleSystem>();

            for (int i = 0; i < walls.Length; i++)
            {
                GameObject go = new GameObject($"GasEmitter_{i}");
                go.transform.SetParent(root.transform, false);
                go.transform.localPosition = walls[i].at;
                // Aimed inward AND down. Gas coming straight off a wall reads as a fan; this is a
                // vent in a ceiling corner, so it should already be falling as it arrives.
                go.transform.localRotation = Quaternion.LookRotation(
                    (walls[i].inward + Vector3.down * 0.7f).normalized, Vector3.up);

                ParticleSystem ps = go.AddComponent<ParticleSystem>();
                ConfigureGasEmitter(ps, walls[i].run, gasMat);
                systems.Add(ps);
            }

            return systems.ToArray();
        }

        private static void ConfigureGasEmitter(ParticleSystem ps, float run, Material mat)
        {
            // Stopped, and stopped from the start: the room is not being gassed until it is.
            ParticleSystem.MainModule main = ps.main;
            main.playOnAwake = false;
            main.loop = true;
            main.duration = 12f;
            // LONG-LIVED and SLOW. Vapour that clears in two seconds is a puff of smoke; this has to
            // still be in the air while the player goes down on top of it.
            main.startLifetime = new ParticleSystem.MinMaxCurve(7f, 11f);
            main.startSpeed = new ParticleSystem.MinMaxCurve(0.22f, 0.55f);
            main.startSize = new ParticleSystem.MinMaxCurve(1.7f, 3.4f);
            main.startRotation = new ParticleSystem.MinMaxCurve(0f, Mathf.PI * 2f);
            // Very low alpha per particle. The cloud is built out of overlap, not out of any one
            // billboard being visible - which is what stops it looking like sprites.
            main.startColor = new Color(0.95f, 0.965f, 0.98f, 0.085f);
            // Barely heavier than air. Enough that it settles rather than hangs at head height.
            main.gravityModifier = 0.014f;
            // WORLD, or the whole cloud would drag along with anything that moved the emitter.
            main.simulationSpace = ParticleSystemSimulationSpace.World;
            main.maxParticles = 260;

            ParticleSystem.EmissionModule emission = ps.emission;
            emission.rateOverTime = 13f;

            // A slot along the wall rather than a point, so it arrives as a sheet.
            ParticleSystem.ShapeModule shape = ps.shape;
            shape.enabled = true;
            shape.shapeType = ParticleSystemShapeType.Box;
            shape.scale = new Vector3(run, 0.25f, 0.15f);
            shape.randomDirectionAmount = 0.12f;

            // It pours in and then hangs. Without the damping it crosses the room and piles up
            // against the far wall, which is a wind tunnel rather than a room filling.
            ParticleSystem.LimitVelocityOverLifetimeModule limit = ps.limitVelocityOverLifetime;
            limit.enabled = true;
            limit.dampen = 0.055f;
            limit.limit = new ParticleSystem.MinMaxCurve(0.5f);

            // THE ONE THAT MAKES IT VAPOUR. Straight-line blobs read as sprites however soft they
            // are; a slow large-scale wobble reads as something moving through air.
            ParticleSystem.NoiseModule noise = ps.noise;
            noise.enabled = true;
            noise.strength = new ParticleSystem.MinMaxCurve(0.55f);
            noise.frequency = 0.17f;
            noise.scrollSpeed = new ParticleSystem.MinMaxCurve(0.09f);
            noise.damping = true;
            noise.quality = ParticleSystemNoiseQuality.High;

            // Fade in over the first fifth, hold, fade out over the last third - so nothing ever
            // appears or vanishes, which is the other half of not looking like sprites.
            ParticleSystem.ColorOverLifetimeModule colour = ps.colorOverLifetime;
            colour.enabled = true;
            var gradient = new Gradient();
            gradient.SetKeys(
                new[] { new GradientColorKey(Color.white, 0f), new GradientColorKey(Color.white, 1f) },
                new[]
                {
                    new GradientAlphaKey(0f, 0f),
                    new GradientAlphaKey(1f, 0.22f),
                    new GradientAlphaKey(0.85f, 0.62f),
                    new GradientAlphaKey(0f, 1f),
                });
            colour.color = new ParticleSystem.MinMaxGradient(gradient);

            // Spreading as it goes, which is what a gas does and what hides the billboard edges.
            ParticleSystem.SizeOverLifetimeModule size = ps.sizeOverLifetime;
            size.enabled = true;
            var grow = new AnimationCurve();
            grow.AddKey(0f, 0.55f);
            grow.AddKey(1f, 1.45f);
            size.size = new ParticleSystem.MinMaxCurve(1f, grow);

            ParticleSystem.RotationOverLifetimeModule spin = ps.rotationOverLifetime;
            spin.enabled = true;
            spin.z = new ParticleSystem.MinMaxCurve(-0.25f, 0.25f);

            var psr = ps.GetComponent<ParticleSystemRenderer>();
            psr.renderMode = ParticleSystemRenderMode.Billboard;
            psr.alignment = ParticleSystemRenderSpace.View;
            psr.sharedMaterial = mat;
            psr.sortMode = ParticleSystemSortMode.Distance;
            // Nothing this soft should be casting or catching a shadow.
            psr.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
            psr.receiveShadows = false;
        }

        // A FLAT DECAL: an unlit, alpha-blended quad for something drawn ON a surface - the digits
        // scrawled on the wall and the readouts lying on the pads.
        //
        // Unlit rather than Lit, and that is the point rather than a saving. Ink on a wall has no
        // shading of its own; a Lit decal picks up the ceiling fixtures and reads as a sticker with a
        // sheen. It also sidesteps the trap that produced a black band along the wall head, where a
        // Lit transparent material kept its specular at zero alpha.
        //
        // Deliberately NOT the particle material next door, which is the same idea for a different
        // renderer: URP's particle shaders expect vertex streams a MeshRenderer does not supply.
        private static Material MakeDecalMaterial(string name, Texture2D map, Color tint)
        {
            string path = $"{MaterialsDir}/{name}.mat";
            Shader shader = Shader.Find("Universal Render Pipeline/Unlit");

            Material mat = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (mat == null)
            {
                mat = new Material(shader);
                AssetDatabase.CreateAsset(mat, path);
            }
            mat.shader = shader;
            mat.SetTexture("_BaseMap", map);
            mat.mainTexture = map;
            mat.SetColor("_BaseColor", tint);
            mat.color = tint;

            mat.SetFloat("_Surface", 1f);
            mat.SetFloat("_Blend", 0f);
            mat.SetFloat("_ZWrite", 0f);
            mat.SetInt("_SrcBlend", (int)UnityEngine.Rendering.BlendMode.SrcAlpha);
            mat.SetInt("_DstBlend", (int)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);
            mat.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");
            mat.DisableKeyword("_ALPHAPREMULTIPLY_ON");
            mat.renderQueue = (int)UnityEngine.Rendering.RenderQueue.Transparent;

            EditorUtility.SetDirty(mat);
            return mat;
        }

        // Unlit and alpha-blended, NOT premultiplied. The translucent Lit material this replaces
        // preserved specular at zero alpha, which is exactly how an invisible box ended up as a
        // visible band along the wall head - see BuildGasEmitters. Unlit has no specular to preserve.
        private static Material MakeParticleMaterial(string name, Texture2D map)
        {
            string path = $"{MaterialsDir}/{name}.mat";
            Shader shader = Shader.Find("Universal Render Pipeline/Particles/Unlit");
            if (shader == null) shader = Shader.Find("Universal Render Pipeline/Unlit");

            Material mat = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (mat == null)
            {
                mat = new Material(shader);
                AssetDatabase.CreateAsset(mat, path);
            }
            mat.shader = shader;
            mat.SetTexture("_BaseMap", map);
            mat.mainTexture = map;
            mat.SetColor("_BaseColor", Color.white);

            mat.SetFloat("_Surface", 1f);
            mat.SetFloat("_Blend", 0f);
            mat.SetFloat("_ZWrite", 0f);
            mat.SetInt("_SrcBlend", (int)UnityEngine.Rendering.BlendMode.SrcAlpha);
            mat.SetInt("_DstBlend", (int)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);
            mat.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");
            mat.DisableKeyword("_ALPHAPREMULTIPLY_ON");
            mat.renderQueue = (int)UnityEngine.Rendering.RenderQueue.Transparent;

            EditorUtility.SetDirty(mat);
            return mat;
        }

        // ROOM2-1'S PUZZLE: five digits scrawled on the south wall, and five counting pads standing
        // one grid cell out from it, one in front of each.
        //
        // WHY THE WALL AND NOT A SIGN. The digits go on the panel grid itself, in the second row up -
        // reachable height, where somebody standing in this room would have written them. The grid is
        // what makes "one digit per cell, in order" legible without a single line of instruction: the
        // wall is already divided into five columns and the answer is one per column.
        //
        // WHY ONE CELL OUT. A pad hard against the wall would be read as part of the wall; a cell's
        // gap makes the pairing an arrangement in the room rather than a label. It is also far enough
        // that the digit above is still in view while standing on the pad, which matters because the
        // player will be counting.
        // WHAT THE PLAYER FALLS THROUGH between the two storeys: a square tube joining the hole in
        // one cycle's floor to the hole in the next one's ceiling, across the service void.
        //
        // Without it the void is open to the room - you would drop out of the floor into a roof space
        // with the plinth housing and the underside of the slab on show. With it, the drop reads as
        // going down a shaft, and the void either side stays sealed.
        //
        // Four walls and no cap at either end, because both ends are the holes it exists to connect.
        private static void BuildExitShaft(Transform parent, string name, float roomCenterZ, Material mat)
        {
            GameObject shaft = new GameObject(name);
            shaft.transform.SetParent(parent, false);
            // Hung from the underside of the floor it starts at, running down the whole void.
            shaft.transform.localPosition = new Vector3(0f, -WallThickness, roomCenterZ + CycleExitZ);

            float half = GridCellWidth / 2f;
            float outer = GridCellWidth + 2f * WallThickness;

            Prim(PrimitiveType.Cube, "Shaft_West", shaft.transform,
                new Vector3(-half - WallThickness / 2f, -ServiceVoid / 2f, 0f),
                new Vector3(WallThickness, ServiceVoid, outer), mat);
            Prim(PrimitiveType.Cube, "Shaft_East", shaft.transform,
                new Vector3(half + WallThickness / 2f, -ServiceVoid / 2f, 0f),
                new Vector3(WallThickness, ServiceVoid, outer), mat);
            Prim(PrimitiveType.Cube, "Shaft_South", shaft.transform,
                new Vector3(0f, -ServiceVoid / 2f, -half - WallThickness / 2f),
                new Vector3(GridCellWidth, ServiceVoid, WallThickness), mat);
            Prim(PrimitiveType.Cube, "Shaft_North", shaft.transform,
                new Vector3(0f, -ServiceVoid / 2f, half + WallThickness / 2f),
                new Vector3(GridCellWidth, ServiceVoid, WallThickness), mat);
        }

        // The lid over that hole: a slab of floor that slides aside when the console is full.
        //
        // Slides sideways INTO the surrounding floor slab, which is solid, so it is out of sight the
        // moment it is open - the same thing a door slab does inside its pocket, without needing a
        // pocket built for it. Authored closed, so the room can be looked at in the editor as the
        // player first meets it.
        private static CycleExit BuildCycleExit(Transform parent, float roomCenterZ, Material floorMat, Transform player)
        {
            GameObject go = new GameObject("CycleExit");
            go.transform.SetParent(parent, false);
            // At the floor plane of the room it belongs to, which is what `throughDrop` is measured
            // from - "the player has fallen well below the floor they were standing on".
            go.transform.localPosition = new Vector3(0f, 0f, roomCenterZ + CycleExitZ);

            // BOTH LIDS ARE FLUSH WITH THE SURFACE THEY FILL, and both retract into the service
            // void - the floor one drops as it slides, the ceiling one rises.
            //
            // The first version recessed each by 10mm to dodge a coplanar-face z-fight against the
            // slab it slid into. That worked and left a 10mm hatch outline in the ceiling of the room
            // below, lit differently from everything round it - which is exactly what a lid is not
            // supposed to look like when it is shut. Retracting out of the slab instead means there
            // is nothing to be coplanar with, so the lid can fill its hole exactly.
            GameObject upper = Prim(PrimitiveType.Cube, "Cover_Floor", go.transform,
                new Vector3(0f, -WallThickness / 2f, 0f),
                new Vector3(GridCellWidth, WallThickness, GridCellWidth), floorMat);

            float ceilingMid = -(ServiceVoid + 1.5f * WallThickness);
            // THE CEILING LID TAKES THE CEILING'S MATERIAL, which stopped being the floor's on
            // 2026-08-20 when the two were split (albedo 0.85/smoothness 0.3 against 1.0/0). Left on
            // `floorMat` it is a darker, glossier square sitting in a matte white ceiling - play saw
            // it as a patch of the wrong colour, which is exactly what it was.
            GameObject lower = Prim(PrimitiveType.Cube, "Cover_Ceiling", go.transform,
                new Vector3(0f, ceilingMid, 0f),
                new Vector3(GridCellWidth, WallThickness, GridCellWidth), CeilingMaterial());

            CycleExit exit = go.AddComponent<CycleExit>();
            exit.covers = new[] { upper.transform, lower.transform };
            // Sideways by its own width so the hole is fully clear, and out of its own slab by rather
            // more than the slab is thick so neither lid can be seen edge-on through the opening.
            exit.openOffsets = new[]
            {
                new Vector3(GridCellWidth, -0.16f, 0f),
                new Vector3(GridCellWidth,  0.16f, 0f),
            };
            exit.player = player;
            exit.audioSource = MakeSource(go.transform, "ExitAudio", spatialBlend: 1f, volume: 0.9f);
            exit.openClip = LoadClip(SfxDir, "sfx_door_open");
            exit.sealClip = LoadClip(SfxDir, "sfx_power_down");
            return exit;
        }

        private static void BuildShell(Transform parent, Material floorMat, Material grooveMat, Material panelMat)
        {
            // The doorway is cut out of the panelling as an exact rectangle, so panels frame the
            // door instead of the door having to fit a whole number of cells.
            Rect doorway = new Rect(-DoorWidth / 2f, 0f, DoorWidth, DoorHeight);

            // Six rooms in a line, each sharing a divider with the next: a room's north wall and its
            // neighbour's south wall face each other across the door pocket, each with the same
            // doorway cut out of its panelling, its backing and its collision, so the opening is a
            // real hole. Room1 is the only one with no doorway to the south, and ROOM4 THE ONLY ONE
            // WITH NONE TO THE NORTH - it is the end of the building, and there is deliberately
            // nothing past it to look at or walk to.
            //
            // Room2West and Room2East used to be a pair of side rooms turned ninety degrees off
            // Room2's east and west walls. They are ON THE CHAIN now, the same shape and orientation
            // as every other room here, between Room2 and Room3 - see Build() for why: a hub with
            // three doors home to the same room read as a walk back and forth between them rather
            // than as progress, and the fix was to let the coloured doors BE the corridor instead of
            // branching off it.
            BuildRoomShell(parent, "Room1", 0f, floorMat, grooveMat, panelMat, Rect.zero, doorway);
            BuildRoomShell(parent, "Room2", RoomPitch, floorMat, grooveMat, panelMat, doorway, doorway);
            BuildRoomShell(parent, "Room2West", 2f * RoomPitch, floorMat, grooveMat, panelMat, doorway, doorway);
            BuildRoomShell(parent, "Room2East", 3f * RoomPitch, floorMat, grooveMat, panelMat, doorway, doorway);
            BuildRoomShell(parent, "Room3", 4f * RoomPitch, floorMat, grooveMat, panelMat, doorway, doorway);
            // Identical to the others in every way, and that is the point rather than a saving:
            // the room the player finally gets out into is the same white cell they have been in
            // for the whole run.
            //
            // EXCEPT FOR THE HOLE IN ITS FLOOR. `room1-0` is the hinge: it closes cycle 1 and opens
            // onto cycle 2, and the way on is a grid cell of floor behind the console that slides
            // aside once the console is full. Its north wall stays solid - there is still nothing past
            // the end of the building, the way out is DOWN.
            BuildRoomShell(parent, "Room4", 5f * RoomPitch, floorMat, grooveMat, panelMat, doorway, Rect.zero,
                floorHole: CycleExitHole);

            // One pocket per join, all UNCAPPED: every one of them has a room through it, and a cap
            // would be a wall across the only way to the next. Room4 needs no pocket of its own - its
            // north wall has no doorway cut in it, so there is no cavity there to close, the same
            // reason the calibration room has none.
            BuildDoorPocketFill(parent, "DoorPocketFill_1", 0f, grooveMat, capFarSide: false);
            BuildDoorPocketFill(parent, "DoorPocketFill_2", RoomPitch, grooveMat, capFarSide: false);
            BuildDoorPocketFill(parent, "DoorPocketFill_3", 2f * RoomPitch, grooveMat, capFarSide: false);
            BuildDoorPocketFill(parent, "DoorPocketFill_4", 3f * RoomPitch, grooveMat, capFarSide: false);
            BuildDoorPocketFill(parent, "DoorPocketFill_5", 4f * RoomPitch, grooveMat, capFarSide: false);

            // A sealed copy of the same shell, well clear of the chain, used for nothing but the
            // mouse-sensitivity step before iteration 1. Rect.zero for both cutouts, so it has no
            // doorways at all - the player is meant to look around it, not leave it, and there is
            // nothing to leave through.
            //
            // Empty on purpose: no bed, no pad, no door, no lamp. What is being judged is how fast
            // the room goes round, and furniture is something to look AT rather than something that
            // shows motion. The panelling does that better than any prop - it is a regular grid, so
            // the grooves sweeping past give the eye an unambiguous read on speed.
            //
            // Far enough out that no slab or wall overrun can touch Room1: this spans Z -26.95 to
            // -16.45 against Room1's -5.25 to 5.25.
            BuildRoomShell(parent, CalibrationRoomName, CalibrationRoomZ,
                floorMat, grooveMat, panelMat, Rect.zero, Rect.zero);

            Material fixtureMat = MakeEmissiveMaterial("CeilingFixture", Color.white, 3.5f);

            // Shadows only in Room1. Every additional light's shadow shares one atlas, and the
            // rooms past the first hold nothing that casts a shadow worth the map: Room2 is
            // balloons, Room3 is two floor pads.
            BuildCeilingLights(parent, "Room1", 0f, fixtureMat, castShadows: true);
            BuildCeilingLights(parent, "Room2", RoomPitch, fixtureMat, castShadows: true);
            // Room2West's fixtures are kept: the chess board dims them and brings them back up as
            // its reward, so something downstream needs the references rather than just the room.
            (Room2WestLights, Room2WestPanels) =
                BuildCeilingLights(parent, "Room2West", 2f * RoomPitch, fixtureMat, castShadows: true);
            BuildCeilingLights(parent, "Room2East", 3f * RoomPitch, fixtureMat, castShadows: true);
            BuildCeilingLights(parent, "Room3", 4f * RoomPitch, fixtureMat, castShadows: true);
            BuildCeilingLights(parent, "Room4", 5f * RoomPitch, fixtureMat, castShadows: true);
            (CalibrationLights, _) =
                BuildCeilingLights(parent, CalibrationRoomName, CalibrationRoomZ, fixtureMat, castShadows: true);

            // Built after the lights, so the probes capture the rooms already lit. The calibration
            // room needs its own: the walls are at 0.85 smoothness, and without a probe to reflect
            // they mirror the procedural sky and come out tinted blue.
            BuildReflectionProbe(parent, "Room1", 0f);
            BuildReflectionProbe(parent, "Room2", RoomPitch);
            BuildReflectionProbe(parent, "Room2West", 2f * RoomPitch);
            BuildReflectionProbe(parent, "Room2East", 3f * RoomPitch);
            BuildReflectionProbe(parent, "Room3", 4f * RoomPitch);
            BuildReflectionProbe(parent, "Room4", 5f * RoomPitch);
            BuildReflectionProbe(parent, CalibrationRoomName, CalibrationRoomZ);
        }

        // Fills the cavity between the two rooms' walls, everywhere except the volume the door slab
        // actually sweeps through.
        //
        // Left as one open pocket, that cavity ran the full width of the building and exited to the
        // sky at both ends - standing in the doorway and looking sideways showed a 0.1m x 5m slot
        // straight to the outside, which is the "you can see through between the walls" report.
        // Capping it also gives the opening a proper reveal instead of a hollow slot at the jamb.
        //
        // Rotated by yaw for a door in a side wall, for the same reason BuildDoorShell is: the pocket
        // geometry is identical, only its axis differs, and a second copy of it would be a second place
        // for the "you can see between the walls" bug to come back. wallHalfExtent is the wall's
        // distance from the room centre along the door's normal, crossHalfWidth how far the fill runs
        // along the wall.
        private static void BuildDoorPocketFill(Transform parent, string name, float roomCenterZ, Material mat,
                                                bool capFarSide,
                                                float wallHalfExtent = RoomDepth / 2f,
                                                float crossHalfWidth = RoomWidth / 2f + WallDepth,
                                                float yaw = 0f)
        {
            GameObject fill = new GameObject(name);
            fill.transform.SetParent(parent, false);
            // The room offset and the rotation both live on the root now, so the measurements below
            // are relative and read the same at any yaw.
            fill.transform.localPosition = new Vector3(0f, 0f, roomCenterZ);
            fill.transform.localRotation = Quaternion.Euler(0f, yaw, 0f);

            float pocketCenterZ = wallHalfExtent + WallDepth + DoorPocketDepth / 2f;

            // Matches the floor and ceiling slabs, so the fill reaches the outer face of the walls it
            // runs between and the divider is closed off at the same plane they are.
            float halfWidth = crossHalfWidth;
            Rect pocket = Rect.MinMaxRect(-halfWidth, 0f, halfWidth, RoomHeight);

            // The slab's full sweep: closed at -DoorWidth/2, open a further DoorWidth to the right.
            // The clearance keeps the fill's faces off the door's, which would otherwise be exactly
            // coincident planes.
            const float clearance = 0.01f;
            Rect doorSweep = Rect.MinMaxRect(
                -DoorWidth / 2f - clearance, 0f,
                DoorWidth / 2f + DoorWidth + clearance, DoorHeight + clearance);

            // No colliders: the walls either side of the doorway already carry the collision, and
            // the only way to reach this volume is through the opening the fill deliberately leaves.
            int piece = 0;
            foreach (Rect part in SubtractRect(pocket, doorSweep))
            {
                if (part.width <= 0.001f || part.height <= 0.001f) continue;

                Prim(PrimitiveType.Cube, $"Fill_{piece++}", fill.transform,
                    new Vector3(part.center.x, part.center.y, pocketCenterZ),
                    new Vector3(part.width, part.height, DoorPocketDepth),
                    mat, removeCollider: true);
            }

            // Seals the far mouth of the pocket where there is no next room to close it. Without
            // this the doorway is a hole to the outside once the door slides clear - the same
            // failure the pocket fill exists to stop, just at the other end of the building. It
            // KEEPS its collider: this is the end of the world for now, and the player must not be
            // able to walk out through the door they just unlocked.
            if (!capFarSide) return;

            Prim(PrimitiveType.Cube, "FarCap", fill.transform,
                new Vector3(0f, RoomHeight / 2f, pocketCenterZ + DoorPocketDepth / 2f + WallThickness / 2f),
                new Vector3(halfWidth * 2f, RoomHeight, WallThickness),
                mat);
        }

        // westCutout/eastCutout default to none and nothing in the chain uses them any more -
        // Room2West and Room2East were the one thing that did, back when they were side rooms turned
        // ninety degrees off Room2's walls. Left on `BuildPanelWall`, which has always taken a cutout
        // in wall-local coordinates and been indifferent to which axis the wall runs along, on the
        // reasoning that a wall with a doorway in an unusual side is cheap to keep able and expensive
        // to re-derive the day something needs it again.
        // floorHole / ceilingHole: a rectangle in ROOM-LOCAL XZ (x across the room, y of the Rect being
        // Z relative to zCenter) to leave out of that slab. Rect.zero means none, which is every room
        // but the two a cycle boundary passes through.
        //
        // The floor takes `floorMat` and the ceiling takes `CeilingMaterial()`, and the two are NOT
        // interchangeable: a floor is directly under the lights and a ceiling faces away from every
        // one of them, so the albedo that stops one clipping is the albedo that kills the other. A
        // pair of per-room overrides lived here for a day in 2026-08-20 while that was being settled;
        // the answer is in the two materials now, so a room does not get to disagree with it.
        private static void BuildRoomShell(Transform parent, string roomName, float zCenter, Material floorMat, Material grooveMat, Material panelMat, Rect southCutout, Rect northCutout, Rect westCutout = default, Rect eastCutout = default, Rect floorHole = default, Rect ceilingHole = default)
        {
            GameObject room = new GameObject(roomName);
            room.transform.SetParent(parent, false);
            Transform t = room.transform;

            float minX = -RoomWidth / 2f, maxX = RoomWidth / 2f;
            float minZ = zCenter - RoomDepth / 2f, maxZ = zCenter + RoomDepth / 2f;

            BuildSlab(t, "Floor", -WallThickness / 2f, zCenter, floorMat, floorHole);
            BuildSlab(t, "Ceiling", RoomHeight + WallThickness / 2f, zCenter, CeilingMaterial(), ceilingHole);

            BuildPanelWall(t, "Wall_South", new Vector3(0f, 0f, minZ), Vector3.right, Vector3.forward, RoomWidth, grooveMat, panelMat, southCutout);
            BuildPanelWall(t, "Wall_North", new Vector3(0f, 0f, maxZ), Vector3.right, Vector3.back, RoomWidth, grooveMat, panelMat, northCutout);
            BuildPanelWall(t, "Wall_West", new Vector3(minX, 0f, zCenter), Vector3.forward, Vector3.right, RoomDepth, grooveMat, panelMat, westCutout);
            BuildPanelWall(t, "Wall_East", new Vector3(maxX, 0f, zCenter), Vector3.forward, Vector3.left, RoomDepth, grooveMat, panelMat, eastCutout);
        }

        // A floor or a ceiling, with an optional hole in it.
        //
        // Slabs run the full room PITCH, not just the interior, so neighbouring rooms' floors meet
        // exactly under the divider. Sized to the interior they would leave an open gap in the doorway
        // threshold and the player would drop through it.
        //
        // THE HOLE REUSES `SubtractRect`, which is the whole reason a floor opening turned out to be
        // cheap. That function is pure Rect arithmetic - it has no idea its inputs are usually
        // along-a-wall and height - so handing it (x, z) instead cuts a floor exactly the way it cuts
        // panelling, collision and backing. Without a hole this emits one cube named `Floor` or
        // `Ceiling` exactly as before, which keeps every room that has no opening byte-identical.
        private static void BuildSlab(Transform t, string name, float yCenter, float zCenter, Material mat, Rect holeLocalXZ)
        {
            float halfX = RoomWidth / 2f + WallDepth;
            Rect slab = Rect.MinMaxRect(-halfX, zCenter - RoomPitch / 2f, halfX, zCenter + RoomPitch / 2f);

            // The hole arrives in room-local Z; the slab is in the room's own frame, where Z is
            // absolute. One offset reconciles them, and it is why the SAME Rect can be handed to two
            // rooms one storey apart and line up.
            Rect hole = holeLocalXZ.width > 0f && holeLocalXZ.height > 0f
                ? Rect.MinMaxRect(holeLocalXZ.xMin, zCenter + holeLocalXZ.yMin,
                                  holeLocalXZ.xMax, zCenter + holeLocalXZ.yMax)
                : new Rect();

            var parts = SubtractRect(slab, hole);

            if (parts.Count == 1)
            {
                Prim(PrimitiveType.Cube, name, t, new Vector3(0f, yCenter, zCenter),
                     new Vector3(slab.width, WallThickness, slab.height), mat);
                return;
            }

            for (int i = 0; i < parts.Count; i++)
            {
                Rect part = parts[i];
                Prim(PrimitiveType.Cube, $"{name}_{i + 1}", t,
                     new Vector3(part.center.x, yCenter, part.center.y),
                     new Vector3(part.width, WallThickness, part.height), mat);
            }
        }

        // Builds one wall as a recessed backing slab plus a grid of raised panels, so the seams are
        // actual grooves rather than a painted-on pattern.
        // faceCenterAtBase: the point on the finished panel surface at the wall's mid-width and floor level.
        // inward: unit normal pointing into the room.
        // cutout: a rectangle in wall-local (along-the-wall, height) coordinates to leave empty.
        // Rect.zero means none.
        // `wallHeight` defaults to `RoomHeight`, which is what every room in the game was until the
        // tree hall. It is a PARAMETER rather than a second constant because the height is a property
        // of the room being built, not of the building - see TreeHallHeight for the one room that
        // needs another value and why it cannot simply raise `RoomHeight` for everybody.
        // `panelHoles` opens the FACE only - the backing and the collision behind it stay whole. That
        // is a different thing from `cutout`, which is a hole all the way through and is what a doorway
        // is. Room3-2N's coloured steps need it: each one IS the wall panel at its cell, so the white
        // panel there must not exist - but the wall behind it must, or the room has a hole in it the
        // moment a step slides out.
        private static void BuildPanelWall(Transform parent, string name, Vector3 faceCenterAtBase, Vector3 rightDir, Vector3 inward, float wallWidth, Material backingMat, Material panelMat, Rect cutout, float wallHeight = RoomHeight, float baseHeight = 0f, Rect[] panelHoles = null)
        {
            Vector3 depthAxis = new Vector3(Mathf.Abs(inward.x), Mathf.Abs(inward.y), Mathf.Abs(inward.z));
            Vector3 widthAxis = new Vector3(Mathf.Abs(rightDir.x), Mathf.Abs(rightDir.y), Mathf.Abs(rightDir.z));

            // `baseHeight` lets a wall start ABOVE the floor, which is what a soffit is: the header
            // over the tree hall's mouth is a wall from 5.46m to 17.57m with open air beneath it.
            Rect wallRect = Rect.MinMaxRect(-wallWidth / 2f, baseHeight, wallWidth / 2f, wallHeight);

            // Backing and collision overrun both ends of the wall by its own depth, so adjacent
            // walls interpenetrate at the corners instead of merely abutting.
            //
            // Sized to the interior exactly, two perpendicular walls meet along a line and leave a
            // WallDepth-square column that neither one covers, running the full height of the room.
            // It never opens wide enough for a raycast to find - the void sits behind a zero-width
            // seam - but rendering two slabs that only touch produces pinhole cracks at the corner
            // from grazing angles. Note this is why thickening the walls would make it WORSE: the
            // void is WallDepth squared.
            //
            // The panel grid is left at the interior width, so the visible cell layout is unchanged
            // and the overrun is buried inside the adjacent wall.
            Rect structureRect = Rect.MinMaxRect(
                wallRect.xMin - WallDepth, wallRect.yMin, wallRect.xMax + WallDepth, wallRect.yMax);

            // The backing slab is cut by the same doorway rect as the panels. As one solid slab it
            // left the doorway a dead-end recess: you could walk through (collision was already
            // cut) but you were looking at wall.
            GameObject backing = new GameObject(name);
            backing.transform.SetParent(parent, false);
            int slab = 0;
            foreach (Rect part in SubtractRect(structureRect, cutout))
            {
                if (part.width <= 0.001f || part.height <= 0.001f) continue;

                Prim(PrimitiveType.Cube, $"Backing_{slab++}", backing.transform,
                    faceCenterAtBase + rightDir * part.center.x + Vector3.up * part.center.y
                        - inward * (GrooveDepth + WallThickness / 2f),
                    widthAxis * part.width + Vector3.up * part.height + depthAxis * WallThickness,
                    backingMat, removeCollider: true);
            }

            // Collision is built separately from invisible boxes rather than left on the backing,
            // for two reasons: the slab sits GrooveDepth too far back (the player would walk past
            // the panels and the camera's near plane would clip through the wall), and it has to be
            // cut around the doorway.
            GameObject collision = new GameObject(name + "_Collision");
            collision.transform.SetParent(parent, false);
            int solid = 0;
            foreach (Rect part in SubtractRect(structureRect, cutout))
            {
                if (part.width <= 0.001f || part.height <= 0.001f) continue;

                GameObject block = new GameObject($"Solid_{solid++}");
                block.transform.SetParent(collision.transform, false);
                block.transform.localPosition = faceCenterAtBase
                    + rightDir * part.center.x
                    + Vector3.up * part.center.y
                    - inward * (WallDepth / 2f);

                BoxCollider blockCollider = block.AddComponent<BoxCollider>();
                blockCollider.size = widthAxis * part.width + Vector3.up * part.height + depthAxis * WallDepth;
            }

            GameObject panels = new GameObject(name + "_Panels");
            panels.transform.SetParent(parent, false);

            float groove = GridLineThickness;
            // THE CELL WIDTH IS FITTED TO THE WALL, and this is the third version of it.
            //
            // Rounding the count and laying whole 1.75m cells left bare backing at the far end - a
            // black border down a 17.5m wall. Clamping the last cell instead covered the backing but
            // left a SLIVER panel against the corner, which play called out as a cut-off panel. Both
            // came from insisting the cell be exactly 1.75m on a wall that is not a multiple of it.
            //
            // So the count is rounded and the width divided out: the hall's 30.45m wall gets 17 cells
            // of 1.791m rather than 17 of 1.75 plus a 0.70m gap. Nobody can see 4cm; everybody can
            // see a sliver. **Every wall in cycle 1 is 8.75 or 10.5 across - 5 and 6 exact cells - so
            // this is arithmetically identical everywhere it was already exact.**
            int cols = Mathf.Max(1, Mathf.RoundToInt(wallWidth / GridCellWidth));
            float cellWidth = wallWidth / cols;

            int piece = 0;
            for (int col = 0; col < cols; col++)
            {
                float cellAlong = -wallWidth / 2f + col * cellWidth;
                float cellEnd = cellAlong + cellWidth;

                for (int row = 0; row * GridCellHeight < wallHeight - 0.001f; row++)
                {
                    // THE GRID STAYS ANCHORED TO THE FLOOR even when the wall does not start there,
                    // so a soffit's cells line up with the cells of the wall beneath it rather than
                    // restarting the rhythm at its own base. Rows entirely below `baseHeight` fall
                    // out through the zero-height check.
                    float bottom = Mathf.Max(row * GridCellHeight, baseHeight);
                    // The top row is a partial cell whenever the room height isn't a whole number
                    // of cells, so clamp it rather than letting panels poke through the ceiling.
                    float top = Mathf.Min(row * GridCellHeight + GridCellHeight, wallHeight);
                    if (top - bottom <= 0.001f) continue;

                    Rect panel = Rect.MinMaxRect(
                        cellAlong + groove / 2f, bottom + groove / 2f,
                        cellEnd - groove / 2f, top - groove / 2f);

                    foreach (Rect part in SubtractRects(SubtractRect(panel, cutout), panelHoles))
                    {
                        if (part.width <= 0.02f || part.height <= 0.02f) continue;

                        Vector3 pos = faceCenterAtBase
                            + rightDir * part.center.x
                            + Vector3.up * part.center.y
                            - inward * (GrooveDepth / 2f);
                        // **A CHAMFERED MESH, NOT A CUBE** - see `ChamferedPanelMesh` for what the
                        // rim buys and why it has to be built at true size rather than scaled.
                        // Collisionless either way: the backing slab behind these is what the player
                        // walks into, which is why the cube this replaces was made with
                        // `removeCollider: true`.
                        ChamferedPanel($"Panel_{piece++}", panels.transform, pos,
                                       part.width, part.height, GrooveDepth, inward, panelMat);
                    }
                }
            }
        }

        // The same subtraction applied over and over. Each hole is taken out of every piece the last
        // one left, so a wall face can carry any number of them - which is what a staircase made OF
        // wall panels needs, one hole per step.
        private static System.Collections.Generic.List<Rect> SubtractRects(
            System.Collections.Generic.List<Rect> parts, Rect[] holes)
        {
            if (holes == null || holes.Length == 0) return parts;

            foreach (Rect hole in holes)
            {
                var next = new System.Collections.Generic.List<Rect>();
                foreach (Rect part in parts) next.AddRange(SubtractRect(part, hole));
                parts = next;
            }
            return parts;
        }

        // Returns `panel` minus `hole` as up to four axis-aligned pieces (below, above, left,
        // right of the hole). Lets a doorway of any size be cut out of the panel grid without the
        // door having to line up with cell boundaries.
        private static System.Collections.Generic.List<Rect> SubtractRect(Rect panel, Rect hole)
        {
            var parts = new System.Collections.Generic.List<Rect>();

            bool overlaps = hole.width > 0f && hole.height > 0f && panel.Overlaps(hole);
            if (!overlaps)
            {
                parts.Add(panel);
                return parts;
            }

            float bandMin = Mathf.Max(panel.yMin, hole.yMin);
            float bandMax = Mathf.Min(panel.yMax, hole.yMax);

            if (hole.yMin > panel.yMin)
                parts.Add(Rect.MinMaxRect(panel.xMin, panel.yMin, panel.xMax, hole.yMin));
            if (hole.yMax < panel.yMax)
                parts.Add(Rect.MinMaxRect(panel.xMin, hole.yMax, panel.xMax, panel.yMax));
            if (hole.xMin > panel.xMin)
                parts.Add(Rect.MinMaxRect(panel.xMin, bandMin, hole.xMin, bandMax));
            if (hole.xMax < panel.xMax)
                parts.Add(Rect.MinMaxRect(hole.xMax, bandMin, panel.xMax, bandMax));

            return parts;
        }

        // floorY / zCentre are WORLD, and they have to be, which is the trap this signature exists to
        // close. `PlaceModel` measures the model's RENDERED bounds - which are world-space - and
        // corrects `localPosition` by the difference, so its `targetXZCenter` and `floorY` are world
        // heights whatever the parent is doing. Parenting a bed to a node carrying the room's offset
        // therefore does NOT move it: cycle 2's bed came out standing in Room1, on cycle 1's floor,
        // exactly where a bed asked for y=0 and z=0.7 belongs.
        //
        // The spawn point below is unaffected - it is placed with `localPosition` and inherits the
        // parent normally - which is why the player woke in the right room with no bed in it.
        // yaw turns the whole arrangement about the room centre - the bed, which end of the room it is
        // at, and which way the sleeper faces - rather than spinning the model on the spot. Cycle 2
        // uses 180 so its bed head is at the other end from cycle 1's.
        //
        // Applied as a SIGN on the layout rather than a rotation on the parent, because `PlaceModel`
        // corrects `localPosition` by a world-space delta: under a rotated parent that correction goes
        // in the wrong direction entirely. Anything placed with plain `localPosition` (the spawn point
        // here, the nightstand elsewhere) can use a rotated wrapper quite safely.
        // `xCentre`/`zCentre` are a WORLD position, because `PlaceModel` corrects a world-space
        // delta into a localPosition - so a caller whose room is not on the origin has to say where it
        // is. X was hard-coded to zero until 2026-08-20 and got away with it for two cycles, both of
        // which put their bed room on x=0; cycle 3's is twenty-one metres out, under room2-0, and the
        // bed would have been built in the middle of the tree hall's pit.
        private static (Transform bed, Transform spawn) BuildBed(Transform parent, Material mat,
                                                                 float floorY = 0f, float zCentre = 0f,
                                                                 float yaw = 0f, float xCentre = 0f)
        {
            // Combined bed + bedside table model, which replaces the old separate Kenney bed,
            // drawer, lamp and cup. It is authored Z-up in centimetres, hence the -90 X rotation
            // and the 0.01 scale - without those it arrives 100x too big and lying on its side.
            // Chosen for the rumpled, slept-in bedding: the loop opens every iteration by waking up
            // here, so the bed has to look like someone just got out of it. The alternatives were
            // all neatly made (or, in old_bed's case, a bare frame with no mattress at all).
            // -90 X uprights it (authored Z-up), then 180 Y turns the headboard toward the door.
            // Keep the glTF materials it ships with - they carry metallic/roughness maps that a
            // hand-rolled URP/Lit stand-in would drop.
            // +1 at yaw 0, -1 at yaw 180. Rounded, so it is exactly a sign rather than a float that
            // happens to be near one.
            float facing = Mathf.Round(Mathf.Cos(yaw * Mathf.Deg2Rad));

            (GameObject bed, _) = PlaceModel($"{FurnitureDir}/messy_bed.glb", parent, "Bed",
                new Vector3(xCentre, 0f, zCentre + 0.7f * facing), floorY, 0.00941f, addBoxCollider: true,
                rotation: Quaternion.Euler(-90f, 180f + yaw, 0f));

            // `xCentre`, NOT ZERO. This shifts the pillow in WORLD space (see UseSinglePillow), so a
            // hard zero centres it on the world origin rather than on its own bed - and cycle 3's bed
            // is twenty-one metres out, under room2-0. Play found it as "room3-1's bed has no pillow";
            // it had one, in the middle of the tree hall's pit.
            //
            // The same fault `BuildBed` itself carried until the same day, for the same reason: two
            // cycles' bed rooms both sat on x = 0, so a world X hard-coded to zero was accidentally
            // right twice.
            UseSinglePillow(bed, keepName: "Pillow_2", hideName: "Pillow_1", centreX: xCentre);

            // This model bakes contact shadows into its occlusion maps, which only looks right in
            // the exact pose it was authored in. Moving the pillow and removing its neighbour left
            // those shadows painted onto the bedding - a dark smear beside the pillow, and a hard
            // black band across the pillow itself. Switch baked occlusion off for both; the scene's
            // SSAO supplies real contact shadows that follow the geometry instead.
            DisableBakedOcclusion(bed, materialName: "Sheet", assetName: "BedSheet");
            DisableBakedOcclusion(bed, materialName: "Pillow_2", assetName: "BedPillow");

            // Hard against the foot of the bed, facing away from it down the room - you have just
            // got up, so the bed is behind you and the open floor is what you see.
            //
            // This sat at Z=-1.75 facing 180 (away from everything), which put the player 1.42m
            // past the foot of the bed with their back to it - so the wake-up sequence, which
            // poses the eye as if lying down and then sits you up, ended with the bed out of
            // frame entirely and you looking at the blank south wall. It never read as waking up
            // in the bed because you were nowhere near it.
            //
            // The player cannot be spawned *in* the bed: the model carries a full-volume
            // BoxCollider (Y 0..0.89) and the CharacterController would spawn interpenetrating it
            // and get shoved out on the first frame. The bed's foot is at Z=-0.33 and the
            // controller's radius is 0.3, so -0.7 is as close as it can stand without overlapping.
            // Keeping X=0 preserves the deliberate door/bed/spawn centre line.
            GameObject spawn = new GameObject("BedSpawnPoint");
            spawn.transform.SetParent(parent, false);
            spawn.transform.localPosition = new Vector3(0f, 0.05f, -0.7f * facing);
            spawn.transform.localRotation = Quaternion.Euler(0f, 180f + yaw, 0f);

            return (bed.transform, spawn.transform);
        }

        // The chess set in the red door's room, centred on its floor.
        //
        // The model is a SketchUp export by way of Collada, which is why it arrives at an odd import
        // scale with a 270 X rotation on its root and 218 separate renderers inside it. That count is
        // the thing to watch: it is the largest single object in the game by an order of magnitude, and
        // it sits in a room nothing can reach yet - so if the frame rate moves, this is the first
        // suspect.
        private static (CarryableItem[] pieces, ChessBoard board) BuildChessSet(
            Transform parent, Vector3 roomCentre, Vector3 doorwayInside, Material propMat,
            Light[] roomLights, Renderer[] roomPanels)
        {
            // addBoxCollider FALSE, unlike the bed and the nightstand. One box over the whole set would
            // be a 3.6m solid block, and a player who cannot walk up to the board cannot get their
            // capsule inside a piece's trigger - the pieces in the middle would be unreachable by E. The
            // board gets its own collider below and the pieces get triggers.
            (GameObject set, Bounds bounds) = PlaceModel($"{FurnitureDir}/chess.glb", parent, "ChessSet",
                new Vector3(roomCentre.x, 0f, roomCentre.z), 0f, ChessScale,
                addBoxCollider: false, rotation: Quaternion.Euler(-90f, 0f, 0f));

            // Logged like the key model's, and for the same reason: every number above is a measurement
            // off this file, and a re-export that changes its units should show up in the build log
            // rather than as a chessboard the size of a room.
            // UNPACKED, and it is the only model in the game that is. Unity lets components be ADDED
            // to a prefab instance but not the hierarchy RESTRUCTURED, and opening the board means
            // reparenting 77 of its children into two movers. The .glb stays the source of truth for
            // the geometry either way - the scene is build output, so nothing is lost by flattening it.
            PrefabUtility.UnpackPrefabInstance(set, PrefabUnpackMode.Completely, InteractionMode.AutomatedAction);

            Debug.Log($"[SceneBuilder] Chess set size={bounds.size} (expects ~5.4 across)");

            // FINDING THE PIECES IN A MACHINE-GENERATED HIERARCHY. This is a SketchUp export by way of
            // Collada, so every node is called instance_N and nothing is named after what it is. The
            // pieces are found by SHAPE instead, which is the only thing in here that means anything:
            //
            // The group holding them is the node that spans the whole set on ALL THREE AXES and has the
            // most children. `SketchUp` and the scene group span it too but have one or two children;
            // the board spans it on X and Z with 77 tiles and is 0.06 TALL against the set's 0.79.
            //
            // Height is the whole discriminator and leaving it out is not hypothetical: the first version
            // tested X and Z only, the board won on child count, and the build reported 70 pieces from
            // its tiles instead of 32 from the group above it.
            Transform group = null;
            foreach (Transform t in set.GetComponentsInChildren<Transform>())
            {
                Renderer[] rs = t.GetComponentsInChildren<Renderer>();
                if (rs.Length == 0) continue;
                Bounds b = rs[0].bounds;
                for (int i = 1; i < rs.Length; i++) b.Encapsulate(rs[i].bounds);
                if (b.size.x < bounds.size.x * 0.95f
                 || b.size.z < bounds.size.z * 0.95f
                 || b.size.y < bounds.size.y * 0.95f) continue;
                if (group == null || t.childCount > group.childCount) group = t;
            }

            if (group == null)
            {
                Debug.LogError("[SceneBuilder] chess.glb: no node spans the set - pieces not built. "
                             + "A re-export has changed its hierarchy.");
                return (new CarryableItem[0], null);
            }

            // Among that group's children, the BOARD is the one with a footprint - 3.60 wide and 0.06 tall
            // where a piece is 0.30 wide and up to 0.72. Half the set's width separates the two by a mile,
            // so the test needs no tuning.
            //
            // TWO PASSES, because the board is the LAST of the 33 children and every piece needs to know
            // how high its top is. One pass built all 32 pieces with a floor height of zero, so a dropped
            // piece would have rested on the floor through the board it came off.
            var pieceNodes = new System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<Transform, Bounds>>();
            float boardTop = 0f;
            Collider boardCollider = null;
            Bounds boardBounds = new Bounds(roomCentre, Vector3.zero);

            foreach (Transform child in group)
            {
                Renderer[] rs = child.GetComponentsInChildren<Renderer>();
                if (rs.Length == 0) continue;
                Bounds b = rs[0].bounds;
                for (int i = 1; i < rs.Length; i++) b.Encapsulate(rs[i].bounds);

                if (b.size.x > bounds.size.x * 0.5f)
                {
                    // The board. Solid, so pieces and players rest ON it rather than in it - and thin
                    // enough that the CharacterController's step offset walks straight over the edge.
                    child.gameObject.name = "Board";
                    BoxCollider slab = child.gameObject.AddComponent<BoxCollider>();
                    slab.center = child.InverseTransformPoint(b.center);
                    // ABS, because half this set is MIRRORED. The dark pieces carry a local scale of
                    // -1, and InverseTransformVector divides by the scale - so a size taken through it
                    // comes back negative and the collider is inside out. It bit the piece triggers
                    // rather than this one, but the correction belongs on both.
                    slab.size = Abs(child.InverseTransformVector(b.size));
                    boardTop = b.max.y;
                    boardBounds = b;
                    boardCollider = slab;
                    continue;
                }

                pieceNodes.Add(new System.Collections.Generic.KeyValuePair<Transform, Bounds>(child, b));
            }

            // THE GRID, MEASURED OFF THE OPENING POSITION rather than divided out of the board's
            // bounding box. The slab is 5.40m across but its playing area is 4.19m from the first file
            // to the eighth - the rest is the frame - so size/8 gives 0.675m cells where the real ones
            // are 0.598m, and by the far file that error is more than a whole square. It shows up in
            // play as "the piece does not land in the middle of a square".
            //
            // Measuring from the extremes is safe because an opening position fills the outer files
            // AND the outer ranks on both sides: the lowest and highest coordinate on each axis are the
            // first and eighth line of that axis, seven pitches apart. The two axes are averaged
            // because they are two measurements of one number.
            float minX = float.MaxValue, maxX = float.MinValue;
            float minZ = float.MaxValue, maxZ = float.MinValue;
            foreach (var node in pieceNodes)
            {
                Vector3 p = node.Key.position;
                minX = Mathf.Min(minX, p.x); maxX = Mathf.Max(maxX, p.x);
                minZ = Mathf.Min(minZ, p.z); maxZ = Mathf.Max(maxZ, p.z);
            }

            float pitch = ((maxX - minX) + (maxZ - minZ)) / (2f * (SquaresPerSide - 1));
            Vector3 gridCentre = new Vector3((minX + maxX) * 0.5f, boardTop, (minZ + maxZ) * 0.5f);

            // The board is NOT centred on where the set was placed - the model has the slab off-centre
            // inside its own bounds - so everything below works off the measured centre and not off
            // roomCentre.
            GameObject boardGO = new GameObject("ChessBoard");
            boardGO.transform.SetParent(parent, false);

            ChessBoard board = boardGO.AddComponent<ChessBoard>();
            board.boardCollider = boardCollider;
            board.squaresPerSide = SquaresPerSide;
            board.squarePitch = pitch;
            board.gridCentre = gridCentre;
            board.surfaceY = boardTop;

            // THE LIT SQUARE. A slab a shade inside a square, so the square's own edges still read
            // under it, and emissive so it is the brightest thing in a room whose lights are OUT
            // until the puzzle is finished - it has to be findable from the far side of a dark room,
            // which is where a player carrying a piece usually is.
            GameObject marker = Prim(PrimitiveType.Cube, "SquareMarker", boardGO.transform,
                gridCentre, new Vector3(pitch * 0.86f, 0.006f, pitch * 0.86f),
                MakeEmissiveMaterial("ChessSquareMarker", new Color(0.30f, 0.72f, 1f), 2.6f),
                removeCollider: true);
            marker.SetActive(false);
            board.marker = marker.transform;

            Sprite pieceIcon = ChessPieceIcon();
            var pieces = new System.Collections.Generic.List<CarryableItem>();
            var anchors = new System.Collections.Generic.List<Transform>();
            var startsHome = new System.Collections.Generic.List<bool>();

            // WHICH PIECES GO ON THE FLOOR, by a shuffle rather than by taking the first twelve. The
            // node order is the exporter's, which groups a colour and a rank together - the first
            // twelve would be one side's back row, and the room would read as one player's pieces
            // knocked over rather than as a set that has been disturbed.
            int[] order = new int[pieceNodes.Count];
            for (int i = 0; i < order.Length; i++) order[i] = i;
            System.Random rng = new System.Random(ChessScatterSeed);
            for (int i = order.Length - 1; i > 0; i--)
            {
                int j = rng.Next(i + 1);
                (order[i], order[j]) = (order[j], order[i]);
            }

            var scattered = new System.Collections.Generic.HashSet<int>();
            for (int i = 0; i < Mathf.Min(ScatteredPieceCount, order.Length); i++) scattered.Add(order[i]);

            float boardHalfSpan = Mathf.Max(boardBounds.size.x, boardBounds.size.z) * 0.5f;
            var spots = new System.Collections.Generic.List<Vector3>();

            for (int i = 0; i < pieceNodes.Count; i++)
            {
                Transform piece = pieceNodes[i].Key;

                // CAPTURED BEFORE ANYTHING MOVES. The anchor is the opening pose and the tilt is the
                // way this piece stands; both are only true of the set as the model left it.
                Vector3 homeLocalPosition = piece.localPosition;
                Quaternion homeLocalRotation = piece.localRotation;
                float tiltX = piece.eulerAngles.x;

                pieces.Add(MakeChessPiece(piece, pieceNodes[i].Value, pieceIcon, tiltX));

                // The socket, as a SIBLING of the piece carrying the pose the piece had. See
                // ChessBoard.homeAnchors: an item is parented to its socket at local identity, so an
                // anchor built this way reproduces the model's own arrangement exactly - without
                // ChessBoard knowing that the set is scaled 0.3039, modelled Z-up, or point-mirrored
                // for the dark half.
                //
                // localScale ONE, not the piece's. CarryableItem.InsertInto restores the item's own
                // local scale on top of this, and a dark piece carries -1 there; copying it here would
                // multiply the two and un-mirror the piece.
                GameObject anchor = new GameObject("Home_" + piece.gameObject.name);
                anchor.transform.SetParent(piece.parent, false);
                anchor.transform.localPosition = homeLocalPosition;
                anchor.transform.localRotation = homeLocalRotation;
                anchor.transform.localScale = Vector3.one;
                anchors.Add(anchor.transform);

                startsHome.Add(!scattered.Contains(i));
                if (!scattered.Contains(i)) continue;

                Vector3 spot = ScatterSpot(rng, roomCentre, gridCentre, boardHalfSpan, doorwayInside, spots);
                spots.Add(spot);
                // The pivot of every piece sits at its base - on the board they stand at exactly the
                // slab's top - so y ZERO is a piece standing on the floor, not one sunk into it.
                piece.position = spot;
                // Turned where it fell. Without this the twelve stand in a shared direction and read
                // as a second, sparser grid rather than as pieces that have been knocked about.
                piece.rotation = Quaternion.Euler(0f, (float)rng.NextDouble() * 360f, 0f) * piece.rotation;
            }

            board.pieces = pieces.ToArray();
            board.homeAnchors = anchors.ToArray();
            board.startsHome = startsHome.ToArray();

            // THE BOARD COMES APART. Split before the anchors are re-hung, so each anchor can be
            // handed to the half its square is on - a seated piece is parented to its anchor, so
            // that is the whole of how thirty-two pieces ride the halves out without anything
            // tracking them.
            (Transform halfWest, Transform halfEast) = SplitBoard(parent, boardCollider.transform, gridCentre.x);
            foreach (Transform a in anchors)
                a.SetParent(a.position.x < gridCentre.x ? halfWest : halfEast, true);

            // TAKEABLE NOW, where it was scenery. The final room's first recess names it, so the
            // thing this room pays out has somewhere to go for the first time.
            (Transform plinth, _, CarryableItem redCube) = BuildKeyPlinth(parent, "ChessPlinth",
                gridCentre, propMat, SlotShape.Square, new Color(0.85f, 0.10f, 0.10f), "ChessRewardKey",
                CubeKeyItemId, "CUBE", SquareIcon());

            ChessReward reward = boardGO.AddComponent<ChessReward>();
            reward.lights = roomLights;
            reward.fixturePanels = roomPanels;
            reward.boardWest = halfWest;
            reward.boardEast = halfEast;
            reward.boardCollider = boardCollider;
            reward.plinth = plinth;
            reward.key = redCube;
            // 1.7 each way opens a 3.4m gap in a 5.4m board - wide enough that the plinth comes up
            // through clear floor rather than between two ledges - and leaves the far half 1.6m short
            // of the wall, which is where the room stops being able to give any more.
            reward.openTravel = 1.7f;
            board.reward = reward;
            // NO ResetNow() HERE, ON PURPOSE. AddComponent already ran Awake, before `plinth`/`key`
            // above were assigned - the same order RewardPlinth's own rooms are already built in,
            // and the reason "a scene whose one prop is invisible cannot be checked without pressing
            // Play" is written on that class rather than solved for it. Calling ResetNow (or
            // anything else that reads plinthUp/plinthDown) here would run it against the zeroed
            // values Awake's skipped capture left behind and BAKE a wrong position into the saved
            // scene - which is exactly what happened the first time this line existed: the plinth
            // landed at world (0,0,0), Room1, and stayed there even once Play mode's own fresh Awake
            // ran, because by then (0,0,0) was the authored position it captured FROM. Play mode's
            // own Awake, running against the fully-serialized scene, is what correctly captures the
            // closed/up state - same as it already does for Room2East and Room3.

            // EVERY PIECE ON A SQUARE OF ITS OWN, checked rather than assumed. Two pieces resolving to
            // one square is exactly what a mis-measured pitch looks like, and the symptom in play would
            // be a piece that cannot be put down with no indication why. Worth an error at build time.
            var occupied = new System.Collections.Generic.HashSet<int>();
            int offBoard = 0, clashes = 0;
            foreach (Transform a in anchors)
            {
                int square = board.SquareAt(a.position);
                if (square < 0) offBoard++;
                else if (!occupied.Add(square)) clashes++;
            }

            if (offBoard > 0 || clashes > 0)
                Debug.LogError($"[SceneBuilder] Chess grid mis-measured: {offBoard} piece(s) off the board, "
                             + $"{clashes} sharing a square. pitch={pitch:F4} centre={gridCentre}");

            // The red cube rides out with the pieces so it lands in the prompt list with them. It is
            // not a piece and the board knows nothing about it; this is the one list both belong to.
            pieces.Add(redCube);

            Debug.Log($"[SceneBuilder] Chess: {pieces.Count - 1} pieces (expects 32), {spots.Count} scattered, "
                    + $"square pitch {pitch:F3}, board top {boardTop:F3}");
            return (pieces.ToArray(), board);
        }

        // Cuts the imported board down its middle so the two halves can slide apart, and hands back
        // the movers they hang off.
        //
        // THE BOARD IS NOT ONE MESH, which is the only reason this is possible at all: the export is
        // 72 separate tiles, four frame rails and a base plate - 77 children. Sorting them by which
        // side of the centre line they sit on is a real split of the real board rather than a trick
        // played with two copies.
        //
        // Three of those children run the WHOLE width - the base plate and the two cross rails - so
        // no side owns them. Each is duplicated and each copy squashed to half width about its own
        // outer edge, which is exact for an axis-aligned slab and costs nothing on this model:
        // every material on the board is a FLAT COLOUR, so there is no texture to stretch.
        //
        // THE MOVERS ARE CHILDREN OF THE ROOM, not of the set. The set is scaled 0.3039 and rotated
        // -90 about X, so a metre of travel written inside it is neither a metre nor along X.
        //
        // No collider on either half. The slab is 0.1m - under the CharacterController's step
        // offset, so it was never something to walk into - and a moving solid that slides into a
        // standing player is a way to get wedged for no gain. The board's own collider stays for
        // aiming and `ChessReward` switches it off as the halves part.
        private static (Transform west, Transform east) SplitBoard(Transform room, Transform boardNode, float centreX)
        {
            GameObject west = new GameObject("BoardHalf_West");
            GameObject east = new GameObject("BoardHalf_East");
            west.transform.SetParent(room, false);
            east.transform.SetParent(room, false);

            // Copied out first: reparenting while iterating a Transform's children skips every other
            // entry, because the collection being walked is the thing being emptied.
            var children = new System.Collections.Generic.List<Transform>();
            foreach (Transform child in boardNode) children.Add(child);

            int split = 0;
            foreach (Transform child in children)
            {
                Renderer[] rs = child.GetComponentsInChildren<Renderer>();
                if (rs.Length == 0) continue;

                Bounds b = rs[0].bounds;
                for (int i = 1; i < rs.Length; i++) b.Encapsulate(rs[i].bounds);

                const float slack = 0.01f;
                if (b.max.x <= centreX + slack) { child.SetParent(west.transform, true); continue; }
                if (b.min.x >= centreX - slack) { child.SetParent(east.transform, true); continue; }

                // A straddler. The squash is done by a WRAPPER at world identity rather than by
                // scaling the child, so it stays a pure world-X scale whatever rotation the child
                // carries - a non-uniform scale applied through a rotated basis shears.
                GameObject twin = Object.Instantiate(child.gameObject, child.parent);
                twin.name = child.gameObject.name + "_E";
                child.gameObject.name = child.gameObject.name + "_W";

                float span = b.max.x - b.min.x;
                ClipHalf(child, west.transform, b.min.x, (centreX - b.min.x) / span);
                ClipHalf(twin.transform, east.transform, b.max.x, (b.max.x - centreX) / span);
                split++;
            }

            Debug.Log($"[SceneBuilder] Chess board split: {west.transform.childCount} west / "
                    + $"{east.transform.childCount} east, {split} part(s) cut in half");
            return (west.transform, east.transform);
        }

        // One straddling part reduced to the half on its pivot's side. The wrapper sits AT the edge
        // that must not move, so scaling about it walks the far edge in to the centre line.
        private static void ClipHalf(Transform child, Transform half, float pivotX, float scaleX)
        {
            GameObject clip = new GameObject(child.gameObject.name + "_Clip");
            clip.transform.SetParent(half, false);
            // After parenting, and while the scale is still one: this is the pivot the squash turns
            // about, so it has to be a world position rather than an offset in a scaled frame.
            clip.transform.position = new Vector3(pivotX, 0f, 0f);
            child.SetParent(clip.transform, true);
            clip.transform.localScale = new Vector3(scaleX, 1f, 1f);
        }

        // The reward, and the only thing in Room2West that is not chess: a plinth rises out of the
        // gap the board leaves, with a red cube on it.
        //
        // Authored RAISED and sunk at runtime by `ChessReward`, exactly like Room4's plinth - a scene
        // whose one prop is invisible cannot be checked without pressing Play. It stands at the
        // board's own centre, so while the board is shut it is under the slab as well as under the
        // floor and there is nothing to notice before it moves.
        // A plinth with one of the escape objects on it. Shared by every room that pays one out, so
        // the three rewards are the same fixture in three colours and three shapes - a player who has
        // seen one knows what the next one is the moment it comes up.
        //
        // `itemId` EMPTY means the object is scenery: it is built and it is lit, but nothing can pick
        // it up. That is the state Room2West's red cube is in - there is nowhere yet for it to go, and
        // a carryable with no destination sits in the HUD row claiming to matter.
        //
        // Returns the plinth, the seat the object rests on, and the object itself when it is takeable.
        private static (Transform plinth, Transform seat, CarryableItem item) BuildKeyPlinth(
            Transform parent, string name, Vector3 centre, Material propMat,
            SlotShape shape, Color accent, string materialName,
            string itemId = "", string displayName = "", Sprite icon = null)
        {
            const float bodyHeight = 0.85f;
            const float bodyWidth = 0.62f;
            const float plateProud = 0.035f;
            const float keySize = 0.30f;

            GameObject plinth = new GameObject(name);
            plinth.transform.SetParent(parent, false);
            plinth.transform.localPosition = new Vector3(centre.x, 0f, centre.z);

            Prim(PrimitiveType.Cube, "Body", plinth.transform,
                new Vector3(0f, bodyHeight / 2f, 0f),
                new Vector3(bodyWidth, bodyHeight, bodyWidth), propMat);

            // The dark inset the object stands on, borrowed from Room4's plinth for the same reason:
            // a pale block on a pale block is one block, and the seat is what says something is
            // MEANT to be there.
            Prim(PrimitiveType.Cube, "TopPlate", plinth.transform,
                new Vector3(0f, bodyHeight + plateProud / 2f, 0f),
                new Vector3(bodyWidth * 0.82f, plateProud, bodyWidth * 0.82f),
                MakeColorMaterial("ChessPlinthPlate", new Color(0.14f, 0.14f, 0.16f)),
                removeCollider: true);

            GameObject seat = new GameObject("Seat");
            seat.transform.SetParent(plinth.transform, false);
            seat.transform.localPosition = new Vector3(0f, bodyHeight + plateProud + keySize / 2f, 0f);

            // POLISHED METAL WITH A GLOW STILL IN IT, on a chamfered version of its own silhouette.
            //
            // These were flat emissive at 2.4 on raw Unity primitives, and the two faults compounded:
            // a matte surface has no highlight to catch, and a primitive has no geometry at its edges
            // for a highlight to run along even if it did. The result was three coloured blocks - the
            // least interesting objects in the game, which is the wrong thing for the three the whole
            // run is spent collecting.
            //
            // The emission is kept, at a fifth of what it was, because the ORIGINAL reason for it
            // stands: each of these arrives in the same second as the biggest lighting change its
            // room has, and Room2West is genuinely dark until that moment. It is also the floor that
            // makes the metal safe here - see MakePolishedMetalMaterial on why a pure metal in this
            // project renders black.
            GameObject key = ShapePrim(shape, "RewardKey", plinth.transform,
                seat.transform.localPosition, Vector3.one * keySize,
                MakePolishedMetalMaterial(materialName, accent, 0.40f), bevelled: true);

            // SCENERY GETS A SOLID BOX, a takeable gets a trigger, and it is never both. CarryableItem
            // takes whatever `GetComponent<Collider>()` hands back as its reach - so an object left
            // with the shape's own 0.30 collider AND a trigger is one you have to stand inside to
            // pick up, because the solid one was added first and wins the lookup.
            if (string.IsNullOrEmpty(itemId))
            {
                key.AddComponent<BoxCollider>();
                return (plinth.transform, seat.transform, null);
            }

            // Local units on a transform scaled to 0.30, so this is 1.02m across and 0.90 tall in the
            // world: an arm's length rather than the object's own size, so it is taken from standing
            // at the plinth instead of from inside it.
            //
            // WIDE ENOUGH TO CLEAR THE PEDESTAL FROM EVERY SIDE, not just the width Body itself needs.
            // Body is a solid 0.62m box (0.31 half-extent) and the player's CharacterController has a
            // 0.08 skin width, so walking straight into ANY face - not a diagonal - stops the player's
            // capsule 0.31 + 0.08 = 0.39m out. A trigger sized to only just clear Body's own half-extent
            // (0.33m, one number over) was closer than that stop distance, so a square approach could
            // never overlap it - only a corner-on approach, where the AABB test's two axes both shrink
            // at once, ever reached it. Measured by walking a CharacterController at this pedestal from
            // all four cardinal directions and a diagonal: the cardinals never overlapped, the diagonal
            // always did - which is exactly "picks up from one angle, not from the side." 0.51m half
            // extent clears the 0.39m stop distance with room to spare.
            BoxCollider trigger = key.AddComponent<BoxCollider>();
            trigger.isTrigger = true;
            trigger.size = new Vector3(3.4f, 3.0f, 3.4f);

            CarryableItem item = key.AddComponent<CarryableItem>();
            item.itemId = itemId;
            item.displayName = displayName;
            item.icon = icon;
            item.iconTint = accent;
            // Its own half-height: the mesh is centred on its pivot, so this is what puts it ON a
            // floor rather than half through one. Only a ghost's timeline ending under it drops one.
            item.floorY = keySize / 2f;
            item.handLocalPosition = HandPoseFor(keySize);
            // Tipped TOWARD the eye, not away. A prism seen square-on is a rectangle; -25 about X
            // brings its top face into view, which is the face that says which shape this is. The
            // yaw follows, so it is a three-quarter view like the chess pieces'.
            item.handLocalEuler = new Vector3(-25f, 20f, 0f);
            // ITS OWN SIZE. The anchor is unscaled, so writing the object's world scale here is what
            // "held at true size" means - it used to be shrunk to 0.22 to fit the view, and the view
            // is what gives way now instead of the object.
            item.handLocalScale = key.transform.lossyScale;
            return (plinth.transform, seat.transform, item);
        }

        // A spot on the floor for a piece to be found on: inside the room, off the board, out of the
        // doorway, and not on top of another piece.
        //
        // Rejection sampling rather than a laid-out pattern, because the point is that the room looks
        // disturbed. The bail-out is not decoration: the free floor here is a RING around a 5.4m board
        // in an 8.75 x 10.5 room, which is roomy for a dozen pieces and would not be for forty, and a
        // build that hangs is worse than a floor that is a little crowded.
        //
        // The four margins are PARAMETERS, not constants, since 2026-08-13: the cube room's pieces are
        // nine times the chess set's, and "clear of a 0.24m piece" and "clear of a 2.16m cube" are not
        // the same number. Every default reproduces the chess room's original behaviour untouched.
        private static Vector3 ScatterSpot(System.Random rng, Vector3 roomCentre, Vector3 gridCentre,
                                           float boardHalfSpan, Vector3 doorwayInside,
                                           System.Collections.Generic.List<Vector3> taken,
                                           float wallMargin = 0.8f, float boardMargin = 0.35f,
                                           float doorClear = 1.6f, float apart = 0.62f)
        {
            // wallMargin: nothing jammed into a corner where it cannot be seen.
            // boardMargin: clear of the slab, so nothing looks like it is on it.
            // doorClear: the way in stays the way in.
            // apart: two pieces never share one E press.

            // Room2West is a room on the chain now, same orientation as every other: WIDTH along X,
            // DEPTH along Z.
            float halfX = RoomWidth / 2f - wallMargin;
            float halfZ = RoomDepth / 2f - wallMargin;
            float keepOut = boardHalfSpan + boardMargin;

            Vector3 fallback = roomCentre;
            for (int attempt = 0; attempt < 400; attempt++)
            {
                Vector3 p = new Vector3(
                    roomCentre.x + ((float)rng.NextDouble() * 2f - 1f) * halfX,
                    0f,
                    roomCentre.z + ((float)rng.NextDouble() * 2f - 1f) * halfZ);
                fallback = p;

                if (Mathf.Abs(p.x - gridCentre.x) < keepOut && Mathf.Abs(p.z - gridCentre.z) < keepOut) continue;

                Vector2 fromDoor = new Vector2(p.x - doorwayInside.x, p.z - doorwayInside.z);
                if (fromDoor.magnitude < doorClear) continue;

                bool crowded = false;
                foreach (Vector3 other in taken)
                    if ((other - p).sqrMagnitude < apart * apart) { crowded = true; break; }
                if (crowded) continue;

                return p;
            }

            return fallback;
        }

        // Componentwise absolute value. Needed because InverseTransformVector divides by the scale and
        // half this chess set is mirrored - see the note where the board's collider is built.
        private static Vector3 Abs(Vector3 v) =>
            new Vector3(Mathf.Abs(v.x), Mathf.Abs(v.y), Mathf.Abs(v.z));

        // One piece, turned into something E can pick up. Everything here is the pin and the key over
        // again - trigger, CarryableItem, hand pose - and nothing about it is chess-specific except how
        // big it is and what it is called.
        //
        // ITS OWN ITEM ID, from its own node name. The alternative was one shared id, which would have
        // capped the player at one piece at a time for free (PlayerHand.carried is a set of ids) and let
        // ItemRegistry's pool hand a ghost any spare piece. That is right for pins, which are
        // interchangeable, and wrong here: a knight is not a bishop, and a puzzle about putting the right
        // piece on the right square needs the recording to name a piece and mean it.
        //
        // The node names are instance_N and say nothing about type, so the ids do not pretend to either.
        // Classifying them - which is a knight, which is a pawn - is the puzzle's job and is in TODO.md.
        //
        // `tiltX` is the piece's own measured world pitch, and it is the whole of what makes a dark
        // piece sit in the hand the same way up as a light one. See the note on handLocalEuler below.
        private static CarryableItem MakeChessPiece(Transform piece, Bounds bounds, Sprite icon, float tiltX)
        {
            piece.gameObject.name = "Piece_" + piece.name.Replace("instance_", string.Empty);

            // A MIRRORED PIECE'S MINUS ONE, MOVED OFF THE PIECE ITSELF. Half this set has a local
            // scale of (-1,-1,-1), and Unity warns "BoxCollider does not support negative scale" on
            // every load for each one. The warning is benign - it uses the absolute value, which for
            // a centred symmetric trigger is exactly right - but a permanent warning in the console
            // is a permanent warning, and the next person to read it will not know that.
            //
            // Pushing the -1 onto a wrapper INSIDE the piece leaves the composite untouched, because
            // the wrapper sits after the piece's own rotation and scale either way:
            //   before  P * R * S(-1) * child
            //   after   P * R * S(+1) * S(-1) * child
            // What changes is that the piece's own transform is now positively scaled - and it is
            // that transform the trigger, `handLocalScale` and the home anchor are all read off. The
            // rotation is untouched, so the measured tilt below still means what it meant.
            if (piece.localScale.x < 0f || piece.localScale.y < 0f || piece.localScale.z < 0f)
            {
                Vector3 mirrored = piece.localScale;

                GameObject wrapper = new GameObject("Mirror");
                wrapper.transform.SetParent(piece, false);

                var meshes = new System.Collections.Generic.List<Transform>();
                foreach (Transform c in piece) if (c != wrapper.transform) meshes.Add(c);
                // worldPositionStays FALSE: the wrapper is still identity at this point, so keeping
                // the local pose is what keeps the child exactly where it was in the piece's frame.
                foreach (Transform c in meshes) c.SetParent(wrapper.transform, false);

                wrapper.transform.localScale = mirrored;
                piece.localScale = Vector3.one;
            }

            // Sized to about one square (0.45m) rather than to the piece, so the reach is even across the
            // board instead of a king being easier to grab than a pawn. Triggers overlapping is fine and
            // expected: ControlHintDisplay prompts over the NEAREST one that wants it.
            BoxCollider trigger = piece.gameObject.AddComponent<BoxCollider>();
            trigger.isTrigger = true;
            trigger.center = piece.InverseTransformPoint(bounds.center);
            // ABS: the dark pieces have a local scale of -1, so this division comes back negative and
            // the trigger is built inside out.
            trigger.size = Abs(piece.InverseTransformVector(new Vector3(0.45f, Mathf.Max(0.45f, bounds.size.y), 0.45f)));

            CarryableItem item = piece.gameObject.AddComponent<CarryableItem>();
            item.itemId = piece.gameObject.name;
            item.displayName = "PIECE";
            item.icon = icon;
            // ZERO, i.e. the floor. floorY is where a piece rests when it is DROPPED, and the only
            // thing that drops one is a ghost's timeline running out under it - on the floor, mid-room.
            // Putting a piece back on the board is not a drop: it goes into its square's socket, which
            // carries its own height. This read boardTop while the pieces all started on the board, and
            // a piece let go of by a past self floated a centimetre over the floor.
            item.floorY = 0f;
            // Further out and lower than the key's hold. A king is 0.72m tall at this scale, and at the
            // key's 0.46m from the eye it would fill the view - which is the cost of the board being
            // twice the size it was. If it still reads as too big in hand, this is the number.
            // STOOD UP IN THE HAND, and the tilt is the whole of it. The set is modelled Z-up, so
            // inside a piece's own local frame the model's "up" is +Z. Attached to the hand anchor at
            // an identity-ish rotation that +Z lines up with the camera's FORWARD - the piece lies down
            // and comes at the eye end-on, which is what "too big and I cannot tell which piece it is"
            // was. A pitch of 270 turns local +Z back onto the parent's up.
            //
            // WHY IT IS MEASURED AND NOT WRITTEN AS -90. Half of this set is MIRRORED: the dark pieces
            // carry a local scale of (-1,-1,-1), and Unity decomposes that basis as a pitch of +90 with
            // a negative scale where the light ones are 270 with a positive one. Both stand up on the
            // board - the two cancel - but handLocalScale copies the sign of the scale, so handing both
            // colours the same -90 stood the light pieces up and the dark ones on their heads. Play
            // found it as "the black ones are held upside down". Taking the pitch off each piece's own
            // world rotation makes the pair cancel in the hand exactly as they do on the board.
            //
            // The yaw is applied AFTER the pitch (Unity's order is Z, X, then Y), so it spins the piece
            // about its own vertical rather than tipping it: a three-quarter view, where face-on a
            // bishop and a pawn are the same silhouette.
            // Sized from the piece's own board footprint, so a king is held further out than a pawn.
            // Its own measured height, so a king is held further out than a pawn. `bounds` is the
            // world-space extent the trigger above is already sized from.
            item.handLocalPosition = HandPoseFor(bounds.size.y);
            item.handLocalEuler = new Vector3(tiltX, HeldPieceYaw, 0f);
            // The same correction on a ghost's wrist, with no yaw: that anchor is tuned for the key and
            // hands a piece over lying along the forearm otherwise. A past self carrying a rook has to
            // read as carrying a rook - who is holding what is half of what makes ghosts legible.
            item.ghostLocalEuler = new Vector3(tiltX, 0f, 0f);
            // ITS BOARD SIZE, exactly. Not optional even for true-size holding: the hand anchor is
            // unscaled and the set is not, so this is the correction that stops a piece being handed
            // over at 1/0.3039 of its own size - a 3.5m king. What is gone is the extra 0.28 that
            // used to shrink it below board size on top of that.
            // The SIGN matters as much as the size - it is what keeps a mirrored piece mirrored.
            item.handLocalScale = piece.lossyScale;
            return item;
        }

        // A pawn in silhouette, standing in for every piece in the readout. One shape for all 32 rather
        // than six drawn shapes: the row is telling the player they are carrying A PIECE, and until the
        // puzzle needs types told apart, six silhouettes would be five more things to learn than the
        // readout is currently saying.
        private static Sprite ChessPieceIcon()
        {
            var icon = new IconCanvas(128);
            icon.Disc(new Vector2(0.5f, 0.735f), 0.135f);                        // head
            icon.Bar(new Vector2(0.5f, 0.575f), new Vector2(0.155f, 0.038f));    // collar
            icon.Shape(p =>
            {
                // Body: a waist that flares to the base, so it reads as turned wood rather than a peg.
                if (p.y < 0.20f || p.y > 0.56f) return false;
                float k = (p.y - 0.20f) / 0.36f;
                float half = Mathf.Lerp(0.185f, 0.072f, Mathf.Sqrt(k));
                return Mathf.Abs(p.x - 0.5f) <= half;
            });
            icon.Bar(new Vector2(0.5f, 0.175f), new Vector2(0.225f, 0.045f));    // base
            return SaveSprite(icon, "icon_chess_piece");
        }


        // THE SIX SYMBOLS, drawn once and used twice: as an opaque picture on a cube and on the
        // recess that wants it, and as a HUD glyph in the carried row. One drawing rather than two
        // means the thing on the wall and the thing in the readout can never drift apart.
        //
        // A CARD FAMILY, extended past the four suits with a star and a crescent. The spec named
        // three; six cubes need six, and picking the two extras from the same visual world - flat,
        // solid, symmetrical, no interior detail - is what keeps them reading as one set rather than
        // as four suits and two strays.
        private struct SymbolSpec
        {
            public string id;
            public string name;
            public System.Action<IconCanvas> draw;
        }

        private static SymbolSpec[] CubeSymbols() => new[]
        {
            new SymbolSpec { id = "Cube_Spade", name = "spade", draw = icon =>
            {
                // The blade: a triangle standing on two lobes.
                icon.Shape(pt =>
                {
                    if (pt.y < 0.42f || pt.y > 0.90f) return false;
                    float k = (0.90f - pt.y) / 0.48f;
                    return Mathf.Abs(pt.x - 0.5f) <= 0.40f * k;
                });
                icon.Disc(new Vector2(0.30f, 0.44f), 0.20f);
                icon.Disc(new Vector2(0.70f, 0.44f), 0.20f);
                // The stem, wide at the foot and narrow where it meets the blade.
                icon.Shape(pt =>
                {
                    if (pt.y < 0.10f || pt.y > 0.44f) return false;
                    float k = (pt.y - 0.10f) / 0.34f;
                    return Mathf.Abs(pt.x - 0.5f) <= Mathf.Lerp(0.17f, 0.045f, k);
                });
            }},
            new SymbolSpec { id = "Cube_Heart", name = "heart", draw = icon =>
            {
                // The textbook parametric heart curve - the one every graphing calculator and
                // Valentine's card uses - traced as a polygon and filled by point-in-polygon, rather
                // than two discs butted against a triangle. Discs-and-a-wedge always read as exactly
                // that up close: two circles with a corner where the straight edges meet them. This
                // is one closed curve with no seam anywhere on it.
                const int n = 240;
                Vector2[] poly = new Vector2[n];
                float minX = float.MaxValue, maxX = float.MinValue, minY = float.MaxValue, maxY = float.MinValue;
                for (int i = 0; i < n; i++)
                {
                    float t = i * Mathf.PI * 2f / n;
                    float sx = 16f * Mathf.Pow(Mathf.Sin(t), 3f);
                    float sy = 13f * Mathf.Cos(t) - 5f * Mathf.Cos(2f * t) - 2f * Mathf.Cos(3f * t) - Mathf.Cos(4f * t);
                    poly[i] = new Vector2(sx, sy);
                    minX = Mathf.Min(minX, sx); maxX = Mathf.Max(maxX, sx);
                    minY = Mathf.Min(minY, sy); maxY = Mathf.Max(maxY, sy);
                }
                float span = Mathf.Max(maxX - minX, maxY - minY);
                float cx = (minX + maxX) * 0.5f, cy = (minY + maxY) * 0.5f;
                const float fill = 0.74f; // how much of the 0..1 canvas the curve's own box fills
                for (int i = 0; i < n; i++)
                    poly[i] = new Vector2(0.5f + (poly[i].x - cx) / span * fill,
                                          0.5f + (poly[i].y - cy) / span * fill);

                icon.Shape(p =>
                {
                    bool inside = false;
                    for (int i = 0, j = n - 1; i < n; j = i++)
                    {
                        Vector2 a = poly[i], b = poly[j];
                        if ((a.y > p.y) != (b.y > p.y)
                            && p.x < (b.x - a.x) * (p.y - a.y) / (b.y - a.y) + a.x)
                            inside = !inside;
                    }
                    return inside;
                });
            }},
            new SymbolSpec { id = "Cube_Clover", name = "clover", draw = icon =>
            {
                // A four-petal rose - r = cos(2*theta), rotated 45 degrees so the petals fall where
                // the old diagonal 2x2 discs did - instead of four circles and a hub disc filling the
                // gap between them. The rose passes through its own centre on all four petals at
                // once, so it needs no separate hub: the seam the old version had at every join
                // between a leaf-disc and the hub is simply not a feature of this curve.
                const float radius = 0.40f;
                Vector2 centre = new Vector2(0.5f, 0.58f);
                icon.Shape(p =>
                {
                    Vector2 d = p - centre;
                    float r = d.magnitude;
                    if (r > radius) return false;
                    float theta = Mathf.Atan2(d.y, d.x) - Mathf.PI / 4f;
                    return r <= radius * Mathf.Abs(Mathf.Cos(2f * theta));
                });
                icon.Bar(new Vector2(0.5f, 0.155f), new Vector2(0.036f, 0.125f));
            }},
            new SymbolSpec { id = "Cube_Diamond", name = "diamond", draw = icon =>
                icon.Shape(pt => Mathf.Abs(pt.x - 0.5f) / 0.34f + Mathf.Abs(pt.y - 0.5f) / 0.44f <= 1f)
            },
            new SymbolSpec { id = "Cube_Star", name = "star", draw = icon =>
            {
                // Five points, and the EDGES HAVE TO BE STRAIGHT. Lerping the radius between the tip
                // and the valley across each sector is the obvious version and it draws a FLOWER -
                // the valleys come out round and the points blunt, because a star is not linear in
                // angle. What it is instead is a straight segment from tip to valley, so the test is
                // which side of that segment the sample falls on.
                const float sector = Mathf.PI * 2f / 5f;
                const float outer = 0.47f, inner = 0.20f;
                Vector2 tip = new Vector2(0f, outer);
                Vector2 valley = new Vector2(inner * Mathf.Sin(sector * 0.5f), inner * Mathf.Cos(sector * 0.5f));
                Vector2 edge = valley - tip;
                // Which side of that edge the centre is on. Everything inside the star is on it too.
                float centreSide = edge.x * -tip.y - edge.y * -tip.x;
                icon.Shape(pt =>
                {
                    Vector2 d = pt - new Vector2(0.5f, 0.5f);
                    float r = d.magnitude;
                    if (r > outer) return false;
                    if (r < 0.0001f) return true;
                    // Folded into one half-sector, so one segment describes all ten edges.
                    float angle = Mathf.Atan2(d.x, d.y);
                    float t = Mathf.Abs(Mathf.Repeat(angle + sector * 0.5f, sector) - sector * 0.5f);
                    Vector2 f = new Vector2(r * Mathf.Sin(t), r * Mathf.Cos(t));
                    float side = edge.x * (f.y - tip.y) - edge.y * (f.x - tip.x);
                    return side * centreSide > 0f;
                });
            }},
            new SymbolSpec { id = "Cube_Moon", name = "moon", draw = icon =>
            {
                icon.Disc(new Vector2(0.44f, 0.5f), 0.40f);
                // sign -1 cuts the bite out, which is the whole shape.
                icon.Disc(new Vector2(0.62f, 0.56f), 0.355f, -1f);
            }},
        };

        // Room2East, behind the blue door: six cubes on the floor, six recesses in the walls and the
        // floor, and a blue sphere on a plinth when every cube is home.
        //
        // THREE ON THE FLOOR, ONE WEST, TWO EAST, by request (2026-08-13) - the room used to put two
        // on every wall that had no doorway. West keeps one recess on its own mid-line, which a
        // doorway can never reach (a doorway is always cut into a Z wall); east keeps two, spaced
        // clear of both its doorways; the remaining three sit on the floor, clear of the walls, the
        // doorways and the plinth in the room's own middle. The recesses find the player's hand
        // themselves, the way every CarryableItem already does - this room is built before the player
        // is, and reordering the build to hand one in would put the player's construction behind a
        // room that does not need it.
        //
        // THE CUBES ARE GLASS, in a silver frame, with the symbol suspended INSIDE - all by request.
        // Glass rather than the wall/floor plates' own opaque material because the ask was specifically
        // for the cube, not the recess it goes home to: the recess stays the flat matte ink the room's
        // "no legend on the wall" rule already asks of it, and the cube is the one thing in the room
        // that gets to look precious. Every cube shares ONE glass tint - see MakeGlassMaterial - for
        // the same reason the plates share one ink colour: SYMBOLS, NOT COLOURS is the room's whole
        // design rule, and a cube tinted by its own answer would undo that as surely as a lit plate did.
        private static (CarryableItem[] cubes, CubeRoom room) BuildCubeRoom(
            Transform parent, Vector3 roomCentre, Material propMat)
        {
            const float cubeSize = 1.0f;    // 3/4 again, by request - everything else follows it
            const float slotY = 2.5f;       // a wide frame at the old chest-height centre clips the floor
            const float alongWall = 3.3f;   // clear of the frame beside it and of the doorway past it

            GameObject root = new GameObject("CubeRoom");
            root.transform.SetParent(parent, false);

            // The reward first, because the scatter has to keep clear of it.
            (Transform plinth, Transform seat, CarryableItem sphere) = BuildKeyPlinth(
                parent, "SpherePlinth", roomCentre, propMat,
                SlotShape.Round, new Color(0.16f, 0.40f, 0.95f), "KeySphereMat",
                SphereKeyItemId, "SPHERE", SphereIcon());

            RewardPlinth rise = plinth.gameObject.AddComponent<RewardPlinth>();
            rise.plinth = plinth;
            rise.key = sphere;
            rise.keySeat = seat;
            rise.riseHeight = 1.25f;

            // pos/rot/floor for all six recesses. A floor mount's rotation (-90 about X) is the same
            // one the chess board's own reward plinth was verified against: it carries local +Z onto
            // world +Y, so "the seat sits cubeSize*0.30 out along local +Z" - the wall recesses' own
            // rule, below - means exactly "up off the floor" here without a second formula.
            float halfX = RoomWidth / 2f;
            var mounts = new (Vector3 pos, Quaternion rot, bool floor)[]
            {
                (new Vector3(roomCentre.x - halfX, slotY, roomCentre.z), Quaternion.Euler(0f, 90f, 0f), false),
                (new Vector3(roomCentre.x + halfX, slotY, roomCentre.z - alongWall), Quaternion.Euler(0f, -90f, 0f), false),
                (new Vector3(roomCentre.x + halfX, slotY, roomCentre.z + alongWall), Quaternion.Euler(0f, -90f, 0f), false),
                (new Vector3(roomCentre.x - 2.2f, 0f, roomCentre.z - 3.0f), Quaternion.Euler(-90f, 0f, 0f), true),
                (new Vector3(roomCentre.x + 2.4f, 0f, roomCentre.z + 1.8f), Quaternion.Euler(-90f, 0f, 0f), true),
                (new Vector3(roomCentre.x - 2.2f, 0f, roomCentre.z + 3.0f), Quaternion.Euler(-90f, 0f, 0f), true),
            };

            SymbolSpec[] symbols = CubeSymbols();
            var cubes = new CarryableItem[symbols.Length];
            var slots = new SymbolSlot[symbols.Length];

            // ONE body material for all six, built once, because the body is the same clear glass on
            // every cube now - what differs is the core inside it. It used to be six materials that
            // differed only by the glyph printed on their faces.
            Material glassMat = MakeGlassMaterial("GlassBody", null,
                                                  new Color(0.92f, 0.96f, 1.00f, 0.28f), 0.97f);

            // Deterministic, like the chess scatter and for the same reason: a scene is build output,
            // so two builds of one commit have to lay the room out identically.
            System.Random rng = new System.Random(CubeScatterSeed);

            // FOUR FIXED FLOOR PLACES, JITTERED - not the chess room's rejection sampler, which this
            // room used until 2026-08-13 and which put the cubes in a huddle. The sampler is right
            // for a room whose only obstacle is a board in the middle; this one has a plinth in its
            // centre, THREE of its six recesses on the floor, and a doorway at each end, and every
            // one of those is a keep-out the sampler has to satisfy at once. What is left is a thin
            // ring, and 400 attempts at "far enough from everything" inside a thin ring either fails
            // into the fallback - which returns a point that satisfies NOTHING - or lands them all in
            // whichever lobe of it the seed happened to like.
            //
            // Written out, the room is laid out on purpose and cannot huddle. The rng still decides
            // the jitter and every cube's yaw, so it does not read as a grid, and the build stays
            // reproducible. Offsets are from the room's own centre: X is the short axis (8.75), Z the
            // long one (10.5), the plinth is at 0,0 and the floor recesses at (-2.2,-3.0), (2.4,1.8)
            // and (-2.2,3.0) - every number below is placed against those.
            var places = new[]
            {
                new Vector2( 2.75f, -1.35f),   // east, opposite the two west recesses
                new Vector2( 1.85f, -3.45f),   // south-east, clear of the entrance's swing
                new Vector2(-2.70f,  0.40f),   // west, between the two west recesses
                new Vector2( 0.10f,  3.45f),   // north, past the far side of the plinth
            };
            // WHICH CUBE STANDS WHERE, and how high. Index into `places`, and a level: 1 means this
            // cube is stacked on the one before it, which by construction names the same place. Two
            // towers of two rather than one of three - a metre cube three high is taller than the
            // player and reads as scenery to walk round rather than a thing to take apart. Placed at
            // opposite ends of the room so the shape is legible from wherever you come in.
            var stand = new (int place, int level)[]
            {
                (0, 0), (0, 1),   // tower, east
                (1, 0),
                (2, 0), (2, 1),   // tower, west
                (3, 0),
            };

            // One jitter per PLACE, not per cube: a stacked cube has to sit on the one below it, and
            // it can only do that if both were told the same place to be.
            var floorSpot = new Vector2[places.Length];
            for (int p = 0; p < places.Length; p++)
                floorSpot[p] = places[p] + new Vector2(((float)rng.NextDouble() * 2f - 1f) * 0.22f,
                                                       ((float)rng.NextDouble() * 2f - 1f) * 0.22f);

            // One yaw per PLACE as well, and a stacked cube takes its own small offset off it rather
            // than a fresh angle: a cube balanced across the corners of the one below it would be a
            // physics claim this project cannot make good on, and a few degrees out reads as stacked
            // by hand where a clean 0 reads as a shop display.
            var baseYaw = new float[places.Length];
            for (int p = 0; p < places.Length; p++) baseYaw[p] = (float)rng.NextDouble() * 360f;

            for (int i = 0; i < symbols.Length; i++)
            {
                SymbolSpec spec = symbols[i];

                // A thin ring behind the glyph on every WORLD-facing copy - the plate and the cube -
                // so each reads as a struck medallion rather than bare ink. Left off the HUD glyph
                // below: that one is 58px in a fixed-width row, where a second stroke competing with
                // the symbol is clutter rather than polish.
                System.Action<IconCanvas> withRing = icon =>
                {
                    icon.Ring(new Vector2(0.5f, 0.5f), 0.475f, 0.430f);
                    spec.draw(icon);
                };

                var paper = new IconCanvas(128);
                withRing(paper);
                Material plateMat = MakeSymbolMaterial("Symbol_" + spec.name,
                                                       SaveSymbolTexture(paper, "symbol_" + spec.name));

                // The same drawing again, INVERTED, for the core suspended inside the glass. The wall
                // plate is ink on paper because it is a printed sign; the core is read through a
                // tinted body in a white room, where a pale face is a white card inside a white cube
                // against a white wall. Its own texture rather than the plate's, so "the sign is
                // dark-on-light and the object is light-on-dark" is a fact about this room's look
                // rather than something a shared file forces on both.
                var core = new IconCanvas(128);
                withRing(core);
                Material coreMat = MakeSymbolMaterial("Inclusion_" + spec.name,
                    SaveSymbolTexture(core, "symbol_core_" + spec.name,
                                      new Color(0.06f, 0.06f, 0.08f), new Color(0.93f, 0.95f, 1.00f)));

                var glyph = new IconCanvas(128);
                spec.draw(glyph);
                Sprite hudIcon = SaveSprite(glyph, "icon_symbol_" + spec.name);

                (int place, int level) = stand[i];
                slots[i] = BuildSymbolSlot(root.transform, spec, plateMat, mounts[i].pos, mounts[i].rot,
                                           cubeSize, mounts[i].floor);
                cubes[i] = BuildSymbolCube(root.transform, spec, glassMat, coreMat, hudIcon, cubeSize,
                    new Vector3(roomCentre.x + floorSpot[place].x, 0f, roomCentre.z + floorSpot[place].y),
                    baseYaw[place] + (level == 0 ? 0f : ((float)rng.NextDouble() * 2f - 1f) * 13f),
                    level);

                // Take the bottom of a tower and the top of it falls. `stand` puts a stacked cube
                // directly after the one it stands on, at the same place, so the support is always
                // the cube built one step earlier - there is no lookup to get wrong.
                if (level > 0) StandOn(cubes[i], cubes[i - 1]);

                slots[i].acceptedItemId = spec.id;
            }

            CubeRoom room = root.AddComponent<CubeRoom>();
            room.cubes = cubes;
            room.slots = slots;
            room.reward = rise;
            foreach (SymbolSlot slot in slots) slot.room = room;

            // The closest pair is the one number that says whether the room reads as scattered or as
            // a huddle, and it is worth printing rather than eyeballing: measured in XZ only, so a
            // tower does not report itself as two cubes on top of each other.
            float closest = float.MaxValue;
            for (int a = 0; a < cubes.Length; a++)
                for (int b = a + 1; b < cubes.Length; b++)
                {
                    Vector3 d = cubes[a].transform.position - cubes[b].transform.position;
                    float flat = new Vector2(d.x, d.z).magnitude;
                    if (flat > 0.01f) closest = Mathf.Min(closest, flat);
                }

            int stacked = 0;
            foreach (var s in stand) if (s.level > 0) stacked++;

            Debug.Log($"[SceneBuilder] Cube room: {cubes.Length} cubes ({stacked} stacked), "
                    + $"{slots.Length} recesses, closest pair {closest:F2}m apart (cube is {cubeSize}m), "
                    + $"plinth at {plinth.position}");
            return (cubes, room);
        }

        // One recess: a symbol plate in a dark frame, standing proud of its mount, with a seat in
        // front of it for the cube. Local +Z is the recess's own outward normal - into the room for a
        // wall mount, straight up for a floor mount (its rotation carries local +Z onto world +Y) - so
        // the frame, plate and seat are built once here and never need to know which kind they are.
        // Only the reach trigger differs between the two, because "stand in front of it" and "stand
        // over it" are different shapes.
        private static SymbolSlot BuildSymbolSlot(Transform parent, SymbolSpec spec, Material faceMat,
                                                  Vector3 position, Quaternion rotation, float cubeSize,
                                                  bool floorMounted)
        {
            GameObject root = new GameObject("Slot_" + spec.name);
            root.transform.SetParent(parent, false);
            root.transform.position = position;
            root.transform.localRotation = rotation;

            // A REAL HOLLOW, not a dark rectangle pretending to be one. It used to be a flat frame
            // with the glyph panel laid on top of it, on the reasoning that there is no CSG here so a
            // cavity has to be near-black inside a lighter border - true, but only ever convincing
            // head-on. A raised RIM makes the same hole out of geometry: four bars standing proud of
            // the wall with the glyph panel at the bottom of the well between them, so the depth is
            // something the light and the viewing angle agree about instead of a trick of tone.
            //
            // The wall cannot be cut into, which is what decides the direction. Everything at local
            // -Z is behind an opaque wall and simply invisible, so the well is built OUT of the
            // surface. `lip` is therefore both how far the fixture protrudes and how deep the recess
            // reads - shallow, because a deep box at head height on a corridor wall stops being a
            // recess and becomes a shelf.
            float mouth = cubeSize + 0.10f;    // the opening: 5cm of clearance round the cube
            const float lip = 0.16f;           // how far the rim stands proud = how deep it reads
            const float rimBand = 0.20f;       // the width of the rim itself
            float frameSize = mouth + 2f * rimBand;

            Material rimMat = MakeColorMaterial("SymbolSlotFrame", new Color(0.10f, 0.10f, 0.12f));

            // Four bars, mitred the way BuildCubeEdging mitres its own and for the same reason: bars
            // cut to one length overlap at the corners with coplanar faces and flicker. The
            // horizontals run the full width and take the corners; the verticals stop against them.
            var rim = new Renderer[4];
            float band = (mouth + rimBand) / 2f;
            rim[0] = Prim(PrimitiveType.Cube, "RimTop", root.transform,
                new Vector3(0f, band, lip / 2f), new Vector3(frameSize, rimBand, lip),
                rimMat, removeCollider: true).GetComponent<Renderer>();
            rim[1] = Prim(PrimitiveType.Cube, "RimBottom", root.transform,
                new Vector3(0f, -band, lip / 2f), new Vector3(frameSize, rimBand, lip),
                rimMat, removeCollider: true).GetComponent<Renderer>();
            rim[2] = Prim(PrimitiveType.Cube, "RimLeft", root.transform,
                new Vector3(-band, 0f, lip / 2f), new Vector3(rimBand, mouth, lip),
                rimMat, removeCollider: true).GetComponent<Renderer>();
            rim[3] = Prim(PrimitiveType.Cube, "RimRight", root.transform,
                new Vector3(band, 0f, lip / 2f), new Vector3(rimBand, mouth, lip),
                rimMat, removeCollider: true).GetComponent<Renderer>();

            // The floor of the well, carrying the glyph. A cube rather than a quad: every face of a
            // Unity cube takes the whole texture, so the one facing the room shows the glyph the
            // right way round with nothing to configure. Sized to the mouth, so the well has no
            // visible seam between its walls and its back.
            Prim(PrimitiveType.Cube, "Plate", root.transform,
                new Vector3(0f, 0f, 0.015f), new Vector3(mouth, mouth, 0.03f), faceMat,
                removeCollider: true);

            // Where the cube ends up. Deep enough that it is INSIDE the well rather than resting on
            // its lip - a third of the cube is past the rim, and the back of it is inside the wall,
            // which is the one thing this project can do that a real hollow cannot: the wall is the
            // occluder, so the cube looks buried rather than clipped. It also covers its own symbol
            // once it is home, which is the correct thing for it to do - that pairing has been
            // answered by the time anything is placed.
            GameObject seat = new GameObject("Seat");
            seat.transform.SetParent(root.transform, false);
            seat.transform.localPosition = new Vector3(0f, 0f, cubeSize * 0.30f);

            // A wall recess is stood IN FRONT OF; a floor recess is stood OVER. The box below is
            // sized for whichever this is - wide on the two axes now horizontal, tall enough on the
            // third to catch a standing player regardless of exactly how close they walk up.
            BoxCollider reach = root.AddComponent<BoxCollider>();
            reach.isTrigger = true;
            if (floorMounted)
            {
                reach.center = new Vector3(0f, 0f, cubeSize * 0.6f);
                reach.size = new Vector3(3.4f, 3.4f, 3.0f);
            }
            else
            {
                reach.center = new Vector3(0f, -1.5f, cubeSize * 0.6f);
                reach.size = new Vector3(3.4f, 3.5f, 3.0f);
            }

            SymbolSlot slot = root.AddComponent<SymbolSlot>();
            slot.seat = seat.transform;
            slot.plateRenderers = rim;
            slot.audioSource = MakeSource(root.transform, "SlotAudio", 1f, 0.8f);
            slot.insertClip = LoadClip(SfxDir, "sfx_floor_button_press");

            // Presented clear of the mouth before it slides home: the cube is 1m and sits with its
            // centre cubeSize*0.30 inside the seat, so it has to start far enough out that no part of
            // it begins already through the rim. The tilt is small and deliberately not symmetrical -
            // a cube that straightens up as it goes in reads as placed by a hand, where one that
            // arrives square reads as a machine feeding it.
            slot.insertOffer = new Vector3(0f, 0f, cubeSize * 0.55f + lip);
            slot.insertTilt = new Vector3(-7f, 13f, 4f);
            slot.insertDuration = 0.45f;
            return slot;
        }

        // One cube, where the room was disturbed - on the floor, or on another cube. Everything here
        // is the chess piece over again - trigger, CarryableItem, hand pose - except that what
        // identifies it is suspended inside it, and its body is glass in a steel frame rather than
        // the recess's opaque ink (see BuildCubeRoom).
        //
        // `floorY` stays half a cube whatever `level` says, and that is right rather than an
        // oversight: a stack is how the room was FOUND, not a property of the cube. Take the top one
        // and put it down and it belongs on the floor; only the loop's own ReturnToOrigin rebuilds
        // the tower, which is exactly the rewind it is there to do.
        private static CarryableItem BuildSymbolCube(Transform parent, SymbolSpec spec, Material glassMat,
                                                     Material coreMat, Sprite icon, float cubeSize,
                                                     Vector3 spot, float yaw, int level)
        {
            // World metres of reach past a face, NOT a multiple of the cube: the reach an arm has is
            // the same whatever size the thing is, so both numbers below are divided back out by
            // cubeSize rather than written as a ratio that silently changes meaning every time the
            // cube is resized. Taller than it is wide because the trigger has to overlap a STANDING
            // player's capsule, whose bounds start well above a knee-high cube's lid.
            const float reachOut = 0.45f;
            const float reachUp = 0.60f;
            // World thickness of one edge of the silver frame, same reasoning.
            const float edge = 0.055f;

            // `level` 0 stands on the floor, 1 stands on the cube below it. Stacked by a WHOLE EDGE
            // THICKNESS more than the cube's own height, so the upper cube's bottom bars come to rest
            // ON the lower cube's top bars: each bar straddles its edge, so stacking by exactly
            // cubeSize would put the two frames through each other with coplanar faces - the same
            // flicker BuildCubeEdging mitres its own corners to avoid - and the two glass faces in
            // the same plane on top of it.
            GameObject cube = Prim(PrimitiveType.Cube, spec.id, parent,
                new Vector3(spot.x, cubeSize / 2f + level * (cubeSize + edge), spot.z),
                Vector3.one * cubeSize, glassMat, removeCollider: true);
            // Turned where it fell, about its own vertical only: a cube tipped onto a corner would
            // read as physics that has run, and nothing here simulates.
            cube.transform.localRotation = Quaternion.Euler(0f, yaw, 0f);

            BuildCubeEdging(cube.transform, edge / cubeSize);

            // THE SYMBOL, SUSPENDED INSIDE THE GLASS rather than printed on its faces - by request,
            // 2026-08-13. A solid core rather than the glyph alone floating in the middle: the glyph
            // alone means an alpha-clipped shell whose near and far faces are both visible through
            // each other, which reads as two symbols rather than one seen in depth. Opaque, so the
            // near face hides the far one and there is exactly one mark to read from any direction -
            // including from ABOVE, which a flat wafer could not answer and which matters in a room
            // whose cubes are on the floor and stacked. Opaque also settles the sort order for free:
            // it draws in the opaque queue with depth, and the glass blends over it afterwards.
            Prim(PrimitiveType.Cube, "Core", cube.transform, Vector3.zero, Vector3.one * 0.58f,
                 coreMat, removeCollider: true);

            BoxCollider trigger = cube.AddComponent<BoxCollider>();
            trigger.isTrigger = true;
            trigger.size = new Vector3(1f + 2f * reachOut / cubeSize,
                                       1f + 2f * reachUp / cubeSize,
                                       1f + 2f * reachOut / cubeSize);

            // SOLID, so a metre-plus of glass is walked around rather than through. On a CHILD, and
            // that is load-bearing rather than tidiness: CarryableItem takes `GetComponent<Collider>()`
            // as its reach trigger, so a solid box added to this same object would be a coin toss over
            // which of the two becomes the reach - the trap BuildKeyPlinth documents. Handed to the
            // item as `blocker` so every path that puts the cube in a hand can switch it off; see
            // CarryableItem.blocker for why holding a solid box would be a bug in two directions.
            //
            // Sized to the glass itself, not to the frame that stands proud of it by half an edge:
            // the frame is a detail you can put a shoulder through without noticing, and matching the
            // collider to the silhouette a player reads as "the cube" is what makes it feel solid.
            GameObject solid = new GameObject("Blocker");
            solid.transform.SetParent(cube.transform, false);
            BoxCollider block = solid.AddComponent<BoxCollider>();

            CarryableItem item = cube.AddComponent<CarryableItem>();
            item.blocker = block;
            item.itemId = spec.id;
            item.displayName = spec.name.ToUpperInvariant();
            item.icon = icon;
            item.floorY = cubeSize / 2f;
            item.handLocalPosition = HandPoseFor(cubeSize);
            // Off-axis on two axes, so what is in the hand is seen as a CUBE - square-on it is a
            // square, which is one of the six symbols and would read as a mistake.
            item.handLocalEuler = new Vector3(-20f, 28f, 0f);
            // ITS OWN SIZE. It used to be held at 0.20 - the size the cube was before it grew - so a
            // metre of glass would not fill the screen. It is a metre of glass, and it is carried
            // like one now: further out, lower, and genuinely in the way. That is the trade, taken
            // deliberately (2026-08-13). HandPoseFor is where it is tuned.
            item.handLocalScale = Vector3.one * cubeSize;
            return item;
        }

        // `upper` rests on `lower` and drops to the floor when it stops doing so. The values live
        // here and the mechanism lives in FallingItem, like every other pairing in this file.
        //
        // The landing borrows the floor pads' clunk, pitched well down. It is the only impact in the
        // library and a metre of glass hitting a floor in silence is worse than a borrowed sound -
        // see docs/audio.md on the pads themselves.
        private static void StandOn(CarryableItem upper, CarryableItem lower)
        {
            FallingItem stack = AddFalling(upper);
            stack.support = lower;
        }

        // WHERE A HELD OBJECT SITS, from how big it is. Held objects are their TRUE SIZE now - the
        // shrink-to-fit that every carryable used to carry is gone - so a big one has to be held
        // further out and lower, the way a person carries a box rather than a key.
        //
        // Grows SUB-LINEARLY with size on purpose. Scaling the distance in step with the object
        // would put everything at the same angular size, which is exactly what the old shrink did by
        // another route: a metre of glass would look like the 20cm prop it used to be. These
        // coefficients keep a small object at roughly the pose it always had and push a large one out
        // far enough to be seen at all, while still reading as large.
        //
        // `size` is the object's world size across, and the caller knows it because it built it.
        private static Vector3 HandPoseFor(float size)
        {
            return new Vector3(0.28f + size * 0.20f,
                              -(0.22f + size * 0.40f),
                               0.45f + size * 0.55f);
        }

        // Everything that can be carried can be DROPPED, and a dropped object falls. One component
        // per carryable, added here so a new carryable anywhere in the building gets it without its
        // author having to know - the same reason the reflection-probe sweep walks the scene rather
        // than trusting every room to opt in.
        //
        // Idempotent: the cube room's towers wire their own support before this runs, and get it
        // back rather than a second copy.
        private static FallingItem AddFalling(CarryableItem item)
        {
            FallingItem fall = item.GetComponent<FallingItem>();
            if (fall != null) return fall;

            fall = item.gameObject.AddComponent<FallingItem>();
            fall.item = item;
            // Its own clip, and it had to be: the landing borrowed the floor pads' clunk pitched
            // down, and that clip is a struck C6 left to ring for a second, so a dropped object
            // announced itself like a doorbell. Pitching a pitched sound down does not stop it being
            // pitched. `sfx_item_drop` is 85ms with its energy under 500Hz - see Tools/generate_sfx.
            fall.audioSource = MakeSource(item.transform, "FallAudio", 1f, 0.85f);
            // A fixed offset PER OBJECT rather than a random one per landing: two cubes off one
            // tower must not land in unison, and the build has to be reproducible. Derived from the
            // name, so an object's own thud is the same weight every iteration - which is a thing
            // the player can learn, where a per-landing shuffle is just noise.
            fall.audioSource.pitch = 0.94f + (Mathf.Abs(item.name.GetHashCode()) % 13) * 0.01f;
            fall.landClip = LoadClip(SfxDir, "sfx_item_drop");
            return fall;
        }

        // TELLS EVERY CARRYABLE UNDER `root` WHICH STOREY IT IS ON. One call per cycle subtree,
        // rather than a line in every builder that makes a carryable.
        //
        // `CarryableItem.floorY` is the object's own half-thickness above ITS OWN floor, and that
        // number is genuinely the object's business. Which floor is not - it is a property of where
        // the thing was placed, so it is set here, in one sweep, at the point the storey is already
        // known. Asking each builder to remember to add it is asking for exactly one of them to
        // forget, and the failure mode is silent: the object falls through the floor to the height of
        // the storey above and hangs there.
        //
        // The ground storey needs no call at all - `floorBaseY` defaults to zero, which is why every
        // value in this file could be written as a bare half-height for as long as there was one
        // level, and why none of them had to change when there stopped being.
        private static int SetFloorBase(Transform root, float floorY)
        {
            if (root == null) return 0;

            CarryableItem[] items = root.GetComponentsInChildren<CarryableItem>(includeInactive: true);
            foreach (CarryableItem item in items) item.floorBaseY = floorY;

            Debug.Log($"[SceneBuilder] Floor base {floorY:0.###} set on {items.Length} carryables under {root.name}");
            return items.Length;
        }

        private static int AddFallingToEveryCarryable()
        {
            int added = 0;
            CarryableItem[] items = UnityEngine.Object.FindObjectsByType<CarryableItem>(
                FindObjectsInactive.Include, FindObjectsSortMode.None);

            foreach (CarryableItem item in items)
                if (item.GetComponent<FallingItem>() == null) { AddFalling(item); added++; }

            Debug.Log($"[SceneBuilder] Falling: {items.Length} carryables, {added} newly wired");
            return added;
        }

        // The silver frame: the twelve edges of the cube, in polished steel, on a glass body. Glass
        // alone has no silhouette of its own in a white room - it is only what it reflects, so from
        // the wrong angle a clear cube is a faint smudge on a white floor and the symbol on it looks
        // like it is floating. The frame is what draws the SHAPE, and it does it in the one material
        // this project can already light convincingly (see MakePolishedMetalMaterial and SS3 on why a
        // metal here is entirely its reflections).
        //
        // `t` is the edge thickness in the cube's own LOCAL units, so a caller expressing it in metres
        // divides by the cube's size once and the frame stays in proportion at any size - including in
        // the hand, where the whole object is rescaled to 0.20.
        //
        // The bars are MITRED rather than all cut to one length, and the reason is z-fighting rather
        // than fussiness: twelve equal bars overlap inside each corner with coplanar side faces, which
        // flicker. So one axis takes the corners outright - X, run the full width and half an edge
        // proud at each end - and the other eight stop exactly where it starts. Faces then touch
        // without ever overlapping.
        private static void BuildCubeEdging(Transform cube, float t)
        {
            Material steel = MakePolishedMetalMaterial(
                "CubeEdgeSteel", new Color(0.88f, 0.89f, 0.93f), 0f);

            // Every bar sits astride its edge - half of it inside the glass, half proud - so the frame
            // catches a highlight along its length instead of lying flush and vanishing into the face
            // it is drawn on.
            var lengths = new[]
            {
                new Vector3(1f + t, t, t),
                new Vector3(t, 1f - t, t),
                new Vector3(t, t, 1f - t),
            };

            for (int axis = 0; axis < 3; axis++)
            {
                for (int corner = 0; corner < 4; corner++)
                {
                    float a = (corner & 1) == 0 ? -0.5f : 0.5f;
                    float b = (corner & 2) == 0 ? -0.5f : 0.5f;
                    Vector3 pos = axis == 0 ? new Vector3(0f, a, b)
                                : axis == 1 ? new Vector3(a, 0f, b)
                                            : new Vector3(a, b, 0f);

                    Prim(PrimitiveType.Cube, $"Edge{axis}{corner}", cube, pos, lengths[axis], steel,
                         removeCollider: true);
                }
            }
        }

        // A filled disc and a filled square, for the two escape objects whose shape IS their name.
        // Deliberately plain: the row they appear in already says which is which by tint, and an
        // outline at 58px closes up under the filter.
        private static Sprite SphereIcon()
        {
            var icon = new IconCanvas(128);
            icon.Disc(new Vector2(0.5f, 0.5f), 0.34f);
            return SaveSprite(icon, "icon_key_sphere");
        }

        // A SQUARE THAT READS AS A CUBE. It was a plain filled square, which names a shape rather
        // than an object - and the thing it labels is a cube.
        //
        // The lines are CUT OUT rather than drawn on: these icons are a single colour with an alpha
        // mask, so there is no second colour to draw with, and a hole is the only mark available. It
        // shows through as whatever is behind - the pale HUD disc, the wall - which is the white line
        // asked for.
        //
        // Two lines from the top-left corner, one across and one down, which is the minimum that
        // makes a square read as a box seen corner-on: they separate a top face and a side face from
        // the front one without changing the silhouette.
        private static Sprite SquareIcon()
        {
            var icon = new IconCanvas(128);
            Vector2 mid = new Vector2(0.5f, 0.5f);
            const float half = 0.300f;
            const float inset = 0.105f;      // how deep the two implied faces are
            const float line = 0.021f;

            icon.Bar(mid, new Vector2(half, half));

            // The top face's lower edge: across, stopping short of the right side so it meets the
            // other line's corner rather than cutting the square in two.
            icon.Bar(mid + new Vector2(inset / 2f, half - inset),
                     new Vector2(half - inset / 2f, line), 0f, -1f);
            // The side face's inner edge: down from that corner.
            icon.Bar(mid + new Vector2(-half + inset, -inset / 2f),
                     new Vector2(line, half - inset / 2f), 0f, -1f);
            // And the short diagonal at the corner where the two faces meet, which is what tells the
            // eye they are receding rather than being panels painted on a flat square.
            for (int i = 0; i < 7; i++)
            {
                float t = i / 6f;
                icon.Bar(mid + new Vector2(-half + inset * (1f - t), half - inset * (1f - t)),
                         new Vector2(line, line), 0f, -1f);
            }
            return SaveSprite(icon, "icon_key_square");
        }

        // The yellow triangle in silhouette. A plain solid triangle rather than an outline: the row
        // it appears in is 58px, the other two glyphs there are solid, and an outline at that size is
        // two thin lines that close up under the bilinear filter.
        private static Sprite TriangleIcon()
        {
            var icon = new IconCanvas(128);
            icon.Shape(p =>
            {
                if (p.y < 0.22f || p.y > 0.80f) return false;
                // 0 at the apex, 1 at the base - so the half-width opens out on the way down.
                float k = (0.80f - p.y) / 0.58f;
                return Mathf.Abs(p.x - 0.5f) <= 0.40f * k;
            });
            return SaveSprite(icon, "icon_key_triangle");
        }

        // The nightstand and the drawer in it, built here rather than imported.
        //
        // It used to be nightstand.glb with a generated drawer bolted to its front face, because the
        // model bakes its whole body into one mesh and has no drawer node to pull. That read exactly
        // as what it was: a pale slab stuck on a dark cabinet, sliding out to reveal the two drawer
        // fronts the model already had painted on it. There is no recess to import, so the carcass
        // has to be built to have one - and the same numbers then cut the opening and fill it, which
        // is the whole reason the two halves are one method.
        //
        // The model's lamp and pot are rebuilt from primitives here; they were the reason it was
        // chosen and the room would be barer without them. Geometry only, no Light: the shadow atlas
        // is sized for exactly the four fixtures that cast, and a fifth would silently halve them.
        //
        // The footprint reproduces the model's measured bounds - min (-1.23, 0, 1.16), max
        // (-0.67, 0.59, 1.52) - so nothing else in the room has to move.
        // pinItemId: the id the three pins share. A parameter rather than a constant because a second
        // cycle gets its own nightstand, and `ItemRegistry` maps an id to ONE socket with the last
        // writer winning - two cycles' pins under one id would be a single six-deep supply that
        // either cycle's ghosts could draw from.
        // A CHEST OF DRAWERS: two bays, and both of them open.
        //
        // Built rather than imported, for the reason the nightstand is: a drawer that opens needs its
        // front to be a separate object from the carcass, and every imported chest is one mesh with
        // drawer fronts modelled into it. The nightstand deliberately has ONE opening bay and a shelf
        // below, because "a second front that does not move is a lie" - this is the other answer to
        // that, where both fronts move and neither is lying.
        //
        // **NOTHING IS IN IT**, and that is deliberate rather than unfinished: what goes in a drawer
        // belongs to a puzzle that has not been designed, and the point of building the container now
        // is to have somewhere for that to go. Both bays are wired as `GhostInteractable`s from the
        // start anyway - the moment anything IS in one, a past self has to be able to open it, and
        // adding a bit later is the one thing `RecordedFrame.signals` makes awkward (CLAUDE.md §1.6).
        //
        // Everything here is LOCAL to the unit, including the drawers, which are children of it. That
        // is not a style choice: the same code written against world positions is what put cycle 2's
        // nightstand drawer fifty metres from its own carcass.
        private static Drawer[] BuildDresser(Transform parent, string name, Vector3 localPosition,
                                             float yaw, bool withLamp = false,
                                             bool withBilliards = false)
        {
            const float w = 0.82f, d = 0.44f, h = 0.86f;
            const float panel = 0.018f;     // carcass stock
            const float legH = 0.09f;       // floor to the underside of the case
            const float topT = 0.034f;      // the slab the cube stands on

            const float caseBottom = legH;
            const float caseTop = h - topT;
            // Two equal bays with the divider's own thickness taken out between them, so the pair
            // fills the carcass exactly rather than leaving a strip of nothing at the bottom.
            const float bayH = (caseTop - caseBottom - panel) / 2f;

            Material wood = MakeColorMaterial("NightstandWood", new Color(0.14f, 0.085f, 0.06f));
            SetSmoothness(wood, 0.25f);
            Material brass = MakeColorMaterial("DrawerHandle", new Color(0.72f, 0.55f, 0.25f));
            SetSmoothness(brass, 0.55f);

            GameObject unit = new GameObject(name);
            unit.transform.SetParent(parent, false);
            unit.transform.localPosition = localPosition;
            unit.transform.localRotation = Quaternion.Euler(0f, yaw, 0f);

            // Carcass: five boards with the FRONT LEFT OFF. That absence is the two openings.
            Prim(PrimitiveType.Cube, "Top", unit.transform, new Vector3(0f, h - topT / 2f, 0f),
                new Vector3(w + 0.03f, topT, d + 0.02f), wood);
            Prim(PrimitiveType.Cube, "Bottom", unit.transform, new Vector3(0f, caseBottom + panel / 2f, 0f),
                new Vector3(w, panel, d), wood);
            Prim(PrimitiveType.Cube, "Back", unit.transform,
                new Vector3(0f, (caseBottom + caseTop) / 2f, d / 2f - panel / 2f),
                new Vector3(w, caseTop - caseBottom, panel), wood);
            Prim(PrimitiveType.Cube, "SideLeft", unit.transform,
                new Vector3(-w / 2f + panel / 2f, (caseBottom + caseTop) / 2f, 0f),
                new Vector3(panel, caseTop - caseBottom, d), wood);
            Prim(PrimitiveType.Cube, "SideRight", unit.transform,
                new Vector3(w / 2f - panel / 2f, (caseBottom + caseTop) / 2f, 0f),
                new Vector3(panel, caseTop - caseBottom, d), wood);
            Prim(PrimitiveType.Cube, "Divider", unit.transform,
                new Vector3(0f, caseBottom + bayH + panel / 2f, 0f),
                new Vector3(w - panel * 2f, panel, d - panel), wood);

            for (int i = 0; i < 4; i++)
            {
                float lx = (i % 2 == 0 ? -1f : 1f) * (w / 2f - 0.04f);
                float lz = (i < 2 ? -1f : 1f) * (d / 2f - 0.04f);
                Prim(PrimitiveType.Cube, $"Leg{i}", unit.transform, new Vector3(lx, legH / 2f, lz),
                    new Vector3(0.048f, legH, 0.048f), wood);
            }

            Drawer upper = BuildDresserBay(unit.transform, name + "_DrawerUpper",
                caseTop - bayH, caseTop, w, d, panel, wood, brass);
            Drawer lower = BuildDresserBay(unit.transform, name + "_DrawerLower",
                caseBottom, caseBottom + bayH, w, d, panel, wood, brass);

            // AND NOW THERE IS SOMETHING IN IT. The comment above about both bays being empty on
            // purpose stood for four days; room2-0 is the puzzle that was waiting for them. The tray
            // geometry is recomputed rather than handed back out of `BuildDresserBay`, because it is
            // three lines of arithmetic off numbers this method already owns and returning a fourth
            // thing from a bay builder to describe the inside of a drawer would be worse.
            if (withBilliards)
                BuildBilliardBalls(upper, lower, w - panel * 2f - 0.01f, bayH - 0.01f, d * 0.76f);

            // AND SOMETHING ON TOP THE PLAYER CAN PICK UP. The nightstand's cube is scenery - a model
            // placed with no collider, which cannot be taken - and this is the opposite: a carryable
            // in its own right, standing on the chest the way the pin stands in the drawer.
            BuildDresserCube(unit.transform, name + "_Cube", new Vector3(w * 0.26f, h, -d * 0.08f));

            // The bedside lamp, when this chest is standing where a nightstand was. Scenery, and the
            // only thing carried over from the unit it replaced - a bed with nothing lit beside it
            // reads as a room nobody sleeps in.
            if (withLamp) BuildNightstandLamp(unit.transform, new Vector3(-w * 0.28f, h, 0.02f));

            return new[] { upper, lower };
        }

        // ONE BAY of the chest above: the tray that slides, the front that carries it, and the volume
        // that answers E. Modelled on the nightstand's single drawer, which is where every number in
        // here was settled.
        private static Drawer BuildDresserBay(Transform unit, string name, float bayBottom, float bayTop,
                                              float w, float d, float panel,
                                              Material wood, Material brass)
        {
            float trayD = d * 0.76f;
            float frontW = w - panel * 2f - 0.01f;
            float frontH = (bayTop - bayBottom) - 0.01f;

            // The drawer's own root sits at the CENTRE OF ITS FRONT PANEL rather than at the unit's
            // origin, because `Drawer.HintAnchor` is the body - anchored at the floor, the E prompt
            // would float at the player's feet instead of on the front they are about to pull.
            GameObject root = new GameObject(name);
            root.transform.SetParent(unit, false);
            root.transform.localPosition =
                new Vector3(0f, (bayBottom + bayTop) / 2f, -d / 2f + panel / 2f);

            GameObject bodyGO = new GameObject("DrawerBody");
            bodyGO.transform.SetParent(root.transform, false);

            Material liner = MakeColorMaterial("DrawerLiner", new Color(0.60f, 0.58f, 0.55f));
            SetSmoothness(liner, 0.15f);

            Prim(PrimitiveType.Cube, "Front", bodyGO.transform, Vector3.zero,
                new Vector3(frontW, frontH, panel), wood, removeCollider: true);
            Prim(PrimitiveType.Cube, "TrayBase", bodyGO.transform,
                new Vector3(0f, -frontH / 2f + 0.008f, trayD / 2f),
                new Vector3(frontW - 0.02f, 0.016f, trayD), liner, removeCollider: true);
            Prim(PrimitiveType.Cube, "TrayLeft", bodyGO.transform,
                new Vector3(-frontW / 2f + 0.008f, 0f, trayD / 2f),
                new Vector3(0.016f, frontH * 0.8f, trayD), liner, removeCollider: true);
            Prim(PrimitiveType.Cube, "TrayRight", bodyGO.transform,
                new Vector3(frontW / 2f - 0.008f, 0f, trayD / 2f),
                new Vector3(0.016f, frontH * 0.8f, trayD), liner, removeCollider: true);
            Prim(PrimitiveType.Cube, "TrayBack", bodyGO.transform, new Vector3(0f, 0f, trayD),
                new Vector3(frontW - 0.02f, frontH * 0.8f, 0.016f), liner, removeCollider: true);
            Prim(PrimitiveType.Cube, "Pull", bodyGO.transform,
                new Vector3(0f, 0f, -panel / 2f - 0.012f),
                new Vector3(frontW * 0.42f, 0.016f, 0.024f), brass, removeCollider: true);

            BoxCollider trigger = root.AddComponent<BoxCollider>();
            trigger.isTrigger = true;
            trigger.size = new Vector3(w + 0.9f, 1.0f, 1.4f);

            Drawer drawerComp = root.AddComponent<Drawer>();
            drawerComp.drawerBody = bodyGO.transform;
            drawerComp.audioSource = MakeSource(root.transform, "DrawerAudio", 1f, 0.8f);
            drawerComp.openClip = LoadClip(SfxDir, "sfx_drawer_open");
            // AND E SHUTS IT AGAIN. Safe here in the way it is not on cycle 1's nightstand: these bays
            // are empty, so a past self's replayed pull closing one costs nothing. See Drawer.canClose
            // for what turning this on for a drawer that HOLDS something would mean.
            //
            // No close clip exists, so `Drawer` pitches the open one down for the return - the same
            // runners in the same carcass, which is the one case where pitching a clip is honest.
            // **CLOSABLE AGAIN, 2026-08-20, BY EXPLICIT REQUEST, AND THE COST IS KNOWN AND ACCEPTED.**
            //
            // It was turned off earlier the same day because the bays stopped being empty. A closable
            // drawer makes E a TOGGLE, `Drawer.SetGhostSignal` reproduces the PULL rather than the
            // resulting state, and so the drawer's openness is the PARITY of how many past selves
            // have reached for it - one ghost opens it, two leave it shut, three open it again. Every
            // ball inside gates on `IsFullyOpen`, so on even iterations a ghost's take, and with it
            // that ghost's whole delivery, silently does not happen.
            //
            // WHAT BUYS THAT BACK: a drawer that cannot be shut is open FOREVER, and it stands
            // between the player and the other bay. `Drawer.WantsInteractHint` keeps an OPEN closable
            // drawer in the aim contest, and its front has slid 0.23m nearer the eye, so it wins the
            // press from in front of the bay below it - play reported the lower bay as unopenable.
            // Being able to shut it is the only way out of that from inside the game.
            //
            // The trade was made deliberately and stated: a drawer found shut is an errand that
            // FAILS, which is a legible outcome the player can see and undo by pulling it open,
            // where a bay that can never be opened is not.
            drawerComp.canClose = true;
            // Two thirds out, like the nightstand's: leaving a third of the tray inside the carcass is
            // what reads as a drawer rather than as a tray hanging in mid-air.
            drawerComp.openLocalOffset = new Vector3(0f, 0f, -trayD * 0.68f);
            return drawerComp;
        }

        // THE CUBE ON THE CHEST, and unlike the nightstand's it can be picked up.
        //
        // THE RUBIK'S CUBE THE NIGHTSTAND USED TO HOLD, and now it can be picked up.
        //
        // The same `rubiks_cube.glb` at the same size it was - about 90mm, which is what the old
        // `PlaceModel(..., 0.8f)` came out at. What changes is only that it is a carryable rather than
        // scenery: the nightstand's was placed with `addBoxCollider: false`, so it could be looked at
        // and never touched.
        //
        // NOT through `PlaceModel`, which corrects a WORLD-space delta into a localPosition. That is
        // safe under an unrotated parent at the origin and wrong everywhere else - it is the same
        // mistake that drew every bucket 1.6m behind itself, and this chest hangs off a furniture
        // holder that is yawed 180 and a storey down. Measured in the ROOT's own frame instead, with
        // the helper that exists for exactly this (`ModelBounds`).
        private static void BuildDresserCube(Transform unit, string name, Vector3 topLocal)
        {
            // 90mm was a keyring trinket on top of a chest - hard to see and harder to aim at, and
            // play reported both. A Rubik's cube is 57mm in life; this is deliberately larger than
            // life because it is an OBJECT in a puzzle game, and the thing it competes with for a
            // press is a drawer front the size of a dinner tray.
            const float size = 0.16f;

            GameObject root = new GameObject(name);
            root.transform.SetParent(unit, false);
            // Standing ON the top rather than in it: the object's own half-height above the slab.
            root.transform.localPosition = topLocal + new Vector3(0f, size / 2f, 0f);

            GameObject source = AssetDatabase.LoadAssetAtPath<GameObject>($"{FurnitureDir}/rubiks_cube.glb");
            GameObject model = (GameObject)PrefabUtility.InstantiatePrefab(source, root.transform);
            model.name = "Visual";
            model.transform.localPosition = Vector3.zero;
            // ITS OWN IMPORT ROTATION IS LEFT ALONE. The prefab root carries (270, 0, 0) to bring a
            // Z-up export into Unity's Y-up; forcing identity stands the cube on a corner, which is
            // what the nightstand's version had to pass a rotation in to avoid.

            Bounds raw = ModelBounds(root.transform, model);
            float longest = Mathf.Max(raw.size.x, Mathf.Max(raw.size.y, raw.size.z));
            float modelScale = size / Mathf.Max(0.0001f, longest);
            model.transform.localScale = Vector3.one * modelScale;
            // CENTRED ON THE ROOT, because `floorY` below is half the object's height - which is only
            // true if the root sits at the middle of it.
            model.transform.localPosition = -raw.center * modelScale;

            GameObject solid = new GameObject("Blocker");
            solid.transform.SetParent(root.transform, false);
            BoxCollider block = solid.AddComponent<BoxCollider>();
            block.size = Vector3.one * size;

            // TIGHT, AND LIFTED. The old volume was the cube plus 0.4m in every direction, which from
            // a 90mm object is a 0.5m ball - and it hung down over the drawer fronts underneath, so
            // standing at the chest put the player inside the cube's reach and the drawer's at once.
            // The two then argued about the press every time. Kept generous sideways, where nothing
            // competes, and cut back below, where the drawers are.
            BoxCollider reach = root.AddComponent<BoxCollider>();
            reach.isTrigger = true;
            reach.size = new Vector3(size + 0.34f, size + 0.20f, size + 0.34f);
            reach.center = new Vector3(0f, size * 0.35f, 0f);

            CarryableItem item = root.AddComponent<CarryableItem>();
            item.blocker = block;
            item.itemId = CycleTwoBlockItemId;
            item.displayName = "CUBE";
            item.icon = SquareIcon();
            // Its own half-height above whatever floor it ends up on - which is NOT where it starts.
            // It begins on the chest, and `FallingItem` leaves it there because nothing dropped it
            // (CarryableItem.Released); put it down and it comes to rest at this height instead.
            item.floorY = size / 2f;
            item.handLocalPosition = HandPoseFor(size);
            // The root is unscaled and so is the hand anchor, so this only says "do not change it".
            item.handLocalScale = Vector3.one;
            item.audioSource = MakeSource(root.transform, "PickupAudio", 1f, 0.85f);
            item.pickupClip = LoadClip(SfxDir, "sfx_item_pickup");
            // The heaviest thing one hand can carry to room2-7, and the only one of its kind.
            MakeWeighable(item, WeightCube);
        }

        // NINE BILLIARD BALLS, SPILLED ACROSS BOTH TRAYS OF THE CHEST - and four of them are the
        // keys to room2-0.
        //
        // WHY NINE AND NOT SIXTEEN. The four the puzzle wants are 2, 3, 4 and 5, so the decoys have to
        // reach past 5 or the answer is "the ones that are there"; 1 and 6, 7, 8 and the cue ball do
        // that, and a drawer that has to be searched for a number is a drawer with a handful in it
        // rather than a rack. Sixteen would also be sixteen more E fixtures a square apart in a volume
        // the two drawer fronts already contest.
        //
        // ONE ID EACH, which is the opposite of every other multiple object in this building. Pins,
        // buckets, ducks and beach balls are SUPPLIES - an id naming several interchangeable things -
        // because a recorded "took a Tool" only ever meant "a free one". Here which one is the entire
        // question, so nine ids with one member each: a pedestal's socket names the ball it wants and
        // `ItemRegistry` can never hand it a different one.
        //
        // NO `Weighable`, AND THAT IS DELIBERATE RATHER THAN FORGOTTEN. Room2-7's target of 26.7kg has
        // exactly one solution across everything cycle 2 can carry - one duck, one beach ball, one
        // full bucket, one axe, one cube - with the nearest miss 0.1kg away. A ball worth anything at
        // all destroys that: at a real 0.17kg the search finds FORTY-NINE ways to make the number, and
        // at 0.16 or 0.20 it is much the same, because nine small addends fill every gap the coarse
        // weights leave. The scale's own sign already names the five things it accepts, so a ball
        // reading zero is what that sign says rather than a lie it tells.
        private static CarryableItem[] BuildBilliardBalls(Drawer upper, Drawer lower,
                                                          float frontW, float frontH, float trayD)
        {
            string path = PlayDir + "/billiard_balls.glb";
            GameObject source = AssetDatabase.LoadAssetAtPath<GameObject>(path);
            if (source == null)
            {
                Debug.LogError($"[SceneBuilder] {path} is missing - room2-0 has no keys and cannot "
                             + "be finished.");
                return new CarryableItem[0];
            }

            // INSTANTIATED ONCE AND ROBBED, like the chess set. Every ball in this file is a separate
            // node with its own textured material sitting at the origin on top of all the others, so
            // "one ball" is one child pulled out of the set - and pulling a child out of a prefab
            // instance is exactly the restructuring Unity refuses, hence the unpack.
            GameObject set = (GameObject)PrefabUtility.InstantiatePrefab(source);
            PrefabUtility.UnpackPrefabInstance(set, PrefabUnpackMode.Completely,
                                               InteractionMode.AutomatedAction);

            float y = -frontH / 2f + 0.016f + BilliardBallSize / 2f;

            Sprite icon = BilliardIcon();
            var built = new System.Collections.Generic.List<CarryableItem>();

            foreach (var spec in BilliardPlan)
            {
                Transform node = FindChildByName(set.transform, spec.node);
                if (node == null)
                {
                    Debug.LogError($"[SceneBuilder] billiard_balls.glb has no node '{spec.node}' - "
                                 + "a re-export has renamed the balls.");
                    continue;
                }

                Drawer drawer = spec.top ? upper : lower;
                built.Add(MakeBilliardBall(node, drawer, spec.id,
                    new Vector3(spec.x, y, spec.z), spec.yaw, icon));
            }

            Object.DestroyImmediate(set);
            Debug.Log($"[SceneBuilder] Billiards: {built.Count} balls of {BilliardBallSize:0.000}m "
                    + "across both bays of Dresser2_1");
            return built.ToArray();
        }

        // WHICH NINE, AND WHERE EACH ONE LIES. Positions are in the drawer BODY's frame, so the balls
        // ride out with the tray instead of hanging in the air in front of a shut drawer - the same
        // parenting the pins have.
        //
        // Two staggered rows rather than a line, and no two centres closer than 0.17 against a 0.13
        // ball: a drawer somebody tipped balls into rather than a rack, and it still has to be
        // possible to aim at one of them.
        //
        // A FIELD RATHER THAN A LOCAL, because room2-0 reads it too: its four recesses will take a
        // press for any ball in the game (`FinalSlot.offerItemIds`), and that list has to BE this one.
        // Two hand-kept lists of the same nine ids is how a pedestal ends up silently refusing to
        // prompt for a ball that exists.
        private static readonly (string node, string id, bool top, float x, float z, float yaw)[]
            BilliardPlan =
        {
            ("Ball1",      "1",   true,  -0.245f, 0.095f,   24f),
            ("Ball2",      "2",   true,  -0.105f, 0.235f,  -63f),
            ("Ball5",      "5",   true,   0.045f, 0.105f,  141f),
            ("Ball7",      "7",   true,   0.185f, 0.245f,  -17f),
            ("Ball Clube", "Cue", true,   0.295f, 0.115f,   88f),
            ("Ball3",      "3",   false, -0.230f, 0.230f,  -38f),
            ("Ball4",      "4",   false, -0.075f, 0.105f,  112f),
            ("Ball6",      "6",   false,  0.115f, 0.240f,   -9f),
            ("Ball8",      "8",   false,  0.265f, 0.120f,   57f),
        };

        // Every ball id in the game, in the order above. What a room2-0 pedestal entertains a press
        // for - see FinalSlot.offerItemIds.
        private static string[] BilliardIds()
        {
            var ids = new string[BilliardPlan.Length];
            for (int i = 0; i < ids.Length; i++) ids[i] = BilliardIdPrefix + BilliardPlan[i].id;
            return ids;
        }

        // One ball, out of the set and into a drawer.
        private static CarryableItem MakeBilliardBall(Transform node, Drawer drawer, string id,
                                                      Vector3 localPos, float yaw, Sprite icon)
        {
            GameObject root = new GameObject("Billiard_" + id);
            root.transform.SetParent(drawer.drawerBody, false);
            root.transform.localPosition = localPos;

            node.SetParent(root.transform, false);
            node.localPosition = Vector3.zero;
            node.name = "Visual";
            GameObject model = node.gameObject;

            // THE NUMBER UP, AND THE BALL SIZED - both MEASURED off the mesh rather than written
            // down, and in one pass because both answers come from the same vertex list.
            //
            // **NOT `ModelBounds`**, which is what every other model here is sized by and is wrong for
            // this one. That helper transforms the eight CORNERS OF THE MESH'S BOX into the target
            // frame, which is exact for a box and an over-estimate for anything else - and the
            // over-estimate depends on the ROTATION. Scattering nine balls through nine different
            // orientations therefore measured nine different "widths": the first build came out with
            // radii spread 23% apart, which is a drawer of visibly mismatched balls. A sphere has to
            // be measured as a sphere, so this takes the extent of the actual vertices.
            (Vector3 centre, float radius) = OrientBilliardBall(root.transform, model, yaw, -22f);

            float modelScale = radius > 0.0001f ? BilliardBallSize / (2f * radius) : 1f;
            model.transform.localScale = Vector3.one * modelScale;
            // Centred on the root, because `floorY` below is half the ball's height - which is only
            // true if the root sits at the middle of it.
            model.transform.localPosition = -centre * modelScale;

            // The pin's volume, because this is the pin's problem: a small object lying in a drawer
            // that has to be reachable from where a player stands at the chest. Nine of these overlap
            // heavily and that is fine and expected - `ItemRegistry.AimedTakeable` hands the press to
            // whichever ball is nearest the crosshair, which is the same arbitration thirty-two chess
            // pieces a square apart already run on.
            BoxCollider trigger = root.AddComponent<BoxCollider>();
            trigger.isTrigger = true;
            trigger.size = Vector3.one * 0.7f;

            CarryableItem item = root.AddComponent<CarryableItem>();
            item.itemId = BilliardIdPrefix + id;
            item.displayName = "BALL " + (id == "Cue" ? "-" : id);
            item.icon = icon;
            item.floorY = BilliardBallSize / 2f;
            item.handLocalPosition = HandPoseFor(BilliardBallSize);
            // The root is unscaled and so is the drawer body, so this only says "do not change it".
            item.handLocalScale = Vector3.one;
            item.requiresOpenDrawer = drawer;
            // AND A DROP LEAVES THE DRAWER BEHIND. The chest itself, which does not move - the tray
            // does. See CarryableItem.dropParent: a ball put down in room2-0 must not slide 0.22m
            // sideways every time a past self opens a drawer at the other end of the building.
            item.dropParent = drawer.transform.parent;
            item.audioSource = MakeSource(root.transform, "PickupAudio", 1f, 0.8f);
            item.pickupClip = LoadClip(SfxDir, "sfx_item_pickup");
            // NO MakeWeighable - see BuildBilliardBalls.
            return item;
        }

        // WHICH WAY THE PRINTED NUMBER FACES, AND HOW BIG THE BALL IS. Both off the mesh, and in one
        // pass because they read the same vertices.
        //
        // THE NUMBER. It sits at the middle of this model's texture, so the vertex whose UV is nearest
        // (0.5, 0.5) is the point it is printed on - and the sphere being centred on its own origin,
        // that vertex's position IS the outward direction. A written euler would be a guess about the
        // product of the export's axis convention and Unity's import correction, and a ball with its
        // number underneath is indistinguishable from a bug in the drawer.
        //
        // `tilt` leans the ball over once the number is upright, and `yaw` spins it about the room's
        // up afterwards - so the number ends up `tilt` degrees off vertical in a direction `yaw`
        // chooses. That is the scatter: a negative tilt leans it toward the front of the drawer, which
        // is the side the player is standing on.
        //
        // The spin also makes the digit's own upright IRRELEVANT, which is why it is not measured:
        // whatever in-plane rotation it lands at reads as one more ball tipped into a drawer.
        //
        // Returns the ball's centre and radius IN THE ROOT'S FRAME, before scaling. Rotation-invariant
        // by construction, which `ModelBounds` is not - see the call site.
        private static (Vector3 centre, float radius) OrientBilliardBall(
            Transform root, GameObject model, float yaw, float tilt)
        {
            MeshFilter filter = model.GetComponentInChildren<MeshFilter>();
            Mesh mesh = filter != null ? filter.sharedMesh : null;
            Vector3[] verts = mesh != null ? mesh.vertices : null;
            Vector2[] uvs = mesh != null ? mesh.uv : null;

            if (verts == null || verts.Length == 0)
            {
                Debug.LogError($"[SceneBuilder] {model.name}: no readable mesh, so the ball is "
                             + "unmeasured and unoriented.");
                return (Vector3.zero, 0f);
            }

            if (uvs == null || uvs.Length != verts.Length)
            {
                Debug.LogWarning($"[SceneBuilder] {model.name}: no readable UVs, so the number is "
                               + "wherever the export left it. Scatter only.");
                model.transform.localRotation = Quaternion.AngleAxis(yaw, Vector3.up)
                                              * model.transform.localRotation;
            }
            else
            {
                int best = -1;
                float bestSqr = float.MaxValue;
                Vector2 middle = new Vector2(0.5f, 0.5f);
                for (int i = 0; i < uvs.Length; i++)
                {
                    float d = (uvs[i] - middle).sqrMagnitude;
                    if (d >= bestSqr) continue;
                    bestSqr = d;
                    best = i;
                }

                Vector3 outward = filter.transform.TransformPoint(verts[best]) - filter.transform.position;
                Vector3 inRoot = root.InverseTransformDirection(outward);
                if (inRoot.sqrMagnitude > 1e-8f)
                    model.transform.localRotation =
                          Quaternion.AngleAxis(yaw, Vector3.up)
                        * Quaternion.AngleAxis(tilt, Vector3.right)
                        * Quaternion.FromToRotation(inRoot.normalized, Vector3.up)
                        * model.transform.localRotation;
            }

            // MEASURED AFTER THE ROTATION, which costs nothing to say and is free to be true: a
            // radius about a centre does not care how the thing is turned. Stated this way round so
            // the pair is unambiguously the pose that is kept.
            Vector3 min = root.InverseTransformPoint(filter.transform.TransformPoint(verts[0]));
            Vector3 max = min;
            for (int i = 1; i < verts.Length; i++)
            {
                Vector3 v = root.InverseTransformPoint(filter.transform.TransformPoint(verts[i]));
                min = Vector3.Min(min, v);
                max = Vector3.Max(max, v);
            }

            Vector3 centre = (min + max) * 0.5f;
            float radius = 0f;
            for (int i = 0; i < verts.Length; i++)
            {
                Vector3 v = root.InverseTransformPoint(filter.transform.TransformPoint(verts[i]));
                radius = Mathf.Max(radius, (v - centre).magnitude);
            }

            return (centre, radius);
        }

        // Depth-first by exact name. `Transform.Find` walks a PATH and these nodes are two levels down
        // under a machine-generated root, so the path would be a second thing to keep in step with the
        // export.
        private static Transform FindChildByName(Transform root, string name)
        {
            foreach (Transform t in root.GetComponentsInChildren<Transform>(true))
                if (t.name == name) return t;

            return null;
        }

        // A BALL WITH A NUMBER SPOT ON IT, for the HUD line that says what is in the hand. A plain
        // disc would be the beach ball's icon at a different size; the white circle bitten out of the
        // middle is the one mark that separates a billiard ball from every other sphere in this game.
        private static Sprite BilliardIcon()
        {
            var icon = new IconCanvas(128);
            Vector2 mid = new Vector2(0.5f, 0.5f);
            icon.Disc(mid, 0.40f);
            icon.Disc(mid, 0.155f, -1f);
            return SaveSprite(icon, "icon_billiard");
        }

        private static (Drawer, CarryableItem[]) BuildNightstand(Transform parent, string pinItemId = ToolItemId)
        {
            // Footprint centre, on the floor. The front face looks down the room, away from the
            // pillow, which is the side the player is on when they turn round from the bed.
            Vector3 centre = new Vector3(-0.95f, 0f, 1.35f);
            const float w = 0.56f, d = 0.36f, h = 0.59f;
            const float panel = 0.018f;     // carcass stock
            const float legH = 0.075f;      // floor to the underside of the case
            const float topT = 0.032f;      // the slab the lamp stands on

            float caseBottom = legH;
            float caseTop = h - topT;
            const float bayH = 0.17f;              // the drawer opening
            float bayTop = caseTop;
            float bayBottom = bayTop - bayH;

            Material wood = MakeColorMaterial("NightstandWood", new Color(0.14f, 0.085f, 0.06f));
            SetSmoothness(wood, 0.25f);
            // Brass, as the model's pulls were. Not metallic: this project cannot light a pure metal
            // (see docs/gotchas.md), so it is a warm colour with some gloss instead.
            Material brass = MakeColorMaterial("DrawerHandle", new Color(0.72f, 0.55f, 0.25f));
            SetSmoothness(brass, 0.55f);

            GameObject unit = new GameObject("Nightstand");
            unit.transform.SetParent(parent, false);
            // LOCAL, not world. It was `position`, which was the same thing for as long as the only
            // nightstand was in a room whose parent sat at the origin - and silently wrong the moment
            // one is built under a parent carrying a storey offset, where it would land on the floor
            // above.
            unit.transform.localPosition = centre;

            // Carcass: five boards with the front left OFF. That absence is the recess - there is
            // nothing else to build, and it is what the imported mesh could not give.
            Prim(PrimitiveType.Cube, "Top", unit.transform, new Vector3(0f, h - topT / 2f, 0f),
                new Vector3(w + 0.03f, topT, d + 0.02f), wood);
            Prim(PrimitiveType.Cube, "Bottom", unit.transform, new Vector3(0f, caseBottom + panel / 2f, 0f),
                new Vector3(w, panel, d), wood);
            Prim(PrimitiveType.Cube, "Back", unit.transform, new Vector3(0f, (caseBottom + caseTop) / 2f, d / 2f - panel / 2f),
                new Vector3(w, caseTop - caseBottom, panel), wood);
            Prim(PrimitiveType.Cube, "SideLeft", unit.transform, new Vector3(-w / 2f + panel / 2f, (caseBottom + caseTop) / 2f, 0f),
                new Vector3(panel, caseTop - caseBottom, d), wood);
            Prim(PrimitiveType.Cube, "SideRight", unit.transform, new Vector3(w / 2f - panel / 2f, (caseBottom + caseTop) / 2f, 0f),
                new Vector3(panel, caseTop - caseBottom, d), wood);
            // Separates the drawer bay above from an open shelf below. A second drawer front would
            // have matched the old model better and lied: only one drawer opens.
            Prim(PrimitiveType.Cube, "Divider", unit.transform, new Vector3(0f, bayBottom - panel / 2f, 0f),
                new Vector3(w - panel * 2f, panel, d - panel), wood);

            for (int i = 0; i < 4; i++)
            {
                float lx = (i % 2 == 0 ? -1f : 1f) * (w / 2f - 0.035f);
                float lz = (i < 2 ? -1f : 1f) * (d / 2f - 0.035f);
                Prim(PrimitiveType.Cube, $"Leg{i}", unit.transform, new Vector3(lx, legH / 2f, lz),
                    new Vector3(0.042f, legH, 0.042f), wood);
            }

            BuildNightstandLamp(unit.transform, new Vector3(-0.13f, h, 0.03f));
            BuildNightstandCube(unit.transform, new Vector3(0.16f, h, -0.05f));

            // The drawer's own root sits at the CENTRE OF ITS FRONT PANEL, not at the unit origin,
            // because Drawer.HintAnchor is drawerBody - anchored at the floor the E prompt would
            // float at the player's feet.
            float frontZ = -d / 2f + panel / 2f;
            float frontY = (bayBottom + bayTop) / 2f;

            GameObject root = new GameObject("NightstandDrawer");
            root.transform.SetParent(parent, false);
            // LOCAL, NOT WORLD - the same fix the carcass above already carries, and this half was
            // missed. `centre` is a position in the PARENT's space, so assigning it to `.position`
            // only lands correctly while that parent sits at the origin unrotated. Cycle 2's
            // nightstand hangs off a furniture holder that is yawed 180 with the bed, one storey
            // down and fifty-odd metres along the corridor - so its drawer was built at world
            // (0.95, 0.47, 107.3) while its carcass stood at (-0.95, -7.21, 55.6). A drawer front
            // floating in the void half a building away, with the bay it belongs in left empty.
            root.transform.localPosition = centre + new Vector3(0f, frontY, frontZ);

            GameObject bodyGO = new GameObject("DrawerBody");
            bodyGO.transform.SetParent(root.transform, false);

            // Inset into the opening rather than laid over it, by 5mm all round: the gap is what
            // shows there is a hole here even with the drawer shut.
            const float trayD = 0.30f;
            float frontW = w - panel * 2f - 0.01f;
            float frontH = bayH - 0.01f;

            // The tray is LINED, in pale grey, and the wood stops at the front panel. This is the one
            // place the unit is not the colour it wants to be: the pin is a dark handle with a bright
            // 6mm needle on it, and against wood the handle disappears - the first version of this
            // carcass lost the tool completely, because the tray it inherited had been white. A liner
            // is what a drawer has anyway, and it puts the contrast back where it is load-bearing.
            Material liner = MakeColorMaterial("DrawerLiner", new Color(0.60f, 0.58f, 0.55f));
            SetSmoothness(liner, 0.15f);

            Prim(PrimitiveType.Cube, "Front", bodyGO.transform, Vector3.zero,
                new Vector3(frontW, frontH, panel), wood, removeCollider: true);
            Prim(PrimitiveType.Cube, "TrayBase", bodyGO.transform, new Vector3(0f, -frontH / 2f + 0.008f, trayD / 2f),
                new Vector3(frontW - 0.02f, 0.016f, trayD), liner, removeCollider: true);
            Prim(PrimitiveType.Cube, "TrayLeft", bodyGO.transform, new Vector3(-frontW / 2f + 0.008f, 0f, trayD / 2f),
                new Vector3(0.016f, frontH * 0.8f, trayD), liner, removeCollider: true);
            Prim(PrimitiveType.Cube, "TrayRight", bodyGO.transform, new Vector3(frontW / 2f - 0.008f, 0f, trayD / 2f),
                new Vector3(0.016f, frontH * 0.8f, trayD), liner, removeCollider: true);
            Prim(PrimitiveType.Cube, "TrayBack", bodyGO.transform, new Vector3(0f, 0f, trayD),
                new Vector3(frontW - 0.02f, frontH * 0.8f, 0.016f), liner, removeCollider: true);
            Prim(PrimitiveType.Cube, "Pull", bodyGO.transform, new Vector3(0f, 0f, -panel / 2f - 0.012f),
                new Vector3(frontW * 0.42f, 0.016f, 0.024f), brass, removeCollider: true);

            BoxCollider trigger = root.AddComponent<BoxCollider>();
            trigger.isTrigger = true;
            trigger.size = new Vector3(w + 0.9f, 1.4f, 1.4f);

            Drawer drawerComp = root.AddComponent<Drawer>();
            drawerComp.drawerBody = bodyGO.transform;
            drawerComp.audioSource = MakeSource(root.transform, "DrawerAudio", 1f, 0.8f);
            drawerComp.openClip = LoadClip(SfxDir, "sfx_drawer_open");
            // Two thirds out, not all the way. Clearing the carcass entirely was right when the
            // drawer was a slab on a solid face and had nowhere to be; now that there is an opening
            // to sit in, leaving a third of the tray inside is what reads as a drawer rather than a
            // tray hanging in mid-air. It still puts the tool well clear of the front.
            drawerComp.openLocalOffset = new Vector3(0f, 0f, -trayD * 0.68f);

            // THREE pins, not one, laid out across the tray.
            //
            // Popping requires the pin in hand for ghosts as for the player, and with one pin in the
            // world that capped the entire room at ONE popper at any moment - so Room2's
            // accumulation, which is the thing every iteration is supposed to add to, did not survive
            // its own rule. The mitigation was always a supply rather than a softer rule
            // (docs/decisions.md), and ItemRegistry now resolves an id to a free instance so several
            // objects can share one.
            //
            // Three buys the player and TWO past selves popping at once. It is not a cap on ghosts,
            // only on simultaneous poppers: a third ghost reaching for a fourth pin finds none, and
            // its errand simply does not happen. Raising the number is now one edit here.
            CarryableItem[] pins = new CarryableItem[3];
            float pinSpacing = (frontW - 0.09f) / 2f;
            for (int i = 0; i < pins.Length; i++)
                pins[i] = BuildPin(bodyGO.transform, i,
                    new Vector3((i - 1) * pinSpacing, -frontH / 2f + 0.032f, trayD * 0.38f), drawerComp, pinItemId);

            return (drawerComp, pins);
        }

        // One pin: a slim needle on a dark handle. Parented to the drawer body, so it rides out with
        // the drawer instead of hanging in the air in front of a shut one, and sat forward in the
        // tray so an open drawer presents it.
        //
        // All three share ToolItemId, which is the point - a recorded "took the Tool" has to be
        // satisfiable by whichever one is going spare. They differ only in name, so the console can
        // say which object a ghost picked up.
        private static CarryableItem BuildPin(Transform drawerBody, int index, Vector3 localPos, Drawer drawer, string itemId)
        {
            GameObject toolRoot = new GameObject(index == 0 ? "BalloonTool" : $"BalloonTool_{index}");
            toolRoot.transform.SetParent(drawerBody, false);
            toolRoot.transform.localPosition = localPos;

            Material handleMat = MakeColorMaterial("ToolHandle", new Color(0.16f, 0.16f, 0.18f));
            Material pinMat = MakeColorMaterial("ToolPin", new Color(0.78f, 0.79f, 0.82f));
            SetSmoothness(pinMat, 0.7f);

            Prim(PrimitiveType.Cylinder, "Handle", toolRoot.transform, new Vector3(0f, 0f, -0.045f),
                new Vector3(0.028f, 0.045f, 0.028f), handleMat, removeCollider: true)
                .transform.localRotation = Quaternion.Euler(90f, 0f, 0f);
            Prim(PrimitiveType.Cylinder, "Pin", toolRoot.transform, new Vector3(0f, 0f, 0.05f),
                new Vector3(0.006f, 0.05f, 0.006f), pinMat, removeCollider: true)
                .transform.localRotation = Quaternion.Euler(90f, 0f, 0f);

            BoxCollider toolTrigger = toolRoot.AddComponent<BoxCollider>();
            toolTrigger.isTrigger = true;
            toolTrigger.size = new Vector3(0.7f, 0.7f, 0.7f);

            CarryableItem toolItem = toolRoot.AddComponent<CarryableItem>();
            toolItem.itemId = itemId;
            toolItem.displayName = "PIN";
            toolItem.icon = PinIcon();
            // Nearer and higher than CarryableItem's default, which put almost none of the pin on
            // screen: at fov 60 a hold 0.42m out has 0.242m of half-height, so the default y of
            // -0.24 sat the tool's CENTRE on the bottom edge of the frame and cropped the handle
            // into the corner. 0.32m out puts half-height at 0.185m, so -0.125 is 68% down - the
            // whole tool inside the frame with room under it, and bigger for being closer.
            //
            // x is 0.14 rather than the 0.175 that looked right in the Editor, which runs a 2.03
            // ultrawide viewport: checked again at 16:9 the handle came within 5% of the right edge,
            // and 16:9 is the narrower case the build has to survive.
            //
            // The ROTATION is deliberately the tuned default, unchanged. It is what the swing arc
            // was built around - BalloonTool pitches about the item's local X from this rest pose, so
            // yawing it turns the chop into a sideways slash. Yawed versions also read worse, not
            // better: past about 25 degrees the handle turns broadside and becomes a black slab.
            toolItem.handLocalPosition = new Vector3(0.14f, -0.125f, 0.32f);
            toolItem.requiresOpenDrawer = drawer;
            // The nightstand's carcass, for the reason the billiard balls' is the chest's - see
            // CarryableItem.dropParent. A pin is normally used in the room it lives in, so this has
            // never visibly mattered; it is still the same latent fault.
            toolItem.dropParent = drawer.transform.parent;
            toolItem.audioSource = MakeSource(toolRoot.transform, "PickupAudio", 1f, 0.8f);
            toolItem.pickupClip = LoadClip(SfxDir, "sfx_item_pickup");

            return toolItem;
        }

        // The drum-shade lamp the imported nightstand carried, rebuilt from three cylinders. It gives
        // off no light - see BuildNightstand for why - so the shade is a pale matte solid rather than
        // anything emissive: a lamp that glowed without lighting the room would read as broken.
        private static void BuildNightstandLamp(Transform unit, Vector3 baseLocal)
        {
            Material metal = MakeColorMaterial("LampStem", new Color(0.12f, 0.09f, 0.07f));
            SetSmoothness(metal, 0.45f);
            Material shade = MakeColorMaterial("LampShade", new Color(0.87f, 0.85f, 0.79f));
            SetSmoothness(shade, 0.08f);

            GameObject lamp = new GameObject("Lamp");
            lamp.transform.SetParent(unit, false);
            lamp.transform.localPosition = baseLocal;

            // Cylinder primitives are 1 unit across and TWO tall, so the Y scale is a half-height.
            Prim(PrimitiveType.Cylinder, "Foot", lamp.transform, new Vector3(0f, 0.011f, 0f),
                new Vector3(0.092f, 0.011f, 0.092f), metal);
            Prim(PrimitiveType.Cylinder, "Stem", lamp.transform, new Vector3(0f, 0.10f, 0f),
                new Vector3(0.034f, 0.078f, 0.034f), metal, removeCollider: true);
            Prim(PrimitiveType.Cylinder, "Shade", lamp.transform, new Vector3(0f, 0.245f, 0f),
                new Vector3(0.20f, 0.072f, 0.20f), shade);
        }

        // The little Rubik's cube beside the lamp, swapped in for a potted plant 2026-08-13 - the
        // point is still just that the top of the nightstand is not bare, not anything about which
        // prop it is.
        //
        // `baseLocal` is where the pot's own root used to sit - `unit`'s local space, Y already at
        // the nightstand's top surface - so PlaceModel is handed unit.position + baseLocal as its
        // WORLD target rather than being reparented under a second empty the way the pot's two
        // primitives were. addBoxCollider false: a solid decorative object nobody can reach behind
        // the lamp does not need one, and it is one fewer collider on a footprint this small.
        private static void BuildNightstandCube(Transform unit, Vector3 baseLocal)
        {
            Vector3 target = unit.position + baseLocal;

            // Measured off the imported model: its renderer bounds are 0.13m across at the prefab's
            // own default root scale of 1.15, so 0.113m per unit of PlaceModel's uniformScale here.
            // 0.8 lands just under 0.09m - small enough to read as a desk toy next to the lamp
            // rather than a prop competing with it. Rotation matches the prefab's own saved root
            // rotation (270, 0, 0) - PlaceModel overwrites rotation to identity unless told
            // otherwise, and identity here stood the cube on a corner.
            PlaceModel($"{FurnitureDir}/rubiks_cube.glb", unit, "Cube",
                new Vector3(target.x, 0f, target.z), target.y, 0.8f,
                addBoxCollider: false, rotation: Quaternion.Euler(-90f, 0f, 0f));
        }

        // One key shape, used three times over: lying on the floor once its balloon bursts, seen
        // through the skin of the balloon that holds it, and mounted on Room2's lock so the thing
        // on the wall says what it wants. Laid out in the XY plane facing -Z.
        private const string GoldKeyPath = FurnitureDir + "/gold_key.glb";

        // Measured off the glb at scale 1, logged on every build so a re-export that moves them is
        // caught rather than discovered: the key runs 8.00 along Y with the BOW at +Y and the bit
        // at -Y, and its shaft turns about the line x=0, z=-0.03.
        private const float KeyModelLength = 8.0f;
        private const float KeyModelTipY = -7.493f;
        // Where the bow stops being a ring and becomes shaft. This is the waterline: everything
        // below it goes into the lock, everything above it stays out where the player can see it.
        private const float KeyModelBowJunctionY = -2.3f;
        private const float KeyModelShaftAxisZ = -0.03f;

        // 0.20m overall, which is what the five primitives it replaces measured. Not a coincidence
        // and not a free choice: Room2's puzzle is spotting the key THROUGH a balloon from across
        // the room, and that was play-tested at this size. A prop key rather than a real 6cm one.
        private const float KeyLength = 0.20f;
        private const float KeyScale = KeyLength / KeyModelLength;
        // Distance from the bow junction to the tip - i.e. how much key there is to push in.
        private const float KeyInsertTravel = (KeyModelBowJunctionY - KeyModelTipY) * KeyScale;

        // How the key hangs when it is NOT in the lock: bow up, bit down, turned off-axis. Only the
        // resting pose - CarryableItem.InsertInto zeroes the root's rotation, which is exactly the
        // frame the insert-and-turn animation wants, and ReturnToOrigin puts this back.
        private static readonly Quaternion KeyRestRotation = Quaternion.Euler(90f, 35f, 0f);

        // The gold key model, laid into its parent so that +Z is "into the lock" and a roll about
        // local Z is "turn the key". Everything downstream - the socket, the insertion, the turn -
        // depends on this frame, so it is established once here rather than at each call site.
        private static GameObject BuildKeyModel(Transform parent, float scaleMul, Material overrideMat,
                                                bool centreOnParent = false)
        {
            GameObject source = AssetDatabase.LoadAssetAtPath<GameObject>(GoldKeyPath);
            if (source == null)
            {
                Debug.LogError($"[SceneBuilder] Key model missing at {GoldKeyPath}");
                return null;
            }

            GameObject model = (GameObject)PrefabUtility.InstantiatePrefab(source, parent);
            model.name = "KeyModel";

            float scale = KeyScale * scaleMul;
            model.transform.localScale = Vector3.one * scale;

            // Two rotations, composed in this order and NOT written as one Euler: Unity evaluates
            // Euler as Y*X*Z, so a single triple would apply the roll before the lay-down and put
            // the bit back where it started.
            //   -90 about X  lays the key down, bow toward -Z (out at the player), bit into +Z.
            //   +90 about Z  rolls it so the flat of the bit stands VERTICAL, matching the
            //                keyhole's vertical slot. A key entering a slot sideways is the wrong
            //                key, and the slot is the one part of the lock that says which way up.
            model.transform.localRotation = Quaternion.AngleAxis(90f, Vector3.forward)
                                          * Quaternion.AngleAxis(-90f, Vector3.right);

            // Put the shaft's own axis on the parent's Z axis. Without this the turn is a wobble
            // about a line 0.75mm off the shaft - small, but it is the difference between a key
            // turning and a key being waggled.
            Vector3 axisPoint = new Vector3(0f, 0f, KeyModelShaftAxisZ) * scale;
            model.transform.localPosition = -(model.transform.localRotation * axisPoint);

            // The origin left by the line above is the BOW, which is what the lock wants - it is the
            // point that seats on the plate face, and CarryableItem.InsertInto drops the root exactly
            // there. It is wrong for the balloon: the key hangs off the origin by 0.09 and ends up
            // shouldered against one side of a 0.24-radius sphere instead of suspended in it, which
            // reads as a key stuck to the skin rather than one floating inside. Measured and
            // subtracted rather than hardcoded, so it survives the key being rescaled.
            if (centreOnParent)
            {
                Renderer[] centred = model.GetComponentsInChildren<Renderer>();
                Bounds local = new Bounds(parent.InverseTransformPoint(centred[0].bounds.center), Vector3.zero);
                foreach (Renderer r in centred)
                {
                    local.Encapsulate(parent.InverseTransformPoint(r.bounds.min));
                    local.Encapsulate(parent.InverseTransformPoint(r.bounds.max));
                }
                model.transform.localPosition -= local.center;
            }

            if (overrideMat != null)
                foreach (Renderer r in model.GetComponentsInChildren<Renderer>(true))
                {
                    Material[] mats = r.sharedMaterials;
                    for (int i = 0; i < mats.Length; i++) mats[i] = overrideMat;
                    r.sharedMaterials = mats;
                }

            // Logged because every constant above is a measurement off this file, and a re-export
            // that moves them should show up in the build log rather than as a key sticking out of a
            // wall. (The nightstand used to be read the same way and no longer needs to be - it is
            // built from authored numbers now, not measured off a mesh.)
            if (scaleMul >= 1f)
            {
                Renderer[] rs = model.GetComponentsInChildren<Renderer>();
                Bounds b = rs[0].bounds;
                for (int i = 1; i < rs.Length; i++) b.Encapsulate(rs[i].bounds);
                // Longest axis, not Z: the loose key's root carries KeyRestRotation, so which world
                // axis the length lands on depends on where this was called from.
                float longest = Mathf.Max(b.size.x, Mathf.Max(b.size.y, b.size.z));
                Debug.Log($"[SceneBuilder] Key model size={b.size} longest={longest:0.000} (expects {KeyLength:0.000})");
            }

            return model;
        }

        // A CLONE of the glb's own Gold, because glb materials are sub-assets regenerated on every
        // reimport and anything written to them is lost - the same trap DisableBakedOcclusion works
        // around for the bed. `tint` scales the base colour: 1 for the loose key, dark for the copy
        // inside a balloon, which is read through a pink translucent skin and washes out at gold.
        //
        // THE ONE VALUE CHANGED IS metallicFactor, 1.0 -> 0.3, and it is not a style preference.
        // A fully metallic surface has NO diffuse term: every photon it shows is a reflection of
        // its surroundings. Reflections here come from a baked probe, and whatever this room's
        // probes are handing a metal it is not the white box they were baked in - the key rendered
        // BLACK with a thin gold rim (the rim being the only direct specular), floating in the
        // middle of a bright white room. Verified it was the metalness and not the lighting: with
        // occlusionTexture_strength forced to 0 nothing changed, and at 0.3 the key came back gold.
        //
        // This departs from "keep the glTF materials these ship with". That rule exists to stop a
        // hand-rolled URP/Lit stand-in dropping a model's metallic/roughness MAPS - and this model
        // has no textures at all, only factors, so there is nothing to drop. It is also the more
        // robust setting for this room: a key with a diffuse term reads as gold wherever it is put,
        // where a mirror only reads as gold where the probe happens to be right.
        private static Material KeyMaterial(string assetName, float tint) =>
            KeyMaterial(assetName, Color.white * tint);

        // tint is now a COLOUR rather than a brightness, which is what lets a red and a blue key be the
        // same object as the gold one. It is still applied by SCALING the glb's own baseColorFactor
        // rather than by assigning a chosen triple - so the model keeps its shading and the result stays
        // correct whichever colour space the glTF shader reads that property in. A red channel above 1
        // is deliberate and is why: scaling a dark gold by 1.0 would give a dark red, and the key has to
        // stay bright enough to be spotted through a balloon from across the room.
        private static Material KeyMaterial(string assetName, Color tint)
        {
            Material gold = null;
            foreach (Object o in AssetDatabase.LoadAllAssetsAtPath(GoldKeyPath))
                if (o is Material m && !m.name.StartsWith("__preview__")) { gold = m; break; }

            if (gold == null)
            {
                Debug.LogWarning($"[SceneBuilder] gold_key.glb has no material - {assetName} left flat");
                return MakeColorMaterial(assetName, new Color(0.85f, 0.68f, 0.24f) * tint);
            }

            string path = $"{MaterialsDir}/{assetName}.mat";
            Material mat = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (mat == null)
            {
                mat = new Material(gold);
                AssetDatabase.CreateAsset(mat, path);
            }
            mat.shader = gold.shader;
            mat.CopyPropertiesFromMaterial(gold);
            mat.shaderKeywords = gold.shaderKeywords;

            mat.SetFloat("metallicFactor", 0.3f);
            const string baseColor = "baseColorFactor";
            if (tint != Color.white && mat.HasProperty(baseColor))
                mat.SetColor(baseColor, gold.GetColor(baseColor) * tint);

            EditorUtility.SetDirty(mat);
            return mat;
        }

        // The hole a key goes into: a round seat for the shaft with a narrow slot under it.
        // Two flat decals sitting on the plate face rather than a cut - the plate is a 0.09m cube
        // and boring a hole through it would show the wall behind.
        private static void BuildKeyholeSlot(Transform parent, Vector3 centre, Material mat)
        {
            GameObject seat = Prim(PrimitiveType.Cylinder, "KeyholeSeat", parent, centre,
                new Vector3(0.055f, 0.002f, 0.055f), mat, removeCollider: true);
            seat.transform.localRotation = Quaternion.Euler(90f, 0f, 0f);

            Prim(PrimitiveType.Cube, "KeyholeSlot", parent,
                new Vector3(centre.x, centre.y - 0.037f, centre.z),
                new Vector3(0.022f, 0.055f, 0.004f), mat, removeCollider: true);
        }

        // Room2's balloons, pooled rather than spawned. The pool is what makes a balloon's id mean
        // the same thing in every iteration, which is what a ghost's recorded pops refer to.
        private static (BalloonField, CarryableItem[]) BuildBalloons(Transform parent)
        {
            const int balloonCount = 70;
            const int fieldSeed = 20260810;

            GameObject root = new GameObject("BalloonField");
            root.transform.SetParent(parent, false);

            // Translucent, so whatever is inside a balloon shows through it as a shape. That is
            // the whole point: the key balloon is now findable by looking rather than by bursting
            // seventy of them and hoping, which is what made the search luck before.
            Material pink = MakeTranslucentMaterial("BalloonPink", new Color(0.98f, 0.44f, 0.68f, 0.62f), 0.72f);
            Material knotMat = MakeColorMaterial("BalloonKnot", new Color(0.76f, 0.28f, 0.5f));

            // Bouncy and slippery. Combine on Maximum so a balloon still bounces off the floor and
            // the walls, which are plain matte colliders with no bounce of their own.
            PhysicsMaterial rubber = AssetDatabase.LoadAssetAtPath<PhysicsMaterial>($"{MaterialsDir}/BalloonRubber.physicMaterial");
            if (rubber == null)
            {
                rubber = new PhysicsMaterial("BalloonRubber");
                AssetDatabase.CreateAsset(rubber, $"{MaterialsDir}/BalloonRubber.physicMaterial");
            }
            rubber.bounciness = 0.55f;
            rubber.dynamicFriction = 0.28f;
            rubber.staticFriction = 0.28f;
            rubber.bounceCombine = PhysicsMaterialCombine.Maximum;
            rubber.frictionCombine = PhysicsMaterialCombine.Minimum;
            EditorUtility.SetDirty(rubber);

            // THREE keys, in three balloons, from the same fixed seed as the spawn points - so each key
            // is in the same balloon in every run, which is what makes "I know where the blue one is"
            // worth having. Distinct by construction rather than by luck: drawing three times from 70
            // collides about one run in twenty-four, and a collision would silently put two keys in one
            // balloon and leave a door with no key anywhere.
            var keyIndices = new System.Collections.Generic.List<int>();
            System.Random keyRng = new System.Random(fieldSeed);
            while (keyIndices.Count < Room2Keys.Length)
            {
                int candidate = keyRng.Next(balloonCount);
                if (!keyIndices.Contains(candidate)) keyIndices.Add(candidate);
            }

            System.Random pitchRng = new System.Random(fieldSeed + 1);

            // Their own layer, so the player's controller can exclude them outright and there is
            // never any contact to be lifted by. Set on the root only - the collider lives there,
            // and the children are visuals.
            int balloonLayer = EnsureLayer(BalloonLayerName);

            Balloon[] balloons = new Balloon[balloonCount];
            for (int i = 0; i < balloonCount; i++)
            {
                GameObject go = new GameObject($"Balloon_{i}");
                go.transform.SetParent(root.transform, false);
                go.layer = balloonLayer;

                Prim(PrimitiveType.Sphere, "Body", go.transform, Vector3.zero,
                    new Vector3(0.48f, 0.58f, 0.48f), pink, removeCollider: true);
                Prim(PrimitiveType.Cube, "Knot", go.transform, new Vector3(0f, -0.3f, 0f),
                    new Vector3(0.06f, 0.07f, 0.06f), knotMat, removeCollider: true);

                SphereCollider col = go.AddComponent<SphereCollider>();
                col.radius = 0.27f;
                col.sharedMaterial = rubber;

                Rigidbody rb = go.AddComponent<Rigidbody>();
                rb.mass = 0.04f;
                // Gravity off: Balloon.FixedUpdate applies its own much gentler fall instead. Unity
                // has no per-body gravity scale, and the alternative - damping a full 9.81 down to
                // a drift - takes so much damping that the balloons stop bouncing and start
                // behaving like they are underwater. Low damping plus a small pull is light AND
                // lively; heavy damping is only slow.
                rb.useGravity = false;
                rb.linearDamping = 1.1f;
                rb.angularDamping = 1.2f;
                // Parked until the field releases them. Built live, seventy spheres would start the
                // scene interpenetrating at the origin - which is in Room1, beside the bed.
                rb.isKinematic = true;
                col.enabled = false;

                Balloon balloon = go.AddComponent<Balloon>();
                balloon.id = i;

                // The key inside, visible through the skin of whichever balloon has one. A child of the
                // balloon, so Balloon.SetInPlay hides and shows it along with everything else and it
                // vanishes the moment the balloon bursts. Hung off its own child so it keeps the bow-up
                // resting pose: BuildKeyModel lays the key along +Z for the lock, and a key floating
                // horizontally inside a balloon reads as debris.
                //
                // In the KEY'S OWN COLOUR, which is what makes the search a search for a particular
                // key rather than for "a key". The balloon's own reference is wired below, once the
                // key objects exist.
                int keySlot = keyIndices.IndexOf(i);
                if (keySlot >= 0)
                {
                    GameObject keyVisual = new GameObject("KeyVisual");
                    keyVisual.transform.SetParent(go.transform, false);
                    keyVisual.transform.localRotation = KeyRestRotation;
                    BuildKeyModel(keyVisual.transform, 0.85f,
                                  KeyMaterial(Room2Keys[keySlot].materialName + "InBalloon",
                                              Room2Keys[keySlot].metal * 0.36f),
                                  centreOnParent: true);
                }
                balloon.audioSource = MakeSource(go.transform, "PopAudio", 1f, 0.8f);
                // A fixed detune per balloon, from the field's own seed. One clip across seventy
                // balloons reads as a machine gun; a balloon keeping the same voice every
                // iteration is one more thing about the room that stays put.
                balloon.audioSource.pitch = 0.86f + (float)pitchRng.NextDouble() * 0.3f;
                balloon.popClip = LoadClip(SfxDir, "sfx_balloon_pop");

                balloons[i] = balloon;
            }

            // THE THREE KEYS. Each is the same object as the one key that was here before - same model,
            // same scale, same hand pose, same seated-orientation-is-identity trick - differing only by
            // its KeySpec. Built in a loop precisely so they cannot drift apart from each other.
            //
            // Their origins are spread along the room's mid-line rather than stacked, because origin is
            // where the loop puts a key back at the top of every iteration: three keys sharing one
            // origin would be three keys inside each other, and `ReturnAllToOrigin` would do it every
            // sixty seconds. Pocketed rather than held on pickup, so taking one does not knock the pin
            // out of the hand that got it.
            var keyItems = new CarryableItem[Room2Keys.Length];
            for (int k = 0; k < Room2Keys.Length; k++)
            {
                KeySpec spec = Room2Keys[k];

                GameObject keyRoot = new GameObject(spec.materialName);
                keyRoot.transform.SetParent(root.transform, false);
                keyRoot.transform.position = new Vector3((k - 1) * 0.5f, 0.06f, RoomPitch);
                // The resting pose lives on the ROOT, not on the model, and that is load-bearing:
                // InsertInto zeroes the root's rotation, which is precisely the frame KeyLock's
                // insert-and-turn works in, and ReturnToOrigin restores this at the top of the loop.
                keyRoot.transform.localRotation = KeyRestRotation;

                BuildKeyModel(keyRoot.transform, 1f, KeyMaterial(spec.materialName, spec.metal));

                BoxCollider keyTrigger = keyRoot.AddComponent<BoxCollider>();
                keyTrigger.isTrigger = true;
                keyTrigger.size = new Vector3(0.9f, 0.9f, 0.9f);

                CarryableItem keyItem = keyRoot.AddComponent<CarryableItem>();
                keyItem.itemId = spec.itemId;
                keyItem.displayName = "KEY";
                keyItem.icon = KeyIcon();
                // One silhouette for all three, tinted. Three drawn shapes would be three things to
                // learn where the colour is already the whole message.
                keyItem.iconTint = spec.display;
                // In the hand the key points the way it goes into a lock - teeth forward, bit vertical
                // - because the root's identity rotation IS the seated orientation (see BuildKeyModel).
                // Held nose-first means walking up to the lock and pressing E needs no mental rotation.
                // Angled up slightly and further from the eye than the pin, which is a short stub where
                // this is 0.20m long and would otherwise cross the middle of the screen.
                keyItem.handLocalPosition = HandPoseFor(KeyScale);
                keyItem.handLocalEuler = new Vector3(-12f, -14f, 0f);
                // LIES FLAT WHEN PUT DOWN. The root's built pose is KeyRestRotation - bow up,
                // standing on its blade - which is the pose of a key left somewhere to be FOUND, not
                // of one that has been dropped. A key stood on end where it fell reads as placed on
                // purpose. This is the same quarter turn BalloonField gives a key coming out of a
                // burst balloon, now stated once on the object instead of at each place that puts
                // one down.
                keyItem.restRoll = 90f;
                keyItem.audioSource = MakeSource(keyRoot.transform, "PickupAudio", 1f, 0.9f);
                keyItem.pickupClip = LoadClip(SfxDir, "sfx_item_pickup");

                keyItems[k] = keyItem;
                // The balloon holding this key learns which one it is. Done here rather than in the
                // balloon loop above because the key objects do not exist yet at that point.
                balloons[keyIndices[k]].heldKey = keyItem;
            }

            BalloonField field = root.AddComponent<BalloonField>();
            field.balloons = balloons;
            field.seed = fieldSeed;
            field.roomCenterZ = RoomPitch;

            // Park the pool now rather than waiting for the first iteration to do it. Built objects
            // sit at their parent's origin, which for these is the middle of Room1.
            field.ComputeSpawnPoints();
            field.ResetField();

            return (field, keyItems);
        }

        // A GATE: TWO LEAVES OF WALL THAT SLIDE APART WHILE A PAD IS HELD.
        //
        // Mechanically this is two `Door`s. That is not a shortcut - `Door` already TRACKS its pads
        // rather than latching (see its own note on why Room1's door works that way), which is
        // exactly the behaviour asked for here: step on, the wall opens; step off, it shuts. Writing
        // a second component for it would be a second answer to "is this open" for the same reason.
        //
        // **SO NOBODY WALKS THROUGH THEIR OWN GATE.** The pad is in this room and the opening is in
        // its wall, and one person cannot be on both. Every one of the four rooms around room3-1 is
        // reachable only while a PAST SELF is standing on the pad - which is the cycle's premise
        // stated in its first room, the way Room3's two pads state cycle 1's.
        //
        // The leaves live in the pocket between this room's wall and the next room's, the same
        // 0.1m cavity an ordinary door slides in, and each slides outward by its own width so the
        // opening clears completely. The cavity is capped by a liner everywhere the leaves do not
        // sweep - without it the gap between the two rooms' walls is open to the skybox at both
        // ends, which is the fault `BuildDoorPocketFill` exists to fix for the ordinary doors.
        // WHERE A WALL'S GATE IS, and both rooms that share the wall have to agree - the opening is
        // cut out of each of their walls separately, so this is the one place the answer lives.
        //
        // **THE GATE IS ALWAYS WHOLE CELLS AND ALWAYS CENTRED; ONLY HOW MANY DEPENDS ON THE WALL.**
        // Room3-1's east and west walls are 10.5 across, six cells, so the middle PAIR straddles the
        // centre and the gate is two leaves opening to their own sides. The north and south walls are
        // 8.75, FIVE cells - there is no middle pair, so the gate is the middle CELL, one leaf, and it
        // slides one way. A two-cell gate on an odd wall was built first and is what this replaces:
        // it could only sit half a cell off centre, which read as a mistake rather than as a wall.
        //
        // A leaf is never part of a cell. A half-width panel would carry a groove down the middle of
        // a cell where the wall has none, which is the one thing that would give a shut gate away.
        private static void GateSpan(float wallWidth, out float openMin, out float openMax,
                                     out float leafTravel, out int leaves)
        {
            // The same rounding `BuildPanelWall` does, so the cells this lands on are the cells that
            // are actually built.
            int cols = Mathf.Max(2, Mathf.RoundToInt(wallWidth / GridCellWidth));
            float cellWidth = wallWidth / cols;

            leaves = cols % 2 == 0 ? 2 : 1;
            float halfSpan = leaves * cellWidth / 2f;
            openMin = -halfSpan;
            openMax = halfSpan;
            // One cell either way. A split pair only has to clear its own half; a single leaf only
            // has its own width to vacate. Both park exactly over the cell next door.
            leafTravel = cellWidth;
        }

        private static Rect GateCutout(float wallWidth)
        {
            GateSpan(wallWidth, out float openMin, out float openMax, out _, out _);
            return Rect.MinMaxRect(openMin, 0f, openMax, GateHeight);
        }

        // A GATE: A PIECE OF THE WALL THAT LEAVES WHILE A PAD IS HELD.
        //
        // **THE LEAVES ARE WALL, not door slabs, and that is the whole specification.** Same material,
        // same 0.025 thickness, same depth off the face, same groove inset, and split into one quad
        // per grid cell so the row line across the opening lands where the wall's own does. Shut,
        // there is nothing to see: no frame, no reveal, no lamp. A player who has not stood on the pad
        // has no way to know a gate is there.
        //
        // **EACH LEAF CARRIES ITS OWN BACKING, and leaving it out is what made the first version show
        // the room next door.** The cutout takes the wall's backing away along with its panels - so
        // the 0.05 groove around a leaf had nothing behind it, and the sightline ran groove, cavity,
        // the neighbour's own cutout, daylight. A panel is not a wall; a panel PLUS the dark plate
        // behind its grooves is. So the plate travels with it, sized to the full cell with no groove
        // inset, which is exactly the area the grooves expose.
        //
        // Mechanically it is one `Door` per leaf. `Door` already TRACKS its pads rather than latching
        // (see its note on Room1); what it did not have was the push-in phase a flush panel needs
        // before it can travel sideways, and that is a field on `Door` now rather than a second
        // component, so "is this open" still has one answer.
        // **BUILT ONCE PER SIDE OF THE WALL, and both sides are needed.** A gate lives in a wall two
        // rooms share, and each of them has its own panelled face - so a gate built on one side only
        // leaves the OTHER room looking at a bare hole where its grid should be. Play found it exactly
        // that way. The two calls take the same pads, so the two faces move as one wall.
        //
        // They fit because a leaf is thin. Each retracts to its OWN side of the 0.1m cavity rather
        // than to the middle of it: near leaf 0.129-0.169 back from its face, far leaf the mirror of
        // that, 12mm between them.
        //
        // `withCavityLiner` belongs to the first call only. The liner fills one volume and building it
        // twice is two coincident slabs fighting for the same pixels.
        private static Door[] BuildPanelGate(Transform parent, string name,
                                             Vector3 wallCentreAtBase, Vector3 rightDir, Vector3 inward,
                                             float wallWidth, Material panelMat, Material grooveMat,
                                             FloorButton[] pads, bool withCavityLiner = true)
        {
            GateSpan(wallWidth, out float openMin, out float openMax, out float leafTravel, out int leaves);

            float leafWidth = (openMax - openMin) / leaves;
            float openCentre = (openMin + openMax) / 2f;
            float groove = GridLineThickness;

            Vector3 outward = -inward;
            Vector3 depthAxis = new Vector3(Mathf.Abs(inward.x), Mathf.Abs(inward.y), Mathf.Abs(inward.z));
            Vector3 widthAxis = new Vector3(Mathf.Abs(rightDir.x), Mathf.Abs(rightDir.y), Mathf.Abs(rightDir.z));

            // THE WHOLE LEAF HAS TO FIT IN THE CAVITY, which is 0.1 deep, so its backing is a thin
            // plate rather than the wall's own 0.1 slab. It only has to stop a sightline down a 0.05
            // groove, not hold a building up.
            const float leafBackingDepth = 0.015f;
            // JUST INSIDE THE CAVITY, not centred in it. Centred was right while only one side had a
            // gate; with a leaf coming from each face they have to pass each other, and the cavity is
            // 0.1 deep against two leaves of 0.04. 4mm past the wall's own backing puts this one at
            // 0.129-0.169 and its opposite number at 0.181-0.221.
            float pushDistance = WallDepth + 0.004f;

            GameObject root = new GameObject(name);
            root.transform.SetParent(parent, false);

            AudioSource audio = MakeSource(root.transform, "GateAudio", spatialBlend: 1f, volume: 0.7f);
            audio.transform.localPosition = wallCentreAtBase + rightDir * openCentre
                                          + Vector3.up * (GateHeight / 2f);
            AudioClip openClip = LoadClip(SfxDir, "sfx_door_open");

            var doors = new Door[leaves];
            for (int i = 0; i < leaves; i++)
            {
                float cellAlong = openMin + i * leafWidth;
                float cellEnd = cellAlong + leafWidth;
                float cellCentre = (cellAlong + cellEnd) / 2f;
                // Two leaves open to their own sides; a single leaf has only one way to go.
                float direction = leaves == 2 ? (i == 0 ? -1f : 1f) : 1f;

                GameObject leafRoot = new GameObject($"Leaf_{i}");
                leafRoot.transform.SetParent(root.transform, false);
                // On the opening's centre, so `Door.doorwayCentre` - read off this, and what decides
                // whether the player is standing in the way - lands in the gap rather than on a leaf.
                leafRoot.transform.localPosition = wallCentreAtBase + rightDir * openCentre
                                                 + Vector3.up * (GateHeight / 2f);

                // ONE QUAD PER GRID CELL, laid out exactly as `BuildPanelWall` does it.
                for (int row = 0; row * GridCellHeight < GateHeight - 0.001f; row++)
                {
                    float bottom = row * GridCellHeight;
                    float top = Mathf.Min(bottom + GridCellHeight, GateHeight);
                    float upCentre = (bottom + top) / 2f;

                    // Chamfered like every other panel in the building, and that consistency is the
                    // reason rather than the look on its own: a gate leaf is meant to read as a
                    // piece of wall until it moves, and a leaf whose panels had sharp rims beside a
                    // wall whose panels did not would announce every door in the game.
                    ChamferedPanel($"Panel_{row}", leafRoot.transform,
                        rightDir * (cellCentre - openCentre)
                            + Vector3.up * (upCentre - GateHeight / 2f)
                            - inward * (GrooveDepth / 2f),
                        leafWidth - groove, top - bottom - groove, GrooveDepth, inward, panelMat);
                }

                // THE BACKING, which is what a groove has at the bottom of it everywhere else in the
                // building. Full cell, no inset, so every slot around and between this leaf's panels
                // has the same near-black behind it that the rest of the wall does.
                Prim(PrimitiveType.Cube, "Backing", leafRoot.transform,
                    rightDir * (cellCentre - openCentre)
                        - inward * (GrooveDepth + leafBackingDepth / 2f),
                    widthAxis * leafWidth + Vector3.up * GateHeight + depthAxis * leafBackingDepth,
                    grooveMat, removeCollider: true);

                // COLLISION IS ONE BOX, THICKER THAN THE PANELS ARE. The opening is cut out of both
                // rooms' wall collision, so a shut gate is the only thing between them - and a 25mm
                // collider is a thin thing to trust a CharacterController against. Built without the
                // groove inset too, so there is no 50mm slot to squeeze through at the seam.
                GameObject block = new GameObject("Solid");
                block.transform.SetParent(leafRoot.transform, false);
                block.transform.localPosition = rightDir * (cellCentre - openCentre)
                                              - inward * ((GrooveDepth + leafBackingDepth) / 2f);
                BoxCollider blockCollider = block.AddComponent<BoxCollider>();
                // As deep as the leaf assembly rather than a door slab's 0.06, so the two sides'
                // colliders do not overlap in the cavity. There are two of them in series anyway, and
                // `CharacterController.Move` sweeps rather than teleports, so neither can be tunnelled.
                blockCollider.size = widthAxis * leafWidth + Vector3.up * GateHeight
                                   + depthAxis * (GrooveDepth + leafBackingDepth);

                // Baked into the probes despite moving, because shut it is wall - see WallWhileShut.
                leafRoot.AddComponent<WallWhileShut>();

                Door door = leafRoot.AddComponent<Door>();
                door.doorPanel = leafRoot.transform;
                door.pushInOffset = outward * pushDistance;
                door.openLocalOffset = rightDir * (direction * leafTravel);
                door.requiredFloorButtons = pads;
                door.openDuration = 1.4f;
                // **SLOW OPEN, SNAP SHUT, and it is the same asymmetry the corridor block has.** The
                // gate is not being closed, it is being let go of: the pad is not held, so the wall
                // is a wall again. 0.3s is also short enough that the 1.18m from an east or west pad
                // cannot be crossed in time, which is what makes "nobody goes through their own pad"
                // true rather than merely intended - see `Door.closeDuration`.
                door.closeDuration = 0.3f;
                // AND IT DOES NOT WAIT FOR ANYONE. See `Door.standsOffForPlayer`: everywhere else in
                // the building a door refuses to shut on the player, and here that reprieve was a way
                // through your own gate and a way to hold it open by loitering in it.
                door.standsOffForPlayer = false;
                door.audioSource = audio;
                // One clip for the pair - two copies of the same slide half a frame apart is a flam.
                door.openClip = i == 0 ? openClip : null;
                door.doorwayClearance = (openMax - openMin) / 2f + 0.6f;
                doors[i] = door;
            }

            // THE CAVITY LINER. Without it the 0.1m gap between the two rooms' walls is open to the
            // skybox at both ends - the fault `BuildDoorPocketFill` fixes for the ordinary doors. It
            // fills everywhere the leaves do NOT go; where they park it has to stay clear.
            if (!withCavityLiner) return doors;

            float clearMin = leaves == 2 ? openMin - leafTravel : openMin;
            float clearMax = openMax + leafTravel;
            Rect cavity = Rect.MinMaxRect(-wallWidth / 2f - WallDepth, 0f,
                                           wallWidth / 2f + WallDepth, RoomHeight);
            Rect swept = Rect.MinMaxRect(clearMin, 0f, clearMax, GateHeight);

            GameObject liner = new GameObject(name + "_CavityLiner");
            liner.transform.SetParent(root.transform, false);
            int part = 0;
            foreach (Rect piece in SubtractRect(cavity, swept))
            {
                if (piece.width <= 0.001f || piece.height <= 0.001f) continue;
                Prim(PrimitiveType.Cube, $"Fill_{part++}", liner.transform,
                    wallCentreAtBase + rightDir * piece.center.x + Vector3.up * piece.center.y
                        + outward * (WallDepth + DoorPocketDepth / 2f),
                    widthAxis * piece.width + Vector3.up * piece.height
                        + depthAxis * DoorPocketDepth,
                    grooveMat, removeCollider: true);
            }

            return doors;
        }

        // THE CORRIDOR NORTH OUT OF ROOM3-1, AND THE SLAB THAT COMES DOWN IN IT.
        //
        // Not a gate. The other three walls of room3-1 open as panels and are meant not to be found;
        // this one is a hole you can see down, with a mechanism in it you are meant to see coming.
        // Both walls it passes through keep the gate-sized cutout and neither gets leaves - the
        // barrier partway along is the only thing that ever blocks the way.
        //
        // **THE CORRIDOR IS ONE CELL WIDE**, the same 1.75 the north wall's gate span is, so its mouth
        // lands on the wall grid exactly and there are no sliver panels beside it. Twenty-two metres
        // of it at that width is a tube, which is the intention: it is somewhere you commit to.
        //
        // The pad that holds the slab up is in room3-1, at the near end. **One person cannot hold it
        // and walk this**, which is the whole of the room - and unlike the gates, being wrong about it
        // is not merely inconvenient. See `CrushingBarrier`.
        // A ROOM THAT IS NOT THE STANDARD SHELL. Room3-2N is twice as wide, twice as deep and THREE
        // times as tall as every other room in the building - the climbing puzzle needs the height and
        // the panel stairs need the floor.
        //
        // **THE GRID CELL DOES NOT CHANGE, ONLY THE COUNT.** 17.5 across is ten cells of 1.75 where a
        // normal wall is five, 21 deep is twelve where a normal one is six, and 16.2234 tall is twelve
        // rows of 1.3519 where a normal wall is four. Every number is an exact multiple, so the
        // panelling reads as the same wall continued rather than as a different wall - which is the
        // whole reason the size is a multiple in the first place.
        //
        // Written as its own builder rather than as parameters on `BuildEmptyRoom`, because that one
        // is not merely sized by constants - `BuildSlab` lays its floor across a whole `RoomPitch` so
        // neighbouring rooms meet under their shared divider, which is a rule about the CHAIN and not
        // about this room. Threading a size through it would put a room-sized hole in that rule.
        private static Transform BuildBigRoom(Transform parent, string name, Vector3 at,
                                              float width, float depth, float height,
                                              Material floorMat, Material grooveMat,
                                              Material panelMat, Material fixtureMat,
                                              Rect southCutout, Rect northCutout,
                                              Rect floorHole, Rect ceilingHole)
        {
            GameObject rootGO = new GameObject(name + "_Root");
            rootGO.transform.SetParent(parent, false);
            rootGO.transform.localPosition = at;

            GameObject roomGO = new GameObject(name);
            roomGO.transform.SetParent(rootGO.transform, false);
            Transform t = roomGO.transform;

            // Overrunning the interior by the wall build-up at every edge, the same reason
            // `BuildPanelWall` overruns its structure: two slabs that merely abut leave a hairline the
            // grazing angles find.
            float slabX = width + 2f * WallDepth;
            float slabZ = depth + 2f * WallDepth;

            // ~~BUILT IN PIECES~~ ONE SLAB AGAIN. It was cut into rectangles for a while so that
            // coloured blocks could come up through it; those went with the levers that drove them
            // (2026-08-21), and a floor with nothing passing through it should be one surface with no
            // seams in it to find.
            // **HOLED, BOTH OF THEM, SINCE 2026-08-30.** The floor opens onto cycle 4 - a whole
            // room's worth, not a hatch - and the ceiling carries the ladder shaft up to room3-0.
            // `BuildSlabRect` subtracts the rect and lays the remainder as pieces, which is what
            // every other holed slab in the building already does.
            Rect slab = Rect.MinMaxRect(-slabX / 2f, -slabZ / 2f, slabX / 2f, slabZ / 2f);
            BuildSlabRect(t, "Floor", -WallThickness / 2f, slab, floorMat, floorHole);
            BuildSlabRect(t, "Ceiling", height + WallThickness / 2f, slab, CeilingMaterial(),
                          ceilingHole);

            // Whole walls, unholed. They carried a hole per coloured step until 2026-08-21; the
            // `panelHoles` argument stays on `BuildPanelWall` because gates still want it.
            // **THE NORTH WALL'S OPENING IS NOT AT FLOOR LEVEL**, and it is the only one in the
            // building that is not: it is the way onto deck B, two storeys up. `BuildPanelWall` cuts
            // a rect in the wall's own frame with y measured from the room's floor, so the height
            // costs nothing here - but nothing else has ever asked it for one, which is why
            // `AssertWalkable` is pointed at it in `BuildCycleThreeShell`.
            BuildPanelWall(t, "Wall_North", new Vector3(0f, 0f, depth / 2f),
                Vector3.right, Vector3.back, width, grooveMat, panelMat, northCutout, height);
            BuildPanelWall(t, "Wall_South", new Vector3(0f, 0f, -depth / 2f),
                Vector3.right, Vector3.forward, width, grooveMat, panelMat, southCutout, height);
            BuildPanelWall(t, "Wall_West", new Vector3(-width / 2f, 0f, 0f),
                Vector3.forward, Vector3.right, depth, grooveMat, panelMat, Rect.zero, height);
            BuildPanelWall(t, "Wall_East", new Vector3(width / 2f, 0f, 0f),
                Vector3.forward, Vector3.left, depth, grooveMat, panelMat, Rect.zero, height);

            BuildTallRoomLights(t, name, width, depth, height, fixtureMat);
            BuildMezzanines(t, width, depth, floorMat, panelMat);

            // Sized to the room rather than to `RoomWidth`/`RoomDepth`, and centred at half its own
            // height. A probe left at the standard size would capture a box a fraction of this one and
            // reflect it onto every surface in here.
            BuildReflectionProbe(t, name, 0f, sizeOverride: new Vector3(width, height, depth),
                                 yCenter: height * 0.5f);

            return t;
        }

        // LIGHTING A ROOM THREE STOREYS TALL, which the standard fixture grid cannot do.
        //
        // `BuildCeilingLights` puts four spots at fixed offsets with `range` 11 and `intensity` 10.5,
        // derived for a 5.4m ceiling. At 16.2m the range does not even REACH the floor, and inverse
        // square says the floor would get a ninth of the light if it did. So this scales both: the
        // grid spreads with the room, the range covers the diagonal, and the intensity goes up by the
        // square of the height ratio - which is the same derivation the 10.5 itself came from.
        //
        // **These numbers are derived, not seen.** The 10.5 was found by eye and then re-derived once
        // when the ceiling moved; this re-derives it again over a much bigger jump, and a jump that
        // big is exactly where an inverse-square approximation stops being one. Expect to retune.
        private static void BuildTallRoomLights(Transform parent, string roomName,
                                                float width, float depth, float height,
                                                Material emissiveMat)
        {
            GameObject root = new GameObject(roomName + "_CeilingLights");
            root.transform.SetParent(parent, false);

            // **BACK TO THE STANDARD 2x2, FROM 3x3** (2026-08-28, by request: the decks were too
            // bright).
            //
            // The nine were justified by a thing that no longer exists - "this is a room the player
            // has to read a route across from the far end of a CCTV feed" - and the feeds were deleted
            // with the staircase they were watching. What is left is a room with two decks in it, read
            // by standing on them.
            //
            // **THE COUNT IS NOT THE WHOLE OF WHY IT WAS BRIGHT UP THERE, and this is only the half
            // that was asked for.** The intensity below is multiplied by the SQUARE of the height
            // ratio - nine times - to get light down to a floor three storeys away. Deck B is 5.4m
            // under the ceiling, which is an ordinary room's height, so a fixture over it runs nine
            // times brighter than the number this building was tuned at. Halving the count takes out
            // the fill between the cones; it does not touch what is directly overhead. `TODO.md`.
            float[] xs = { -width / 4f, width / 4f };
            float[] zs = { -depth / 4f, depth / 4f };

            const float panelSize = 1.4f, panelThickness = 0.04f;
            float heightRatio = height / RoomHeight;

            int index = 0;
            foreach (float x in xs)
                foreach (float z in zs)
                {
                    GameObject fixture = new GameObject($"Fixture_{index++}");
                    fixture.transform.SetParent(root.transform, false);
                    fixture.transform.localPosition = new Vector3(x, height, z);

                    Prim(PrimitiveType.Cube, "Panel", fixture.transform,
                        new Vector3(0f, -panelThickness / 2f, 0f),
                        new Vector3(panelSize, panelThickness, panelSize),
                        emissiveMat, removeCollider: true);

                    GameObject lightGO = new GameObject("Light");
                    lightGO.transform.SetParent(fixture.transform, false);
                    lightGO.transform.localPosition = new Vector3(0f, -panelThickness, 0f);
                    lightGO.transform.localRotation = Quaternion.Euler(90f, 0f, 0f);

                    Light light = lightGO.AddComponent<Light>();
                    light.type = LightType.Spot;
                    light.spotAngle = CeilingSpotAngle;
                    light.innerSpotAngle = 45f;
                    // Far enough to reach the floor with the cone's edge, not just its axis. Taken
                    // from the fixtures' own spacing, so it followed the grid from 3x3 to 2x2 without
                    // having to be retuned.
                    light.range = Mathf.Sqrt(height * height + (width / 4f) * (width / 4f)) * 1.15f;
                    // The same inverse-square move that took 9 to 10.5 when the ceiling rose 8%.
                    light.intensity = CeilingLightIntensity * heightRatio * heightRatio;
                    light.color = new Color(0.99f, 0.99f, 1f);
                    // NO SHADOWS AT ALL in here. Every additional light's shadow shares one atlas, and
                    // several casters in one room would take the whole of it from the rest of the cycle.
                    light.shadows = LightShadows.None;
                    light.renderMode = LightRenderMode.ForcePixel;
                }
        }

        // ==================================================== ROOM3-2N'S SECOND STOREY, AND ITS THIRD
        //
        // **A ROOM THREE STOREYS TALL WITH NOTHING IN IT IS NOT BIG, IT IS EMPTY** (2026-08-21, by
        // request: more structure, things coming up out of the floor, and a half-floor like a second
        // storey - the kind that is open in the middle). Height only reads as height when there is
        // something AT the heights. Two partial decks, five columns and seven blocks that come up out
        // of the floor are what turn sixteen metres of air into a place with an up and a down.
        //
        // Everything here is authored off the grid the walls are: a deck's surface is a whole number
        // of ROWS off the floor, a block's footprint is a whole CELL, and a block's travel is a whole
        // number of rows. That is what lets the coloured stairs arrive exactly on a deck without
        // either layout ever being measured against the other.

        // ROOM3-2N'S TWO LIFT SHAFTS, placed off the decks rather than eyeballed.
        //
        // Lift A stands beside deck A's inner edge on the open side; lift B stands inside deck B's
        // void. Both are written here rather than inside the builder because they are facts about
        // THIS ROOM's floor plan, and the builder is about what a lift is.
        private const float DeckALiftPad = 2.0f;
        // Deck A is two cells deep down the west wall; its edge plus half a pad puts the panel's west
        // face on that edge.
        private const float DeckALiftX = -RoomWidth + 2f * GridCellWidth + DeckALiftPad / 2f;
        private const float DeckALiftZ = 2.0f;
        // **HOW HIGH A PANEL SITS ABOVE THE FLOOR IT RESTS ON, and it is not decoration.** A slab
        // whose top face were exactly flush with the deck below it would occupy the same space as that
        // deck's own slab - `DeckSlab` is 0.25 thick - which is the coplanar-faces rule broken in the
        // worst way, two solids sharing a volume. A step clears it, reads as a platform rather than as
        // a seam in the floor, and is well under the 0.72m the controller walks up.
        private const float LiftRestingStep = 0.20f;

        // Deck B's void is 1.75 wide (one cell) and runs z 5.25 to 8.75. 1.6 leaves 7.5cm of daylight
        // on each side - enough that the slab is never scraping the deck it passes through, tight
        // enough that the gap is not a place to fall down.
        private const float DeckBLiftPad = 1.6f;
        private const float DeckBLiftX = -3f * GridCellWidth;
        private const float DeckBVoidMaxZ = 8.75f;

        private const float DeckSlab = 0.25f;
        // How far a deck runs INTO the wall it lands on. Not zero, because a deck that stops exactly
        // on the wall's panel face puts one of its own faces on that plane; not `WallDepth`, because
        // that reaches the backing plane and does the same thing one layer further in. 0.06 is
        // between the two, which is the only place it can be - `docs/gotchas.md`.
        private const float DeckIntoWall = 0.06f;
        private const int DeckARows = 4;
        private const int DeckBRows = 8;

        // A DECK: a partial floor, the rectangles it is made of, and the holes cut in it. A `Rect`'s
        // x and y are x and z in the room's frame throughout this section.
        private struct Mezzanine
        {
            public string name;
            public float surfaceY;
            public Rect[] area;
            public Rect[] voids;
        }

        private static Mezzanine[] PlanMezzanines(float width, float depth)
        {
            float wx = width / 2f + DeckIntoWall;
            float wz = depth / 2f + DeckIntoWall;

            return new[]
            {
                // DECK A, one storey up: an L down the west wall and along the north. **No parapet
                // anywhere on it**, and that is deliberate rather than unfinished - the whole request
                // was for a floor you can see past, and a rail on the inside edge would hide the one
                // thing this room is for, which is looking down at which colour of step is out.
                new Mezzanine
                {
                    name = "DeckA",
                    surfaceY = DeckARows * GridCellHeight,
                    area = new[]
                    {
                        Rect.MinMaxRect(-wx, -7f, -width / 2f + 2f * GridCellWidth, 7f),
                        Rect.MinMaxRect(-wx, 7f, wx, wz),
                    },
                    // **ONE HOLE, FOR THE SECOND LIFT'S COLUMN TO PASS THROUGH.** That lift runs
                    // between the two decks and its glass column is carried to the ground floor, so
                    // it has to cross this one. Cut rather than clipped: a tube intersecting a slab
                    // is two solids sharing a volume, and this deck is already built by subtracting
                    // rectangles, so a hole costs one entry.
                    //
                    // Sized off the column rather than chosen - `DeckBLiftPad * 0.28` is the tube's
                    // own diameter, and a quarter-metre of daylight round it keeps the two surfaces
                    // from grazing. It sits under the panel's rest position, so when the lift is down
                    // the hole is covered by the thing that made it.
                    voids = new[]
                    {
                        Rect.MinMaxRect(
                            DeckBLiftX - DeckBLiftPad * 0.14f - 0.25f,
                            DeckBVoidMaxZ - DeckBLiftPad / 2f - DeckBLiftPad * 0.14f - 0.25f,
                            DeckBLiftX + DeckBLiftPad * 0.14f + 0.25f,
                            DeckBVoidMaxZ - DeckBLiftPad / 2f + DeckBLiftPad * 0.14f + 0.25f),
                    },
                },

                // DECK B, two storeys up, over the north-west quarter, with a square cut clean out of
                // the middle. That hole is the request taken literally: standing on deck B you look
                // through it onto deck A and past deck A's open side to the floor, which is three
                // storeys in one glance and the only place in the building you can get one.
                new Mezzanine
                {
                    name = "DeckB",
                    surfaceY = DeckBRows * GridCellHeight,
                    // **3.62 AND NOT 3.5, WHICH IS MEASURED RATHER THAN CHOSEN.** A deck buried in a
                    // wall has an end cap inside that wall, and at 3.5 deck B's landed 5mm off a west
                    // wall panel's edge while overlapping it - `CycleThreeDiagnostics` found it, the
                    // eye would have found it later as a flickering sliver at the top of the stair.
                    // Nothing here is on the wall grid on purpose: an edge that ends INSIDE a wall
                    // must miss that wall's panel lines, and the only way to be sure is to scan.
                    area = new[] { Rect.MinMaxRect(-wx, 3.62f, -GridCellWidth, wz) },
                    voids = new[]
                    {
                        Rect.MinMaxRect(-3.5f * GridCellWidth, 5.25f,
                                        -2.5f * GridCellWidth, 8.75f),
                    },
                },
            };
        }

        private static void BuildMezzanines(Transform room, float width, float depth,
                                            Material floorMat, Material panelMat)
        {
            GameObject root = new GameObject("Mezzanines");
            root.transform.SetParent(room, false);

            foreach (Mezzanine deck in PlanMezzanines(width, depth))
            {
                var parts = new System.Collections.Generic.List<Rect>(deck.area);
                parts = SubtractRects(parts, deck.voids);

                GameObject deckGO = new GameObject(deck.name);
                deckGO.transform.SetParent(root.transform, false);

                int i = 0;
                foreach (Rect part in parts)
                {
                    if (part.width < 0.02f || part.height < 0.02f) continue;
                    Prim(PrimitiveType.Cube, $"Slab_{i++:00}", deckGO.transform,
                        new Vector3(part.center.x, deck.surfaceY - DeckSlab / 2f, part.center.y),
                        new Vector3(part.width, DeckSlab, part.height), floorMat);
                }
            }

            BuildDeckColumns(root.transform, panelMat);
        }

        // **~~A dark edge beam on every exposed deck edge~~ REMOVED 2026-08-28, by request.** It was
        // built to make a bare slab read as a floor sitting on something, and what it actually did was
        // draw a heavy black outline round both mezzanines - in a white building whose only other dark
        // lines are the wall grooves, that read as a diagram of the decks rather than as structure.
        //
        // **The lifts keep their black rims**, and the difference is worth keeping straight: a rim on
        // a 2m platform is a mark on a thing you stand on, and an outline round a 17m mezzanine is a
        // border round the room. Same material, same idea, opposite result at opposite scales.
        //
        // THE COLUMNS UNDER THEM. A deck hung off two walls needs no support to stand up in a game
        // engine, and does need one to look like it is standing up.
        private static void BuildDeckColumns(Transform parent, Material mat)
        {
            float aTop = DeckARows * GridCellHeight;
            float aUnder = aTop - DeckSlab;
            float bUnder = DeckBRows * GridCellHeight - DeckSlab;

            void Column(string name, float x, float z, float from, float to) =>
                Prim(PrimitiveType.Cube, name, parent,
                    new Vector3(x, (from + to) / 2f, z),
                    new Vector3(0.5f, to - from, 0.5f), mat);

            Column("Column_A0", -5.75f, -6f, 0f, aUnder);
            Column("Column_A1", -5.75f, 6f, 0f, aUnder);
            Column("Column_A2", 7.5f, 7.6f, 0f, aUnder);
            // Ten metres of column straight off the floor, past deck A without touching it, up to
            // deck B. It is the one thing in the room that shows the whole height at once.
            Column("Column_B0", -2.25f, 4.4f, 0f, bUnder);
            Column("Column_B1", -2.25f, 9.8f, aTop, bUnder);
        }

        // ==================================================== WHAT FINISHING THE CUBE COSTS
        //
        // The clock stops, the cube goes into the floor, every structure in cycle 3 leaves, and the
        // facility says what the player has done. `FacilityFailure` owns the sequence; this owns the
        // LIST - which is the only part of it that needs to know what was built in here.
        //
        // **GATHERED, NOT ENUMERATED.** Every room's own children are walked and everything that is
        // not the SHELL is a mover. Naming the decks, the lifts, the beam, the bed and the pads by
        // hand would be a list to keep in step with a cycle that is still being built - and the
        // failure mode of forgetting one is a white room with a lift still standing in it, which is
        // the one thing this sequence must not leave behind.
        //
        // What stays is what makes the room a room: floor, ceiling, walls, the panels on them, the
        // lights, the gates that ARE walls, the reflection probe and the gas emitters the boundary
        // owns. Everything else is furniture.
        private static readonly string[] FailureKeeps =
        {
            "Floor", "Ceiling", "Wall_", "Gate", "ReflectionProbe", "_CeilingLights", "_Gas",
        };

        // How far a thing travels before it is switched off. Down goes clear under the floor slab;
        // sideways goes past the far wall of a room twice the standard size. Both only have to be
        // "out of sight", and being generous costs nothing - the object is gone at the end of it.
        private const float FailureDropDistance = 9f;
        private const float FailureSlideDistance = 16f;
        // The wave spreads from the cube at roughly a room a second, which is slow enough to watch
        // and fast enough that the room is empty before the announcement finishes.
        private const float FailureWaveSeconds = 2.6f;
        private const float FailureMoveSeconds = 1.9f;
        // Below this above its room's floor, a thing is STANDING and goes down through it. Above it,
        // a thing is hung or held up and goes sideways. Measured off each object rather than listed,
        // so a new prop is classified by what it is rather than by being remembered here.
        private const float FailureStandingClearance = 0.35f;

        private static FacilityFailure BuildFacilityFailure(Transform cycleRoot, BedlamCube cube,
                                                            WallPanelDisplay panels)
        {
            if (cube == null) return null;

            GameObject go = new GameObject("FacilityFailure");
            go.transform.SetParent(cycleRoot, false);

            FacilityFailure failure = go.AddComponent<FacilityFailure>();
            // The blocks and nothing else. The mat and the rope round it are the STAND, and they
            // leave with the rest of the furniture - the cube goes first and on its own because it
            // is the only thing in this room the player made.
            failure.cube = cube.transform.Find("Cube");
            failure.wallPanels = panels;
            // 2D, at 0 spatial blend: an evacuation siren comes out of the whole building, and one
            // that got quieter as the player walked away from a speaker would be a speaker.
            failure.sirenSource = MakeSource(go.transform, "Siren", 0f, 0.55f, loop: true);
            failure.sirenClip = LoadClip(SfxDir, "sfx_alarm_siren");
            failure.wayDownSign = wayDownHint;
            // `cameraShaker` and `narration` live in the core scene and are bound at runtime by
            // `CycleBinding` - see the note there.

            var movers = new System.Collections.Generic.List<FacilityFailure.Mover>();
            Vector3 from = cube.aim != null ? cube.aim.position : cube.transform.position;
            float furthest = 0.001f;

            foreach (Transform room in cycleRoot.GetComponentsInChildren<Transform>(true))
            {
                // A ROOM, NOT ANYTHING WHOSE NAME BEGINS THAT WAY. `Room3_1_CeilingLights` does,
                // and the first version of this walked into it and took all four fixtures out of
                // every room in the cycle - which leaves a white room the player cannot see. The
                // keep list is the same one the children are filtered against, applied one level up:
                // a group that is part of the shell has no contents that are furniture.
                if (!room.name.StartsWith("Room3_") || room.name.EndsWith("_Root")) continue;
                if (IsFailureKeep(room.name)) continue;
                // **NOT THE ROOM THE PLAYER IS STANDING IN.** room3-0 is where the break happens and
                // its floor is the way down to cycle 4; taking it apart would be taking apart the
                // thing being escaped through. What comes apart is the cycle BEHIND them, seen from
                // room3-0's mouth looking back over deck B and down sixteen metres - which is the
                // only place in the building that view exists.
                if (room.name == "Room3_0") continue;

                foreach (Transform child in room)
                {
                    if (IsFailureKeep(child.name)) continue;
                    AddFailureMovers(child, room.position, from, movers, ref furthest);
                }
            }

            // THE WAVE, normalised after the fact. Distance is collected first and turned into
            // seconds here, because "how long until this one goes" is a fraction of the room and the
            // room's size is not known until every mover has been found.
            for (int i = 0; i < movers.Count; i++)
            {
                FacilityFailure.Mover m = movers[i];
                m.delay = m.delay / furthest * FailureWaveSeconds;
                movers[i] = m;
            }

            failure.movers = movers.ToArray();

            int down = 0;
            foreach (FacilityFailure.Mover m in movers) if (m.travel.y < -0.5f) down++;
            Debug.Log($"[SceneBuilder] Facility failure: {movers.Count} structures leave cycle 3 "
                    + $"({down} through the floor, {movers.Count - down} sideways), over "
                    + $"{FailureWaveSeconds + FailureMoveSeconds:0.#}s from the cube outward.");
            return failure;
        }

        // THE ONE GROUP THAT IS NOT ONE STRUCTURE.
        //
        // `Mezzanines` is both decks AND the five columns under them. Taken whole it measures from
        // the floor to ten metres up, so it classifies as STANDING and is driven down through the
        // ground floor the player is watching from. Split, each piece gets the answer it deserves:
        // the columns reach the floor and are swallowed by it, the decks do not and slide out.
        //
        // **A LIST OF ONE, AND IT IS A LIST BECAUSE THE DERIVED VERSION WAS WRONG.** The first
        // attempt split anything taller than a storey and a half, on the reasoning that nothing that
        // tall is a single structure. It caught the mezzanines and three things it should not have:
        // the beam (its own segments reach the ceiling call sixteen metres up), the upper lift (its
        // glass column runs the whole height of the room) and the cube's own stand - whose bounds at
        // BUILD time include twelve blocks scattered over three storeys, a state that by definition
        // cannot exist when this sequence runs. A rule measured against a scene that is saved
        // unsolved cannot describe a room that has just been solved.
        private static readonly string[] FailureSplits = { "Mezzanines" };

        private static void AddFailureMovers(Transform what, Vector3 roomAt, Vector3 from,
                                             System.Collections.Generic.List<FacilityFailure.Mover> movers,
                                             ref float furthest)
        {
            Bounds b = MeasuredBounds(what.gameObject);
            if (b.size == Vector3.zero) return;

            if (System.Array.IndexOf(FailureSplits, what.name) >= 0 && what.childCount > 0)
            {
                foreach (Transform part in what) AddFailureMovers(part, roomAt, from, movers, ref furthest);
                return;
            }

            // STANDING OR HELD UP. A bed, a plinth and a lift's own shaft all reach the floor and
            // are swallowed by it; a deck, a receiver on a wall and the beam's muzzle do not, and a
            // thing with nothing under it cannot sink through anything.
            bool standing = b.min.y - roomAt.y < FailureStandingClearance;
            Vector3 outward = what.position - roomAt;
            outward.y = 0f;
            // A thing exactly on the room's axis has no side to leave by. West, arbitrarily and
            // consistently - it only has to be A direction.
            if (outward.sqrMagnitude < 0.01f) outward = Vector3.left;

            movers.Add(new FacilityFailure.Mover
            {
                what = what,
                travel = standing
                    ? Vector3.down * FailureDropDistance
                    : outward.normalized * FailureSlideDistance,
                // Distance for now; turned into seconds by the caller, once the furthest thing in
                // the cycle is known.
                delay = Vector3.Distance(what.position, from),
                duration = FailureMoveSeconds,
            });
            furthest = Mathf.Max(furthest, movers[movers.Count - 1].delay);
        }

        private static bool IsFailureKeep(string name)
        {
            foreach (string keep in FailureKeeps)
                if (name.StartsWith(keep) || name.EndsWith(keep)) return true;
            return false;
        }

        // **A CYCLE BOUNDARY THE SIZE OF A ROOM.** `BuildCycleExit` opens one grid cell in a floor;
        // this opens room4-1's whole ceiling, which is what "the way down is in the middle of the
        // room" turns into once the room below is the thing being opened onto.
        //
        // TWO LEAVES THAT PART, not one slab that slides. A single 8.75m lid has nowhere to go: it
        // would have to travel its own width, and room3-2N has exactly 4.375m of floor either side of
        // the hole to hide in. Halved, each leaf travels its own half-width and parks exactly under
        // the floor beside it - the same trick the panel gates use, at ten times the size.
        //
        // ONE LID, NOT TWO. `BuildCycleExit` carries a ceiling lid as well because it opens onto a
        // room whose own ceiling is otherwise intact; here room4-1 has NO ceiling of its own - the
        // underside of this lid IS its ceiling, one service void above its walls. So there is one
        // slab, and what the player falls through is the void the skirt encloses.
        private static CycleExit BuildRoomSizedExit(Transform parent, Material floorMat, Transform player)
        {
            GameObject go = new GameObject("CycleExit");
            go.transform.SetParent(parent, false);
            go.transform.localPosition = new Vector3(0f, 0f, CycleExitZ);

            float halfW = RoomWidth / 2f;

            GameObject west = Prim(PrimitiveType.Cube, "Cover_Floor_West", go.transform,
                new Vector3(-halfW / 2f, -WallThickness / 2f, 0f),
                new Vector3(halfW, WallThickness, RoomDepth), floorMat);
            GameObject east = Prim(PrimitiveType.Cube, "Cover_Floor_East", go.transform,
                new Vector3(halfW / 2f, -WallThickness / 2f, 0f),
                new Vector3(halfW, WallThickness, RoomDepth), floorMat);

            CycleExit exit = go.AddComponent<CycleExit>();
            exit.covers = new[] { west.transform, east.transform };
            // Its own half-width each way, so each leaf ends exactly under the floor beside the hole.
            // No drop with it: these retract INTO the slab they are flush with, which is solid, so
            // there is nothing to be coplanar with once they are inside it.
            exit.openOffsets = new[] { new Vector3(-halfW, 0f, 0f), new Vector3(halfW, 0f, 0f) };
            // Slower than a hatch, because it is ten times the hatch. The seal is quicker than the
            // open for the reason every door in this game is: closing behind you is not a thing to
            // watch.
            exit.openDuration = 3.4f;
            exit.sealDuration = 1.6f;
            exit.player = player;
            exit.audioSource = MakeSource(go.transform, "ExitAudio", 1f, 0.9f);
            exit.openClip = LoadClip(SfxDir, "sfx_door_open");
            exit.sealClip = LoadClip(SfxDir, "sfx_door_open");
            return exit;
        }

        // The void between room3-2N's floor and room4-1's walls, walled in. Without it the gap is
        // open at the sides and the hole looks out into nothing on the way down.
        private static void BuildRoomSizedSkirt(Transform parent, Material mat)
        {
            GameObject skirt = new GameObject("ExitSkirt_Cycle3");
            skirt.transform.SetParent(parent, false);
            skirt.transform.localPosition = new Vector3(0f, -WallThickness, CycleExitZ);

            float halfW = RoomWidth / 2f, halfD = RoomDepth / 2f;
            float outer = RoomDepth + 2f * WallThickness;

            Prim(PrimitiveType.Cube, "Skirt_West", skirt.transform,
                new Vector3(-halfW - WallThickness / 2f, -ServiceVoid / 2f, 0f),
                new Vector3(WallThickness, ServiceVoid, outer), mat);
            Prim(PrimitiveType.Cube, "Skirt_East", skirt.transform,
                new Vector3(halfW + WallThickness / 2f, -ServiceVoid / 2f, 0f),
                new Vector3(WallThickness, ServiceVoid, outer), mat);
            Prim(PrimitiveType.Cube, "Skirt_South", skirt.transform,
                new Vector3(0f, -ServiceVoid / 2f, -halfD - WallThickness / 2f),
                new Vector3(RoomWidth, ServiceVoid, WallThickness), mat);
            Prim(PrimitiveType.Cube, "Skirt_North", skirt.transform,
                new Vector3(0f, -ServiceVoid / 2f, halfD + WallThickness / 2f),
                new Vector3(RoomWidth, ServiceVoid, WallThickness), mat);
        }

        // The bed a player falls into has to be under the hole they fell through, and the hole is
        // room3-2N's own middle now rather than a cell somebody placed.
        private static void AssertUnderCycleFourHole(Transform cycleFourRoot)
        {
            if (cycleFourRoot == null) return;

            float wantX = CycleThreeX + GridCellWidth / 2f;
            float wantZ = CycleThreeZ + NorthRoomZ;
            Vector3 at = cycleFourRoot.position;

            if (Mathf.Abs(at.x - wantX) < 0.05f && Mathf.Abs(at.z - wantZ) < 0.05f) return;

            Debug.LogError($"[SceneBuilder] Cycle 4 is not under room3-2N's opening: it is at "
                         + $"({at.x:0.##}, {at.z:0.##}) and the hole is at ({wantX:0.##}, {wantZ:0.##}). "
                         + "A player dropping through would land outside the room.");
        }

        // ==================================================== THE LADDER
        //
        // **THE WAY OUT OF ROOM3-2N IS A THING YOU CARRY IN.** There is a hole in the ceiling above
        // deck B and room3-0 on the other side of it, and no way up: the room ships with the top of
        // its own climb unreachable. The ladder is in room3-2S, two rooms away, and standing it in
        // the shaft with a left click is what turns the hole into a route.
        //
        // WHY ROOM3-2S. That room already has one job - it is where the riser pane is fetched from -
        // and this is the same job: somewhere you FETCH from rather than somewhere you look. It also
        // keeps the four-rooms-four-jobs split the cycle is built on.
        private const string LadderModel = ToolsDir + "/ladder.glb";
        private const string LadderItemId = "Ladder";
        // **DERIVED FROM THE CLIMB, not written.** Deck B to room3-0's floor, plus enough to stand
        // proud of the opening at the top - which is what a ladder does and what tells the player
        // from below that there is something up there. Shorten the gap above and the ladder follows;
        // the two cannot disagree.
        // **THE LADDER LEANS** (2026-08-31, by request: "make it look like it is leaning against the
        // wall"). Every number below follows from that one sentence and from where the wall is; none
        // of them is chosen.
        //
        // Vertical, the ladder stood in the middle of a 1.75m shaft and 35cm of it poked out of
        // room3-0's floor - a stub, with nothing to take hold of and nothing to rest on. To lean it
        // needs two things the old arrangement did not have: **a wall within reach of its head**,
        // which is why the shaft moved (`LadderShaftXZ`), and **length**, because a leaning ladder
        // covers the same rise over a longer run.
        //
        //          room3-0        |<- west wall
        //                         |__
        //                         |  \   head, LadderHeadRise above the floor
        //          ---------------+---\-------  room3-0's floor / the shaft mouth
        //                         |    \
        //          room3-2N       |     \  LadderLeanDegrees off vertical
        //                         |      \
        //          ===============+=======*==  deck B, the foot on its mark
        //
        // How much height there is to gain: deck B to room3-0's floor.
        private const float LadderClimbRise = RoomZeroY - DeckBSurfaceY;      // 5.96
        // How far the head stands proud of the floor once it is up there. A grab rail - the height a
        // hand wants when it is stepping off the top of something, and what turns a hole in a floor
        // into somewhere you can obviously climb out of.
        private const float LadderHeadRise = 1.20f;
        // OFF VERTICAL. Twelve degrees is what a real ladder is set at, and here it is also what
        // keeps the CLIMBER inside the hole: the ladder's head is against the wall, so the shallower
        // the lean the closer to that wall the whole climb runs. At 12 degrees the player's capsule
        // passes the shaft mouth with 8cm to spare on the west side; at 6 it would clip the rim.
        private const float LadderLeanDegrees = 12f;
        // How far the head sits off the wall FACE - half the ladder's own thickness, so it touches
        // rather than intersects. `BuildPanelWall` is given the finished panel surface, so a room's
        // half-width IS its visible wall (see that method's `faceCenterAtBase`).
        private const float LadderHeadClearance = 0.13f;

        // And the rest is trigonometry. `static readonly` rather than `const` because `Mathf` cannot
        // run in a constant initialiser - the values are still fixed at load and still written in
        // exactly one place.
        private static readonly float LadderRun =
            (LadderClimbRise + LadderHeadRise) * Mathf.Tan(LadderLeanDegrees * Mathf.Deg2Rad);
        private static readonly float LadderLength =
            Mathf.Sqrt(LadderRun * LadderRun
                     + (LadderClimbRise + LadderHeadRise) * (LadderClimbRise + LadderHeadRise));
        // UP THE LADDER, as a unit vector in the room's own frame. The lean is westward, so x is
        // negative; z is untouched, which keeps the climb in one plane and the shaft square.
        private static readonly Vector3 LadderClimbDir =
            new Vector3(-Mathf.Sin(LadderLeanDegrees * Mathf.Deg2Rad),
                         Mathf.Cos(LadderLeanDegrees * Mathf.Deg2Rad), 0f);
        // WHERE THE FOOT STANDS, which is the head's x plus the whole run. Room3-2N's west wall face
        // is at -RoomWidth (the room is two `RoomWidth` across), and room3-0 shares that same line -
        // which is what makes one number serve both rooms.
        private static readonly float LadderFootX =
            -RoomWidth + LadderHeadClearance + LadderRun;
        // Where it lies in room3-2S before anybody moves it, and how it is held.
        private static readonly Vector3 LadderRestXZ = new Vector3(2.6f, 0f, -2.2f);

        private static CarryableItem BuildLadder(Transform room, Material propMat)
        {
            (GameObject go, Bounds box) = PlaceModelLocal(LadderModel, room, "Ladder",
                new Vector3(LadderRestXZ.x, 0f, LadderRestXZ.z), Quaternion.identity, LadderLength);
            if (go == null) return null;

            // LYING DOWN, because it is not standing in anything yet. Which axis is its length is
            // measured rather than assumed - the model comes in with its own idea of up, and this
            // project has been caught by that once already (see `BedlamRopePitch`).
            Debug.Log($"[SceneBuilder] Ladder as imported: {box.size.x:0.##} x {box.size.y:0.##} x "
                    + $"{box.size.z:0.##}m. Its longest side is the one the mount stands upright.");

            // Sat on the floor. `PlaceModelLocal` centres what it places, which buries half of
            // anything that is meant to rest on something.
            go.transform.position += Vector3.up * (room.position.y - box.min.y);
            box = MeasuredBounds(go);

            // **THE PIVOT MOVES TO THE MIDDLE OF THE LADDER** (2026-08-30, by request: "hold it by
            // the middle instead"), and it is the one change that retires a whole family of bugs
            // rather than another of them.
            //
            // This model's origin is at one END, and five separate faults came out of that in three
            // days - it could not be picked up, then only in the middle, then not by ghosts, then it
            // landed facing north, then it sank under the bed (`docs/gotchas.md`). Every one was some
            // system asking "where is this object" and getting an answer 3m from what the player was
            // looking at. Centred, they all get the obvious answer.
            //
            // Done by moving the ROOT and putting the children back, which leaves the mesh exactly
            // where it is in the world and changes only what the transform's origin means. The same
            // move `MakeChessPiece` makes for the mirrored half of the chess set, for the same
            // reason: the composite is untouched and what reads off the transform is fixed.
            {
                Vector3 delta = box.center - go.transform.position;
                var kids = new System.Collections.Generic.List<Transform>();
                foreach (Transform kid in go.transform) kids.Add(kid);
                go.transform.position = box.center;
                foreach (Transform kid in kids) kid.position -= delta;
            }

            BoxCollider trigger = go.AddComponent<BoxCollider>();
            trigger.isTrigger = true;
            trigger.center = go.transform.InverseTransformPoint(box.center);
            trigger.size = Abs(go.transform.InverseTransformVector(box.size + Vector3.one * 0.8f));

            // THE PROMPT ANCHOR. It starts at the middle - which is now the pivot as well - and
            // `LongItemAnchor` slides it from there to wherever along the length the player is
            // looking, so E works anywhere on the ladder rather than at one point on it.
            GameObject anchor = new GameObject("HintAnchor");
            anchor.transform.SetParent(go.transform, false);
            anchor.transform.position = box.center;

            // THE SPAN, MEASURED: end to end along the model's own long axis, which the import log
            // above prints. Centred on the pivot now, which is what `CarryableItem.heldSpan` means.
            Vector3 span = go.transform.InverseTransformVector(
                Vector3.forward * (box.size.z > box.size.x ? box.size.z : box.size.x));

            LongItemAnchor slider = go.AddComponent<LongItemAnchor>();
            slider.anchor = anchor.transform;
            // `item` is assigned after it exists, below.

            CarryableItem item = go.AddComponent<CarryableItem>();
            item.itemId = LadderItemId;
            item.displayName = "LADDER";
            item.icon = LadderIcon();
            item.hintAnchor = anchor.transform;
            // **IT LIES WHERE IT WAS PUT DOWN.** Without this `LieDown` restores the pose it was
            // BUILT in, which for this model is lying along +Z - so a ladder dropped facing anywhere
            // snapped round to north. See `CarryableItem.keepsDropYaw`.
            item.keepsDropYaw = true;
            // The same line, read by the other thing that needs it: `HeldItemClearance` sweeps it so
            // the whole ladder meets a wall rather than only the end in the hand.
            item.heldSpan = span;
            // Half its own height, which is what `floorY` means for an object whose pivot IS its
            // centre - and this one's is, since the re-centring above.
            item.floorY = box.size.y / 2f;
            // **IT POSES ITSELF, LEVEL, OFF THE BODY** - `LevelCarry`, which is `Mirror`'s trick made
            // general. The ordinary hold hangs off the CAMERA, so the ladder inherited the player's
            // pitch: look down and eight metres of it drove into the floor, look up and into the
            // ceiling, and both read as the ladder disappearing because what was left on screen was
            // the inside of a slab. Reported from play as exactly that.
            //
            // Level and yawed off the body, it cannot do either. Front to back along the player's own
            // axis (by request), four degrees off it so a long thin thing is not a single line
            // vanishing at the crosshair.
            //
            // `handLocalPosition` is left as the fallback for anything that ever poses this WITHOUT
            // the component - a ghost's belt layout reads it - and `posesItself` is what tells
            // `HeldItemClearance` not to drag an object that is placing itself.
            item.posesItself = true;
            item.handLocalPosition = new Vector3(0.42f, -0.58f, 0.55f);
            item.handLocalEuler = new Vector3(0f, 4f, 4f);

            LevelCarry carry = go.AddComponent<LevelCarry>();
            carry.item = item;
            // Chest height and just off the shoulder, which is where a person's hands are on a ladder
            // they are walking with.
            carry.carryHeight = 1.15f;
            carry.carryAhead = 0.50f;
            carry.carrySide = 0.34f;
            carry.yaw = 4f;
            item.handLocalScale = go.transform.lossyScale;
            item.audioSource = MakeSource(go.transform, "PickupAudio", 1f, 0.85f);
            item.pickupClip = LoadClip(SfxDir, "sfx_item_pickup");
            slider.item = item;
            return item;
        }

        // THE SPOT ON DECK B, and everything the climb needs to know. Built as a child of room3-2N so
        // its two heights can be stated in that room's frame and turned into world ones here.
        private static LadderMount BuildLadderMount(Transform room, Material propMat,
                                                   Transform dismounts)
        {
            GameObject go = new GameObject("LadderMount");
            go.transform.SetParent(room, false);
            // **AT THE FOOT, WHICH IS NO LONGER UNDER THE HOLE.** A leaning ladder stands out from
            // what it leans on: the mark is `LadderRun` east of the shaft's centre, and the head is
            // what sits at the mouth. See `LadderLeanDegrees` for the whole arrangement.
            go.transform.localPosition = new Vector3(LadderFootX, DeckBSurfaceY, LadderShaftXZ.y);

            // A MARK ON THE DECK, so the spot exists before the ladder does. Near-black among white
            // surfaces reads as a recess, which is the same trick every plinth top in the game plays.
            Prim(PrimitiveType.Cube, "Mark", go.transform, new Vector3(0f, 0.008f, 0f),
                new Vector3(GridCellWidth * 0.8f, 0.014f, GridCellWidth * 0.8f),
                MakeColorMaterial("LadderMark", new Color(0.14f, 0.14f, 0.16f)), removeCollider: true);

            // Where an accepted ladder stands: at the mark, upright, its foot on the deck. The seat's
            // own frame is what the ladder arrives in, so the rotation lives here and the ladder
            // itself needs to know nothing about which way up it was carried.
            GameObject seat = new GameObject("Seat");
            seat.transform.SetParent(go.transform, false);
            // HALF THE LADDER UP THE SLANT. Its pivot is its own centre (`BuildLadder` re-centres
            // it), so the seat is the midpoint of the line from the foot to the head.
            seat.transform.localPosition = LadderClimbDir * (LadderLength / 2f);
            // MEASURED, NOT WRITTEN. The model's long axis is its own; this turns whatever that is
            // onto world up. Logged by `BuildLadder` so a re-export that changes it is visible.
            // **AND THEN LEANS IT.** About +Z, which takes the model's up (+Y after the turn above)
            // toward -X - the same westward lean `LadderClimbDir` is built from, so the ladder is
            // drawn along the line the climb actually runs on.
            seat.transform.localRotation = Quaternion.AngleAxis(LadderLeanDegrees, Vector3.forward)
                                         * Quaternion.Euler(-90f, 0f, 0f);

            // THE PROMPT, AT CHEST HEIGHT IN THE SHAFT rather than on the mark. See
            // `LadderMount.hintAnchor`: a point on the deck is a point anything standing on the deck
            // occludes, and an occluded anchor is a left click that does nothing.
            GameObject hint = new GameObject("HintAnchor");
            hint.transform.SetParent(go.transform, false);
            // Up the ladder's own line rather than straight up, so the disc hangs where the ladder
            // will be rather than beside it.
            hint.transform.localPosition = LadderClimbDir * 1.2f;

            LadderMount mount = go.AddComponent<LadderMount>();
            mount.acceptedItemId = LadderItemId;
            mount.seat = seat.transform;
            mount.hintAnchor = hint.transform;
            mount.bottomY = room.position.y + DeckBSurfaceY;
            mount.topY = room.position.y + RoomZeroY;
            // WHICH WAY UP THE LADDER GOES, in world space - the volume follows it and so does the
            // climb. `TransformDirection` rather than the local vector straight across, so a room
            // that is ever yawed does not silently send the climb sideways.
            mount.climbDirection = room.TransformDirection(LadderClimbDir).normalized;
            // EVERY LIP room3-0 AUTHORED, in order. `LadderMount` picks the nearest at the moment
            // somebody steps off - see the note on `Dismounts` in `BuildBreakRoomThree`.
            if (dismounts != null)
            {
                var spots = new System.Collections.Generic.List<Transform>();
                foreach (Transform spot in dismounts) spots.Add(spot);
                mount.dismounts = spots.ToArray();
                if (spots.Count == 0)
                    Debug.LogError("[SceneBuilder] the ladder mount has no step-off points. A climb "
                                 + "would end with the player standing over the hole.");
            }
            mount.audioSource = MakeSource(go.transform, "MountAudio", 1f, 0.9f);
            mount.installClip = LoadClip(SfxDir, "sfx_door_open");

            Debug.Log($"[SceneBuilder] Ladder mount on deck B at {go.transform.position}, climb "
                    + $"{mount.bottomY:0.##} to {mount.topY:0.##} ({mount.topY - mount.bottomY:0.##}m), "
                    + $"ladder {LadderLength:0.##}m leaning {LadderLeanDegrees:0.#}deg over a run of "
                    + $"{LadderRun:0.##}m. Head {LadderHeadRise:0.##}m above room3-0's floor, "
                    + $"{LadderHeadClearance:0.##}m off the west wall. Shaft centre "
                    + $"{LadderShaftXZ.x:0.##}, axis at the mouth "
                    + $"{LadderFootX - LadderClimbRise * LadderRun / (LadderClimbRise + LadderHeadRise):0.##}.");
            return mount;
        }

        // THE SIGN THAT SAYS WHAT IS MISSING: a pictogram of a ladder on the wall beside a spot with
        // no ladder in it. That pairing is the whole sentence, and it is the only thing in the room
        // that explains the hole in the ceiling.
        //
        // Built off `MakeWallFace` like cycle 2's pedestal signs, and set to full alpha for the same
        // reason theirs are: those are faded in and retired by `PanelMessage`, and this is true for
        // as long as the room is unsolved.
        private static void BuildLadderSign(Transform room, Vector3 localPos, Quaternion facing)
        {
            CanvasGroup face = MakeWallFace(room, "LadderSign", localPos, facing,
                f => MakeWallIcon(f, "Ladder", LadderIcon(), Vector2.zero, 1280f,
                                  new Color(0.20f, 0.20f, 0.23f, 0.88f)),
                worldWidth: 0.85f, withPlate: false, authoredHeight: 1600f);

            if (face != null) face.alpha = 1f;
        }

        // HOW WIDE THE CUBE'S RECESS IS, and it is the RIM: `BuildFinalSlot` cuts the hole at 0.80
        // of it. The held cube is 0.40m across (`BedlamHeldScale` of the 1.6m assembly), so the hole
        // wants to be a little over that - 0.42m here, which is 12mm of daylight on each side. The
        // 0.34 this inherited from cycle 1's console gave a 0.27m hole for a 0.40m object.
        private const float CycleThreeSlotSize = 0.53f;

        // THE FLOOR OF THAT RECESS, AS THE CUBE'S OWN UNDERSIDE.
        //
        // `BedlamSolvedCells` indexes as `(x * n + y) * n + z`, so the bottom layer of the solved
        // packing - `y == 0` - is the sixteen entries at `x * 16 + z`. Each names a piece; the model
        // gives its thirteen pieces three shared materials; so those sixteen cells resolve to
        // sixteen tiles in the cube's own three colours, laid out as the cube actually packs.
        //
        // Read out rather than written down, which is the point: there is one statement of the
        // packing in this project and this is not a second one. Change the solution and the recess
        // changes with it.
        private static void BuildCubeRecessFloor(Transform slotRoot, float across)
        {
            const int n = BedlamCells;
            float tile = across / n;
            // A hair of the dark hole left between tiles, so the grid reads as sixteen cells rather
            // than as one mottled square.
            float gap = tile * 0.10f;

            GameObject grid = new GameObject("CubeFace");
            grid.transform.SetParent(slotRoot, false);
            // Above the hole quad `BuildFinalSlot` laid down, which stays as the grout under it.
            grid.transform.localPosition = new Vector3(0f, 0.006f, 0f);

            for (int x = 0; x < n; x++)
            {
                for (int z = 0; z < n; z++)
                {
                    int piece = BedlamSolvedCells[(x * n + 0) * n + z];
                    Prim(PrimitiveType.Cube, $"Cell_{x}{z}", grid.transform,
                        new Vector3((x - (n - 1) / 2f) * tile, 0f, (z - (n - 1) / 2f) * tile),
                        new Vector3(tile - gap, 0.004f, tile - gap),
                        MakeColorMaterial($"BedlamFace_{BedlamPieceMaterial(piece)}",
                                          BedlamPieceColor(piece)),
                        removeCollider: true);
                }
            }
        }

        // WHICH OF THE MODEL'S THREE MATERIALS A PIECE WEARS. Measured off `bedlam_cube.glb` and
        // stated here because a `.glb` is not a thing this file can read at build time: pieces 0-3
        // are the blue one, 4-7 the red, 8-12 the amber. If the model is ever re-split, this is the
        // one line that has to follow it.
        private static int BedlamPieceMaterial(int piece) =>
            piece <= 3 ? 0 : piece <= 7 ? 1 : 2;

        private static Color BedlamPieceColor(int piece)
        {
            switch (BedlamPieceMaterial(piece))
            {
                // The glTF base colours, lifted off black a little: a recess is a shadowed hole and
                // pure primaries in one read as ink rather than as plastic.
                case 0: return new Color(0.12f, 0.20f, 0.78f);
                case 1: return new Color(0.78f, 0.13f, 0.13f);
                default: return new Color(0.85f, 0.62f, 0.05f);
            }
        }

        // A LADDER, DRAWN. Two stiles and four rungs - the least that reads as one at 24 pixels, and
        // the same flat orthographic style the block icon uses.
        private static Sprite LadderIcon()
        {
            var icon = new IconCanvas(128);
            icon.Bar(new Vector2(0.32f, 0.5f), new Vector2(0.055f, 0.42f));
            icon.Bar(new Vector2(0.68f, 0.5f), new Vector2(0.055f, 0.42f));
            for (int i = 0; i < 4; i++)
                icon.Bar(new Vector2(0.5f, 0.20f + i * 0.20f), new Vector2(0.24f, 0.045f));
            return SaveSprite(icon, "icon_ladder");
        }

        // ==================================================== CYCLE 4
        //
        // **ONE SEALED ROOM UNDER ROOM3-0'S HATCH: a bed, an empty chest and the gas.** Exactly what
        // cycle 3 was on the day it was started, and for the same reason - the BOUNDARY is the thing
        // being exercised, and a puzzle would be in the way of testing it. `finalRoom` stays null,
        // which is a supported state: the loop simply keeps iterating here, which is the honest
        // shape of a cycle with no puzzles in it.
        //
        // It sits a storey below ROOM3-0 rather than below cycle 3's floor - see `CycleFourFloorY`
        // for why, and `AssertCycleFourClear` for the check that makes that safe.
        private static (Transform root, Transform bedSpawn, ParticleSystem[] gas,
                        GhostInteractable[] signals)
            BuildCycleFourShell(Material floorMat, Material grooveMat, Material panelMat,
                                Material propMat)
        {
            // Its own fixture material, like cycles 2 and 3: `CeilingFixture` is one emissive
            // material shared by every room in a cycle, and a fourth cycle borrowing another's would
            // be a fourth cycle that goes dark when something two storeys up is finished.
            Material fixtureMat = MakeEmissiveMaterial("CeilingFixtureCycle4", Color.white, 3.5f);

            GameObject root = new GameObject("Room_Cycle4");
            // Axis-aligned, like cycle 3 and for the same reason: one room, nothing to avoid, and
            // whatever grows out of it can decide its own facing.
            root.transform.position = new Vector3(CycleFourX, CycleFourFloorY, CycleFourZ);

            // THE HOLE THE PLAYER ARRIVES THROUGH. Its lid is not here - it lives on the join in the
            // core scene with the floor lid above it, because one `CycleExit` drives both and a
            // reference across a scene boundary comes back null. What this room owns is the absence.
            // **NO CEILING OF ITS OWN.** The hole is the whole slab: what closes this room in is
            // room3-2N's floor, one service void above its walls, and that slab is the lid that
            // opens onto it. A ceiling here would be a second one under the first, and the player
            // would arrive by falling through both.
            Rect wholeCeiling = Rect.MinMaxRect(
                -RoomWidth, -RoomDepth, RoomWidth, RoomDepth);

            Transform r1 = BuildEmptyRoom(root.transform, "Room4_1", Vector3.zero,
                                          floorMat, grooveMat, panelMat, fixtureMat,
                                          doorwayNorth: false, ceilingHole: wholeCeiling);

            (_, Transform spawn) = BuildBed(r1, propMat, floorY: CycleFourFloorY,
                                            zCentre: CycleFourZ, yaw: 0f, xCentre: CycleFourX);

            // Empty, and wired as `GhostInteractable`s whatever is in it - which is what makes
            // putting something in one later a one-line change rather than a signal-bit problem
            // (CLAUDE.md §1.6).
            Drawer[] drawers = BuildDresser(r1, "Dresser4_1", new Vector3(-0.95f, 0f, 1.35f),
                                            yaw: 0f, withLamp: true);

            ParticleSystem[] gas = BuildGasEmitters(r1, "Room4_1_Gas", 0f);

            var signals = new GhostInteractable[drawers.Length];
            for (int i = 0; i < drawers.Length; i++) signals[i] = drawers[i];

            Debug.Log($"[SceneBuilder] Cycle 4: Room4_1 at ({CycleFourX:0.##}, {CycleFourFloorY:0.###}, "
                    + $"{CycleFourZ:0.##}), one sealed room, {signals.Length} signal(s), no way out.");
            return (root.transform, spawn, gas, signals);
        }

        private static (Cycle cycle, WallPanelDisplay display) AssembleCycleFour(
            Transform root, Transform bedSpawn, ParticleSystem[] gasEmitters,
            GhostInteractable[] signals, Texture2D testCard, Texture2D staticNoise)
        {
            var panels = new System.Collections.Generic.List<Renderer>();
            foreach (Renderer r in root.GetComponentsInChildren<Renderer>())
            {
                if (r.transform.parent == null || !r.transform.parent.name.EndsWith("_Panels")) continue;
                panels.Add(r);
            }
            WallPanelDisplay display = MakeWallPanelDisplay(
                "WallPanelDisplay_Cycle4", panels.ToArray(), testCard, staticNoise);

            GameObject go = new GameObject("Cycle4");
            Cycle cycle = go.AddComponent<Cycle>();
            cycle.bedSpawnPoint = bedSpawn;
            cycle.doors = root.GetComponentsInChildren<Door>(true);
            cycle.drawers = root.GetComponentsInChildren<Drawer>(true);
            cycle.gasEmitters = gasEmitters;
            CheckGhostSignals("Cycle 4", signals);
            cycle.ghostInteractables = signals;
            cycle.conditions = root.GetComponentsInChildren<RoomCondition>(true);
            // No room0, so no console and no way to finish. See the note in AssembleCycleTwo for what
            // a `finalRoom` costs to add when there is one.
            cycle.finalRoom = null;
            cycle.worldRoot = root;
            cycle.wallPanels = display;

            SetFloorBase(root, CycleFourFloorY);
            return (cycle, display);
        }

        // ==================================================== ROOM3-0, AND THE WAY DOWN TO CYCLE 4
        //
        // Cycle 3's `-0`, and the only room in the building that is not on its cycle's ground floor.
        //
        // **IT IS REACHED FROM DECK B, TWO STOREYS UP INSIDE ROOM3-2N.** That is the whole reason the
        // tall room exists. Everything in it - the beam, the mirrors, both lifts, the blocks spread
        // over three storeys - was a climb that ended in a dead end: deck B had nothing on it. This
        // is what the climb buys, so the light puzzle and the way out of the cycle are one errand
        // instead of two features sharing a shell.
        //
        // A DOORWAY AT 10.8m, which is a thing no other wall in this building has. `BuildPanelWall`
        // takes its cutout as a rect in the wall's own frame with y measured from the room's floor,
        // so a hole this far up costs nothing extra - but it is the first one that is not at floor
        // level, and `AssertWalkable` is aimed at it for that reason.
        private const float DeckBSurfaceY = DeckBRows * GridCellHeight;      // 10.8156

        // **ROOM3-0 SITS ON TOP OF ROOM3-2N** (2026-08-30, by request), where it was north of it for
        // a day. Its floor is one service void above that room's ceiling - the same gap every storey
        // in this building has - and the way up is a LADDER through a hole in the ceiling, not a
        // doorway in a wall. See `LadderShaft`.
        //
        // Over the room's NORTH-WEST QUARTER rather than its middle, and that is forced rather than
        // chosen: the hole has to be above DECK B, which is the only floor at that height, and deck B
        // is an L from x -8.81 to -1.75 and z 3.62 to 10.56. A standard room centred here covers the
        // bulk of it. All three are in room3-2N's own frame.
        private const float RoomZeroX = -RoomWidth / 2f;                     // -4.375
        private const float RoomZeroZ = RoomDepth / 2f;                      //  5.25
        // **THE GAP BETWEEN ROOM3-2N'S CEILING AND ROOM3-0'S FLOOR, and it is NOT a service void**
        // (2026-08-30, by request: the ladder was too long to carry).
        //
        // Every other storey in this building is `StoreyDrop` apart, of which 1.6m is plenum. That
        // 1.6m was doing nothing for the player here - it is a gap they climb THROUGH, in the dark,
        // between two holes - and it was 1.6m of ladder. At 0.35 the two slabs still cannot be
        // coplanar (the rule that stops them z-fighting) and the climb loses a fifth of its height.
        //
        // **This is the only floor pair in the game that is not a storey apart**, which is why it has
        // its own constant rather than borrowing `ServiceVoid`: the next thing to reuse that number
        // must not inherit a decision made about a ladder.
        private const float LadderVoid = 0.35f;
        private const float RoomZeroY = 3f * RoomHeight + 2f * WallThickness + LadderVoid;

        // WHERE THE LADDER STANDS, in room3-2N's frame: **the far corner of deck B** (2026-08-30, by
        // request), one cell in from the west wall and one from the north. That is as far from
        // everything as this room can put it - the square void cut through deck B, both lifts and the
        // column all sit south and east of here - and it is the corner a player crossing deck B walks
        // toward rather than past. One grid cell across, like every other hole in a floor here.
        //
        // It has to be under ROOM3-0 as well, which is what stops it going right into the corner: that
        // room covers x -8.75 to 0 and z 0 to 10.5 of this one, so the hole's own half-cell has to
        // stay inside those.
        // **THE SHAFT IS AGAINST THE WEST WALL**, moved there in 2026-08-31 so the ladder has
        // something to lean on. Its west edge is bitten 25mm INTO the wall rather than made flush
        // with it: flush puts the hole's cut edge and the wall's face on the same plane facing the
        // same way, which is the coplanar flicker CLAUDE.md §3 warns about, and it would leave a
        // 0-width sliver of floor nobody can stand on. Buried, the floor simply ends at the wall.
        //
        // The shaft's own tube walls land inside the room wall's depth for the same reason, so there
        // is no seam between them to see.
        private const float LadderWallBite = 0.025f;
        private static readonly Vector2 LadderShaftXZ =
            new Vector2(-RoomWidth - LadderWallBite + GridCellWidth / 2f, 9.2f);

        private static Rect LadderShaftHole(float xCentre, float zCentre) => Rect.MinMaxRect(
            xCentre - GridCellWidth / 2f, zCentre - GridCellWidth / 2f,
            xCentre + GridCellWidth / 2f, zCentre + GridCellWidth / 2f);

        // WHERE CYCLE 4 BEGINS: **directly under room3-2N, a storey below cycle 3's floor** - the
        // ordinary arrangement, restored (2026-08-30). It hung under room3-0 for a day, and room3-0
        // moving on top of room3-2N put that 18m above the floor; a cycle boundary that high would
        // have needed the hatch's two lids pulled apart and a long tube between them, for a fall
        // nobody sees the middle of. The way down is in room3-2N's floor now, so cycle 4 goes where
        // every other cycle has gone: one storey straight down.
        private const float CycleFourX = CycleThreeX + GridCellWidth / 2f;
        private const float CycleFourZ = CycleThreeZ + NorthRoomZ;
        private const float CycleFourFloorY = CycleThreeFloorY - StoreyDrop;
        // room3-0's position in the CYCLE's frame rather than room3-2N's: the big room is offset half
        // a cell (see BuildCycleThreeShell) and everything about this room is hung off it.
        private const float RoomZeroXInCycle = GridCellWidth / 2f + RoomZeroX;
        private const float RoomZeroZInCycle = NorthRoomZ + RoomZeroZ;

        // **THE WAY DOWN IS A ROOM-SIZED HOLE IN THE MIDDLE OF ROOM3-2N'S FLOOR** (2026-08-30, by
        // request), where every other cycle boundary in this building is one grid cell. It is
        // room4-1's whole ceiling: the storey below opens, rather than a hatch opening onto it.
        //
        // Centred on room3-2N, which is what "in the middle of the room" means and is also what puts
        // room4-1 squarely under it - the bed a player falls into has to be under the hole they fell
        // through, and `AssertUnderHatch` is what says so.
        private static readonly Rect CycleFourHole = Rect.MinMaxRect(
            -RoomWidth / 2f, -RoomDepth / 2f, RoomWidth / 2f, RoomDepth / 2f);

        // **CYCLE 3'S ESCAPE OBJECT IS THE ASSEMBLED CUBE ITSELF** (2026-08-30, by request), where
        // for a day it was a green cube on a plinth that rose beside it. Finishing the puzzle shrinks
        // the thing you built until it fits in one hand, and that is what goes in room3-0's console.
        //
        // The id and the colour stay because the SLOT still needs both: a recess is cut to a shape
        // and lit in a colour, and the shape it is cut to is a cube whichever object fills it.
        private const string CycleThreeKeyItemId = "Cycle3Key";
        private static readonly Color CycleThreeKeyColor = new Color(0.16f, 0.78f, 0.36f);

        // ROOM3-0 ITSELF: one recess, one hatch, and the break.
        //
        // ONE SLOT, because cycle 3 pays out one object (by request, 2026-08-30). That makes this the
        // shortest `-0` in the game - cycle 1 takes three and cycle 2 takes three - and the length is
        // deliberately not here: what cycle 3 charges is the CLIMB, and the console is the receipt.
        private static (Transform room, FinalRoomSequence final) BuildBreakRoomThree(
            Transform parent, Material floorMat, Material grooveMat, Material panelMat,
            Material propMat, Material fixtureMat)
        {
            // **NO DOORWAY AT ALL.** The only way in is the hole in its own floor, which is the top
            // of the ladder shaft - a room you arrive in by climbing into it. Its floor hole and
            // room3-2N's ceiling hole are the same hole, stated in each room's own frame.
            Rect hole = LadderShaftHole(LadderShaftXZ.x - RoomZeroX, LadderShaftXZ.y - RoomZeroZ);

            Transform t = BuildEmptyRoom(parent, "Room3_0",
                new Vector3(RoomZeroXInCycle, RoomZeroY, RoomZeroZInCycle),
                floorMat, grooveMat, panelMat, fixtureMat,
                doorwayNorth: false, floorHole: hole);

            // --- the console ------------------------------------------------------------------------
            GameObject rack = new GameObject("Room3_0_Console");
            rack.transform.SetParent(t, false);

            // **ALREADY STANDING**, unlike cycle 1's and cycle 2's consoles, which come up out of the
            // floor when the player arrives. By request (2026-08-30): you climb into this room and
            // the thing the cube goes on is simply there. `RewardPlinth` is still what owns it, with
            // no travel - so `FinalRoomSequence` has the reference it expects and the loop still
            // resets it, without a rise nobody asked for.
            RewardPlinth risen = rack.AddComponent<RewardPlinth>();
            risen.plinth = rack.transform;
            risen.riseHeight = 0f;
            risen.riseSeconds = 0.01f;

            GameObject unit = new GameObject("Pedestal_Cube");
            unit.transform.SetParent(rack.transform, false);
            // **IN THE MIDDLE OF THE ROOM** (2026-08-31, by request). `PedestalRowZ` puts cycle 1's
            // and cycle 2's consoles 2.8m south of centre, because in those rooms the way down opens
            // in the middle and the row has to stand clear of it. Room3-0's way down is not in this
            // room at all - it is a storey below, in room3-2N - so nothing here is competing with the
            // middle, and one object on its own belongs at the centre of the room it is the point of.
            unit.transform.localPosition = Vector3.zero;

            // **FULL HEIGHT, and the `- SocketCapThickness` this used to carry was a copy-paste from
            // room2-0.** That subtraction is right for a BALL socket, where the missing 76mm is
            // filled by a `Cap` mesh with the bowl cut out of it - a box primitive cannot have a
            // hole in it, so the top of the pedestal has to be a different object. A SQUARE recess
            // is a painted quad, not a carved bowl, and `BuildFinalSlot` builds no cap for it: the
            // pedestal's top face sat 76mm below its own rim with nothing between them, open all the
            // way round. Cycle 1's console, which uses the same square recess, always did this the
            // right way - its plinth is full height and the slot sits on top.
            Prim(PrimitiveType.Cube, "Body", unit.transform,
                 new Vector3(0f, PedestalHeight / 2f, 0f),
                 new Vector3(PedestalWidth, PedestalHeight, PedestalDepth),
                 propMat, removeCollider: true);

            BoxCollider solid = unit.AddComponent<BoxCollider>();
            solid.center = new Vector3(0f, PedestalHeight / 2f, 0f);
            solid.size = new Vector3(PedestalWidth, PedestalHeight, PedestalDepth);

            // A SQUARE RECESS FOR A SQUARE OBJECT, which is the rule cycle 1's console already
            // follows: the hole says what goes in it, and there is nothing else in the room to say
            // it. Cycle 2's four identical bowls could not - they all took the same KIND of thing -
            // and had to carry a pictogram each. One slot needs no pictogram.
            FinalSlot slot = BuildFinalSlot(unit.transform, "Slot", SlotShape.Square,
                new Vector3(0f, PedestalHeight, 0f), CycleThreeSlotSize, CycleThreeKeyColor,
                reachCentre: new Vector3(0f, -0.55f, 0.42f),
                reachSize: new Vector3(1.30f, 2.60f, 2.00f));
            slot.acceptedItemId = CycleThreeKeyItemId;
            slot.refuseClip = LoadClip(SfxDir, "sfx_switch_off");

            // **AND THE HOLE IS THE CUBE'S OWN UNDERSIDE** (2026-08-31, by request: a recess with
            // several colours in it, like the block cube, rather than a green one).
            //
            // Not a decorative pattern - it is READ OUT of `BedlamSolvedCells`. The bottom layer of
            // the solved packing is `y == 0`, which by that table's own indexing is every sixteenth
            // entry, and each cell names the piece that fills it. The model has three materials
            // (blue, red, amber) shared between its thirteen pieces, so those sixteen cells resolve
            // to sixteen colours and the recess floor is the imprint of the thing that goes in it.
            //
            // It also does the job the green was doing badly. One escape object per cycle means the
            // colour was never distinguishing anything - it was just a colour nothing in the room
            // was - and this says what fits here in the only language the cube speaks.
            BuildCubeRecessFloor(slot.transform, CycleThreeSlotSize * 0.80f);

            // --- the way in -------------------------------------------------------------------------
            //
            // THE TOP OF THE LADDER, which is the only way into this room. **The console does NOT
            // rise here** (2026-08-30, by request: the structure the cube goes on is already
            // standing when you arrive) - the trigger is kept so `FinalRoomSequence.Active` still
            // turns on when somebody gets here, which is what makes the slot answer a press.
            GameObject escapeGO = new GameObject("EscapeTrigger_Cycle3");
            escapeGO.transform.SetParent(t, false);
            escapeGO.transform.localPosition = new Vector3(hole.center.x, 0f, hole.center.y);
            EscapeTrigger escape = escapeGO.AddComponent<EscapeTrigger>();
            // **NO DOOR TO BE OPEN, AND THAT USED TO MEAN NOBODY EVER ARRIVED.** `TryArm` began by
            // requiring one, which is right for every other final room in the building and fatal
            // here: `PlayerArrived` stayed false, `FinalRoomSequence.Active` with it, and the recess
            // refused the cube in silence. See `EscapeTrigger.requiresOpenDoor`.
            escape.requiresOpenDoor = false;
            // BOTH HALF-EXTENTS, and the depth was the second half of the same bug: it kept its
            // 0.5m default while the step-off point is 1.37m away in z, so even with the door test
            // gone a player standing where the climb puts them was outside the volume.
            escape.halfWidth = GridCellWidth;
            escape.halfDepth = GridCellWidth;
            // AND A CEILING ON IT. This volume ignores Y by design - a doorway is a doorway at any
            // height - which stopped being harmless when room3-0 was stacked over room3-2N: without
            // this, standing at the ladder's FOOT two storeys down armed the console up here.
            escape.halfHeight = RoomHeight / 2f;

            // WHERE THE CLIMB PUTS YOU DOWN, and there are TWO of them (2026-08-31).
            //
            // `LadderMount` cannot work this out for itself - the top of its shaft is a hole, and
            // which side of it is floor is a fact about THIS room. The mouth sits in the north-west
            // corner with barely 40cm between it and either wall, so of its four sides only the
            // SOUTH and the EAST are places a person can be put down at all.
            //
            // **TWO, because one was a shove.** A single point meant every step-off travelled to the
            // same lip however the player had come - so somebody who dipped into the mouth from the
            // south and climbed straight back out was carried across the opening to the other side,
            // which play reported as "walking at the ladder teleports me backwards". `LadderMount`
            // takes the nearer, so the step-off is the shortest move that reaches floor.
            //
            // Just clear of the rim rather than a whole cell out: the lip is where you step, and a
            // metre and three quarters is a stride and a half past it.
            float lip = GridCellWidth / 2f + 0.55f;

            GameObject dismounts = new GameObject("Dismounts");
            dismounts.transform.SetParent(t, false);

            GameObject dismountS = new GameObject("Dismount_South");
            dismountS.transform.SetParent(dismounts.transform, false);
            dismountS.transform.localPosition = new Vector3(hole.center.x, 0f, hole.center.y - lip);

            GameObject dismountE = new GameObject("Dismount_East");
            dismountE.transform.SetParent(dismounts.transform, false);
            dismountE.transform.localPosition = new Vector3(hole.center.x + lip, 0f, hole.center.y);

            // **AND THE SIGN THAT SAYS WHERE THE WAY OUT IS.** The floor that opens is in room3-2N,
            // a storey below and out of sight from here; without this the break ends with a player
            // in a red room with nothing to do. Authored at alpha 0 and raised by `FacilityFailure`,
            // because before the break there is nothing to point at.
            CanvasGroup wayDown = MakeWallFace(t, "WayDownSign",
                new Vector3(0f, 2.1f, RoomDepth / 2f - 0.06f), Quaternion.Euler(0f, 180f, 0f),
                f => MakeWallIcon(f, "WayDown", DownArrowIcon(), Vector2.zero, 1280f,
                                  new Color(0.85f, 0.10f, 0.10f, 0.95f)),
                worldWidth: 1.5f, withPlate: false, authoredHeight: 1600f);

            GameObject seqGO = new GameObject("BreakSequence");
            seqGO.transform.SetParent(t, false);
            FinalRoomSequence sequence = seqGO.AddComponent<FinalRoomSequence>();
            sequence.console = risen;
            sequence.slots = new[] { slot };
            slot.sequence = sequence;
            sequence.arrival = escape;
            // The boundary owns the hatch, as it has since cycle 3 existed: `CrossToNextCycle` wakes
            // the storey below and repoints the gas before opening the floor, and a player must not
            // be able to drop into a cycle that is still asleep.
            sequence.opensWayOutOnBreak = false;
            // No timer. `FacilityFailure` is what plays here and it runs to its own length; the ten
            // seconds only ever bounded the window before the ENDING's scrim, and this is not that.
            sequence.breakDuration = 0f;

            wayDownHint = wayDown;
            return (t, sequence);
        }

        // Carried out of `BuildBreakRoomThree` rather than returned, because it belongs to
        // `FacilityFailure` and that is assembled a scene apart. One field is cheaper than a fourth
        // member on a tuple two callers already thread through.
        private static CanvasGroup wayDownHint;

        // AN ARROW POINTING DOWN, THROUGH A FLOOR. Two marks: the arrow, and the line under it that
        // makes the arrow read as going THROUGH something rather than merely pointing at it.
        private static Sprite DownArrowIcon()
        {
            var icon = new IconCanvas(128);
            icon.Bar(new Vector2(0.5f, 0.66f), new Vector2(0.10f, 0.22f));
            icon.Shape(p =>
            {
                if (p.y < 0.26f || p.y > 0.50f) return false;
                float k = (p.y - 0.26f) / 0.24f;
                return Mathf.Abs(p.x - 0.5f) <= 0.30f * k;
            });
            icon.Bar(new Vector2(0.5f, 0.15f), new Vector2(0.34f, 0.045f));
            return SaveSprite(icon, "icon_way_down");
        }

        // NOTHING OF CYCLE 4 MAY BE INSIDE CYCLE 3, which is the one thing this arrangement could get
        // silently wrong. Room3-0 is up in the air and cycle 4 hangs under it, so for the first time
        // in this building two cycles overlap in ELEVATION - and whether that matters is entirely a
        // question about their footprints, which is exactly the kind of thing that is obvious in a
        // plan and wrong in a build.
        // Every MESH in a subtree, and nothing else. Zero-size entries are skipped as well as
        // particles: a renderer with no extent is a renderer that is not anywhere.
        private static Bounds SolidBounds(Transform root)
        {
            bool any = false;
            Bounds box = new Bounds(root.position, Vector3.zero);

            foreach (MeshRenderer r in root.GetComponentsInChildren<MeshRenderer>(true))
            {
                if (r.bounds.size == Vector3.zero) continue;
                if (!any) { box = r.bounds; any = true; }
                else box.Encapsulate(r.bounds);
            }

            return box;
        }

        private static void AssertCycleFourClear(Transform cycleThreeRoot, Transform cycleFourRoot)
        {
            if (cycleThreeRoot == null || cycleFourRoot == null) return;

            // **MEASURED OFF MESHES, NOT OFF `MeasuredBounds`.** That helper encapsulates every
            // Renderer, and a cycle has ParticleSystemRenderers in it - the four gas emitters - whose
            // bounds before they have ever played are a degenerate box at the WORLD ORIGIN. Both
            // cycles therefore measured as reaching from (0,0,0), which made them overlap each other
            // and everything else. The first run of this check reported exactly that.
            Bounds four = SolidBounds(cycleFourRoot);

            // **ROOM BY ROOM, NOT CYCLE BY CYCLE.** One box round the whole of cycle 3 spans from its
            // ground floor at -18.2 up to room3-0's ceiling at -1.8, and a box that tall overlaps
            // anything anywhere near it - the first run of this check reported a collision that was
            // nothing but that. What actually has to be true is that no ROOM of cycle 3 shares space
            // with cycle 4, and the rooms are what the player can be inside.
            int clashes = 0;
            float nearest = float.MaxValue;

            foreach (Transform room in cycleThreeRoot.GetComponentsInChildren<Transform>(true))
            {
                if (!room.name.StartsWith("Room3_") || room.name.EndsWith("_Root")) continue;
                if (room.name.EndsWith("_CeilingLights") || room.name.EndsWith("_Gas")) continue;

                Bounds box = SolidBounds(room);
                if (box.size == Vector3.zero) continue;

                if (box.Intersects(four))
                {
                    clashes++;
                    Debug.LogError($"[SceneBuilder] CYCLE 4 IS INSIDE {room.name}. That room spans "
                                 + $"{box.min} to {box.max} and cycle 4 spans {four.min} to "
                                 + $"{four.max}. Room3-0 is {DeckBSurfaceY:0.##}m up and cycle 4 hangs "
                                 + "a storey under it, so the two share an elevation band - they must "
                                 + "not share a footprint.");
                    continue;
                }

                // How close the nearest miss is, on the axis it misses by. Worth logging: the whole
                // arrangement rests on a gap that is one service void deep and one wall build-up
                // wide, and a number in the log is what notices it closing.
                Vector3 gap = Vector3.Max(box.min - four.max, four.min - box.max);
                nearest = Mathf.Min(nearest, Mathf.Max(gap.x, Mathf.Max(gap.y, gap.z)));
            }

            if (clashes == 0)
                Debug.Log($"[SceneBuilder] Cycle 4 clear of every room in cycle 3, nearest miss "
                        + $"{nearest:0.###}m. Cycle 4 floor {CycleFourFloorY:0.###} against cycle 3's "
                        + $"{CycleThreeFloorY:0.###} and room3-0's "
                        + $"{CycleThreeFloorY + RoomZeroY:0.###}.");
        }

        // ==================================================== ROOM3-2N'S GROUND FLOOR: THE BEDLAM CUBE
        //
        // Thirteen blocks, one of them standing on the floor inside a roped-off square to the right
        // of the door, and the other twelve spread across all THREE of the room's storeys: four on
        // the floor, four on deck A, four on deck B.
        //
        // **THE SCATTER IS WHAT TIES THE PUZZLE TO THE ROOM.** On one floor this is Room2West's chess
        // board again in a bigger room. Across three, every block above the ground costs a ride on a
        // `BeamLift` - which costs a past self holding a mirror on a receiver - so the light puzzle
        // and the cube puzzle are one errand instead of two rooms sharing a shell. The lift runs the
        // right way round for it: it is pulled DOWN by the beam and climbs when the beam goes, so the
        // player's hands are free the whole ride and a block can be carried in them.
        //
        // **THE PACKING IS SOLVED OFFLINE AND BAKED INTO THE MODEL.** `bedlam_cube.glb` here is not
        // the file that was downloaded - `Tools/split_bedlam_cube.py` takes that one, splits its
        // three colour-merged meshes into the thirteen pieces they actually hold, solves the exact
        // cover, and writes each piece out already rotated into its solved pose with that pose as
        // its NODE TRANSLATION. So this function computes nothing about the puzzle: it reads the
        // model's own arrangement, keeps it as thirteen anchors, and scatters the blocks.
        //
        // That is the same trick `BuildChessSet` uses - the home square is where the piece started -
        // and it is here for the same reason. A pose captured off the model cannot disagree with the
        // model, where a table of thirteen positions and rotations written in this file could.
        //
        // THE ANCHOR IS A SIBLING OF THE PIECE, carrying the local pose the piece had before it was
        // moved. `CarryableItem.InsertInto` parents at local identity, so an anchor built that way
        // reproduces the solved cube exactly - and it does so WITHOUT this file knowing which way
        // the glTF importer turned the model on the way in. Anything measured off the file's own
        // axes would have to know; a sibling does not.
        private const string BedlamModel = PlayDir + "/bedlam_cube.glb";
        private const string RopeModel = FurnitureDir + "/velvet_rope.glb";

        private const int BedlamPieceCount = 13;
        private const int BedlamCells = 4;
        // The block that starts on the floor, and it is chosen rather than picked. Block 2 is the
        // only one that is both on the cube's BOTTOM LAYER - so it lies flat on the mat and the cube
        // is seen to grow upward out of it, rather than hanging in the air waiting for a floor - and
        // among the best connected in the solution: eight of the other twelve share a face with it,
        // so the player has eight blocks that go on straight away instead of a hunt for the one that
        // does. `CheckBedlamSolution` proves the rest are reachable from it whatever is chosen here.
        private const int BedlamSeedPiece = 2;
        private const int BedlamScatterRngSeed = 20260829;

        // WHICH BLOCK FILLS WHICH CELL OF THE FINISHED CUBE, printed by the splitter and pasted
        // here. Sixty-four entries, cell `(x * 4 + y) * 4 + z` in the model's own grid.
        //
        // **THIS IS THE ONE THING IN THE PIPELINE COPIED BY HAND, so the build checks it** - see
        // `CheckBedlamSolution`. It is what `BedlamCube` derives "these two blocks touch" from, and
        // touching is the whole rule for whether a block may be clicked home yet; a table that did
        // not describe this model would be a cube with blocks that never go on, and no symptom
        // until somebody played it.
        //
        // Which AXIS is which does not matter and cannot be read off this - the importer is free to
        // permute them - because nothing here is ever compared against a world direction. Only the
        // adjacency it encodes is used.
        private static readonly int[] BedlamSolvedCells =
        {
             0,  0,  0,  1,   5,  0,  3,  3,  12, 12,  3,  8,  12,  8,  8,  8,
             5,  7,  0,  1,   5,  7,  2,  1,   5,  3,  3,  1,  12,  8,  4,  9,
             7,  7,  2,  2,   5, 10,  2,  1,  11,  6,  6,  9,   6,  6,  4,  9,
             7, 10, 10, 10,  11, 10,  2,  9,  11, 11,  4,  9,  11,  6,  4,  4,
        };

        // Where the cube stands, measured off the CORRIDOR MOUTH rather than off the room's middle:
        // "on your right as you come out" is a statement about the door, and the room is offset half
        // a cell from the corridor (see BuildCycleThreeShell) so its centre is the wrong thing to
        // hang it on. Far enough in that the rope clears the south wall, near enough that it is the
        // first thing on that side.
        // WHERE A PUT-DOWN LANDS, before the object's own half-width is added. One number, read by
        // `PlayerHand` and by every ghost - see the note where it is assigned.
        private const float DropAheadDistance = 0.55f;

        private const float BedlamStandRight = 3.8f;
        private const float BedlamStandIn = 3.3f;

        // What the splitter was run at - the finished cube is four of these across, so 1.6m on the
        // floor. **DOUBLED 2026-08-29, by request**, from the 0.2 it was built at. It scales nothing
        // here (the model already carries metres); it is the number the splitter is re-run with, and
        // it is stated so `CheckBedlamSolution` can measure the cell map's box in the same units the
        // geometry is in.
        private const float BedlamCellSize = 0.4f;

        // The mat the cube is built on. **~~A waist-high plinth~~ GONE 2026-08-29, by request: the
        // first block lies on the FLOOR.** What the plinth was actually doing was two things, and
        // only one of them was height - the other was being a dark inset that says something is MEANT
        // to stand here, and that half is kept as a mat because the flash that answers a refused
        // click has to live on something.
        //
        // Sized to the finished cube plus a hand's width, and only just proud of the floor: at 2cm it
        // would be a step, and coplanar with the slab it would z-fight (CLAUDE.md §3).
        private const float BedlamMatSize = 2.2f;
        private const float BedlamMatThickness = 0.012f;
        private const float BedlamMatLift = 0.004f;

        // THE ROPE ROUND IT, AND IT IS THE MODEL'S OWN ARRANGEMENT. `velvet_rope.glb` is not a single
        // stanchion - it is nine posts and eight spans already laid out as a museum enclosure with
        // one side left open, which is exactly the thing that was asked for. Placed once and sized,
        // rather than rebuilt post by post out of its parts: a rope run assembled in this file would
        // be this file deciding where the rings sit on the posts, which is the artist's decision and
        // is already correct in the file.
        //
        // **NO COLLIDER, deliberately.** A velvet rope that stopped a `CharacterController` would be
        // a 5m box round the one thing in the room the player has to walk up to twelve times, and the
        // ways in and out of it would depend on a gap two ropes happen to leave. It is a mark on the
        // floor plan, and the cube inside it is the solid thing.
        private const float BedlamRopeSpan = 4.6f;
        // **HOW IT ARRIVES, MEASURED RATHER THAN DERIVED.** `velvet_rope.glb` comes in LYING DOWN -
        // its posts run along Unity's +Z with the ball ends at the far one - and no amount of reading
        // its node matrices predicted that: the two root nodes compose to a plain 1:100 scale, so on
        // paper it should stand up on its own. It does not. Working out why is not worth a build; the
        // built scene was measured instead, which is the rule this project already keeps for
        // `MakeChessPiece`'s tilt and for every other imported pose.
        //
        // -90 about X stands it up. 180 about Y then turns the OPENING - the one gap in the ring,
        // between the posts the model leaves unroped - to face the corridor, so the way in is on the
        // side the player arrives from. Unity applies Z, then X, then Y, so the yaw lands after the
        // pitch, which is the order these two want.
        private const float BedlamRopePitch = -90f;
        private const float BedlamRopeYaw = 180f;

        private static BedlamCube BuildBedlamCube(Transform room, float roomWidth, float roomDepth,
                                                  float mouthX, Material propMat)
        {
            GameObject source = AssetDatabase.LoadAssetAtPath<GameObject>(BedlamModel);
            if (source == null)
            {
                Debug.LogError($"[SceneBuilder] no model at {BedlamModel} - room3-2N has no puzzle. "
                             + "Run Tools/split_bedlam_cube.py over the downloaded bedlam_cube.glb.");
                return null;
            }

            Vector3 standAt = new Vector3(mouthX + BedlamStandRight, 0f,
                                          -roomDepth / 2f + BedlamStandIn);

            // THE STAND IS THE CUBE'S OWN TRANSFORM, and that is not tidiness. `BedlamPlacer` asks
            // `PlayerLookup.InView(cube.aim, cube.transform)`, which forgives every collider under
            // the named owner - so the mat and the cube's own solid box have to be INSIDE this
            // subtree or they occlude the very point the prompt hangs on. Everything the cube is made
            // of hangs off this one transform for that reason.
            GameObject stand = new GameObject("BedlamStand");
            stand.transform.SetParent(room, false);
            stand.transform.localPosition = standAt;

            BedlamCube cube = stand.AddComponent<BedlamCube>();
            cube.solvedCells = BedlamSolvedCells;
            cube.cellsPerSide = BedlamCells;
            cube.seedPiece = BedlamSeedPiece;

            // The dark inset the cube is built on, and the thing that answers a click. A pale block
            // on a pale floor is one surface; the mat is what says something is MEANT to be here, and
            // flashing it is how a refused block is told apart from a control that did nothing.
            GameObject mat = Prim(PrimitiveType.Cube, "Mat", stand.transform,
                new Vector3(0f, BedlamMatLift + BedlamMatThickness / 2f, 0f),
                new Vector3(BedlamMatSize, BedlamMatThickness, BedlamMatSize),
                MakeColorMaterial("BedlamMat", new Color(0.14f, 0.14f, 0.16f)),
                removeCollider: true);
            cube.statusRenderer = mat.GetComponent<Renderer>();

            // THE MODEL, AT ITS OWN SIZE. `PlaceModelLocal` would rescale it to a longest side, and
            // there is nothing to rescale: the splitter wrote it out in metres, four cells across,
            // so a scale of one is the size the puzzle was cut at.
            GameObject instance = (GameObject)PrefabUtility.InstantiatePrefab(source, stand.transform);
            instance.name = "Cube";
            instance.transform.localPosition = Vector3.zero;
            instance.transform.localRotation = Quaternion.identity;
            instance.transform.localScale = Vector3.one;
            // UNPACKED, like the chess set and for the same reason: Unity lets components be added
            // to a prefab instance but not the hierarchy restructured, and every block here is about
            // to be reparented out across three storeys. The .glb stays the source of truth for the
            // geometry - the scene is build output, so nothing is lost by flattening it.
            PrefabUtility.UnpackPrefabInstance(instance, PrefabUnpackMode.Completely,
                                               InteractionMode.AutomatedAction);

            var pieceNodes = new Transform[BedlamPieceCount];
            foreach (Transform t in instance.GetComponentsInChildren<Transform>(true))
            {
                if (!t.name.StartsWith("Piece_")) continue;
                if (!int.TryParse(t.name.Substring("Piece_".Length), out int index)) continue;
                if (index >= 0 && index < BedlamPieceCount) pieceNodes[index] = t;
            }

            // Measured while the model is still assembled, which is the only moment it IS a cube.
            Bounds assembled = MeasuredBounds(instance);
            // STOOD ON THE MAT, i.e. its bottom face on the floor rather than its centre at a height.
            // The seed block is on the cube's bottom layer, so this is also what puts THAT block flat
            // on the ground, which is the whole of the request.
            instance.transform.localPosition +=
                new Vector3(0f, BedlamMatLift + BedlamMatThickness + assembled.size.y / 2f, 0f)
                - stand.transform.InverseTransformPoint(assembled.center);
            assembled = MeasuredBounds(instance);

            // WHERE THE CLICK IS AIMED AND WHERE THE DISC HANGS: the middle of the finished cube.
            // Positioned from the re-measured bounds rather than left at the model's local origin,
            // because the importer is free to have put a node between the two.
            GameObject aim = new GameObject("Aim");
            aim.transform.SetParent(instance.transform, false);
            aim.transform.position = assembled.center;
            cube.aim = aim.transform;

            // THE ASSEMBLED CUBE IS SOLID, from the first block rather than the last. One box over
            // the whole 4x4x4 volume, not one collider per block: the blocks come and go and their
            // colliders would come and go with them, and a shape that changes under the player is a
            // shape they can be standing inside when it appears. The cost is honest and small - the
            // empty part of a half-built cube is solid too - and the alternative is a metre and a
            // half of geometry the player walks straight through.
            BoxCollider solid = aim.AddComponent<BoxCollider>();
            solid.size = assembled.size;

            BuildBedlamRope(stand.transform);

            var blocks = new CarryableItem[BedlamPieceCount];
            var homes = new Transform[BedlamPieceCount];
            var boxes = new Bounds[BedlamPieceCount];

            Sprite icon = BedlamBlockIcon();
            System.Random rng = new System.Random(BedlamScatterRngSeed);
            BedlamShelf[] shelves = BedlamShelves(roomWidth, roomDepth, mouthX, standAt);
            var spots = new System.Collections.Generic.List<Vector3>();
            // Every spot on every shelf. `spots` is cleared between storeys - it exists to space
            // blocks apart from their own neighbours - and the check at the end of the loop is about
            // one fixture, so it needs the ones that were thrown away.
            var landed = new System.Collections.Generic.List<Vector3>();
            int shelf = 0, placedOnShelf = 0;

            for (int i = 0; i < BedlamPieceCount; i++)
            {
                Transform piece = pieceNodes[i];
                if (piece == null)
                {
                    Debug.LogError($"[SceneBuilder] {BedlamModel}: no node called Piece_{i:00} - the "
                                 + "split has changed. Re-run Tools/split_bedlam_cube.py.");
                    return null;
                }

                // CAPTURED BEFORE ANYTHING MOVES. This pose is the solved cube, and it is only true
                // of the model as the splitter left it.
                Vector3 homeLocalPosition = piece.localPosition;
                Quaternion homeLocalRotation = piece.localRotation;
                boxes[i] = MeasuredBounds(piece.gameObject);

                GameObject anchor = new GameObject($"Home_{i:00}");
                anchor.transform.SetParent(piece.parent, false);
                anchor.transform.localPosition = homeLocalPosition;
                anchor.transform.localRotation = homeLocalRotation;
                anchor.transform.localScale = Vector3.one;
                homes[i] = anchor.transform;

                blocks[i] = MakeBedlamBlock(piece, boxes[i], i, icon);

                // **THE SEED IS SCATTERED LIKE THE REST, and it has to be.** It was left standing
                // at its home pose for a while, so that the saved scene showed a mat with a block on
                // it - and `CheckHintAnchors` reported it: a block at its home pose has its prompt
                // anchor buried inside the cube's own solid box, which is a collider `PlayerLookup`
                // would not forgive it. Inert, because the seed is seated on the first frame and a
                // seated block has no trigger - and a warning that is inert is still a warning the
                // next reader has to work out, which is what CLAUDE.md §3 says about permanent
                // console noise.
                //
                // Nothing about play changes: `BedlamCube.Start` seats it before the first frame is
                // drawn, and every iteration's reset does it again. What changes is that the scene on
                // disk now shows the puzzle unsolved, which is what it is.

                // ONE SHELF AT A TIME, in order, so the four counts are exact rather than emergent.
                while (shelf < shelves.Length - 1 && placedOnShelf >= shelves[shelf].blocks)
                {
                    shelf++;
                    placedOnShelf = 0;
                    spots.Clear();     // a different storey - nothing up here can crowd anything down there
                }
                placedOnShelf++;

                Vector3 spot = BedlamScatterSpot(rng, shelves[shelf], spots);
                spots.Add(spot);
                landed.Add(spot);
                // The pivot is the block's own centre, so it has to be lifted by half its height to
                // stand on the surface rather than half through it - the same number `floorY`
                // carries, added to the deck this shelf is.
                piece.position = room.TransformPoint(spot) + Vector3.up * (boxes[i].size.y / 2f);
                // Turned where it fell. Yaw only: a block tipped onto a corner would have to be read
                // as a different shape from the one it becomes on the cube, and this puzzle is hard
                // enough without that. Yaw also leaves its height alone, which is what keeps the
                // lift above true.
                piece.rotation = Quaternion.Euler(0f, (float)rng.NextDouble() * 360f, 0f) * piece.rotation;
            }

            // **AND NOTHING LANDED ON THE LADDER'S MARK.** The exclusion above is what keeps that
            // true; this is what says so if it ever stops being. A block on the mark does not look
            // like a bug - it looks like one of twelve blocks lying about a room full of blocks -
            // and what it actually does is make the ladder impossible to install, silently, because
            // `LadderPlacer`'s view ray runs into it. Play spent a session on that. Cheap to check
            // and it names the cause rather than the symptom.
            Rect mark = Grow(LadderShaftHole(LadderFootX, LadderShaftXZ.y), 3f * BedlamCellSize / 2f);
            foreach (Vector3 at in landed)
                if (mark.Contains(new Vector2(at.x, at.z)))
                    Debug.LogError($"[SceneBuilder] a Bedlam block landed at ({at.x:0.##}, {at.z:0.##}), "
                                 + "on the ladder's mark. It will occlude the mount and the ladder "
                                 + "cannot be installed. Fix the deck B keepClear in BedlamShelves.");

            // **THE OBJECT THE PUZZLE BECOMES.** A second copy of the model with nothing moved - so
            // every node sits at its solved translation and the thing is a finished cube - built
            // small, hidden, and revealed at the end of the shrink. See `BedlamCube.Shrink` for why
            // the assembly itself cannot be the carryable.
            cube.assembled = instance.transform;
            cube.held = BuildHeldCube(stand.transform, source, assembled, icon);
            cube.heldScale = BedlamHeldScale;

            cube.pieces = blocks;
            cube.homeAnchors = homes;
            cube.audioSource = MakeSource(stand.transform, "SeatAudio", 1f, 0.9f);
            cube.insertClip = LoadClip(SfxDir, "sfx_item_pickup");

            CheckBedlamSolution(cube, boxes, assembled, shelves);
            return cube;
        }

        // THE ROPE, PLACED ONCE. Centred on the cube and sized by its longest side, which is the run
        // end to end; everything else about it - post height, spacing, where the rings sit, which
        // side is left open - comes with the model.
        private static void BuildBedlamRope(Transform stand)
        {
            (GameObject rope, Bounds bounds) = PlaceModelLocal(RopeModel, stand, "Rope",
                Vector3.zero, Quaternion.Euler(BedlamRopePitch, BedlamRopeYaw, 0f), BedlamRopeSpan);
            if (rope == null) return;

            // Sat on the floor rather than centred on the cube's middle. `PlaceModelLocal` centres
            // what it places, which is right for a thing hung on a wall and wrong for a thing
            // standing on one - the posts would be buried to the waist.
            rope.transform.position += Vector3.up * (stand.position.y - bounds.min.y);

            // NOT SOLID. See the note on `BedlamRopeSpan`: the rope is a mark on the floor plan and
            // the cube inside it is the thing you cannot walk through. Colliders come off rather than
            // being left off, because a `.glb` import decides for itself whether it has any.
            foreach (Collider c in rope.GetComponentsInChildren<Collider>(true))
                Object.DestroyImmediate(c);

            // The posts' HEIGHT is the number to read here, and it is the one that says the model
            // came in the right way up: it should be about a metre. Anything near the enclosure's
            // own width means the pitch above is wrong again and the whole thing is lying on the
            // floor - which is exactly how this arrived the first time.
            Debug.Log($"[SceneBuilder] Bedlam rope: {bounds.size.x:0.##} x {bounds.size.z:0.##}m "
                    + $"enclosure, posts {bounds.size.y:0.##}m tall, centred on the cube.");
        }

        // ONE SURFACE BLOCKS ARE THROWN ONTO: a storey, where a block may land on it, and how many
        // land there. Written as data rather than as three code paths because the only thing that
        // differs between the ground, deck A and deck B is a height and a set of rectangles.
        private struct BedlamShelf
        {
            public string name;
            public float surfaceY;
            // Where a block's CENTRE may be, in the room's own XZ. Inset from the real edge by half a
            // block, so a 1.2m block thrown at the lip of a deck does not hang over it.
            public Rect[] spots;
            public Rect[] keepClear;
            public int blocks;
        }

        // Deck A is an L down the west wall and along the north; deck B is a rectangle over the
        // north-west quarter with a square cut out of it. Both are `PlanMezzanines`' shapes, inset -
        // stated again here rather than derived from that function, because what it returns is where
        // the SLAB is and this is where a metre of block may stand on it, which is not the same
        // rectangle and would need the inset applying to each piece anyway.
        private static BedlamShelf[] BedlamShelves(float roomWidth, float roomDepth, float mouthX,
                                                   Vector3 standAt)
        {
            float halfX = roomWidth / 2f, halfZ = roomDepth / 2f;
            // Half a block's longest footprint. Every piece is at most three cells across.
            float inset = 3f * BedlamCellSize / 2f + 0.15f;

            return new[]
            {
                // THE GROUND FLOOR, east of the corridor mouth and along the south wall. Everything
                // else down here - both lifts, all five columns, the beam's lane - is west or north.
                new BedlamShelf
                {
                    name = "ground floor",
                    surfaceY = 0f,
                    spots = new[]
                    {
                        Rect.MinMaxRect(mouthX + 1.6f, -halfZ + 1.3f, halfX - inset, -halfZ + 8.5f),
                    },
                    // The roped-off square. A block dropped inside the rope is one the player has to
                    // step over to reach the thing they are aiming at, and it would read as part of
                    // the exhibit rather than as something to fetch.
                    keepClear = new[]
                    {
                        Rect.MinMaxRect(standAt.x - 2.7f, standAt.z - 2.2f,
                                        standAt.x + 2.7f, standAt.z + 2.2f),
                    },
                    // FIVE, not four: the seed is thrown down here with them (see the note in
                    // `BuildBedlamCube`), and it is on the ground because that is where it ends up -
                    // `BedlamCube` lifts it onto the mat before the first frame.
                    blocks = 5,
                },

                // DECK A, one storey up: the west strip and the north strip of its L.
                new BedlamShelf
                {
                    name = "deck A",
                    surfaceY = DeckARows * GridCellHeight,
                    spots = new[]
                    {
                        Rect.MinMaxRect(-halfX + inset, -6.4f,
                                        -halfX + 2f * GridCellWidth - inset, 6.4f),
                        Rect.MinMaxRect(-halfX + inset, 7f + inset, halfX - inset, 10.5f - inset),
                    },
                    keepClear = new[]
                    {
                        // The hole deck A carries for lift B's column, and the lift panel that rests
                        // in it - see PlanMezzanines.
                        Rect.MinMaxRect(DeckBLiftX - 1.4f, DeckBVoidMaxZ - DeckBLiftPad / 2f - 1.4f,
                                        DeckBLiftX + 1.4f, DeckBVoidMaxZ - DeckBLiftPad / 2f + 1.4f),
                        // Column B1, which stands ON deck A and carries on up to deck B.
                        Rect.MinMaxRect(-3.4f, 8.6f, -1.1f, 11f),
                        // Where lift A arrives, so the ride does not end with a block underfoot.
                        Rect.MinMaxRect(DeckALiftX - 1.8f, DeckALiftZ - 1.8f,
                                        DeckALiftX + 1.8f, DeckALiftZ + 1.8f),
                    },
                    blocks = 4,
                },

                // DECK B, two storeys up: the rectangle minus the square hole you look down through.
                new BedlamShelf
                {
                    name = "deck B",
                    surfaceY = DeckBRows * GridCellHeight,
                    spots = new[]
                    {
                        Rect.MinMaxRect(-halfX + inset, 3.62f + inset,
                                        -GridCellWidth - inset, 10.5f - inset),
                    },
                    keepClear = new[]
                    {
                        // The void, and lift B's panel resting inside it. One rectangle: the panel is
                        // in the hole, so the hole plus a block's half-width covers both.
                        Rect.MinMaxRect(-3.5f * GridCellWidth - inset, 5.25f - inset,
                                        -2.5f * GridCellWidth + inset, 8.75f + inset),
                        // **THE LADDER'S MARK, AND THE SHAFT ABOVE IT.** Deck B's strip runs straight
                        // through the one spot on it that has a job, and nothing said so - so a block
                        // could be thrown onto the mark. That is not merely untidy: `LadderPlacer`
                        // ends in `PlayerLookup.InView`, whose ray to the mount ran along the deck
                        // and straight into the block, so **the ladder could not be installed at
                        // all** and the prompt never appeared to say why. One rectangle, both
                        // symptoms. (The prompt anchor has come off the deck as well - see
                        // `LadderMount.hintAnchor` - because the build is not the only thing that can
                        // leave an object standing here.)
                        Grow(LadderShaftHole(LadderShaftXZ.x, LadderShaftXZ.y), inset),
                        // **AND THE MARK, WHICH IS NO LONGER UNDER THE MOUTH.** The ladder leans, so
                        // its foot stands `LadderRun` out from the shaft - two separate squares to
                        // keep clear rather than one, and the foot is the one the prompt is on.
                        Grow(LadderShaftHole(LadderFootX, LadderShaftXZ.y), inset),
                    },
                    blocks = 4,
                },
            };
        }

        // A rectangle with a margin on every side. Written out because `Rect` has no such thing and
        // an exclusion always wants one: what has to be kept clear is the FIXTURE plus half a block,
        // or a block placed just outside it still overhangs.
        private static Rect Grow(Rect r, float by) =>
            Rect.MinMaxRect(r.xMin - by, r.yMin - by, r.xMax + by, r.yMax + by);

        // WHERE ONE BLOCK IS THROWN on a given shelf. Best of thirty rather than reject-and-retry: a
        // retry loop either has to be allowed to fail - which puts two blocks inside each other - or
        // to run forever when the area is too small for the spacing asked of it. Taking the roomiest
        // of a fixed number of throws degrades instead, so crowding a deck simply tightens the spots.
        private static Vector3 BedlamScatterSpot(System.Random rng, BedlamShelf shelf,
                                                 System.Collections.Generic.List<Vector3> taken)
        {
            Vector3 best = Vector3.zero;
            float bestClearance = float.MinValue;

            // Weighted by AREA, so a shelf made of a long strip and a short one does not put half its
            // blocks on the short one. Computed per call rather than cached: three shelves, twelve
            // blocks, thirty throws each is nothing.
            float total = 0f;
            foreach (Rect r in shelf.spots) total += Mathf.Max(0f, r.width * r.height);

            for (int attempt = 0; attempt < 30; attempt++)
            {
                Rect area = shelf.spots[0];
                float pick = (float)rng.NextDouble() * total;
                foreach (Rect r in shelf.spots)
                {
                    float a = Mathf.Max(0f, r.width * r.height);
                    if (pick <= a) { area = r; break; }
                    pick -= a;
                }

                Vector2 flat = new Vector2(Mathf.Lerp(area.xMin, area.xMax, (float)rng.NextDouble()),
                                           Mathf.Lerp(area.yMin, area.yMax, (float)rng.NextDouble()));
                if (InAny(shelf.keepClear, flat)) continue;

                float clearance = float.MaxValue;
                foreach (Vector3 other in taken)
                    clearance = Mathf.Min(clearance, Vector2.Distance(flat, new Vector2(other.x, other.z)));

                if (clearance <= bestClearance) continue;
                bestClearance = clearance;
                best = new Vector3(flat.x, shelf.surfaceY, flat.y);
            }

            // Every throw landed in a keep-clear rectangle, which is a shelf whose spots and
            // exclusions have been written to cancel each other out. Reported rather than silently
            // stacking a block at the room's origin.
            if (bestClearance == float.MinValue)
                Debug.LogError($"[SceneBuilder] no clear spot on {shelf.name} for a Bedlam block - "
                             + "its keep-clear rectangles cover its whole area.");

            return best;
        }

        private static bool InAny(Rect[] rects, Vector2 point)
        {
            if (rects == null) return false;
            foreach (Rect r in rects) if (r.Contains(point)) return true;
            return false;
        }

        // What the finished cube shrinks INTO. A quarter of its own size, which is 0.4m across - the
        // scale of every other escape object in the game (cycle 1's three are 0.30) and small enough
        // that a console recess can be cut for it.
        private const float BedlamHeldScale = 0.25f;

        private static CarryableItem BuildHeldCube(Transform parent, GameObject source,
                                                   Bounds assembled, Sprite icon)
        {
            GameObject instance = (GameObject)PrefabUtility.InstantiatePrefab(source, parent);
            instance.name = "HeldCube";
            instance.transform.localRotation = Quaternion.identity;
            instance.transform.localScale = Vector3.one * BedlamHeldScale;
            PrefabUtility.UnpackPrefabInstance(instance, PrefabUnpackMode.Completely,
                                               InteractionMode.AutomatedAction);

            // Centred on its own pivot, so the reveal can put it exactly where the assembly stood.
            Bounds box = MeasuredBounds(instance);
            instance.transform.position += instance.transform.position - box.center;
            box = MeasuredBounds(instance);

            BoxCollider trigger = instance.AddComponent<BoxCollider>();
            trigger.isTrigger = true;
            trigger.center = instance.transform.InverseTransformPoint(box.center);
            trigger.size = Abs(instance.transform.InverseTransformVector(Vector3.one * 1.4f));

            CarryableItem item = instance.AddComponent<CarryableItem>();
            item.itemId = CycleThreeKeyItemId;
            item.displayName = "CUBE";
            item.icon = icon;
            // **NOT THE CYCLE'S GREEN** (2026-08-31, by request). Every other escape object in the
            // game is one colour and its HUD tint is that colour; this one is three, and tinting a
            // white pictogram green named a colour the object does not have anywhere on it. Left
            // untinted, the icon reads as the drawing it is.
            item.iconTint = Color.white;
            item.floorY = box.size.y / 2f;
            item.handLocalPosition = HandPoseFor(box.size.x);
            // Off-axis on two axes, so what is in the hand reads as a CUBE - square-on it is a
            // square, which is the shape of the recess and not of the object.
            item.handLocalEuler = new Vector3(-22f, 26f, 0f);
            item.handLocalScale = instance.transform.lossyScale;
            item.audioSource = MakeSource(instance.transform, "PickupAudio", 1f, 0.85f);
            item.pickupClip = LoadClip(SfxDir, "sfx_item_pickup");

            Debug.Log($"[SceneBuilder] Bedlam held cube: {box.size.x:0.##}m against the assembly's "
                    + $"{assembled.size.x:0.##}m ({BedlamHeldScale:0.##} of it).");
            return item;
        }

        private static CarryableItem MakeBedlamBlock(Transform piece, Bounds bounds, int index,
                                                     Sprite icon)
        {
            // THE BLOCK PLUS AN ARM'S REACH, so it is taken from standing beside it rather than
            // from inside it. Triggers overlapping is fine and expected: `PlayerLookup.AimedAnchor`
            // gives the press to whichever one the player is actually looking at (CLAUDE.md §1.2).
            //
            // ABS on the size, and it is not paranoia: `InverseTransformVector` divides through the
            // transform, so under a parent the importer chose to mirror this comes back negative and
            // the trigger is built inside out. The chess set found that the hard way.
            BoxCollider trigger = piece.gameObject.AddComponent<BoxCollider>();
            trigger.isTrigger = true;
            trigger.center = piece.InverseTransformPoint(bounds.center);
            trigger.size = Abs(piece.InverseTransformVector(bounds.size)) + Vector3.one * 0.7f;

            // SOLID, ON A CHILD, since the blocks doubled in size. At 0.6m across they were scenery
            // to walk over like a chess piece; at 1.2m a block is a thing you go round, and one you
            // can walk through in a room built to be climbed reads as a hole in the floor plan.
            //
            // The child is load-bearing rather than tidiness: `CarryableItem` takes
            // `GetComponent<Collider>()` as its reach trigger, so a solid box on this same object
            // would be a coin toss over which of the two becomes the reach - the trap
            // `BuildKeyPlinth` documents. Handed over as `blocker`, so every path that puts the block
            // in a hand switches it off.
            GameObject solid = new GameObject("Blocker");
            solid.transform.SetParent(piece, false);
            BoxCollider block = solid.AddComponent<BoxCollider>();
            block.center = piece.InverseTransformPoint(bounds.center);
            block.size = Abs(piece.InverseTransformVector(bounds.size));

            CarryableItem item = piece.gameObject.AddComponent<CarryableItem>();
            item.blocker = block;
            item.itemId = $"Bedlam_{index:00}";
            item.displayName = "BLOCK";
            item.icon = icon;
            // Its own half-height. The mesh is centred on its pivot - the splitter put it there so
            // that a node's translation could be the whole of where the block goes - so this is what
            // stands a dropped block ON the floor rather than half through it. It is a height above
            // whatever `FallingItem.SurfaceUnder` finds, which is what lets a block be put down on a
            // deck five metres up rather than sinking to the one floor the cycle was told about.
            item.floorY = bounds.size.y / 2f;
            item.handLocalPosition = HandPoseFor(Mathf.Max(bounds.size.x, bounds.size.z));
            // Tipped toward the eye and turned off square. A polycube seen face-on is a rectangle,
            // and which rectangle it is is the only thing the player has to go on.
            item.handLocalEuler = new Vector3(-18f, 24f, 0f);
            item.ghostLocalEuler = Vector3.zero;
            // ITS OWN SIZE, which is what "held at true size" means with an unscaled hand anchor.
            // Written even where the parent is unscaled, because the SIGN is what keeps a mirrored
            // import mirrored and the importer is free to have made one.
            item.handLocalScale = piece.lossyScale;
            return item;
        }

        // THE ONE HAND-COPIED THING IN THIS PUZZLE, CHECKED. `BedlamSolvedCells` is printed by the
        // splitter and pasted into this file, and everything about which blocks may join which hangs
        // off it. These are every property of it that can be tested without knowing how the importer
        // turned the model:
        //
        //   - it describes 64 cells and names only blocks that exist,
        //   - the counts are the Bedlam Cube's own - twelve blocks of five cells and one of four,
        //   - the graph it makes is CONNECTED from the seed, or some block could never be clicked
        //     home no matter what order they were carried in, and
        //   - each block's cells span the same box its geometry does. That last one is what ties the
        //     table to THIS model rather than to any thirteen-piece packing, and it is compared as a
        //     multiset of extents so it holds whichever way the importer permuted the axes.
        private static void CheckBedlamSolution(BedlamCube cube, Bounds[] boxes, Bounds assembled,
                                                BedlamShelf[] shelves)
        {
            const int n = BedlamCells;

            foreach (int piece in BedlamSolvedCells)
                if (piece < 0 || piece >= BedlamPieceCount)
                {
                    Debug.LogError($"[SceneBuilder] BedlamSolvedCells names block {piece}, which does "
                                 + "not exist. Re-paste it from Tools/split_bedlam_cube.py.");
                    return;
                }

            if (BedlamSolvedCells.Length != n * n * n)
            {
                Debug.LogError($"[SceneBuilder] BedlamSolvedCells has {BedlamSolvedCells.Length} cells "
                             + $"where {n * n * n} are wanted.");
                return;
            }

            var counts = new int[BedlamPieceCount];
            var lo = new Vector3Int[BedlamPieceCount];
            var hi = new Vector3Int[BedlamPieceCount];
            for (int i = 0; i < BedlamPieceCount; i++)
            {
                lo[i] = new Vector3Int(n, n, n);
                hi[i] = new Vector3Int(-1, -1, -1);
            }

            for (int x = 0; x < n; x++)
                for (int y = 0; y < n; y++)
                    for (int z = 0; z < n; z++)
                    {
                        int piece = BedlamSolvedCells[(x * n + y) * n + z];
                        counts[piece]++;
                        lo[piece] = Vector3Int.Min(lo[piece], new Vector3Int(x, y, z));
                        hi[piece] = Vector3Int.Max(hi[piece], new Vector3Int(x, y, z));
                    }

            int fours = 0, wrong = 0;
            for (int i = 0; i < BedlamPieceCount; i++)
            {
                if (counts[i] == 4) fours++;
                else if (counts[i] != 5) wrong++;

                // The cells' box against the geometry's, as sorted extents. The importer may name
                // the axes what it likes; it cannot change how long the block is. This is also what
                // catches the cell size and the model's scale drifting apart - re-run the splitter
                // with a different `--cell` and forget to move `BedlamCellSize`, and every one of
                // the thirteen fails at once.
                Vector3 fromCells = (Vector3)(hi[i] - lo[i] + Vector3Int.one) * BedlamCellSize;
                float[] a = { fromCells.x, fromCells.y, fromCells.z };
                float[] b = { boxes[i].size.x, boxes[i].size.y, boxes[i].size.z };
                System.Array.Sort(a);
                System.Array.Sort(b);
                for (int k = 0; k < 3; k++)
                    if (Mathf.Abs(a[k] - b[k]) > 0.02f)
                    {
                        Debug.LogError($"[SceneBuilder] Bedlam block {i} fills a "
                                     + $"{a[0]:0.##}x{a[1]:0.##}x{a[2]:0.##} box in BedlamSolvedCells "
                                     + $"and measures {b[0]:0.##}x{b[1]:0.##}x{b[2]:0.##}. The table "
                                     + "does not describe this model at this cell size.");
                        break;
                    }
            }

            if (fours != 1 || wrong != 0)
                Debug.LogError($"[SceneBuilder] BedlamSolvedCells has {fours} blocks of four cells and "
                             + $"{wrong} of neither four nor five - a Bedlam Cube is twelve fives and "
                             + "one four.");

            // CONNECTED FROM THE SEED, walked the way `BedlamCube.CanSeat` walks it. A packing whose
            // graph came apart leaves blocks that are refused forever, and the symptom in play is a
            // click that does nothing on a block the player has no way of seeing is stranded.
            var reached = new System.Collections.Generic.HashSet<int> { BedlamSeedPiece };
            var queue = new System.Collections.Generic.Queue<int>();
            queue.Enqueue(BedlamSeedPiece);
            while (queue.Count > 0)
            {
                int here = queue.Dequeue();
                for (int x = 0; x < n; x++)
                    for (int y = 0; y < n; y++)
                        for (int z = 0; z < n; z++)
                        {
                            if (BedlamSolvedCells[(x * n + y) * n + z] != here) continue;
                            foreach (Vector3Int step in BedlamSteps)
                            {
                                int nx = x + step.x, ny = y + step.y, nz = z + step.z;
                                if (nx < 0 || ny < 0 || nz < 0 || nx >= n || ny >= n || nz >= n) continue;
                                if (reached.Add(BedlamSolvedCells[(nx * n + ny) * n + nz]))
                                    queue.Enqueue(BedlamSolvedCells[(nx * n + ny) * n + nz]);
                            }
                        }
            }

            if (reached.Count != BedlamPieceCount)
                Debug.LogError($"[SceneBuilder] only {reached.Count} of {BedlamPieceCount} Bedlam blocks "
                             + $"can be reached from the seed (block {BedlamSeedPiece}) - the rest could "
                             + "never be put on.");

            string spread = string.Empty;
            foreach (BedlamShelf s in shelves) spread += $"{s.blocks} on {s.name}, ";

            Debug.Log($"[SceneBuilder] Bedlam cube at {cube.transform.position}: {BedlamPieceCount} "
                    + $"blocks, assembled {assembled.size.x:0.##}x{assembled.size.y:0.##}"
                    + $"x{assembled.size.z:0.##}m standing on the floor, seed block {BedlamSeedPiece} "
                    + $"lifted onto the mat at run time, {reached.Count} reachable from it, {spread}"
                    + "thirteen in all.");
        }

        private static readonly Vector3Int[] BedlamSteps =
        {
            new Vector3Int(1, 0, 0), new Vector3Int(-1, 0, 0),
            new Vector3Int(0, 1, 0), new Vector3Int(0, -1, 0),
            new Vector3Int(0, 0, 1), new Vector3Int(0, 0, -1),
        };

        // AN L OF THREE SQUARES, which is the smallest drawing that reads as one of these blocks
        // rather than as a box. Deliberately flat and orthographic: the readout is 24 pixels of
        // silhouette, and an isometric cube at that size is a hexagon.
        private static Sprite BedlamBlockIcon()
        {
            var icon = new IconCanvas(128);
            const float half = 0.15f;
            icon.Bar(new Vector2(0.34f, 0.34f), new Vector2(half, half));
            icon.Bar(new Vector2(0.34f, 0.66f), new Vector2(half, half));
            icon.Bar(new Vector2(0.66f, 0.66f), new Vector2(half, half));
            return SaveSprite(icon, "icon_bedlam_block");
        }

        // **~~The four spots under the decks~~ GONE 2026-08-28, by request.** They were four
        // fixtures at a flat intensity of 6, on the reasoning that "a deck is a ceiling for whatever
        // is under it". True, and they were adding to the same complaint the 3x3 overhead grid was:
        // the upper storeys were too bright. A deck's underside reading as shade is what tells you
        // there is a floor over your head, and this room's problem was never too little light.
        //
        // ==================================================== CYCLE 3'S BEAM, AND THE MIRRORS THAT BEND IT
        //
        // A laser leaves room3-2E and has to arrive in room3-2N. Nothing between the two is a switch:
        // the light is bent by mirrors, a mirror only works while somebody is holding it, and nobody
        // can hold two (CLAUDE.md §4). **One mirror is one past self.**
        //
        // Why it is this and not the coloured levers it replaced: a lever REMEMBERS a decision, so a
        // past self who threw one wrongly goes on throwing it wrongly for the rest of the cycle, and
        // there is no way to make a remembered decision both meaningful and harmless. A mirror
        // remembers nothing - a ghost holding one is a body in a place, which `RecordedFrame` already
        // stores exactly. The full argument is in `Mirror`.
        //
        // Everything here lives in ONE HORIZONTAL PLANE at `BeamHeight`, and that is forced by the
        // recording format rather than chosen for looks: a timeline has `position`, `yaw` and
        // `signals` in it and no pitch anywhere, so a mirror that could tilt would replay at the wrong
        // angle in a ghost's hands.

        private const string MirrorModel = FurnitureDir + "/mirror_trensum.glb";

        // A SUPPLY of five, sharing one id, exactly as the three pins share `"Tool"`. A recorded "took
        // a Mirror" has to be satisfiable by whichever one is going spare, and `CarryEvent`'s
        // `instanceName` is what keeps track of WHICH - see CLAUDE.md §1.4.
        // The FIRST pane's name, and the stem the rest are numbered off. Each mirror's id is its own
        // object name now - see the assignment in `BuildMirror`.
        private const string MirrorItemId = "Mirror";

        // THE ONE PANE THAT LEAVES THE PLANE. Named rather than numbered because it is not one of the
        // rack's five and must never be mistaken for one - by a reader or by a ghost, which is why it
        // carries its own id.
        // THE SOCKET, IN TWO SIZES, AND THEY DO DIFFERENT JOBS.
        //
        // `SocketFace` is the grey disc: what the player FINDS, from the far end of a room seventeen
        // metres across and three storeys tall. It wants to be big.
        //
        // `SocketBore` is the notch cut in the middle of it: what the player AIMS AT. It wants to be
        // small, because a hole only reads as drilled while it is much smaller than the plate it is
        // drilled in - at 0.34 against a 0.44 collar the two were nearly the same circle, which is
        // why the last version read as a dark disc rather than as a hole.
        //
        // **NEITHER IS `LaserReceiver.radius`, and that is deliberate.** The hit is judged on 0.7m,
        // which is generous on purpose: a mirror is aimed by turning your body and the law of
        // reflection doubles every wobble, so at twenty metres one degree of hand is 70cm of travel
        // and a target measured in centimetres is one nobody could hold. **The cost is that a beam can
        // land visibly outside the notch and still count** - worth knowing before anybody "fixes" it
        // by tightening the tolerance to match the picture. `TODO.md`.
        private const float SocketFace = 1.15f;
        private const float SocketBore = 0.20f;
        // How deep the bore is. Deep relative to its own WIDTH is what reads as a hole - at 0.20
        // across, 0.13 down is two thirds of a diameter, so the wall of the bore is visible from any
        // angle a player approaches it at rather than only dead ahead.
        private const float SocketDepth = 0.13f;

        // **~~THE RISER PANE AND ITS 45 DEGREES~~ GONE 2026-08-30**, with the ceiling call two days
        // before it. What it did is worth keeping written down, because the arithmetic is the kind
        // that gets rediscovered: a pane tilted up by t turns a level beam through 2t, so 45 and only
        // 45 sends a level beam straight up. If anything ever wants a beam to leave this plane again,
        // that is the number and `Mirror.facePitch` is the field.
        private const int MirrorCount = 5;

        // Chest height. Under the 2.7038 gate opening by a mile, so the beam passes through every gate
        // in the cycle, and above the bed in room3-1 so it crosses that room without being interrupted
        // by the furniture. One constant: the emitter, the receiver and every mirror take it from
        // here, so the beam cannot miss a mirror by being on a different plane from it.
        private const float BeamHeight = 1.2f;

        // Where along its own wall the emitter sits. Centred.
        //
        // **THE EMITTER IS ON ROOM3-2E'S SOUTH WALL AND FIRES NORTH** (2026-08-22, by request; it was
        // on the east wall firing west). That is not a cosmetic move - it changes the puzzle, and for
        // the better:
        //
        // - **The first mirror now lives in room3-2E.** Firing north, the light runs up its own room
        //   and stops at the far wall; getting it out through the gate, which is in the WEST wall,
        //   takes a turn made inside this room. The route was two mirrors long with five on the floor.
        //   It is three now, and room3-2E stops being a wall with a gun on it.
        // - **The lane through room3-1 becomes the player's choice** rather than a constant here. The
        //   west-bound leg can leave at any z the gate's opening allows - the middle PAIR of cells,
        //   so ±1.75 of the wall's centre.
        //
        // **And that choice is narrower than it looks, because of the bed.** The beam clears it on its
        // own (0.89 tall against a 1.2 lane), but the corner mirror in room3-1 has to be STOOD at, on
        // the corridor's axis, and a person holding a mirror half a metre in front of them needs rather
        // more room than a beam. The bed is 1.26 x 2.05 and sits 0.70 NORTH of centre, so it reaches
        // z +1.72 and eats the northern half of the band outright. What is left is roughly z -1.75 to
        // -0.7: about a metre of usable lane, on the south side, with the bed visibly explaining why.
        // Both figures are read off the build (`Cycle 3 bed:` in the log) rather than off a plan.
        private const float BeamLane = 0f;

        // ONE MIRROR, scattered on a floor or held in both hands.
        //
        // **EVERYTHING ABOUT THIS MODEL IS MEASURED, AND EACH THING THAT WAS ASSUMED INSTEAD WAS
        // WRONG IN PLAY.** `mirror_trensum.glb` is an IKEA clamp-on vanity mirror converted from an
        // FBX. Three separate traps, in the order they were found:
        //
        // 1. **It is Z-UP**, not Y-up - foot at z 0, head at z 0.229.
        // 2. **The glass is not on a model axis.** The head is TILTED on its clamp, the way a
        //    dressing-table mirror is, so assuming the silvered normal was the model's +Y left every
        //    mirror in the room a few degrees turned. The give-away was in the dump from the start:
        //    the pane's own bounds are (0.165, 0.0437, 0.1596), and 44mm is far too thick for a sheet
        //    of glass unless it is lying at an angle inside its own box. About 15 degrees of it.
        // 3. **A pane's vertex normals do not say which side of the frame it is on.** Averaging them
        //    gives the axis; the SIGN has to come from somewhere else, and getting it backwards
        //    silvered the side facing the holder. Play reported it exactly that way - "the front of
        //    the mirror is looking at me". The other pane settles it: the two are back to back, so
        //    the vector from one to the other IS the first one's outward direction.
        //
        // And then the tilt has to be taken OUT rather than lived with, because it pulls two ways at
        // once: the optics need the glass vertical (the beam is horizontal), and the eye needs the
        // stand vertical (it is a thing standing on a floor). Aligning either one leans the other by
        // fifteen degrees, which is what "make it stand up straight" was about. **So the head is
        // rotated back on its own clamp** - which is what the clamp is for - and both come out
        // upright.
        private static CarryableItem BuildMirror(Transform parent, string name, Vector3 floorAt,
                                                 float yaw, Sprite icon, float facePitch = 0f)
        {
            GameObject root = new GameObject(name);
            root.transform.SetParent(parent, false);
            root.transform.localPosition = floorAt;
            root.transform.localRotation = Quaternion.Euler(0f, yaw, 0f);

            // The face carries everything visible and is what `Mirror` re-aims every frame off the
            // HOLDER. The root follows a hand - a bone, for a ghost - and must not be believed.
            GameObject face = new GameObject("Face");
            face.transform.SetParent(root.transform, false);

            (GameObject model, Bounds bounds) = PlaceModelLocal(
                MirrorModel, face.transform, "Model", Vector3.zero, Quaternion.identity, MirrorHeight);
            if (model == null) return null;

            Renderer front = null, back = null, clamp = null;
            foreach (Renderer r in model.GetComponentsInChildren<Renderer>(true))
            {
                if (r.name.StartsWith("CLAMP")) clamp = r;
                if (!r.name.StartsWith("MIRROR")) continue;
                if (front == null) front = r;
                else if (back == null) back = r;
            }

            if (front == null || back == null)
            {
                Debug.LogError($"[SceneBuilder] {name}: expected two `MIRROR` meshes in {MirrorModel}, "
                             + "found " + (front == null ? "none" : "one")
                             + ". Run Iteration Room/Dump Furniture Models.");
                return null;
            }

            MeshFilter frontMesh = front.GetComponent<MeshFilter>();
            if (frontMesh == null || frontMesh.sharedMesh == null)
            {
                Debug.LogError($"[SceneBuilder] {name}: the `MIRROR` mesh has no geometry.");
                return null;
            }

            // WHICH WAY THE GLASS POINTS - **the THIN AXIS of the mesh's own bounds**, sign from the
            // other pane.
            //
            // **It was the average of the vertex normals, and that was wrong for a reason worth
            // keeping**: a pane modelled as a SOLID - front, back and a rim - has a normal for every
            // direction and they cancel, so the average is a near-zero vector pointing nowhere in
            // particular. The magnitude check passed anyway (it is not exactly zero) and the direction
            // was noise, which is why every mirror in the room came out at some arbitrary angle. Play
            // called it "the disc looks like it can rotate", which is precisely what a garbage
            // orientation looks like.
            //
            // A flat disc has one short axis and it is the normal. That is a fact about the shape
            // rather than about how somebody chose to weld the mesh.
            Vector3 ms = frontMesh.sharedMesh.bounds.size;
            Vector3 thin = ms.x <= ms.y && ms.x <= ms.z ? Vector3.right
                         : ms.y <= ms.z ? Vector3.up : Vector3.forward;

            Vector3 glassNormal = face.transform.InverseTransformDirection(
                front.transform.TransformDirection(thin)).normalized;

            // The two panes are back to back, so the vector from one to the other IS the first one's
            // outward direction. Anywhere a sign has to be chosen, find a second feature that decides
            // it rather than picking and waiting to be told.
            Vector3 outward = face.transform.InverseTransformDirection(
                front.bounds.center - back.bounds.center);
            if (Vector3.Dot(outward, glassNormal) < 0f) glassNormal = -glassNormal;

            // The glass is round, so its largest local dimension IS its diameter.
            float radius = 0.5f * Mathf.Max(ms.x, Mathf.Max(ms.y, ms.z)) * front.transform.lossyScale.x;

            // STAND IT UP FIRST. The model's own up - its +Z, which is what the FBX conversion left
            // behind - becomes +Y, and the HORIZONTAL part of the glass normal becomes +Z. Written as
            // which axis becomes which rather than as three numbers, because the numbers would be a
            // lie the moment the model is replaced.
            Vector3 modelUp = Vector3.forward;
            Vector3 flatNormal = Vector3.ProjectOnPlane(glassNormal, modelUp);
            if (flatNormal.sqrMagnitude < 1e-6f) flatNormal = Vector3.right;
            model.transform.localRotation =
                Quaternion.Inverse(Quaternion.LookRotation(flatNormal.normalized, modelUp));

            // THEN TAKE THE TILT OUT OF THE HEAD, on the clamp it tilts on. What turns with the glass
            // is the frame and both panes; the arm, the stem and the foot stay where they are, which
            // is what keeps the thing standing on its base.
            //
            // **THEY ARE TURNED ONE BY ONE ABOUT A SHARED POINT, NOT REPARENTED UNDER A COMMON PIVOT,
            // and the first version did the second and silently did nothing.** A model placed with
            // `PrefabUtility.InstantiatePrefab` is a prefab INSTANCE, and Unity refuses to restructure
            // one - `SetParent` across it is dropped without an exception. The build cheerfully
            // reported "levelled on the clamp: yes" for a pivot that had collected zero nodes, which
            // is what a log that measures the intention instead of the result is worth.
            //
            // Rotating each node about the same world point by the same amount is exactly what a
            // common parent would have done, and needs no restructuring at all.
            var tilting = new System.Collections.Generic.List<Transform>();
            foreach (Transform t in model.GetComponentsInChildren<Transform>(true))
            {
                if (!(t.name.StartsWith("FRAME") || t.name.StartsWith("MIRROR"))) continue;
                // Only the topmost of each - a pane's mesh child carries the same name as its node.
                if (t.parent != null && (t.parent.name.StartsWith("FRAME")
                                         || t.parent.name.StartsWith("MIRROR"))) continue;
                tilting.Add(t);
            }

            Vector3 clampAt = clamp != null ? clamp.bounds.center : front.bounds.center;

            // Re-measured after the stand went upright, because that is the angle that is left.
            // `FromToRotation` rather than an euler: it carries its own sign, and a sign written by
            // hand here is a coin toss that only shows up in a screenshot.
            Vector3 nNow = face.transform.InverseTransformDirection(
                front.transform.TransformDirection(thin)).normalized;
            if (Vector3.Dot(nNow, Vector3.forward) < 0f) nNow = -nNow;

            float tilt = Mathf.Asin(Mathf.Clamp(nNow.y, -1f, 1f)) * Mathf.Rad2Deg;
            Vector3 nLevel = new Vector3(nNow.x, 0f, nNow.z);
            if (tilting.Count > 0 && nLevel.sqrMagnitude > 1e-6f)
            {
                Quaternion level = Quaternion.FromToRotation(nNow, nLevel.normalized);
                level.ToAngleAxis(out float angle, out Vector3 axis);
                if (angle > 0.01f && angle < 359.99f)
                {
                    Vector3 axisWorld = face.transform.TransformDirection(axis);
                    foreach (Transform t in tilting) t.RotateAround(clampAt, axisWorld, angle);
                }
            }

            // **MEASURED AFTER, not before.** The line under this used to print the angle the stand-up
            // left behind and stop there, which says nothing at all about whether the correction
            // worked - and it did not, for a while, with the log cheerfully reporting the fault it
            // was supposed to catch.
            Vector3 after = face.transform.InverseTransformDirection(
                front.transform.TransformDirection(thin)).normalized;
            if (Vector3.Dot(after, Vector3.forward) < 0f) after = -after;
            float residual = Mathf.Asin(Mathf.Clamp(after.y, -1f, 1f)) * Mathf.Rad2Deg;

            if (name.EndsWith("Mirror"))
                Debug.Log($"[SceneBuilder] {name}: glass thin axis {thin}, stand-up left the disc "
                        + $"{tilt:0.##}° off vertical, {tilting.Count} node(s) turned on the clamp, "
                        + $"**residual {residual:0.##}°**.");

            // THE DISC'S CENTRE BECOMES THE OBJECT'S ORIGIN, re-measured after both turns. Everything
            // downstream - the carry pose, `Mirror.Centre`, the beam, the prompt - then talks about the
            // glass rather than about a pivot that happens to be under a foot.
            Vector3 centreInFace = face.transform.InverseTransformPoint(front.bounds.center);
            model.transform.localPosition -= centreInFace;

            // **AND THE OBJECT NOW STANDS ON THE FLOOR.** `CarryableItem.floorY` is how far the ORIGIN
            // rests above the floor, and this origin is the middle of the glass - so it is the height
            // of the glass above the mirror's own foot, measured rather than guessed. Without it a
            // dropped mirror sank to its waist.
            bounds = MeasuredBounds(model);
            float glassAboveFoot = root.transform.position.y - bounds.min.y;
            root.transform.localPosition += Vector3.up * glassAboveFoot;

            // **THE BACK IS BLANKED, and that is the single-sided rule made visible.** The model ships
            // with glass on both sides; a beam that arrives at the back of this one stops dead, so the
            // two faces must not look alike or the rule is a trick.
            back.sharedMaterial = MakeColorMaterial("MirrorBack", new Color(0.13f, 0.13f, 0.15f));

            BoxCollider reach = root.AddComponent<BoxCollider>();
            reach.isTrigger = true;
            reach.size = Vector3.one * 1.1f;

            CarryableItem item = root.AddComponent<CarryableItem>();
            // ONE ID PER PANE. Five mirrors sharing one id made a SUPPLY, and a ghost replaying
            // "took a Mirror" would then take whichever was going spare - which for a puzzle made of
            // people standing in a line is the route quietly rearranging itself. It matters more now
            // that the panes are not interchangeable: one of them sends the beam to the ceiling, and
            // a ghost handed THAT one where a flat one was recorded breaks the chain. Same reasoning
            // as the pool props; see `BuildFloatingProps`.
            item.itemId = name;
            item.displayName = "MIRROR";
            // `Mirror.Sync` puts the glass in front of the holder's BODY, not at the hand anchor - so
            // `HeldItemClearance` must not freeze the view on a contact measured at the anchor. See
            // `CarryableItem.posesItself`.
            item.posesItself = true;
            item.icon = icon;
            item.floorY = glassAboveFoot;
            // **THE PROMPT HANGS OFF THE GLASS, NOT OFF THE ROOT, and that is how you take one off a
            // past self.** A carried item is parented to its holder's hand - a wrist bone, for a ghost
            // - while `Mirror` puts the glass out in front of their body. Left on the root, the aim
            // test and the prompt disc sat at the wrist and the thing you were looking at was a metre
            // away: play found it as "taking the mirror off a ghost does not work". The reach volume
            // follows the same point, from `Mirror.Sync`.
            item.hintAnchor = face.transform;
            item.handLocalPosition = new Vector3(0f, -0.34f, 0.62f);
            item.restsUpright = true;
            item.audioSource = MakeSource(root.transform, "PickupAudio", 1f, 0.85f);
            item.pickupClip = LoadClip(SfxDir, "sfx_item_pickup");

            Mirror mirror = root.AddComponent<Mirror>();
            mirror.face = face.transform;
            mirror.radius = radius;
            mirror.frontRenderer = front;
            mirror.backRenderer = back;
            mirror.reach = reach;
            // ABOVE THE HOLDER'S FEET, not a world height. `BeamHeight` is how high the emitter
            // fires above its own floor, so a holder standing on any floor in the cycle presents the
            // glass exactly where a beam crossing that floor is - which on the ground floor is the
            // height this used to be pinned to, and on deck A is five metres higher.
            mirror.carryHeight = BeamHeight;
            mirror.facePitchDegrees = facePitch;

            // **THE DISC LEANS; THE STAND DOES NOT.**
            //
            // **TURNED ABOUT A SHARED POINT, NEVER REPARENTED - the same rule the stand-up correction
            // above had to learn, and the first version of this broke it and looked like something
            // else entirely.** `model` is a prefab INSTANCE, so `SetParent` across it is dropped
            // without an exception: the panes and the frame did not move an inch. What DID move was
            // the empty pivot they were supposed to hang under, and `Mirror.Normal` read that - so the
            // optics tilted 45 degrees while the object stood up straight, and the mirror rendered a
            // reflection of a plane it was not on. Play reported it as "the frame is not rotated, only
            // the mirror inside it is", which is exactly what a 45-degree reflection painted onto an
            // upright pane looks like.
            //
            // `tilting` is already the right set and was built for the same job one correction
            // earlier: the topmost `FRAME` and `MIRROR` nodes and nothing else. Measured off
            // `mirror_trensum.glb` rather than assumed, in model units:
            //   FRAME        y 0.117 - 0.252    the rim, 0.138 across
            //   MIRROR 2     y 0.119 - 0.248    glass
            //   MIRROR 2.001 y 0.122 - 0.251    glass, the other face
            //   C / CLAMP / FOOT / BASE / BOLT  y 0 - 0.198   the stand, which must NOT move
            //   ring         y 0.005            **NOT the rim** - a 24mm ring lying on the base plate
            //   IMG-1872     y 0.005            a flat label on the base
            // `ring` is the one a name would get wrong, which is why the bounds are written down.
            //
            // The turn happens about the GLASS CENTRE, which is `face`'s own origin by construction -
            // the model was slid to put it there. That point is within a millimetre of the clamp's
            // centre (0.184 against 0.185), so the head turns on the hinge a real one turns on.
            if (Mathf.Abs(facePitch) > 0.01f)
            {
                // An EMPTY marker, and it is only the optics. It carries no children - the visual
                // parts cannot be reparented under it - and exists so `Mirror.Normal` has a transform
                // to read that is driven by the same number as the geometry below.
                GameObject glassPivot = new GameObject("GlassTilt");
                glassPivot.transform.SetParent(face.transform, false);
                glassPivot.transform.localRotation = Quaternion.Euler(-facePitch, 0f, 0f);
                mirror.glass = glassPivot.transform;

                // And the geometry, turned to match. `-facePitch` about the face's own +X is the same
                // rotation the marker just took: both send the outward normal up by `facePitch`.
                Vector3 hinge = face.transform.position;
                Vector3 pitchAxis = face.transform.right;
                foreach (Transform t in tilting) t.RotateAround(hinge, pitchAxis, -facePitch);

                // **MEASURED OFF THE PANE, NOT COUNTED OFF THE LIST.** A log that says how many nodes
                // it meant to turn is what let the reparent ship; this reads the front pane's actual
                // world normal back and reports the angle it really makes with the horizontal, so a
                // rotation that did not happen prints 0.
                Vector3 paneNormal = front.transform.TransformDirection(thin).normalized;
                float panePitch = 90f - Vector3.Angle(paneNormal, Vector3.up);
                Debug.Log($"[SceneBuilder] {name}: head turned on the hinge - {tilting.Count} node(s), "
                        + $"pane now **{Mathf.Abs(panePitch):0.#}deg** off vertical against "
                        + $"{facePitch:0.#} asked for. Expects 3 nodes (two panes and the frame); the "
                        + "stand is not among them.");
            }

            BuildMirrorReflection(root.transform, mirror, front);

            return item;
        }

        // WHAT THE GLASS SHOWS. A camera standing behind the mirror looking back, and a shader that
        // samples what it drew by SCREEN position - see `MirrorReflection` for the four rules that
        // keep it affordable and `MirrorGlass.shader` for why screen space rather than UVs.
        private static void BuildMirrorReflection(Transform root, Mirror mirror, Renderer glass)
        {
            Shader shader = AssetDatabase.LoadAssetAtPath<Shader>($"{ShadersDir}/MirrorGlass.shader");
            if (shader == null)
            {
                Debug.LogError($"[SceneBuilder] MirrorGlass.shader missing from {ShadersDir} - "
                             + "the mirrors will show whatever the model shipped with.");
                return;
            }

            // **THE TINT IS WHAT ENDS THE TUNNEL**, and it is a value rather than a shader default
            // for the reason every number in this project is (CLAUDE.md §2). Slightly cool and a
            // quarter down from white: real glass loses about that much per bounce, and two mirrors
            // facing each other then fade out on their own instead of needing a cap.
            Material glassMat = MakeColorMaterial("MirrorGlass", new Color(0.76f, 0.78f, 0.82f));
            glassMat.shader = shader;
            glassMat.SetColor("_Tint", new Color(0.76f, 0.78f, 0.82f));
            glass.sharedMaterial = glassMat;

            GameObject rig = new GameObject("ReflectionCamera");
            rig.transform.SetParent(root, false);

            Camera cam = rig.AddComponent<Camera>();
            cam.enabled = false;
            cam.clearFlags = CameraClearFlags.SolidColor;
            cam.backgroundColor = Color.black;
            cam.allowHDR = false;
            cam.allowMSAA = false;
            // The building, not the horizon. Room3-2N is the deepest thing a mirror can be pointed
            // down and it is 21m.
            cam.farClipPlane = 40f;
            // The WHOLE player, never the headless one they are looking out of - the entire point of
            // a mirror here is seeing yourself. The shadow body goes too: the world body already casts
            // here, and both would put two shadows under one person.
            cam.cullingMask &= ~(1 << EnsureLayer(PlayerBodyViewLayer));
            cam.cullingMask &= ~(1 << EnsureLayer(PlayerBodyShadowLayer));

            // Same trim as the CCTV feeds, and for the same reason: a reflection of a white room does
            // not need the pipeline the game needs, and shadow maps were the expensive part.
            UniversalAdditionalCameraData data = cam.GetUniversalAdditionalCameraData();
            data.renderShadows = false;
            data.renderPostProcessing = false;
            data.requiresColorOption = CameraOverrideOption.Off;
            data.requiresDepthOption = CameraOverrideOption.Off;
            data.antialiasing = AntialiasingMode.None;
            data.dithering = false;
            data.stopNaN = false;

            MirrorReflection reflection = root.gameObject.AddComponent<MirrorReflection>();
            reflection.mirror = mirror;
            reflection.glass = glass;
            reflection.reflectionCamera = cam;
        }

        // Big enough to be a thing carried in both hands and to be an easy target for a beam twenty
        // metres away. At this height the glass comes out about half a metre across.
        private const float MirrorHeight = 1.0f;

        // WHERE THE FIVE LIVE. **Scattered across room3-2W's floor** (2026-08-21, by request) rather
        // than racked in a row on a wall. A rack says "take one of these five"; five of them standing
        // about at odd angles says "somebody left these here", which is what every other room in this
        // building says about its contents.
        //
        // Placed clear of the walk in from the east gate, so getting into the room is not a matter of
        // stepping over the puzzle.
        private static CarryableItem[] BuildMirrorRack(Transform room, Material propMat)
        {
            GameObject rack = new GameObject("Mirrors");
            rack.transform.SetParent(room, false);

            var spots = new (float x, float z, float yaw)[]
            {
                (-2.6f,  3.7f,  40f),
                ( 1.6f,  4.3f, 205f),
                (-3.1f, -2.2f, 120f),
                ( 2.2f, -3.9f, 290f),
                (-0.4f,  0.9f, 165f),
            };

            // Drawn once and shared. `SaveSprite` writes a PNG and reimports it, so a glyph made
            // inside the loop is the same file written five times over.
            Sprite icon = MirrorIcon();

            var mirrors = new CarryableItem[MirrorCount];
            for (int i = 0; i < MirrorCount && i < spots.Length; i++)
                mirrors[i] = BuildMirror(rack.transform, i == 0 ? "Mirror" : $"Mirror_{i}",
                    new Vector3(spots[i].x, 0f, spots[i].z), spots[i].yaw, icon);

            return mirrors;
        }

        // THE SOURCE. On room3-2E's SOUTH wall, firing north up its own room - so the first mirror of
        // the route has to be held in here, and the way out through the west gate is a turn somebody
        // makes rather than a line somebody drew.
        private static LaserBeam BuildLaserEmitter(Transform room, Material propMat)
        {
            GameObject root = new GameObject("LaserEmitter");
            root.transform.SetParent(room, false);
            root.transform.localPosition = new Vector3(BeamLane, BeamHeight, -RoomDepth / 2f + 0.2f);
            // Local +Z points the way the beam goes: north, up its own room, at nothing in particular
            // until somebody stands in it with a mirror.
            root.transform.localRotation = Quaternion.LookRotation(Vector3.forward, Vector3.up);

            // **DARK, AND THAT IS THE WHOLE OF IT** (simplified 2026-08-28, by request: it had got
            // "조잡" - cluttered).
            //
            // The one thing this object needed was to stop being white: built out of `propMat` it was
            // a pale box against a pale wall in a pale room, and the only part you could find was the
            // 6mm aperture. A dark housing fixes that completely.
            //
            // **Everything ELSE that was added along with the dark - heat-sink fins, a hazard band, a
            // recessed throat, a flare at the mouth - was solving a problem nobody had**, and three
            // of the four introduced one: the band shared a plane with the housing's front face and
            // the flare's radius exactly matched the barrel's, which is what play saw as a black
            // wedge across the muzzle. A box, a barrel and a lit aperture say "this fires something"
            // without any of that.
            Material shell = MakeColorMaterial("LaserShell", new Color(0.12f, 0.12f, 0.14f));
            SetSmoothness(shell, 0.55f);

            Prim(PrimitiveType.Cube, "Housing", root.transform, new Vector3(0f, 0f, -0.16f),
                new Vector3(0.42f, 0.42f, 0.44f), shell);
            Prim(PrimitiveType.Cylinder, "Barrel", root.transform, new Vector3(0f, 0f, 0.10f),
                new Vector3(0.13f, 0.09f, 0.13f), shell)
                .transform.localRotation = Quaternion.Euler(90f, 0f, 0f);

            // The lit mouth. Past 1.0 on purpose: `ConfigureVolume` puts the bloom threshold at 1.2
            // precisely so this building's near-white walls do NOT bloom, so a thing that should has
            // to be given a value that clears it.
            Material glow = MakeEmissiveMaterial("LaserGlow", new Color(1f, 0.28f, 0.22f), 6f);
            Prim(PrimitiveType.Cylinder, "Aperture", root.transform, new Vector3(0f, 0f, 0.192f),
                new Vector3(0.075f, 0.006f, 0.075f), glow, removeCollider: true)
                .transform.localRotation = Quaternion.Euler(90f, 0f, 0f);

            GameObject muzzle = new GameObject("Muzzle");
            muzzle.transform.SetParent(root.transform, false);
            muzzle.transform.localPosition = new Vector3(0f, 0f, 0.2f);

            LaserBeam beam = root.AddComponent<LaserBeam>();
            beam.muzzle = muzzle.transform;

            // ONE LINE RENDERER PER POSSIBLE SEGMENT, built here rather than pooled at runtime so
            // the scene says what it contains. Unlit: a beam is a light source, not a lit surface.
            //
            // **ONE PLAIN RED LINE, and it went two passes and came back** (2026-08-28). A hot white
            // core inside a red halo is what a laser in air actually looks like, and in this room it
            // was worse: the thing has to be findable at a glance across seventeen metres of white,
            // and what makes it findable is being RED - which a white-cored beam is not, and a wide
            // soft one has an edge instead of a colour.
            Material beamMat = MakeColorMaterial("LaserBeamLine", new Color(1f, 0.22f, 0.16f));
            Shader unlit = Shader.Find("Universal Render Pipeline/Unlit");
            if (unlit != null) beamMat.shader = unlit;

            var lines = new LineRenderer[beam.maxBounces + 1];
            for (int i = 0; i < lines.Length; i++)
            {
                GameObject seg = new GameObject($"Segment_{i:00}");
                seg.transform.SetParent(root.transform, false);
                LineRenderer line = seg.AddComponent<LineRenderer>();
                line.useWorldSpace = true;
                line.positionCount = 2;
                line.widthMultiplier = 0.03f;
                line.numCapVertices = 2;
                line.sharedMaterial = beamMat;
                line.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
                line.receiveShadows = false;
                line.enabled = false;
                lines[i] = line;
            }
            beam.segments = lines;

            // WHERE IT LANDS. Two spheres for the same reason the beam is two lines: a hot point and
            // the scatter around it. This is the thing the whole aiming loop is watching move, so it
            // has to be findable across a room three storeys tall.
            GameObject dot = Prim(PrimitiveType.Sphere, "TerminalDot", root.transform,
                Vector3.zero, Vector3.one * 0.09f, glow, removeCollider: true);
            beam.terminalDot = dot.transform;

            beam.audioSource = MakeSource(root.transform, "LaserAudio", spatialBlend: 1f, volume: 0.6f);
            beam.hitClip = LoadClip(SfxDir, "sfx_switch_on");
            return beam;
        }

        // WHAT IT HAS TO REACH. On room3-2N's west wall for now, so the shortest route needs one turn
        // in room3-1 and one more inside the big room - two mirrors of the five.
        //
        // **WHAT IT DOES IS UNDECIDED, AND THAT IS DELIBERATE.** `LaserReceiver.Lit` is the whole
        // interface; whether the beam runs a machine or opens the way out of the cycle is a design
        // decision that has not been taken, and taking it in code before it is taken in play is what
        // put a CCTV system in this cycle before there was a puzzle for it to watch.
        // **A LINE PAINTED ON THE WALL AND THE FLOOR, FROM A CALL PLATE TO THE LIFT IT WORKS**
        // (2026-08-28, by request).
        //
        // Two plates on opposite walls and two lifts elsewhere in the room is four possible pairings
        // and no way to tell which is real - the only way to learn it was to fire the beam and see
        // what moved, which makes the room a guess rather than a puzzle. A line answers it before
        // anything is tried, and answers it from across the room.
        //
        // **PAINT, NOT CONDUIT.** It was a run of 75mm tube that lit up while its plate was live,
        // which is a fine idea and the wrong object: a pipe standing off a floor is a THING IN THE
        // ROOM, and the room already has enough of those - it read as another mechanism to work out
        // rather than as a label on the two that exist. Paint is flat, is obviously not machinery,
        // and is what a real plant marks a circuit with.
        //
        // **FLAT ENOUGH TO BE 2D, WITHOUT BEING A DECAL.** There is no decal system here and one is
        // not worth building for two lines, so these are boxes 8mm thick lying against the surface -
        // thin enough to have no visible side, offset just clear of it so nothing z-fights. The rule
        // this project keeps relearning is that a face laid EXACTLY on another face flickers, and the
        // offset is the whole of avoiding it.
        //
        // **ORTHOGONAL, IN THREE RUNS: down the wall, along X, along Z.** Not a straight line between
        // the two points - a stripe slanting across a floor reads as an annotation somebody drew,
        // where one that turns square corners reads as a marking that belongs to the building. It is
        // also easier to follow: the eye tracks a right angle and loses a diagonal among the wall
        // grid's own lines.
        private static void BuildCallConduit(Transform room, string name, Vector3 plateAt,
                                             Vector3 inward, Vector2 toXZ)
        {
            const float ink = 0.055f;      // how wide the line is painted
            const float leaf = 0.008f;     // how thick the paint is
            const float clear = 0.006f;    // how far it stands off the surface it is painted on

            GameObject root = new GameObject(name);
            root.transform.SetParent(room, false);

            Material paint = MakeColorMaterial("MarkingPaint", new Color(0.09f, 0.09f, 0.10f));
            SetSmoothness(paint, 0.18f);

            void Bar(string barName, Vector3 at, Vector3 size) =>
                Prim(PrimitiveType.Cube, barName, root.transform, at, size, paint,
                     removeCollider: true);

            // ON THE WALL: from just under the plate down to the floor. Placed off the PLATE rather
            // than off a wall coordinate - the plate is mounted a known distance proud of the wall it
            // is bolted to, so this cannot drift if the fixture moves.
            float wallX = plateAt.x - inward.x * (0.13f - clear);
            float wallZ = plateAt.z - inward.z * (0.13f - clear);
            float top = plateAt.y - 0.80f;

            Bar("Wall", new Vector3(wallX, (top + clear) / 2f, wallZ),
                new Vector3(Mathf.Abs(inward.x) > 0.5f ? leaf : ink, top - clear,
                            Mathf.Abs(inward.z) > 0.5f ? leaf : ink));

            // ON THE FLOOR: out from the wall, then along to the lift. The corner is where the two
            // runs overlap, which is also what stops a hairline gap showing at the turn.
            float fromX = wallX + inward.x * 0.02f;
            float fromZ = wallZ + inward.z * 0.02f;

            Bar("Floor_X", new Vector3((fromX + toXZ.x) / 2f, clear, fromZ),
                new Vector3(Mathf.Abs(toXZ.x - fromX) + ink, leaf, ink));
            Bar("Floor_Z", new Vector3(toXZ.x, clear, (fromZ + toXZ.y) / 2f),
                new Vector3(ink, leaf, Mathf.Abs(toXZ.y - fromZ) + ink));
        }

        // A DECK ON A SHAFT, PULLED DOWN BY THE BEAM AND RISING WHEN IT GOES. See `BeamLift` for why
        // it runs that way round rather than the obvious one.
        //
        // **WHERE IT STANDS IS DECIDED BY DECK A'S EDGE, not chosen.** Deck A is an L two cells deep
        // down the west wall, so its inner edge is at `-width/2 + 2 * GridCellWidth`; the shaft is
        // butted against that edge on the open side, and the panel at rest is flush with the deck's
        // surface. Anywhere else and the ride ends beside the deck rather than on it.
        // ONE STOREY OF LIFT. Both of room3-2N's are this, and the only things that differ are where
        // the shaft stands, how big the deck is, and which two surfaces it runs between - so they are
        // arguments and there is one description of what a lift IS.
        //
        // `lowerSurface` and `upperSurface` are the FLOORS it joins, not slab positions: the panel's
        // top face lands flush with each. Everything about the slab's own thickness is dealt with
        // here, so a caller never has to think about it.
        private static BeamLift BuildBeamLift(Transform room, string name, Vector2 shaftXZ, float pad,
                                              float lowerSurface, float upperSurface,
                                              Material propMat, Material grooveMat,
                                              float? shaftFootY, params LaserReceiver[] calls)
        {
            const float thickness = 0.24f;      // thick enough to read as a floor rather than a card

            GameObject root = new GameObject(name);
            root.transform.SetParent(room, false);
            root.transform.localPosition = new Vector3(shaftXZ.x, 0f, shaftXZ.y);

            GameObject panel = new GameObject("Deck");
            panel.transform.SetParent(root.transform, false);

            Prim(PrimitiveType.Cube, "Slab", panel.transform, Vector3.zero,
                new Vector3(pad, thickness, pad), propMat);
            // A dark rim, so the edge of a floor several metres up is visible from on top of it.
            // There is no parapet anywhere in this room by decision, which makes the edge itself the
            // only warning there is.
            //
            // **ALL FOUR SIDES** (2026-08-28, by request). The west band was left off because that is
            // the side butted against the deck, and a band there marks an edge you cannot fall off -
            // which was reasoning about the DECK'S geometry from inside a builder that knows nothing
            // about it, and is wrong for the second lift anyway. Three sides read as an unfinished
            // object rather than as a considered omission, which is what play reported.
            const float rim = 0.06f;
            void Rim(string rimName, Vector3 at, Vector3 size) =>
                Prim(PrimitiveType.Cube, rimName, panel.transform, at, size, grooveMat,
                    removeCollider: true);

            Rim("RimN", new Vector3(0f, thickness / 2f, pad / 2f - rim / 2f),
                new Vector3(pad, 0.02f, rim));
            Rim("RimS", new Vector3(0f, thickness / 2f, -pad / 2f + rim / 2f),
                new Vector3(pad, 0.02f, rim));
            Rim("RimE", new Vector3(pad / 2f - rim / 2f, thickness / 2f, 0f),
                new Vector3(rim, 0.02f, pad));
            Rim("RimW", new Vector3(-pad / 2f + rim / 2f, thickness / 2f, 0f),
                new Vector3(rim, 0.02f, pad));

            // **AND THE COLUMN THAT HOLDS IT UP.** Play reported the deck as floating - which it was,
            // a slab travelling through air with no mechanism under it, and that reads as something
            // broken rather than as a lift.
            //
            // Glass, for two reasons that pull the same way: a solid column standing in a room three
            // storeys tall would become the thing the eye goes to, and the whole point of deck B's
            // void is being able to look down through it. `BeamLift.StretchShaft` scales this to span
            // the floor and the deck's underside every frame, so it is measured off the lift rather
            // than animated beside it.
            //
            // Its collider stays: the column is a real object standing in the room, and a player at
            // the bottom of a raised shaft should meet it rather than walk through it.
            Material tube = MakeTranslucentMaterial("LiftShaftGlass",
                new Color(0.62f, 0.70f, 0.76f, 0.20f), 0.92f);
            GameObject shaft = Prim(PrimitiveType.Cylinder, "Shaft", root.transform,
                Vector3.zero, new Vector3(pad * 0.28f, 1f, pad * 0.28f), tube);

            // A collar at the foot, so the column lands ON something rather than stopping at a plane.
            float footY = shaftFootY ?? lowerSurface - LiftRestingStep;
            Prim(PrimitiveType.Cylinder, "ShaftCollar", root.transform,
                new Vector3(0f, footY + 0.06f, 0f),
                new Vector3(pad * 0.42f, 0.06f, pad * 0.42f), grooveMat, removeCollider: true);

            // WHO IS ON IT. Inset by a third of a metre all round, so somebody standing on the deck
            // beside the panel at either end is not dragged along with it; two metres tall, because
            // what is being asked is "are your feet on this", and a standing capsule's bounds are.
            GameObject rideGO = new GameObject("Rider");
            rideGO.transform.SetParent(panel.transform, false);
            BoxCollider ride = rideGO.AddComponent<BoxCollider>();
            ride.isTrigger = true;
            ride.center = new Vector3(0f, thickness / 2f + 1.0f, 0f);
            ride.size = new Vector3(pad - 0.6f, 2.0f, pad - 0.6f);

            BeamLift lift = root.AddComponent<BeamLift>();
            lift.panel = panel.transform;
            lift.calls = calls;
            lift.shaft = shaft.transform;
            // The floor the column stands on. Usually a resting step below where the deck rests -
            // but the second lift is asked to carry its column PAST the deck it starts from and down
            // to the ground, so the caller can say where the floor is.
            lift.shaftBaseY = shaftFootY ?? lowerSurface - LiftRestingStep;
            lift.PanelHalfThickness = thickness / 2f;
            // Half a slab under each surface, so the TOP FACE lands flush with the floor it is joining
            // at either end. Getting this off by the thickness is a step at the top and a lip at the
            // bottom, and both read as the lift being broken rather than as a number being wrong.
            lift.raisedY = upperSurface - thickness / 2f;
            lift.loweredY = lowerSurface - thickness / 2f;
            lift.speed = 2.2f;
            lift.rideVolume = ride;
            lift.audioSource = MakeSource(root.transform, "LiftAudio", spatialBlend: 1f, volume: 0.5f);
            // The same clip the crushing barrier moves on - the two are the same event, a slab
            // that travels, and this building has one sound for that.
            lift.moveClip = LoadClip(SfxDir, "sfx_door_open");

            // Starts where the loop will always put it back.
            lift.ResetLift();

            Debug.Log($"[SceneBuilder] Cycle 3 {name}: {pad:0.##}m deck at local "
                    + $"({shaftXZ.x:0.##}, {shaftXZ.y:0.##}), surfaces {lowerSurface:0.##} -> "
                    + $"{upperSurface:0.##} ({upperSurface - lowerSurface:0.##}m of travel) at "
                    + $"{lift.speed:0.#}m/s, {calls.Length} call(s) - any one lowers it.");
            return lift;
        }

        // **A CALL PLATE IN THE CEILING**, which is where one has to be if the riser pane is the only
        // thing that can reach it: a pane tilted 45 degrees turns a level beam through 90, and a
        // vertical beam lands on the ceiling. Face down, so `Covers` is asked about a point directly
        // under it.
        private static LaserReceiver BuildCeilingCall(Transform room, string name, Vector3 localPos,
                                                      Material propMat)
        {
            GameObject root = new GameObject(name);
            root.transform.SetParent(room, false);
            root.transform.localPosition = localPos;

            // The same pale plate with a small bore drilled in it that the wall sockets have - one
            // kind of object, one look, whichever surface it is bolted to.
            Material bezel = MakeColorMaterial("LaserBezel", new Color(0.58f, 0.59f, 0.61f));
            SetSmoothness(bezel, 0.62f);

            Prim(PrimitiveType.Cube, "Plate", root.transform, new Vector3(0f, 0.06f, 0f),
                new Vector3(1.5f, 0.14f, 1.5f), bezel);
            MakeRing(root.transform, "Face", new Vector3(0f, -0.055f, 0f), Vector3.down,
                SocketFace / 2f, SocketBore / 2f, SocketDepth,
                MakeColorMaterial("LaserCollar", new Color(0.74f, 0.75f, 0.77f)));

            Prim(PrimitiveType.Cylinder, "BoreFloor", root.transform,
                new Vector3(0f, -0.055f + SocketDepth + 0.008f, 0f),
                new Vector3(SocketBore * 0.99f, 0.008f, SocketBore * 0.99f),
                MakeColorMaterial("LaserBore", new Color(0.05f, 0.05f, 0.055f)), removeCollider: true);

            Material lampMat = MakeEmissiveMaterial("LaserReceiverLamp", Color.white, 1f);
            GameObject lens = Prim(PrimitiveType.Cylinder, "Lens", root.transform,
                new Vector3(0f, -0.055f + SocketDepth - 0.004f, 0f),
                new Vector3(SocketBore * 0.80f, 0.006f, SocketBore * 0.80f), lampMat,
                removeCollider: true);

            LaserReceiver call = root.AddComponent<LaserReceiver>();
            call.lamp = lens.GetComponent<Renderer>();
            call.offColour = new Color(0.30f, 0.055f, 0.045f);
            call.radius = 0.7f;
            call.audioSource = MakeSource(root.transform, "ReceiverAudio",
                                          spatialBlend: 1f, volume: 0.8f);
            call.onClip = LoadClip(SfxDir, "sfx_switch_on");
            return call;
        }

        // A PLATE ON A WALL. `inward` is the way it faces, which is also the axis its body is thin
        // on - so the same builder makes a west plate and an east one without a second copy of it.
        private static LaserReceiver BuildLaserReceiver(Transform room, string name, Vector3 localPos,
                                                       Vector3 inward, Material propMat)
        {
            GameObject root = new GameObject(name);
            root.transform.SetParent(room, false);
            root.transform.localPosition = localPos;
            // **A PLATE WITH A SMALL HOLE IN THE MIDDLE OF IT, AND THE BEAM GOES IN THE HOLE**
            // (2026-08-28, by request).
            //
            // This has now been three things. White on a white wall - invisible. Then a dark bezel
            // round a dark bore - "온통 검은색이여서 레이저를 넣는 구멍으로 안보여", all black, so it
            // does not read as somewhere you put a laser. Both failures are the same failure: **a
            // hole is read from the CONTRAST between its rim and its inside, and each version had
            // only one of the two.**
            //
            // So: a pale steel plate, and a small dark bore drilled in the centre of it. The plate is
            // what you find from across the room; the bore is what you aim at; and a hole a good deal
            // smaller than the plate is what makes it look drilled rather than painted on.
            Material bezel = MakeColorMaterial("LaserBezel", new Color(0.58f, 0.59f, 0.61f));
            SetSmoothness(bezel, 0.62f);

            Prim(PrimitiveType.Cube, "Plate", root.transform, -inward * 0.06f,
                new Vector3(0.14f, 1.5f, 1.5f), bezel);

            Quaternion facing = Quaternion.LookRotation(inward) * Quaternion.Euler(90f, 0f, 0f);

            // **THE GREY DISC, WITH A REAL HOLE IN IT.** A `Cylinder` primitive here is what made the
            // last version's notch invisible - a solid disc hides whatever is behind it, and no
            // arrangement of primitives puts a hole in one. `MakeRing` is an annulus with the bore's
            // wall included, so what you look into is geometry rather than a darker circle.
            GameObject face = MakeRing(root.transform, "Face", inward * 0.055f, inward,
                SocketFace / 2f, SocketBore / 2f, SocketDepth,
                MakeColorMaterial("LaserCollar", new Color(0.74f, 0.75f, 0.77f)));

            // THE BOTTOM OF THE BORE, seen down the hole. Dark, and deliberately not black: a
            // zero-value surface takes no light at all and reads as a hole cut in the SCREEN, with
            // nothing for the eye to place in space.
            GameObject well = Prim(PrimitiveType.Cylinder, "BoreFloor", root.transform,
                inward * (0.055f - SocketDepth - 0.008f),
                new Vector3(SocketBore * 0.99f, 0.008f, SocketBore * 0.99f),
                MakeColorMaterial("LaserBore", new Color(0.05f, 0.05f, 0.055f)), removeCollider: true);
            well.transform.localRotation = facing;

            // And the lens sitting on it, which is the part that lights.
            Material lampMat = MakeEmissiveMaterial("LaserReceiverLamp", Color.white, 1f);
            GameObject lamp = Prim(PrimitiveType.Cylinder, "Lens", root.transform,
                inward * (0.055f - SocketDepth + 0.004f),
                new Vector3(SocketBore * 0.80f, 0.006f, SocketBore * 0.80f), lampMat,
                removeCollider: true);
            lamp.transform.localRotation = facing;

            LaserReceiver receiver = root.AddComponent<LaserReceiver>();
            receiver.lamp = lamp.GetComponent<Renderer>();
            // A DARK RED LENS WHEN IT IS OFF, not a grey one. The default here is a neutral charcoal,
            // which inside a dark bore is indistinguishable from the bore - so the socket had no
            // pupil. A red glass that is merely unlit says both what the fixture is FOR and that it
            // is currently not receiving.
            receiver.offColour = new Color(0.30f, 0.055f, 0.045f);
            receiver.radius = 0.7f;
            receiver.audioSource = MakeSource(root.transform, "ReceiverAudio", spatialBlend: 1f, volume: 0.8f);
            receiver.onClip = LoadClip(SfxDir, "sfx_switch_on");
            return receiver;
        }

        private static CrushingBarrier BuildNorthCorridor(Transform parent, Material floorMat,
                                                          Material grooveMat, Material panelMat,
                                                          FloorButton pad)
        {
            GateSpan(RoomWidth, out float openMin, out float openMax, out _, out _);
            float halfWidth = (openMax - openMin) / 2f;

            // **THE WALLS STAND 20mm WIDER THAN THE OPENING, AND THAT IS THE FLICKER FIX.**
            //
            // Measured rather than reasoned, after three wrong guesses - `CycleThreeDiagnostics`
            // opens the built scene and looks for renderers with a face in common. Eight of the twelve
            // pairs it found were this one: room3-1's north wall panel beside the opening ends at
            // x 20.80, and the corridor's side-wall BACKING has its outer face at x 20.80 as well.
            // Full height, both jambs, exactly coplanar.
            //
            // It is not a coincidence of placement, it is a coincidence of CONSTANTS. A panel is inset
            // from its cell boundary by `GridLineThickness / 2` = 0.025, and a backing starts
            // `GrooveDepth` = 0.025 behind the wall face. The two numbers are equal, so the two planes
            // land on each other, and no amount of moving things along Z will separate them.
            //
            // Widening the WALLS broke it, and the corridor stood 20mm wider than its mouth for a day.
            //
            // **IT IS BACK TO ZERO, AND THE 20mm WAS COSTING SOMETHING AT THE OTHER END** (2026-08-21).
            // Two things happened after that fix. The walls were inset along Z until they touch
            // neither room's wall at all, which is what actually separates them from room3-1's
            // panelling - the sentence above about Z is wrong, and it was written before the inset
            // existed. And room3-2N grew a staircase whose steps are wall panels with a metre of tail
            // behind them: the step in the cell next to the mouth reaches 25mm PAST the mouth's edge,
            // into the back of this corridor's west wall.
            //
            // Those two pull opposite ways on the same number. Every 1mm of clearance moves this wall
            // 1mm further west and buries 1mm more of it inside that step - at 25mm the blue step
            // would come through the corridor wall and be visible from inside the corridor. At zero,
            // the wall's face sits 25mm proud of the step's edge and hides it, which is the margin the
            // step's own groove already provides. Keep it at zero unless a scan says otherwise.
            const float wallClearance = 0f;
            float wallHalfWidth = halfWidth + wallClearance;

            // Between the two rooms' inner faces. Both ends are derived, so moving either room moves
            // the corridor with it rather than leaving a gap nobody notices until they fall through.
            // **THE CORRIDOR'S WALLS TOUCH NEITHER ROOM'S WALL, and that took three goes to get to.**
            //
            // `BuildPanelWall` extends its backing and collision `WallDepth` past each end so
            // perpendicular walls bury each other's corners. The corridor runs along Z, so its overrun
            // goes north and south into whatever is there. Built flush to room3-1's inner face it
            // stood 12.5cm INSIDE the room - two black pillars. Inset by one `WallDepth` it stopped
            // protruding but its front face landed on z 113.75, which is exactly the plane of room3-1's
            // own wall panels: coplanar, overlapping, and torn-looking from every angle.
            //
            // Inset by TWO, it starts where room3-1's wall build-up ends. The two ABUT and never
            // share a volume, which is the only arrangement of the three with nothing to fight over -
            // and it is what play asked for in as many words: stop the structures overlapping.
            //
            // Everything else follows: the room beyond moves out by the same amount at its end, and
            // the floor, the shaft and the block still span the whole way between the inner faces.
            float zStart = RoomDepth / 2f;                       // room3-1's inner face
            float wallStart = zStart + 2f * WallDepth;           // clear of room3-1's wall entirely
            float wallEnd = wallStart + CorridorRun;
            float zEnd = wallEnd + 2f * WallDepth;               // room3-2N's inner face
            float zMid = (zStart + zEnd) / 2f;                   // also the walls' midpoint
            float run = zEnd - zStart;

            GameObject root = new GameObject("Room3_1_NorthCorridor");
            root.transform.SetParent(parent, false);

            // Floor and ceiling run the full width including the wall build-up, so the side walls sit
            // ON them rather than beside them.
            float slabWidth = 2f * wallHalfWidth + 2f * WallDepth;

            // **THE FLOOR STOPS WHERE THE ROOMS' FLOORS DO, and getting that wrong was the last
            // flicker.** `BuildSlab` lays a room's floor across its whole `RoomPitch` so neighbouring
            // rooms meet exactly under their shared divider - so room3-1's floor already reaches
            // 5.425, well past its own inner face at 5.25. A corridor floor starting at the inner face
            // double-laid the first 175mm with both top faces on y=0, which is two coplanar surfaces
            // fighting for every pixel right where the player walks in. The big room's floor overruns
            // its interior by `WallDepth` and did the same at the far end.
            //
            // Abutting rather than overlapping is the house style here - see `BuildSlab`, where
            // adjacent rooms' floors meet at the pitch boundary and nothing overlaps at all.
            float floorStart = RoomPitch / 2f;          // where room3-1's own floor slab ends
            float floorEnd = zEnd - WallDepth;          // where room3-2N's begins
            Prim(PrimitiveType.Cube, "Floor", root.transform,
                new Vector3(0f, -WallThickness / 2f, (floorStart + floorEnd) / 2f),
                new Vector3(slabWidth, WallThickness, floorEnd - floorStart), floorMat);

            // NO CEILING OVER THE CORRIDOR. The block that fills it IS the ceiling while it is down,
            // and while it is up the underside of that block is what the player walks beneath - which
            // is the whole image. A slab here would be a lid over a lift shaft and the block would
            // have nowhere to go; the void's own top, built with the barrier below, closes it in.

            // Panelled like every other wall in the building, at the corridor's own height so the grid
            // reads as the same grid one row shorter.
            // **PANELLED THE FULL HEIGHT OF THE SHAFT, not just of the walk.** The corridor has no
            // ceiling of its own - the block is its ceiling - so anyone standing in it with the block
            // raised is looking up past the walking height into the space the block came out of. Built
            // only as high as the corridor, those walls stopped at 2.70 and the shaft's own structure
            // showed above them as a black band down both sides. Play saw it exactly that way.
            //
            // Panelling all the way up also means the shaft needs no separate sides: the wall's own
            // backing and collision are the enclosure, so there is nothing behind the panels to see.
            float shaftTop = GateHeight + CorridorShaftHeight;
            BuildPanelWall(root.transform, "Wall_West", new Vector3(-wallHalfWidth, 0f, zMid),
                Vector3.forward, Vector3.right, CorridorRun, grooveMat, panelMat, Rect.zero, shaftTop);
            BuildPanelWall(root.transform, "Wall_East", new Vector3(wallHalfWidth, 0f, zMid),
                Vector3.forward, Vector3.left, CorridorRun, grooveMat, panelMat, Rect.zero, shaftTop);

            // ~~JAMB TRIM~~ REMOVED. Thin dark fillers were added here on the theory that the dark
            // beside the mouth was a slot opening onto an unlit corridor. It was not - it was the wall
            // overrun above, standing in the room. With that inset, the 25mm either side of the
            // opening is room3-1's OWN groove, backed by its own wall backing 25mm behind, exactly
            // like every other groove on that wall. Nothing to fill.

            // --- the fill ----------------------------------------------------------------------
            //
            // **THE CORRIDOR IS SOLID, AND THE PAD HOLLOWS IT OUT.** Not a slab partway along - the
            // whole twenty-two metres is one block, and holding the pad lifts the entire thing into a
            // void of exactly its own height above. What the player walks through is the hole it
            // leaves; what is over their head the whole way is the block, held up by a foot at the
            // near end that is not theirs.
            //
            // Letting go does not close a door. It fills the corridor back in, everywhere at once,
            // and anywhere inside it is inside the block.
            //
            // The lift is `GateHeight`, so the corridor and the void above it stack to 5.42 - within
            // 2mm of `RoomHeight`, which is not a coincidence worth engineering around but is worth
            // knowing: this whole assembly is one storey tall, like everything else here.
            //
            // **THE 60mm ON TOP IS THE LAST OF THE FLICKER, and it is the most literal answer to what
            // play described** ("after the structure has finished rising, the upper part flickers").
            // At `GateHeight + 0.02` the block's underside came to rest at exactly `GateHeight` - and
            // `GateHeight` is where the wall's cutout stops, so the wall backing's own bottom face is
            // on that plane too. A 25mm-deep strip across the full width of the mouth, near-black
            // backing against white block, sharing a plane, right at the top edge of the opening a
            // player walks under and looks up at.
            //
            // Raised 40mm clear of it instead. The mouth's headroom is unchanged - that is the wall's
            // cutout, not the block - and the top still lands inside `Shaft_Top` without touching
            // either of its faces.
            float lift = GateHeight + 0.06f;

            GameObject barrierRoot = new GameObject("NorthBarrier");
            barrierRoot.transform.SetParent(root.transform, false);
            barrierRoot.transform.localPosition = new Vector3(0f, 0f, zMid);

            // JUST THE TOP OF THE SHAFT. Its sides are the corridor's own panelled walls, which run
            // the full height, and **its two ENDS are the rooms' own walls** - the cutout at each end
            // stops at `GateHeight`, so above the corridor's mouth both walls are intact and already
            // close the shaft.
            //
            // **END CAPS WERE BUILT HERE AND WERE A BUG.** They were placed half the run plus half a
            // wall from the corridor's midpoint, which lands 5cm PAST each room's inner face - so each
            // one was a 2m x 2.7m white slab stuck to the INSIDE of a room's wall, above the corridor
            // mouth, with no grid on it. Play saw it exactly: the panels above the opening did not line
            // up and the dark edging round it was the wrong thickness, because none of it was the wall.
            //
            // White, not the near-black every other cavity in this building is: a groove or a door
            // pocket is meant to read as a dark line, and this is a surface the player looks straight
            // up at from inside the corridor. It is a ceiling and takes the ceiling's material.
            // Same trim at the south end as the floor gets, and for the same reason: room3-1's ceiling
            // slab sits at exactly this height and reaches 5.425. The north end needs none - room3-2N
            // is three storeys tall, so its ceiling is nowhere near this one.
            float shaftStart = RoomPitch / 2f - zMid;
            // 30mm short at the north end, the same as the block below it and for the same reason:
            // room3-2N's inner face is a panel plane, and a lid that reaches it shares that plane.
            float shaftEnd = run / 2f - 0.03f;
            Prim(PrimitiveType.Cube, "Shaft_Top", barrierRoot.transform,
                new Vector3(0f, GateHeight + CorridorShaftHeight + WallThickness / 2f,
                            (shaftStart + shaftEnd) / 2f),
                new Vector3(slabWidth, WallThickness, shaftEnd - shaftStart), CeilingMaterial());

            // AUTHORED FILLED, which is the pose it rests in - every plinth and lid in this project is
            // authored in its resting pose so the scene can be read without pressing Play.
            //
            // **AND WHAT IT LOOKS LIKE FILLED IS THE NORTH WALL.** The block is white, not the
            // near-black the void around it is, and its south end carries the wall's own panel grid on
            // the wall's own plane - one cell wide, two rows, inset half a groove, with the dark
            // backing plate behind them that every groove in this building has. Stand in room3-1 with
            // the pad untouched and there is no corridor: there is a wall, and it is the same wall as
            // the other three. The same specification the gates are built to, on a leaf that happens
            // to be twenty-two metres deep.
            GameObject slab = new GameObject("Fill");
            slab.transform.SetParent(barrierRoot.transform, false);
            slab.transform.localPosition = Vector3.zero;

            const float faceBackingDepth = 0.015f;
            // **NOTHING ON THIS BLOCK IS EXACTLY AS WIDE AS THE CORRIDOR, and that is what stopped the
            // flicker.** At exactly 1.75 its sides were the same plane as the corridor's wall panels,
            // and two coplanar faces fight for the same pixels from every angle. The clearances are
            // asymmetric on purpose: the body is 2mm clear each side and the face backing only 1mm, so
            // no slot is ever left uncovered wide enough to see the lit wall behind the groove - which
            // is what read as a thicker black border with a bright edge to it.
            // **20mm EACH SIDE, UP FROM 2mm, AND THE OLD NUMBER WAS THE FLICKER.** Two parallel faces
            // 2mm apart running twenty-three metres are within the depth buffer's precision at that
            // distance - at 20m with a 0.05 near plane a 24-bit buffer resolves about half a
            // millimetre, so 2mm is four times nothing and the pair shimmer, worse the more the camera
            // moves. It is not a coplanarity bug, which a hair of clearance fixes; it is a RESOLUTION
            // one, and the only fix is a gap the buffer can tell apart. 20mm reads as the mechanical
            // clearance a sliding block would have anyway.
            const float bodyClearance = 0.04f;    // 20mm each side
            // The face keeps its 1mm. It is 15mm deep and sits at the mouth, so it has no long
            // parallel run to shimmer down - and a wider gap here lets the lit wall show through the
            // groove as a bright edge.
            const float faceClearance = 0.002f;
            // Sunk below the floor rather than resting on it, for the same reason: a bottom face at
            // y=0 is the floor slab's top face. Buried, there is no shared plane and no gap either.
            const float sink = 0.02f;
            float faceZ = zStart - zMid;                       // the block's south end, in its own frame
            float grooveGap = GridLineThickness;

            // **THE FACE IS ONLY DRAWN WHILE THE BLOCK IS SHUT, and that is a flicker fix measured
            // rather than guessed** (2026-08-21, by `CycleThreeDiagnostics` scanning the OPENED pose -
            // the first scan that had ever looked at this cycle with anything moved).
            //
            // The block lifts by its own height, so this two-row grid arrives exactly on the wall's
            // own panels in rows 2 and 3 of the same cell: same plane, same width, overlapping. A
            // whole cell of coplanar panelling directly above the corridor mouth, in the one place a
            // player standing in room3-1 is looking.
            //
            // **It cannot be fixed by moving anything.** The shaft is exactly one block tall, so a
            // taller face rises out through the top of it; a face set back far enough to clear the
            // wall is a face visibly recessed while shut, which is the one thing it exists not to be.
            // What is left is the observation that this grid has no job once the block moves: it is
            // the wall while the wall is a wall, and after that it is a lid on a lift. Switched off at
            // the first millimetre of travel, so the change happens under the clunk.
            var faceRenderers = new System.Collections.Generic.List<Renderer>();

            for (int row = 0; row * GridCellHeight < GateHeight - 0.001f; row++)
            {
                float bottom = row * GridCellHeight;
                float top = Mathf.Min(bottom + GridCellHeight, GateHeight);
                // THE ONE THING THAT IS EXACTLY ON THE GRID. These are what room3-1 sees when the
                // corridor is shut, so they are the wall's own panels - cell width less one groove,
                // row height less one groove - and no clearance is applied to them.
                faceRenderers.Add(Prim(PrimitiveType.Cube, $"FacePanel_{row}", slab.transform,
                    new Vector3(0f, (bottom + top) / 2f, faceZ + GrooveDepth / 2f),
                    new Vector3(2f * halfWidth - grooveGap, top - bottom - grooveGap, GrooveDepth),
                    panelMat, removeCollider: true).GetComponent<Renderer>());
            }

            faceRenderers.Add(Prim(PrimitiveType.Cube, "FaceBacking", slab.transform,
                new Vector3(0f, (GateHeight - sink) / 2f, faceZ + GrooveDepth + faceBackingDepth / 2f),
                new Vector3(2f * halfWidth - faceClearance, GateHeight + sink, faceBackingDepth),
                grooveMat, removeCollider: true).GetComponent<Renderer>());

            // The mass itself, starting where the face finishes so nothing is coplanar with anything.
            //
            // **AND STOPPING 60mm SHORT AT THE NORTH END**, which is the same rule at the other end and
            // was also found by scanning the opened pose: raised, the block's top reaches into
            // `Shaft_Top` and the two shared their north face exactly.
            //
            // 60 rather than 30 because the lid stops 30 short as well, and shortening both by the
            // same amount moved the shared plane rather than removing it - which is the entire lesson
            // of this corridor, made once more in one line. Both ends land inside room3-2N's own wall
            // build-up, so nothing can see either gap while the block is down.
            float bodyStart = faceZ + GrooveDepth + faceBackingDepth;
            float bodyEnd = zEnd - zMid - 0.06f;
            Prim(PrimitiveType.Cube, "Body", slab.transform,
                new Vector3(0f, (GateHeight - sink) / 2f, (bodyStart + bodyEnd) / 2f),
                new Vector3(2f * halfWidth - bodyClearance, GateHeight + sink, bodyEnd - bodyStart),
                panelMat);

            // **THE CORRIDOR HAD NO REFLECTION PROBE, AND TWENTY-THREE METRES OF 0.85-SMOOTH WHITE
            // PANELLING IS ALMOST ENTIRELY WHAT IT REFLECTS** (2026-08-21; play reported the ceiling
            // "flickering, and worse the more I move", once the block was fully up).
            //
            // Every other space in the building has one and this one fell between two rooms: room3-1's
            // probe is a box around room3-1 and room3-2N's is a box around room3-2N, and the corridor
            // is in neither. **Box projection does not politely give up outside its box - it
            // EXTRAPOLATES**, so every surface in here was sampling room3-1's cubemap re-projected up
            // to twenty metres past where it was captured. That smears, and it swims as the camera
            // moves, which is what "flickers when I move" looks like on a surface with no texture of
            // its own to anchor it.
            //
            // It only shows once the block is up because until then there is no corridor to stand in -
            // which is also why no earlier scan of this cycle could have found it.
            //
            // Sized to the walk plus its shaft and centred on the run, so the box is the space rather
            // than a room next to it.
            BuildReflectionProbe(root.transform, "Room3_1_Corridor", zMid,
                                 sizeOverride: new Vector3(slabWidth, shaftTop, run),
                                 yCenter: shaftTop * 0.5f);

            AudioSource audio = MakeSource(barrierRoot.transform, "BarrierAudio",
                                           spatialBlend: 1f, volume: 0.95f);
            audio.transform.localPosition = new Vector3(0f, GateHeight / 2f, 0f);

            // BAKED INTO THE PROBES, and said out loud rather than left to luck. `MovesDuringPlay`
            // happens not to list `CrushingBarrier`, so this would be baked anyway - but its face IS
            // room3-1's north wall while it is down, and a wall missing from the reflections is the
            // mark that gives a concealed opening away (see WallWhileShut). Marking it means adding
            // `CrushingBarrier` to that list later cannot quietly undo this.
            slab.AddComponent<WallWhileShut>();

            CrushingBarrier barrier = barrierRoot.AddComponent<CrushingBarrier>();
            barrier.slab = slab.transform;
            barrier.openLocalOffset = new Vector3(0f, lift, 0f);
            barrier.pads = new[] { pad };
            barrier.audioSource = audio;
            // **SLOW UP, FAST DOWN, and the asymmetry is the whole feel of it.** 0.9s read as the
            // block being flicked aside; twenty-two metres of it should look like it weighs what it
            // weighs, and 2.6s is a lift rather than a flinch. The fall stays at 0.45 on purpose - it
            // is not closing, it is being let go of, and the thing you spent nine seconds earning
            // should take half a second to lose.
            barrier.openDuration = 2.6f;
            barrier.closeDuration = 0.45f;
            barrier.faceRenderers = faceRenderers.ToArray();
            barrier.moveClip = LoadClip(SfxDir, "sfx_door_open");
            // The heaviest thing in the SFX folder. There is no crunch in it and there does not need
            // to be - the room is a facility, and what it does to you is switch you off.
            barrier.crushClip = LoadClip(SfxDir, "sfx_power_down");
            // THE WHOLE CORRIDOR IS THE KILL VOLUME, because the whole corridor is the block. There is
            // no safe corner to stand in: the only safe place is out of it at one end or the other.
            barrier.killHalfExtents = new Vector3(halfWidth, GateHeight, run / 2f);

            return barrier;
        }

        private static FloorButton BuildFloorButton(Transform parent, Material mat, string name, Vector3 position)
        {
            // Root at unit scale so the activation volume is defined in clean world units;
            // the flattened cylinder mesh lives on an unscaled-collider visual child instead.
            GameObject root = new GameObject(name);
            root.transform.SetParent(parent, false);
            root.transform.localPosition = position;

            // Unity's cylinder is 1 unit across, so the X/Z scale is the diameter.
            const float padRadius = 0.35f;
            GameObject visual = Prim(PrimitiveType.Cylinder, "Visual", root.transform, Vector3.zero,
                new Vector3(padRadius * 2f, 0.03f, padRadius * 2f), mat, removeCollider: true);

            // No collider: FloorButton is a logical volume tested against the player's centre, not
            // a physics trigger. Its radius is derived from the visible pad here so the hit area
            // and the thing you can see can't drift apart - a hair proud of the edge, no more.
            FloorButton fb = root.AddComponent<FloorButton>();
            fb.activationRadius = padRadius + 0.05f;
            fb.buttonRenderer = visual.GetComponent<Renderer>();

            // **THE CLUNK IS WIRED HERE, WHERE THE PAD IS MADE, AND THAT IS THE POINT.** It used to be
            // wired in `BuildAudio` from a HAND-WRITTEN LIST of pads, and the comment beside that list
            // already recorded this exact bug happening to the doors: cycle 2's seven were left off
            // it and opened in silence for weeks, because a door that makes no sound looks exactly
            // like a door. Cycle 3's four pads were then left off the same list, and play reported it
            // as "the floor pad sound is gone".
            //
            // A list of every instance of a thing, maintained by hand, is a list that will be wrong.
            // The fix is not a better list - it is that there is no list: every pad in the game gets
            // its source and its clips from the one function that can make one.
            //
            // Positional and parented to the pad, which is the entire point of it. The door lamp only
            // reports the condition to someone looking at the door; the clunk reaches you wherever you
            // are, so hearing a ghost step onto a pad behind you is how the puzzle tells you the way
            // is open - and in room3-1, where four pads open four different walls, it is how you learn
            // which is which without turning round.
            fb.audioSource = MakeSource(root.transform, "FloorButtonAudio", 1f, 0.9f);
            fb.pressClip = LoadClip(SfxDir, "sfx_floor_button_press");
            fb.releaseClip = LoadClip(SfxDir, "sfx_floor_button_release");
            return fb;
        }

        // The slab, its pocket, and the lamp above it - everything both doors have in common. What
        // differs is only what unlocks them: Room1's is a button wired to a floor pad, Room2's is a
        // key lock fed by whatever a balloon gave up.
        // yaw turns the whole door, which is how a door in a SIDE wall costs nothing: the slab, the
        // pocket offset, the lamp and the slide are all measured in this root's local frame, so
        // rotating the root puts every one of them on a different wall with no second copy of the
        // measurements. 0 is a north wall, 90 the east, -90 the west.
        //
        // wallHalfExtent is how far the wall is from the room centre along the door's own normal -
        // RoomDepth/2 for the end walls this was written for, RoomWidth/2 for a side wall. It used to
        // be hardcoded, which is the only thing that made this Z-only.
        private static (Door door, DoorIndicator indicator, float wallInnerZ) BuildDoorShell(
            Transform parent, string name, float roomCenterZ, Material mat,
            float wallHalfExtent = RoomDepth / 2f, float yaw = 0f)
        {
            GameObject doorRoot = new GameObject(name);
            doorRoot.transform.SetParent(parent, false);
            // The root carries the room offset, so every measurement below stays in the same local
            // frame it was tuned in back when there was only one door. The offset is in the PARENT's
            // frame and the rotation is the root's own, so the two do not interfere.
            doorRoot.transform.localPosition = new Vector3(0f, 0f, roomCenterZ);
            doorRoot.transform.localRotation = Quaternion.Euler(0f, yaw, 0f);

            // The slab lives in the pocket between this room's wall and the next room's, so sliding
            // it sideways tucks it inside the wall build-up rather than dragging it across the
            // panelling. wallInnerZ is the room surface; the pocket starts WallDepth behind that.
            float wallInnerZ = wallHalfExtent;
            float slabZ = wallInnerZ + WallDepth + DoorPocketDepth / 2f;

            // The slab KEEPS its collider. The doorway is cut out of both walls' collision, so the
            // closed door is the only thing standing between the two rooms - built without one, the
            // player just walks through it and the puzzle is bypassable. Once open the slab sits
            // entirely behind the wall's own collision, so it never blocks the opening it cleared.
            GameObject panel = Prim(PrimitiveType.Cube, "DoorPanel", doorRoot.transform,
                new Vector3(0f, DoorHeight / 2f, slabZ),
                new Vector3(DoorWidth, DoorHeight, DoorThickness), mat);

            // A single lamp block split down the middle: red half on the left, green on the right,
            // only ever one of them lit. Both halves share one emissive material and are driven
            // apart by DoorIndicator through property blocks.
            Material lampMat = MakeEmissiveMaterial("IndicatorLamp", Color.white, 1f);
            const float lampWidth = 0.34f, lampHeight = 0.11f, lampDepth = 0.04f;
            float lampY = DoorHeight + 0.28f;
            // Proud of the wall surface by half its depth, so it sits on the panelling.
            float lampZ = wallInnerZ - lampDepth / 2f;

            GameObject lampRoot = new GameObject("DoorIndicator");
            lampRoot.transform.SetParent(doorRoot.transform, false);

            GameObject redHalf = Prim(PrimitiveType.Cube, "RedHalf", lampRoot.transform,
                new Vector3(-lampWidth / 4f, lampY, lampZ),
                new Vector3(lampWidth / 2f, lampHeight, lampDepth), lampMat, removeCollider: true);
            GameObject greenHalf = Prim(PrimitiveType.Cube, "GreenHalf", lampRoot.transform,
                new Vector3(lampWidth / 4f, lampY, lampZ),
                new Vector3(lampWidth / 2f, lampHeight, lampDepth), lampMat, removeCollider: true);

            Door door = doorRoot.AddComponent<Door>();
            // Slides right (+X as seen from inside the room) by its own width, so it clears the
            // opening exactly.
            door.openLocalOffset = new Vector3(DoorWidth, 0f, 0f);
            door.doorPanel = panel.transform;

            DoorIndicator indicator = lampRoot.AddComponent<DoorIndicator>();
            indicator.redHalf = redHalf.GetComponent<Renderer>();
            indicator.greenHalf = greenHalf.GetComponent<Renderer>();
            indicator.door = door;

            return (door, indicator, wallInnerZ);
        }

        // A powered door with no control of its own, held open while every pad handed to it is
        // held. Room1 passes one pad, Room3 two.
        //
        // There was a DoorButton on the wall beside Room1's until a play-test found nobody could
        // locate it - testers held the pad, walked to the door and expected it to open. See Door's
        // own note for why they were right and what removing the button buys. Note the wall beside
        // these doors is bare, which is part of the point: there is no affordance left to mislead.
        // yaw / wallHalfExtent pass straight through to `BuildDoorShell`, which has always taken them -
        // this only ever hid them. The ring needs both: its three corner doors sit in a WEST wall
        // (yaw 270) whose half-extent is `RoomWidth/2`, not the `RoomDepth/2` a north wall has.
        private static Door BuildPadDoor(Transform parent, string name, float roomCenterZ,
                                         FloorButton[] pads, Material mat,
                                         float yaw = 0f, float wallHalfExtent = RoomDepth / 2f)
        {
            (Door door, DoorIndicator indicator, float _) =
                BuildDoorShell(parent, name, roomCenterZ, mat, wallHalfExtent, yaw);

            // The lamp tracks the condition, not the door, so it goes green the moment the pads are
            // all held. With no button anywhere it is the room's only readout for that, which makes
            // it load-bearing rather than decorative - and in Room3 it is the only way to tell "one
            // of my past selves has arrived" from "both have".
            indicator.requiredFloorButtons = pads;
            door.requiredFloorButtons = pads;

            return door;
        }

        // A keyed door on the north wall of the room centred at roomCenterZ - no pad and no condition
        // to hold open, and deliberately not a button: the shape of the thing on the wall is the
        // puzzle telling you what it wants. Called three times now, once per coloured key, at three
        // different joins in the corridor - identical every time except the wall it ends up in and
        // the key it wants, which is the point: three doors that behave the same and differ only by
        // colour is what makes the colour readable as the rule.
        private static (Door, KeyLock) BuildKeyDoor(Transform parent, string name, float roomCenterZ, Material mat, KeySpec spec)
        {
            (Door door, DoorIndicator indicator, float wallInnerZ) =
                BuildDoorShell(parent, name, roomCenterZ, mat);
            return (door, AttachKeyLock(door, indicator, wallInnerZ, mat, spec));
        }

        // The lock beside a door, and the colour that says which key it wants.
        //
        // Factored out of BuildKeyDoor when Room2 grew from one keyed door to three. Every one of them
        // is the same fixture at a different colour, and the colour comes from the same KeySpec the key
        // itself is built from - so a lock cannot end up wanting a key that does not match the plate
        // beside it. That was the whole risk in this feature: the colours are the only instructions the
        // player gets, and two places deciding them independently is how they come apart.
        private static KeyLock AttachKeyLock(Door door, DoorIndicator indicator, float wallInnerZ,
                                             Material mat, KeySpec spec)
        {
            GameObject lockRoot = new GameObject("KeyLock");
            lockRoot.transform.SetParent(door.transform, false);
            lockRoot.transform.localPosition = new Vector3(-GridCellWidth, GridCellHeight * 1.5f, wallInnerZ - 0.06f);

            // Taller and narrower than the door button next door: across a room the two have to
            // read as different kinds of thing rather than as the same switch twice.
            //
            // IN THE KEY'S COLOUR, and this is the primary signal - it is the thing the player is
            // standing in front of with a key in hand. The band on the door says the same thing from
            // across the room; this says it at arm's length.
            Material plateMat = MakeColorMaterial(spec.materialName + "Plate", spec.display);
            SetSmoothness(plateMat, 0.45f);
            GameObject plate = Prim(PrimitiveType.Cube, "Visual", lockRoot.transform, Vector3.zero,
                new Vector3(0.2f, 0.3f, 0.09f), plateMat, removeCollider: true);

            // A plain keyhole, NOT the key silhouette this used to carry. The etching said what the
            // lock wanted, which was the right idea while nothing could ever be put in it - but the
            // key is now literally inserted here, and an inserted key sitting on top of an engraved
            // one reads as two keys. A keyhole says the same thing and leaves the socket empty.
            Material slotMat = MakeColorMaterial("KeySlot", new Color(0.06f, 0.06f, 0.07f));
            BuildKeyholeSlot(lockRoot.transform, new Vector3(0f, -0.03f, -0.047f), slotMat);

            // Where an accepted key ends up: SEATED, not parked on the surface. The key used to be
            // laid flat against the plate like a sticker, which is what "insert" meant when the
            // key was five primitives. It is a real key now and it goes IN.
            //
            // The plate is a 0.09-deep cube, so its face is at z -0.045. Putting the bow junction
            // exactly on that face leaves the bow standing proud where it can be seen and everything
            // from the shaft down inside the plate - and behind the plate is 0.015 of air and then
            // 0.125 of wall, so the 0.13 of shaft and bit has somewhere to be and is hidden the
            // whole way. Nothing is clipped and nothing reaches Room3 (the tip stops 0.10 short).
            const float plateFaceZ = -0.045f;
            float bowJunction = -KeyModelBowJunctionY * KeyScale;
            GameObject socket = new GameObject("KeySocket");
            socket.transform.SetParent(lockRoot.transform, false);
            // Y matches the keyhole seat below, so the shaft runs into the hole rather than past it.
            socket.transform.localPosition = new Vector3(0f, -0.03f, plateFaceZ - bowJunction);

            // **A WIDER REACH THAN THE LOCK IS BIG** (2026-08-29, by request: the E range was tight).
            //
            // 0.8 x 0.8 was about the size of the plate itself, so the player had to stand almost
            // exactly in front of it - and this is a fixture you walk up to holding a key, from
            // whatever angle the door happens to be on. The volume is what says "close enough to
            // touch"; being ON SCREEN is what stops it firing behind your back, and that half is
            // `PlayerLookup.InView` rather than a small box (CLAUDE.md 1.2). So the box can be
            // generous without the press becoming loose.
            BoxCollider trigger = lockRoot.AddComponent<BoxCollider>();
            trigger.isTrigger = true;
            trigger.size = new Vector3(2.2f, 2.4f, 2.0f);

            KeyLock keyLock = lockRoot.AddComponent<KeyLock>();
            keyLock.door = door;
            keyLock.keySocket = socket.transform;
            // How far back the key is presented before it slides in - exactly the length of key
            // that ends up buried, so it starts with its tip at the hole rather than at a distance
            // someone picked.
            keyLock.insertTravel = KeyInsertTravel;
            keyLock.lockRenderer = plate.GetComponent<Renderer>();
            // THE ONE THING THAT MAKES A DOOR PICKY. Both the player's gate (hand.Holding) and a
            // ghost's hand-over (ItemRegistry.FindSocket, keyed on AcceptedItemId) read this, so the
            // matching is enforced in one place for living and dead alike.
            keyLock.requiredItemId = spec.itemId;
            // The lamp over this door reports "you are carrying the key" the way the other one
            // reports "the pad is held".
            if (indicator != null) indicator.keyLock = keyLock;

            // NO BAND ON THE DOOR. There was one, in the same colour, on the reasoning that the plate is
            // 0.2m wide and the far side of the room is where the player decides which key to look for.
            // It went because the plate turned out to be enough on its own and the band was not free: a
            // whole slab wearing a colour reads as a coloured DOOR, which invites the idea that the door
            // itself is the thing that changes, where the lock is what actually differs. One coloured
            // fixture beside three identical doors says that more precisely than three coloured doors.
            return keyLock;
        }

        private static (GameObject, FirstPersonController, PlayerRecorder, CameraShaker, PlayerHand) BuildPlayer(Transform spawn, GhostInteractable[] ghostInteractables)
        {
            GameObject player = new GameObject("Player");
            player.tag = "Player";
            player.transform.position = spawn.position;
            player.transform.rotation = spawn.rotation;

            CharacterController cc = player.AddComponent<CharacterController>();
            cc.height = 1.8f;
            cc.radius = 0.3f;
            cc.center = new Vector3(0f, 0.9f, 0f);
            // **RAISED FROM UNITY'S 0.3 SO CYCLE 3'S STAIRS ARE WALKED UP, NOT JUMPED** (2026-08-21).
            //
            // The first attempt at making a grid-row step climbable was a bigger jump - 6 to 7.9,
            // 0.90m to 1.56m - and play called it awkward, which it is: the player floats, and every
            // room in the game inherits it. This does the opposite. The step comes down to half a row
            // (0.651m to its top) and the controller simply walks up it.
            //
            // **AND IT CANNOT REACH ANYTHING A JUMP COULD NOT ALREADY.** 0.72 is below the 0.90m the
            // jump has always cleared, so nothing in cycles 1 and 2 becomes reachable that was not
            // reachable before - which is exactly what the 1.56m jump could not promise. The two
            // existing things that lean on this value both still hold: the chess board is thinner than
            // this and is still walked over, and balloons are excluded from the controller entirely
            // (see `excludeLayers` below) so nobody rides one to the ceiling.
            cc.stepOffset = PlayerStepOffset;

            // ~~THE PLAYER CAST A SHADOW~~ REMOVED 2026-08-17, by request.
            //
            // It was the ghosts' own body model parented to the player with every renderer set to
            // `ShadowCastingMode.ShadowsOnly` - never drawn, so it could not be seen from inside or
            // clip the near plane, and it put the same silhouette on the floor that a past self does.
            //
            // Recorded rather than just deleted because the idea is an obvious one to have again, and
            // because the part that is NOT obvious is what it costs: nothing in this building casts a
            // shadow unless a light is told to, and only Room1's fixtures were. Restoring it means
            // restoring `castShadows: true` across the rooms as well, which is a shadow map per room.

            // The controller does not collide with balloons at all. They are still solid to each
            // other, to the floor and to the walls - this excludes exactly one pair. Without it the
            // player can stand on one, and the moment a balloon under a standing player takes any
            // upward push at all, stepOffset walks them up onto it and they ride it to the ceiling.
            // FirstPersonController pushes them from an overlap query instead of by contact.
            int balloonLayer = EnsureLayer(BalloonLayerName);
            cc.excludeLayers = 1 << balloonLayer;

            // A rig sits between the player and the camera purely so CameraShaker has somewhere to
            // write. FirstPersonController rewrites the camera's own localPosition and euler angles
            // every frame, so a shake applied to the camera itself would be wiped instantly.
            GameObject rigGO = new GameObject("CameraRig");
            rigGO.transform.SetParent(player.transform, false);
            CameraShaker shaker = rigGO.AddComponent<CameraShaker>();

            GameObject camGO = new GameObject("PlayerCamera");
            camGO.transform.SetParent(rigGO.transform, false);
            camGO.transform.localPosition = new Vector3(0f, 1.6f, 0f);
            Camera cam = camGO.AddComponent<Camera>();
            camGO.AddComponent<AudioListener>();
            cam.tag = "MainCamera";

            // **THE PLAYER SEES THEIR OWN BODY AND NOT THE ONE THE MIRRORS SEE.** Two bodies, two
            // layers, and each camera picks one - see `BuildPlayerBody`. This one takes the headless
            // one, because it is standing inside the other one's skull.
            BuildPlayerBody(player.transform);
            cam.cullingMask &= ~(1 << EnsureLayer(PlayerBodyWorldLayer));

            // Unity's default near plane of 0.3 is the same as the controller's radius, and that
            // does not work: what pokes through a wall is the near plane's CORNER, not its centre,
            // and at fov 60 that corner reaches 0.463m (0.532m ultrawide) while the capsule stops
            // the camera 0.3m away - less once skinWidth lets the wall penetrate the capsule. The
            // whole wall build-up is only WallDepth (0.125m) thick, so the frustum clipped clean
            // through it: stand against a wall or the door, look sideways, and you saw the far side
            // of the room. At 0.05 the corner reaches 0.077m, comfortably inside the standoff.
            cam.nearClipPlane = 0.05f;
            // Pulled in from the default 1000 to keep depth precision concentrated where the scene
            // actually is (~22m across both rooms). The panels are 0.025m proud of their backing,
            // and SSAO resolves those grooves off the depth buffer.
            cam.farClipPlane = 100f;

            // Opt the camera into the volume stack - URP cameras ignore post-processing otherwise.
            UniversalAdditionalCameraData camData = camGO.AddComponent<UniversalAdditionalCameraData>();
            camData.renderPostProcessing = true;
            camData.antialiasing = AntialiasingMode.SubpixelMorphologicalAntiAliasing;

            FirstPersonController fpc = player.AddComponent<FirstPersonController>();
            fpc.playerCamera = cam;
            fpc.pushLayers = 1 << balloonLayer;
            // 2D: these are the player's own feet, not something across the room. Fired off the same
            // step phase the head bob is drawn from, so the sound and the movement are one event.
            fpc.footstepSource = MakeSource(player.transform, "FootstepAudio", 0f, 1f);
            // Three, cycled by step number rather than picked at random - a random order re-uses the
            // same clip twice in a row often enough to be heard doing it.
            fpc.footstepClips = new[]
            {
                LoadClip(SfxDir, "sfx_footstep_1"),
                LoadClip(SfxDir, "sfx_footstep_2"),
                LoadClip(SfxDir, "sfx_footstep_3"),
            };
            // AND THE SAME THREE FOR WATER, swapped in while the player is in room2-5's pool. Generated
            // rather than sourced, like the chop - see MakeWadeClip for why a splash clip and a
            // footstep clip are both the wrong sound for this.
            //
            // ON THE PLAYER, so it is built by `Build` and NOT by `RebuildCycleTwo`: a cycle rebuilt on
            // its own gets the pool without the sound of walking in it, and the fallback in `Footstep`
            // is what makes that quiet rather than silent. Same standing hazard as the door audio.
            fpc.wadeClips = new[]
            {
                MakeWadeClip("sfx_wade_1", 20260819),
                MakeWadeClip("sfx_wade_2", 20260820),
                MakeWadeClip("sfx_wade_3", 20260821),
            };

            PlayerRecorder recorder = player.AddComponent<PlayerRecorder>();
            recorder.interactables = ghostInteractables;

            // Parented under the camera rather than the player, so a carried item rides the view -
            // including through the wake-up, where WakeUpSequence poses the camera directly and
            // anything hung off the body would swing independently of where you are looking.
            GameObject handAnchor = new GameObject("HandAnchor");
            handAnchor.transform.SetParent(camGO.transform, false);

            PlayerHand hand = player.AddComponent<PlayerHand>();
            hand.holdAnchor = handAnchor.transform;
            // HOW FAR IN FRONT A PUT-DOWN LANDS, and it is written from here into BOTH the player's
            // hand and the ghost prefab (see BuildGhostPrefab). It was a component default on each
            // and they were not the same act: the player threw the object a metre forward and a past
            // self let it go at its own feet, which room3-2N's ledges turned into "the player drops
            // it off the deck and every ghost afterwards leaves it on the lip".
            hand.dropAhead = DropAheadDistance;
            // The same eye the controller uses, so the visibility walk-back inside `PutDownPoint`
            // asks from the same height whether it is the player's camera or a past self's head.
            hand.eyeHeight = fpc.standingEyeHeight;
            // A put-down stops at a wall rather than going through it. Balloons excluded for the
            // same reason the controller excludes them - an object put down in Room2 would otherwise
            // be stopped short by whatever balloon happened to be drifting past.
            hand.dropBlockers = ~(1 << balloonLayer);

            // Stops a held object reaching through a wall the player is standing against. Balloons
            // are excluded from the cast for the same reason the controller excludes them: the item
            // would otherwise shy away from every balloon in Room2 as the player walked through them.
            HeldItemClearance clearance = handAnchor.AddComponent<HeldItemClearance>();
            clearance.anchor = handAnchor.transform;
            clearance.eye = camGO.transform;
            clearance.hand = hand;
            clearance.ignoreRoot = player.transform;
            clearance.blockers = ~(1 << balloonLayer);

            // ~~A FIRST-PERSON HAND UNDER THE HELD OBJECT~~ **BUILT AND REMOVED 2026-08-24, after
            // play, by request: it hurt the game more than it helped.**
            //
            // It was DavidFischer's rigged FPS hands on `PlayerBodyView`, parented here so
            // `HeldItemClearance` pulled it in with whatever it was holding, closing per object from
            // the object's own thinnest dimension. None of that was the problem - it worked. The
            // problem is what a hand DOES to a first-person game: it fills the corner of the frame
            // permanently, and this is a game about looking at rooms.
            //
            // **The reasoning that argued FOR it still stands and is why this note is here**: held
            // objects are their true size, so a metre of glass genuinely fills the view, and a hand
            // is what explains that rather than leaving it a prop stuck to the camera. If it ever
            // comes back, `git log` has the whole of it - the measured-not-written rig orientation,
            // the 100x bone-space trap, and the per-object closure. What it does NOT solve is the
            // objection above.
            // Takes and surrenders go into the same timeline the frames do, so a past self can
            // repeat them. Only items flagged ghostCarryable are written.
            hand.recorder = recorder;

            BalloonTool tool = player.AddComponent<BalloonTool>();
            tool.playerCamera = cam;
            tool.hand = hand;
            tool.recorder = recorder;
            // 2D: this is the player's own arm, not something across the room. The clip slot is
            // left empty - there is no swing sound generated yet, and borrowing the bed's sheet
            // rustle for it would be worse than silence. BalloonTool guards on null.
            tool.audioSource = MakeSource(player.transform, "ToolAudio", 0f, 0.5f);

            return (player, fpc, recorder, shaker, hand);
        }

        private const string GhostModelPath = "Assets/ArtAssets/Smooth_Male_Casual@Walking.fbx";

        // **TWO LAYERS, because a first-person body and a body in a mirror are not the same object.**
        // A renderer cannot be told to draw differently per camera, so there are two of them and every
        // camera in the building is told which one it may see:
        //
        //     PlayerBodyView    headless. ONLY the player's own camera renders it.
        //     PlayerBodyWorld   whole. Everything EXCEPT the player's camera renders it.
        //
        // The head has to go from the first one because the camera is inside it, and a head rendered
        // from the inside is a wall of skull across the top of the frame.
        private const string PlayerBodyViewLayer = "PlayerBodyView";
        private const string PlayerBodyWorldLayer = "PlayerBodyWorld";
        // **AND A THIRD, WHICH IS ONLY EVER A SHADOW** (2026-08-22). The player cast none in their own
        // view and the cause was not the lights: a camera's culling mask culls SHADOW CASTERS too, so
        // excluding `PlayerBodyWorld` from the player's camera removed the body's shadow along with the
        // body. The view body cannot supply it either - it is headless and armless, and a headless
        // armless shadow on the floor is worse than no shadow at all.
        //
        // So a whole third instance, drawn by nobody (`ShadowsOnly`) and rendered by the player's
        // camera alone; the mirrors and the CCTV feeds exclude it and take the world body's shadow
        // instead, or a player standing in front of a mirror would cast two. Each of the three now
        // does exactly one job, which is the same argument that built the first two.
        private const string PlayerBodyShadowLayer = "PlayerBodyShadow";
        // The same 0.377 the ghosts use, and for the same measured reason: the rig stands 4.739m at
        // scale 1, so this puts it at 1.75m - a hair under the 1.8m controller and right for the 1.6m
        // eye it is seen from.
        private const float PlayerBodyScale = 0.377f;


        // ~~`PlayerBodyViewSetback` and `FirstPersonHiddenBones`~~ **BOTH GONE 2026-08-23 with the
        // first-person body they served.** The setback pushed that instance 20cm behind the player so
        // the camera was not inside its chest; the bone list hid its head, its arms and finally its
        // whole upper body. Neither has a subject any more - see `BuildPlayerBody`. `git log` has the
        // measurements if the body ever comes back.

        // The ghosts are real people now - a rigged, animated, opaque figure rather than the six
        // faint primitives that came before. That is a deliberate change of what a ghost IS: it
        // used to read as an afterimage of you, and it now reads as a person who was here. The
        // reference film shows past selves as people, so this is the faithful reading; the cost is
        // that six of them in a room is a crowd rather than a memory.
        //
        // The model is Quaternius' Smooth Male Casual (CC0), 7,932 triangles with twelve clips
        // baked in. Its own materials are already flat-colour URP/Lit with no textures, which is
        // exactly what this room wants - the walls carry the detail, the figures do not.
        // Transform.Find only walks one level and takes a path; a rig's bone can be at any depth
        // under any number of exporter-invented parents, so this searches by name instead.
        private static Transform FindDeep(Transform root, string name)
        {
            foreach (Transform t in root.GetComponentsInChildren<Transform>(true))
                if (t.name == name) return t;
            return null;
        }

        // A place on a ghost's skeleton that a carried object can be parented to, in METRES.
        //
        // TWO OBJECTS, AND THE PAIR IS THE WHOLE POINT. This FBX has a `HumanArmature` node at scale
        // 100 inside a body scaled to 0.377, so every bone's lossyScale is 37.7: parent a 0.2m key
        // to one and you get a 7.5m key, flung metres away because its local offset is multiplied by
        // the same number. The OUTER node cancels that and must stay at localPosition zero - an
        // offset written there would be in the 37.7x space too, so 3cm arrives as 1.13m. The offset
        // therefore goes on the CHILD, where the scale is already 1 and centimetres mean centimetres.
        //
        // Factored out when the ghost grew a second one of these. Getting it wrong is not a subtle
        // failure - it is an object the size of a room - but it is an easy one to get wrong twice,
        // so the check is built in: the returned anchor's lossyScale is asserted at 1.
        private static Transform MakeGhostAnchor(Transform rigRoot, Transform fallback, string boneName,
                                                 string label, Vector3 localOffset)
        {
            Transform bone = FindDeep(rigRoot, boneName);
            if (bone == null)
                Debug.LogWarning($"[SceneBuilder] ghost rig has no {boneName} - {label} items will ride the root");

            GameObject scaleNode = new GameObject(label + "Scale");
            scaleNode.transform.SetParent(bone != null ? bone : fallback, false);
            scaleNode.transform.localPosition = Vector3.zero;

            Vector3 rigScale = scaleNode.transform.lossyScale;
            scaleNode.transform.localScale = new Vector3(
                Mathf.Approximately(rigScale.x, 0f) ? 1f : 1f / rigScale.x,
                Mathf.Approximately(rigScale.y, 0f) ? 1f : 1f / rigScale.y,
                Mathf.Approximately(rigScale.z, 0f) ? 1f : 1f / rigScale.z);

            GameObject anchor = new GameObject(label + "Anchor");
            anchor.transform.SetParent(scaleNode.transform, false);
            anchor.transform.localPosition = localOffset;

            Debug.Log($"[SceneBuilder] Ghost {label} anchor on {boneName}: rig scale {rigScale.x:0.###} -> "
                + $"{anchor.transform.lossyScale.x:0.###} (expects 1)");

            return anchor.transform;
        }

        // THE PLAYER'S BODY, twice. See `PlayerBody` for why twice.
        //
        // Parented to the player ROOT rather than to the camera rig, so it takes the yaw and not the
        // pitch: a body that tipped forward when you looked at your feet would be a body doing a
        // somersault every time you checked where you were standing. The controller's origin is at
        // the feet (`cc.center` is half its height), so this sits at local zero.
        private static void BuildPlayerBody(Transform player)
        {
            GameObject model = AssetDatabase.LoadAssetAtPath<GameObject>(GhostModelPath);
            if (model == null)
            {
                Debug.LogError($"[SceneBuilder] Player body model missing at {GhostModelPath}");
                return;
            }

            // **THE MODEL'S OWN MATERIALS, and that is the fix rather than the shortcut.** It ships
            // with six of them - Shirt, Skin, Pants, Eyes, Socks, Hair - already on
            // `Universal Render Pipeline/Lit`, which the dump says and nobody had asked. They were
            // being overwritten with one flat grey, so the player was a slab and play said so.
            //
            // Not the GHOSTS' materials either: `GhostMaterials` is the afterimage shader, a hollow
            // rim that exists to say "this is a recording". The two now differ the way they should -
            // the living player is a person and a past self is a smear of one - out of one model.
            // ~~A THIRD INSTANCE, `PlayerBody_View`~~ **GONE 2026-08-23, after play, by request: look
            // down and there is nothing there.**
            //
            // It was the headless armless one the player's own camera drew, and the decision to drop
            // it is narrower than it looks. Of the three reasons a body was added at all, only ONE
            // was ever about that instance - "look down and see yourself". The other two, being on the
            // CCTV and being in a mirror, are the WORLD body's job and are untouched.
            //
            // And the remaining reason is thin in this game specifically: cycle 3 is a mirror puzzle,
            // so there is a place built for seeing yourself properly, and a glance at your own shins
            // is the worse version of that moment. Against it: 7,932 untextured triangles are at their
            // closest to the camera here of anywhere in the building, and the legs are scrubbed by
            // travel, so they do not match strafing, jumping or falling. Legs that disagree with the
            // movement read worse than no legs. Same argument the arms lost on 2026-08-22.
            //
            // **What went with it**: `FirstPersonHiddenBones`, `PlayerBody.hideBones`,
            // `PlayerBody.onlyWhileDriving` and `PlayerBodyViewSetback`. All four existed only to make
            // that instance tolerable. `git log` has them if it ever comes back.
            MakePlayerBody(player, "PlayerBody_World", model,
                           EnsureLayer(PlayerBodyWorldLayer),
                           shadows: UnityEngine.Rendering.ShadowCastingMode.On);
            // ~~`PlayerBody_Shadow`~~ **GONE 2026-08-24, after play, by request: the quality was not
            // there.** The player casts nothing in their own view.
            //
            // It was a second copy of the body drawn ShadowsOnly, and it existed for a reason that
            // still holds mechanically: a culling mask culls shadow CASTERS too, so masking the world
            // body out of the player's camera takes its shadow with it, and something else has to put
            // one back. Nothing does now.
            //
            // **Three shapes were tried in one day and the objection outlived all of them**, which is
            // the useful part of this note:
            //
            //   the body, one CORNER fixture casting - read as detached, a long shadow off to one side
            //   the body, all four casting     - "like a skeleton": four silhouettes, eight limbs
            //   a plain capsule                - fixed the limbs by deleting them; not a person
            //   the body, nearest fixture only - short, overhead, correctly shaped, still not good
            //
            // So the remaining suspects are not the caster and not the silhouette. They are that these
            // are POINT lights standing in for 1.4m emissive panels - a real area source gives a soft
            // penumbra where a point gives a hard edge - and URP's default shadow bias, which
            // peter-pans the contact point away from the feet. **Anyone restoring this should fix one
            // of those first rather than trying a fifth shape.**
            //
            // What did NOT go with it: the ceiling fixtures still cast, so the ROOMS still have
            // shadows - see `ShadowBudget`. This removes the player from that, nothing else. And
            // `PlayerBody_World` is untouched, so a mirror and the CCTV still show a whole person.
        }

        private static void MakePlayerBody(Transform player, string name, GameObject model,
                                           int layer,
                                           UnityEngine.Rendering.ShadowCastingMode shadows)
        {
            GameObject body = (GameObject)PrefabUtility.InstantiatePrefab(model);
            body.name = name;
            body.transform.SetParent(player, false);
            // Exactly where the player is. Both remaining instances want the true position - the
            // world body because mirrors and CCTV must agree with the room, the shadow body because
            // it is now the only thing telling the player where their own feet are.
            body.transform.localPosition = Vector3.zero;
            body.transform.localRotation = Quaternion.identity;
            body.transform.localScale = Vector3.one * PlayerBodyScale;

            // No colliders, for the reason the ghosts have none: the player already has a capsule, and
            // a second one inside it would fight the first. It also keeps the body out of every
            // raycast in the building - `PlayerLookup.Occluded` and `LaserBeam` both filter the Player
            // tag, but not having a collider at all is cheaper than being filtered.
            foreach (Collider c in body.GetComponentsInChildren<Collider>(true))
                Object.DestroyImmediate(c);

            foreach (Transform t in body.GetComponentsInChildren<Transform>(true))
                t.gameObject.layer = layer;

            SkinnedMeshRenderer skin = body.GetComponentInChildren<SkinnedMeshRenderer>(true);
            if (skin != null)
            {
                skin.sharedMaterials = PlayerBodyMaterials(skin.sharedMaterials, name);
                // ONE CASTER PER CAMERA, never two: the world body casts for the mirrors and the
                // feeds, the shadow body casts for the player, and the view body casts for nobody.
                skin.shadowCastingMode = shadows;
                // **THE VIEW BODY DOES NOT RECEIVE**, and that is not laziness. The shadow body stands
                // in the same place wearing the same pose, so a receiving view body would be lit
                // through its own coincident shadow caster - depth-fighting on every surface of your
                // own legs, which is the classic way this arrangement produces acne.
                skin.receiveShadows = shadows == UnityEngine.Rendering.ShadowCastingMode.On;
                // The bounds Unity computes for a skinned mesh are the bind pose's, and this rig's are
                // wrong enough that it vanishes when its origin leaves the frustum.
                skin.updateWhenOffscreen = true;
            }

            Animator animator = body.GetComponent<Animator>();
            if (animator == null) animator = body.AddComponent<Animator>();
            animator.runtimeAnimatorController = GhostAnimatorController();
            animator.applyRootMotion = false;

            PlayerBody driver = body.AddComponent<PlayerBody>();
            driver.animator = animator;
        }

        // ENROLS EVERY SHADOW-CASTING CEILING FIXTURE IN ONE BUDGET, and switches them all off.
        //
        // **THE ENROLMENT TEST IS "THE BUILDER GAVE IT SHADOWS"** - `BuildCeilingLights` sets
        // `LightShadows.Soft` on the fixtures of any room built with `castShadows`, and this collects
        // exactly those. No name tag and no second list to keep in step: a room that opts out never
        // had shadows set, so it is never found here.
        //
        // Then every one of them goes to `None`, because from here on WHICH of them casts is
        // `ShadowBudget`'s decision and there must be exactly one owner of it (CLAUDE.md §2). It also
        // means the scene is saved, and the reflection probes are baked, with nothing casting - which
        // is what the bake did anyway when only one light in the building cast, and what stops a
        // 360-degree cubemap render asking for thirty shadow maps.
        //
        // **ONE BUDGET PER CYCLE, ON THE CYCLE'S OWN GameObject** - which is what makes it survive
        // being saved. The cycles are split into scenes of their own further down `Build`, and a
        // single budget sitting in the core scene held references to lights that walked off into
        // `Cycle2` and `Cycle3`: Unity refuses to serialise a cross-scene reference, so two thirds of
        // the list would have arrived at runtime as nulls. Hung off the `Cycle`, the component and
        // every light it names are in one subtree and move together. It is also the right owner on
        // its own merits (CLAUDE.md §2): a cycle owns its rooms, and only the loaded one runs.
        //
        // **OWNERSHIP IS TESTED AGAINST `worldRoot`, NOT BY WALKING UP TO A `Cycle`.** This runs
        // before the bake, and at that point a cycle's rooms are still under its `worldRoot` with
        // that root NOT yet parented to the `Cycle` itself - the split loop does that later. Asking
        // `GetComponentInParent<Cycle>` here finds nothing at all, and the first version of this
        // reported all sixty-four fixtures as orphans and switched them off for good.
        //
        // A scene walk rather than a line in every room's builder, for the same reason
        // `AddFallingToEveryCarryable` is one: a new room gets this without its author knowing.
        private static void WireShadowBudget()
        {
            var byCycle = new System.Collections.Generic.Dictionary<
                Cycle, System.Collections.Generic.List<Light>>();
            int orphans = 0;

            Cycle[] cycles = Object.FindObjectsByType<Cycle>(FindObjectsInactive.Include,
                                                             FindObjectsSortMode.None);

            foreach (Light light in Object.FindObjectsByType<Light>(FindObjectsInactive.Include,
                                                                    FindObjectsSortMode.None))
            {
                if (light.shadows == LightShadows.None) continue;

                // **THE CALIBRATION ROOM IS NOT A CYCLE'S BUSINESS, and enrolling it here was a
                // silent bug.** This runs long before `ExtractCalibrationRoom` lifts that room into
                // the core scene, so its four fixtures were being written into CYCLE 1's budget - and
                // then the lift put them in a different scene from the component holding them. Unity
                // nulls a serialised reference across a scene boundary, so those four were never
                // switched by anything and kept the `Soft` the builder gave them: four permanent
                // casters nobody was counting. With four more in the player's own room that is eight
                // maps wanting a four-map atlas, which is the one thing `ConfigureUrpAsset` warns
                // about. `cross-scene-report.txt` had named all four.
                //
                // They get their own budget instead, in `ExtractCalibrationRoom`, where they end up.
                if (LiftedWithCalibrationRoom(light.transform)) continue;

                light.shadows = LightShadows.None;

                Cycle owner = null;
                foreach (Cycle c in cycles)
                {
                    Transform root = c.worldRoot != null ? c.worldRoot : c.transform;
                    if (light.transform.IsChildOf(root)) { owner = c; break; }
                }

                if (owner == null) { orphans++; continue; }

                if (!byCycle.TryGetValue(owner, out var list))
                    byCycle[owner] = list = new System.Collections.Generic.List<Light>();
                list.Add(light);
            }

            if (orphans > 0)
                Debug.LogWarning($"[SceneBuilder] ShadowBudget: {orphans} shadow-casting light(s) are "
                               + "under no Cycle, so nothing will ever switch them on. They have been "
                               + "left dark rather than left casting.");

            if (byCycle.Count == 0)
            {
                Debug.LogWarning("[SceneBuilder] ShadowBudget: no fixture is set to cast, so nothing "
                               + "in this game will ever have a shadow. Check `castShadows`.");
                return;
            }

            foreach (var pair in byCycle)
            {
                ShadowBudget budget = pair.Key.gameObject.AddComponent<ShadowBudget>();
                budget.fixtures = pair.Value.ToArray();

                // **FOUR CASTERS, AT 2048 EACH IN A 4096 ATLAS** (2026-08-25, by request). Authored
                // here rather than left to the component's own default, which is what CLAUDE.md §2
                // asks and which this had been quietly relying on.
                //
                // **ONE caster was tried for a day and play rejected it**, and the reason is worth
                // keeping: the single caster is whichever fixture is NEAREST THE PLAYER, so walking
                // across a room swaps it and every shadow in the room jumps to a new angle. `range`
                // is sized (10m) precisely so the casting SET does not change while you are inside a
                // room - and that guarantee only holds when the whole room's ceiling is in the set.
                // With one, the set changes constantly and the guarantee is worthless.
                //
                // Four also restores what a ceiling of four panels actually does: overlapping soft
                // shadows, dark where all four meet under an object and faint where only one reaches.
                budget.maxCasters = 4;

                Debug.Log($"[SceneBuilder] ShadowBudget on '{pair.Key.name}': {pair.Value.Count} "
                        + $"eligible ceiling fixtures, at most {budget.maxCasters} casting within "
                        + $"{budget.range}m of the player.");
            }
        }

        // WHAT THE PLAYER IS WEARING, one material per slot, MATCHED BY THE SLOT'S OWN NAME.
        //
        // The model ships six - Shirt, Skin, Pants, Eyes, Socks, Hair - already on URP/Lit, and they
        // are replaced rather than tuned in place because they are sub-assets of the FBX: editing
        // those would edit the asset, and CLAUDE.md §2 puts values in `SceneBuilder` rather than in
        // the thing being valued.
        //
        // **THIS IS BELIEVABLE, NOT PHOTOREAL, AND THAT CEILING IS THE MODEL'S.** 7,932 triangles, no
        // UVs and no textures at all - the dump says so - so every surface is one flat colour and
        // there is no skin, no fabric weave and no wrinkle to be had at any setting. What CAN be done
        // is stop it reading as a mannequin: muted clothing rather than saturated, a plausible skin
        // tone, cloth at low smoothness so it is not plastic, and wet-looking eyes.
        //
        // Anything past that is a different asset, not a different number.
        private static Material[] PlayerBodyMaterials(Material[] source, string bodyName)
        {
            var result = new Material[source.Length];
            for (int i = 0; i < source.Length; i++)
            {
                string slot = source[i] != null ? source[i].name : "";
                Material made;

                if (slot.StartsWith("Skin")) made = BodyMaterial("PlayerSkin", 0.80f, 0.62f, 0.51f, 0.25f);
                else if (slot.StartsWith("Hair")) made = BodyMaterial("PlayerHair", 0.15f, 0.12f, 0.10f, 0.30f);
                else if (slot.StartsWith("Shirt")) made = BodyMaterial("PlayerShirt", 0.33f, 0.37f, 0.44f, 0.14f);
                else if (slot.StartsWith("Pants")) made = BodyMaterial("PlayerPants", 0.20f, 0.23f, 0.30f, 0.12f);
                else if (slot.StartsWith("Socks")) made = BodyMaterial("PlayerSocks", 0.74f, 0.74f, 0.71f, 0.10f);
                else if (slot.StartsWith("Eyes")) made = BodyMaterial("PlayerEyes", 0.09f, 0.09f, 0.11f, 0.80f);
                else
                {
                    Debug.LogWarning($"[SceneBuilder] {bodyName}: unrecognised material slot '{slot}' - "
                                   + "left as imported. Run Iteration Room/Dump Furniture Models.");
                    made = source[i];
                }

                result[i] = made;
            }
            return result;
        }

        private static Material BodyMaterial(string name, float r, float g, float b, float smoothness)
        {
            Material m = MakeColorMaterial(name, new Color(r, g, b));
            SetSmoothness(m, smoothness);
            return m;
        }


        private static GhostReplayer BuildGhostPrefab()
        {
            string prefabPath = $"{PrefabsDir}/Ghost.prefab";

            GameObject model = AssetDatabase.LoadAssetAtPath<GameObject>(GhostModelPath);
            if (model == null)
            {
                Debug.LogError($"[SceneBuilder] Ghost model missing at {GhostModelPath}");
                return null;
            }

            GameObject ghost = new GameObject("Ghost");
            GameObject body = (GameObject)PrefabUtility.InstantiatePrefab(model);
            body.transform.SetParent(ghost.transform, false);
            body.name = "Body";

            // Measured, not guessed: the rig stands 4.739m at scale 1 (bone extents, verified in
            // the editor), so 0.377 puts it at 1.75m - a hair under the player's 1.8m controller
            // and right for the 1.6m eye height they are seen from.
            body.transform.localScale = Vector3.one * 0.377f;

            // Colliders would break the game outright: a ghost is something you walk THROUGH, and
            // one that pushed the player would change the recording being made against it.
            foreach (Collider c in body.GetComponentsInChildren<Collider>(true))
                Object.DestroyImmediate(c);

            SkinnedMeshRenderer skin = body.GetComponentInChildren<SkinnedMeshRenderer>(true);
            if (skin != null)
            {
                skin.sharedMaterials = GhostMaterials(skin.sharedMaterials);
                // Shadows are OFF again, and that reverses a call made when the ghosts were opaque
                // ("a person with no shadow reads as a bug"). It does not survive the figures
                // becoming afterimages: a hollow rim that throws a solid, fully detailed shadow on
                // the floor puts every piece of detail this shader exists to remove straight back
                // into the room, in the one place the eye is guaranteed to read it as real.
                skin.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
                skin.receiveShadows = false;
                // The bounds Unity computes for a skinned mesh are the bind pose's, and this rig's
                // are wrong enough that ghosts vanish when their origin leaves the frustum.
                skin.updateWhenOffscreen = true;
            }

            Animator animator = body.GetComponent<Animator>();
            if (animator == null) animator = body.AddComponent<Animator>();
            animator.runtimeAnimatorController = GhostAnimatorController();
            animator.applyRootMotion = false;

            GhostReplayer replayer = ghost.AddComponent<GhostReplayer>();
            replayer.animator = animator;
            // A ghost pops only while holding the tool, the same test BalloonTool applies to the
            // player. Same constant on both sides so the two gates cannot drift apart.
            replayer.popToolItemId = ToolItemId;
            // The player's own put-down distance. Same constant on both sides so the two cannot
            // drift apart - the same reasoning `popToolItemId` above is written from here under.
            replayer.dropAhead = DropAheadDistance;

            // Where the EQUIPPED item rides. Hung off the rig's right hand so it swings with the arm
            // through the walk cycle - parented to the ghost's root it would slide along beside the
            // figure, which reads as an object being dragged rather than carried.
            //
            // Metres, in the hand's own frame. Just past the wrist so the key sits in the fist
            // rather than inside it. This is the one place to tune a ghost's grip.
            replayer.carryAnchor = MakeGhostAnchor(body.transform, ghost.transform, "MiddleHand.R",
                                                   "Carry", new Vector3(0f, -0.03f, 0.04f));

            // AND WHERE EVERYTHING ELSE IT CARRIES RIDES - a belt line across the hips.
            //
            // A ghost used to hide every item but the equipped one, which made those items
            // UNTAKEABLE as well as unseen, because CarryableItem.IsAvailable reads `visible`. A
            // past self holding pin and key with the pin out put the key somewhere the living player
            // could neither see nor reach. Wearing them is what makes "who has the key" answerable
            // and the answer reachable, and it needs no HUD to say it.
            //
            // The HIPS rather than the hand, because a stowed object should not swing with the arm;
            // rather than the ghost root, because at the root it slides beside the figure. The
            // 0.09 forward clears the body so an object sits ON the belt rather than in the pelvis,
            // and 0.13 apart is enough that two 0.22-scaled escape objects do not intersect.
            replayer.stowAnchor = MakeGhostAnchor(body.transform, ghost.transform, "Hips",
                                                  "Stow", Vector3.zero);
            replayer.stowLocalOrigin = new Vector3(0f, 0f, 0.09f);
            replayer.stowStep = new Vector3(0.13f, 0f, 0f);

            GameObject prefabAsset = PrefabUtility.SaveAsPrefabAsset(ghost, prefabPath);
            Object.DestroyImmediate(ghost);


            return prefabAsset.GetComponent<GhostReplayer>();
        }

        // ONE material across every submesh, where the opaque version cloned six (Skin, Shirt,
        // Pants, Hair, Eyes, Socks). Keeping them tinted apart would have survived the fresnel and
        // handed back the very thing the change removes: a rim that still says shirt-here,
        // trousers-there is a legible person, just a see-through one. The array still has to be
        // the submesh count long, so the same material is handed to every slot.
        //
        // The old Assets/Materials/Ghost*.mat are left on disk and simply unreferenced - they are
        // the FBX's own colours and cost nothing, and going back means pointing at them again.
        private static Material[] GhostMaterials(Material[] source)
        {
            Material faint = GhostFaintMaterial();
            var result = new Material[source.Length];
            for (int i = 0; i < source.Length; i++) result[i] = faint;
            return result;
        }

        // Tuning lives here rather than in the .shader's defaults, for the same reason every other
        // number in this project does: the shader is the mechanism, SceneBuilder is the value.
        private static Material GhostFaintMaterial()
        {
            string path = $"{MaterialsDir}/GhostFaint.mat";
            Shader shader = AssetDatabase.LoadAssetAtPath<Shader>($"{ShadersDir}/GhostFaint.shader");
            if (shader == null)
            {
                Debug.LogError($"[SceneBuilder] GhostFaint.shader missing from {ShadersDir}");
                return MakeColorMaterial("GhostFaintFallback", new Color(0.7f, 0.76f, 0.86f));
            }

            // GhostFaint.mat already exists from the era of the six faint primitives, on URP/Lit.
            // Reassigning the shader on the existing asset keeps its GUID, so nothing that
            // referenced it has to be found and repointed.
            Material mat = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (mat == null)
            {
                mat = new Material(shader);
                AssetDatabase.CreateAsset(mat, path);
            }
            mat.shader = shader;
            // The asset arrives carrying _SURFACE_TYPE_TRANSPARENT from its URP/Lit days. Swapping
            // the shader does not drop it - it just moves to m_InvalidKeywords and sits in the
            // diff forever. This shader declares no keywords at all, so the set is emptied.
            mat.shaderKeywords = new string[0];

            // Cool and desaturated, not white: at white the rim reads as a highlight on the wall
            // panelling behind it, which is the one colour in the room it must not be confused for.
            // Written through .linear - the project renders linear and SetColor takes the value
            // as-is, so an sRGB triple passed straight in comes out pale.
            mat.SetColor("_BaseColor", ((Color)new Color32(178, 194, 220, 255)).linear);
            mat.SetColor("_RimColor", ((Color)new Color32(224, 237, 255, 255)).linear);
            mat.SetFloat("_RimPower", 2.2f);
            mat.SetFloat("_RimAlpha", 0.75f);
            mat.SetFloat("_CoreAlpha", 0.06f);
            mat.SetFloat("_BottomFade", 0.35f);
            mat.SetFloat("_SoftFade", 0.12f);
            mat.renderQueue = (int)UnityEngine.Rendering.RenderQueue.Transparent;

            EditorUtility.SetDirty(mat);
            return mat;
        }

        // Three states, no transitions, because GhostReplayer scrubs each of them by hand - it
        // pins animator.speed at 0 and writes the normalized time itself. See the note there for
        // why the walk has to advance with distance rather than with the clock.
        private static RuntimeAnimatorController GhostAnimatorController()
        {
            string path = $"{PrefabsDir}/GhostAnimator.controller";
            var controller = AssetDatabase.LoadAssetAtPath<UnityEditor.Animations.AnimatorController>(path);
            if (controller == null)
                controller = UnityEditor.Animations.AnimatorController.CreateAnimatorControllerAtPath(path);

            var machine = controller.layers[0].stateMachine;
            // Rebuilt from scratch each time, since adding is not idempotent and a retried build
            // would otherwise stack duplicate states - the same failure ConfigureAmbientOcclusion
            // guards against with the SSAO feature.
            foreach (var child in machine.states) machine.RemoveState(child.state);

            AddGhostState(machine, "Walk", "Man_Walk", true);
            AddGhostState(machine, "Idle", "Man_Idle", false);
            AddGhostState(machine, "Swing", "Man_SwordSlash", false);

            EditorUtility.SetDirty(controller);
            return controller;
        }

        private static void AddGhostState(UnityEditor.Animations.AnimatorStateMachine machine,
                                          string stateName, string clipSuffix, bool isDefault)
        {
            AnimationClip clip = null;
            foreach (Object o in AssetDatabase.LoadAllAssetsAtPath(GhostModelPath))
            {
                var candidate = o as AnimationClip;
                if (candidate == null) continue;

                // LoadAllAssetsAtPath hands back the editor's hidden "__preview__" copies of every
                // clip alongside the real ones, and they sort first. Binding a state to one leaves
                // an animator that works in the editor and has nothing to play in a build - it
                // looked completely correct until the states were dumped and read.
                if (candidate.name.StartsWith("__preview__")) continue;

                // Clips arrive named "HumanArmature|Man_Walk", so match the tail rather than the
                // whole string - the armature prefix is the exporter's, not ours.
                if (candidate.name.EndsWith(clipSuffix)) { clip = candidate; break; }
            }
            if (clip == null) Debug.LogWarning($"[SceneBuilder] ghost clip '{clipSuffix}' not found");

            var state = machine.AddState(stateName);
            state.motion = clip;
            state.writeDefaultValues = true;
            if (isDefault) machine.defaultState = state;
        }

        private static void UseSinglePillow(GameObject bed, string keepName, string hideName, float centreX)
        {
            Transform hide = FindDescendant(bed.transform, hideName);
            if (hide != null) hide.gameObject.SetActive(false);

            Transform keep = FindDescendant(bed.transform, keepName);
            if (keep == null) return;

            Renderer[] renderers = keep.GetComponentsInChildren<Renderer>();
            if (renderers.Length == 0) return;

            Bounds bounds = renderers[0].bounds;
            for (int i = 1; i < renderers.Length; i++) bounds.Encapsulate(renderers[i].bounds);

            // Shift in world space: the model root is rotated, so nudging localPosition.x would
            // move the pillow along the model's axis rather than the room's.
            keep.position += new Vector3(centreX - bounds.center.x, 0f, 0f);
        }

        // Swaps a model's material for a copy with baked ambient occlusion switched off. The glb's
        // own materials are sub-assets that get regenerated on every reimport, so the copy has to
        // live as its own asset rather than being edited in place. The scene's SSAO still supplies
        // real contact shadows, so nothing is lost.
        private static void DisableBakedOcclusion(GameObject model, string materialName, string assetName)
        {
            foreach (Renderer renderer in model.GetComponentsInChildren<Renderer>(true))
            {
                if (renderer.sharedMaterial == null || renderer.sharedMaterial.name != materialName) continue;

                string path = $"{MaterialsDir}/{assetName}.mat";
                Material copy = AssetDatabase.LoadAssetAtPath<Material>(path);
                if (copy == null)
                {
                    copy = new Material(renderer.sharedMaterial);
                    AssetDatabase.CreateAsset(copy, path);
                }

                // Re-copy every build so the glb staying the source of truth for the other maps.
                copy.shader = renderer.sharedMaterial.shader;
                copy.CopyPropertiesFromMaterial(renderer.sharedMaterial);
                if (copy.HasProperty("occlusionTexture_strength")) copy.SetFloat("occlusionTexture_strength", 0f);

                EditorUtility.SetDirty(copy);
                renderer.sharedMaterial = copy;
            }
            AssetDatabase.SaveAssets();
        }

        private static Transform FindDescendant(Transform root, string name)
        {
            foreach (Transform t in root.GetComponentsInChildren<Transform>(true))
                if (t.name == name) return t;
            return null;
        }

        // A MOTOR AND A CLIP ON EVERY DOOR, factored out of `BuildAudio` so the per-cycle rebuild can
        // call it too.
        //
        // It had to be: `RebuildCycleTwo` builds that cycle without the rest of the game, and
        // `BuildAudio` lives in the full build - so a cycle rebuilt on its own came out with seven
        // doors that had no AudioSource and no clip and opened in silence. That is the standing hazard
        // of a partial build, and the answer is that anything a cycle needs has to be reachable from
        // the cycle's own path rather than only from `Build`.
        private static void WireDoorAudio(Door[] doors)
        {
            AudioClip doorOpen = LoadClip(SfxDir, "sfx_door_open");
            foreach (Door d in doors)
            {
                if (d == null) continue;
                d.audioSource = MakeSource(d.transform, "DoorAudio", 1f, 1f);
                d.openClip = doorOpen;
            }
        }

        private static (NarrationDirector, RoomAmbience) BuildAudio(GameObject player, Door[] doors, WakeUpSequence wakeUp)
        {
            GameObject root = new GameObject("Audio");

            // --- the PA announcer ---
            GameObject paGO = new GameObject("PA");
            paGO.transform.SetParent(root.transform, false);
            NarrationDirector narration = paGO.AddComponent<NarrationDirector>();
            // 2D on purpose: a room-wide tannoy has no position you could walk away from.
            narration.voiceSource = MakeSource(paGO.transform, "Voice", 0f, 1f);
            narration.chimeSource = MakeSource(paGO.transform, "Chime", 0f, 0.7f);
            // Both go through the same speaker, so both get the same treatment.
            (AudioEchoFilter voiceEcho, AudioReverbFilter voiceReverb) =
                AddTannoyFilters(narration.voiceSource);
            // The chime is not trimmed. It is two notes with nothing to smear, and it is the same
            // two notes in every language - see NarrationDirector.
            AddTannoyFilters(narration.chimeSource);

            narration.voiceEcho = voiceEcho;
            narration.voiceReverb = voiceReverb;
            // THE NUMBERS LIVE HERE, not in the component (CLAUDE.md §2). English is what
            // `AddTannoyFilters` just authored, restated so switching back is a real assignment
            // rather than "whatever the filter happens to hold".
            narration.englishTannoy = new NarrationDirector.TannoyTrim
            {
                echoWetMix = 0.33f,
                reverbDecayTime = 2.1f,
                reverbLevel = 250f,
            };
            // Roughly half the slap and half the tail. Enough that the horn is still in a room, not
            // so much that a one-syllable countdown digit is still ringing when the next one lands.
            narration.koreanTannoy = new NarrationDirector.TannoyTrim
            {
                echoWetMix = 0.15f,
                reverbDecayTime = 1.1f,
                reverbLevel = 80f,
            };

            // BOTH LANGUAGES WIRED IN, one chosen at runtime - see `NarrationDirector.Lines` for why
            // it is not loaded on demand. The two folders carry the SAME FILENAMES, which is what lets
            // one gather serve both; `Tools/generate_narration.ps1` writes them.
            narration.english = LoadVoiceSet(VoiceDir);
            narration.korean = LoadVoiceSet(VoiceDir + "/ko");
            narration.announcementChime = LoadClip(SfxDir, "sfx_chime");

            // Say so rather than shipping a silent PA. A missing Korean folder is not an error - the
            // director falls back to English - but it is never what anybody intended, and a language
            // that quietly stops talking is exactly the kind of fault that survives to a release.
            if (narration.korean == null || narration.korean.iterationGenericLine == null)
                Debug.LogWarning("[SceneBuilder] No Korean voice lines in " + VoiceDir + "/ko - the PA "
                               + "will speak English in both languages. Run "
                               + "Tools/generate_narration.ps1 -Language ko");

            // --- room tone and machinery ---
            GameObject ambienceGO = new GameObject("Ambience");
            ambienceGO.transform.SetParent(root.transform, false);
            RoomAmbience ambience = ambienceGO.AddComponent<RoomAmbience>();
            ambience.musicSource = MakeSource(ambienceGO.transform, "Music", 0f, 0.5f, loop: true);
            ambience.machineSource = MakeSource(ambienceGO.transform, "Machines", 0f, 0.7f);
            ambience.ominousLoop = LoadClip(SfxDir, "sfx_ominous_loop");
            // The two halves of the loop boundary, split across the blackout by LoopManager.
            ambience.pullIn = LoadClip(SfxDir, "sfx_pull_in");
            ambience.powerDown = LoadClip(SfxDir, "sfx_power_down");

            // ~~THE FLOOR PADS~~ WIRED IN `BuildFloorButton` SINCE 2026-08-21. They were wired
            // here from a hand-written list, cycle 3's four were never added to it, and play found
            // them silent. See that function for why the list itself was the bug.

            // --- the doors ---
            WireDoorAudio(doors);

            // --- the body waking up ---
            // 2D and parented to the player: this is the player's own breath, not a sound in the
            // room. It hangs off the player rather than the WakeUpSequence, which lives on the UI
            // canvas where a positional source would be meaningless.
            wakeUp.bodySource = MakeSource(player.transform, "BodyAudio", 0f, 1f);
            wakeUp.gaspClip = LoadClip(SfxDir, "sfx_gasp");
            wakeUp.sheetRustleClip = LoadClip(SfxDir, "sfx_sheet_rustle");

            return (narration, ambience);
        }

        // Turns a clean AudioSource into a wall-mounted PA horn firing into a hard, empty room.
        //
        // Done as a runtime filter chain rather than baked into the WAVs on purpose: the clips stay
        // clean masters, the treatment is one Inspector tweak away from being retuned, and a
        // replacement take dropped into Assets/Audio/Voice/ inherits the whole thing for free.
        //
        // Component order IS the signal chain - Unity runs the filters top to bottom on the
        // GameObject, so these are added in the order they should process. Reverb last: putting it
        // ahead of the distortion would grit up the tail as well as the voice, which reads as a
        // broken speaker rather than a room.
        // Returns the two filters whose settings are language-dependent, so `NarrationDirector` can
        // dial them without owning the rest of the chain. Everything else here is the same in every
        // language: the band-limiting and the drive are the SPEAKER, and the speaker does not change.
        private static (AudioEchoFilter echo, AudioReverbFilter reverb) AddTannoyFilters(AudioSource source)
        {
            GameObject go = source.gameObject;

            // Band-limit first. A horn driver has no bottom and no top, and losing both is most of
            // what makes a voice read as "coming out of a speaker" rather than as narration - the
            // ear identifies the channel long before it identifies the reverb.
            AudioHighPassFilter hp = go.AddComponent<AudioHighPassFilter>();
            hp.cutoffFrequency = 340f;
            hp.highpassResonanceQ = 1f;

            AudioLowPassFilter lp = go.AddComponent<AudioLowPassFilter>();
            lp.cutoffFrequency = 3600f;
            // Slightly resonant rather than flat: a real horn has a peak up there, and that peak is
            // the nasal honk of every station announcement ever made.
            lp.lowpassResonanceQ = 1.6f;

            // Just enough drive to suggest an overdriven line. Past ~0.3 the words stop being
            // intelligible, and the announcer has actual information in them (the iteration number).
            AudioDistortionFilter dist = go.AddComponent<AudioDistortionFilter>();
            dist.distortionLevel = 0.17f;

            // The slap off the far wall. 105ms is roughly the round trip across a room this size,
            // so it reads as this room rather than as an effect.
            AudioEchoFilter echo = go.AddComponent<AudioEchoFilter>();
            echo.delay = 105f;
            echo.decayRatio = 0.22f;
            echo.dryMix = 1f;
            echo.wetMix = 0.33f;

            // And the tail. Preset is set to User first: assigning any individual property switches
            // it there anyway, and setting it explicitly keeps the intent readable.
            AudioReverbFilter verb = go.AddComponent<AudioReverbFilter>();
            verb.reverbPreset = AudioReverbPreset.User;
            verb.dryLevel = 0f;
            verb.room = -350f;
            // Dark tail. Hard painted panels absorb almost nothing low and quite a lot high, and a
            // bright tail would fight the band-limiting the horn just did.
            verb.roomHF = -900f;
            verb.decayTime = 2.1f;
            verb.decayHFRatio = 0.55f;
            verb.reflectionsLevel = -650f;
            verb.reverbLevel = 250f;
            verb.diffusion = 100f;
            verb.density = 100f;

            return (echo, verb);
        }

        // spatialBlend 0 is 2D (heard the same everywhere), 1 is fully positional.
        private static AudioSource MakeSource(Transform parent, string name, float spatialBlend, float volume, bool loop = false)
        {
            GameObject go = new GameObject(name);
            go.transform.SetParent(parent, false);

            AudioSource source = go.AddComponent<AudioSource>();
            source.playOnAwake = false;
            source.loop = loop;
            source.spatialBlend = spatialBlend;
            source.volume = volume;
            // Linear rather than the logarithmic default: the room is only ~10m across, and the
            // default curve is still near full volume across the whole of it.
            source.rolloffMode = AudioRolloffMode.Linear;
            source.minDistance = 1f;
            source.maxDistance = 14f;
            return source;
        }

        // A DULL WOOD CHOP, generated rather than sourced - which is how every other clip in this
        // project was made (see docs/audio.md).
        //
        // The chop used to borrow `sfx_item_pickup`, a bright little tick that read as picking
        // something up because that is what it is. An axe into a standing trunk is the opposite:
        // almost no high end, a hard transient, and a short woody thump that dies fast because a
        // living tree does not ring.
        //
        // Three layers, and each is doing one job:
        //  - a low body around 90Hz that drops a fifth as it decays. That downward slide is most of
        //    what makes a thump sound like it hit WOOD rather than a drum head.
        //  - a brief burst of filtered noise for the bite of the blade, gone in 40ms.
        //  - a faint mid ring, low enough in level to be felt rather than heard, so the tail is not
        //    perfectly dead.
        private static AudioClip MakeChopClip(string assetName)
        {
            string path = $"{SfxDir}/{assetName}.wav";
            AudioClip existing = AssetDatabase.LoadAssetAtPath<AudioClip>(path);
            if (existing != null) return existing;

            const int rate = 44100;
            const float seconds = 0.42f;
            int count = (int)(rate * seconds);
            float[] data = new float[count];

            var rng = new System.Random(20260816);
            float noiseLow = 0f;
            for (int i = 0; i < count; i++)
            {
                float t = i / (float)rate;

                // BODY. The pitch falls as it decays, which is the wood.
                float bodyEnv = Mathf.Exp(-t * 19f);
                float freq = Mathf.Lerp(96f, 62f, Mathf.Clamp01(t * 14f));
                float body = Mathf.Sin(2f * Mathf.PI * freq * t) * bodyEnv * 0.85f;

                // BITE. White noise through a one-pole low-pass, so it is a thock rather than a hiss.
                float raw = (float)(rng.NextDouble() * 2.0 - 1.0);
                noiseLow += (raw - noiseLow) * 0.22f;
                float bite = noiseLow * Mathf.Exp(-t * 78f) * 0.55f;

                // RING, well down and gone quickly.
                float ring = Mathf.Sin(2f * Mathf.PI * 310f * t) * Mathf.Exp(-t * 34f) * 0.12f;

                // A 2ms fade in so the very first sample is not a click of its own.
                float attack = Mathf.Clamp01(t / 0.002f);
                data[i] = Mathf.Clamp(body + bite + ring, -1f, 1f) * attack;
            }

            WriteWav(path, data, rate);
            AssetDatabase.ImportAsset(path);
            return AssetDatabase.LoadAssetAtPath<AudioClip>(path);
        }

        // A STEP THROUGH WAIST-DEEP WATER, generated like every other clip in this project.
        //
        // IT IS NOT A SPLASH AND IT IS NOT A FOOTSTEP, which is the whole reason it exists rather than
        // reusing either. `sfx_water_splash_*` is water hitting something from above - a hard front and
        // a bright scatter - and a footstep is a transient off a hard floor. Neither is what a leg
        // pushed through a body of water sounds like:
        //
        //  - **There is no transient.** Water is heavy and slow, so the sound SWELLS over ~50ms rather
        //    than starting. A sharp attack is the single thing that makes a water sound read as a
        //    sample of a water sound.
        //  - **Most of it is low.** The body is the mass being shoved sideways, a couple of hundred
        //    hertz and below, and it is what makes the water sound DEEP rather than shallow.
        //  - **The top is bubbles, and it comes AFTER.** Air dragged under surfaces behind the push
        //    and breaks up, so the fizz is delayed and decays on its own, faster, clock.
        //
        // Three of them, seeded differently, for the reason the three footsteps exist: consecutive
        // identical steps read as a sample player rather than as a person walking.
        private static AudioClip MakeWadeClip(string assetName, int seed, float seconds = 0.62f,
                                              float decay = 5.2f, float fizzLevel = 0.42f,
                                              float lowWeight = 2.6f)
        {
            string path = $"{SfxDir}/{assetName}.wav";
            AudioClip existing = AssetDatabase.LoadAssetAtPath<AudioClip>(path);
            if (existing != null) return existing;

            const int rate = 44100;
            int count = (int)(rate * seconds);
            float[] data = new float[count];

            var rng = new System.Random(seed);
            float low = 0f, mid = 0f, high = 0f;
            // Where the bubbles start, which is after the push - and not the same place twice.
            float fizzDelay = 0.045f + (float)rng.NextDouble() * 0.05f;
            float peak = 0f;

            for (int i = 0; i < count; i++)
            {
                float t = i / (float)rate;
                float raw = (float)(rng.NextDouble() * 2.0 - 1.0);

                // Three one-pole filters off one noise source, which is how one sound ends up with a
                // bottom, a middle and a top that move together rather than three layers that do not.
                low += (raw - low) * 0.035f;
                mid += (raw - mid) * 0.20f;
                high += (raw - high) * 0.65f;

                // THE PUSH. Soft in, long out - and the tail is longer than the body because water
                // keeps moving after the leg has stopped.
                float swell = (1f - Mathf.Exp(-t * 26f)) * Mathf.Exp(-t * decay);
                float body = (low * lowWeight + mid * 0.9f) * swell;

                // THE BUBBLES, delayed and on their own decay, and gated so they only exist while
                // there is air still coming up.
                float ft = t - fizzDelay;
                float fizz = 0f;
                if (ft > 0f)
                {
                    // Modulated, because bubbles are individual events rather than a hiss - two slow
                    // waves are enough to break it into a texture.
                    float grain = 0.55f + 0.45f * Mathf.Sin(2f * Mathf.PI * 23f * ft)
                                              * Mathf.Sin(2f * Mathf.PI * 7.3f * ft + seed);
                    fizz = (raw - high) * Mathf.Exp(-ft * 11f) * fizzLevel * grain;
                }

                // A 3ms fade in, so sample zero is not a click of its own.
                data[i] = (body + fizz) * Mathf.Clamp01(t / 0.003f);
                peak = Mathf.Max(peak, Mathf.Abs(data[i]));
            }

            // NORMALISED rather than hand-balanced. The three layers are noise, so their sum's level
            // depends on the seed - without this the three clips come out at three volumes and the
            // walk has a limp.
            float gain = peak > 0.0001f ? 0.86f / peak : 1f;
            for (int i = 0; i < count; i++) data[i] = Mathf.Clamp(data[i] * gain, -1f, 1f);

            WriteWav(path, data, rate);
            AssetDatabase.ImportAsset(path);
            return AssetDatabase.LoadAssetAtPath<AudioClip>(path);
        }

        // A HANDWHEEL BEING WOUND ROUND. Generated like every other clip here.
        //
        // Three things, and the second is the one that makes it a valve rather than a machine:
        //  - a low GRIND, filtered noise with a slow tremolo on it, which is the thread turning under
        //    load. It runs the whole length of the turn and is most of the volume;
        //  - a SQUEAK that RISES then FALLS, two detuned partials with vibrato. Metal complaining
        //    changes pitch as the load on it changes, and a steady tone reads as an electric motor;
        //  - CLICKS, one per twelfth of a turn, so the wheel has teeth and you can hear how far round
        //    it has gone with your eyes elsewhere. That last part is the load-bearing one: this room
        //    is solved by past selves turning wheels behind you.
        //
        // Its length is the valve's turn duration - `Valve.turnDuration` - because a sound that ends
        // before the animation does says the wheel stopped when it did not.
        private static AudioClip MakeValveTurnClip(string assetName)
        {
            string path = $"{SfxDir}/{assetName}.wav";
            AudioClip existing = AssetDatabase.LoadAssetAtPath<AudioClip>(path);
            if (existing != null) return existing;

            const int rate = 44100;
            const float seconds = 1.4f;
            int count = (int)(rate * seconds);
            float[] data = new float[count];

            var rng = new System.Random(20260824);
            float low = 0f, mid = 0f;
            float peak = 0f;

            for (int i = 0; i < count; i++)
            {
                float t = i / (float)rate;
                float u = t / seconds;
                // In and out over the first and last tenth, so neither end is a cut.
                float env = Mathf.Min(1f, u / 0.1f) * Mathf.Min(1f, (1f - u) / 0.12f);

                float raw = (float)(rng.NextDouble() * 2.0 - 1.0);
                low += (raw - low) * 0.06f;
                mid += (raw - mid) * 0.30f;
                // The tremolo is what makes the grind mechanical rather than a hiss.
                float grind = (low * 2.2f + mid * 0.5f) * (0.65f + 0.35f * Mathf.Sin(2f * Mathf.PI * 11f * t));

                // The squeak: up over the first half, down over the second, with vibrato on top.
                float bend = Mathf.Sin(Mathf.PI * u);
                float freq = Mathf.Lerp(430f, 690f, bend) + Mathf.Sin(2f * Mathf.PI * 6.5f * t) * 18f;
                float squeal = (Mathf.Sin(2f * Mathf.PI * freq * t)
                              + Mathf.Sin(2f * Mathf.PI * freq * 1.51f * t) * 0.45f) * 0.13f * bend;

                // Teeth. A short decaying tick every twelfth of a turn.
                const int teeth = 12;
                float toothPhase = (t * teeth / seconds) % 1f;
                float click = Mathf.Exp(-toothPhase * 60f) * 0.22f * (float)(rng.NextDouble() * 0.6 + 0.7);

                data[i] = (grind + squeal + click) * env;
                peak = Mathf.Max(peak, Mathf.Abs(data[i]));
            }

            float gain = peak > 0.0001f ? 0.82f / peak : 1f;
            for (int i = 0; i < count; i++) data[i] = Mathf.Clamp(data[i] * gain, -1f, 1f);

            WriteWav(path, data, rate);
            AssetDatabase.ImportAsset(path);
            return AssetDatabase.LoadAssetAtPath<AudioClip>(path);
        }

        // THE VALVE REACHING ITS STOP. A short, hard, metallic clank - this is the sound that says
        // "this one is finished", and it is the only feedback a player gets that a wheel is done other
        // than E going quiet on it.
        private static AudioClip MakeValveStopClip(string assetName)
        {
            string path = $"{SfxDir}/{assetName}.wav";
            AudioClip existing = AssetDatabase.LoadAssetAtPath<AudioClip>(path);
            if (existing != null) return existing;

            const int rate = 44100;
            const float seconds = 0.5f;
            int count = (int)(rate * seconds);
            float[] data = new float[count];

            var rng = new System.Random(20260825);
            float noise = 0f;

            for (int i = 0; i < count; i++)
            {
                float t = i / (float)rate;

                // The impact: a fast noise burst, low-passed just enough not to be a hiss.
                float raw = (float)(rng.NextDouble() * 2.0 - 1.0);
                noise += (raw - noise) * 0.55f;
                float hit = noise * Mathf.Exp(-t * 95f) * 0.7f;

                // And the ring, three INHARMONIC partials - a struck metal object has no harmonic
                // series, and giving it one is what makes a clank read as a musical note.
                float ring = (Mathf.Sin(2f * Mathf.PI * 320f * t) * 0.5f
                            + Mathf.Sin(2f * Mathf.PI * 741f * t) * 0.32f
                            + Mathf.Sin(2f * Mathf.PI * 1483f * t) * 0.16f) * Mathf.Exp(-t * 13f) * 0.5f;

                data[i] = Mathf.Clamp(hit + ring, -1f, 1f) * Mathf.Clamp01(t / 0.001f);
            }

            WriteWav(path, data, rate);
            AssetDatabase.ImportAsset(path);
            return AssetDatabase.LoadAssetAtPath<AudioClip>(path);
        }

        // 16-bit mono PCM. Unity can author an AudioClip in memory but cannot SAVE one, and a clip
        // that exists only in memory does not survive the scene being written - the same trap the
        // reflection probes fell into.
        private static void WriteWav(string path, float[] samples, int rate)
        {
            using (var stream = new System.IO.FileStream(path, System.IO.FileMode.Create))
            using (var w = new System.IO.BinaryWriter(stream))
            {
                int dataBytes = samples.Length * 2;
                w.Write(new char[] { 'R', 'I', 'F', 'F' });
                w.Write(36 + dataBytes);
                w.Write(new char[] { 'W', 'A', 'V', 'E' });
                w.Write(new char[] { 'f', 'm', 't', ' ' });
                w.Write(16);                      // PCM header size
                w.Write((short)1);                // PCM
                w.Write((short)1);                // mono
                w.Write(rate);
                w.Write(rate * 2);                // byte rate
                w.Write((short)2);                // block align
                w.Write((short)16);               // bits
                w.Write(new char[] { 'd', 'a', 't', 'a' });
                w.Write(dataBytes);
                for (int i = 0; i < samples.Length; i++)
                    w.Write((short)(Mathf.Clamp(samples[i], -1f, 1f) * short.MaxValue));
            }
        }

        // SHRINKS THE TEXTURES OF AN IMPORTED MODEL, in place, by rewriting them as real assets.
        //
        // WHY THIS EXISTS. `realistic_tree.glb` ships four 4096x4096 textures and glTFast imports
        // them UNCOMPRESSED: 628MB of VRAM for one tree, measured. (`tree_roots.glb` added 17MB more
        // while the hall had a separate stump model; it does not any longer - the tree keeps its own.)
        // That is the stutter play reported, and it is not the polygon count it looks like - the
        // roots are 1.3M triangles, which is a lot, but a modern GPU eats triangles and chokes on
        // two thirds of a gigabyte of texture.
        //
        // They cannot simply be re-imported with better settings: they are SUB-ASSETS of a custom
        // importer (`GltfImporter`), so there is no TextureImporter to configure. So each one is
        // blitted into a render target at the size we actually want, read back, written out as a
        // real PNG asset with proper settings, and the material is pointed at the copy. A blit is
        // used rather than `GetPixels` because a sub-asset texture is not readable.
        //
        // Runs once per build and is idempotent: the PNG is only regenerated if it is missing.
        private static void ShrinkModelTextures(string modelPath, int maxSize)
        {
            var seen = new System.Collections.Generic.Dictionary<Texture, Texture2D>();
            long before = 0, after = 0;
            int rewritten = 0;

            foreach (Object asset in AssetDatabase.LoadAllAssetsAtPath(modelPath))
            {
                Material mat = asset as Material;
                if (mat == null) continue;

                foreach (string prop in mat.GetTexturePropertyNames())
                {
                    Texture src = mat.GetTexture(prop);
                    Texture2D srcTex = src as Texture2D;
                    if (srcTex == null) continue;
                    if (srcTex.width <= maxSize && srcTex.height <= maxSize) continue;

                    if (!seen.TryGetValue(srcTex, out Texture2D copy))
                    {
                        before += UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(srcTex);
                        copy = ShrunkCopy(srcTex, maxSize,
                            System.IO.Path.GetFileNameWithoutExtension(modelPath) + "_" + srcTex.name);
                        seen[srcTex] = copy;
                        if (copy != null)
                        {
                            after += UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(copy);
                            rewritten++;
                        }
                    }
                    if (copy != null) mat.SetTexture(prop, copy);
                }
            }

            if (rewritten > 0)
                Debug.Log($"[SceneBuilder] {System.IO.Path.GetFileName(modelPath)}: {rewritten} texture(s) "
                        + $"shrunk to {maxSize}px - {before / 1048576}MB -> {after / 1048576}MB");
        }

        // One texture, downscaled and saved as a compressed asset. The blit is what makes this work
        // on a texture that is not readable, which every model sub-asset is.
        private static Texture2D ShrunkCopy(Texture2D src, int maxSize, string assetName)
        {
            string path = $"{TexturesDir}/Shrunk/{assetName}.png";
            Texture2D existing = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
            if (existing != null) return existing;

            if (SystemInfo.graphicsDeviceType == GraphicsDeviceType.Null)
            {
                Debug.LogWarning("[SceneBuilder] No graphics device: textures left at full size.");
                return null;
            }

            float aspect = src.height / (float)src.width;
            int w = Mathf.Min(maxSize, src.width);
            int h = Mathf.Max(1, Mathf.RoundToInt(w * aspect));

            // sRGB matters: an albedo blitted through a linear target comes back washed out.
            RenderTexture rt = RenderTexture.GetTemporary(w, h, 0, RenderTextureFormat.ARGB32,
                                                          RenderTextureReadWrite.sRGB);
            RenderTexture previous = RenderTexture.active;
            Graphics.Blit(src, rt);
            RenderTexture.active = rt;

            Texture2D flat = new Texture2D(w, h, TextureFormat.RGBA32, false);
            flat.ReadPixels(new Rect(0f, 0f, w, h), 0, 0);
            flat.Apply();
            RenderTexture.active = previous;
            RenderTexture.ReleaseTemporary(rt);

            Directory.CreateDirectory($"{TexturesDir}/Shrunk");
            File.WriteAllBytes(path, flat.EncodeToPNG());
            Object.DestroyImmediate(flat);

            AssetDatabase.ImportAsset(path, ImportAssetOptions.ForceUpdate);
            if (AssetImporter.GetAtPath(path) is TextureImporter imp)
            {
                imp.textureType = TextureImporterType.Default;
                imp.mipmapEnabled = true;
                imp.maxTextureSize = maxSize;
                // COMPRESSED, unlike the originals. This is where the 628MB actually goes.
                imp.textureCompression = TextureImporterCompression.Compressed;
                imp.alphaIsTransparency = true;
                imp.SaveAndReimport();
            }
            return AssetDatabase.LoadAssetAtPath<Texture2D>(path);
        }

        // Extension-agnostic, so a sourced .ogg or .mp3 drops in as readily as a .wav.
        // ONE LANGUAGE'S WORTH OF PA LINES. Both folders use identical filenames, so which language
        // this is comes entirely from `dir` - that is the whole reason the Korean set went into a
        // subfolder rather than getting a suffix on every name.
        private static NarrationDirector.VoiceSet LoadVoiceSet(string dir)
        {
            var set = new NarrationDirector.VoiceSet();

            set.iterationLines = new AudioClip[NarrationIterationLines];
            for (int i = 0; i < set.iterationLines.Length; i++)
                set.iterationLines[i] = LoadClip(dir, $"voice_iteration_{i + 1:00}");

            set.iterationGenericLine = LoadClip(dir, "voice_iteration_generic");
            set.tenSecondsLine = LoadClip(dir, "voice_ten_seconds");

            // Element 0 is "Nine.", counting down to "One." at the end.
            set.countdownLines = new AudioClip[9];
            for (int i = 0; i < set.countdownLines.Length; i++)
                set.countdownLines[i] = LoadClip(dir, $"voice_count_{9 - i}");

            set.newCycleLine = LoadClip(dir, "voice_new_cycle");
            set.cycleTerminatedLine = LoadClip(dir, "voice_cycle_terminated");
            set.cycleBrokenLine = LoadClip(dir, "voice_cycle_broken");
            set.allCyclesBrokenLine = LoadClip(dir, "voice_all_cycles_broken");
            set.manualTerminationLine = LoadClip(dir, "voice_manual_termination");
            return set;
        }

        private static AudioClip LoadClip(string dir, string baseName)
        {
            foreach (string ext in new[] { ".wav", ".ogg", ".mp3", ".aif", ".aiff" })
            {
                AudioClip clip = AssetDatabase.LoadAssetAtPath<AudioClip>($"{dir}/{baseName}{ext}");
                if (clip != null) return clip;
            }
            return null;
        }

        // The HUD face. Monospace on purpose, and for two reasons at once.
        //
        // Diegetically, everything on screen belongs to the facility rather than to the player -
        // the iteration number, the clock, the control that ends a cycle - and a terminal face says
        // that where a proportional one reads as a game's own UI. The room is built out of wall
        // *displays* for the same reason.
        //
        // Practically, the countdown is a number that changes every second: in a proportional font
        // its digits are different widths, so it reflows and twitches on the spot every tick. In a
        // monospace one it does not move at all.
        //
        // NOTE ON LICENSING: Consolas is Microsoft's, copied out of C:/Windows/Fonts. Fine for a
        // prototype that never leaves this machine, NOT fine to ship. Swapping it is one file and
        // this path - JetBrains Mono or IBM Plex Mono are both SIL OFL and drop straight in.
        // THE INK ON A BRIGHT SURFACE. Near-black rather than the red everything on this screen used
        // to be: red is this game's ALARM - the ERROR test card, the last ten seconds, the collapse -
        // and spending it on five button labels leaves nothing to say anything with. It is the same
        // charcoal the grooves in every wall are painted, so the type reads as printed ON the room.
        private static readonly Color MenuInk = new Color(0.11f, 0.11f, 0.13f, 1f);
        // The one accent, and there is exactly one on the screen at rest.
        private static readonly Color MenuAccent = new Color(0.80f, 0.10f, 0.10f, 1f);

        // WEIGHTS, and the whole family is on disk - sixteen faces, of which this project used one.
        // A hierarchy built from SIZE alone is what four sizes with no ratio between them looks like;
        // one built from weight needs only two sizes. ExtraLight at 86 is a different instrument from
        // Regular at 86, and it is the one a title wants.
        // THE HANGUL FACE, for the one label that must be Korean before any language is chosen.
        // Everything else swaps at runtime through `LocalizedText`, which resolves the same asset -
        // this exists so the two cannot point at different files.
        private static Font KoreanUIFont() =>
            AssetDatabase.LoadAssetAtPath<Font>("Assets/Resources/Fonts/D2Coding.ttf");

        private static Font UIFont(string weight)
        {
            Font font = AssetDatabase.LoadAssetAtPath<Font>(
                $"{FontsDir}/JetBrains_Mono/static/JetBrainsMono-{weight}.ttf");
            return font != null ? font : UIFont();
        }

        private static Font UIFont()
        {
            // The STATIC Regular, not the variable font that ships alongside it: uGUI's legacy
            // Font has no axis control, so a variable face is a coin toss on which weight renders.
            Font font = AssetDatabase.LoadAssetAtPath<Font>($"{FontsDir}/JetBrains_Mono/static/JetBrainsMono-Regular.ttf");
            // Falls back rather than throwing: a missing font should leave the UI ugly and legible,
            // not leave the scene unbuildable.
            return font != null ? font : Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
        }

        // Top-left readout of what is in the player's pockets. Carrying is state the loop rewinds
        // and the key is invisible once pocketed, so without this "do I still have the key" is only
        // answerable by walking to the door and trying it.
        private static GameObject BuildCarriedItems(Transform canvas, PlayerHand hand)
        {
            // ONE SLOT. It was a row of eight, sized for a pocket that could hold every symbol cube
            // at once; the hand holds exactly one object now and the other seven were a readout of
            // something that cannot happen.
            const float slotSize = 58f;

            GameObject go = new GameObject("CarriedItems");
            go.transform.SetParent(canvas, false);

            RectTransform rect = go.AddComponent<RectTransform>();
            rect.anchorMin = new Vector2(0f, 1f);
            rect.anchorMax = new Vector2(0f, 1f);
            rect.pivot = new Vector2(0f, 1f);
            rect.sizeDelta = new Vector2(slotSize, slotSize);
            rect.anchoredPosition = new Vector2(36f, -30f);

            GameObject slotGO = new GameObject("Slot");
            slotGO.transform.SetParent(go.transform, false);

            Image image = slotGO.AddComponent<Image>();
            // Red like the rest of the HUD: the walls are near-white, so a white glyph disappears
            // into them.
            image.color = Color.red;
            image.raycastTarget = false;
            image.preserveAspect = true;
            image.enabled = false;

            RectTransform slotRect = image.GetComponent<RectTransform>();
            slotRect.anchorMin = new Vector2(0f, 1f);
            slotRect.anchorMax = new Vector2(0f, 1f);
            slotRect.pivot = new Vector2(0f, 1f);
            slotRect.sizeDelta = new Vector2(slotSize, slotSize);
            slotRect.anchoredPosition = Vector2.zero;

            // The put-down prompt, under the icon rather than out in the middle of the screen: it
            // explains this readout, so it belongs on it. A child of the row, so moving the row
            // moves the label with it.
            GameObject hintGO = new GameObject("DropHint");
            hintGO.transform.SetParent(go.transform, false);

            CanvasGroup hintGroup = hintGO.AddComponent<CanvasGroup>();
            hintGroup.alpha = 0f;
            hintGroup.blocksRaycasts = false;
            hintGroup.interactable = false;

            Text hint = hintGO.AddComponent<Text>();
            hint.font = UIFont();
            hint.fontSize = 16;
            hint.alignment = TextAnchor.UpperLeft;
            hint.color = Color.red;
            // Bracketed key then the verb, the same shape as the end-cycle control's label.
            hint.text = "[E] — PUT DOWN";
            Localize(hint, "hud.putDown");
            // 0.6 * 16 * 16 is about 154px against a 300px rect, but overflow is set anyway - a
            // silently rewrapping HUD label has bitten this project twice.
            hint.horizontalOverflow = HorizontalWrapMode.Overflow;
            hint.verticalOverflow = VerticalWrapMode.Overflow;
            hint.raycastTarget = false;

            RectTransform hintRect = hint.GetComponent<RectTransform>();
            hintRect.anchorMin = new Vector2(0f, 1f);
            hintRect.anchorMax = new Vector2(0f, 1f);
            hintRect.pivot = new Vector2(0f, 1f);
            hintRect.sizeDelta = new Vector2(300f, 22f);
            // anchoredPosition, never localPosition: the latter is stale on a RectTransform, and
            // it must be written AFTER AddComponent<Text> replaced the Transform.
            hintRect.anchoredPosition = new Vector2(0f, -(slotSize + 10f));

            CarriedItemsDisplay display = go.AddComponent<CarriedItemsDisplay>();
            display.hand = hand;
            display.slot = image;
            display.dropHint = hintGroup;
            return go;
        }

        // The two control prompts. A grey disc over whatever the player has walked up to, with an
        // E on it, and a second disc carrying a mouse glyph that appears on the pin the moment it
        // is in hand. Each is shown once and then retired for good - see ControlHintDisplay.
        //
        // Built last of everything on the canvas so it draws over the eyelids and the HUD, and
        // parented to a full-screen rect so a screen point converts straight to an anchoredPosition.
        // THE SCREEN AS A CONTROLLER, for the WebGL build opened on a phone. See TouchControls for
        // why this is raw touch handling rather than uGUI buttons, and why the visuals here are
        // non-interactive images: every one of them is placed AT RUNTIME from the same numbers the
        // hit test uses, so a mark and the press it describes can never end up in two places.
        //
        // **RAYCAST TARGETS OFF ON EVERY PIECE.** TouchControls asks the EventSystem whether
        // something that wants presses is under a finger, so that `EndCycleControl` keeps its hold -
        // and its own artwork answering that question would block the look drag across a third of
        // the screen.
        //
        // Built into the same canvas as the HUD, and it costs a desktop player nothing: `Active` is
        // false off a touch device, so the group sits at zero alpha and samples nothing.
        private static TouchControls BuildTouchControls(Transform canvas)
        {
            GameObject root = new GameObject("TouchControls");
            root.transform.SetParent(canvas, false);
            Stretch(root.AddComponent<RectTransform>());

            CanvasGroup group = root.AddComponent<CanvasGroup>();
            group.alpha = 0f;
            // Never takes a press itself - this whole layer is read by polling, not by the
            // EventSystem, and blocking raycasts here would swallow the pause menu underneath it.
            group.blocksRaycasts = false;
            group.interactable = false;

            Sprite disc = HintDiscSprite();

            TouchControls touch = root.AddComponent<TouchControls>();
            touch.group = group;

            // THE STICK, drawn only while a thumb is down - see TouchControls.Draw. It appears where
            // the finger lands, so there is nothing to place here beyond its look.
            touch.stickBase = MakeTouchDisc(root.transform, "StickBase", disc,
                                            new Color(1f, 1f, 1f, 0.13f));
            touch.stickKnob = MakeTouchDisc(root.transform, "StickKnob", disc,
                                            new Color(1f, 1f, 1f, 0.30f));
            touch.stickBase.gameObject.SetActive(false);
            touch.stickKnob.gameObject.SetActive(false);

            // WHERE THE THUMBS GO. The left box is the stick's, the rest of the screen turns the
            // view, and the buttons sit up the right-hand edge where a right thumb reaches without
            // covering the middle of the room. E is the biggest and the lowest because it is the
            // verb this game is almost entirely made of.
            touch.stickZone = new Rect(0f, 0f, 0.45f, 0.72f);
            touch.stickRadius = 0.115f;

            // E AND JUMP SWAPPED 2026-08-15, after play on a phone: E was in the lowest position
            // where the thumb rests, jump above it. That is backwards for how often each is used -
            // jump is pressed a handful of times in a run and E is pressed constantly, but the
            // resting spot is also where the thumb sits BETWEEN presses, so it was catching the
            // wrong one. E takes the upper spot, which the thumb travels to deliberately.
            //
            // Sizes did NOT swap. E stays the biggest target because it is still the verb this game
            // is almost entirely made of.
            SetTouchButton(touch.interact, root.transform, disc, "E",
                           new Vector2(0.885f, 0.420f), 0.098f);
            // A MOUSE RATHER THAN THE WORD "USE", and the icon already exists: this is the same
            // left-button glyph `ControlHintDisplay` puts on whatever a click would act on. The word
            // was a placeholder that named the input; the glyph names the same thing the rest of the
            // game already uses for it, so a player who has seen the prompt disc knows this button.
            SetTouchButton(touch.use, root.transform, disc, "USE",
                           new Vector2(0.700f, 0.135f), 0.072f, MouseLeftIcon());
            SetTouchButton(touch.jump, root.transform, disc, "JUMP",
                           new Vector2(0.885f, 0.175f), 0.072f);
            // Top corner, small, and away from everything else: it is pressed between runs rather
            // than during one.
            SetTouchButton(touch.pause, root.transform, disc, "II",
                           new Vector2(0.955f, 0.930f), 0.042f);

            return touch;
        }

        // THE TOUCH BUTTONS ARE ONE TRANSPARENT GREY.
        //
        // They shipped white at 17% alpha, which is the HUD's own language for a prompt and
        // invisible against the one thing this building is made of. The first fix gave each button
        // its own hue - red, amber, blue - and play called it: three saturated circles are the
        // loudest thing on a screen showing a white room, and they read as a different game's UI
        // bolted on.
        //
        // So the answer to "cannot be seen" turned out to be VALUE, not colour. A dark grey at 62%
        // composites to about 0.45 over a white wall, which is a clear silhouette and carries the
        // white label at readable contrast - and over an unlit wall (room2-1 starts dark) it goes
        // darker still while the label stays white. One colour, both ends.
        private static readonly Color TouchButtonColour = new Color(0.12f, 0.12f, 0.14f, 0.62f);
        private static readonly Color TouchRimColour = new Color(0.04f, 0.04f, 0.06f, 0.55f);

        // One round control: the disc, its label, and the numbers TouchControls hit-tests against.
        // `icon` replaces the text label when the button has a glyph of its own - see the mouse on
        // USE. Everything else carries its word, because there is no drawing of "jump" that is
        // clearer than the word.
        private static void SetTouchButton(TouchControls.TouchButton button, Transform parent,
                                           Sprite disc, string label, Vector2 center, float radius,
                                           Sprite icon = null)
        {
            button.label = label;
            button.center = center;
            button.radius = radius;

            // A CONTAINER rather than the disc itself, because a button is three pieces now: the
            // rim, the fill and the label. `TouchControls.LayOut` sizes this one rect and the rest
            // stretch to it, so there is still exactly one thing that knows how big a button is.
            GameObject go = new GameObject("Touch_" + label);
            go.transform.SetParent(parent, false);
            RectTransform rect = go.AddComponent<RectTransform>();
            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            button.visual = rect;

            // Built in draw order: the rim first, so it sits behind. It is anchored slightly OUTSIDE
            // its parent rather than given a pixel offset, so the ring keeps its proportion at any
            // button size and on any screen.
            MakeTouchDisc(rect, "Rim", disc, TouchRimColour, -0.07f);
            MakeTouchDisc(rect, "Fill", disc, TouchButtonColour, 0f);

            if (icon != null)
            {
                GameObject iconGO = new GameObject("Icon");
                iconGO.transform.SetParent(rect, false);
                Image glyph = iconGO.AddComponent<Image>();
                glyph.sprite = icon;
                glyph.color = Color.white;
                glyph.raycastTarget = false;
                // Inset inside the disc rather than filling it, so the button still reads as a
                // button with something on it. Anchors, so the inset is proportional at any size.
                RectTransform ir = iconGO.GetComponent<RectTransform>();
                ir.anchorMin = new Vector2(0.24f, 0.24f);
                ir.anchorMax = new Vector2(0.76f, 0.76f);
                ir.offsetMin = Vector2.zero;
                ir.offsetMax = Vector2.zero;
                return;
            }

            GameObject textGO = new GameObject("Label");
            textGO.transform.SetParent(rect, false);
            Text text = textGO.AddComponent<Text>();
            text.font = UIFont();
            // Against the disc's own size rather than a point size, so it stays centred and legible
            // whatever the screen does - the disc is sized from screen height at runtime.
            text.fontSize = 30;
            text.resizeTextForBestFit = true;
            text.resizeTextMinSize = 8;
            text.resizeTextMaxSize = 44;
            text.alignment = TextAnchor.MiddleCenter;
            // Fully opaque, unlike the HUD's own labels: this one is read at a glance with a thumb
            // beside it, over a fill that is itself over whatever the room happens to be.
            text.color = Color.white;
            text.text = label;
            text.raycastTarget = false;
            Stretch(text.GetComponent<RectTransform>());
        }

        // `overhang` is how far outside the parent this reaches, as a fraction of the parent - 0
        // fills it exactly, -0.07 makes a ring 7% proud all round. Zero for a free-standing disc
        // (the stick), which is positioned by TouchControls rather than stretched to anything.
        private static RectTransform MakeTouchDisc(Transform parent, string name, Sprite disc,
                                                   Color colour, float overhang = float.NaN)
        {
            GameObject go = new GameObject(name);
            go.transform.SetParent(parent, false);

            Image image = go.AddComponent<Image>();
            image.sprite = disc;
            image.color = colour;
            // See BuildTouchControls: this layer must be invisible to the EventSystem.
            image.raycastTarget = false;

            RectTransform rect = go.GetComponent<RectTransform>();

            if (float.IsNaN(overhang))
            {
                // FREE-STANDING: centre-anchored, because TouchControls positions and sizes it
                // directly as an offset from the middle of the canvas.
                rect.anchorMin = new Vector2(0.5f, 0.5f);
                rect.anchorMax = new Vector2(0.5f, 0.5f);
            }
            else
            {
                // STRETCHED TO ITS PARENT, and beyond it by `overhang`. Anchors rather than offsets
                // so the proportion survives a button of any size.
                rect.anchorMin = new Vector2(overhang, overhang);
                rect.anchorMax = new Vector2(1f - overhang, 1f - overhang);
                rect.offsetMin = Vector2.zero;
                rect.offsetMax = Vector2.zero;
            }

            rect.pivot = new Vector2(0.5f, 0.5f);
            return rect;
        }

        private static ControlHintDisplay BuildControlHints(Transform canvas, Camera playerCamera, BalloonTool swingTool,
                                              MonoBehaviour[] interactTargets)
        {
            Sprite disc = HintDiscSprite();

            GameObject root = new GameObject("ControlHints");
            root.transform.SetParent(canvas, false);
            RectTransform area = root.AddComponent<RectTransform>();
            area.anchorMin = Vector2.zero;
            area.anchorMax = Vector2.one;
            area.offsetMin = Vector2.zero;
            area.offsetMax = Vector2.zero;

            (CanvasGroup interactGroup, RectTransform interactRect) =
                MakeHintBadge(area, "InteractHint", disc);
            // The key itself, in the HUD's monospace face - the same one the iteration number and
            // the clock use, because this is the facility labelling its own equipment.
            GameObject glyphGO = new GameObject("Glyph");
            glyphGO.transform.SetParent(interactRect, false);
            Text glyph = glyphGO.AddComponent<Text>();
            glyph.font = UIFont();
            glyph.fontSize = 44;
            glyph.alignment = TextAnchor.MiddleCenter;
            glyph.color = Color.white;
            glyph.raycastTarget = false;
            glyph.text = "E";
            RectTransform glyphRect = glyph.GetComponent<RectTransform>();
            glyphRect.anchorMin = Vector2.zero;
            glyphRect.anchorMax = Vector2.one;
            glyphRect.offsetMin = Vector2.zero;
            glyphRect.offsetMax = Vector2.zero;

            (CanvasGroup swingGroup, RectTransform swingRect) = MakeHintBadge(area, "SwingHint", disc);
            GameObject mouseGO = new GameObject("Glyph");
            mouseGO.transform.SetParent(swingRect, false);
            Image mouse = mouseGO.AddComponent<Image>();
            mouse.sprite = MouseLeftIcon();
            mouse.color = Color.white;
            mouse.raycastTarget = false;
            mouse.preserveAspect = true;
            RectTransform mouseRect = mouse.GetComponent<RectTransform>();
            mouseRect.anchorMin = new Vector2(0.5f, 0.5f);
            mouseRect.anchorMax = new Vector2(0.5f, 0.5f);
            mouseRect.sizeDelta = new Vector2(48f, 48f);
            mouseRect.anchoredPosition = Vector2.zero;

            ControlHintDisplay display = root.AddComponent<ControlHintDisplay>();
            display.playerCamera = playerCamera;
            display.swingTool = swingTool;
            display.interactTargets = interactTargets;
            display.area = area;
            display.interactGroup = interactGroup;
            display.interactRect = interactRect;
            display.swingGroup = swingGroup;
            display.swingRect = swingRect;
            return display;
        }

        private static (CanvasGroup, RectTransform) MakeHintBadge(Transform parent, string name, Sprite disc)
        {
            GameObject go = new GameObject(name);
            go.transform.SetParent(parent, false);

            RectTransform rect = go.AddComponent<RectTransform>();
            // Centred anchors: ControlHintDisplay writes a screen position straight into
            // anchoredPosition, which only lines up if the anchor is the middle of the parent.
            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.sizeDelta = new Vector2(78f, 78f);

            CanvasGroup group = go.AddComponent<CanvasGroup>();
            group.alpha = 0f;
            // Never eats input: the end-cycle control is a real uGUI button, and a prompt that
            // swallowed clicks would be a bug that only shows up when both are on screen.
            group.blocksRaycasts = false;
            group.interactable = false;

            Image background = go.AddComponent<Image>();
            background.sprite = disc;
            // Grey and translucent - present enough to read against a white wall, quiet enough not
            // to become the thing you look at.
            background.color = new Color(0.25f, 0.25f, 0.27f, 0.78f);
            background.raycastTarget = false;

            return (group, rect);
        }

        private static (IterationLabel label, WakeUpSequence wakeUp, Transform canvas, CanvasGroup loading, CaptureRig capture) BuildUI(PlayerHand hand)
        {
            GameObject canvasGO = new GameObject("Canvas");
            Canvas canvas = canvasGO.AddComponent<Canvas>();
            canvas.renderMode = RenderMode.ScreenSpaceOverlay;
            // Scale with the screen rather than the default constant pixel size, which pins the
            // text to a fixed point size and leaves it tiny at 4K and oversized in a small window.
            CanvasScaler scaler = canvasGO.AddComponent<CanvasScaler>();
            scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;
            scaler.referenceResolution = new Vector2(1920f, 1080f);
            scaler.screenMatchMode = CanvasScaler.ScreenMatchMode.MatchWidthOrHeight;
            // Split the difference between matching width and height, so neither a wide nor a tall
            // window blows the UI up.
            scaler.matchWidthOrHeight = 0.5f;

            canvasGO.AddComponent<GraphicRaycaster>();

            // Built first so it sits at the back of the canvas: the iteration label and the timer
            // then draw ON TOP of the closed eyelids instead of being blacked out by them.
            WakeUpSequence wakeUp = BuildEyelids(canvasGO.transform);

            // THE LOADING SCREEN: the title screen's own photograph, drifting, instead of black.
            //
            // The cycle scenes load asynchronously and nothing can be shown until they arrive, so the
            // window was filled by shutting the eyelids - correct, and a black rectangle. Filling it
            // with the picture the menu already uses costs one Image and makes the wait look like part
            // of the game rather than like a hitch.
            //
            // BUILT LAST so it draws over the eyelids, which are shut underneath it the whole time.
            // Faster than the menu's drift by design: this is on screen for a few seconds, not for as
            // long as somebody leaves the title up, so the movement has to be visible immediately.
            GameObject loadGO = new GameObject("LoadingBackdrop");
            loadGO.transform.SetParent(canvasGO.transform, false);
            CanvasGroup loadGroup = loadGO.AddComponent<CanvasGroup>();
            loadGroup.blocksRaycasts = false;
            loadGroup.interactable = false;
            Stretch(loadGO.AddComponent<RectTransform>());

            GameObject loadImageGO = new GameObject("Image");
            loadImageGO.transform.SetParent(loadGO.transform, false);
            Image loadImage = loadImageGO.AddComponent<Image>();
            Sprite loadShot = AssetDatabase.LoadAssetAtPath<Sprite>(MenuBackgroundPath);
            loadImage.sprite = loadShot;
            // The same guard the menu's scrim needed: an Image with no sprite is a solid rectangle,
            // and a white one here would be a white flash on every start.
            loadImage.color = loadShot != null ? Color.white : new Color(0.05f, 0.05f, 0.06f, 1f);
            loadImage.raycastTarget = false;
            Stretch(loadImage.GetComponent<RectTransform>());
            MenuBackdrop loadDrift = loadImageGO.AddComponent<MenuBackdrop>();
            loadDrift.period = 13f;
            loadDrift.verticalPeriod = 19f;
            loadDrift.overscan = 0.10f;

            GameObject groupGO = new GameObject("IterationLabelGroup");
            groupGO.transform.SetParent(canvasGO.transform, false);
            CanvasGroup group = groupGO.AddComponent<CanvasGroup>();
            group.alpha = 0f;

            RectTransform rect = groupGO.AddComponent<RectTransform>();
            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            // Dead centre. It used to sit 150px above, which read as a subtitle floating over the
            // room; the label is the iteration announcing itself, so it belongs on the middle of
            // the screen with nothing else on it.
            rect.sizeDelta = new Vector2(1200f, 140f);
            rect.anchoredPosition = Vector2.zero;

            GameObject textGO = new GameObject("Label");
            textGO.transform.SetParent(groupGO.transform, false);
            Text text = textGO.AddComponent<Text>();
            text.font = UIFont();
            // Bigger than it was, because the letters are now spaced out (see IterationLabel) and
            // tracked-out text at 42 reads as small print rather than as a title card.
            text.fontSize = 54;
            text.alignment = TextAnchor.MiddleCenter;
            // Never wrap. The spaced-out string is full of spaces, so a rect a shade too narrow
            // would break the label across two lines mid-word - "ITERATIO / N 12".
            text.horizontalOverflow = HorizontalWrapMode.Overflow;
            text.verticalOverflow = VerticalWrapMode.Overflow;
            // Red, not white - the room walls are near-white, so white text is invisible.
            text.color = Color.red;
            RectTransform textRect = text.GetComponent<RectTransform>();
            textRect.anchorMin = Vector2.zero;
            textRect.anchorMax = Vector2.one;
            textRect.offsetMin = Vector2.zero;
            textRect.offsetMax = Vector2.zero;

            // CYCLE N, above the iteration and inside the SAME CanvasGroup so the two fade as one
            // card rather than as two announcements.
            //
            // Smaller than the iteration deliberately: the cycle is the frame and the iteration is
            // the subject. Anchored to the group's top edge and pushed clear of it, so the stack
            // stays centred on the screen as a whole.
            GameObject cycleGO = new GameObject("CycleLabel");
            cycleGO.transform.SetParent(groupGO.transform, false);
            Text cycleText = cycleGO.AddComponent<Text>();
            cycleText.font = UIFont();
            cycleText.fontSize = 34;
            cycleText.alignment = TextAnchor.MiddleCenter;
            cycleText.horizontalOverflow = HorizontalWrapMode.Overflow;
            cycleText.verticalOverflow = VerticalWrapMode.Overflow;
            cycleText.color = Color.red;
            RectTransform cycleRect = cycleText.GetComponent<RectTransform>();
            cycleRect.anchorMin = new Vector2(0f, 1f);
            cycleRect.anchorMax = new Vector2(1f, 1f);
            cycleRect.pivot = new Vector2(0.5f, 0.5f);
            cycleRect.sizeDelta = new Vector2(0f, 60f);
            cycleRect.anchoredPosition = new Vector2(0f, 42f);
            // Off until there has been more than one bed - IterationLabel.Show enables it. Cycle 1
            // says nothing, the way iteration 1 gets no reset announcement.
            cycleText.enabled = false;

            IterationLabel label = groupGO.AddComponent<IterationLabel>();
            label.canvasGroup = group;
            label.label = text;
            label.cycleLabel = cycleText;

            BuildSleepingGas(canvasGO.transform);
            GameObject timerGO = BuildCountdownTimer(canvasGO.transform);
            GameObject endCycleGO = BuildEndCycleControl(canvasGO.transform);
            GameObject carriedGO = BuildCarriedItems(canvasGO.transform, hand);

            // THE CAPTURE RIG, holding the three readouts above by reference. The prompts, the touch
            // layer and the two cameras are added by `WireCaptureRig` in `Build`, because none of
            // them exists yet at this point.
            CaptureRig capture = BuildCaptureRig(timerGO, endCycleGO, carriedGO, groupGO);

            // uGUI buttons do nothing without one of these in the scene, and NewScene's default
            // objects are only a camera and a light.
            GameObject eventSystem = new GameObject("EventSystem");
            eventSystem.AddComponent<UnityEngine.EventSystems.EventSystem>();
            eventSystem.AddComponent<UnityEngine.EventSystems.StandaloneInputModule>();

            return (label, wakeUp, canvasGO.transform, loadGroup, capture);
        }

        // THE RIG THAT MAKES A RECORDING A TRAILER: HUD off, camera off the player's head. See
        // `CaptureRig` for why it is not gated on `AcceptsInput` and why its two keys are not in
        // `InputBindings`.
        //
        // ITS OWN ROOT, NOT A CHILD OF THE CANVAS. It hides canvas children by deactivating them, and
        // an object that can deactivate its own parent's siblings is confusing enough without also
        // sitting among them. It is also not per-cycle: the HUD, the player and this all live in
        // `IterationRoom`, so the rig survives a cycle swap with its references intact.
        //
        // The tuned numbers live here rather than on the component, per CLAUDE.md SS2 - a capture rig
        // is still a mechanism, and how fast its camera flies is still a value.
        private static CaptureRig BuildCaptureRig(GameObject timer, GameObject endCycle,
                                                  GameObject carried, GameObject card)
        {
            GameObject go = new GameObject("CaptureRig");
            CaptureRig rig = go.AddComponent<CaptureRig>();

            // Everything that is a READOUT. The eyelids, the gas and the pause menu are deliberately
            // absent: the first two are the game rather than an overlay on it, and a hidden pause
            // menu is a game that looks broken when somebody presses Escape mid-take.
            rig.hud = new[] { timer, endCycle, carried };
            // The ITERATION / CYCLE card, on its own step - it is the one overlay that is also the
            // best single frame in the game.
            rig.cards = new[] { card };

            // A THIRD OF WALKING PACE. `walkSpeed` is 2.5 and a camera moving at it reads as a person
            // rather than as a camera; the scroll wheel takes it up when a shot needs to cover ground.
            rig.flySpeed = 1.6f;
            rig.boostMultiplier = 4f;
            rig.minSpeed = 0.15f;
            rig.maxSpeed = 12f;
            // Well under gameplay sensitivity, which is tuned for finding things in a hurry.
            rig.lookSensitivity = 0.6f;

            // A QUARTER OF THE RETREAT SPEED GOES UP. Enough to read as "backed off and slightly
            // high" per the shotlist without the shot visibly climbing.
            rig.dollyRiseRatio = 0.25f;
            // Same constant governs the ramp up on press and the ease down on release - see
            // `CaptureRig.HandleDolly`.
            rig.dollyEaseTime = 1.1f;

            return rig;
        }

        // The half of the wiring that cannot happen inside `BuildUI`: the prompts and the touch layer
        // are built after it returns, and the player camera after that again.
        private static void WireCaptureRig(CaptureRig rig, GameObject hints, GameObject touch,
                                           Camera playerCamera)
        {
            if (rig == null) return;

            var hidden = new System.Collections.Generic.List<GameObject>(rig.hud) { hints, touch };
            rig.hud = hidden.ToArray();

            rig.playerCamera = playerCamera;
            rig.captureCamera = BuildCaptureCamera(rig.transform, playerCamera);
        }

        // THE SECOND CAMERA, disabled until F10. Not parented to the player - the whole point is that
        // it leaves - and not carrying an `AudioListener`, because the scene already has exactly one
        // and a second is a warning on every frame plus a mix nobody chose.
        private static Camera BuildCaptureCamera(Transform parent, Camera playerCamera)
        {
            GameObject go = new GameObject("CaptureCamera");
            go.transform.SetParent(parent, false);

            Camera cam = go.AddComponent<Camera>();
            cam.enabled = false;
            // Optics are copied off the player camera at detach time (see `CaptureRig.SetDetached`),
            // so what is set here is only what a fresh Camera would otherwise get wrong.
            cam.nearClipPlane = playerCamera.nearClipPlane;
            cam.farClipPlane = playerCamera.farClipPlane;
            cam.fieldOfView = playerCamera.fieldOfView;

            // **THE OPPOSITE BODY TO THE PLAYER'S OWN CAMERA.** `BuildPlayer` masks out the world body
            // and keeps the headless one, because it is standing inside the other one's skull. A
            // camera that has flown away wants the reverse: the whole person, head included, exactly
            // as a mirror or a past self sees them. Without this the trailer's wide shots have a
            // decapitated player in them.
            cam.cullingMask &= ~(1 << EnsureLayer(PlayerBodyViewLayer));
            cam.cullingMask &= ~(1 << EnsureLayer(PlayerBodyShadowLayer));

            // The same pipeline treatment the player camera gets, or the footage stops looking like
            // the game: post-processing off would drop the volume stack the whole building is graded
            // through, and no AA on a room made of straight black panel joins crawls badly in motion.
            UniversalAdditionalCameraData data = go.AddComponent<UniversalAdditionalCameraData>();
            data.renderPostProcessing = true;
            data.antialiasing = AntialiasingMode.SubpixelMorphologicalAntiAliasing;

            return cam;
        }

        // Escape's overlay. Built after everything else on the canvas so it draws over the HUD,
        // the control prompts and the eyelids - a pause menu behind a closed eyelid would be a
        // strange thing to discover.
        private static void BuildPauseMenu(Transform canvas, FirstPersonController playerController)
        {
            GameObject root = new GameObject("PauseMenu");
            root.transform.SetParent(canvas, false);
            Stretch(root.AddComponent<RectTransform>());

            CanvasGroup group = root.AddComponent<CanvasGroup>();
            group.alpha = 0f;
            group.blocksRaycasts = false;
            group.interactable = false;

            // Heavier than the title screen's scrim: this one has to read as the game having
            // stopped, where the menu's only has to hold text off a picture.
            GameObject scrimGO = new GameObject("Scrim");
            scrimGO.transform.SetParent(root.transform, false);
            Image scrim = scrimGO.AddComponent<Image>();
            scrim.color = new Color(0f, 0f, 0f, 0.72f);
            // Left as a raycast target on purpose: it is what stops a click reaching the end-cycle
            // control sitting underneath it.
            scrim.raycastTarget = true;
            Stretch(scrim.GetComponent<RectTransform>());

            GameObject titleGO = new GameObject("Title");
            titleGO.transform.SetParent(root.transform, false);
            Text title = titleGO.AddComponent<Text>();
            title.font = UIFont();
            title.fontSize = 52;
            title.alignment = TextAnchor.MiddleCenter;
            title.color = Color.red;
            // Spaced out in the string, as everything else in this typeface is.
            title.text = "P A U S E D";
            Localize(title, "pause.title");
            title.horizontalOverflow = HorizontalWrapMode.Overflow;
            title.verticalOverflow = VerticalWrapMode.Overflow;
            title.raycastTarget = false;
            RectTransform titleRect = title.GetComponent<RectTransform>();
            titleRect.anchorMin = new Vector2(0.5f, 0.5f);
            titleRect.anchorMax = new Vector2(0.5f, 0.5f);
            titleRect.sizeDelta = new Vector2(1000f, 100f);
            titleRect.anchoredPosition = new Vector2(0f, 170f);

            // FOUR ROWS NOW, at the same 80 pitch the three had. RESTART CYCLE sits SECOND rather
            // than last: it is an action on the run like RESUME, where MAIN MENU and QUIT are ways
            // out of the game - and putting a destructive one at the bottom of a column is how it
            // gets clicked by somebody reaching for QUIT.
            Button resume = Localize(MakeMenuButton(root.transform, "ResumeButton", "RESUME", new Vector2(0f, 80f)), "pause.resume", "  ");
            Button restart = Localize(MakeMenuButton(root.transform, "RestartButton", "RESTART CYCLE", new Vector2(0f, 0f)), "pause.restart", "  ");
            Button toMenu = Localize(MakeMenuButton(root.transform, "MenuButton", "MAIN MENU", new Vector2(0f, -80f)), "pause.mainMenu", "  ");
            Button quit = Localize(MakeMenuButton(root.transform, "QuitButton", "QUIT", new Vector2(0f, -160f)), "menu.quit", "  ");

            // THE SETTINGS, below the buttons rather than above them: these are settings, not
            // actions, and the things a paused player most often wants stay at the top.
            //
            // **VOLUME IS HERE NOW as well as on the title screen** (2026-08-21, by request), and the
            // pause overlay is the place it was most missing: "too loud" is a thought a player has
            // while the PA is talking over them, and until now the only fix was quitting to the menu.
            // Both write the same `GameSettings.MasterVolume`, so neither can disagree with the other.
            //
            // ON THE SAME LEFT COLUMN AS THE BUTTONS. They were centre-anchored while the buttons hang
            // off the screen's left margin, so the two only lined up at 16:9 and read as two designs
            // at any other aspect - see MakeLeftColumn.
            Transform pauseColumn = MakeLeftColumn(root.transform, "Column");
            // Red on a near-black scrim, where the settings page is charcoal on a bright photograph.
            Color pauseInk = new Color(1f, 0.35f, 0.35f, 0.85f);

            (Slider sensitivity, Text sensitivityValue) =
                MakeSettingsSliderRow(pauseColumn, "Sensitivity", "MOUSE SENSITIVITY",
                                      "set.sensitivity", "0.00", -250f, pauseInk);
            (Slider volume, Text volumeValue) =
                MakeSettingsSliderRow(pauseColumn, "Volume", "VOLUME", "set.volume", "80%",
                                      -300f, pauseInk);

            GameObject hintGO = new GameObject("Hint");
            hintGO.transform.SetParent(root.transform, false);
            Text hint = hintGO.AddComponent<Text>();
            hint.font = UIFont();
            hint.fontSize = 18;
            hint.alignment = TextAnchor.MiddleCenter;
            hint.color = new Color(1f, 0.35f, 0.35f, 0.7f);
            hint.text = "[ESC] TO RESUME";
            hint.raycastTarget = false;
            RectTransform hintRect = hint.GetComponent<RectTransform>();
            hintRect.anchorMin = new Vector2(0.5f, 0.5f);
            hintRect.anchorMax = new Vector2(0.5f, 0.5f);
            hintRect.sizeDelta = new Vector2(600f, 36f);
            hintRect.anchoredPosition = new Vector2(0f, -370f);

            PauseMenu pause = root.AddComponent<PauseMenu>();
            pause.playerController = playerController;
            pause.group = group;
            pause.resumeButton = resume;
            pause.restartButton = restart;
            pause.menuButton = toMenu;
            pause.quitButton = quit;
            pause.sensitivitySlider = sensitivity;
            pause.sensitivityValue = sensitivityValue;
            pause.volumeSlider = volume;
            pause.volumeValue = volumeValue;
        }

        // The ending: a full-screen black scrim and a card over it. Two separate CanvasGroups
        // rather than one, because the whole shape of the ending is that the room goes first and
        // the card arrives afterwards, with a beat of nothing in between.
        //
        // Deliberately NOT the wake-up's eyelids, even though they are black panels over the same
        // canvas and would have been free. The lids blink, and the blink is the loop taking you -
        // it is the visual signature of the exact thing that has just failed. Reusing it here would
        // say the cycle turned over.
        private static EndingSequence BuildEndingScreen(Transform canvas)
        {
            GameObject root = new GameObject("EndingScreen");
            root.transform.SetParent(canvas, false);
            Stretch(root.AddComponent<RectTransform>());

            GameObject scrimGO = new GameObject("Scrim");
            scrimGO.transform.SetParent(root.transform, false);
            CanvasGroup scrimGroup = scrimGO.AddComponent<CanvasGroup>();
            scrimGroup.alpha = 0f;
            // Never a raycast target, unlike the pause scrim. There is nothing underneath left to
            // click by the time this is up, and blocking would only matter if something could still
            // be interacted with - which would be a bug, not a thing to defend against here.
            scrimGroup.blocksRaycasts = false;
            Stretch(scrimGO.AddComponent<RectTransform>());

            Image scrim = scrimGO.AddComponent<Image>();
            // Fully opaque, unlike the pause overlay's 0.72: this is not a layer over the room, it
            // is the room being gone.
            scrim.color = Color.black;
            scrim.raycastTarget = false;

            GameObject cardGO = new GameObject("Card");
            cardGO.transform.SetParent(root.transform, false);
            CanvasGroup cardGroup = cardGO.AddComponent<CanvasGroup>();
            cardGroup.alpha = 0f;
            cardGroup.blocksRaycasts = false;
            Stretch(cardGO.AddComponent<RectTransform>());

            GameObject headlineGO = new GameObject("Headline");
            headlineGO.transform.SetParent(cardGO.transform, false);
            Text headline = headlineGO.AddComponent<Text>();
            headline.font = UIFont();
            headline.fontSize = 52;
            headline.alignment = TextAnchor.MiddleCenter;
            headline.color = Color.red;
            // Filled in by EndingSequence, which spaces it out in the string. Seeded here only so
            // the object is not blank in the saved scene.
            headline.text = "C Y C L E   B R O K E N";
            Localize(headline, "end.title");
            headline.horizontalOverflow = HorizontalWrapMode.Overflow;
            headline.verticalOverflow = VerticalWrapMode.Overflow;
            headline.raycastTarget = false;
            RectTransform headlineRect = headline.GetComponent<RectTransform>();
            headlineRect.anchorMin = new Vector2(0.5f, 0.5f);
            headlineRect.anchorMax = new Vector2(0.5f, 0.5f);
            headlineRect.sizeDelta = new Vector2(1400f, 100f);
            headlineRect.anchoredPosition = new Vector2(0f, 30f);

            GameObject detailGO = new GameObject("Detail");
            detailGO.transform.SetParent(cardGO.transform, false);
            Text detail = detailGO.AddComponent<Text>();
            detail.font = UIFont();
            detail.fontSize = 22;
            detail.alignment = TextAnchor.MiddleCenter;
            // Dimmer than the headline, and not spaced out: this is the facility's record of the
            // run rather than its verdict on it, and it is the one number the player earned.
            detail.color = new Color(1f, 0.35f, 0.35f, 0.75f);
            detail.text = "ESCAPED ON ITERATION 1";
            detail.horizontalOverflow = HorizontalWrapMode.Overflow;
            detail.verticalOverflow = VerticalWrapMode.Overflow;
            detail.raycastTarget = false;
            RectTransform detailRect = detail.GetComponent<RectTransform>();
            detailRect.anchorMin = new Vector2(0.5f, 0.5f);
            detailRect.anchorMax = new Vector2(0.5f, 0.5f);
            detailRect.sizeDelta = new Vector2(1000f, 40f);
            detailRect.anchoredPosition = new Vector2(0f, -40f);

            // The run's total clock time, under the iteration count - the facility's record again,
            // not its verdict, so it gets the same treatment `detail` does rather than the
            // headline's. Smaller and dimmer still: this is the second line of a record, not a
            // second thing being announced.
            GameObject timeDetailGO = new GameObject("TimeDetail");
            timeDetailGO.transform.SetParent(cardGO.transform, false);
            Text timeDetail = timeDetailGO.AddComponent<Text>();
            timeDetail.font = UIFont();
            timeDetail.fontSize = 18;
            timeDetail.alignment = TextAnchor.MiddleCenter;
            timeDetail.color = new Color(1f, 0.35f, 0.35f, 0.6f);
            timeDetail.text = "TOTAL TIME 0:00";
            timeDetail.horizontalOverflow = HorizontalWrapMode.Overflow;
            timeDetail.verticalOverflow = VerticalWrapMode.Overflow;
            timeDetail.raycastTarget = false;
            RectTransform timeDetailRect = timeDetail.GetComponent<RectTransform>();
            timeDetailRect.anchorMin = new Vector2(0.5f, 0.5f);
            timeDetailRect.anchorMax = new Vector2(0.5f, 0.5f);
            timeDetailRect.sizeDelta = new Vector2(1000f, 34f);
            timeDetailRect.anchoredPosition = new Vector2(0f, -72f);

            // THE PER-CYCLE BREAKDOWN, in the same place `timeDetail` sits and taller. The two are
            // never on screen together - a one-cycle run gets the single TOTAL TIME line this card
            // has always had, and a run through several gets the table instead - so they can share
            // the space rather than one of them leaving a gap in the layout of the other.
            //
            // ANCHORED AT ITS TOP, which is what lets it grow downward as cycles are added without
            // anything above it moving: the rect is centred at -166 and 200 tall, so its first line
            // starts at -66 whether there are two cycles in it or five.
            GameObject breakdownGO = new GameObject("Breakdown");
            breakdownGO.transform.SetParent(cardGO.transform, false);
            Text breakdown = breakdownGO.AddComponent<Text>();
            breakdown.font = UIFont();
            breakdown.fontSize = 18;
            breakdown.alignment = TextAnchor.UpperCenter;
            // The same dim red as `timeDetail`, because it IS `timeDetail` when there is more than
            // one cycle to report - a record, not a verdict.
            breakdown.color = new Color(1f, 0.35f, 0.35f, 0.6f);
            // Padded columns need a monospace cell, which UIFont() is - see EndingSequence.Row.
            breakdown.lineSpacing = 1.25f;
            breakdown.text = string.Empty;
            breakdown.horizontalOverflow = HorizontalWrapMode.Overflow;
            breakdown.verticalOverflow = VerticalWrapMode.Overflow;
            breakdown.raycastTarget = false;
            RectTransform breakdownRect = breakdown.GetComponent<RectTransform>();
            breakdownRect.anchorMin = new Vector2(0.5f, 0.5f);
            breakdownRect.anchorMax = new Vector2(0.5f, 0.5f);
            breakdownRect.sizeDelta = new Vector2(1000f, 200f);
            breakdownRect.anchoredPosition = new Vector2(0f, -166f);

            // "CLICK TO CONTINUE", on a group of its own so it can arrive after the card rather than
            // with it - the numbers get their moment before anything asks the player to move on.
            GameObject promptGO = new GameObject("Prompt");
            promptGO.transform.SetParent(root.transform, false);
            CanvasGroup promptGroup = promptGO.AddComponent<CanvasGroup>();
            promptGroup.alpha = 0f;
            promptGroup.blocksRaycasts = false;
            Stretch(promptGO.AddComponent<RectTransform>());

            GameObject promptTextGO = new GameObject("PromptText");
            promptTextGO.transform.SetParent(promptGO.transform, false);
            Text prompt = promptTextGO.AddComponent<Text>();
            prompt.font = UIFont();
            prompt.fontSize = 18;
            prompt.alignment = TextAnchor.MiddleCenter;
            // Dimmer than the record above it: this is an instruction, not part of what the run said.
            prompt.color = new Color(1f, 0.35f, 0.35f, 0.55f);
            prompt.text = "CLICK TO CONTINUE";
            Localize(prompt, "end.clickContinue");
            prompt.horizontalOverflow = HorizontalWrapMode.Overflow;
            prompt.verticalOverflow = VerticalWrapMode.Overflow;
            prompt.raycastTarget = false;
            RectTransform promptRect = prompt.GetComponent<RectTransform>();
            promptRect.anchorMin = new Vector2(0.5f, 0.5f);
            promptRect.anchorMax = new Vector2(0.5f, 0.5f);
            promptRect.sizeDelta = new Vector2(800f, 34f);
            // Below the breakdown, which is 200 tall centred at -166 - so this clears its bottom edge.
            promptRect.anchoredPosition = new Vector2(0f, -300f);

            EndingSequence ending = root.AddComponent<EndingSequence>();
            ending.prompt = prompt;
            ending.promptGroup = promptGroup;
            ending.scrimGroup = scrimGroup;
            ending.cardGroup = cardGroup;
            ending.headline = headline;
            ending.detail = detail;
            ending.timeDetail = timeDetail;
            ending.breakdown = breakdown;
            ending.menuScene = "MainMenu";

            return ending;
        }

        // The room telling the player about the end-cycle control, on all four walls at once. Hung
        // in Room1 now and shown from iteration 2 - see the call site for why it moved out of Room3.
        //
        // World-space canvases hung just proud of the panelling rather than the panels themselves
        // being lit to spell it. That was the first idea and it does not survive contact with the
        // grid: a wall is 5 or 6 cells across by 4 tall, so panel-as-pixel gives a 6x4 display and
        // nothing legible can be written in it. What makes this still read as the wall rather than
        // as a poster is the dark plate behind the text - a section of white panelling switching to
        // near-black with red type on it is exactly what a display doing something looks like, and
        // it is the same red-on-near-black the HUD already uses.
        private static PanelMessage BuildWallMessage(Transform parent, float roomCenterZ)
        {
            GameObject root = new GameObject("WallMessage");
            root.transform.SetParent(parent, false);
            root.transform.localPosition = new Vector3(0f, 0f, roomCenterZ);

            // Proud of the panel faces, which sit on the room bound itself. Small enough to read as
            // printed on the wall, large enough that no camera angle z-fights with it.
            const float standoff = 0.05f;
            float halfDepth = RoomDepth / 2f;
            // Set so the plate's BOTTOM edge clears the door lamp, not merely the doorway. The
            // plate is 1.98m tall, so at 3.95 it spans 2.96..4.94: above the lamp at 2.725..2.835
            // by 0.125m and under the 5.408 ceiling by 0.47. At the 3.4 it was first built at it
            // covered the lamp on the north wall completely - and every room in the chain has that
            // lamp, so the number carried across the move to Room1 unchanged.
            //
            // All four faces share the height even though only the north one has a lamp under it:
            // two walls are in view at once from most of this room, and a sign that changes height
            // between them reads as a mistake.
            const float y = 3.95f;

            // All four walls. In Room1 the player wakes facing 180 degrees - down the room at the
            // SOUTH wall, away from the bed - and then turns for the door in the north one, so the
            // two walls that matter here are opposite each other. Covering all four costs nothing
            // extra and removes the question. It retires against the action (see PanelMessage), so
            // the sign is not paid for once per iteration for the rest of the run.
            //
            // Each canvas's forward (+Z) points INTO its wall, i.e. away from the room. That reads
            // backwards and it is the opposite of what was built first, which came out mirrored.
            //
            // The rule: a world-space canvas is legible when its forward matches the direction the
            // viewer is LOOKING, not when it points at the viewer. Unity's own default scene is the
            // proof - camera at z = -10 looking toward +Z, canvas at the origin unrotated, text the
            // right way round. So a wall message must face the same way as the eyes reading it, and
            // a player at the middle of the room looks outwards at every one of these.
            CanvasGroup[] faces = MakeFourWallFaces(root.transform, y, standoff, FillTerminationMessage);

            PanelMessage message = root.AddComponent<PanelMessage>();
            message.faces = faces;
            message.roomCenterZ = roomCenterZ;
            message.halfDepth = halfDepth;
            return message;
        }

        // Room4 - the room past the last door, and everything in it.
        //
        // The shell is a plain white cell like the other three (BuildShell), and that is the point
        // rather than a saving: the room the player finally gets out into looks exactly like the one
        // they have been trying to get out of. What makes it the ending is that NOTHING ELSE IS IN
        // IT. One object, and it is not there when they walk in - it comes up out of the floor, the
        // only thing in the game that does, so there is nothing to look for and nowhere else to go.
        //
        // The plinth is authored in its RAISED position and sunk at runtime by FinalRoomSequence.
        // Authoring it underground instead would leave a scene whose one prop is invisible and
        // impossible to check without pressing Play.
        private static FinalRoomSequence BuildFinalRoom(Transform parent, float roomCenterZ,
                                                        Material propMat, Door doorBehind,
                                                        WallPanelDisplay wallPanels,
                                                        CameraShaker cameraShaker, PlayerHand hand,
                                                        string cubeId, string sphereId, string prismId)
        {
            GameObject root = new GameObject("FinalRoom");
            root.transform.SetParent(parent, false);
            root.transform.localPosition = new Vector3(0f, 0f, roomCenterZ);

            // Waist height, so the plate on top is looked DOWN at from a 1.6m eye rather than
            // squared up to like the calibration wall's. The two plates are the same fixture at
            // opposite ends of the run, and the difference in how you stand over them is the only
            // thing separating "begin" from "end".
            const float plinthHeight = 1.05f;
            // WIDER THAN IT IS DEEP now, where it used to be a 1.15 square. Three recesses in a row
            // need a run of top surface, and a console you stand at the front of - sockets across the
            // back, the press at the front - is a clearer object than a square block with four things
            // crowded onto it. The depth is unchanged, so the walk round it is what it always was.
            const float plinthWidth = 1.70f;
            const float plinthDepth = 1.15f;
            const float plateProud = 0.02f;

            // The three recesses, in a row across the top. 0.46 apart spans 1.38 of the 1.55 of
            // usable plate. They used to sit in the back half with a press at the front; the press is
            // gone, so the row is centred and the console is the three things it asks for.
            const float slotPitch = 0.46f;
            const float slotSize = 0.26f;
            const float slotRowZ = 0f;

            Material plateMat = MakeColorMaterial("FinalPlate", new Color(0.05f, 0.05f, 0.055f));

            GameObject plinth = new GameObject("Plinth");
            plinth.transform.SetParent(root.transform, false);
            plinth.transform.localPosition = Vector3.zero;

            // Keeps its collider - it is a solid object in the middle of the room, and the player
            // has to walk round it to the plate. Rising through someone standing exactly on the
            // centre would shove them aside on the next frame, which is ugly but not reachable: the
            // rise starts as they clear the doorway, six metres away.
            Prim(PrimitiveType.Cube, "Body", plinth.transform,
                new Vector3(0f, plinthHeight / 2f, 0f),
                new Vector3(plinthWidth, plinthHeight, plinthDepth), propMat);

            // The dark inset the button sits in, so the top of the plinth reads as a switched-off
            // display among white surfaces - the same near-black as every groove in the building.
            Prim(PrimitiveType.Cube, "TopPlate", plinth.transform,
                new Vector3(0f, plinthHeight + plateProud / 2f, 0f),
                new Vector3(plinthWidth * 0.91f, plateProud, plinthDepth * 0.78f), plateMat,
                removeCollider: true);

            // THE THREE RECESSES, one per escape object. Built before the button so the row is the
            // first thing in the hierarchy as it is the first thing on the console.
            //
            // Shapes, not colours, are what say which is which - the same principle the cube room's
            // spec insists on - so each is cut to the silhouette of the thing it takes: a square hole,
            // a round hole, a triangular hole. The colour is carried by the rim on top of that,
            // because the three objects are distinct in both and there is no reason to spend only one.
            var slots = new FinalSlot[3];
            slots[0] = BuildFinalSlot(plinth.transform, "Slot_Cube", SlotShape.Square,
                new Vector3(-slotPitch, plinthHeight + plateProud, slotRowZ), slotSize,
                new Color(0.85f, 0.10f, 0.10f));
            slots[1] = BuildFinalSlot(plinth.transform, "Slot_Sphere", SlotShape.Round,
                new Vector3(0f, plinthHeight + plateProud, slotRowZ), slotSize,
                new Color(0.16f, 0.40f, 0.95f));
            slots[2] = BuildFinalSlot(plinth.transform, "Slot_Prism", SlotShape.Triangle,
                new Vector3(slotPitch, plinthHeight + plateProud, slotRowZ), slotSize,
                new Color(0.95f, 0.78f, 0.12f));

            // Which object each recess takes, handed in rather than written here, because two of the
            // three do not exist yet and an empty id is the honest way to say that: an undeclared slot
            // accepts nothing, prompts for nothing, and is skipped by FinalSlot.AllFilled.
            slots[0].acceptedItemId = cubeId;
            slots[1].acceptedItemId = sphereId;
            slots[2].acceptedItemId = prismId;

            // NO BUTTON. There was one here - a plate that ended the game on a single press - and
            // three recesses that each want a named object say everything it said, in a room the
            // player now has to reach with all three inside a running sixty seconds.

            // NO ERROR SIGN ON THE WALLS. It was four wall-sized canvases like Room3's message, and
            // that was the wrong instrument: a sign is something the room PUTS UP, and a facility
            // that can still put a sign up has not failed. The word lives on the panels themselves
            // now - every one of them a screen showing a test card with ERROR on it - so the room
            // does not report the fault, it IS the fault. See WallPanelDisplay.
            // THE CONSOLE IS A RewardPlinth, the same fixture the other three rooms pay out on. It
            // rises when the player reaches Room4 and sinks when the loop takes them back - which is
            // only a question now that the clock runs through this room. The old rise was a coroutine
            // fired by an event that could happen once; an iteration can end in here.
            RewardPlinth console = plinth.AddComponent<RewardPlinth>();
            console.plinth = plinth.transform;
            // Clears the floor by a hair, so nothing shows through the slab before it is meant to.
            console.riseHeight = plinthHeight + plateProud + 0.06f;
            console.riseSeconds = 2.4f;

            FinalRoomSequence sequence = root.AddComponent<FinalRoomSequence>();
            sequence.console = console;
            sequence.slots = slots;
            foreach (FinalSlot slot in slots) { slot.sequence = sequence; slot.hand = hand; }
            sequence.doorBehind = doorBehind;
            sequence.wallPanels = wallPanels;
            sequence.cameraShaker = cameraShaker;
            // TEN SECONDS from the press to the scrim starting, and that is a floor rather than a
            // pause: the door takes 1s to seal and the panels take glitchOnset 6.5s to fail across
            // the whole building. At the 3.4s this was first built at, all of that was still
            // arriving when the screen went black. The room has to be SEEN broken, or the last
            // thing the player did has no visible consequence.
            sequence.breakDuration = 10f;

            return sequence;
        }

        // Which silhouette a recess is cut to. Named rather than passed as a mesh, because the
        // caller is stating what the hole IS for, and where that mesh comes from is this file's
        // problem - two of the three are Unity primitives and the third has to be built.
        // `Dish` is the odd one out and says so: the other three are FLAT SILHOUETTES faked into
        // reading as wells, and this is a real hemispherical cavity with real geometry. Room2-0 needed
        // it because a flat disc says "something round belongs here" and the room has to say
        // "a BILLIARD BALL belongs here" - a bowl cut to the ball's own radius is the only shape that
        // can only be for a ball.
        private enum SlotShape { Square, Round, Triangle, Dish }

        // One recess: a coloured rim with a darker hole inside it, and a seat at the bottom for
        // whatever goes in.
        //
        // NOT A REAL HOLE, because there is no CSG here and the top plate is one box. What reads as
        // depth is the pair: a rim standing 12mm proud of the plate and a near-black floor 4mm above
        // it, so the eye takes the dark shape as the inside of a well. That is the same trick the
        // plinth's own TopPlate already plays - near-black among white surfaces reads as a cavity.
        // `reachCentre` / `reachSize` default to cycle 1's console, which is a 1.15m-deep block
        // approached from -Z. Room2-0's pedestals are 0.80 deep and approached from +Z, so the volume
        // has to lean the other way - a reach biased toward the side the player is NOT on is the exact
        // fault that made this recess unreachable on its first build.
        // `dishPlateHalf` is the cap's footprint, and only `SlotShape.Dish` uses it: that shape
        // replaces the caller's top plate rather than sitting on one, because a cavity has to have
        // material taken OUT of the thing above it and this project has no CSG. Everything else
        // ignores it.
        private static FinalSlot BuildFinalSlot(Transform parent, string name, SlotShape shape,
                                                Vector3 localTop, float size, Color accent,
                                                Vector3 reachCentre = default,
                                                Vector3 reachSize = default,
                                                Vector2 dishPlateHalf = default)
        {
            const float rimProud = 0.012f;
            const float floorProud = 0.004f;
            const float rimInset = 0.80f;   // the hole, as a fraction of the rim

            GameObject root = new GameObject(name);
            root.transform.SetParent(parent, false);
            root.transform.localPosition = localTop;

            // ONE material for all three rims. Each says something different about itself - idle,
            // ready, filled - and says it through a property block, which is what FinalSlot drives.
            Material rimMat = MakeEmissiveMaterial("FinalSlotRim", Color.white, 1f);
            Material holeMat = MakeColorMaterial("FinalSlotHole", new Color(0.03f, 0.03f, 0.035f));

            GameObject rim;
            GameObject seat = new GameObject("Seat");
            seat.transform.SetParent(root.transform, false);

            if (shape == SlotShape.Dish)
            {
                float bowl = size / 2f;
                // Enough material under the pole that the cap is a solid thing with a hole in it
                // rather than a shell that meets itself at a point.
                float thickness = bowl + 0.006f;

                // THE CAP: the top of the pedestal, with the bowl taken out of the middle of it. One
                // mesh, because the plate's top face and the bowl's inside are the same surface -
                // a hole is not a separate object, it is the absence of one.
                GameObject cap = new GameObject("Cap");
                cap.transform.SetParent(root.transform, false);
                cap.AddComponent<MeshFilter>().sharedMesh = BallSocketMesh(
                    $"BallSocket_{Mathf.RoundToInt(bowl * 1000f)}"
                    + $"_{Mathf.RoundToInt(dishPlateHalf.x * 1000f)}"
                    + $"x{Mathf.RoundToInt(dishPlateHalf.y * 1000f)}",
                    dishPlateHalf.x, dishPlateHalf.y, bowl, thickness);
                cap.AddComponent<MeshRenderer>().sharedMaterial = holeMat;

                // THE RING ROUND THE MOUTH, and it is the lit part. `FinalSlot` paints one renderer
                // to say idle / ready / filled / refused, and painting the whole cap would light a
                // dark inset the size of the pedestal top - the mark has to be AT the hole, which is
                // the thing the player is aiming at.
                GameObject ringGO = new GameObject("Rim");
                ringGO.transform.SetParent(root.transform, false);
                // A hair proud, or it z-fights the cap's top face along the whole ring.
                ringGO.transform.localPosition = new Vector3(0f, 0.0015f, 0f);
                ringGO.AddComponent<MeshFilter>().sharedMesh = AnnulusMesh(
                    $"BallSocketRing_{Mathf.RoundToInt(bowl * 1000f)}", bowl, bowl + 0.026f);
                ringGO.AddComponent<MeshRenderer>().sharedMaterial = rimMat;
                rim = ringGO;

                // AT THE MOUTH, WHICH IS THE BOWL'S OWN CENTRE - so a ball seated here sits exactly
                // half in and half out, the way a ball rests in a dish cut to its own radius. That is
                // the whole reason the bowl is a hemisphere and not a cup.
                seat.transform.localPosition = Vector3.zero;
            }
            else
            {
                rim = ShapePrim(shape, "Rim", root.transform,
                    new Vector3(0f, rimProud / 2f, 0f), new Vector3(size, rimProud, size), rimMat);
                ShapePrim(shape, "Hole", root.transform,
                    new Vector3(0f, floorProud / 2f + rimProud * 0.35f, 0f),
                    new Vector3(size * rimInset, floorProud, size * rimInset), holeMat);

                // Where the object lands. At the floor of the well rather than on the plate, so an
                // inserted object sits IN the recess - the seat is the socket CarryableItem parents to.
                seat.transform.localPosition = new Vector3(0f, rimProud * 0.35f + floorProud, 0f);
            }

            // THE REACH, and it has to reach past the console rather than sit over it. The recesses
            // are in the TOP of a 1.15m-deep block, so a volume centred on a recess is inside the
            // block: the nearest a player can physically get is pressed against the front face, which
            // is 0.45m short of where the first version's box began. It was unreachable, and only
            // standing at it in play found that - the geometry all measured correctly.
            //
            // Biased toward -Z, which is the way in from Room3, and wide enough that the three boxes
            // overlap. Overlapping is right: a player at the middle of the console is at all three
            // recesses, and which one answers is decided by what is in their hand.
            BoxCollider reach = root.AddComponent<BoxCollider>();
            reach.isTrigger = true;
            reach.center = reachCentre == Vector3.zero ? new Vector3(0f, -0.55f, -0.45f) : reachCentre;
            reach.size = reachSize == Vector3.zero ? new Vector3(1.5f, 2.6f, 2.7f) : reachSize;

            FinalSlot slot = root.AddComponent<FinalSlot>();
            slot.seat = seat.transform;
            slot.rimRenderer = rim.GetComponent<Renderer>();
            slot.idleColor = accent * 0.35f;
            slot.readyColor = accent;
            slot.filledColor = accent;
            slot.audioSource = MakeSource(root.transform, "SlotAudio", 1f, 0.8f);
            slot.insertClip = LoadClip(SfxDir, "sfx_floor_button_press");
            // acceptedItemId is deliberately left EMPTY. None of the three escape objects exists as
            // a carryable yet, and a slot that names an id nothing wears would prompt for a press
            // that cannot succeed. See TODO.md.
            return slot;
        }

        // A BALL SOCKET: a rectangular cap with a hemispherical bowl sunk into the middle of it.
        //
        // Its origin is the BOWL'S CENTRE, which is also the plate's top plane - so the caller places
        // it at the height the pedestal's top surface should be and everything else follows.
        //
        // **EVERY FACE IS DOUBLE-SIDED**, wound both ways with opposite normals, which is the same
        // thing `FlatPanelMesh` does and for a better reason here: a hand-derived winding is the one
        // kind of mistake in this file that cannot be checked without rendering it, and the cost is
        // nothing. Nothing is lost to z-fighting either - of any coincident pair exactly one is
        // front-facing from any camera, so the other is culled rather than fighting. The back faces
        // are all inside a sealed box (the cap's own walls and the pedestal body under it) and are
        // never seen.
        private static Mesh BallSocketMesh(string assetName, float halfX, float halfZ,
                                           float bowlRadius, float thickness)
        {
            return SaveGeneratedMesh(assetName, () =>
            {
                const int segments = 48;
                const int rings = 10;

                var verts = new System.Collections.Generic.List<Vector3>();
                var norms = new System.Collections.Generic.List<Vector3>();
                var tris = new System.Collections.Generic.List<int>();

                void Face(Vector3[] corners, Vector3 n)
                {
                    for (int side = 0; side < 2; side++)
                    {
                        int o = verts.Count;
                        foreach (Vector3 c in corners) { verts.Add(c); norms.Add(side == 0 ? n : -n); }
                        for (int i = 1; i + 1 < corners.Length; i++)
                        {
                            if (side == 0) { tris.Add(o); tris.Add(o + i); tris.Add(o + i + 1); }
                            else { tris.Add(o); tris.Add(o + i + 1); tris.Add(o + i); }
                        }
                    }
                }

                // THE ANGLES ROUND THE CAP, and the four CORNERS are in the list on purpose: without
                // them a segment can straddle a corner, and the side wall built on it is a single
                // non-planar quad bridging two faces of the box.
                var angles = new System.Collections.Generic.List<float>();
                for (int i = 0; i < segments; i++) angles.Add(i / (float)segments * Mathf.PI * 2f);
                angles.Add(Mathf.Atan2(halfZ, halfX));
                angles.Add(Mathf.Atan2(halfZ, -halfX));
                angles.Add(Mathf.Atan2(-halfZ, -halfX) + Mathf.PI * 2f);
                angles.Add(Mathf.Atan2(-halfZ, halfX) + Mathf.PI * 2f);
                angles.Sort();

                // Where a ray at this angle leaves the rectangle.
                Vector3 OnEdge(float a)
                {
                    float c = Mathf.Cos(a), s = Mathf.Sin(a);
                    float t = Mathf.Min(halfX / Mathf.Max(0.0001f, Mathf.Abs(c)),
                                        halfZ / Mathf.Max(0.0001f, Mathf.Abs(s)));
                    return new Vector3(c * t, 0f, s * t);
                }
                Vector3 OnMouth(float a) =>
                    new Vector3(Mathf.Cos(a) * bowlRadius, 0f, Mathf.Sin(a) * bowlRadius);

                for (int i = 0; i < angles.Count; i++)
                {
                    float a0 = angles[i], a1 = angles[(i + 1) % angles.Count];
                    Vector3 e0 = OnEdge(a0), e1 = OnEdge(a1);
                    Vector3 m0 = OnMouth(a0), m1 = OnMouth(a1);

                    // The top face: the strip between the mouth of the bowl and the edge of the cap.
                    Face(new[] { m0, m1, e1, e0 }, Vector3.up);

                    // The side wall under that strip. Its normal is the BOX face it lies on, decided
                    // from the midpoint - which is unambiguous because the corners are vertices.
                    Vector3 mid = (e0 + e1) * 0.5f;
                    Vector3 outward = Mathf.Abs(Mathf.Abs(mid.x) - halfX) < 0.0005f
                        ? new Vector3(Mathf.Sign(mid.x), 0f, 0f)
                        : new Vector3(0f, 0f, Mathf.Sign(mid.z));
                    Vector3 down = Vector3.down * thickness;
                    Face(new[] { e0, e1, e1 + down, e0 + down }, outward);
                }

                // THE BOWL. Latitude bands from the mouth down to the pole, on the sphere centred on
                // this mesh's own origin - so a vertex's position IS its outward direction and the
                // face the player sees, which is the INSIDE, takes the negative of it.
                for (int r = 0; r < rings; r++)
                {
                    float lat0 = r / (float)rings * Mathf.PI * 0.5f;
                    float lat1 = (r + 1) / (float)rings * Mathf.PI * 0.5f;
                    float r0 = Mathf.Cos(lat0) * bowlRadius, y0 = -Mathf.Sin(lat0) * bowlRadius;
                    float r1 = Mathf.Cos(lat1) * bowlRadius, y1 = -Mathf.Sin(lat1) * bowlRadius;

                    for (int i = 0; i < angles.Count; i++)
                    {
                        float a0 = angles[i], a1 = angles[(i + 1) % angles.Count];
                        Vector3 p00 = new Vector3(Mathf.Cos(a0) * r0, y0, Mathf.Sin(a0) * r0);
                        Vector3 p01 = new Vector3(Mathf.Cos(a1) * r0, y0, Mathf.Sin(a1) * r0);
                        Vector3 p10 = new Vector3(Mathf.Cos(a0) * r1, y1, Mathf.Sin(a0) * r1);
                        Vector3 p11 = new Vector3(Mathf.Cos(a1) * r1, y1, Mathf.Sin(a1) * r1);

                        // The last band closes on the pole, where both inner points are the same
                        // vertex - a triangle rather than a quad, so no zero-area faces are emitted.
                        Vector3 n = -((p00 + p01 + p10 + p11) * 0.25f).normalized;
                        if (r1 < 0.0001f) Face(new[] { p00, p01, new Vector3(0f, y1, 0f) }, n);
                        else Face(new[] { p00, p01, p11, p10 }, n);
                    }
                }

                var mesh = new Mesh { name = assetName };
                mesh.indexFormat = verts.Count > 65000
                    ? UnityEngine.Rendering.IndexFormat.UInt32
                    : UnityEngine.Rendering.IndexFormat.UInt16;
                mesh.SetVertices(verts);
                mesh.SetNormals(norms);
                mesh.SetTriangles(tris, 0);
                mesh.RecalculateBounds();
                return mesh;
            });
        }

        // A FLAT RING, lying in the XZ plane about its own origin. The lit mark round the mouth of a
        // ball socket, and double-sided for the reason the socket is.
        private static Mesh AnnulusMesh(string assetName, float inner, float outer)
        {
            return SaveGeneratedMesh(assetName, () =>
            {
                const int segments = 48;
                var verts = new System.Collections.Generic.List<Vector3>();
                var norms = new System.Collections.Generic.List<Vector3>();
                var tris = new System.Collections.Generic.List<int>();

                for (int i = 0; i < segments; i++)
                {
                    float a0 = i / (float)segments * Mathf.PI * 2f;
                    float a1 = (i + 1) / (float)segments * Mathf.PI * 2f;
                    Vector3 i0 = new Vector3(Mathf.Cos(a0) * inner, 0f, Mathf.Sin(a0) * inner);
                    Vector3 i1 = new Vector3(Mathf.Cos(a1) * inner, 0f, Mathf.Sin(a1) * inner);
                    Vector3 o0 = new Vector3(Mathf.Cos(a0) * outer, 0f, Mathf.Sin(a0) * outer);
                    Vector3 o1 = new Vector3(Mathf.Cos(a1) * outer, 0f, Mathf.Sin(a1) * outer);

                    for (int side = 0; side < 2; side++)
                    {
                        int o = verts.Count;
                        foreach (Vector3 c in new[] { i0, i1, o1, o0 })
                        {
                            verts.Add(c);
                            norms.Add(side == 0 ? Vector3.up : Vector3.down);
                        }
                        if (side == 0) { tris.Add(o); tris.Add(o + 1); tris.Add(o + 2); tris.Add(o); tris.Add(o + 2); tris.Add(o + 3); }
                        else { tris.Add(o); tris.Add(o + 2); tris.Add(o + 1); tris.Add(o); tris.Add(o + 3); tris.Add(o + 2); }
                    }
                }

                var mesh = new Mesh { name = assetName };
                mesh.SetVertices(verts);
                mesh.SetNormals(norms);
                mesh.SetTriangles(tris, 0);
                mesh.RecalculateBounds();
                return mesh;
            });
        }

        // `bevelled` swaps the primitive for a generated chamfered version of the same silhouette.
        // Only the three escape objects ask for it - the recesses they go into keep the plain
        // shapes, because a hole is read as an outline and a chamfer on one is detail nobody looks
        // at. See BevelledPrismMesh for what the chamfer buys and what it costs.
        private static GameObject ShapePrim(SlotShape shape, string name, Transform parent,
                                            Vector3 localPos, Vector3 localScale, Material mat,
                                            bool keepCollider = false, bool bevelled = false)
        {
            if (bevelled)
            {
                GameObject bev = new GameObject(name);
                bev.transform.SetParent(parent, false);
                bev.transform.localPosition = localPos;
                bev.transform.localScale = localScale;
                bev.AddComponent<MeshFilter>().sharedMesh = BevelledPrismMesh(shape, 0.06f);
                bev.AddComponent<MeshRenderer>().sharedMaterial = mat;
                if (keepCollider) bev.AddComponent<BoxCollider>();
                return bev;
            }

            if (shape == SlotShape.Square)
                return Prim(PrimitiveType.Cube, name, parent, localPos, localScale, mat,
                            removeCollider: !keepCollider);

            if (shape == SlotShape.Round)
                // A Unity cylinder is 2 units tall at scale 1, so its Y has to be halved to mean the
                // same thing the cube's does. Everything else here states a thickness in metres.
                return Prim(PrimitiveType.Cylinder, name, parent, localPos,
                    new Vector3(localScale.x, localScale.y * 0.5f, localScale.z), mat,
                    removeCollider: !keepCollider);

            GameObject go = new GameObject(name);
            go.transform.SetParent(parent, false);
            go.transform.localPosition = localPos;
            go.transform.localScale = localScale;
            // Chamfer 0: the same three-sided prism this always used, minus the inverted caps. Unity
            // has no triangular primitive, so this is the one shape of the three that has always had
            // to be generated.
            go.AddComponent<MeshFilter>().sharedMesh = BevelledPrismMesh(shape, 0f);
            go.AddComponent<MeshRenderer>().sharedMaterial = mat;
            // A box round a prism. The shape is what the player reads; what they bump into can be the
            // bounding box, and a MeshCollider for a triangle you walk past is a cost with no payer.
            if (keepCollider) go.AddComponent<BoxCollider>();
            return go;
        }

        // ONE GENERATOR FOR EVERY PRISM IN THE GAME: an n-gon extruded, optionally with its top and
        // bottom rims chamfered. Square is a 4-gon, Triangle a 3-gon, Round a 48-gon.
        //
        // It replaces TriangularPrismMesh, which it is a superset of at chamfer 0 - AND WHICH HAD
        // BOTH CAPS WOUND INSIDE OUT. Unity's front face is the one whose cross(v1-v0, v2-v0) points
        // along the normal (checked against the built-in Quad, whose winding and normals are known),
        // and that prism's caps pointed into the solid while its sides pointed out. The caps were
        // therefore backface-culled: looking down at the yellow triangle you were seeing through its
        // top face to the inside of the far side. It survived unnoticed because the material was
        // emissive at 2.4 and saturated, so the inside of the shape is very nearly the same image as
        // the outside - and it would NOT survive the polished metal above, which is what sent
        // anybody to look. Anything generated here now gets its winding checked against that Quad.
        //
        // WHY A CHAMFER AT ALL. A Unity cube has six flat faces meeting at perfectly sharp edges, so
        // under any lighting the whole of each face is one shade and the object is three flat tones
        // in a row. That is what makes a primitive look like a primitive, and no material fixes it,
        // because there is no geometry near the edge for a highlight to run along. A 6% chamfer puts
        // a narrow band at every rim facing halfway between two faces, and on a polished metal that
        // band catches a bright line that moves as the player turns. It is the cheapest thing in
        // rendering that reads as "manufactured" rather than "default".
        //
        // The same generator handles Round, which lets the three actually match: a puck with a
        // machined rim beside a chamfered cube beside a chamfered prism reads as one set of objects
        // from one factory, where a Unity cylinder's razor rim next to a chamfered cube does not.
        //
        // SMOOTHING IS PER SHAPE. Square and Triangle give every face its own vertices, so the edges
        // stay hard - the existing prism's rule, and a chamfer whose bands got smoothed into the
        // faces would be a lumpy cube rather than a bevelled one. Round shares its side vertices all
        // the way round, so RecalculateNormals averages across the barrel and the chamfers and the
        // puck comes out genuinely round instead of a 48-sided drum.
        //
        // SAVED AS AN ASSET, for the reason TriangularPrismMesh gives: a Mesh made with `new Mesh()`
        // and assigned in a scene is a runtime object with no home, and the scene serialises a
        // reference to nothing.
        //
        // NORMALISED TO A UNIT BOUNDING BOX like the prism it generalises, so a localScale of 0.30
        // still means 0.30 ACROSS for every one of the three. The barrel ring is the widest part, so
        // it is the ring the bounds are taken from.
        // EVERY BIT A GHOST WILL EVER READ, CHECKED AT BUILD TIME.
        //
        // `RecordedFrame.signals` is one `uint`, so an interactable's index IS its bit and there are
        // 32 of them. `PlayerRecorder.SampleSignals` clamps to that width and DROPS the rest, which
        // is the correct thing for it to do at runtime and a terrible way to find out: the 33rd
        // fixture simply never records, the ghosts never operate it, and nothing about the room it is
        // in looks wrong. Said here instead, where the array is known exactly and a build log is
        // already being read.
        //
        // Two more faults are the same shape and cost nothing to catch alongside it. A NULL entry is
        // a bit that can never be set - usually a builder that returned null because its object was
        // not built - and it silently shifts nothing, so it is a wasted bit rather than a corruption.
        // A DUPLICATE entry is worse: one fixture on two bits, where the second bit's rising edge
        // fires a second time on a ghost that only ever did the thing once.
        // **EVERY PROMPT ANCHOR, CHECKED AGAINST THE SOLID THINGS THAT ARE NOT FORGIVEN.**
        //
        // Written 2026-08-29 after the same bug shipped TWICE in two days, and both times it was
        // found by a person playing rather than by anything here.
        //
        // The shape of it: `PlayerLookup.InView` refuses a press whose anchor is behind geometry, and
        // it forgives the fixture's OWN geometry by walking up from the anchor to the nearest
        // `IInteractHintTarget`. A fixture that implements no such interface - `WaterTank` is a
        // `RoomCondition` - resolves to the anchor itself, so its own body is not forgiven and **it
        // occludes its own prompt.** Play reported that as "you have to jump to interact with it",
        // which is a description of a raycast clearing a rim and reads like nothing at all.
        //
        // **THE PREDICATE IS: BURIED IN A SOLID THE FIXTURE DOES NOT OWN, DEEPER THAN THE RAY STOPS
        // SHORT.** An anchor that far inside is occluded from essentially every angle - no camera
        // position helps, short of getting inside the collider.
        //
        // **THE FIRST VERSION LEFT THE SECOND HALF OFF AND WAS 39/39 NOISE.** It flagged every object
        // resting ON a surface, because a carryable's anchor is its own origin and its `floorY` is
        // zero - so the anchor sits on the floor plane, technically inside the floor's bounds, and
        // `Occluded` already forgives precisely that (`SurfaceClearance`). A check that does not know
        // what has already been fixed reports the fix.
        //
        // **IT DOES NOT CATCH EVERYTHING, and saying so is the point.** An anchor a centimetre in
        // FRONT of its own unforgiven body passes here and still fails from a low angle. This is the
        // sharp end of the class, not the whole of it - a player is still the instrument for the rest.
        // The same number `PlayerLookup.SurfaceClearance` uses, restated here because that one is
        // private runtime code and a build check that reached into it would break the moment either
        // moved. If they ever disagree this check gets quieter, never louder - which is the direction
        // a duplicated constant should fail in.
        private const float AnchorSurfaceClearance = 0.05f;

        private static void CheckHintAnchors()
        {
            var colliders = new System.Collections.Generic.List<Collider>();
            foreach (GameObject root in SceneManager.GetActiveScene().GetRootGameObjects())
                colliders.AddRange(root.GetComponentsInChildren<Collider>(true));

            int checked_ = 0, bad = 0;

            foreach (GameObject root in SceneManager.GetActiveScene().GetRootGameObjects())
                foreach (MonoBehaviour behaviour in root.GetComponentsInChildren<MonoBehaviour>(true))
                {
                    if (!(behaviour is IInteractHintTarget target)) continue;

                    Transform anchor = target.HintAnchor;
                    if (anchor == null) continue;
                    checked_++;

                    // The same resolution `PlayerLookup.OwnerObject` performs: the nearest ancestor
                    // that claims the press. Duplicated rather than shared because that one is
                    // runtime code and this is a build check, and a check that calls the thing it is
                    // checking proves nothing.
                    var owner = anchor.GetComponentInParent<IInteractHintTarget>() as Component;
                    Transform ownerTransform = owner != null ? owner.transform : anchor;

                    foreach (Collider c in colliders)
                    {
                        if (c == null || c.isTrigger || !c.enabled) continue;
                        if (c.transform.IsChildOf(ownerTransform)) continue;
                        // The player's own capsule is never an occluder either.
                        if (c.transform.root.CompareTag("Player")) continue;
                        if (!c.bounds.Contains(anchor.position)) continue;

                        // **AND DEEPER IN THAN THE RAY'S OWN CLEARANCE, or it is not a problem.**
                        //
                        // The first run of this check reported 39 of 110 and every one was the same
                        // thing: an object RESTING ON a surface. A carryable's anchor is its own
                        // origin and its `floorY` is how far that origin sits above the floor - zero
                        // for a chess piece, an axe, a bucket - so the anchor is on the floor plane
                        // and inside the floor's bounds by a hair.
                        //
                        // `PlayerLookup.Occluded` already forgives exactly that: it drops the last
                        // `SurfaceClearance` of the cast, because the surface a thing stands on is not
                        // hiding it. A check that does not know about that mitigation reports the
                        // thing it fixed, which is worse than reporting nothing - a warning list that
                        // is 39/39 noise is a warning list nobody reads.
                        //
                        // So the question is not "is the anchor inside" but "is it buried DEEPER than
                        // the ray stops short". Measured off the bounds rather than the mesh, which is
                        // conservative in the safe direction: an AABB is never smaller than the shape.
                        Vector3 lo = anchor.position - c.bounds.min;
                        Vector3 hi = c.bounds.max - anchor.position;
                        float buried = Mathf.Min(
                            Mathf.Min(lo.x, hi.x), Mathf.Min(Mathf.Min(lo.y, hi.y), Mathf.Min(lo.z, hi.z)));
                        if (buried <= AnchorSurfaceClearance) continue;

                        bad++;
                        Debug.LogWarning(
                            $"[SceneBuilder] PROMPT ANCHOR INSIDE UNFORGIVEN GEOMETRY: "
                          + $"{behaviour.GetType().Name} on '{behaviour.name}' has its anchor "
                          + $"'{anchor.name}' at {anchor.position} inside the collider on "
                          + $"'{c.name}', which is not under '{ownerTransform.name}'. "
                          + "`PlayerLookup.InView` will refuse this press from most angles - the "
                          + "symptom is a prompt that only appears if the player jumps or crouches. "
                          + "Fix by moving the anchor clear, or by passing the owning fixture to the "
                          + "`InView(anchor, owner)` overload.");
                        break;
                    }
                }

            Debug.Log($"[SceneBuilder] Hint anchors checked: {checked_}, {bad} inside geometry their "
                    + "own fixture does not own. Anything but 0 is a prompt the player has to find a "
                    + "camera angle for.");
        }

        private static void CheckGhostSignals(string cycleName, GhostInteractable[] signals)
        {
            if (signals == null) return;

            if (signals.Length > 32)
            {
                Debug.LogError($"[SceneBuilder] {cycleName} wires {signals.Length} ghost interactables, "
                    + "and RecordedFrame.signals is a uint - 32 is the hard cap. Everything from index "
                    + $"32 on ({signals[32]?.name ?? "null"} first) is dropped by "
                    + "PlayerRecorder.SampleSignals and will never be replayed by a ghost. Widen the "
                    + "mask to a ulong (RecordedFrame, PlayerRecorder, GhostReplayer) or spend fewer "
                    + "bits - see CLAUDE.md 1.6.");
            }

            for (int i = 0; i < signals.Length; i++)
            {
                if (signals[i] == null)
                {
                    Debug.LogError($"[SceneBuilder] {cycleName} ghost interactable {i} is NULL - "
                        + "that bit can never be set, and every entry after it is one a ghost will "
                        + "read but nothing will ever write.");
                    continue;
                }

                for (int j = i + 1; j < signals.Length; j++)
                {
                    if (signals[j] != signals[i]) continue;
                    Debug.LogError($"[SceneBuilder] {cycleName} wires '{signals[i].name}' at both bit "
                        + $"{i} and bit {j}. One fixture on two bits fires its rising edge twice.");
                }
            }
        }

        // CAN THIS CYCLE ACTUALLY BE FINISHED? Asked as a build error, for the same reason
        // `CheckGhostSignals` is: the failure is silent and the build log is already being read.
        //
        // A cycle ends by putting the objects its console asks for into that console, and the console
        // asks by ID. Nothing checks that an object wearing that id exists - `FinalSlot` registers as
        // a socket for it, `ItemRegistry` happily holds a socket with no supply, and the room simply
        // waits forever. Cycle 2 is in exactly that state as this is written: its console declares
        // three shards, `BuildRingShard` is never called, and the only way to discover that is to walk
        // the whole cycle carrying nothing.
        //
        // Scoped to the cycle's own root, because an id is only reachable from inside the cycle that
        // holds it - one cycle is awake at a time, and a carryable in a sleeping one is unregistered.
        private static void CheckCycleFinishable(string cycleName, Transform cycleRoot,
                                                 FinalRoomSequence final)
        {
            if (cycleRoot == null || final == null || final.slots == null) return;

            var ids = new System.Collections.Generic.HashSet<string>();
            foreach (CarryableItem item in cycleRoot.GetComponentsInChildren<CarryableItem>(true))
                if (item != null && !string.IsNullOrEmpty(item.itemId)) ids.Add(item.itemId);

            int declared = 0;
            foreach (FinalSlot slot in final.slots)
            {
                if (slot == null || !slot.Declared) continue;
                declared++;
                if (ids.Contains(slot.AcceptedItemId)) continue;

                Debug.LogError($"[SceneBuilder] {cycleName}'s console declares a slot for "
                    + $"'{slot.AcceptedItemId}' and NOTHING IN THE CYCLE WEARS THAT ID. The cycle "
                    + "cannot be finished: the slot waits for an object that does not exist, and the "
                    + "only symptom is a player walking the whole cycle finding nothing to carry.");
            }

            if (declared == 0)
                Debug.LogWarning($"[SceneBuilder] {cycleName}'s console declares no slots at all, so "
                    + "nothing can complete it. That is correct only for a cycle still being designed.");
        }

        // CAN THE PLAYER ACTUALLY WALK THROUGH HERE? Asked as a build error rather than left for
        // somebody to find by walking.
        //
        // It has been got wrong twice already - three chorus levers went squarely in front of both of
        // room2's doors, and a hatch lid was left out of a ceiling - and both times the only thing
        // that caught it was a play-through. That is the most expensive test there is for the
        // cheapest possible mistake, when every position involved is known exactly, here.
        //
        // **A SWEPT SPHERE RATHER THAN BOUNDS ARITHMETIC**, and the first attempt is why. Comparing
        // AABBs against a doorway band flagged the floor, the ceiling, all four walls and the door
        // slab itself - twenty false errors, which is worse than no check at all because it teaches
        // everyone to ignore the output. Walking a sphere the size of the player through the gap
        // asks the only question that matters and cannot be fooled by a large bounding box.
        //
        // **IT CHECKS THE DOORWAY, NOT THE ROOM.** The second attempt swept right across each room
        // and flagged the bed - which is furniture in the middle of a room, walked around rather than
        // through. This is not a pathfinder and should not pretend to be one; what it is for is the
        // approach to an opening, which is where the mistakes it exists to catch actually happen.
        // WHAT THE PLAYER IS ACTUALLY STOPPED BY - the same mask `BuildPlayer` gives the
        // CharacterController, and asking anything else makes both asserts below liars.
        //
        // Swept with `~0` these checked layers the player walks straight THROUGH, and room2-6 is where
        // that surfaced: 210 balls, 3 ducks and 2 beach balls float in its pool on the balloon layer,
        // which `cc.excludeLayers` removes outright precisely so there is no invisible wall in the
        // water. One ball drifting into the doorway at build time therefore failed the walk with
        // `'Solid' blocks the way through` - naming a `MakeFloatBody` collider that cannot block
        // anybody - and the room was reported as impassable for days while being perfectly walkable in
        // play. A false error is worse than no check: this one taught its reader to skip the output,
        // which is the failure mode the bounds-arithmetic version was already rewritten to avoid.
        private static int PlayerBlockingMask() => ~(1 << EnsureLayer(BalloonLayerName));

        private static void AssertWalkable(Transform roomRoot, string label, Vector3 localFrom, Vector3 localTo)
        {
            // Colliders built this frame are not in the physics scene until it is told about them.
            Physics.SyncTransforms();

            const float radius = 0.34f;      // the controller's 0.3, plus a little
            Vector3 from = roomRoot.TransformPoint(localFrom + Vector3.up * 0.95f);
            Vector3 to = roomRoot.TransformPoint(localTo + Vector3.up * 0.95f);

            int steps = Mathf.CeilToInt(Vector3.Distance(from, to) / (radius * 0.8f));
            for (int i = 0; i <= steps; i++)
            {
                Vector3 at = Vector3.Lerp(from, to, i / (float)steps);
                Collider[] hits = Physics.OverlapSphere(at, radius, PlayerBlockingMask(),
                                                        QueryTriggerInteraction.Ignore);
                foreach (Collider hit in hits)
                {
                    // Things that are MEANT to be in the way, and open. A door slab is the doorway;
                    // the tree is the hall's entire puzzle, standing where it stands until it is felled.
                    //
                    // `Tree` USED TO BE NAMED HERE AND WAS SILENTLY `UnityEngine.Tree` - the project's
                    // own Tree went out with the reverted cycle-2 puzzle set and the terrain type took
                    // the name over without a compile error. The check has been doing nothing since.
                    if (hit.GetComponentInParent<Door>() != null) continue;
                    if (hit.GetComponentInParent<CycleExit>() != null) continue;
                    // Room3-1's north corridor is SOLID until a pad is held - that is the room, not a
                    // fault. What this check is for there is the geometry around the block: the two
                    // wall cutouts, the corridor floor and its side walls. Exactly the same reason a
                    // door slab is skipped.
                    if (hit.GetComponentInParent<CrushingBarrier>() != null) continue;
                    if (hit.GetComponentInParent<TreeTrunk>() != null) continue;
                    Debug.LogError($"[SceneBuilder] {label}: '{hit.name}' blocks the way through "
                                 + $"(swept at {at}).");
                    return;
                }
            }
        }

        // THE OPPOSITE ASSERT, and the only place in the project that wants one: a gap the player
        // must NOT be able to walk over. `AssertWalkable` proves a doorway is clear; this proves a
        // pit is still a pit, which is a thing a stray collider or a mis-signed Rect can quietly
        // undo - and would undo the whole room without any other symptom.
        private static void AssertNotWalkable(Transform roomRoot, string label, Vector3 localFrom, Vector3 localTo)
        {
            Physics.SyncTransforms();

            const float radius = 0.34f;
            // Swept at ANKLE height, not the chest height `AssertWalkable` uses: what is being looked
            // for is floor under the player, and a chest-high sweep through an open shaft finds
            // nothing whether or not there is a floor beneath it.
            Vector3 from = roomRoot.TransformPoint(localFrom + Vector3.up * 0.15f);
            Vector3 to = roomRoot.TransformPoint(localTo + Vector3.up * 0.15f);

            int steps = Mathf.CeilToInt(Vector3.Distance(from, to) / (radius * 0.8f));
            for (int i = 0; i <= steps; i++)
            {
                Vector3 at = Vector3.Lerp(from, to, i / (float)steps);
                // Same mask as `AssertWalkable`, and for a sharper reason here: a floating ball is not
                // floor. Swept with `~0`, one drifting over the pit would report the hole as spanned
                // and hide a genuinely missing floor behind a prop the player falls straight past.
                foreach (Collider hit in Physics.OverlapSphere(at, radius, PlayerBlockingMask(),
                                                               QueryTriggerInteraction.Ignore))
                {
                    // The bridge is built disabled, so it cannot be what is found here - and if it
                    // ever is, that is exactly the bug this assert exists to catch.
                    Debug.LogError($"[SceneBuilder] {label}: '{hit.name}' spans the pit that is "
                                 + $"supposed to be impassable (swept at {at}).");
                    return;
                }
            }
        }

        // ONE SHARD, as a carryable. `BuildPin` is the template this follows - the simplest complete
        // carryable in the project.
        //
        // The mesh is shared; only the yaw differs, and it is the yaw that says which third of the
        // ring this is. Held, they all look alike, which is correct: what the player is collecting is
        // three of a thing, not three different things.
        private static CarryableItem BuildRingShard(Transform parent, string name, string itemId,
                                                     Vector3 localPos, float yaw, Mesh mesh, Material mat)
        {
            GameObject go = new GameObject(name);
            go.transform.SetParent(parent, false);
            go.transform.localPosition = localPos;

            // The mesh on a CHILD, carrying the yaw. The item's own transform stays axis-aligned so
            // the hand pose and the reach trigger are read off something unrotated - the same
            // separation `MakeChessPiece` makes for the mirrored pieces.
            GameObject body = new GameObject("Body");
            body.transform.SetParent(go.transform, false);
            body.transform.localRotation = Quaternion.Euler(0f, yaw, 0f);
            body.AddComponent<MeshFilter>().sharedMesh = mesh;
            body.AddComponent<MeshRenderer>().sharedMaterial = mat;

            // The reach volume, on the item itself - CarryableItem takes GetComponent<Collider>() as
            // its trigger, so this must be the only collider on this object.
            BoxCollider reach = go.AddComponent<BoxCollider>();
            reach.isTrigger = true;
            reach.center = new Vector3(0f, 0.12f, 0f);
            reach.size = new Vector3(0.9f, 0.5f, 0.9f);

            CarryableItem item = go.AddComponent<CarryableItem>();
            item.itemId = itemId;
            item.displayName = "SHARD";
            item.floorY = 0.03f;
            item.handLocalPosition = HandPoseFor(0.45f);
            item.handLocalEuler = new Vector3(12f, 0f, 0f);
            item.audioSource = MakeSource(go.transform, "ShardAudio", spatialBlend: 1f, volume: 0.8f);
            item.pickupClip = LoadClip(SfxDir, "sfx_item_pickup");
            return item;
        }

        // A THIRD OF A RING: the shape all three of cycle 2's escape objects share.
        //
        // Generated rather than composed out of primitives, because the one thing this shape has to
        // do is look BROKEN OFF - an arc with two flat radial faces where it parted from its
        // neighbours. A box approximation gives a staircase on the inner and outer curves, which
        // reads as a low-poly wedge rather than as a piece of something.
        //
        // Saved as an asset and served from cache on the next build, exactly as `BevelledPrismMesh`
        // is: a Mesh created at edit time and assigned to a scene object is lost on reload unless it
        // lives somewhere.
        //
        // All three shards are the SAME mesh, rotated. They are thirds of one ring, so they are
        // identical by construction - and a puzzle that asked the player to tell them apart would be
        // cycle 1's shape-matching again under a new name.
        private static Mesh RingShardMesh(float sweepDegrees, float innerRadius, float outerRadius, float thickness)
        {
            string assetName = $"RingShard{Mathf.RoundToInt(sweepDegrees)}";
            string path = GeneratedDir + "/" + assetName + ".mesh";
            Mesh existing = AssetDatabase.LoadAssetAtPath<Mesh>(path);
            if (existing != null) return existing;

            const int segments = 24;
            float half = thickness / 2f;
            var verts = new System.Collections.Generic.List<Vector3>();
            var tris = new System.Collections.Generic.List<int>();

            // Four rings of vertices - inner and outer, top and bottom - walked together so every
            // face of the solid can be stitched from the same index arithmetic.
            for (int i = 0; i <= segments; i++)
            {
                float a = Mathf.Deg2Rad * (-sweepDegrees / 2f + sweepDegrees * i / segments);
                float sin = Mathf.Sin(a), cos = Mathf.Cos(a);
                verts.Add(new Vector3(sin * innerRadius, half, cos * innerRadius));
                verts.Add(new Vector3(sin * outerRadius, half, cos * outerRadius));
                verts.Add(new Vector3(sin * innerRadius, -half, cos * innerRadius));
                verts.Add(new Vector3(sin * outerRadius, -half, cos * outerRadius));
            }

            void Quad(int a, int b, int c, int d)
            {
                tris.Add(a); tris.Add(b); tris.Add(c);
                tris.Add(a); tris.Add(c); tris.Add(d);
            }

            for (int i = 0; i < segments; i++)
            {
                int p0 = i * 4, p1 = (i + 1) * 4;
                Quad(p0 + 0, p0 + 1, p1 + 1, p1 + 0);   // top
                Quad(p0 + 2, p1 + 2, p1 + 3, p0 + 3);   // bottom
                Quad(p0 + 1, p0 + 3, p1 + 3, p1 + 1);   // outer curve
                Quad(p0 + 0, p1 + 0, p1 + 2, p0 + 2);   // inner curve
            }

            // THE BROKEN ENDS. Flat radial faces, and the whole reason this is not a torus segment
            // with open sides - they are what the eye reads as a fracture.
            int last = segments * 4;
            Quad(0, 2, 3, 1);
            Quad(last + 1, last + 3, last + 2, last + 0);

            Mesh mesh = new Mesh { name = assetName };
            mesh.SetVertices(verts);
            mesh.SetTriangles(tris, 0);
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();

            if (!Directory.Exists(GeneratedDir)) Directory.CreateDirectory(GeneratedDir);
            AssetDatabase.CreateAsset(mesh, path);
            AssetDatabase.SaveAssets();
            return AssetDatabase.LoadAssetAtPath<Mesh>(path);
        }

        // A WALL PANEL WITH ITS FRONT RIM CHAMFERED, at true size.
        //
        // **THE ARGUMENT IS ALREADY IN THIS FILE, one screen down, and it was only ever applied to
        // three objects.** `BevelledPrismMesh` says it: a Unity cube's faces meet at perfectly sharp
        // edges, so each face is one flat shade under any lighting, "and no material fixes it,
        // because there is no geometry near the edge for a highlight to run along". That was written
        // about the escape objects. The building is made of some three thousand cubes.
        //
        // Here it is worth more than it is there, because of what the panels already are: each one
        // stands `GrooveDepth` proud of its backing, so the building is a grid of raised rectangles
        // with a shadow line around every one. Chamfering the front rim puts a lit line inside every
        // one of those shadow lines - thousands of them - and that pairing is most of what separates
        // a photographed wall from an extruded one.
        //
        // **ONLY THE FRONT RIM.** The back face is buried against the backing slab and the four side
        // walls are the groove itself; neither is where the light is. Four edges, not twelve.
        //
        // **TRUE SIZE, NOT A SCALED UNIT CUBE, and that is the whole reason this exists as a mesh per
        // size.** A panel is 1.72 x 1.32 x 0.025: a chamfer written as a fraction and scaled with the
        // box comes out 100mm across the face and 1.5mm through the depth, which is not a chamfer, it
        // is a wedge. The metres have to survive into the vertices.
        //
        // Cached by size, so the grid's identical cells share one asset and go on batching - the
        // partial panels around doorways are the only ones that mint new ones. The build logs how
        // many distinct meshes it ended up with; if that number is ever in the hundreds, the sizes
        // have stopped repeating and this trade needs looking at again.
        // **A DISC WITH A HOLE THROUGH IT - and it has to be a generated mesh, because nothing else
        // here can make a hole.**
        //
        // The socket's grey face was a `Cylinder` primitive with a dark cylinder behind it, and play
        // reported the obvious consequence: "홈이 안보여" - the notch is invisible. Of course it is. A
        // solid disc in front of a dark one hides it completely; there is no CSG in this project, so
        // "put the dark thing behind" can never produce a hole. Either the geometry has a hole in it
        // or the picture does not.
        //
        // `SymbolSlot` solves the same problem for a SQUARE recess by standing four bars proud of the
        // wall and putting the glyph at the bottom of the well between them - a real hollow made out
        // of what a primitive can do. A round one has no such trick: forty bars in a circle is a
        // polygon nobody asked for. So this is an annulus, extruded, with its inner wall facing the
        // axis so you can see down the bore from in front.
        //
        // **THE WINDING IS EXPLICIT AND THE NORMALS ARE SET BY HAND**, rather than left to
        // `RecalculateNormals`. CLAUDE.md records what a backwards winding costs here: it does not
        // read as a geometry bug, it renders BLACK, and it cost this project a day of chasing
        // lighting theories. Each of the three surfaces is derived from Unity's own convention -
        // normal = (v1-v0) x (v2-v0), checked against the built-in Quad - and written down below.
        private static Mesh RingMesh(float outerRadius, float innerRadius, float depth)
        {
            int ko = Mathf.RoundToInt(outerRadius * 10000f);
            int ki = Mathf.RoundToInt(innerRadius * 10000f);
            int kd = Mathf.RoundToInt(depth * 10000f);

            string assetName = $"Ring_{ko}_{ki}_{kd}";
            string path = GeneratedDir + "/" + assetName + ".mesh";

            Mesh existing = AssetDatabase.LoadAssetAtPath<Mesh>(path);
            if (existing != null) return existing;

            // Enough that the bore reads as round at the half-metre the player gets to it, and few
            // enough that the whole fixture is under a thousand triangles.
            const int segments = 48;

            var verts = new System.Collections.Generic.List<Vector3>();
            var norms = new System.Collections.Generic.List<Vector3>();
            var tris = new System.Collections.Generic.List<int>();

            // Local +Z is OUT of the wall, and the ring is extruded back to -Z. The caller orients it
            // with `LookRotation(inward)`, which maps local +Z onto the direction the socket faces.
            Vector3 At(float radius, int i, float z)
            {
                float a = 2f * Mathf.PI * i / segments;
                return new Vector3(Mathf.Cos(a) * radius, Mathf.Sin(a) * radius, z);
            }
            Vector3 Radial(int i)
            {
                float a = 2f * Mathf.PI * i / segments;
                return new Vector3(Mathf.Cos(a), Mathf.Sin(a), 0f);
            }

            void Tri(Vector3 a, Vector3 b, Vector3 c, Vector3 na, Vector3 nb, Vector3 nc)
            {
                int at = verts.Count;
                verts.Add(a); verts.Add(b); verts.Add(c);
                norms.Add(na); norms.Add(nb); norms.Add(nc);
                tris.Add(at); tris.Add(at + 1); tris.Add(at + 2);
            }

            for (int i = 0; i < segments; i++)
            {
                int j = (i + 1) % segments;
                Vector3 ri = Radial(i), rj = Radial(j);
                Vector3 outI = At(outerRadius, i, 0f), outJ = At(outerRadius, j, 0f);
                Vector3 inI = At(innerRadius, i, 0f), inJ = At(innerRadius, j, 0f);
                Vector3 outIb = At(outerRadius, i, -depth), outJb = At(outerRadius, j, -depth);
                Vector3 inIb = At(innerRadius, i, -depth), inJb = At(innerRadius, j, -depth);

                // THE FRONT FACE, an annulus whose normal points out of the wall. The order is
                // checked rather than guessed: with normal = (v1-v0) x (v2-v0) - Unity's own
                // convention, verified against its built-in Quad - (outer_i, inner_j, inner_i)
                // crosses to +Z and the reverse of it to -Z.
                Tri(outI, inJ, inI, Vector3.forward, Vector3.forward, Vector3.forward);
                Tri(outI, outJ, inJ, Vector3.forward, Vector3.forward, Vector3.forward);

                // THE BORE'S WALL, facing the axis - the surface that says the hole has DEPTH, and
                // the whole reason this is a mesh rather than a flat ring.
                Tri(inI, inJb, inIb, -ri, -rj, -ri);
                Tri(inI, inJ, inJb, -ri, -rj, -rj);

                // THE OUTER WALL, facing away from the axis: the rim's own thickness seen from the
                // side, which is what makes the face read as standing PROUD of the plate.
                Tri(outI, outIb, outJb, ri, ri, rj);
                Tri(outI, outJb, outJ, ri, rj, rj);
            }

            Mesh mesh = new Mesh { name = assetName };
            mesh.SetVertices(verts);
            mesh.SetNormals(norms);
            mesh.SetTriangles(tris, 0);
            mesh.RecalculateTangents();
            mesh.RecalculateBounds();

            if (!Directory.Exists(GeneratedDir)) Directory.CreateDirectory(GeneratedDir);
            AssetDatabase.CreateAsset(mesh, path);
            return AssetDatabase.LoadAssetAtPath<Mesh>(path);
        }

        // A ring standing on a surface, with a genuine hole through it. `inward` is the way the face
        // points; the mesh is built about local +Z and turned onto it.
        private static GameObject MakeRing(Transform parent, string name, Vector3 localPos,
                                           Vector3 inward, float outerRadius, float innerRadius,
                                           float depth, Material mat)
        {
            GameObject go = new GameObject(name);
            go.transform.SetParent(parent, false);
            go.transform.localPosition = localPos;
            go.transform.localRotation = Quaternion.LookRotation(inward);

            go.AddComponent<MeshFilter>().sharedMesh = RingMesh(outerRadius, innerRadius, depth);
            MeshRenderer renderer = go.AddComponent<MeshRenderer>();
            renderer.sharedMaterial = mat;
            return go;
        }

        private static Mesh ChamferedPanelMesh(float width, float height, float depth, float chamfer)
        {
            // Rounded to the tenth of a millimetre BEFORE it becomes a key, or floating point turns
            // one panel size into a dozen assets that differ in the seventh decimal.
            int kw = Mathf.RoundToInt(width * 10000f);
            int kh = Mathf.RoundToInt(height * 10000f);
            int kd = Mathf.RoundToInt(depth * 10000f);
            int kc = Mathf.RoundToInt(chamfer * 10000f);

            string assetName = $"Panel_{kw}_{kh}_{kd}_{kc}";
            string path = GeneratedDir + "/" + assetName + ".mesh";
            panelMeshNames.Add(assetName);

            Mesh existing = AssetDatabase.LoadAssetAtPath<Mesh>(path);
            if (existing != null) return existing;

            float hx = width / 2f, hy = height / 2f, hz = depth / 2f;
            // Never eat the whole panel. A sliver beside a doorway can be narrower than the chamfer
            // wants to be, and a chamfer wider than half the piece inverts it.
            float c = Mathf.Min(chamfer, Mathf.Min(hx, hy) * 0.45f);
            c = Mathf.Min(c, depth * 0.5f);

            // The front face, inset by the chamfer, and the rim it meets the sides at. Connecting two
            // concentric rectangles corner to corner gives four quads and needs no corner facet - the
            // twist at each corner IS the mitre.
            Vector3[] front =
            {
                new Vector3(-(hx - c), -(hy - c), hz), new Vector3(hx - c, -(hy - c), hz),
                new Vector3(hx - c, hy - c, hz), new Vector3(-(hx - c), hy - c, hz),
            };
            Vector3[] rim =
            {
                new Vector3(-hx, -hy, hz - c), new Vector3(hx, -hy, hz - c),
                new Vector3(hx, hy, hz - c), new Vector3(-hx, hy, hz - c),
            };
            Vector3[] back =
            {
                new Vector3(-hx, -hy, -hz), new Vector3(hx, -hy, -hz),
                new Vector3(hx, hy, -hz), new Vector3(-hx, hy, -hz),
            };

            var verts = new System.Collections.Generic.List<Vector3>();
            var uvs = new System.Collections.Generic.List<Vector2>();
            var tris = new System.Collections.Generic.List<int>();

            // **UV IS AN XY PROJECTION ACROSS THE WHOLE PANEL, not a face-by-face 0-1.** The cube this
            // replaces gave its front face exactly 0..1 and the panel materials tile against that
            // (`ApplySurfaceDetail(panelMat, ..., new Vector2(5f, 3f), ...)`). This reproduces it to
            // within the chamfer - 6mm on a 1.72m panel is three thousandths of a UV - and has the
            // advantage of running continuously over the rim, so the grain does not break at the
            // edge the way per-face mapping would.
            void Quad(Vector3 a, Vector3 b, Vector3 cc, Vector3 d)
            {
                int at = verts.Count;
                foreach (Vector3 v in new[] { a, b, cc, d })
                {
                    verts.Add(v);
                    uvs.Add(new Vector2((v.x + hx) / width, (v.y + hy) / height));
                }
                // **WOUND THIS WAY ROUND BECAUSE THE OTHER WAY BUILT THE BUILDING INSIDE OUT**, and
                // it shipped that way for a day (2026-08-25). `a,b,cc,d` arrive counter-clockwise
                // seen from OUTSIDE the solid, and Unity treats clockwise-from-the-front as
                // front-facing - so `(0,2,1) / (0,3,2)`, which is what this was, faces every quad
                // backwards. `RecalculateNormals` derives normals from exactly this, so every panel
                // in the game got a normal pointing INTO the wall and the face the room can see was
                // shaded as though it faced away from every light in it. **Result: a white building
                // with pure black walls**, floors and ceilings untouched because they are plain
                // slabs and never came through here.
                //
                // The comment that used to sit here claimed the winding was correct and cited
                // `BevelledPrismMesh` learning it the hard way - the same mistake, in the same
                // project, caught the first time only because that mesh was emissive. **Do not
                // reason about winding from the comment. Build it and look at it.**
                tris.Add(at); tris.Add(at + 1); tris.Add(at + 2);
                tris.Add(at); tris.Add(at + 2); tris.Add(at + 3);
            }

            Quad(front[0], front[1], front[2], front[3]);                 // the face
            for (int i = 0; i < 4; i++)                                   // the chamfer, four quads
            {
                int j = (i + 1) % 4;
                Quad(rim[i], rim[j], front[j], front[i]);
            }
            for (int i = 0; i < 4; i++)                                   // the groove walls
            {
                int j = (i + 1) % 4;
                Quad(back[i], back[j], rim[j], rim[i]);
            }
            Quad(back[3], back[2], back[1], back[0]);                     // the buried face

            Mesh mesh = new Mesh { name = assetName };
            mesh.SetVertices(verts);
            mesh.SetUVs(0, uvs);
            mesh.SetTriangles(tris, 0);
            // Every face has its own vertices, so this leaves the edges hard - a chamfer smoothed
            // into the face it borders is a rounded-off cube, not a bevelled one. Same rule
            // `BevelledPrismMesh` states for Square and Triangle.
            mesh.RecalculateNormals();
            mesh.RecalculateTangents();
            mesh.RecalculateBounds();

            if (!Directory.Exists(GeneratedDir)) Directory.CreateDirectory(GeneratedDir);
            AssetDatabase.CreateAsset(mesh, path);
            panelMeshesBuilt++;
            return AssetDatabase.LoadAssetAtPath<Mesh>(path);
        }

        // WHICH distinct panel sizes the building turned out to have, and how many of them this run
        // had to generate. The two differ on every build after the first - the meshes are assets, so
        // a rebuild serves them from disk - and reporting only the second reads as "0 panels" on a
        // healthy build. See `ChamferedPanelMesh` for why the count is worth watching at all.
        private static readonly System.Collections.Generic.HashSet<string> panelMeshNames =
            new System.Collections.Generic.HashSet<string>();
        private static int panelMeshesBuilt;

        // One chamfered panel, in place of the cube `Prim` would have made.
        //
        // **SCALE STAYS AT ONE, and the rotation is what places it.** The metres live in the mesh -
        // that is the whole point of a mesh per size - so the transform may not stretch it. What the
        // transform does instead is turn it to face the way the wall does.
        //
        // `inward` points INTO the room from the wall face, and the mesh is built facing +Z, so
        // that is the look direction. NOT the `depthAxis` the wall also carries: that one is
        // componentwise absolute, so it has the panel's thickness but no idea which side of the wall
        // the room is on, and a panel built against it faces out of the building half the time.
        private static GameObject ChamferedPanel(string name, Transform parent, Vector3 localPos,
                                                 float width, float height, float depth,
                                                 Vector3 inward, Material mat)
        {
            GameObject go = new GameObject(name);
            go.transform.SetParent(parent, false);
            go.transform.localPosition = localPos;
            go.transform.localRotation = Quaternion.LookRotation(inward, Vector3.up);
            go.transform.localScale = Vector3.one;

            go.AddComponent<MeshFilter>().sharedMesh =
                ChamferedPanelMesh(width, height, depth, PanelChamfer);
            go.AddComponent<MeshRenderer>().sharedMaterial = mat;
            return go;
        }

        private static Mesh BevelledPrismMesh(SlotShape shape, float chamfer)
        {
            // The chamfer is in the asset name, so a shape and its bevelled twin are two assets and
            // neither can be served from the other's cache. It is also what retires the old
            // TriangularPrism.mesh without having to find and delete it: nothing asks for that path
            // any more.
            string assetName = $"Prism{shape}{Mathf.RoundToInt(chamfer * 100f)}";
            string path = GeneratedDir + "/" + assetName + ".mesh";
            Mesh existing = AssetDatabase.LoadAssetAtPath<Mesh>(path);
            if (existing != null) return existing;

            // Round gets enough segments that the silhouette is a circle at arm's length, which is
            // where these are looked at hardest - it is in the hand for most of a final lap.
            int sides = shape == SlotShape.Round ? 48 : (shape == SlotShape.Triangle ? 3 : 4);
            bool smooth = shape == SlotShape.Round;

            // Where vertex 0 sits. The triangle keeps its apex at +Z, away from the player and so the
            // top of the shape as it is looked down on - the existing prism's choice, kept because
            // the recess in Room4 is cut from the unbevelled mesh at the same angle. A 4-gon starts
            // at 45 degrees, which is what turns it into an axis-aligned square rather than a
            // diamond.
            float turn = shape == SlotShape.Triangle ? Mathf.PI * 0.5f
                       : shape == SlotShape.Square ? Mathf.PI * 0.25f : 0f;

            Vector2[] unit = new Vector2[sides];
            for (int i = 0; i < sides; i++)
            {
                float a = turn + i * Mathf.PI * 2f / sides;
                unit[i] = new Vector2(Mathf.Cos(a), Mathf.Sin(a));
            }

            // Fit the widest ring to a unit box in XZ. A triangle inscribed in a circle is neither
            // square nor centred on that circle, so without this it comes out smaller and offset
            // against the other two - which in a row of three reads as a mistake, not as a triangle.
            float minX = float.MaxValue, maxX = float.MinValue, minY = float.MaxValue, maxY = float.MinValue;
            foreach (Vector2 v in unit)
            {
                minX = Mathf.Min(minX, v.x); maxX = Mathf.Max(maxX, v.x);
                minY = Mathf.Min(minY, v.y); maxY = Mathf.Max(maxY, v.y);
            }
            Vector2 centre = new Vector2((minX + maxX) * 0.5f, (minY + maxY) * 0.5f);
            Vector2 span = new Vector2(maxX - minX, maxY - minY);
            for (int i = 0; i < sides; i++)
                unit[i] = new Vector2((unit[i].x - centre.x) / span.x, (unit[i].y - centre.y) / span.y);

            // Rings bottom to top. With a chamfer there are four - bottom cap edge, bottom of the
            // barrel, top of the barrel, top cap edge - and the caps are pulled in by the chamfer
            // while the barrel stays full width. Without one there are just the two ends, and no
            // degenerate zero-height band is emitted for RecalculateNormals to choke on.
            //
            // 6% is the chamfer these objects use. Big enough to catch a light at 0.30m across - 18mm
            // on the real object, about the width of the highlight it exists to hold - and small
            // enough that the silhouette is still unmistakably a cube, a triangle or a disc, which is
            // the one thing these three must never stop being: the recesses are cut to match.
            float[] ringY, ringScale;
            if (chamfer > 0f)
            {
                float inset = 1f - chamfer * 2f;
                ringY = new[] { -0.5f, -0.5f + chamfer, 0.5f - chamfer, 0.5f };
                ringScale = new[] { inset, 1f, 1f, inset };
            }
            else
            {
                ringY = new[] { -0.5f, 0.5f };
                ringScale = new[] { 1f, 1f };
            }
            int rings = ringY.Length;

            var verts = new System.Collections.Generic.List<Vector3>();
            var tris = new System.Collections.Generic.List<int>();

            Vector3 At(int ring, int i) =>
                new Vector3(unit[i].x * ringScale[ring], ringY[ring], unit[i].y * ringScale[ring]);

            // WINDING, stated once because getting it wrong is invisible on an emissive object and
            // fatal on a metal one: Unity's front face is the triangle whose cross(v1-v0, v2-v0)
            // points ALONG the outward normal. The ring runs counter-clockwise in XZ seen from +Y.
            if (smooth)
            {
                // One continuous side surface with shared vertices, so the normals average round the
                // circumference and across both chamfers - a rounded-off puck rather than a drum.
                int baseIndex = verts.Count;
                for (int r = 0; r < rings; r++)
                    for (int i = 0; i < sides; i++) verts.Add(At(r, i));

                for (int r = 0; r < rings - 1; r++)
                    for (int i = 0; i < sides; i++)
                    {
                        int j = (i + 1) % sides;
                        int a = baseIndex + r * sides + i, b = baseIndex + r * sides + j;
                        int c = baseIndex + (r + 1) * sides + j, d = baseIndex + (r + 1) * sides + i;
                        tris.Add(a); tris.Add(d); tris.Add(c);
                        tris.Add(a); tris.Add(c); tris.Add(b);
                    }
            }
            else
            {
                // Every band of every face gets its own four vertices, so nothing smooths into
                // anything: the faces stay flat and the chamfers stay as distinct bands.
                for (int r = 0; r < rings - 1; r++)
                    for (int i = 0; i < sides; i++)
                    {
                        int j = (i + 1) % sides;
                        int b = verts.Count;
                        verts.Add(At(r, i)); verts.Add(At(r, j));
                        verts.Add(At(r + 1, j)); verts.Add(At(r + 1, i));
                        tris.Add(b); tris.Add(b + 3); tris.Add(b + 2);
                        tris.Add(b); tris.Add(b + 2); tris.Add(b + 1);
                    }
            }

            // Caps, as fans off their own vertices so they stay flat whatever the sides do. Wound
            // opposite ways so both face outward - and note the TOP fan runs backwards against the
            // ring. A fan following a counter-clockwise ring produces a downward normal, which is
            // exactly the inversion the mesh this replaces shipped with.
            int topBase = verts.Count;
            for (int i = 0; i < sides; i++) verts.Add(At(rings - 1, i));
            for (int i = 1; i < sides - 1; i++)
            {
                tris.Add(topBase); tris.Add(topBase + i + 1); tris.Add(topBase + i);
            }

            int botBase = verts.Count;
            for (int i = 0; i < sides; i++) verts.Add(At(0, i));
            for (int i = 1; i < sides - 1; i++)
            {
                tris.Add(botBase); tris.Add(botBase + i); tris.Add(botBase + i + 1);
            }

            Mesh mesh = new Mesh { name = assetName };
            mesh.SetVertices(verts);
            mesh.SetTriangles(tris, 0);
            mesh.RecalculateNormals();
            // No RecalculateTangents: tangents are derived from UVs, this mesh has none, and nothing
            // wearing it uses a normal map. Asking for them buys a warning and a garbage array.
            mesh.RecalculateBounds();

            if (!Directory.Exists(GeneratedDir)) Directory.CreateDirectory(GeneratedDir);
            AssetDatabase.CreateAsset(mesh, path);
            AssetDatabase.SaveAssets();
            return mesh;
        }

        // The canvas, the plate and the placement, shared by every wall sign in the game. What goes ON
        // it comes from the caller: Room3's message is two lines of text, Room2's is a row of
        // pictograms, and both want exactly this plate at exactly this height on all four walls.
        private static CanvasGroup MakeWallFace(Transform parent, string name, Vector3 localPosition,
                                                Quaternion localRotation, System.Action<Transform> fillContent,
                                                float worldWidth = 7.2f, bool withPlate = true,
                                                float authoredHeight = 440f)
        {
            GameObject go = new GameObject(name);
            go.transform.SetParent(parent, false);

            Canvas canvas = go.AddComponent<Canvas>();
            canvas.renderMode = RenderMode.WorldSpace;

            // Authored large and scaled down, which is the standard way to keep world-space UI text
            // from rendering as a handful of blocky pixels: the font rasterises at the RectTransform
            // size, not the final world size.
            // Always authored 1600 WIDE whatever the final size, so every sign in the game rasterises
            // at the same resolution and the x layout numbers inside fillContent mean the same thing at
            // every scale. Only the scale changes: 7.2m for a wall-wide message, 3.6m over a door.
            //
            // The authored HEIGHT is separate because a sign's aspect is set by what it has to cover.
            // 440 is the text plate's shape; the side-wall pictograms are 618, which is what makes their
            // box exactly two rows of the wall grid tall at their width.
            RectTransform rect = go.GetComponent<RectTransform>();
            rect.sizeDelta = new Vector2(1600f, authoredHeight);
            rect.localScale = Vector3.one * (worldWidth / 1600f);

            // Placed through anchoredPosition3D, set after the Canvas exists. AddComponent<Canvas>()
            // replaces the GameObject's plain Transform with a RectTransform, and a RectTransform's
            // local x and y come from its anchored position - so this is the field that means
            // anything. Anchors centred, so the offset is measured from the parent's origin (a
            // non-RectTransform parent is treated as a zero-size rect there).
            //
            // Worth knowing when verifying this in the saved scene, because it looks exactly like a
            // bug: a RectTransform's serialized m_LocalPosition is stale - here it stays {0,0,0}
            // while m_AnchoredPosition carries the real placement, and Unity recomputes the former
            // on load. Read m_AnchoredPosition, not m_LocalPosition.
            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.anchoredPosition3D = localPosition;
            rect.localRotation = localRotation;

            CanvasGroup group = go.AddComponent<CanvasGroup>();
            group.alpha = 0f;
            group.blocksRaycasts = false;
            group.interactable = false;

            // The plate. This is what makes it a display rather than PAINT - GrooveDark is the same
            // near-black that sits at the bottom of every groove in the room.
            //
            // Optional, because that distinction is the whole choice. A lit black plate is the
            // facility interrupting, which is right for the message that stops an iteration; it is
            // far too loud for a small hint over a doorway, which wants to read as something
            // stencilled on the wall and be ignorable once it has been understood.
            if (withPlate)
            {
                GameObject plateGO = new GameObject("Plate");
                plateGO.transform.SetParent(go.transform, false);
                Image plate = plateGO.AddComponent<Image>();
                plate.color = new Color(0.04f, 0.04f, 0.045f, 0.94f);
                plate.raycastTarget = false;
                Stretch(plate.GetComponent<RectTransform>());
            }

            fillContent?.Invoke(go.transform);

            return group;
        }

        // All four walls of one room, at one height, carrying one piece of content.
        //
        // Each canvas's forward (+Z) points INTO its wall, i.e. away from the room. That reads
        // backwards and it is the opposite of what was built first, which came out mirrored.
        //
        // The rule: a world-space canvas is legible when its forward matches the direction the viewer
        // is LOOKING, not when it points at the viewer. Unity's own default scene is the proof -
        // camera at z = -10 looking toward +Z, canvas at the origin unrotated, text the right way
        // round. So a wall sign must face the same way as the eyes reading it, and a player anywhere
        // in the middle of a room looks outwards at every one of these.
        //
        // Worth knowing: this is why wall signs are canvases and not textures on the panelling. A
        // panel is a PrimitiveType.Cube, and a cube's +X and -X faces carry opposite U - so the same
        // texture reads mirrored on the east wall against the west (docs/gotchas.md). A canvas has no
        // such handedness, only the facing rule above, which is one decision instead of per-wall
        // bookkeeping.
        private static CanvasGroup[] MakeFourWallFaces(Transform parent, float y, float standoff,
                                                       System.Action<Transform> fillContent)
        {
            float halfWidth = RoomWidth / 2f;
            float halfDepth = RoomDepth / 2f;

            return new[]
            {
                MakeWallFace(parent, "South", new Vector3(0f, y, -halfDepth + standoff), Quaternion.Euler(0f, 180f, 0f), fillContent),
                MakeWallFace(parent, "North", new Vector3(0f, y, halfDepth - standoff), Quaternion.identity, fillContent),
                MakeWallFace(parent, "West", new Vector3(-halfWidth + standoff, y, 0f), Quaternion.Euler(0f, -90f, 0f), fillContent),
                MakeWallFace(parent, "East", new Vector3(halfWidth - standoff, y, 0f), Quaternion.Euler(0f, 90f, 0f), fillContent),
            };
        }

        // Room3's content: the two text lines that were the only thing a wall face ever held.
        private static void FillTerminationMessage(Transform face)
        {
            MakeWallLine(face, "Headline", "H O L D   [ N ]", 132, Color.red,
                new Vector2(0f, 78f), new Vector2(1600f, 190f));
            // Not spaced out, unlike the headline: this line is 29 characters and spacing it would
            // put it past the wall. The headline carries the treatment for both.
            MakeWallLine(face, "Detail", "TO SKIP TO THE NEXT ITERATION", 74,
                new Color(1f, 0.35f, 0.35f, 0.9f), new Vector2(0f, -90f), new Vector2(1600f, 130f));
        }

        // Room2's sign: PIN, then LEFT CLICK, then a balloon, then that balloon gone. No words at all.
        //
        // It exists because of a specific failure, not as decoration. A player on the itch build could
        // not work out how to burst a balloon and gave up - "kept trying and closed it". The
        // left-click prompt now sits on the balloon a swing would burst, but that prompt only appears
        // while the pin is IN HAND, so it says nothing at all to the player who walked past the drawer
        // and arrived here empty-handed. This is the sign for that player: it names the tool, the
        // button and the outcome, in the order they happen.
        //
        // Four icons and three arrows, drawn to the same 1600px width the text lines use. Sizes and
        // centres are laid out from one total so the row stays centred if any of them change.
        //
        // CHARCOAL ON THE BARE WALL, no plate behind it. The first version was red on a lit black
        // plate, borrowed from Room3's message, and it dominated the room - which is wrong for this
        // one. Room3's sign interrupts an iteration and should be impossible to miss once; this is a
        // standing hint that has to be findable when wanted and ignorable for the rest of the run, so
        // it reads as stencilled on the panelling. The value sits well clear of GrooveDark (0.04) so
        // it cannot be mistaken for a seam, and the arrows go dimmer still - they are punctuation, and
        // at equal weight the row reads as seven things rather than four and three.
        //
        // The icon size is a parameter because the two placements want different weights: 190 over the
        // door leaves margin either side of the row, 295 fills the authored width exactly for the big
        // side-wall signs. The arrow keeps its ratio to the icon so the row's rhythm is the same at
        // both sizes.
        private static void FillBalloonPictogram(Transform face, float icon)
        {
            float arrow = icon * (90f / 190f);
            float total = icon * 4f + arrow * 3f;
            float x = -total / 2f;

            Color ink = new Color(0.20f, 0.20f, 0.23f, 0.72f);
            // The arrows are RED while the things they connect stay charcoal, which inverts what the
            // first version did - it dimmed them, on the grounds that they are punctuation. Colour
            // separates them better than weight does: the eye now gets the direction of the sequence
            // before it has identified any of the four objects, and "left to right, then it pops" is
            // the half of this sign that has to survive being glanced at. Same red the facility uses
            // for its own text, held slightly off full so it reads as printed rather than lit.
            Color punctuation = new Color(0.82f, 0.12f, 0.12f, 0.85f);

            Sprite[] sprites = { PinIcon(), MouseLeftIcon(), BalloonIcon(), BalloonBurstIcon() };
            string[] names = { "Pin", "Click", "Balloon", "Burst" };
            Sprite arrowSprite = ArrowRightIcon();

            for (int i = 0; i < sprites.Length; i++)
            {
                MakeWallIcon(face, names[i], sprites[i], new Vector2(x + icon / 2f, 0f), icon, ink);
                x += icon;

                if (i == sprites.Length - 1) continue;
                MakeWallIcon(face, $"Arrow{i}", arrowSprite, new Vector2(x + arrow / 2f, 0f), arrow, punctuation);
                x += arrow;
            }
        }

        private static void MakeWallIcon(Transform parent, string name, Sprite sprite,
                                         Vector2 anchoredPosition, float size, Color color)
        {
            GameObject go = new GameObject(name);
            go.transform.SetParent(parent, false);

            Image image = go.AddComponent<Image>();
            image.sprite = sprite;
            image.color = color;
            image.raycastTarget = false;
            // The icons are square and drawn square; preserveAspect keeps a future non-square one
            // from being stretched to fit rather than fitted.
            image.preserveAspect = true;

            RectTransform rect = image.GetComponent<RectTransform>();
            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.sizeDelta = new Vector2(size, size);
            rect.anchoredPosition = anchoredPosition;
        }

        // Room2's pictogram: the two SIDE walls, retired the moment the player pops anything.
        //
        // The side walls, and only those. A sign went over the key door first, on the reasoning that
        // the way out is the one surface every player in here is guaranteed to face - and it was
        // removed, because that is a description of where a player is LOOKING and not of where they
        // are stuck. Someone who cannot burst a balloon is standing among balloons turning on the
        // spot, which puts a side wall in front of them; and a hint over the exit reads as being about
        // the exit. Two big signs beside the puzzle say it where the puzzle is.
        //
        // South is bare for the opposite reason: it is at the player's back on the way in, and nobody
        // turns round for it.
        //
        // These are the ANSWER rather than a label, so they are sized to be read from anywhere in the
        // room - 7.0m, up from the 2.2m first tried and the 3.6m after it, both of which read as too
        // small from across the room. Charcoal on bare wall, no plate, at every size.
        //
        // The retirement is the other difference from Room3's. That sign goes on the first visit out,
        // because skipping an iteration is learned in one reading. This one stays until the player has
        // actually burst something, because the player it exists for is the one who arrives with empty
        // hands, fails, and walks back out to look for the tool - under the leave-once rule they would
        // return to a blank wall, having been shown the answer at the one moment they could not use it.
        private static PanelMessage BuildBalloonPictogram(Transform parent, float roomCenterZ, BalloonTool tool)
        {
            GameObject root = new GameObject("BalloonPictogram");
            root.transform.SetParent(parent, false);
            root.transform.localPosition = new Vector3(0f, 0f, roomCenterZ);

            const float standoff = 0.05f;
            float halfWidth = RoomWidth / 2f;
            float halfDepth = RoomDepth / 2f;

            // THE WIDTH IS SIZED TO THE WALL GRID, and the height is sized to clear a doorway.
            //
            // A side wall is RoomDepth long, so it is 10.5 / 1.75 = SIX columns: the sign spans the
            // middle four, 7.0m, with the column boundaries falling at -3.5 and +3.5. That is why it
            // reads as printed on those panels rather than floating across them.
            //
            // The HEIGHT used to be grid-aligned too - the middle two rows, centred on RoomHeight/2 -
            // and it cannot be any more, because Room2's side walls now have DOORWAYS in them. A door
            // is 2.5 tall with its lamp at 2.725..2.835, and the icons in a sign centred at 2.7039 hang
            // down to 2.06: two of the four would have sat across the top of the door. Centred at 3.55
            // the icons run 2.905..4.195, clearing the lamp by 7cm, and only the middle arrow is over
            // the doorway at all. Nothing is lost visually since there is no plate - the rect is
            // invisible and only the row of icons reads.
            const float sideWidth = GridCellWidth * 4f;                  // 7.0, four columns
            const float sideAuthoredHeight = 618f;
            const float sideY = 3.55f;                                   // icons 2.905..4.195

            // 295 fills the authored width exactly - 4 icons plus 3 arrows at the row's own ratio come
            // to 1600 - so the sequence spans all four columns. A four-step row laid out horizontally
            // cannot also be two rows TALL: at 295 the icons are 1.29m against the block's 2.70m, and
            // making them taller would mean fewer than four fitting across. So the row fills the width
            // of the eight panels and sits centred in their height.
            const float sideIcon = 295f;

            // Each canvas's forward (+Z) points INTO its wall: a world-space canvas is legible when its
            // forward matches the direction the viewer is LOOKING, not when it points at the viewer.
            // See MakeFourWallFaces for the full rule, and for why signs are canvases and not textures
            // on the panelling.
            var faces = new[]
            {
                MakeWallFace(root.transform, "West", new Vector3(-halfWidth + standoff, sideY, 0f),
                             Quaternion.Euler(0f, -90f, 0f), f => FillBalloonPictogram(f, sideIcon),
                             sideWidth, withPlate: false, authoredHeight: sideAuthoredHeight),
                MakeWallFace(root.transform, "East", new Vector3(halfWidth - standoff, sideY, 0f),
                             Quaternion.Euler(0f, 90f, 0f), f => FillBalloonPictogram(f, sideIcon),
                             sideWidth, withPlate: false, authoredHeight: sideAuthoredHeight),
            };

            PanelMessage message = root.AddComponent<PanelMessage>();
            message.faces = faces;
            message.roomCenterZ = roomCenterZ;
            message.halfDepth = halfDepth;
            message.retireOnPop = tool;
            return message;
        }

        private static void MakeWallLine(Transform parent, string name, string content, int fontSize,
                                         Color color, Vector2 anchoredPosition, Vector2 size)
        {
            GameObject go = new GameObject(name);
            go.transform.SetParent(parent, false);

            Text text = go.AddComponent<Text>();
            text.font = UIFont();
            text.fontSize = fontSize;
            text.alignment = TextAnchor.MiddleCenter;
            text.color = color;
            text.text = content;
            text.horizontalOverflow = HorizontalWrapMode.Overflow;
            text.verticalOverflow = VerticalWrapMode.Overflow;
            text.raycastTarget = false;

            RectTransform rect = text.GetComponent<RectTransform>();
            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.sizeDelta = size;
            rect.anchoredPosition = anchoredPosition;
        }

        // `ink` null keeps the pale red this was built with, which is right over the pause menu's
        // black scrim and wrong over the title screen's white wall - the same split MakeMenuButton
        // makes, for the same reason.
        // A LABEL THAT ALSO PICKS ITS FACE AND SIZE, for the page and section headings. The menu's
        // whole hierarchy is size and weight - see the title's note on why it is ExtraLight at 86 -
        // and `MakeRowLabel` hard-codes Regular at 18, which is one voice and not three.
        private static Text MakeRowLabelWeight(Transform parent, string name, string content,
                                               Vector2 anchoredPosition, Vector2 size,
                                               TextAnchor alignment, Color ink,
                                               string weight, int fontSize)
        {
            Text text = MakeRowLabelInk(parent, name, content, anchoredPosition, size, alignment, ink);
            if (text != null)
            {
                text.font = UIFont(weight);
                text.fontSize = fontSize;
            }
            return text;
        }

        // ONE SETTINGS ROW: label on the column edge, slider at the indent, number after it. Both
        // sliders on the settings page and both on the pause overlay are built through here, so the
        // four cannot drift apart - which is exactly what had happened.
        //
        // The INK is a parameter and not a constant, because the two pages that use it sit on
        // opposite grounds: the settings page is charcoal on a bright photograph, the pause overlay
        // is red on a near-black scrim. Everything else about the row is identical, which is the
        // point of having one.
        private static (Slider slider, Text value) MakeSettingsSliderRow(
            Transform column, string name, string label, string locKey, string initialValue,
            float y, Color ink)
        {
            Localize(MakeRowLabelInk(column, name + "Label", label,
                new Vector2(SettingsLabelWidth / 2f, y), new Vector2(SettingsLabelWidth, 30f),
                TextAnchor.MiddleLeft, ink), locKey);

            const float sliderWidth = 240f;
            Slider slider = MakeSlider(column, name + "Slider",
                new Vector2(SettingsControlX + sliderWidth / 2f, y), new Vector2(sliderWidth, 26f));

            // The readout starts a clear gap past the track's right end. Left-aligned in its rect, so
            // "100%" and "8%" both begin at the same x instead of the number sliding about as it
            // changes width.
            Text value = MakeRowLabelInk(column, name + "Value", initialValue,
                new Vector2(SettingsControlX + sliderWidth + 20f + 45f, y), new Vector2(90f, 30f),
                TextAnchor.MiddleLeft, ink);

            return (slider, value);
        }

        // **THE TITLE, REPEATED BEHIND ITSELF AND FADING - THE GAME'S OWN PREMISE AS A LOGOTYPE**
        // (2026-08-28, by request: the words were "심심하다", and thickness alone was not the answer).
        //
        // Every game decorates its title somehow; the question is whether the decoration is ABOUT
        // anything. This one is. The thing the player looks at for fifteen minutes is a past self
        // rendered faint and a step behind - `docs/ghosts.md`'s afterimage - and stacking the word on
        // its own trail is that image made out of type. It is not a style borrowed from a genre: no
        // other game would arrive at it, because no other game is about the thing it draws.
        //
        // **PLAIN `Text` COPIES, NOT A SHADER.** uGUI has `Shadow` and `Outline`, and both are one
        // offset apiece with no independent alpha ramp - three of them stacked is three copies of one
        // colour, which is a blur rather than a trail. Copies cost three extra draws on a static
        // screen and give every echo its own step and its own fade, which is the whole effect.
        //
        // Inserted BEFORE the title in sibling order, because that is uGUI's draw order: first child
        // is furthest back. The trail has to be behind the word or it is fog over it.
        //
        // The text is READ OFF the title rather than passed in, so the two cannot drift apart. That is
        // safe precisely because the title is facility-voice (CLAUDE.md §3) and carries no `Loc` key -
        // nothing translates it and nothing rewrites it at runtime.
        private static void MakeTitleAfterimage(Text title, int count, Vector2 step,
                                                float firstAlpha, float falloff)
        {
            if (title == null || count <= 0) return;

            RectTransform titleRect = title.GetComponent<RectTransform>();
            Transform parent = title.transform.parent;
            int frontIndex = title.transform.GetSiblingIndex();

            // The nearest echo's alpha is given rather than derived, because the FIRST step down from
            // solid is the one the eye judges the whole ramp by - derived from the falloff it was
            // either a double image or nothing at all. Scaled by the title's own alpha so the trail
            // fades with it if the screen ever dips.
            float alpha = title.color.a * firstAlpha / falloff;
            for (int i = 1; i <= count; i++)
            {
                alpha *= falloff;

                GameObject echoGO = new GameObject($"TitleEcho_{i}");
                echoGO.transform.SetParent(parent, false);

                Text echo = echoGO.AddComponent<Text>();
                echo.font = title.font;
                echo.fontSize = title.fontSize;
                echo.fontStyle = title.fontStyle;
                echo.alignment = title.alignment;
                echo.lineSpacing = title.lineSpacing;
                echo.horizontalOverflow = title.horizontalOverflow;
                echo.verticalOverflow = title.verticalOverflow;
                echo.text = title.text;
                echo.raycastTarget = false;
                echo.color = new Color(title.color.r, title.color.g, title.color.b, alpha);

                RectTransform echoRect = echo.GetComponent<RectTransform>();
                echoRect.anchorMin = titleRect.anchorMin;
                echoRect.anchorMax = titleRect.anchorMax;
                echoRect.pivot = titleRect.pivot;
                echoRect.sizeDelta = titleRect.sizeDelta;
                echoRect.anchoredPosition = titleRect.anchoredPosition + step * i;

                // Each one goes immediately in front of where the title currently is, so they end up
                // ordered furthest-first with the solid word last. Re-read every pass: inserting
                // shifts the title along by one.
                echoGO.transform.SetSiblingIndex(frontIndex);
                frontIndex = title.transform.GetSiblingIndex();
            }
        }

        private static Text MakeRowLabelInk(Transform parent, string name, string content,
                                            Vector2 anchoredPosition, Vector2 size,
                                            TextAnchor alignment, Color ink)
        {
            Text text = MakeRowLabel(parent, name, content, anchoredPosition, size, alignment);
            if (text != null) { text.color = ink; text.font = UIFont("Medium"); }
            return text;
        }

        // Same shape, one line: a menu button that has already been told what surface it is on.
        // Re-hangs a menu button on the BOTTOM-RIGHT corner. `MakeMenuButton` anchors everything to
        // the left edge at mid-height, which is right for a column and wrong for the one entry that is
        // not in it - and anchoring to the corner rather than offsetting from the centre is what keeps
        // it in the corner when the window is resized.
        // `rise` stacks a second entry above the first. There are two things in this corner now -
        // RECORD and CREDITS - and 78 is the button's own 66 plus a gap, which is deliberately TIGHTER
        // than the column's 88: these are a pair off to one side, not a continuation of the menu.
        private static void CornerBottomRight(RectTransform rect, float rise = 0f)
        {
            if (rect == null) return;
            rect.anchorMin = new Vector2(1f, 0f);
            rect.anchorMax = new Vector2(1f, 0f);
            rect.pivot = new Vector2(1f, 0f);
            // The same margin off both edges as the column has off the left.
            rect.anchoredPosition = new Vector2(-MenuLeftMargin, MenuLeftMargin + rise);
        }

        private static Button MakeMenuButtonInk(Transform parent, string name, string label,
                                                Vector2 anchoredPosition) =>
            MakeMenuButton(parent, name, label, anchoredPosition, MenuInk, "Bold");

        private static Text MakeRowLabel(Transform parent, string name, string content,
                                         Vector2 anchoredPosition, Vector2 size, TextAnchor alignment)
        {
            GameObject go = new GameObject(name);
            go.transform.SetParent(parent, false);

            Text text = go.AddComponent<Text>();
            text.font = UIFont();
            text.fontSize = 18;
            text.alignment = alignment;
            text.color = new Color(1f, 0.35f, 0.35f, 0.85f);
            text.text = content;
            // Overflow, so a rect a shade too narrow cannot break the label across two lines - the
            // same reason IterationLabel sets it.
            text.horizontalOverflow = HorizontalWrapMode.Overflow;
            text.verticalOverflow = VerticalWrapMode.Overflow;
            text.raycastTarget = false;

            RectTransform rect = text.GetComponent<RectTransform>();
            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.sizeDelta = size;
            rect.anchoredPosition = anchoredPosition;

            return text;
        }

        // A uGUI Slider assembled by hand. Three things about it are not optional, because Slider
        // drives them itself every frame and gets them from the hierarchy rather than from fields:
        // the fill must be the child of a container rect (Slider rewrites the fill's anchors within
        // its parent), the handle likewise, and both must leave their offsets at zero or the value
        // it computes lands somewhere other than where it draws.
        private static Slider MakeSlider(Transform parent, string name, Vector2 anchoredPosition, Vector2 size)
        {
            const float handleWidth = 22f;
            Sprite uiSprite = AssetDatabase.GetBuiltinExtraResource<Sprite>("UI/Skin/UISprite.psd");

            GameObject go = new GameObject(name);
            go.transform.SetParent(parent, false);
            RectTransform rect = go.AddComponent<RectTransform>();
            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.sizeDelta = size;
            rect.anchoredPosition = anchoredPosition;

            GameObject bgGO = new GameObject("Background");
            bgGO.transform.SetParent(go.transform, false);
            Image bg = bgGO.AddComponent<Image>();
            bg.sprite = uiSprite;
            bg.type = Image.Type.Sliced;
            bg.color = new Color(0.16f, 0.04f, 0.04f, 0.9f);
            RectTransform bgRect = bg.GetComponent<RectTransform>();
            bgRect.anchorMin = new Vector2(0f, 0.3f);
            bgRect.anchorMax = new Vector2(1f, 0.7f);
            bgRect.offsetMin = Vector2.zero;
            bgRect.offsetMax = Vector2.zero;

            // Inset by half the handle at each end, so the handle's centre reaches the track's ends
            // at 0 and 1 rather than hanging off them.
            GameObject fillAreaGO = new GameObject("Fill Area");
            fillAreaGO.transform.SetParent(go.transform, false);
            RectTransform fillArea = fillAreaGO.AddComponent<RectTransform>();
            fillArea.anchorMin = new Vector2(0f, 0.3f);
            fillArea.anchorMax = new Vector2(1f, 0.7f);
            fillArea.offsetMin = new Vector2(handleWidth / 2f, 0f);
            fillArea.offsetMax = new Vector2(-handleWidth / 2f, 0f);

            GameObject fillGO = new GameObject("Fill");
            fillGO.transform.SetParent(fillAreaGO.transform, false);
            Image fill = fillGO.AddComponent<Image>();
            fill.sprite = uiSprite;
            fill.type = Image.Type.Sliced;
            fill.color = new Color(0.7f, 0.11f, 0.11f, 0.95f);
            RectTransform fillRect = fill.GetComponent<RectTransform>();
            fillRect.offsetMin = Vector2.zero;
            fillRect.offsetMax = Vector2.zero;

            GameObject handleAreaGO = new GameObject("Handle Slide Area");
            handleAreaGO.transform.SetParent(go.transform, false);
            RectTransform handleArea = handleAreaGO.AddComponent<RectTransform>();
            handleArea.anchorMin = new Vector2(0f, 0f);
            handleArea.anchorMax = new Vector2(1f, 1f);
            handleArea.offsetMin = new Vector2(handleWidth / 2f, 0f);
            handleArea.offsetMax = new Vector2(-handleWidth / 2f, 0f);

            GameObject handleGO = new GameObject("Handle");
            handleGO.transform.SetParent(handleAreaGO.transform, false);
            Image handle = handleGO.AddComponent<Image>();
            handle.sprite = uiSprite;
            handle.type = Image.Type.Sliced;
            handle.color = Color.white;
            RectTransform handleRect = handle.GetComponent<RectTransform>();
            handleRect.anchorMin = new Vector2(0f, 0f);
            handleRect.anchorMax = new Vector2(0f, 1f);
            handleRect.pivot = new Vector2(0.5f, 0.5f);
            // Only the width is fixed; a zero height against top-and-bottom anchors is full height.
            handleRect.sizeDelta = new Vector2(handleWidth, 0f);
            handleRect.anchoredPosition = Vector2.zero;

            Slider slider = go.AddComponent<Slider>();
            slider.direction = Slider.Direction.LeftToRight;
            slider.fillRect = fillRect;
            slider.handleRect = handleRect;
            slider.targetGraphic = handle;
            slider.wholeNumbers = false;
            // The range and the starting value are PauseMenu's to set - they belong to GameSettings,
            // and seeding them here would put the same number in two places.

            // Same treatment as the buttons: a white graphic tinted by the ColorBlock, since a
            // multiply against an already-dark handle has nothing left to brighten with.
            ColorBlock colors = slider.colors;
            colors.normalColor = new Color(0.62f, 0.1f, 0.1f, 1f);
            colors.highlightedColor = new Color(0.85f, 0.2f, 0.2f, 1f);
            colors.pressedColor = new Color(1f, 0.35f, 0.35f, 1f);
            colors.selectedColor = colors.highlightedColor;
            colors.fadeDuration = 0.12f;
            slider.colors = colors;

            return slider;
        }

        // The title screen: a camera, a canvas and a still of the room. Deliberately almost
        // nothing, because the whole point of it being a separate scene is that it opens instantly
        // while the room behind it takes a real moment to come in.
        private static void BuildMainMenuScene()
        {
            Scene menu = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);

            GameObject camGO = new GameObject("MenuCamera");
            camGO.tag = "MainCamera";
            Camera cam = camGO.AddComponent<Camera>();
            cam.clearFlags = CameraClearFlags.SolidColor;
            // Black behind everything: the background image is stretched to the screen, but a
            // window shaped nothing like 16:9 should fall away to black rather than to the URP
            // default blue.
            cam.backgroundColor = Color.black;
            camGO.AddComponent<AudioListener>();

            GameObject canvasGO = new GameObject("Canvas");
            Canvas canvas = canvasGO.AddComponent<Canvas>();
            canvas.renderMode = RenderMode.ScreenSpaceOverlay;
            CanvasScaler scaler = canvasGO.AddComponent<CanvasScaler>();
            scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;
            scaler.referenceResolution = new Vector2(1920f, 1080f);
            scaler.screenMatchMode = CanvasScaler.ScreenMatchMode.MatchWidthOrHeight;
            scaler.matchWidthOrHeight = 0.5f;
            canvasGO.AddComponent<GraphicRaycaster>();

            // The captured room, and a scrim over it. The room is near-white and the HUD's red
            // would fight it head-on; the scrim also puts the picture behind the title rather than
            // beside it, which is what a background is for.
            GameObject backgroundGO = new GameObject("Background");
            backgroundGO.transform.SetParent(canvasGO.transform, false);
            Image background = backgroundGO.AddComponent<Image>();
            Sprite shot = AssetDatabase.LoadAssetAtPath<Sprite>(MenuBackgroundPath);
            background.sprite = shot;
            // A missing capture leaves a deliberate dark panel rather than uGUI's default white
            // box, so a build without a graphics device still produces a menu that looks intended.
            background.color = shot != null ? Color.white : new Color(0.06f, 0.06f, 0.07f, 1f);
            background.raycastTarget = false;
            Stretch(background.GetComponent<RectTransform>());
            // AND IT MOVES. See MenuBackdrop: a still photograph behind a menu reads as a loading
            // screen, and the same picture drifting reads as a place the game is already running in.
            // It overscans the canvas, so the `Stretch` above sets the size it slides WITHIN.
            backgroundGO.AddComponent<MenuBackdrop>();

            // **AND ONE SIDE OF IT GOES OUT.** The same shot with the left-hand fixtures doused, laid
            // over the lit one at an alpha `MenuFlicker` cuts between - see that script for why a
            // photograph cannot flicker any other way, and why the pattern is hard cuts rather than a
            // fade.
            //
            // **A CHILD OF THE BACKGROUND, WHICH IS WHAT KEEPS THE TWO REGISTERED.** `MenuBackdrop`
            // slides the picture around to stop it reading as a loading screen; a sibling would sit
            // still while the lit frame drifted under it, and the flicker would arrive as a picture
            // jumping half a metre sideways. Stretched to the parent, it inherits every pixel of that
            // motion for free.
            Sprite darkShot = AssetDatabase.LoadAssetAtPath<Sprite>(MenuBackgroundDarkPath);
            if (darkShot != null)
            {
                GameObject darkGO = new GameObject("BackgroundDark");
                darkGO.transform.SetParent(backgroundGO.transform, false);
                Image darkImage = darkGO.AddComponent<Image>();
                darkImage.sprite = darkShot;
                // Transparent at rest - the room is whole until the fault takes it.
                darkImage.color = new Color(1f, 1f, 1f, 0f);
                darkImage.raycastTarget = false;
                Stretch(darkImage.GetComponent<RectTransform>());
                darkGO.AddComponent<MenuFlicker>();
            }
            else
            {
                // Said rather than skipped silently: a menu with no flicker looks exactly like a menu
                // whose second capture failed, and the two want telling apart.
                Debug.LogWarning($"[SceneBuilder] {MenuBackgroundDarkPath} is missing, so the title "
                               + "screen will not flicker. Rebuild from the Editor with a graphics "
                               + "device.");
            }

            // THE SCRIM IS A THIRD OF WHAT IT WAS, and it is a gradient rather than a flat wash.
            //
            // At 0.5 flat it was doing two jobs badly: darkening the whole picture to make red text
            // legible anywhere on it, which threw away the one thing the shot has going for it - the
            // room is BRIGHT, and a bright room is what this game looks like. The menu is down the
            // left edge now, so only the left edge needs protecting. A horizontal ramp does that and
            // leaves the room at nearly its captured brightness on the right, where the eye goes.
            GameObject scrimGO = new GameObject("Scrim");
            scrimGO.transform.SetParent(canvasGO.transform, false);
            Image scrim = scrimGO.AddComponent<Image>();
            Sprite scrimSprite = MakeMenuScrimSprite();
            scrim.sprite = scrimSprite;
            scrim.type = Image.Type.Simple;
            // WHITE ONLY IF THE RAMP LOADED. A uGUI `Image` with a null sprite draws a solid rect at
            // its colour, so white-plus-no-sprite is a white sheet over the whole title screen -
            // which is what a failed import produced. The fallback is the flat wash this replaced,
            // lightened, so a menu that loses its gradient is still a menu.
            scrim.color = scrimSprite != null ? Color.white : new Color(1f, 1f, 1f, 0.55f);
            if (scrimSprite == null)
                Debug.LogWarning("[SceneBuilder] menu scrim gradient failed to import; using a flat wash.");
            scrim.raycastTarget = false;
            Stretch(scrim.GetComponent<RectTransform>());

            GameObject menuGO = new GameObject("Menu");
            menuGO.transform.SetParent(canvasGO.transform, false);
            CanvasGroup menuGroup = menuGO.AddComponent<CanvasGroup>();
            Stretch(menuGO.AddComponent<RectTransform>());

            GameObject titleGO = new GameObject("Title");
            titleGO.transform.SetParent(menuGO.transform, false);
            Text title = titleGO.AddComponent<Text>();
            title.font = UIFont();
            // **AND BACK TO LIGHT AT 86** (2026-08-28, by request: thin suits the game).
            //
            // It went ExtraLight -> ExtraBold earlier the same day on the reasoning below, which was
            // about the game's SUBJECT - a facility, whose lettering would be painted and heavy. That
            // reasoning was sound and lost to something better: the game's LOOK is a white room, thin
            // black grooves and a lot of empty space, and a title has to belong to what is on screen
            // rather than to what the fiction is about. Light is what the room is made of.
            //
            // Kept because it is the argument that will be made again -
            // **~~EXTRABOLD AT 86, UP FROM EXTRALIGHT~~** (was: "글자가 얇아").
            //
            // The thin setting was a real argument and it was the wrong one for this game. Thin at a
            // large size is the elegant-product voice - it reads as a design tool or a streaming
            // service, and it is what every default title screen reaches for. **This building is a
            // facility, and the title is on the FACILITY'S side of the split** (CLAUDE.md §3: `ROOM 2`,
            // `ERROR`, `FIRE AXE`, and the title stay English in every language because they are the
            // place talking to itself, not the game talking to the player). Painted-on plant lettering
            // is heavy, and heavy is what makes 86 read as stencilled on a wall rather than set in a
            // deck.
            //
            // The hierarchy the old note wanted is kept and inverted: the title is now the heaviest
            // thing on the screen and the five labels stay Medium at 26, so the ratio is still weight
            // and not four sizes with nothing between them.
            title.font = UIFont("Light");
            title.fontSize = 86;
            // CENTRED, while the buttons stay down the left edge. The two were moved together and
            // that was one step too far: a left-hung title over a left-hung column leaves the whole
            // right half empty and the words stop being a title at all. Centred over an off-centre
            // menu is the arrangement that reads - the name of the game belongs to the picture, the
            // buttons belong to the edge.
            title.alignment = TextAnchor.MiddleCenter;
            // CHARCOAL, not red. See MenuInk: red is the alarm this game rings, and a title screen
            // that rings it before anything has happened has nothing left to ring it with.
            title.color = MenuInk;
            // Spaced out in the string, exactly as IterationLabel does it and for the same reason:
            // uGUI's Text has no tracking control at all, and in a monospace face a space is one
            // cell. The in-game label and the title then read as the same typeface doing the same
            // thing, which is the point - both are the facility talking.
            title.text = "I T E R A T I O N";
            // "ROOM" is a SECOND Text below it rather than a line break, because one `Text` has one
            // font size and the two words do not want the same one - `ROOM` at 86 reads as a heading
            // of equal weight, which makes the pair a list instead of a title.
            title.lineSpacing = 1f;
            title.horizontalOverflow = HorizontalWrapMode.Overflow;
            title.verticalOverflow = VerticalWrapMode.Overflow;
            title.raycastTarget = false;
            // LEFT-HUNG, not centred. A centred title over a centred column is a poster: the screen
            // reads as a picture of a menu. Pushing both to the left edge puts the ROOM in the middle
            // of the frame with the words beside it, which is the arrangement horror titles on Steam
            // use and the reason they use it - the place is the subject, not the interface.
            //
            // Anchored to the LEFT EDGE rather than to the centre with a negative offset, so a wider
            // window widens the picture instead of dragging the words toward the middle.
            RectTransform titleRect = title.GetComponent<RectTransform>();
            titleRect.anchorMin = new Vector2(0.5f, 0.5f);
            titleRect.anchorMax = new Vector2(0.5f, 0.5f);
            titleRect.pivot = new Vector2(0.5f, 0.5f);
            titleRect.sizeDelta = new Vector2(1400f, 140f);
            titleRect.anchoredPosition = new Vector2(0f, 268f);

            // **~~Three fading echoes behind the word~~ ONE TITLE, 2026-08-28, by request.**
            // The idea was the ghost afterimage as a logotype, and it was about the right thing;
            // what it looked like on a real screen was the word printed four times. At 86pt with the
            // letters a cell apart there is no offset that clears its own NEIGHBOUR without also
            // being far enough to read as a separate word - which is a fact about a monospace face
            // set this large, and not something a smaller step would have fixed.
            //
            // `MakeTitleAfterimage` is kept for whatever wants a trail at a size where one works.

            GameObject subtitleGO = new GameObject("TitleRoom");
            subtitleGO.transform.SetParent(menuGO.transform, false);
            Text subtitle = subtitleGO.AddComponent<Text>();
            // MEDIUM against the title's Light, which is the pairing this started with and the one
            // that works: the smaller word carries the weight, and that is what lets it hold its own
            // beneath the larger one without being set any larger. The buttons stay Bold - they are
            // the thing you click, and they are not the title.
            subtitle.font = UIFont("Medium");
            // Smaller, and spaced WIDER, so the shorter word spans a similar width to the one above
            // it. Letter-spaced in the string for the reason IterationLabel is: uGUI's Text has no
            // tracking control, and in a monospace face a space is exactly one cell.
            subtitle.fontSize = 52;
            subtitle.alignment = TextAnchor.MiddleCenter;
            // **THE ONE RED THING ON THE SCREEN AT REST**, and it is one word of the game's own name.
            // Everything else - title, five labels - is charcoal, so this is the only place the eye is
            // sent, and the colour still means what it means everywhere else in the building.
            //
            // At 52 it is large enough that red on white does not vibrate the way a 26pt label would,
            // which is the other half of why the accent is HERE and not on the buttons.
            subtitle.color = MenuAccent;
            subtitle.text = "R  O  O  M";
            subtitle.horizontalOverflow = HorizontalWrapMode.Overflow;
            subtitle.verticalOverflow = VerticalWrapMode.Overflow;
            subtitle.raycastTarget = false;
            RectTransform subtitleRect = subtitle.GetComponent<RectTransform>();
            subtitleRect.anchorMin = new Vector2(0.5f, 0.5f);
            subtitleRect.anchorMax = new Vector2(0.5f, 0.5f);
            subtitleRect.pivot = new Vector2(0.5f, 0.5f);
            subtitleRect.sizeDelta = new Vector2(1400f, 90f);
            subtitleRect.anchoredPosition = new Vector2(0f, 190f);

            // CONTINUE FIRST, since 2026-08-20. It is the entry a returning player wants and the one
            // that needs no decision; PLAY under it opens the cycle picker, which is a decision. The
            // two swapped meanings on the same day - see MainMenu.Play and MainMenu.Continue.
            //
            // CONTINUE is HIDDEN by `MainMenu.Start` when nothing has been played, so a first-time
            // title screen is PLAY / SETTINGS / QUIT with a gap where this is. The gap is deliberate:
            // shuffling the column up would move PLAY under the player's cursor between sessions.
            // THREE WAYS IN, AND EACH MEANS ONE THING: resume, start from the beginning, jump to a
            // cycle. The two a player uses have no page in between; only the rare one does.
            // **CHARCOAL, AND BOLD** (2026-08-28, by request: the words were too thin). The plate
            // under each of these is transparent until the pointer is on it (see `MakeMenuButton`),
            // so what the player sees at rest is five words printed on a white wall - which is what
            // the room is. Words printed on a wall with nothing around them have only their own
            // weight to hold the screen with, which is exactly why Medium was not enough here and
            // would have been fine inside a box.
            Button continueButton = MakeMenuButton(menuGO.transform, "ContinueButton",
                                                   "CONTINUE", new Vector2(0f, -30f), MenuInk, "Bold");
            Localize(continueButton, "menu.continue", "  ");
            Button playButton = MakeMenuButton(menuGO.transform, "PlayButton", "PLAY",
                                               new Vector2(0f, -118f), MenuInk, "Bold");
            Localize(playButton, "menu.play", "  ");
            Button cycleSelectButton = MakeMenuButton(menuGO.transform, "CycleSelectButton",
                                                      "CYCLE SELECT", new Vector2(0f, -206f), MenuInk, "Bold");
            Localize(cycleSelectButton, "menu.cycleSelect", "  ");
            // THE LAST RUN'S BILL, IN THE BOTTOM-RIGHT CORNER rather than in the column.
            //
            // It is not a way into the game and it is not a way out of it, which is what every entry
            // in that column is - and a sixth row pushed QUIT down to within seventy pixels of the
            // screen edge. Cornered, it reads as what it is: a thing the facility keeps, off to one
            // side of the choices.
            Button recordButton = MakeMenuButton(menuGO.transform, "RecordButton",
                                                 "RECORD", Vector2.zero, MenuInk, "Bold");
            Localize(recordButton, "menu.record", "  ");
            // ONE ROW UP: CREDITS is the bottom of this pair (2026-08-24, by request).
            CornerBottomRight(recordButton.GetComponent<RectTransform>(), 78f);
            // ~~TEST: CYCLE BOUNDARY~~ REMOVED 2026-08-15, by request. It was a development shortcut
            // into the cycle boundary with cycle 1 already finished, sitting on the title screen
            // between CONTINUE and QUIT and labelled loudly so it could not be mistaken for content.
            //
            // What it did is not lost: CONTINUE's cycle picker reaches any cycle from its own bed,
            // which covers most of what the shortcut was for, and `DebugStart.AtCycleBoundary` and
            // `LoopManager.JumpToBoundary` are both still there for a developer who sets the flag by
            // hand. What is gone is the entry on the screen a player sees.
            //
            // QUIT moves up into the gap rather than leaving a hole in the column.
            Button settingsButton = MakeMenuButton(menuGO.transform, "SettingsButton",
                                                   "SETTINGS", new Vector2(0f, -294f), MenuInk, "Bold");
            Localize(settingsButton, "menu.settings", "  ");
            // -382 AGAIN, now that CREDITS has left the column for the bottom-right corner. It was
            // slid to -470 to make room for it; the column's pitch is 88 throughout and this closes
            // the gap rather than leaving a hole where a button used to be.
            Button quitButton = MakeMenuButton(menuGO.transform, "QuitButton", "QUIT",
                                               new Vector2(0f, -382f), MenuInk, "Bold");

            // THE CYCLE PICKER, on a page of its own over the same background. A title screen that
            // grows a row every time the game grows a cycle stops being a title screen.
            GameObject cycleGO = new GameObject("CyclePicker");
            cycleGO.transform.SetParent(canvasGO.transform, false);
            CanvasGroup cycleGroup = cycleGO.AddComponent<CanvasGroup>();
            cycleGroup.alpha = 0f;
            cycleGroup.blocksRaycasts = false;
            Stretch(cycleGO.AddComponent<RectTransform>());

            // ONE PER CYCLE AND NOTHING ELSE. The calibration room had an entry here for one build
            // and it was a mistake worth recording: it and CYCLE 1 both start cycle 1 and differ only
            // in whether the sensitivity step runs, which no label can carry. PLAY is that path now,
            // and the sensitivity is adjustable on SETTINGS either way.
            //
            // The count is read from the cycle list rather than written here, so adding a cycle adds
            // its button - the same rule LoopManager follows for deciding which cycle is the last.
            var cycleButtons = new Button[CycleCount];
            for (int i = 0; i < CycleCount; i++)
                cycleButtons[i] = MakeMenuButton(cycleGO.transform, $"CycleButton_{i + 1}",
                                                 $"CYCLE {i + 1}", new Vector2(0f, -30f - i * 88f),
                                                 MenuInk, "Bold");

            // AND ONE "END" ENTRY PER CYCLE THAT HAS A SUCCESSOR: start that cycle with its last room
            // already finished, so the hatch into the next one opens within seconds. A development
            // shortcut, on the page that is already one - see MainMenu.PlayFromCycleEnd.
            //
            // `CycleCount - 1` rather than a written number, so the day cycle 4 exists this grows by
            // itself and the last cycle never gets an entry it has nothing to cross into.
            var cycleEndButtons = new Button[Mathf.Max(0, CycleCount - 1)];
            for (int i = 0; i < cycleEndButtons.Length; i++)
                cycleEndButtons[i] = MakeMenuButton(cycleGO.transform, $"CycleEndButton_{i + 1}",
                                                    $"CYCLE {i + 1} END", 
                                                    new Vector2(0f, -30f - (CycleCount + i) * 88f),
                                                    MenuInk, "Bold");

            Button cycleBack = MakeMenuButton(cycleGO.transform, "CycleBackButton",
                                              "BACK",
                                              new Vector2(0f, -30f - (CycleCount + cycleEndButtons.Length) * 88f),
                                              MenuInk, "Bold");
            Localize(cycleBack, "menu.back", "  ");

            // THE RECORD PAGE, over the same background as the cycle picker and laid out the same:
            // one block of monospaced text and a way back. The table itself comes from `RunReport`,
            // which is also what the ending card prints - one formatter, two screens.
            GameObject recordGO = new GameObject("Record");
            recordGO.transform.SetParent(canvasGO.transform, false);
            CanvasGroup recordGroup = recordGO.AddComponent<CanvasGroup>();
            recordGroup.alpha = 0f;
            recordGroup.blocksRaycasts = false;
            Stretch(recordGO.AddComponent<RectTransform>());

            GameObject recordTableGO = new GameObject("RecordTable");
            recordTableGO.transform.SetParent(recordGO.transform, false);
            Text recordTable = recordTableGO.AddComponent<Text>();
            recordTable.font = UIFont("Medium");
            recordTable.fontSize = 22;
            recordTable.alignment = TextAnchor.UpperCenter;
            recordTable.color = MenuInk;
            // Padded columns need a monospace cell, which UIFont is - see RunReport.Row.
            recordTable.lineSpacing = 1.3f;
            recordTable.text = string.Empty;
            recordTable.horizontalOverflow = HorizontalWrapMode.Overflow;
            recordTable.verticalOverflow = VerticalWrapMode.Overflow;
            recordTable.raycastTarget = false;
            RectTransform recordTableRect = recordTable.GetComponent<RectTransform>();
            recordTableRect.anchorMin = new Vector2(0.5f, 0.5f);
            recordTableRect.anchorMax = new Vector2(0.5f, 0.5f);
            recordTableRect.pivot = new Vector2(0.5f, 0.5f);
            recordTableRect.sizeDelta = new Vector2(1000f, 320f);
            // Anchored so the first row starts just under the title, and the block grows downward as
            // cycles are added without anything above it moving.
            recordTableRect.anchoredPosition = new Vector2(0f, -30f);

            Button recordBack = Localize(MakeMenuButtonInk(recordGO.transform, "RecordBackButton",
                                                  "BACK", new Vector2(0f, -230f)), "menu.back", "  ");

            // SETTINGS, on its own page over the same background as the cycle picker. It belongs on
            // the TITLE screen rather than only in the pause menu because the first thing this game
            // does is talk - the PA is running before the player has a control to press - and "turn it
            // down" should not require starting first. The same argument now carries the other two:
            // a player who already knows their sensitivity, or who cannot use the default movement
            // keys at all, should not have to play an iteration to say so.
            GameObject settingsGO = new GameObject("Settings");
            settingsGO.transform.SetParent(canvasGO.transform, false);
            CanvasGroup settingsGroup = settingsGO.AddComponent<CanvasGroup>();
            settingsGroup.alpha = 0f;
            settingsGroup.blocksRaycasts = false;
            Stretch(settingsGO.AddComponent<RectTransform>());

            // EVERYTHING ON ONE LEFT EDGE, the same one the title screen's buttons and this page's
            // own BACK are hung on - see MakeLeftColumn for why that is a container rather than a
            // number written into each row.
            Transform col = MakeLeftColumn(settingsGO.transform, "Column");

            // The page says its own name, in the title's face rather than the buttons'. The title
            // screen sets its hierarchy with SIZE and WEIGHT and no rules or boxes anywhere, so this
            // page does too: ExtraLight 52 against the rows' Regular 18 is what separates them.
            Localize(MakeRowLabelWeight(col, "SettingsHeading", "SETTINGS",
                new Vector2(300f, 330f), new Vector2(600f, 70f), TextAnchor.MiddleLeft, MenuInk,
                "ExtraLight", 52), "menu.settings");

            // THE THREE ROWS, evenly spaced, label on the edge and control at one indent. Language
            // first because it is the setting that rewrites every other label on the page, including
            // BACK - a player who has landed here by accident should reach it before reading anything.
            const float languageRowY = 240f;
            const float volumeRowY = 185f;
            const float sensitivityRowY = 130f;

            MakeRowLabelInk(col, "LanguageLabel", "LANGUAGE",
                new Vector2(SettingsLabelWidth / 2f, languageRowY),
                new Vector2(SettingsLabelWidth, 30f), TextAnchor.MiddleLeft, MenuInk);
            // **THE TWO BUTTONS ARE NEVER TRANSLATED.** "ENGLISH" and "한국어" each stay in their own
            // language whichever is selected, which is the one convention every language picker
            // follows and the only one that works: a player who has landed in a language they cannot
            // read has to be able to find their way out, and "영어"/"한국어" would be two words they
            // cannot tell apart. It is also why they are plain `MakeSettingsButton`s with no
            // `Localize` on them.
            Button englishButton = MakeSettingsButton(col, "LanguageEnglish", "ENGLISH",
                new Vector2(SettingsControlX + 75f, languageRowY), new Vector2(150f, 30f), out Text englishInk);
            Button koreanButton = MakeSettingsButton(col, "LanguageKorean", "한국어",
                new Vector2(SettingsControlX + 240f, languageRowY), new Vector2(150f, 30f), out Text koreanInk);
            // The Korean button has to be able to draw its own name before anything has switched, so
            // it is the one label in the project that takes the Hangul face at build time.
            Font koreanFace = KoreanUIFont();
            if (koreanFace != null) koreanInk.font = koreanFace;

            (Slider volumeSlider, Text volumeValue) =
                MakeSettingsSliderRow(col, "Volume", "VOLUME", "set.volume", "80%", volumeRowY, MenuInk);
            (Slider sensitivitySlider, Text sensitivityValue) =
                MakeSettingsSliderRow(col, "Sensitivity", "MOUSE SENSITIVITY", "set.sensitivity",
                                      "1.10", sensitivityRowY, MenuInk);

            KeyBindingPanel bindings = BuildKeyBindings(col, settingsGroup);

            // BACK sits on the same edge as everything above it, which is the whole point of the
            // column. It anchors to the screen's left rather than to the column, because that is what
            // MakeMenuButton does and the two edges are now the same edge.
            Button settingsBack = Localize(MakeMenuButtonInk(settingsGO.transform, "SettingsBackButton",
                                                 "BACK", new Vector2(0f, -355f)), "menu.back", "  ");

            // The loading state, built over the same middle of the screen the buttons occupy so
            // one replaces the other in place instead of the eye having to travel.
            GameObject loadingGO = new GameObject("Loading");
            loadingGO.transform.SetParent(canvasGO.transform, false);
            CanvasGroup loadingGroup = loadingGO.AddComponent<CanvasGroup>();
            loadingGroup.alpha = 0f;
            loadingGroup.blocksRaycasts = false;
            Stretch(loadingGO.AddComponent<RectTransform>());

            GameObject loadingLabelGO = new GameObject("Label");
            loadingLabelGO.transform.SetParent(loadingGO.transform, false);
            Text loadingLabel = loadingLabelGO.AddComponent<Text>();
            loadingLabel.font = UIFont();
            loadingLabel.fontSize = 22;
            loadingLabel.alignment = TextAnchor.MiddleCenter;
            // Charcoal like everything else on this surface - the loading page has no backdrop of
            // its own, it is the same photograph of a white room with a bar drawn over it.
            loadingLabel.font = UIFont("Medium");
            loadingLabel.color = MenuInk;
            loadingLabel.text = "LOADING 0%";
            loadingLabel.raycastTarget = false;
            RectTransform loadingLabelRect = loadingLabel.GetComponent<RectTransform>();
            loadingLabelRect.anchorMin = new Vector2(0.5f, 0.5f);
            loadingLabelRect.anchorMax = new Vector2(0.5f, 0.5f);
            loadingLabelRect.sizeDelta = new Vector2(600f, 40f);
            loadingLabelRect.anchoredPosition = new Vector2(0f, -20f);

            GameObject barGO = new GameObject("Bar");
            barGO.transform.SetParent(loadingGO.transform, false);
            Image bar = barGO.AddComponent<Image>();
            bar.color = new Color(0f, 0f, 0f, 0.6f);
            bar.raycastTarget = false;
            RectTransform barRect = bar.GetComponent<RectTransform>();
            barRect.anchorMin = new Vector2(0.5f, 0.5f);
            barRect.anchorMax = new Vector2(0.5f, 0.5f);
            barRect.sizeDelta = new Vector2(560f, 8f);
            barRect.anchoredPosition = new Vector2(0f, -60f);

            GameObject fillGO = new GameObject("Fill");
            fillGO.transform.SetParent(barGO.transform, false);
            Image fill = fillGO.AddComponent<Image>();
            // A filled Image needs a sprite to have anything to fill; this is uGUI's own.
            fill.sprite = AssetDatabase.GetBuiltinExtraResource<Sprite>("UI/Skin/UISprite.psd");
            fill.type = Image.Type.Filled;
            fill.fillMethod = Image.FillMethod.Horizontal;
            fill.fillAmount = 0f;
            fill.color = Color.red;
            fill.raycastTarget = false;
            Stretch(fill.GetComponent<RectTransform>());

            // THE CREDITS, read out of the models themselves and put on a page of their own.
            //
            // What was here was a single dim line reading "FURNITURE MODELS: CREATIVE COMMONS". The
            // reasoning for it was right - credit belongs where the player already is, not somewhere
            // they have to go looking - but the line was not an attribution, and twenty-six of them
            // do not fit on it. So the strip stays as the POINTER and the page carries the content:
            // still on the title screen, still unmissable, one click away instead of nought.
            System.Collections.Generic.List<ModelCredit> modelCredits = ReadModelCredits();
            CheckModelLicences(modelCredits);
            WriteAttributionFile(modelCredits);

            (CanvasGroup creditsGroup, Button creditsBack) = BuildCreditsPage(canvasGO.transform, modelCredits);

            // **OUT OF THE COLUMN AND INTO THE CORNER** (2026-08-24, by request), directly above
            // RECORD - and the reason is the one already written beside RECORD rather than a new one.
            // Every entry in that column is a way INTO the game or a way OUT of it; a licence list is
            // neither. Two of them now sit off to one side, which is where the things the facility
            // keeps belong.
            Button creditsButton = MakeMenuButton(menuGO.transform, "CreditsButton", "CREDITS",
                                                  Vector2.zero, MenuInk, "Bold");
            Localize(creditsButton, "menu.credits", "  ");
            // THE BOTTOM OF THE CORNER PAIR, with RECORD sitting on top of it.
            CornerBottomRight(creditsButton.GetComponent<RectTransform>());

            // THE ROOM TONE, ON THE TITLE SCREEN. The same clip `RoomAmbience` runs in the game, at
            // less than half the level - see MainMenu.ambienceVolume. 2D, looping, and started at
            // zero so `MainMenu.Start` can ride it up instead of the loop's first sample clicking in.
            //
            // The menu scene already has the one AudioListener it is allowed (on its camera), so this
            // needs nothing else to be heard - and `GameSettings.ApplyAudio` in MainMenu.Awake has
            // already put the player's saved master volume on that listener by the time it fades in.
            AudioSource menuTone = MakeSource(canvasGO.transform, "Ambience", 0f, 0f, loop: true);
            menuTone.clip = LoadClip(SfxDir, "sfx_ominous_loop");
            menuTone.playOnAwake = true;

            MainMenu mainMenu = canvasGO.AddComponent<MainMenu>();
            mainMenu.menuGroup = menuGroup;
            mainMenu.loadingGroup = loadingGroup;
            mainMenu.playButton = playButton;
            mainMenu.quitButton = quitButton;
            mainMenu.continueButton = continueButton;
            mainMenu.ambience = menuTone;
            mainMenu.cycleSelectButton = cycleSelectButton;
            mainMenu.recordButton = recordButton;
            mainMenu.recordBackButton = recordBack;
            mainMenu.recordGroup = recordGroup;
            mainMenu.recordText = recordTable;
            mainMenu.cycleBackButton = cycleBack;
            mainMenu.cycleGroup = cycleGroup;
            mainMenu.cycleButtons = cycleButtons;
            mainMenu.cycleEndButtons = cycleEndButtons;
            mainMenu.creditsButton = creditsButton;
            mainMenu.creditsBackButton = creditsBack;
            mainMenu.creditsGroup = creditsGroup;
            mainMenu.settingsButton = settingsButton;
            mainMenu.settingsBackButton = settingsBack;
            mainMenu.settingsGroup = settingsGroup;
            mainMenu.sensitivitySlider = sensitivitySlider;
            mainMenu.englishButton = englishButton;
            mainMenu.koreanButton = koreanButton;
            mainMenu.englishInk = englishInk;
            mainMenu.koreanInk = koreanInk;
            mainMenu.sensitivityValue = sensitivityValue;
            mainMenu.bindings = bindings;
            mainMenu.volumeSlider = volumeSlider;
            mainMenu.volumeValue = volumeValue;
            mainMenu.loadingFill = fill;
            mainMenu.loadingLabel = loadingLabel;

            // uGUI buttons are inert without one, and an empty scene has nothing at all in it.
            GameObject eventSystem = new GameObject("EventSystem");
            eventSystem.AddComponent<UnityEngine.EventSystems.EventSystem>();
            eventSystem.AddComponent<UnityEngine.EventSystems.StandaloneInputModule>();

            EditorSceneManager.SaveScene(menu, MenuScenePath);
        }

        // The step between PLAY and the load: move the mouse, watch the room turn, set the number
        // before the clock has ever started. See SensitivityCalibration for why the pointer is
        // captured here and why that forces the wheel and the arrow keys instead of a dragged
        // slider - the pause menu's slider stays as the way to change it later.
        //
        // Laid out around the exact middle of the screen, which is where the buttons were: the page
        // this replaces and the page it becomes occupy the same space, so nothing has to travel.
        // The sensitivity step, built on the ROOM's canvas rather than the menu's - the player sets
        // it while standing in the finished room looking through the real camera. See
        // SensitivityCalibration for the two attempts that came before and why neither worked.
        //
        // The readout sits on its own dark plate rather than behind a full-screen scrim, so the
        // room stays at full brightness behind it. The thing being judged is how the room moves;
        // dimming it to make the text legible would be dimming the subject.
        private static SensitivityCalibration BuildCalibrationPage(Transform canvas)
        {
            GameObject root = new GameObject("Calibration");
            root.transform.SetParent(canvas, false);
            CanvasGroup group = root.AddComponent<CanvasGroup>();
            group.alpha = 0f;
            group.blocksRaycasts = false;
            Stretch(root.AddComponent<RectTransform>());

            // Almost nothing is drawn here any more: the control list, the gauge and the value
            // all moved onto the calibration room's own south wall, which is the wall the player
            // spawns facing. What is left on the SCREEN is the one line that has to follow the eye
            // wherever it goes, because it is how the player leaves.
            //
            // No plate behind it. The line is empty for all of a normal run - it only appears
            // when the browser has refused pointer capture - and a plate under an empty string is
            // a black bar across the bottom of the screen for no reason.
            Text lockHint = MakeMenuLine(root.transform, "LockHint", "[ENTER]  TO BEGIN", 24,
                Color.red, new Vector2(0f, -400f), new Vector2(1200f, 40f));

            SensitivityCalibration calibration = root.AddComponent<SensitivityCalibration>();
            calibration.group = group;
            calibration.lockHint = lockHint;

            // Everything else on the canvas goes away while this is up. The countdown reading 1:00
            // and a dimmed END CYCLE control are describing a loop that has not started, and the
            // player is being asked to judge how the ROOM moves - anything else on screen is
            // something for the eye to land on instead.
            //
            // Expressed as "all but these two" rather than as a list of what to hide, so a HUD
            // element added later is covered without anyone remembering to come back here. PauseMenu
            // stays live because a player who wants out must not be trapped by a settings screen.
            var hidden = new System.Collections.Generic.List<GameObject>();
            foreach (Transform child in canvas)
            {
                // ControlHints stays on as well as PauseMenu: the start button on the wall is an
                // IInteractHintTarget, so the E disc has to be able to appear over it.
                if (child == root.transform || child.name == "PauseMenu" || child.name == "ControlHints") continue;
                hidden.Add(child.gameObject);
            }
            calibration.hideWhileActive = hidden.ToArray();

            return calibration;
        }

        // The calibration room's south wall - the one the player spawns facing - carrying the
        // control list, the sensitivity gauge and the value, plus two physical plates below it that
        // raise and lower the setting.
        //
        // On the wall rather than on the screen because the room is built out of displays, so the
        // facility explaining itself on one is the same move Room3 makes. It also puts the readout
        // and the control that drives it in the same place: the player presses E at a plate and
        // watches the number above it move, which no screen overlay can do.
        //
        // The plates carry a second job. They are the only thing in the room E can be pressed at,
        // so the control list above can name E and have it be true in the same room. A practice
        // ball existed for exactly that and was deleted once these took the work over - one fixture
        // doing two jobs beats two doing one each.
        private static CalibrationStartButton BuildCalibrationWall(Transform parent, float roomCenterZ,
                                                                   SensitivityCalibration calibration)
        {
            GameObject root = new GameObject("CalibrationWall");
            root.transform.SetParent(parent, false);

            float wallZ = roomCenterZ - RoomDepth / 2f;   // inner face of the south wall

            // --- the display ---
            GameObject faceGO = new GameObject("Display");
            faceGO.transform.SetParent(root.transform, false);

            Canvas canvas = faceGO.AddComponent<Canvas>();
            canvas.renderMode = RenderMode.WorldSpace;

            RectTransform rect = faceGO.GetComponent<RectTransform>();
            // Taller than it was, because the plate that used to bound it is gone. Nothing physical
            // sits under this on the south wall, so the height is free.
            rect.sizeDelta = new Vector2(1600f, 820f);
            rect.localScale = Vector3.one * 0.004f;       // -> 6.4m x 3.28m on an 8.75m x 5.41m wall
            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            // Set through anchoredPosition3D and AFTER the Canvas exists - see MakeWallFace for the
            // two traps in that sentence.
            rect.anchoredPosition3D = new Vector3(0f, 3.05f, wallZ + 0.05f);
            // Forward points INTO the wall: a world-space canvas is legible when its forward matches
            // the direction the viewer is LOOKING, and a player in this room looks south at it.
            rect.localRotation = Quaternion.Euler(0f, 180f, 0f);

            CanvasGroup wallGroup = faceGO.AddComponent<CanvasGroup>();
            wallGroup.alpha = 0f;
            wallGroup.blocksRaycasts = false;
            wallGroup.interactable = false;

            // NO PLATE. This used to sit on a lit near-black slab, the same one Room3's message uses,
            // and it was removed for the reason the Room2 pictogram's was: a plate is the facility
            // interrupting, which suits a sign that stops an iteration and does not suit the room
            // quietly labelling its own controls. Stencilled on the panelling, it belongs to the wall.
            //
            // Two consequences, both handled below. Everything got BIGGER, because a plate was the only
            // thing making the old sizes feel filled - on bare wall the same glyphs read as small. And
            // the colours changed: the old red-on-black values were chosen against a dark ground and
            // wash out on white panelling.

            // --- controls, upper half ---
            // Sized in canvas units; at 0.004 scale an 84px cap is 0.34m of wall, up from 0.25m.
            const float key = 84f, gap = 9f, step = key + gap, capGap = 30f;
            const float keysW = 3f * key + 2f * gap;   // 270
            // Charcoal, not the old pale red: on white panelling a light red is barely there, and this
            // is the same ink the Room2 sign uses, so the game's two wordless displays match. Well
            // clear of GrooveDark (0.04) so a glyph cannot be mistaken for a seam.
            Color wallText = new Color(0.20f, 0.20f, 0.23f, 0.78f);

            const float keysX = -430f;
            // Spaced from the edges of what sits on each row, not by a uniform pitch: the W/A/S/D
            // block is two caps deep and straddles its row where SPACE is a single 44px bar. A
            // uniform pitch is what put the bar inside the A/S/D row twice on the screen version.
            // Spaced from the bottom edge of what sits on the row above, not by a uniform pitch: the
            // W/A/S/D block is two caps deep and straddles its row where SPACE is a single bar. A
            // uniform pitch is what put the bar inside the A/S/D row twice on the screen version.
            const float rowMove = 300f;          // W 304.5..388.5, A/S/D 211.5..295.5
            const float rowJump = 162.5f;        // SPACE 133.5..191.5, so 20 clear of A/S/D
            const float rowInteract = 71.5f;     // E 29.5..113.5, so 20 clear of SPACE

            MakeKeyCap(faceGO.transform, "KeyW", "W", new Vector2(keysX, rowMove + step / 2f), new Vector2(key, key), 36);
            MakeKeyCap(faceGO.transform, "KeyA", "A", new Vector2(keysX - step, rowMove - step / 2f), new Vector2(key, key), 36);
            MakeKeyCap(faceGO.transform, "KeyS", "S", new Vector2(keysX, rowMove - step / 2f), new Vector2(key, key), 36);
            MakeKeyCap(faceGO.transform, "KeyD", "D", new Vector2(keysX + step, rowMove - step / 2f), new Vector2(key, key), 36);
            MakeKeyCap(faceGO.transform, "KeySpace", "SPACE", new Vector2(keysX, rowJump), new Vector2(keysW, 58f), 26);
            MakeKeyCap(faceGO.transform, "KeyE", "E", new Vector2(keysX, rowInteract), new Vector2(key, key), 36);

            // FIGURES INSTEAD OF WORDS. The room says nothing else in English, and this wall is the
            // first thing a player sees - so the one screen that has to be understood before the game
            // starts is the worst place to require reading. Same treatment as the Room2 sign.
            //
            // 100 against the keycaps' 84, because a figure needs more room than a letter to read at
            // all: the glyph is a whole body where a cap is one character. Centred on the row rather
            // than left-aligned as the old captions were, so both columns line up as a grid whatever
            // each row's key happens to be.
            const float figure = 100f;
            const float keyFigureX = keysX + keysW / 2f + capGap + figure / 2f;

            MakeWallIcon(faceGO.transform, "MoveFigure", FigureWalkIcon(), new Vector2(keyFigureX, rowMove), figure, wallText);
            MakeWallIcon(faceGO.transform, "JumpFigure", FigureJumpIcon(), new Vector2(keyFigureX, rowJump), figure, wallText);
            MakeWallIcon(faceGO.transform, "InteractFigure", FigurePressIcon(), new Vector2(keyFigureX, rowInteract), figure, wallText);

            // The right column is the mouse alone. Sprint and crouch were briefly here and moved to the
            // side walls: they are the two controls that are about HOW you cross a room, and putting
            // them on the walls you cross between says that better than a fifth row can.
            const float glyph = 104f;
            const float glyphX = 300f;
            // Level with the middle of the keyboard block, which spans 29.5 to 388.5.
            const float rowLook = 209f;
            const float rightFigureX = glyphX + glyph / 2f + capGap + figure / 2f;

            GameObject mouseGO = new GameObject("MouseGlyph");
            mouseGO.transform.SetParent(faceGO.transform, false);
            Image mouse = mouseGO.AddComponent<Image>();
            mouse.sprite = MouseIcon();
            mouse.color = wallText;
            mouse.raycastTarget = false;
            mouse.preserveAspect = true;
            RectTransform mouseRect = mouse.GetComponent<RectTransform>();
            mouseRect.anchorMin = new Vector2(0.5f, 0.5f);
            mouseRect.anchorMax = new Vector2(0.5f, 0.5f);
            mouseRect.sizeDelta = new Vector2(glyph, glyph);
            mouseRect.anchoredPosition = new Vector2(glyphX, rowLook);

            MakeWallIcon(faceGO.transform, "LookFigure", FigureLookIcon(), new Vector2(rightFigureX, rowLook), figure, wallText);

            // ~~TAB, level with E~~ REMOVED with Tab itself, 2026-08-13. The hand holds one object
            // and E is the whole of handling it: press to pick up, press again to put down. The
            // second half of that is taught by the HUD's own prompt under the carried icon, where it
            // can appear at the moment there is something to put down - which a wall in the first
            // room cannot do.

            // --- sensitivity, lower half ---
            // The reds stay red - this is the facility's own voice and red on white panelling is the
            // strongest thing in the room - but everything that WAS a pale red on black had to darken,
            // because pale red on white is barely a mark.
            Color wallRed = new Color(0.74f, 0.09f, 0.09f, 1f);

            Localize(MakeMenuLine(faceGO.transform, "Headline", "M O U S E   S E N S I T I V I T Y", 48,
                wallRed, new Vector2(0f, -40f), new Vector2(1500f, 70f)), "cal.title");

            Text value = MakeMenuLine(faceGO.transform, "Value", "1.10", 56, wallRed,
                new Vector2(0f, -130f), new Vector2(500f, 70f));

            GameObject barGO = new GameObject("Gauge");
            barGO.transform.SetParent(faceGO.transform, false);
            Image bar = barGO.AddComponent<Image>();
            // The empty track. It was near-opaque black, which on a dark plate was a recess and on white
            // panelling would be a solid bar with a red one inside it. Light enough now to read as the
            // groove the fill sits in.
            bar.color = new Color(0.18f, 0.18f, 0.20f, 0.30f);
            bar.raycastTarget = false;
            RectTransform barRect = bar.GetComponent<RectTransform>();
            barRect.anchorMin = new Vector2(0.5f, 0.5f);
            barRect.anchorMax = new Vector2(0.5f, 0.5f);
            barRect.sizeDelta = new Vector2(950f, 28f);
            barRect.anchoredPosition = new Vector2(0f, -200f);

            GameObject fillGO = new GameObject("Fill");
            fillGO.transform.SetParent(barGO.transform, false);
            Image fill = fillGO.AddComponent<Image>();
            fill.sprite = AssetDatabase.GetBuiltinExtraResource<Sprite>("UI/Skin/UISprite.psd");
            fill.type = Image.Type.Filled;
            fill.fillMethod = Image.FillMethod.Horizontal;
            fill.fillAmount = 0.5f;
            fill.color = wallRed;
            fill.raycastTarget = false;
            Stretch(fill.GetComponent<RectTransform>());

            Localize(MakeMenuLine(faceGO.transform, "AdjustHint", "SCROLL TO ADJUST", 30,
                new Color(0.62f, 0.10f, 0.10f, 0.85f), new Vector2(0f, -250f), new Vector2(1400f, 44f)),
                "cal.scrollAdjust");
            Localize(MakeMenuLine(faceGO.transform, "BeginHint", "PRESS [E] AT THE PANEL BEHIND YOU", 34,
                wallRed, new Vector2(0f, -320f), new Vector2(1400f, 50f)), "cal.begin");

            // The two side walls: one control each, and nothing else on them.
            CanvasGroup sprintWall = MakeCalibrationSideWall(root.transform, "SprintWall", roomCenterZ,
                west: true, keyLabel: "SHIFT", figureSprite: FigureRunIcon(), ink: wallText);
            CanvasGroup crouchWall = MakeCalibrationSideWall(root.transform, "CrouchWall", roomCenterZ,
                west: false, keyLabel: "CTRL", figureSprite: FigureCrouchIcon(), ink: wallText);

            calibration.wallGroups = new[] { wallGroup, sprintWall, crouchWall };
            calibration.fill = fill;
            calibration.valueLabel = value;

            // --- the start button, on the OPPOSITE wall ---
            // The display is on the south wall and this is on the north, six metres behind the
            // player's back. That separation is the point: reading the panel and reaching the way
            // out costs a full 180 turn and a walk, which is exactly the thing the step is asking
            // the player to judge. Adjust at the display, turn, feel it, press - and if it was
            // wrong, turn back.
            //
            // It is one CELL OF THE WALL GRID rather than a box stuck on the wall: panel-sized,
            // sat 15mm proud, dark where its neighbours are white. The room's fiction is that the
            // panels are displays, so a single cell lit up and asking to be pressed is the room
            // speaking its own language - where a green slab was an object from another game.
            Material plateMat = MakeColorMaterial("CalibrationPlate", new Color(0.05f, 0.05f, 0.055f));
            // The keyword has to be compiled in for the press flash; a property block cannot turn a
            // shader keyword on. Black means it contributes nothing until E is pressed.
            plateMat.EnableKeyword("_EMISSION");
            plateMat.SetColor("_EmissionColor", Color.black);
            plateMat.globalIlluminationFlags = MaterialGlobalIlluminationFlags.RealtimeEmissive;
            EditorUtility.SetDirty(plateMat);

            const float panelW = GridCellWidth - GridLineThickness;    // 1.70, the visible face
            const float panelH = GridCellHeight - GridLineThickness;   // 1.3019
            const float proud = 0.03f;
            // Column 2 of 5 and row 1 of 4 on an end wall, i.e. dead centre horizontally at the
            // second row up. Cell centres are (i + 0.5) * cell, so this is 2.028m - head height,
            // which is where a wall panel worth reading belongs. Reach is a horizontal test, so
            // the height costs nothing.
            float buttonY = 1.5f * GridCellHeight;
            float northWallZ = roomCenterZ + RoomDepth / 2f;

            GameObject buttonRoot = new GameObject("StartButton");
            buttonRoot.transform.SetParent(root.transform, false);
            buttonRoot.transform.localPosition = new Vector3(0f, buttonY, northWallZ - proud / 2f);

            GameObject visual = Prim(PrimitiveType.Cube, "Visual", buttonRoot.transform, Vector3.zero,
                new Vector3(panelW, panelH, proud), plateMat, removeCollider: true);

            // The word, on the cell itself. Same treatment as every other display in the project:
            // spaced caps in the string, since uGUI has no tracking control and a space is one cell
            // of a monospace face.
            GameObject labelGO = new GameObject("Label");
            labelGO.transform.SetParent(buttonRoot.transform, false);
            Canvas labelCanvas = labelGO.AddComponent<Canvas>();
            labelCanvas.renderMode = RenderMode.WorldSpace;

            RectTransform labelRect = labelGO.GetComponent<RectTransform>();
            labelRect.sizeDelta = new Vector2(850f, 650f);
            labelRect.localScale = Vector3.one * 0.002f;               // -> 1.70m x 1.30m
            labelRect.anchorMin = new Vector2(0.5f, 0.5f);
            labelRect.anchorMax = new Vector2(0.5f, 0.5f);
            labelRect.pivot = new Vector2(0.5f, 0.5f);
            // anchoredPosition3D and AFTER the Canvas - see MakeWallFace for both traps.
            labelRect.anchoredPosition3D = new Vector3(0f, 0f, -(proud / 2f + 0.004f));
            // Identity: this wall faces north, so a player reading it is looking along +Z, and a
            // world-space canvas is legible when its forward matches the viewer's look direction.
            labelRect.localRotation = Quaternion.identity;

            // The speaker, above the word rather than beside it - this is the room's last screen
            // before the clock starts, and the PA and every room's audio cues are half of what the
            // facility tells the player from here on. Red, the same voice BEGIN speaks in, because
            // this is the facility's own instruction and not a HUD element laid over the room.
            MakeWallIcon(labelGO.transform, "VolumeHint", VolumeIcon(), new Vector2(0f, 195f), 160f, Color.red);

            Localize(MakeMenuLine(labelGO.transform, "Text", "B E G I N", 150, Color.red,
                Vector2.zero, new Vector2(850f, 220f)), "cal.beginPlate");

            CalibrationStartButton button = buttonRoot.AddComponent<CalibrationStartButton>();
            button.calibration = calibration;
            button.buttonRenderer = visual.GetComponent<Renderer>();
            button.audioSource = MakeSource(buttonRoot.transform, "ButtonAudio", 1f, 0.8f);
            button.pressClip = LoadClip(SfxDir, "sfx_floor_button_press");
            return button;
        }

        private static RectTransform MakePlate(Transform parent, string name, Vector2 anchoredPosition, Vector2 size)
        {
            GameObject go = new GameObject(name);
            go.transform.SetParent(parent, false);

            Image plate = go.AddComponent<Image>();
            // GrooveDark, the same near-black that sits at the bottom of every groove in the room -
            // so a panel of UI reads as part of the facility rather than as an overlay.
            plate.color = new Color(0.04f, 0.04f, 0.045f, 0.82f);
            plate.raycastTarget = false;

            RectTransform rect = plate.GetComponent<RectTransform>();
            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.sizeDelta = size;
            rect.anchoredPosition = anchoredPosition;
            return rect;
        }

        // A key cap: a red rounded rect with a near-black one inset inside it, which is a border
        // without needing a border sprite. uGUI's own UISprite is 9-sliced, so one sprite gives
        // every size of cap the same corner radius - a square W and a wide SPACE bar included.
        // One of the calibration room's side walls: a single key and the figure it produces, and
        // nothing else on the whole wall.
        //
        // Sprint and crouch went here rather than staying as two more rows on the south wall, and the
        // reason is what they are: the other four controls are things you do in a place, where these
        // two are how you CROSS one. Putting them on the walls the player crosses between - and one
        // each, so a wall means a control - says that better than a fifth and sixth row can. It also
        // means the player meets them by turning their head, which is the thing this room exists to
        // teach them to do.
        //
        // Bigger than anything on the south wall: it is one control on 10.5m of wall, so the sizes that
        // made a dense list legible would look like a stamp in the corner here.
        private static CanvasGroup MakeCalibrationSideWall(Transform parent, string name, float roomCenterZ,
                                                          bool west, string keyLabel, Sprite figureSprite,
                                                          Color ink)
        {
            const float standoff = 0.05f;
            const float y = 2.4f;
            const float worldWidth = 4.6f;

            float x = (west ? -1f : 1f) * (RoomWidth / 2f - standoff);
            // Forward INTO the wall, which for a side wall means a quarter turn. A world-space canvas is
            // legible when its forward matches the direction the viewer is LOOKING - see
            // MakeFourWallFaces - and a player in this room looking at the west wall is looking -X.
            Quaternion rotation = Quaternion.Euler(0f, west ? -90f : 90f, 0f);

            GameObject go = new GameObject(name);
            go.transform.SetParent(parent, false);

            Canvas canvas = go.AddComponent<Canvas>();
            canvas.renderMode = RenderMode.WorldSpace;

            RectTransform rect = go.GetComponent<RectTransform>();
            rect.sizeDelta = new Vector2(1000f, 620f);
            rect.localScale = Vector3.one * (worldWidth / 1000f);
            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.anchoredPosition3D = new Vector3(x, y, roomCenterZ);
            rect.localRotation = rotation;

            CanvasGroup group = go.AddComponent<CanvasGroup>();
            group.alpha = 0f;
            group.blocksRaycasts = false;
            group.interactable = false;

            // Key above, figure below, both centred - a column rather than the south wall's rows,
            // because one pair has no list to line up with and centring it owns the wall.
            MakeKeyCap(go.transform, "Key", keyLabel, new Vector2(0f, 150f), new Vector2(460f, 120f), 54);
            MakeWallIcon(go.transform, "Figure", figureSprite, new Vector2(0f, -110f), 300f, ink);
            return group;
        }

        private static void MakeKeyCap(Transform parent, string name, string label,
                                       Vector2 anchoredPosition, Vector2 size, int fontSize = 26)
        {
            Sprite rounded = AssetDatabase.GetBuiltinExtraResource<Sprite>("UI/Skin/UISprite.psd");

            GameObject go = new GameObject(name);
            go.transform.SetParent(parent, false);

            Image outer = go.AddComponent<Image>();
            outer.sprite = rounded;
            outer.type = Image.Type.Sliced;
            outer.color = new Color(0.75f, 0.14f, 0.14f, 0.95f);
            outer.raycastTarget = false;
            RectTransform rect = outer.GetComponent<RectTransform>();
            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.sizeDelta = size;
            rect.anchoredPosition = anchoredPosition;

            GameObject faceGO = new GameObject("Face");
            faceGO.transform.SetParent(go.transform, false);
            Image face = faceGO.AddComponent<Image>();
            face.sprite = rounded;
            face.type = Image.Type.Sliced;
            face.color = new Color(0.06f, 0.05f, 0.06f, 0.98f);
            face.raycastTarget = false;
            RectTransform faceRect = face.GetComponent<RectTransform>();
            faceRect.anchorMin = Vector2.zero;
            faceRect.anchorMax = Vector2.one;
            // Inset on all four sides, so the outer colour shows as an even rim at any cap size.
            faceRect.offsetMin = new Vector2(3f, 3f);
            faceRect.offsetMax = new Vector2(-3f, -3f);

            GameObject textGO = new GameObject("Label");
            textGO.transform.SetParent(go.transform, false);
            Text text = textGO.AddComponent<Text>();
            text.font = UIFont();
            text.fontSize = fontSize;
            text.alignment = TextAnchor.MiddleCenter;
            text.color = new Color(1f, 0.45f, 0.45f, 1f);
            text.text = label;
            text.horizontalOverflow = HorizontalWrapMode.Overflow;
            text.verticalOverflow = VerticalWrapMode.Overflow;
            text.raycastTarget = false;
            Stretch(text.GetComponent<RectTransform>());
        }

        // The word beside a key or a glyph. Takes the x its text should START at, since every
        // caption in a column has to begin at the same place whatever its length - the rect is
        // centred, so the offset below is half its width. 190 fits the longest of these
        // ("LOOK AROUND", 11 monospace cells) at either size it is used in.
        //
        // The colour is a parameter because these appear on two very different backgrounds: the
        // wall display puts a near-black plate under them and wants the HUD's light red, where
        // anything drawn straight onto the room's white panelling needs a much darker one.
        private static void MakeCaption(Transform parent, string name, string content, Vector2 leftEdge,
                                        Color? color = null, int fontSize = 22) =>
            MakeMenuLine(parent, name, content, fontSize, color ?? new Color(0.7f, 0.06f, 0.06f, 1f),
                leftEdge + new Vector2(95f, 0f), new Vector2(190f, 30f), TextAnchor.MiddleLeft);

        // WHO MADE WHAT, READ OUT OF THE FILES THEMSELVES.
        //
        // Every `.glb` here came off Sketchfab, and Sketchfab's exporter writes the title, the author,
        // the licence and the source URL into the glTF's own `asset.extras`. That is the primary
        // record, it cannot get separated from the file it describes, and reading it is what makes a
        // credits screen impossible to forget to update.
        //
        // **THE HAND-MAINTAINED VERSION WAS WRONG, WHICH IS WHY THIS IS CODE.**
        // `docs/asset-licences.md` was a table somebody typed, and checking it against the files found:
        // `chess.glb` credited to the wrong person, `rubiks_cube.glb` credited to the wrong person,
        // thirteen models missing from it entirely, and - the one that matters - `cctv_camera.glb`
        // recorded as CC-BY when the file says **CC-BY-NC**. That is the same argument `FloorButton`'s
        // audio settled: a list of every instance of a thing, maintained by hand, is a list that will
        // be wrong. So there is no list.
        private struct ModelCredit
        {
            public string file, title, author, authorUrl, licence, source;
        }

        // Only the fields wanted, so `JsonUtility` can ignore the rest of a 30MB glTF header.
        [System.Serializable] private class GltfExtras
        {
            public string title, author, license, source;
        }
        [System.Serializable] private class GltfAssetBlock { public GltfExtras extras; }
        [System.Serializable] private class GltfHeader { public GltfAssetBlock asset; }

        private static System.Collections.Generic.List<ModelCredit> ReadModelCredits()
        {
            var credits = new System.Collections.Generic.List<ModelCredit>();
            if (!Directory.Exists(ArtAssetsDir)) return credits;

            foreach (string path in Directory.GetFiles(ArtAssetsDir, "*.glb", SearchOption.AllDirectories))
            {
                // The retarget spike is scratch, not shipped. Anything under a folder starting with
                // `_` is the same kind of thing.
                if (path.Replace('\\', '/').Contains("/_")) continue;

                GltfExtras extras = ReadGltfExtras(path);
                if (extras == null || string.IsNullOrEmpty(extras.author))
                {
                    // Silence here would be the whole bug coming back. A model whose file carries no
                    // attribution needs one found by hand and written into the docs.
                    Debug.LogWarning($"[SceneBuilder] {Path.GetFileName(path)} carries no author in its "
                                   + "glTF extras - it cannot be credited automatically. Find its source "
                                   + "and record it in docs/asset-licences.md.");
                    continue;
                }

                credits.Add(new ModelCredit
                {
                    file = Path.GetFileName(path),
                    title = string.IsNullOrEmpty(extras.title) ? Path.GetFileNameWithoutExtension(path) : extras.title,
                    author = BeforeParen(extras.author),
                    authorUrl = InsideParen(extras.author),
                    licence = PrettyLicence(BeforeParen(extras.license)),
                    source = extras.source,
                });
            }

            credits.Sort((a, b) => string.Compare(a.title, b.title, System.StringComparison.OrdinalIgnoreCase));
            return credits;
        }

        // A GLB is a 12-byte header then length-prefixed chunks; the first is always the JSON.
        private static GltfExtras ReadGltfExtras(string path)
        {
            try
            {
                using (FileStream fs = File.OpenRead(path))
                using (var br = new BinaryReader(fs))
                {
                    if (br.ReadUInt32() != 0x46546C67u) return null;   // not "glTF"
                    br.ReadUInt32();                                   // version
                    br.ReadUInt32();                                   // total length
                    int chunkLength = (int)br.ReadUInt32();
                    if (br.ReadUInt32() != 0x4E4F534Au) return null;   // first chunk is not "JSON"

                    string json = System.Text.Encoding.UTF8.GetString(br.ReadBytes(chunkLength));
                    return JsonUtility.FromJson<GltfHeader>(json)?.asset?.extras;
                }
            }
            catch (System.Exception e)
            {
                Debug.LogWarning($"[SceneBuilder] could not read glTF header of {Path.GetFileName(path)}: {e.Message}");
                return null;
            }
        }

        // Sketchfab writes `Name (url)` and `CC-BY-4.0 (url)`.
        private static string BeforeParen(string value)
        {
            if (string.IsNullOrEmpty(value)) return "";
            int i = value.IndexOf(" (", System.StringComparison.Ordinal);
            return (i < 0 ? value : value.Substring(0, i)).Trim();
        }

        private static string InsideParen(string value)
        {
            if (string.IsNullOrEmpty(value)) return "";
            int open = value.IndexOf('(');
            int close = value.LastIndexOf(')');
            return open >= 0 && close > open ? value.Substring(open + 1, close - open - 1) : "";
        }

        // `CC-BY-NC-4.0` is the machine's spelling; `CC BY-NC 4.0` is the one the licence itself uses.
        private static string PrettyLicence(string code) =>
            string.IsNullOrEmpty(code) ? "?" : code.Replace("CC-", "CC ").Replace("-4.0", " 4.0");

        // THE CREDITS PAGE. Every model, its author and its licence, on a page of its own over the
        // same background as SETTINGS and the cycle picker.
        //
        // **A PAGE RATHER THAN THE ONE-LINE STRIP IT REPLACES.** The strip said "FURNITURE MODELS:
        // CREATIVE COMMONS", which names no author, no title, no licence version and no link - it is
        // a statement that a licence exists somewhere, not an attribution. CC-BY 4.0 asks for the
        // creator, the title, the licence and a link where practicable, and twenty-six of those do
        // not fit on one line at the bottom of a title screen.
        //
        // Two columns, because one would run off the bottom at any readable size.
        private static (CanvasGroup group, Button back) BuildCreditsPage(
            Transform canvas, System.Collections.Generic.List<ModelCredit> credits)
        {
            GameObject root = new GameObject("Credits");
            root.transform.SetParent(canvas, false);
            CanvasGroup group = root.AddComponent<CanvasGroup>();
            group.alpha = 0f;
            group.blocksRaycasts = false;
            Stretch(root.AddComponent<RectTransform>());

            MakeMenuLine(root.transform, "Title", "CREDITS", 52, MenuInk,
                         new Vector2(0f, 430f), new Vector2(900f, 70f));

            // The heading says what the list IS, so a player reading it knows these are obligations
            // being met rather than a thank-you note.
            MakeMenuLine(root.transform, "Subtitle",
                         "3D MODELS FROM SKETCHFAB, USED UNDER CREATIVE COMMONS", 15,
                         new Color(MenuInk.r, MenuInk.g, MenuInk.b, 0.6f),
                         new Vector2(0f, 386f), new Vector2(1200f, 24f));

            const int perColumn = 13;
            const float rowPitch = 26f;
            const float top = 340f;

            for (int i = 0; i < credits.Count; i++)
            {
                ModelCredit c = credits[i];
                int column = i / perColumn;
                int row = i % perColumn;
                // Two columns either side of centre. Left-aligned within each, so the eye has one
                // edge to run down rather than a ragged centred stack.
                float x = column == 0 ? -470f : 60f;

                MakeMenuLine(root.transform, $"Credit{i}",
                             $"\"{c.title}\" — {c.author} — {c.licence}", 13, MenuInk,
                             new Vector2(x + 200f, top - row * rowPitch), new Vector2(400f, 22f),
                             TextAnchor.MiddleLeft);
            }

            // The typefaces are the other third-party thing in the build, and the OFL wants naming
            // too. Audio and code are this project's own - see docs/asset-licences.md.
            MakeMenuLine(root.transform, "Fonts",
                         "TYPE: JETBRAINS MONO (JETBRAINS) AND D2CODING (NAVER), BOTH SIL OFL 1.1", 13,
                         new Color(MenuInk.r, MenuInk.g, MenuInk.b, 0.75f),
                         new Vector2(0f, -60f), new Vector2(1400f, 22f));

            MakeMenuLine(root.transform, "Links",
                         "FULL LIST WITH LINKS: ATTRIBUTION.md, SHIPPED BESIDE THE GAME", 13,
                         new Color(MenuInk.r, MenuInk.g, MenuInk.b, 0.55f),
                         new Vector2(0f, -86f), new Vector2(1400f, 22f));

            Button back = Localize(MakeMenuButtonInk(root.transform, "CreditsBackButton",
                                                     "BACK", new Vector2(0f, -230f)), "menu.back", "  ");
            return (group, back);
        }

        // THE FULL ATTRIBUTION, WITH URLS, AS A FILE THAT TRAVELS WITH THE BUILD.
        //
        // The page names creator, title and licence, which is a reasonable manner for a screen. The
        // licence also asks for a link to the material "where practicable", and twenty-six URLs on a
        // menu is not practicable - but a text file beside the executable is. Written on every build
        // from the same source the page uses, so the two cannot disagree.
        private static void WriteAttributionFile(System.Collections.Generic.List<ModelCredit> credits)
        {
            var sb = new System.Text.StringBuilder();
            sb.AppendLine("# Attribution");
            sb.AppendLine();
            sb.AppendLine("Iteration Room uses the following third-party assets.");
            sb.AppendLine("**Generated by `SceneBuilder` from each file's own glTF metadata — do not edit by hand.**");
            sb.AppendLine();
            sb.AppendLine("## 3D models");
            sb.AppendLine();

            foreach (ModelCredit c in credits)
            {
                sb.AppendLine($"- **\"{c.title}\"** by {c.author} — {c.licence}");
                if (!string.IsNullOrEmpty(c.source)) sb.AppendLine($"  - Source: {c.source}");
                if (!string.IsNullOrEmpty(c.authorUrl)) sb.AppendLine($"  - Author: {c.authorUrl}");
            }

            sb.AppendLine();
            sb.AppendLine("## Fonts");
            sb.AppendLine();
            sb.AppendLine("- **JetBrains Mono** by JetBrains — SIL Open Font License 1.1");
            sb.AppendLine("- **D2Coding** by NAVER Corporation — SIL Open Font License 1.1");
            sb.AppendLine();
            sb.AppendLine("## Everything else");
            sb.AppendLine();
            sb.AppendLine("Code, scenes, textures, materials, meshes, shaders and sound effects are this");
            sb.AppendLine("project's own work. See `docs/asset-licences.md` for the full record.");

            string path = Path.Combine(Directory.GetParent(Application.dataPath).FullName, "ATTRIBUTION.md");
            File.WriteAllText(path, sb.ToString());
            Debug.Log($"[SceneBuilder] Attribution written for {credits.Count} models to {path}");
        }

        // **THE BUILD POLICES THE LICENCES NOW**, because the last check was a document and the
        // document was wrong. NC cannot be sold at all, so it fails loudly; SA is sellable but viral
        // and wants a decision rather than a surprise.
        private static void CheckModelLicences(System.Collections.Generic.List<ModelCredit> credits)
        {
            foreach (ModelCredit c in credits)
            {
                if (c.licence.Contains("NC"))
                    Debug.LogError($"[SceneBuilder] NON-COMMERCIAL ASSET: {c.file} is {c.licence} "
                                 + $"(\"{c.title}\" by {c.author}). This CANNOT ship in a paid build - "
                                 + "replace the model or keep the game free. See docs/asset-licences.md.");
                else if (c.licence.Contains("SA"))
                    Debug.LogWarning($"[SceneBuilder] SHARE-ALIKE ASSET: {c.file} is {c.licence} "
                                   + $"(\"{c.title}\" by {c.author}). Sellable, but the model and any "
                                   + "modification of it stay under the same licence - decide deliberately.");
            }
        }

        private static Text MakeMenuLine(Transform parent, string name, string content, int fontSize,
                                         Color color, Vector2 anchoredPosition, Vector2 size,
                                         TextAnchor alignment = TextAnchor.MiddleCenter)
        {
            GameObject go = new GameObject(name);
            go.transform.SetParent(parent, false);

            Text text = go.AddComponent<Text>();
            text.font = UIFont();
            text.fontSize = fontSize;
            text.alignment = alignment;
            text.color = color;
            text.text = content;
            text.horizontalOverflow = HorizontalWrapMode.Overflow;
            text.verticalOverflow = VerticalWrapMode.Overflow;
            text.raycastTarget = false;

            RectTransform rect = text.GetComponent<RectTransform>();
            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.sizeDelta = size;
            rect.anchoredPosition = anchoredPosition;

            return text;
        }

        // THE LIVE DIAL, in the calibration room, behind TAB. See `LightingTuner` for the four rules
        // that make it safe and the one thing it lies about.
        //
        // **DISARMED IN A RELEASE PLAYER.** A development panel on the first screen every player sees
        // is exactly why the first one was deleted; this one checks
        // `Application.isEditor || Debug.isDebugBuild` in `Awake` and goes inert if neither holds -
        // `CaptureRig`'s bargain, for the same reason. The object is still built, because the scene
        // is built once and serves both.
        //
        // Surfaces are gathered BY MATERIAL rather than by name, because that is the question being
        // asked - "everything wearing PanelWhite in this room" is precisely the set a wall slider
        // should move, and it survives any renaming of the objects themselves.
        private static void BuildLightingTuner(Transform parent)
        {
            var walls = new System.Collections.Generic.List<Renderer>();
            var floors = new System.Collections.Generic.List<Renderer>();
            var ceilings = new System.Collections.Generic.List<Renderer>();

            foreach (Renderer r in parent.GetComponentsInChildren<Renderer>(true))
            {
                if (!InCalibrationRoom(r.transform)) continue;
                Material m = r.sharedMaterial;
                if (m == null) continue;

                if (m.name == "PanelWhite") walls.Add(r);
                else if (m.name == "FloorWhite") floors.Add(r);
                else if (m.name == "CeilingWhite") ceilings.Add(r);
            }

            GameObject go = new GameObject("LightingTuner");
            go.transform.SetParent(parent, false);
            LightingTuner tuner = go.AddComponent<LightingTuner>();
            // The controller is found at runtime rather than wired: the player is not in this room's
            // hierarchy, and one serialised reference across a scene boundary is all it takes.
            tuner.fixtures = CalibrationLights;
            tuner.wallPanels = walls.ToArray();
            tuner.floors = floors.ToArray();
            tuner.ceilings = ceilings.ToArray();

            Debug.Log($"[SceneBuilder] LightingTuner wired: {walls.Count} wall, {floors.Count} floor, "
                    + $"{ceilings.Count} ceiling renderer(s), "
                    + $"{(CalibrationLights != null ? CalibrationLights.Length : 0)} fixture(s). TAB in play mode.");
        }

        // **WHAT `ExtractCalibrationRoom` WILL TAKE, WHICH IS NOT THE SAME SET AS `InCalibrationRoom`.**
        //
        // That method matches the shell exactly - a parent named `CalibrationRoom` - and the lift
        // matches a PREFIX, because the room is several siblings: the shell, `CalibrationWall`, its
        // start button, and `CalibrationRoom_CeilingLights`. Ask the exact question about a fixture
        // and the answer is no, because its parent is the last of those and not the first.
        //
        // The comment on `ExtractCalibrationRoom` records this trap costing a bug once already, for
        // `CalibrationWall`. It cost a second one here: `WireShadowBudget` used the exact test, missed
        // all four fixtures, and enrolled them in cycle 1's budget anyway.
        //
        // **Anything asking "will the lift take this?" must ask THIS, not the other one.**
        private static bool LiftedWithCalibrationRoom(Transform t)
        {
            for (Transform p = t; p != null; p = p.parent)
                if (p.name.StartsWith("Calibration")) return true;
            return false;
        }

        private static bool InCalibrationRoom(Transform t)
        {
            for (Transform p = t; p != null; p = p.parent)
                if (p.name == CalibrationRoomName) return true;
            return false;
        }

        private static void Stretch(RectTransform rect)
        {
            rect.anchorMin = Vector2.zero;
            rect.anchorMax = Vector2.one;
            rect.offsetMin = Vector2.zero;
            rect.offsetMax = Vector2.zero;
        }

        // A LEFT-TO-RIGHT DARKENING RAMP, so the words have something to sit on and the room does
        // not. Generated rather than authored, like every other texture here.
        //
        // The falloff is squared and stops well short of the right edge: the aim is a pool of shade
        // under the column, not a vignette, and anything that reaches the middle starts reading as a
        // dimmed screenshot again.
        private static Sprite MakeMenuScrimSprite()
        {
            const int w = 256, h = 4;
            Texture2D tex = new Texture2D(w, h, TextureFormat.RGBA32, false) { name = "MenuScrim" };
            tex.wrapMode = TextureWrapMode.Clamp;
            tex.filterMode = FilterMode.Bilinear;

            // **WHITE, NOT BLACK, SINCE 2026-08-20.** It was a dark ramp because the type was red and
            // red needs darkening to read; the type is charcoal now and charcoal needs the opposite.
            //
            // What it is really doing is CALMING THE GRID. The wall behind the column is near-black
            // grooves on white at full contrast, which is the worst possible field to set type in -
            // a wash of the room's own white flattens it to a whisper under the words and leaves it
            // at full strength on the right, where the eye is meant to go.
            for (int x = 0; x < w; x++)
            {
                float u = x / (float)(w - 1);
                // Full strength at the very edge, gone by 55% across.
                float k = 1f - Mathf.Clamp01(u / 0.55f);
                float a = k * k * 0.86f;
                Color c = new Color(1f, 1f, 1f, a);
                for (int y = 0; y < h; y++) tex.SetPixel(x, y, c);
            }
            tex.Apply();

            string path = TexturesDir + "/MenuScrim.png";
            File.WriteAllBytes(path, tex.EncodeToPNG());
            AssetDatabase.ImportAsset(path, ImportAssetOptions.ForceUpdate);
            // THE TYPE HAS TO BE SET BEFORE THE ASSET IS ASKED FOR AS A SPRITE. A freshly written PNG
            // imports as a plain Texture2D by default, and `LoadAssetAtPath<Sprite>` on one of those
            // returns null - which is how the scrim ended up as a white sheet.
            if (AssetImporter.GetAtPath(path) is TextureImporter imp)
            {
                imp.textureType = TextureImporterType.Sprite;
                imp.spriteImportMode = SpriteImportMode.Single;
                imp.alphaIsTransparency = true;
                imp.mipmapEnabled = false;
                imp.wrapMode = TextureWrapMode.Clamp;
                imp.SaveAndReimport();
            }
            AssetDatabase.Refresh();
            return AssetDatabase.LoadAssetAtPath<Sprite>(path);
        }

        // `ink` null keeps the red-on-dark this was built with, which is what the PAUSE menu wants -
        // it sits over a 0.72 black scrim, where charcoal would be invisible. The title screen passes
        // `MenuInk`, because it sits over a bright white room.
        //
        // THE WHITE SLAB IS GONE, and it was the single loudest thing on the title screen: five filled
        // rectangles stacked down the edge of a photograph of a white room. The plate is still THERE -
        // a `Button` needs a graphic to receive a click - it is simply transparent until the pointer
        // is on it, which is the whole of the difference between a menu that looks built and one that
        // looks laid out.
        // THE CONTROLS LIST on the settings page: every verb `InputBindings` knows about, as a label
        // and a button showing the key it is on.
        //
        // TWO COLUMNS, because eleven rows in one would run past the BACK button and off a 1080-tall
        // reference canvas. The split is computed from the count rather than written down, so adding a
        // twelfth verb to `InputBindings.All` re-balances the page instead of overflowing it.
        //
        // The key buttons are authored showing the DEFAULT binding, not the current one. This runs in
        // the Editor, where `InputBindings.Get` would read whatever the developer's own PlayerPrefs
        // happen to hold and bake it into the shipped scene; `KeyBindingPanel.Awake` refreshes every
        // row from the real bindings on the first frame anyway.
        private static KeyBindingPanel BuildKeyBindings(Transform page, CanvasGroup group)
        {
            GameObject root = new GameObject("KeyBindings");
            root.transform.SetParent(page, false);
            RectTransform rootRect = root.AddComponent<RectTransform>();
            // Zero-sized and on its parent's own origin, so the column edge stays the column edge one
            // level down and every x below is still "how far in from the edge".
            rootRect.anchorMin = rootRect.anchorMax = new Vector2(0.5f, 0.5f);
            rootRect.pivot = new Vector2(0.5f, 0.5f);
            rootRect.sizeDelta = Vector2.zero;
            rootRect.anchoredPosition = Vector2.zero;

            // A section heading one step below the page's own: Medium 26 against ExtraLight 52. The
            // title screen sets its hierarchy with size and weight and draws no rules or boxes
            // anywhere, so this page does the same.
            Localize(MakeRowLabelWeight(root.transform, "ControlsHeading", "CONTROLS",
                new Vector2(200f, 55f), new Vector2(400f, 32f), TextAnchor.MiddleLeft, MenuInk,
                "Medium", 26), "set.controls");
            // Paler than the labels: it is an instruction about the list rather than part of it, and
            // it is the one line on the page that changes while the player is using it.
            Text hint = MakeRowLabelInk(root.transform, "ControlsHint", "CLICK A KEY TO CHANGE IT",
                new Vector2(310f, 22f), new Vector2(620f, 24f), TextAnchor.MiddleLeft,
                new Color(MenuInk.r, MenuInk.g, MenuInk.b, 0.55f));

            GameAction[] actions = InputBindings.All;
            var rows = new KeyBindingPanel.Row[actions.Length];

            const float firstRowY = -25f, rowStep = 40f, secondColumnX = 580f;
            int perColumn = (actions.Length + 1) / 2;

            for (int i = 0; i < actions.Length; i++)
            {
                float originX = i / perColumn == 0 ? 0f : secondColumnX;
                float y = firstRowY - (i % perColumn) * rowStep;

                // 250 wide against the longest label ("STRAFE RIGHT", 12 characters, about 130px at
                // this size) - the 0.6 x fontSize x length check CLAUDE.md asks for, with room spare.
                Localize(MakeRowLabelInk(root.transform, "Label_" + actions[i], InputBindings.Label(actions[i]),
                    new Vector2(originX + 125f, y), new Vector2(250f, 26f), TextAnchor.MiddleLeft, MenuInk),
                    "act." + actions[i]);

                Button keyButton = MakeSettingsButton(root.transform, "Key_" + actions[i],
                    InputBindings.KeyLabel(InputBindings.DefaultFor(actions[i])),
                    new Vector2(originX + 370f, y), new Vector2(190f, 30f), out Text keyLabel);

                rows[i] = new KeyBindingPanel.Row
                {
                    action = actions[i],
                    button = keyButton,
                    keyLabel = keyLabel,
                };
            }

            // Left edge on the column like every label above it, so its centre - which is what a
            // centre-pivot rect is positioned by - sits half its width in.
            Button reset = Localize(MakeSettingsButton(root.transform, "ResetBindings", "RESET TO DEFAULTS",
                new Vector2(140f, -280f), new Vector2(280f, 34f), out _), "set.resetBindings");

            KeyBindingPanel panel = root.AddComponent<KeyBindingPanel>();
            panel.rows = rows;
            panel.resetButton = reset;
            panel.hint = hint;
            // So the panel can tell whether the page it is on is the one being looked at - an alpha of
            // zero does not stop Update, and a row left listening behind a closed page would eat the
            // title screen's next keypress.
            panel.group = group;
            return panel;
        }

        // A COMPACT, CENTRED BUTTON for the settings page, which `MakeMenuButton` cannot be: that one
        // is 340x66 and anchors itself to the left margin so the title column lines up, which is right
        // for five choices and wrong for eleven rows in a grid.
        //
        // **VISIBLE AT REST, unlike the title column's buttons.** Those draw nothing until the pointer
        // is over them, on the argument that the mark should be earned rather than five of them sitting
        // on screen. A key binding is a VALUE being displayed as well as a control, so it has to have a
        // plate around it whether or not anything is hovering it.
        private static Button MakeSettingsButton(Transform parent, string name, string label,
                                                 Vector2 anchoredPosition, Vector2 size, out Text text)
        {
            GameObject go = new GameObject(name);
            go.transform.SetParent(parent, false);

            RectTransform rect = go.AddComponent<RectTransform>();
            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.sizeDelta = size;
            rect.anchoredPosition = anchoredPosition;

            // White, with the whole look coming from the ColorBlock - a Button tints its target
            // graphic by MULTIPLYING, so a plate that is already dark has nothing left to shade with.
            Image background = go.AddComponent<Image>();
            background.color = Color.white;

            GameObject textGO = new GameObject("Label");
            textGO.transform.SetParent(go.transform, false);
            text = textGO.AddComponent<Text>();
            text.font = UIFont("Medium");
            text.fontSize = 18;
            text.alignment = TextAnchor.MiddleCenter;
            text.color = MenuInk;
            text.text = label;
            text.raycastTarget = false;
            // Overflow rather than wrap: "MIDDLE MOUSE" is the longest thing this can be asked to hold
            // and it fits, but a rebind can put any key label in here and a silent rewrap to two lines
            // is the failure CLAUDE.md warns about twice.
            text.horizontalOverflow = HorizontalWrapMode.Overflow;
            text.verticalOverflow = VerticalWrapMode.Overflow;
            Stretch(text.GetComponent<RectTransform>());

            Button button = go.AddComponent<Button>();
            button.targetGraphic = background;

            ColorBlock colors = button.colors;
            colors.normalColor = new Color(0.11f, 0.11f, 0.13f, 0.07f);
            colors.highlightedColor = new Color(0.11f, 0.11f, 0.13f, 0.16f);
            colors.pressedColor = new Color(0.80f, 0.10f, 0.10f, 0.22f);
            // Back to rest once the click is over. Left on `highlightedColor`, the last row clicked
            // stays lit for the rest of the page's life and reads as still waiting for a key.
            colors.selectedColor = colors.normalColor;
            colors.disabledColor = new Color(0f, 0f, 0f, 0f);
            colors.fadeDuration = 0.12f;
            button.colors = colors;

            return button;
        }

        // A CONTAINER HUNG ON THE SAME LEFT EDGE THE MENU BUTTONS USE, so a page can mix rows with
        // buttons and have the two line up.
        //
        // **THIS EXISTS BECAUSE THE CANVAS SCALER MATCHES 0.5.** `MakeMenuButton` anchors to the
        // screen's LEFT edge at `MenuLeftMargin`; `MakeRowLabel`, `MakeSlider` and everything else
        // that takes an `anchoredPosition` anchors to the CENTRE. At exactly 16:9 those two can be
        // made to agree by writing `132 - 960` into every row, and at any other aspect ratio they
        // silently drift apart - the canvas's logical width changes with the aspect, so the centre
        // moves relative to the left edge. The settings page was built that way first and it is why
        // it read as two designs stacked: a block of rows floating in the middle with a BACK button
        // three hundred pixels away at the margin.
        //
        // A zero-sized rect pinned to the left edge fixes it for good: its own centre IS that point,
        // so children written at `x = 0` sit exactly on the button column's edge at every aspect,
        // and every x below reads as "how far in from the edge" rather than as a screen coordinate.
        private static Transform MakeLeftColumn(Transform parent, string name)
        {
            GameObject go = new GameObject(name);
            go.transform.SetParent(parent, false);
            RectTransform rect = go.AddComponent<RectTransform>();
            rect.anchorMin = new Vector2(0f, 0.5f);
            rect.anchorMax = new Vector2(0f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.sizeDelta = Vector2.zero;
            // The +6 is MakeMenuButton's own nudge, repeated so the two edges are the same edge.
            rect.anchoredPosition = new Vector2(MenuLeftMargin + 6f, 0f);
            return go.transform;
        }

        // THE SHAPE OF ONE SETTINGS ROW, so the four of them cannot drift apart. A label on the
        // column edge and its control at a fixed indent - the numbers are here once rather than in
        // eight call sites.
        private const float SettingsLabelWidth = 300f;
        private const float SettingsControlX = 340f;

        // TAG A LABEL WITH WHICH STRING IT IS. The English stays authored in the `Text` itself, so a
        // scene built with this stripped is an English scene and nothing here can make a label blank -
        // `LocalizedText` only overwrites what is already correct.
        //
        // Deliberately a call AFTER the text is made rather than a parameter threaded through
        // `MakeRowLabel`, `MakeMenuLine`, `MakeMenuButton` and the rest: five builders would each need
        // an extra argument that almost every caller passes as null, and the ones that are NOT
        // localised (the facility's own signage - see `Loc`) would look like oversights instead of
        // decisions.
        private static Text Localize(Text text, string key)
        {
            if (text == null) return null;
            LocalizedText loc = text.gameObject.AddComponent<LocalizedText>();
            loc.target = text;
            loc.key = key;
            return text;
        }

        // A button's label lives on a child, and `MakeMenuButton` indents it with two spaces so the
        // words form one column down the left edge. That padding is layout, not content, so it stays
        // out of the string table and is re-applied here.
        private static Button Localize(Button button, string key, string prefix = "")
        {
            if (button == null) return null;
            Text text = button.GetComponentInChildren<Text>(true);
            if (text == null) return button;
            LocalizedText loc = text.gameObject.AddComponent<LocalizedText>();
            loc.target = text;
            loc.key = key;
            loc.prefix = prefix;
            return button;
        }

        private static Button MakeMenuButton(Transform parent, string name, string label,
                                             Vector2 anchoredPosition, Color? ink = null,
                                             string weight = null)
        {
            GameObject go = new GameObject(name);
            go.transform.SetParent(parent, false);

            // LEFT EDGE, like the title - see the note there. `anchoredPosition.x` arrives as 0 from
            // every call site and is ADDED to the margin, so the column lines up with the title
            // without every call having to know where the edge is.
            RectTransform rect = go.AddComponent<RectTransform>();
            rect.anchorMin = new Vector2(0f, 0.5f);
            rect.anchorMax = new Vector2(0f, 0.5f);
            rect.pivot = new Vector2(0f, 0.5f);
            rect.sizeDelta = new Vector2(340f, 60f);
            rect.anchoredPosition = new Vector2(MenuLeftMargin + anchoredPosition.x + 6f,
                                                anchoredPosition.y);

            // White, with the dark look coming entirely from the ColorBlock below: a Button tints
            // its target graphic by multiplying, so a background that is already near-black has
            // nothing left to brighten with on hover.
            Image background = go.AddComponent<Image>();
            background.color = Color.white;

            GameObject textGO = new GameObject("Label");
            textGO.transform.SetParent(go.transform, false);
            Text text = textGO.AddComponent<Text>();
            text.font = weight != null ? UIFont(weight) : UIFont();
            text.fontSize = 28;
            // Left inside the plate too, so the words form one column down the edge rather than a
            // ragged one centred inside boxes of a single width.
            text.alignment = TextAnchor.MiddleLeft;
            text.color = ink ?? Color.red;
            text.text = "  " + label;
            text.raycastTarget = false;
            Stretch(text.GetComponent<RectTransform>());

            Button button = go.AddComponent<Button>();
            button.targetGraphic = background;

            ColorBlock colors = button.colors;
            if (ink.HasValue)
            {
                // ON A BRIGHT SURFACE: nothing at rest, and the plate is only ever a HOVER. The
                // pointer earns the mark rather than five of them being on screen permanently.
                colors.normalColor = new Color(0f, 0f, 0f, 0f);
                colors.highlightedColor = new Color(0.11f, 0.11f, 0.13f, 0.09f);
                // Red only on the press, which is the one moment it means something here.
                colors.pressedColor = new Color(0.80f, 0.10f, 0.10f, 0.20f);
                colors.selectedColor = colors.highlightedColor;
                colors.disabledColor = new Color(0f, 0f, 0f, 0f);
            }
            else
            {
                colors.normalColor = new Color(0f, 0f, 0f, 0.55f);
                colors.highlightedColor = new Color(0.34f, 0.04f, 0.04f, 0.8f);
                colors.pressedColor = new Color(0.6f, 0.08f, 0.08f, 0.9f);
                colors.selectedColor = colors.highlightedColor;
                colors.disabledColor = new Color(0f, 0f, 0f, 0.3f);
            }
            colors.fadeDuration = 0.12f;
            button.colors = colors;

            return button;
        }

        // Two black panels that meet in the middle. They're driven through their anchors at
        // runtime, so the sizes set here don't matter - only that they exist and are full-width.
        private static WakeUpSequence BuildEyelids(Transform canvasParent)
        {
            GameObject root = new GameObject("Eyelids");
            root.transform.SetParent(canvasParent, false);
            RectTransform rootRect = root.AddComponent<RectTransform>();
            rootRect.anchorMin = Vector2.zero;
            rootRect.anchorMax = Vector2.one;
            rootRect.offsetMin = Vector2.zero;
            rootRect.offsetMax = Vector2.zero;

            RectTransform top = MakeEyelid(root.transform, "EyelidTop");
            RectTransform bottom = MakeEyelid(root.transform, "EyelidBottom");

            WakeUpSequence wakeUp = root.AddComponent<WakeUpSequence>();
            wakeUp.topLid = top;
            wakeUp.bottomLid = bottom;
            return wakeUp;
        }

        private static RectTransform MakeEyelid(Transform parent, string name)
        {
            GameObject go = new GameObject(name);
            go.transform.SetParent(parent, false);

            Image image = go.AddComponent<Image>();
            image.color = Color.black;
            image.raycastTarget = false;

            RectTransform rect = go.GetComponent<RectTransform>();
            rect.offsetMin = Vector2.zero;
            rect.offsetMax = Vector2.zero;
            return rect;
        }

        // Returns the object it built, purely so `CaptureRig` can be handed the HUD by reference
        // rather than finding it by name at runtime. Same for the two builders below it.
        private static GameObject BuildCountdownTimer(Transform canvasParent)
        {
            GameObject go = new GameObject("CountdownTimer");
            go.transform.SetParent(canvasParent, false);

            RectTransform rect = go.AddComponent<RectTransform>();
            rect.anchorMin = new Vector2(1f, 1f);
            rect.anchorMax = new Vector2(1f, 1f);
            rect.pivot = new Vector2(1f, 1f);
            rect.sizeDelta = new Vector2(160f, 50f);
            rect.anchoredPosition = new Vector2(-20f, -20f);

            Text text = go.AddComponent<Text>();
            text.font = UIFont();
            text.fontSize = 32;
            text.alignment = TextAnchor.UpperRight;
            text.color = Color.red;

            CountdownTimer timer = go.AddComponent<CountdownTimer>();
            timer.label = text;
            return go;
        }

        // The end-cycle control, immediately left of the countdown. Built last so it draws over the
        // eyelids rather than under them.
        // THE GAS THAT ENDS A CYCLE. A full-screen wash and a valve, and nothing that warns.
        //
        // A screen wash rather than a particle system, and that is a considered choice rather than a
        // shortcut: gas the player is inside is not gas they can look at. Volumetric fog in the room
        // would be something happening over there, and the beat is that it is happening to them.
        // Sitting on the HUD canvas also means it is drawn OVER the eyelids' parent, so the wash and
        // the blink stack correctly.
        //
        // 2D audio for the same reason. The player has no idea where the vents are and is not meant
        // to - a positioned hiss invites them to turn and look for it.
        private static void BuildSleepingGas(Transform canvasParent)
        {
            GameObject go = new GameObject("SleepingGas");
            go.transform.SetParent(canvasParent, false);

            Image haze = go.AddComponent<Image>();
            // Authored fully transparent. SleepingGas.Administer writes the alpha, and Clear puts it
            // back - a haze left up would open the next cycle behind a white sheet.
            haze.color = new Color(0.92f, 0.94f, 0.96f, 0f);
            // The wash must never eat a click. Nothing under it is interactive at a boundary, but a
            // full-screen Image defaults to raycast target and this is exactly the kind of invisible
            // blocker that is impossible to find later.
            haze.raycastTarget = false;

            RectTransform rect = haze.GetComponent<RectTransform>();
            rect.anchorMin = Vector2.zero;
            rect.anchorMax = Vector2.one;
            rect.offsetMin = Vector2.zero;
            rect.offsetMax = Vector2.zero;

            SleepingGas gas = go.AddComponent<SleepingGas>();
            gas.haze = haze;
            gas.audioSource = MakeSource(go.transform, "GasAudio", spatialBlend: 0f, volume: 0.7f);
            gas.hissClip = LoadClip(SfxDir, "sfx_gas_hiss");
        }

        private static GameObject BuildEndCycleControl(Transform canvasParent)
        {
            GameObject go = new GameObject("EndCycleControl");
            go.transform.SetParent(canvasParent, false);

            RectTransform rect = go.AddComponent<RectTransform>();
            rect.anchorMin = new Vector2(1f, 1f);
            rect.anchorMax = new Vector2(1f, 1f);
            rect.pivot = new Vector2(1f, 1f);
            // Wide enough for the label to fit on one line, which it did not: "HOLD [N] - END
            // CYCLE" is 20 monospace cells, i.e. ~192px at fontSize 16, inside a box that was 168
            // wide - so uGUI wrapped it onto two cramped lines and it read as decoration next to
            // the countdown rather than as a control. That is very likely why testers asked for a
            // skip button that has existed since the first build.
            rect.sizeDelta = new Vector2(224f, 40f);
            // The countdown is 160 wide, inset 20 from the corner, so it ends 180 in.
            rect.anchoredPosition = new Vector2(-192f, -20f);

            // Fades out while the clock isn't running, so the control reads as unavailable rather
            // than broken during the wake-up.
            CanvasGroup group = go.AddComponent<CanvasGroup>();

            Image background = go.AddComponent<Image>();
            background.color = new Color(0f, 0f, 0f, 0.55f);

            // The hold gauge, drawn between the background and the label so it fills behind the
            // text rather than over it.
            GameObject fillGO = new GameObject("Fill");
            fillGO.transform.SetParent(go.transform, false);
            Image fill = fillGO.AddComponent<Image>();
            // A filled Image needs a sprite to have anything to fill; the built-in UI sprite is the
            // one uGUI itself uses for buttons.
            fill.sprite = AssetDatabase.GetBuiltinExtraResource<Sprite>("UI/Skin/UISprite.psd");
            fill.type = Image.Type.Filled;
            fill.fillMethod = Image.FillMethod.Horizontal;
            fill.fillAmount = 0f;
            fill.color = new Color(0.75f, 0.1f, 0.1f, 0.85f);
            fill.raycastTarget = false;
            RectTransform fillRect = fill.GetComponent<RectTransform>();
            fillRect.anchorMin = Vector2.zero;
            fillRect.anchorMax = Vector2.one;
            fillRect.offsetMin = Vector2.zero;
            fillRect.offsetMax = Vector2.zero;

            GameObject labelGO = new GameObject("Label");
            labelGO.transform.SetParent(go.transform, false);
            Text label = labelGO.AddComponent<Text>();
            label.font = UIFont();
            label.fontSize = 16;
            label.alignment = TextAnchor.MiddleCenter;
            label.color = Color.red;
            // "HOLD" states the interaction, and the key is advertised because it is the one that
            // works with the cursor locked.
            label.text = "HOLD [N] — END CYCLE";
            Localize(label, "hud.endCycle");
            // Belt and braces with the wider rect above: a label that silently rewraps is how this
            // became unreadable in the first place, and at some resolutions the scaler will shave
            // a pixel off.
            label.horizontalOverflow = HorizontalWrapMode.Overflow;
            label.verticalOverflow = VerticalWrapMode.Overflow;
            label.raycastTarget = false;
            RectTransform labelRect = label.GetComponent<RectTransform>();
            labelRect.anchorMin = Vector2.zero;
            labelRect.anchorMax = Vector2.one;
            labelRect.offsetMin = Vector2.zero;
            labelRect.offsetMax = Vector2.zero;

            EndCycleControl control = go.AddComponent<EndCycleControl>();
            control.fill = fill;
            control.group = group;
            return go;
        }
    }
}
